class _StaticValue:
    """Tk-free fallback exposing the small ``.get()`` API used by UI code.

    Never construct ``tk.Variable`` objects inside ``getattr`` defaults: Python
    evaluates those defaults eagerly, which crashes headless calculation/export
    paths even when the real attribute exists.
    """
    __slots__ = ("_value",)

    def __init__(self, value=None):
        self._value = value

    def get(self):
        return self._value


def _v225_const_var(value=None):
    return _StaticValue(value)

