def open_path(p: Path):
    if os.name == "nt":
        os.startfile(str(p))
    elif sys.platform == "darwin":
        os.system(f'open "{p}"')
    else:
        os.system(f'xdg-open "{p}"')


def bind_combobox_first_letter_jump(combo):
    """Bind first-letter navigation only to ttk.Combobox widgets.

    This keeps normal Entry/Text typing unchanged.  When a combobox has a
    drop-down list, pressing an English letter jumps to the next matching item.
    Repeated presses cycle through matching options.
    """
    try:
        if not isinstance(combo, ttk.Combobox):
            return combo
        combo._letter_jump_last = (None, -1)
        def _jump(event):
            ch = (getattr(event, "char", "") or "")
            if len(ch) != 1 or not ch.isalpha() or not ch.isascii():
                return None
            values = list(combo.cget("values") or [])
            if not values:
                return None
            key = ch.lower()
            last_key, last_pos = getattr(combo, "_letter_jump_last", (None, -1))
            start = (last_pos + 1) if last_key == key else 0
            ordered = list(range(start, len(values))) + list(range(0, start))
            for i in ordered:
                if str(values[i]).lower().startswith(key):
                    combo.set(values[i])
                    combo._letter_jump_last = (key, i)
                    try:
                        combo.event_generate("<<ComboboxSelected>>")
                    except Exception:
                        pass
                    return "break"
            return None
        combo.bind("<KeyPress>", _jump, add="+")
    except Exception:
        pass
    return combo


class EditableTree(ttk.Treeview):
    """Small Excel-like Treeview with double-click editing.

    Some columns use an editable Combobox so SPPS users can select common
    amino acids, modifiers, coupling reagents, catalysts, bases, and solvents.
    Values remain editable because laboratories often use vendor- or
    protocol-specific reagent names. The SPPS coupling solvent is represented
    as one coupling cocktail solvent for the amino acid/modifier + reagent(s) + base mixture,
    not as separate unit/reagent/base dissolution solvents.
    """
    def __init__(self, master, columns, on_edit=None, combo_values=None, **kwargs):
        super().__init__(master, columns=columns, show="headings", **kwargs)
        self._on_edit = on_edit
        self._edit_entry = None
        self._combo_values = combo_values or {}
        for col in columns:
            self.heading(col, text=col)
            self.column(col, width=180, minwidth=110, anchor="w", stretch=True)
        self.bind("<Double-1>", self._begin_edit)

    def _begin_edit(self, event):
        if self.identify("region", event.x, event.y) != "cell":
            return
        row_id = self.identify_row(event.y)
        col_id = self.identify_column(event.x)
        if not row_id or not col_id:
            return
        col_index = int(col_id.replace("#", "")) - 1
        cols = list(self["columns"])
        if col_index < 0 or col_index >= len(cols):
            return
        col_name = cols[col_index]
        if col_name in {"No"}:
            return
        bbox = self.bbox(row_id, col_id)
        if not bbox:
            return
        x, y, w, h = bbox
        values = list(self.item(row_id, "values"))
        old = values[col_index] if col_index < len(values) else ""
        if self._edit_entry is not None:
            self._edit_entry.destroy()
        choices = self._combo_values.get(col_name)
        if choices:
            e = ttk.Combobox(self, values=choices, state="normal")
            bind_combobox_first_letter_jump(e)
            e.set(str(old))
        else:
            e = ttk.Entry(self)
            e.insert(0, str(old))
            e.select_range(0, "end")
        e.focus_set()
        e.place(x=x, y=y, width=w, height=h)
        self._edit_entry = e

        def commit(_event=None):
            new = e.get()
            values[col_index] = new
            self.item(row_id, values=values)
            e.destroy()
            self._edit_entry = None
            if self._on_edit:
                self._on_edit(row_id, col_name, new)

        def cancel(_event=None):
            e.destroy()
            self._edit_entry = None

        def live_preview(_event=None):
            # V1.0.19: update the underlying tree row while typing so Batch Manager
            # preview tables refresh immediately instead of waiting for focus-out.
            try:
                new_live = e.get()
                live_values = list(self.item(row_id, "values"))
                live_values += [""] * max(0, len(cols) - len(live_values))
                live_values[col_index] = new_live
                self.item(row_id, values=live_values)
                if self._on_edit:
                    self._on_edit(row_id, col_name, new_live)
            except Exception:
                pass

        e.bind("<KeyRelease>", live_preview, add="+")
        e.bind("<<ComboboxSelected>>", live_preview, add="+")
        e.bind("<Return>", commit)
        e.bind("<FocusOut>", commit)
        e.bind("<Escape>", cancel)


