    def __init__(self):
        super().__init__()
        self.title("SPPS Planner")
        set_pepforge_icon(self)
        self.geometry("1920x1080")
        self.minsize(1550, 900)
        self.last_outdir: Path | None = None
        self._row_meta_by_no = {}
        self._build()
        self.bind_all_combobox_typeahead()
        self.rebuild_table()
        self.after(300, self.refresh_outputs_from_tree)

    def _state_file_path(self) -> Path:
        """Persistent autosave file; survives app restart and installer updates."""
        if os.name == "nt":
            base = Path(os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or Path.home()) / "SPPS Planner"
        else:
            base = Path.home() / ".spps_planner"
        base.mkdir(parents=True, exist_ok=True)
        return base / "spps_planner_session_v1.json"

    def schedule_autosave(self):
        """Debounced autosave used by editor fields, batch table edits, and tab changes."""
        if getattr(self, "_restoring_state", False):
            return
        try:
            if getattr(self, "_autosave_after_id", None):
                self.after_cancel(self._autosave_after_id)
            self._autosave_after_id = self.after(450, self.save_autosave_state)
        except Exception:
            pass

    def _collect_state(self) -> dict:
        try:
            if hasattr(self, "pm_live_sync_selected"):
                self.pm_live_sync_selected()
        except Exception:
            pass
        batch_rows = []
        try:
            batch_rows = self._batch_rows_from_tree()
        except Exception:
            pass
        selected_pm = 0
        try:
            sel = self.pm_list.curselection()
            selected_pm = int(sel[0]) if sel else 0
        except Exception:
            pass
        defaults = {}
        for name in [
            "project_name", "seq", "lot_no", "resin", "scale", "loading", "coupling_eq",
            "modifier_eq", "coupling_repeats", "modifier_repeats", "default_reagent",
            "default_reagent_eq", "default_reagent_count", "default_catalyst", "default_catalyst_eq",
            "default_catalyst_count", "default_base", "default_base_eq", "default_base_count",
            "default_depro", "default_depro_ratio", "default_depro_count", "default_solvent1",
            "default_solvent1_count", "default_solvent2", "default_solvent2_count",
            "final_meoh_count", "ml_per_mmol", "default_coupling_solution_solvent",
            "default_loading_dissolve_solvent", "outdir", "batch_solution_conc",
            "batch_coupling_eq", "batch_actual_round_ml", "batch_actual_extra_ml",
            "batch_default_scale", "batch_default_resin", "batch_default_loading", "loading_aa_eq", "loading_diea_eq", "batch_hbtu_eq",
            "batch_hbtu_conc", "batch_hbtu_mw", "batch_nmp_density"
        ]:
            try:
                var = getattr(self, name, None)
                if var is not None and hasattr(var, "get"):
                    defaults[name] = var.get()
            except Exception:
                pass
        return {
            "app_version": APP_VERSION,
            "saved_at": datetime.now().isoformat(timespec="seconds"),
            "selected_pm_index": selected_pm,
            "pm_items": list(getattr(self, "pm_items", [])),
            "batch_rows": batch_rows,
            "defaults": defaults,
        }

    def save_autosave_state(self):
        try:
            state = self._collect_state()
            self.state_file.parent.mkdir(parents=True, exist_ok=True)
            tmp = self.state_file.with_suffix(".tmp")
            tmp.write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")
            tmp.replace(self.state_file)
            self._autosave_after_id = None
        except Exception as exc:
            try:
                self._log(f"Autosave warning: {exc}\n")
            except Exception:
                pass

    def load_autosave_state(self):
        """Restore Project Manager and Batch Manager data without requiring Generate."""
        try:
            if not self.state_file.exists():
                return
            state = json.loads(self.state_file.read_text(encoding="utf-8"))
            self._restoring_state = True
            defaults = state.get("defaults", {}) if isinstance(state, dict) else {}
            for name, value in defaults.items():
                try:
                    var = getattr(self, name, None)
                    if var is not None and hasattr(var, "set"):
                        var.set(value)
                except Exception:
                    pass
            pm_items = state.get("pm_items", []) if isinstance(state, dict) else []
            if isinstance(pm_items, list) and pm_items:
                self.pm_items = [dict(x) for x in pm_items if isinstance(x, dict)]
                keep = int(state.get("selected_pm_index", 0) or 0)
                self.pm_refresh_list(keep_index=keep, reload_editor=True)
            batch_rows = state.get("batch_rows", []) if isinstance(state, dict) else []
            if hasattr(self, "batch_tree") and isinstance(batch_rows, list) and batch_rows:
                for iid in list(self.batch_tree.get_children()):
                    self.batch_tree.delete(iid)
                for row in batch_rows:
                    if isinstance(row, dict):
                        self.batch_add_row(row)
                self._renumber_batch_rows()
                self.refresh_batch_workspace_preview()
            try:
                self._log(f"Autosaved session restored: {self.state_file}\n")
            except Exception:
                pass
        except Exception as exc:
            try:
                self._log(f"Autosave restore warning: {exc}\n")
            except Exception:
                pass
        finally:
            self._restoring_state = False

    def on_close(self):
        try:
            self.save_autosave_state()
        finally:
            self.destroy()

    def _generate_lot_no(self) -> str:
        today = datetime.now().strftime("%y%m%d")
        seq_hint = re.sub(r"[^A-Za-z0-9]+", "", str(getattr(self, "seq", _v225_const_var("SPPS")).get() or "SPPS").upper())[:6] or "SPPS"
        return f"SPPS-{today}-{seq_hint}"

    def refresh_lot_no(self):
        try:
            self.lot_no.set(self._generate_lot_no())
            self.refresh_outputs_from_tree()
        except Exception:
            pass

    def _build(self):
        style = ttk.Style(self)
        style.configure("Treeview", rowheight=28, font=("Segoe UI", 10))
        style.configure("Treeview.Heading", font=("Segoe UI", 10, "bold"))
        style.configure("TNotebook.Tab", padding=(24, 10), font=("Segoe UI", 11, "bold"))
        main = ttk.Frame(self, padding=10)
        main.pack(fill="both", expand=True)
        ttk.Label(main, text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout", font=("Segoe UI", 18, "bold")).pack(anchor="w")
        self.project_name = tk.StringVar(value="")
        self.seq = tk.StringVar(value="Ac-EEMQRR-NH2")
        self.lot_no = tk.StringVar(value=self._generate_lot_no())

        project_bar = ttk.Labelframe(main, text="Project", padding=8)
        project_bar.pack(fill="x", pady=(0,8))
        ttk.Label(project_bar, text="Project name", width=16).grid(row=0, column=0, sticky="w", padx=(0,4))
        ttk.Entry(project_bar, textvariable=self.project_name).grid(row=0, column=1, sticky="ew", padx=(0,10))
        ttk.Label(project_bar, text="Sequence", width=12).grid(row=0, column=2, sticky="w", padx=(0,4))
        ttk.Entry(project_bar, textvariable=self.seq).grid(row=0, column=3, sticky="ew", padx=(0,10))
        ttk.Label(project_bar, text="LOT No.", width=10).grid(row=0, column=4, sticky="w", padx=(0,4))
        ttk.Entry(project_bar, textvariable=self.lot_no, width=22).grid(row=0, column=5, sticky="ew", padx=(0,4))
        ttk.Button(project_bar, text="Auto LOT", width=10, command=self.refresh_lot_no).grid(row=0, column=6, sticky="ew")
        project_bar.columnconfigure(1, weight=1)
        project_bar.columnconfigure(3, weight=1)
        project_bar.columnconfigure(5, weight=0)
        # V1.0.19: Project/sequence controls are managed in the Project Manager editor.
        # Keep these variables for legacy single-plan functions, but do not occupy the top screen.
        project_bar.pack_forget()

        form = ttk.Labelframe(main, text="Resin / Coupling / Base / Solvent Defaults", padding=8)
        self.setup_form = form
        form.pack(fill="x")
        self.resin = tk.StringVar(value="Amide")
        self.scale = tk.DoubleVar(value=400.0)
        self.loading = tk.DoubleVar(value=0.8)
        self.coupling_eq = tk.StringVar(value="5")  # V2.0.52: StringVar prevents Entry from auto-formatting typed 1 as 1.0
        self.modifier_eq = tk.DoubleVar(value=3.0)
        self.coupling_repeats = tk.IntVar(value=1)
        self.modifier_repeats = tk.IntVar(value=1)
        self.default_reagent = tk.StringVar(value="DIC")
        self.default_reagent_eq = tk.DoubleVar(value=5.0)
        self.default_reagent_count = tk.IntVar(value=1)
        self.default_catalyst = tk.StringVar(value="HOBt")
        self.default_catalyst_eq = tk.DoubleVar(value=5.0)
        self.default_catalyst_count = tk.IntVar(value=1)
        self.default_base = tk.StringVar(value="")
        self.default_base_eq = tk.DoubleVar(value=5.0)
        self.default_base_count = tk.IntVar(value=1)
        self.default_depro = tk.StringVar(value="Piperidine")
        self.default_depro_ratio = tk.StringVar(value="20% in DMF")
        self.default_depro_count = tk.IntVar(value=2)
        self.default_solvent1 = tk.StringVar(value="DMF")
