def _v27_apply_hbtu_nmp_preset(self):
    # Formula basis from user's HBTU/NMP sheet:
    # HBTU mmol = total coupling mmol * HBTU eq
    # HBTU solution volume (mL) = HBTU mmol / HBTU concentration (M)
    try:
        self.default_reagent.set("HBTU")
        self.default_reagent_eq.set(10.0)
        self.default_reagent_count.set(1)
        self.default_catalyst.set("")
        self.default_catalyst_eq.set(0.0)
        self.default_catalyst_count.set(0)
        self.default_base.set("")
        self.default_base_eq.set(0.0)
        self.default_base_count.set(0)
        self.default_coupling_solution_solvent.set("NMP")
        self.default_solvent1.set("NMP")
        self.default_solvent1_count.set(1)
        if hasattr(self, "batch_hbtu_eq"):
            self.batch_hbtu_eq.set("10")
        if hasattr(self, "batch_hbtu_conc"):
            self.batch_hbtu_conc.set("0.4")
        self.rebuild_table()
        self.refresh_outputs_from_tree()
        if hasattr(self, "refresh_batch_workspace_preview"):
            self.refresh_batch_workspace_preview()
        self._log("Applied HBTU/NMP preset: HBTU 10 eq, 0.4 M in NMP; volume = mmol / M.\n")
    except Exception as e:
        messagebox.showerror("HBTU/NMP preset", str(e))


def _v27_hbtu_nmp_calculation_check(self, total_step_mmol: float, hbtu_eq: float | None = None, hbtu_conc: float | None = None):
    try:
        hbtu_eq = float(hbtu_eq if hbtu_eq is not None else getattr(self, "batch_hbtu_eq", _v225_const_var("10")).get())
    except Exception:
        hbtu_eq = 10.0
    try:
        hbtu_conc = float(hbtu_conc if hbtu_conc is not None else getattr(self, "batch_hbtu_conc", _v225_const_var("0.4")).get())
    except Exception:
        hbtu_conc = 0.4
    total_step_mmol = float(total_step_mmol or 0)
    hbtu_mmol = total_step_mmol * hbtu_eq
    solution_mL = hbtu_mmol / hbtu_conc if hbtu_conc else 0.0
    hbtu_mw = float(getattr(self, "batch_hbtu_mw", _v225_const_var("379.247")).get() or 379.247) if hasattr(self, "batch_hbtu_mw") else 379.247
    hbtu_g = hbtu_mmol * hbtu_mw / 1000.0
    return {"hbtu_mmol": hbtu_mmol, "solution_mL": solution_mL, "hbtu_g": hbtu_g, "solvent": "NMP"}


