def _v28_clean_numeric(value, default=0.0):
    try:
        if value is None:
            return default
        s = str(value).replace(",", "").replace("mL", "").replace("g", "").strip()
        if not s:
            return default
        return float(s)
    except Exception:
        return default


def _v28_extract_aa_from_unit(self, unit_name: str):
    """Extract synthesizer AA stock token from plan/material display names.

    Examples:
      Fmoc-Lys(Boc)-OH -> K
      Fmoc-His(Trt)-OH -> H
      Fmoc-Gly-OH      -> G
      D-Lys            -> D-Lys
      K                -> K
    """
    text = str(unit_name or "").strip()
    if not text:
        return None
    # D-form and non-natural tokens first.
    toks = self._aa_letters_from_sequence(text)
    if toks:
        # Avoid extracting C from CTC/chemical words; for Fmoc names the tokenizer
        # may fail, so use 3-letter map below before accepting noisy long text.
        if len(text) <= 12:
            return toks[0]
    three = {
        "ALA":"A", "ARG":"R", "ASN":"N", "ASP":"D", "CYS":"C", "GLN":"Q", "GLU":"E",
        "GLY":"G", "HIS":"H", "ILE":"I", "LEU":"L", "LYS":"K", "MET":"M", "PHE":"F",
        "PRO":"P", "SER":"S", "THR":"T", "TRP":"W", "TYR":"Y", "VAL":"V",
        "HYP":"Hyp", "NLE":"Nle", "ORN":"Orn", "AIB":"Aib", "DAB":"Dab", "DAP":"Dap",
        "CIT":"Cit", "CHA":"Cha", "SAR":"Sar"
    }
    up = re.sub(r"[^A-Za-z0-9-]", " ", text).upper()
    # D-xxx in Fmoc-D-Lys type names.
    m = re.search(r"D[- ]?(ALA|ARG|ASN|ASP|CYS|GLN|GLU|GLY|HIS|ILE|LEU|LYS|MET|PHE|PRO|SER|THR|TRP|TYR|VAL)", up)
    if m:
        one = three.get(m.group(1))
        full = {"A":"Ala","R":"Arg","N":"Asn","D":"Asp","C":"Cys","Q":"Gln","E":"Glu","G":"Gly","H":"His","I":"Ile","L":"Leu","K":"Lys","M":"Met","F":"Phe","P":"Pro","S":"Ser","T":"Thr","W":"Trp","Y":"Tyr","V":"Val"}.get(one, one)
        return "D-" + full
    for k, v in three.items():
        if re.search(r"(^|[-_ /])" + re.escape(k) + r"($|[-_ /])", up):
            return v
    if len(text) == 1 and text.upper() in set("ARNDCQEGHILKMFPSTWYV"):
        return text.upper()
    return None


def _v28_dataframe_from_tree(tree):
    try:
        cols = list(tree["columns"])
        rows = []
        for iid in tree.get_children():
            vals = list(tree.item(iid, "values"))
            vals += [""] * max(0, len(cols)-len(vals))
            rows.append(dict(zip(cols, vals)))
        return pd.DataFrame(rows, columns=cols)
    except Exception:
        return pd.DataFrame()


def _v28_save_manual_tables_from_selected(self):
    idx = self.pm_current_index() if hasattr(self, "pm_list") else None
    if idx is None or idx < 0 or idx >= len(getattr(self, "pm_items", [])):
        return
    try:
        if hasattr(self, "pm_selected_plan_tree"):
            self.pm_items[idx]["manual_plan"] = _v28_dataframe_from_tree(self.pm_selected_plan_tree).to_dict("records")
        if hasattr(self, "pm_selected_material_tree"):
            self.pm_items[idx]["manual_materials"] = _v28_dataframe_from_tree(self.pm_selected_material_tree).to_dict("records")
        self.schedule_autosave()
    except Exception:
        pass


def _v28_make_tree_editable(self, tree, on_commit=None):
    """Enable double-click cell editing on standard ttk.Treeview tables."""
    try:
        if getattr(tree, "_v28_editable", False):
            return
        tree._v28_editable = True
        tree._v28_editor = None

        def begin(event):
            if tree.identify("region", event.x, event.y) != "cell":
                return
            row_id = tree.identify_row(event.y)
            col_id = tree.identify_column(event.x)
            if not row_id or not col_id:
                return
            col_index = int(col_id.replace("#", "")) - 1
            cols = list(tree["columns"])
            if col_index < 0 or col_index >= len(cols):
                return
            col_name = cols[col_index]
            if col_name in {"No", "no"}:
                return
            bbox = tree.bbox(row_id, col_id)
            if not bbox:
                return
            x, y, w, h = bbox
            vals = list(tree.item(row_id, "values"))
            vals += [""] * max(0, len(cols)-len(vals))
            old = vals[col_index]
            if tree._v28_editor is not None:
                try: tree._v28_editor.destroy()
                except Exception: pass
            e = ttk.Entry(tree)
            e.insert(0, str(old))
            e.select_range(0, "end")
            e.place(x=x, y=y, width=w, height=h)
            e.focus_set()
            tree._v28_editor = e

            def commit(_event=None):
                new = e.get()
                vals[col_index] = new
                tree.item(row_id, values=vals)
                try: e.destroy()
                except Exception: pass
                tree._v28_editor = None
                if on_commit:
                    on_commit(tree, row_id, col_name, new)

            def cancel(_event=None):
                try: e.destroy()
                except Exception: pass
                tree._v28_editor = None
            e.bind("<Return>", commit)
            e.bind("<FocusOut>", commit)
            e.bind("<Escape>", cancel)
            return "break"
        tree.bind("<Double-1>", begin, add="+")
    except Exception:
        pass


def _v28_on_selected_result_edit(self, tree, row_id, col_name, new_value):
    # Restore the old manual intervention behavior: users can change a specific
    # row's repeat/use_count/eq/etc. and Batch Manager reads the edited table.
    try:
        _v28_save_manual_tables_from_selected(self)
        if hasattr(self, "refresh_batch_workspace_preview"):
            self.refresh_batch_workspace_preview()
    except Exception:
        pass


