def _v28_manual_plan_counts_for_item(self, item):
    counts = {}
    manual = item.get("manual_plan") or []
    if not manual:
        return counts
    for row in manual:
        unit = row.get("Unit name") or row.get("unit") or row.get("material") or ""
        aa = self._v28_extract_aa_from_unit(unit)
        if not aa:
            continue
        repeat = _v28_clean_numeric(row.get("Repeat", row.get("repeat", 1)), 1.0)
        use_count = _v28_clean_numeric(row.get("use_count", row.get("Use count", 1)), 1.0)
        # Repeat/use_count is the user's manual synthesis-count intervention.
        n = max(repeat, 0) * max(use_count, 1)
        counts[aa] = counts.get(aa, 0.0) + n
    return counts


def _v28_sequence_counts_for_item(self, item):
    counts = {}
    seq = str(item.get("sequence", "") or "")
    for aa in self._aa_letters_from_sequence(seq):
        counts[aa] = counts.get(aa, 0.0) + 1.0
    return counts


def _v28_counts_for_item(self, item):
    # Prefer manually edited Selected Plan rows; otherwise parse sequence.
    counts = self._v28_manual_plan_counts_for_item(item)
    if counts:
        return counts
    return self._v28_sequence_counts_for_item(item)


def _v28_aa_calculator_df(self, rows=None):
    try:
        conc = float(self.batch_solution_conc.get())
    except Exception:
        conc = 0.25
    try:
        aa_eq = float(self.batch_coupling_eq.get())
    except Exception:
        aa_eq = 10.0
    totals = {}
    # Use pm_items directly so manual edited plan/material counts are available.
    items = list(getattr(self, "pm_items", []) or [])
    for item in items:
        try: copies = max(int(float(item.get("copies", 1) or 1)), 1)
        except Exception: copies = 1
        try: scale = float(item.get("scale", 0.2) or 0.2)
        except Exception: scale = 0.2
        for aa, local_count in self._v28_counts_for_item(item).items():
            count = float(local_count or 0) * copies
            totals.setdefault(aa, {"count":0.0, "mmol":0.0})
            totals[aa]["count"] += count
            totals[aa]["mmol"] += count * scale * aa_eq
    out=[]
    for aa in sorted(totals):
        count = totals[aa]["count"]
        mmol = totals[aa]["mmol"]
        calc_ml = mmol / conc if conc else 0.0
        actual_ml = self._v23_roundup_ml(calc_ml)
        mw = self._mw_for_token(aa) or self.MW_FALLBACK.get(aa, 0.0)
        weight_g = actual_ml/1000.0*conc*mw if actual_ml and conc and mw else 0.0
        count_disp = int(count) if abs(count-round(count)) < 1e-9 else round(count, 2)
        out.append({
            "AA": aa, "count": count_disp, "eq": aa_eq, "solvent": "DMF", "conc_M": conc,
            "calculated_mL": round(calc_ml, 3), "actual_mL": round(actual_ml, 3),
            "MW": round(mw, 2) if mw else "manual", "weight_g": round(weight_g, 3),
            "note": "actual mL = round-up + reserve; manual Repeat/use_count edits are included"
        })
    return pd.DataFrame(out, columns=["AA","count","eq","solvent","conc_M","calculated_mL","actual_mL","MW","weight_g","note"])


def _v28_batch_totals(self, rows=None):
    coupling={}; catalyst={}; solvent={}; modifier={}
    try: aa_eq=float(self.batch_coupling_eq.get())
    except Exception: aa_eq=10.0
    try: hbtu_eq=float(self.batch_hbtu_eq.get())
    except Exception: hbtu_eq=10.0
    try: hbtu_conc=float(self.batch_hbtu_conc.get())
    except Exception: hbtu_conc=0.4
    for item in list(getattr(self, "pm_items", []) or []):
        try: copies=max(int(float(item.get("copies",1) or 1)),1)
        except Exception: copies=1
        try: scale=float(item.get("scale",0.2) or 0.2)
        except Exception: scale=0.2
        counts=self._v28_counts_for_item(item)
        steps=sum(float(v or 0) for v in counts.values()) * copies
        step_mmol=steps*scale
        chem=str(item.get("chemistry","DIC/HOBt") or "DIC/HOBt")
        if steps:
            if "HBTU/NMP" in chem:
                self._v23_add_solution_record(coupling,"HBTU","coupling reagent stock",steps,hbtu_eq,"NMP",hbtu_conc,step_mmol*hbtu_eq,"HBTU/NMP stock; solution volume = mmol / M")
                calc_ml=(step_mmol*hbtu_eq)/hbtu_conc if hbtu_conc else 0.0
                self._v23_add_solution_record(solvent,"NMP","HBTU stock solvent",steps,"","",0,calc_ml,"NMP required before round-up/reserve")
            else:
                self._v23_add_solution_record(coupling,"DIC","coupling reagent",steps,5.0,"neat/DMF",0,step_mmol*5.0,"DIC for synthesizer coupling prep")
                add="Oxyma" if "Oxyma" in chem else "HOBt"
                self._v23_add_solution_record(catalyst,add,"catalyst/additive",steps,5.0,"DMF",0,step_mmol*5.0,"catalyst/additive for coupling bottle")
                self._v23_add_solution_record(solvent,"DMF","coupling solvent reservoir",steps,"","",0,step_mmol*10.0,"DMF used for coupling/cocktail transfer; reserve applied")
            self._v23_add_solution_record(solvent,"DMF","AA stock solvent",steps,"","",0,0,"AA stock solvent volume is listed in AA table")
            self._v23_add_solution_record(solvent,"DMF","wash/deprotection reservoir",steps,"","",0,step_mmol*8.0*10.0,"DMF wash/deprotection reservoir estimate")
            self._v23_add_solution_record(solvent,"DCM","final wash reservoir",steps,"","",0,copies*scale*3.0*10.0,"DCM final wash reservoir estimate")
        seq=str(item.get("sequence","") or "")
        if self._sequence_has_nterm_ac(seq):
            self._v23_add_solution_record(modifier,"Acetic anhydride (Ac2O)","N-terminal Ac cap",copies,3.0,"neat/DMF",0,copies*scale*3.0,"Ac detected from sequence prefix Ac-")
    return {"coupling":self._v23_solution_records_to_df(coupling),"catalyst":self._v23_solution_records_to_df(catalyst),"solvent":self._v23_solution_records_to_df(solvent),"modifier":self._v23_solution_records_to_df(modifier)}


# Clean placeholder rendering: empty table stays empty, no fake placeholder rows.
def _v28_write_tree(self, tree: ttk.Treeview, df: pd.DataFrame, columns):
    try:
        for item in tree.get_children():
            tree.delete(item)
        if list(tree["columns"]) != list(columns):
            tree.configure(columns=list(columns))
            for col in columns:
                tree.heading(col, text=col)
                tree.column(col, width=130, minwidth=60, anchor="w", stretch=True)
        if df is None or df.empty:
            return
        for _, row in df.iterrows():
            vals = [_v25_format_display_value(self, row.get(c, ""), c) if "_v25_format_display_value" in globals() else row.get(c, "") for c in columns]
            tree.insert("", "end", values=vals)
    except Exception:
        pass


