def _v29_to_float(self, x, default=0.0):
    try:
        if x is None or str(x).strip() == "": return default
        return float(str(x).replace(',', '').strip())
    except Exception:
        return default

def _v29_safe_log(self, msg):
    try:
        if hasattr(self, 'log_text') and self.log_text is not None:
            self.log_text.insert('end', str(msg)); self.log_text.see('end')
    except Exception:
        pass

def _v29_safe_write_df(self, text_widget, df):
    try:
        if text_widget is None: return
        try: text_widget.configure(state='normal')
        except Exception: pass
        text_widget.delete('1.0', 'end')
        if df is not None:
            text_widget.insert('end', df.to_string(index=False) if hasattr(df, 'to_string') else str(df))
    except Exception:
        pass

def _v29_write_tree(self, tree, df, columns):
    try:
        if tree is None: return
        cols = list(columns or [])
        tree.configure(columns=cols, show='headings')
        for col in cols:
            try:
                tree.heading(col, text=col)
                w = 120
                if col in ('Note',): w = 280
                elif col in ('Item','material','Unit name'): w = 190
                elif col in ('Category','class'): w = 150
                elif col.lower().endswith('ml') or col in ('Actual_mL','Calculated_mL','Weight_g'): w = 110
                tree.column(col, width=w, minwidth=55, anchor='w', stretch=True)
            except Exception: pass
        for item in list(tree.get_children()): tree.delete(item)
        if df is None or getattr(df, 'empty', False): return
        for _, row in df.iterrows():
            vals=[]
            for c in cols:
                v=row.get(c,'')
                try:
                    if pd.isna(v): v=''
                except Exception: pass
                if isinstance(v,(int,float)):
                    cl=c.lower()
                    if 'ml' in cl or 'volume' in cl:
                        v=f"{float(v):.1f}"
                    elif cl in ('mw','density','weight_g','planned_g','calculated_g'):
                        v=f"{float(v):.2f}"
                    else:
                        v=f"{float(v):.2f}"
                vals.append(v)
            tree.insert('', 'end', values=vals)
    except Exception as e:
        try: print('Tree refresh error:', e)
        except Exception: pass

def _v29_round_actual_ml(self, calc_ml):
    calc_ml = _v29_to_float(self, calc_ml, 0.0)
    if calc_ml <= 0:
        return 0.0
    import math
    step_var = getattr(self, 'batch_actual_round_ml', None)
    extra_var = getattr(self, 'batch_actual_extra_ml', None)
    step_raw = step_var.get() if hasattr(step_var, 'get') else 10
    extra_raw = extra_var.get() if hasattr(extra_var, 'get') else 10
    step = max(_v29_to_float(self, step_raw, 10), 1)
    extra = max(_v29_to_float(self, extra_raw, 10), 0)
    return math.ceil(calc_ml / step) * step + extra

def _v29_pm_rows(self):
    # Avoid recursive call to pm_live_sync_selected here. This function must be safe during refresh.
    rows=[]
    for i,item in enumerate(list(getattr(self,'pm_items',[]) or []), start=1):
        seq=str(item.get('sequence','') or '').strip()
        if not seq: continue
        rows.append({'No':i,'Project':item.get('project',''),'Peptide name':item.get('peptide',''),'Sequence':seq,'Copies':item.get('copies','1') or '1','Scale mmol':item.get('scale','0.2') or '0.2','Resin':item.get('resin',''),'Loading':item.get('loading',''),'LOT No':item.get('lot',''),'Chemistry':item.get('chemistry','DIC/HOBt') or 'DIC/HOBt'})
    return rows

def _v29_aa_counts_from_seq(self, seq):
    counts={}
    try: aas=self._aa_letters_from_sequence(seq)
    except Exception: aas=[c for c in str(seq or '').replace('-','') if c.isalpha() and c.isupper()]
    for aa in aas:
        if str(aa).upper()=='AC': continue
        counts[aa]=counts.get(aa,0.0)+1.0
    return counts

def _v29_material_lookup(self, token):
    mw=0.0; den=0.0
    try: mw=self._mw_for_token(token) or 0.0
    except Exception: pass
    try: den=self._density_for_token(token) or 0.0
    except Exception: pass
    if not mw: mw=getattr(self,'MW_FALLBACK',{}).get(token,0.0)
    return float(mw or 0), float(den or 0)

def _v29_add_record(self, records, cat, item, solvent, count, eq, conc, mmol, note=''):
    item=str(item or '').strip(); solvent=str(solvent or '').strip()
    if not item: return
    key=(cat,item,solvent,str(eq),str(conc),note)
    rec=records.setdefault(key, {'Category':cat,'Item':item,'Solvent':solvent,'Count':0.0,'Eq':eq,'Conc_M':conc,'mmol':0.0,'Note':note})
    rec['Count'] += float(count or 0); rec['mmol'] += float(mmol or 0)

def _v29_records_to_df(self, records):
    rows=[]
    for rec in records.values():
        item=rec['Item']; mmol=float(rec.get('mmol') or 0); conc=_v29_to_float(self, rec.get('Conc_M'), 0.0)
        mw,density=_v29_material_lookup(self,item)
        calc_ml=(mmol/conc) if conc else 0.0
        actual_ml=_v29_round_actual_ml(self, calc_ml) if calc_ml else 0.0
        weight_g=(actual_ml/1000.0*conc*mw) if (actual_ml and conc and mw) else ((mmol*mw/1000.0) if mw else 0.0)
        volume_ml=(weight_g/density) if (density and weight_g and not conc) else (actual_ml if actual_ml else 0.0)
        rows.append({'Category':rec['Category'],'Item':item,'Solvent':rec.get('Solvent',''),'Count':rec.get('Count',0),'Eq':rec.get('Eq',''),'Conc_M':conc if conc else '', 'Calculated_mL':calc_ml if calc_ml else '', 'Actual_mL':actual_ml if actual_ml else '', 'MW':mw if mw else '', 'Density':density if density else '', 'Weight_g':weight_g if weight_g else '', 'Volume_mL':volume_ml if volume_ml else '', 'Note':rec.get('Note','')})
    return pd.DataFrame(rows, columns=V29_BATCH_COLUMNS)

def _v29_calculate_batch_tables(self):
    """Compatibility route to the single V2.2.5 Batch calculator."""
    final = globals().get('_v225_calculate_batch_tables')
    if callable(final):
        return final(self)
    raise RuntimeError('V2.2.5 Batch calculator is not loaded yet')

def _v29_export_batch_tables(self):
    try:
        outdir=Path(getattr(self,'outdir',_v225_const_var('spps_output')).get() or 'spps_output')/'batch_manager'
        outdir.mkdir(parents=True, exist_ok=True)
        tables=_v29_calculate_batch_tables(self)
        with pd.ExcelWriter(outdir/'batch_synthesizer_calculator.xlsx', engine='openpyxl') as writer:
            for name,df in tables.items(): df.to_excel(writer,index=False,sheet_name=name[:31])
        messagebox.showinfo('Export complete', f'Batch calculator saved:\n{outdir}')
    except Exception as e: messagebox.showerror('Export error', str(e))

def _v29_build_batch_tab(self):
    fr=ttk.Frame(self.tabs); self.tabs.add(fr,text='Batch Manager')
    fr.rowconfigure(2,weight=1); fr.columnconfigure(0,weight=1)
    top=ttk.Frame(fr,padding=4); top.grid(row=0,column=0,sticky='ew')
    ttk.Label(top,text='Synthesizer stock/cocktail calculator - linked live from Project Manager').pack(side='left')
    ttk.Button(top,text='Refresh now',command=self.refresh_batch_workspace_preview).pack(side='right',padx=3)
    ttk.Button(top,text='Export batch tables',command=lambda: _v29_export_batch_tables(self)).pack(side='right',padx=3)
    defaults=ttk.Labelframe(fr,text='Preparation defaults',padding=5); defaults.grid(row=1,column=0,sticky='ew',padx=4,pady=3)
    self.batch_solution_conc=tk.StringVar(value='0.25'); self.batch_coupling_eq=tk.StringVar(value='10'); self.batch_actual_round_ml=tk.StringVar(value='10'); self.batch_actual_extra_ml=tk.StringVar(value='10'); self.batch_hbtu_eq=tk.StringVar(value='10'); self.batch_hbtu_conc=tk.StringVar(value='0.4')
    fields=[('AA conc M',self.batch_solution_conc),('AA eq',self.batch_coupling_eq),('Actual round mL',self.batch_actual_round_ml),('Extra reserve mL',self.batch_actual_extra_ml),('HBTU eq',self.batch_hbtu_eq),('HBTU conc M',self.batch_hbtu_conc)]
    for i,(lab,var) in enumerate(fields):
        ttk.Label(defaults,text=lab).grid(row=0,column=i*2,sticky='w',padx=(3,2)); ttk.Entry(defaults,textvariable=var,width=10).grid(row=0,column=i*2+1,sticky='w',padx=(0,10))
        try: var.trace_add('write', lambda *_: self.after_idle(self.refresh_batch_workspace_preview))
        except Exception: pass
    nb=ttk.Notebook(fr); nb.grid(row=2,column=0,sticky='nsew',padx=4,pady=4)
    self.v29_batch_trees={}
    for key,title in [('AA stock','AA stock'),('Coupling reagents','Coupling reagents'),('Catalyst/additive','Catalyst/additive'),('Solvents','Solvents'),('Chemicals','Chemicals'),('Summary','Summary')]:
        tab=ttk.Frame(nb); tab.rowconfigure(0,weight=1); tab.columnconfigure(0,weight=1); nb.add(tab,text=title)
        cols=V29_BATCH_COLUMNS if key!='Summary' else ['No','Project','Peptide name','LOT No','Sequence','Copies','Scale mmol','Resin','Chemistry']
        tree=ttk.Treeview(tab,columns=cols,show='headings'); y=ttk.Scrollbar(tab,orient='vertical',command=tree.yview); x=ttk.Scrollbar(tab,orient='horizontal',command=tree.xview)
        tree.configure(yscrollcommand=y.set,xscrollcommand=x.set); tree.grid(row=0,column=0,sticky='nsew'); y.grid(row=0,column=1,sticky='ns'); x.grid(row=1,column=0,sticky='ew')
        self.v29_batch_trees[key]=tree; _v29_write_tree(self,tree,pd.DataFrame(columns=cols),cols)
    self.after_idle(self.refresh_batch_workspace_preview)

def _v29_refresh_batch_workspace_preview(self):
    try:
        tables=_v29_calculate_batch_tables(self); trees=getattr(self,'v29_batch_trees',{})
        for key,df in tables.items():
            tree=trees.get(key)
            if tree is not None:
                cols=list(df.columns) if not df.empty else (V29_BATCH_COLUMNS if key!='Summary' else ['No','Project','Peptide name','LOT No','Sequence','Copies','Scale mmol','Resin','Chemistry'])
                _v29_write_tree(self,tree,df,cols)
    except Exception as e: _v29_safe_log(self,f'Batch refresh warning: {e}\n')

