# ========================= V1.0.30 HBTU/NMP CHECK + GLOBAL COMBO KEYJUMP =========================
# The following patch is intentionally appended instead of replacing large UI sections.
# It keeps all V1.0.29 working features and only strengthens:
#   1) HBTU/NMP formula reporting/checking
#   2) first-letter navigation for every ttk.Combobox/dropdown in the app
#
# HBTU/NMP chemistry reference:
#   target final volume (mL) = total HBTU mmol / HBTU concentration M
#   HBTU mass (g) = HBTU concentration M × final volume L × HBTU MW
#   NMP is the HBTU cocktail solvent. If a lab sheet requests an NMP molarity
#   check, the app reports an optional NMP equivalent-volume note separately.

APP_VERSION = 'V2.1.7'


def _v30_combobox_first_letter_jump(combo):
    """Bind first-letter navigation to a ttk.Combobox only.

    Behavior requested by user:
      - when the cursor/focus is on a dropdown field with a triangle button,
        pressing an English key jumps to the next option whose displayed name
        starts with that key;
      - repeated presses cycle through matching entries;
      - normal Entry/Text widgets are not affected.

    Examples:
      D -> DIC / DMF / DCM
      H -> HBTU / HATU / HOBt
      N -> NMP
      P -> Piperidine / Pal resin
    """
    try:
        if not isinstance(combo, ttk.Combobox):
            return combo
        if getattr(combo, "_v30_keyjump_bound", False):
            return combo
        combo._v30_keyjump_bound = True
        combo._letter_jump_last = (None, -1)

        def _jump(event):
            # Ignore modified/system shortcuts; accept plain English letters only.
            try:
                if getattr(event, "state", 0) & 0x0004:  # Ctrl
                    return None
                if getattr(event, "state", 0) & 0x0008:  # Alt
                    return None
            except Exception:
                pass
            ch = (getattr(event, "char", "") or "")
            if len(ch) != 1 or not ch.isascii() or not ch.isalpha():
                return None
            values = [str(v) for v in (combo.cget("values") or [])]
            if not values:
                return None
            key = ch.lower()
            last_key, last_pos = getattr(combo, "_letter_jump_last", (None, -1))
            start = (last_pos + 1) if last_key == key else 0
            # Primary behavior: startswith. Fallback: contains the letter.
            ordered = list(range(start, len(values))) + list(range(0, start))
            for i in ordered:
                if values[i].lower().startswith(key):
                    combo.set(values[i])
                    combo.icursor("end")
                    combo._letter_jump_last = (key, i)
                    try:
                        combo.event_generate("<<ComboboxSelected>>")
                    except Exception:
                        pass
                    return "break"
            for i in ordered:
                if key in values[i].lower():
                    combo.set(values[i])
                    combo.icursor("end")
                    combo._letter_jump_last = (key, i)
                    try:
                        combo.event_generate("<<ComboboxSelected>>")
                    except Exception:
                        pass
                    return "break"
            return None

        combo.bind("<KeyPress>", _jump, add="+")
        combo.bind("<FocusIn>", lambda _e: setattr(combo, "_letter_jump_last", (None, -1)), add="+")
    except Exception:
        pass
    return combo


# Replace the earlier helper name so editable Treeview comboboxes use V1.0.30 behavior too.
bind_combobox_first_letter_jump = _v30_combobox_first_letter_jump


def _v30_bind_all_combobox_typeahead(self):
    def walk(widget):
        try:
            if isinstance(widget, ttk.Combobox):
                _v30_combobox_first_letter_jump(widget)
            for child in widget.winfo_children():
                walk(child)
        except Exception:
            pass
    walk(self)
    # Some widgets are created lazily after tab construction; bind one more time later.
    try:
        self.after(500, lambda: walk(self))
        self.after(1500, lambda: walk(self))
    except Exception:
        pass


def _v30_hbtu_nmp_formula_check(self, target_final_ml=16.0, hbtu_conc=0.4, hbtu_mw=379.247, nmp_mw=99.133, nmp_density=1.028):
    """Return the bench-sheet HBTU/NMP check used for verification.

    For the user's reference image:
      HBTU = 0.4 M × 0.016 L × 379.247 g/mol = 2.43 g
    """
    try:
        final_l = float(target_final_ml) / 1000.0
        hbtu_mol = float(hbtu_conc) * final_l
        hbtu_g = hbtu_mol * float(hbtu_mw)
        # Optional NMP molarity check from the reference sheet.
        nmp_mol_08m = 0.8 * final_l
        nmp_g_08m = nmp_mol_08m * float(nmp_mw)
        nmp_ml_08m = nmp_g_08m / float(nmp_density) if nmp_density else 0.0
        return {
            "target_final_ml": target_final_ml,
            "hbtu_conc_M": hbtu_conc,
            "hbtu_mmol": hbtu_mol * 1000.0,
            "hbtu_g": hbtu_g,
            "nmp_08M_mmol": nmp_mol_08m * 1000.0,
            "nmp_08M_g": nmp_g_08m,
            "nmp_08M_ml": nmp_ml_08m,
        }
    except Exception:
        return {}


def _v30_records_to_df(self, records):
    """V1.0.30 total table conversion with explicit HBTU/NMP formula notes.

    Preserves V1.0.29 columns, rounding rules, and actual volume reserve behavior.
    """
    rows=[]
    for rec in records.values():
        item=rec['Item']; mmol=float(rec.get('mmol') or 0); conc=_v29_to_float(self, rec.get('Conc_M'), 0.0)
        mw,density=_v29_material_lookup(self,item)
        calc_ml=(mmol/conc) if conc else 0.0
        actual_ml=_v29_round_actual_ml(self, calc_ml) if calc_ml else 0.0
        weight_g=(actual_ml/1000.0*conc*mw) if (actual_ml and conc and mw) else ((mmol*mw/1000.0) if mw else 0.0)
        volume_ml=(weight_g/density) if (density and weight_g and not conc) else (actual_ml if actual_ml else 0.0)
        note=rec.get('Note','')
        if str(item).upper() == 'HBTU' and conc:
            note = (str(note) + '; ' if note else '') + 'formula: HBTU g = conc(M) × actual_L × MW; calc mL = mmol / conc(M)'
        if str(item).upper() == 'NMP':
            note = (str(note) + '; ' if note else '') + 'HBTU/NMP cocktail solvent; actual mL uses round-up/reserve'
        rows.append({'Category':rec['Category'],'Item':item,'Solvent':rec.get('Solvent',''),'Count':rec.get('Count',0),'Eq':rec.get('Eq',''),'Conc_M':conc if conc else '', 'Calculated_mL':calc_ml if calc_ml else '', 'Actual_mL':actual_ml if actual_ml else '', 'MW':mw if mw else '', 'Density':density if density else '', 'Weight_g':weight_g if weight_g else '', 'Volume_mL':volume_ml if volume_ml else '', 'Note':note})
    return pd.DataFrame(rows, columns=V29_BATCH_COLUMNS)


SPPSGui.bind_all_combobox_typeahead = _v30_bind_all_combobox_typeahead
SPPSGui._hbtu_nmp_formula_check = _v30_hbtu_nmp_formula_check
# Override the global conversion function used by V1.0.29 batch calculations.
_v29_records_to_df = _v30_records_to_df
