# ======================= V2.0.0 FINAL PATCH: TERMINAL-A DOUBLING + BUTTON FIX =======================
# This patch is the GitHub V2 final behavior requested after V1.0.30:
#   - Batch Manager AA stock calculation matches the synthesizer sheet convention:
#       main region = 1 eq, terminal A region = 2 eq when sequence is written as ...A
#       Example: QKELEKRIKEA x 6 gives A=12, E=18, K=18, Q=6, R=6, I=6, L=6.
#   - Optional explicit two-region syntax is also accepted: REGION1+REGION2 or REGION1|REGION2.
#       Region 2 residues are counted as 2 eq.
#   - Project Manager global action buttons are made stateful and immediately refresh all views.

try:
    _v2_old_apply_dic_hobt_preset = SPPSGui.apply_dic_hobt_preset
except Exception:
    _v2_old_apply_dic_hobt_preset = None
try:
    _v2_old_apply_hbtu_nmp_preset = SPPSGui.apply_hbtu_nmp_preset
except Exception:
    _v2_old_apply_hbtu_nmp_preset = None


def _v2_clean_seq_for_region_count(seq: str) -> str:
    s = str(seq or '').strip()
    # Remove common terminal/text modifiers while keeping amino-acid one-letter sequence.
    for token in ['Ac-', 'ac-', '-NH2', '-nh2', 'NH2', 'CONH2']:
        s = s.replace(token, '')
    return s.strip()


def _v2_letters_from_plain_region(self, region: str):
    try:
        return list(self._aa_letters_from_sequence(region))
    except Exception:
        return [c for c in str(region or '') if c.isalpha() and c.isupper() and c not in {'X'}]


def _v2_aa_counts_from_seq(self, seq):
    """AA equivalent counts for synthesizer stock preparation.

    Batch Manager is a synthesizer bottle calculator, not a simple sequence counter.
    The user's reference sheet has a 1 eq main region and a 2 eq terminal region.
    Therefore QKELEKRIKEA is interpreted as QKELEKRIKE at 1 eq + terminal A at 2 eq.
    Explicit syntax is supported too: QKELEKRIKE+A or QKELEKRIKE|A.
    """
    counts = {}
    s = _v2_clean_seq_for_region_count(seq)
    if not s:
        return counts

    # Explicit two-region input support.
    sep = None
    for candidate in ['|', '+', '/']:
        if candidate in s:
            sep = candidate
            break
    if sep:
        left, right = s.split(sep, 1)
        for aa in _v2_letters_from_plain_region(self, left):
            counts[aa] = counts.get(aa, 0.0) + 1.0
        for aa in _v2_letters_from_plain_region(self, right):
            counts[aa] = counts.get(aa, 0.0) + 2.0
        return counts

    letters = _v2_letters_from_plain_region(self, s)
    if not letters:
        return counts

    # Reference-sheet shorthand: terminal A is region 2 / 2 eq.
    # This makes QKELEKRIKEA x6 match the provided sheet: A=12 and main region at 1 eq.
    if len(letters) >= 2 and str(letters[-1]).upper() == 'A':
        main = letters[:-1]
        terminal = [letters[-1]]
        for aa in main:
            counts[aa] = counts.get(aa, 0.0) + 1.0
        for aa in terminal:
            counts[aa] = counts.get(aa, 0.0) + 2.0
        return counts

    for aa in letters:
        counts[aa] = counts.get(aa, 0.0) + 1.0
    return counts


