# ======================= V2.0.2 PATCH: SINGLE SOURCE SYNC + N-TERM DOUBLING FIX =======================
# Fixes after V2.0.0:
#   - User-entered sequence is N->C. AEKIRKELEKQ is the correct sequence.
#   - The N-terminal residue (first letter) is the doubling region for synthesizer AA stock prep.
#     Therefore AEKIRKELEKQ x6 gives A=12, E=18, K=18, Q=6, R=6, I=6, L=6.
#   - AA stock is 10 eq once, not 5 eq x 2.
#   - Project Manager is the single source of truth; every edit refreshes selected outputs and Batch Manager.
#   - Ambiguous Solvent 1 / Solvent 2 columns are hidden from the Project Manager selected-plan view.

VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'
try:
    SPPSGui.TITLE = VERSION_LABEL
except Exception:
    pass

_V201_PLAN_DISPLAY_COLUMNS = [
    "No", "Unit name", "Unit eq", "Unit amount(g)",
    "Coupling reagent 1", "Coupling reagent 2 / catalyst", "Coupling base", "Coupling cocktail solvent",
    "Coupling cocktail volume(mL)", "Repeat", "Note"
]


def _v201_seq_letters(self, seq: str):
    """Return clean one-letter AA sequence from a user N->C sequence string."""
    s = str(seq or "").strip()
    for token in ["Ac-", "ac-", "-NH2", "-nh2", "NH2", "CONH2"]:
        s = s.replace(token, "")
    # Treat explicit separators as plain sequence separators, not as reverse-order hacks.
    s = s.replace("|", "").replace("+", "").replace("/", "")
    try:
        letters = list(self._aa_letters_from_sequence(s))
    except Exception:
        letters = []
    if not letters:
        letters = [c for c in s if c.isalpha() and c.isupper() and c in set("ARNDCQEGHILKMFPSTWYV")]
    return letters


def _v201_aa_counts_from_seq(self, seq):
    """Synthesizer stock counts from N->C sequence.

    Default production rule: the first residue in N->C sequence is the N-terminal/doubling region.
    This is not the old reversed QKE... shorthand. It makes AEKIRKELEKQ match the user's sheet.
    """
    counts = {}
    letters = _v201_seq_letters(self, seq)
    if not letters:
        return counts
    for i, aa in enumerate(letters):
        factor = 2.0 if i == 0 else 1.0
        counts[aa] = counts.get(aa, 0.0) + factor
    return counts


def _v201_counts_for_item(self, item):
    """Use manual selected-plan intervention only if the user edited it; otherwise use N->C doubling counts."""
    try:
        manual = item.get("manual_plan") or []
        # Do not trust auto-generated selected plan as manual intervention unless explicitly marked.
        if item.get("manual_plan_edited") and manual:
            counts = self._v28_manual_plan_counts_for_item(item)
            if counts:
                return counts
    except Exception:
        pass
    return _v201_aa_counts_from_seq(self, item.get("sequence", ""))


def _v201_round1(x):
    try:
        return round(float(x), 1)
    except Exception:
        return x


def _v201_round2(x):
    try:
        return round(float(x), 2)
    except Exception:
        return x


def _v201_aa_calculator_df(self, rows=None):
    try:
        conc = float(self.batch_solution_conc.get())
    except Exception:
        conc = 0.25
    try:
        aa_eq = float(self.batch_coupling_eq.get())
    except Exception:
        aa_eq = 10.0
    # Force synthesizer-stock default: 10 eq once.
    if aa_eq <= 0:
        aa_eq = 10.0
    totals = {}
    for item in list(getattr(self, "pm_items", []) or []):
        seq = str(item.get("sequence", "") or "").strip()
        if not seq:
            continue
        try:
            copies = max(int(float(item.get("copies", 1) or 1)), 1)
        except Exception:
            copies = 1
        try:
            scale = float(item.get("scale", 0.2) or 0.2)
        except Exception:
            scale = 0.2
        for aa, local_count in _v201_counts_for_item(self, item).items():
            count = float(local_count or 0) * copies
            totals.setdefault(aa, {"count": 0.0, "mmol": 0.0})
            totals[aa]["count"] += count
            totals[aa]["mmol"] += count * scale * aa_eq
    out = []
    for aa in sorted(totals):
        count = totals[aa]["count"]
        mmol = totals[aa]["mmol"]
        calc_ml = mmol / conc if conc else 0.0
        actual_ml = self._v23_roundup_ml(calc_ml)
        mw = self._mw_for_token(aa) or self.MW_FALLBACK.get(aa, 0.0)
        weight_g = actual_ml / 1000.0 * conc * mw if actual_ml and conc and mw else 0.0
        count_disp = int(count) if abs(count - round(count)) < 1e-9 else _v201_round2(count)
        out.append({
            "AA": aa,
            "count": count_disp,
            "eq": _v201_round2(aa_eq),
            "solvent": "DMF",
            "conc_M": _v201_round2(conc),
            "calculated_mL": _v201_round1(calc_ml),
            "actual_mL": _v201_round1(actual_ml),
            "MW": _v201_round2(mw) if mw else "manual",
            "weight_g": _v201_round2(weight_g),
            "note": "AA stock for synthesizer: 10 eq once; N-terminal first residue is doubled; actual mL includes reserve",
        })
    return pd.DataFrame(out, columns=["AA", "count", "eq", "solvent", "conc_M", "calculated_mL", "actual_mL", "MW", "weight_g", "note"])


def _v201_batch_totals(self, rows=None):
    coupling = {}; catalyst = {}; solvent = {}; modifier = {}
    try: hbtu_eq = float(self.batch_hbtu_eq.get())
    except Exception: hbtu_eq = 10.0
    try: hbtu_conc = float(self.batch_hbtu_conc.get())
    except Exception: hbtu_conc = 0.4
    try: aa_eq = float(self.batch_coupling_eq.get())
    except Exception: aa_eq = 10.0
    for item in list(getattr(self, "pm_items", []) or []):
        seq = str(item.get("sequence", "") or "").strip()
        if not seq:
            continue
        try: copies = max(int(float(item.get("copies", 1) or 1)), 1)
        except Exception: copies = 1
        try: scale = float(item.get("scale", 0.2) or 0.2)
        except Exception: scale = 0.2
        counts = _v201_counts_for_item(self, item)
        # one coupling bottle event per equivalent-counted residue for synthesizer prep.
        steps = sum(float(v or 0) for v in counts.values()) * copies
        step_mmol = steps * scale
        chem = str(item.get("chemistry", "DIC/HOBt") or "DIC/HOBt")
        if steps:
            if "HBTU/NMP" in chem:
                self._v23_add_solution_record(coupling, "HBTU", "coupling reagent stock", steps, hbtu_eq, "NMP", hbtu_conc, step_mmol * hbtu_eq, "HBTU/NMP stock; HBTU g = M x L x MW")
                calc_ml = (step_mmol * hbtu_eq) / hbtu_conc if hbtu_conc else 0.0
                self._v23_add_solution_record(solvent, "NMP", "HBTU/NMP stock solvent", steps, "", "", 0, calc_ml, "NMP volume for HBTU/NMP stock before reserve")
            else:
                # DIC/HOBt are kept; default is still the setup value, but AA stock remains 10 eq once.
                try: dic_eq = float(self.default_reagent_eq.get())
                except Exception: dic_eq = 5.0
                try: hobt_eq = float(self.default_catalyst_eq.get())
                except Exception: hobt_eq = 5.0
                self._v23_add_solution_record(coupling, "DIC", "coupling reagent", steps, dic_eq, "neat/DMF", 0, step_mmol * dic_eq, "DIC for synthesizer coupling prep")
                add = "Oxyma" if "Oxyma" in chem else "HOBt"
                self._v23_add_solution_record(catalyst, add, "catalyst/additive", steps, hobt_eq, "DMF", 0, step_mmol * hobt_eq, "catalyst/additive for coupling bottle")
                self._v23_add_solution_record(solvent, "DMF", "coupling solvent reservoir", steps, "", "", 0, step_mmol * max(aa_eq, 10.0), "DMF for coupling/cocktail transfer; reserve applied")
            self._v23_add_solution_record(solvent, "DMF", "AA stock solvent", steps, "", "", 0, 0, "AA stock solvent volume is shown in AA stock table")
        if self._sequence_has_nterm_ac(seq):
            self._v23_add_solution_record(modifier, "Acetic anhydride (Ac2O)", "N-terminal Ac cap", copies, 3.0, "neat/DMF", 0, copies * scale * 3.0, "Ac detected from sequence prefix Ac-")
    return {"coupling": self._v23_solution_records_to_df(coupling), "catalyst": self._v23_solution_records_to_df(catalyst), "solvent": self._v23_solution_records_to_df(solvent), "modifier": self._v23_solution_records_to_df(modifier)}


def _v201_clean_selected_plan_view(self):
    """Hide ambiguous Solvent 1/2 columns in the visible Project Manager selected-plan table."""
    try:
        tree = getattr(self, "pm_selected_plan_tree", None)
        if tree is None:
            return
        df = self.pm_tree_to_df(getattr(self, "tree", None)) if hasattr(self, "pm_tree_to_df") else pd.DataFrame()
        cols = [c for c in _V201_PLAN_DISPLAY_COLUMNS if c in list(df.columns)]
        if not cols:
            cols = ["No", "Unit name", "Unit eq", "Unit amount(g)", "Coupling reagent 1", "Coupling cocktail solvent"]
        self._write_tree(tree, df, cols)
    except Exception:
        pass


