def _v201_pm_live_sync_selected(self):
    # Replace any previous live-sync with a stricter single-source-of-truth update.
    if getattr(self, "_pm_loading_editor", False):
        return
    idx = self.pm_current_index() if hasattr(self, "pm_list") else None
    if idx is None or idx < 0 or idx >= len(getattr(self, "pm_items", [])):
        return
    try:
        self.pm_items[idx].update({
            "project": self.pm_project.get().strip(),
            "peptide": self.pm_peptide.get().strip(),
            "sequence": self.pm_sequence.get().strip(),
            "scale": self.pm_scale.get().strip(),
            "resin": self.pm_resin.get().strip(),
            "loading": self.pm_loading.get().strip(),
            "lot": self.pm_lot.get().strip(),
            "chemistry": self.pm_chemistry.get().strip(),
            "copies": self.pm_copies.get().strip(),
            "status": self.pm_items[idx].get("status", "Ready"),
        })
        self.pm_refresh_list(keep_index=idx, reload_editor=False)
        self.pm_update_summary()
        try:
            self.refresh_batch_workspace_preview()
        except Exception:
            pass
        self.schedule_autosave()
    except Exception:
        pass


