def _v201_build_project_manager_tab(self):
    if _v201_old_build_pm_tab:
        _v201_old_build_pm_tab(self)
    try:
        # Keep AA stock at 10 eq once by default.
        if hasattr(self, "batch_coupling_eq"):
            self.batch_coupling_eq.set("10")
    except Exception:
        pass
    # Ensure editor variables trigger full live sync.
    def changed(*_):
        try:
            self.after_idle(lambda _self=self: _v201_refresh_all_views(_self))
        except Exception:
            pass
    for name in ["pm_project", "pm_peptide", "pm_sequence", "pm_scale", "pm_resin", "pm_loading", "pm_lot", "pm_chemistry", "pm_copies"]:
        var = getattr(self, name, None)
        if hasattr(var, "trace_add"):
            try:
                var.trace_add("write", lambda *_: changed())
            except Exception:
                pass
    try:
        _v201_clean_selected_plan_view(self)
    except Exception:
        pass


