def _v203_pm_rows(self):
    rows = []
    for i, item in enumerate(list(getattr(self, "pm_items", []) or []), start=1):
        seq = str(item.get("sequence", "") or "").strip()
        if not seq:
            continue
        resin = _v203_normalize_resin_name(item.get("resin", ""))
        loading = _v29_to_float(self, item.get("loading", ""), 0.0)
        scale = _v29_to_float(self, item.get("scale", "0.2"), 0.2)
        resin_g = scale / loading if loading else 0.0
        rows.append({
            "No": i,
            "Project": item.get("project", ""),
            "Peptide name": item.get("peptide", ""),
            "Sequence": seq,
            "Copies": item.get("copies", "1") or "1",
            "Scale mmol": item.get("scale", "0.2") or "0.2",
            "Resin": resin,
            "Loading": item.get("loading", ""),
            "Resin_g": _v201_round2(resin_g) if resin_g else "",
            "LOT No": item.get("lot", ""),
            "Chemistry": item.get("chemistry", "DIC/HOBt") or "DIC/HOBt",
        })
    return rows


def _v203_last_aa_from_sequence(self, seq: str) -> str:
    try:
        aas = list(self._aa_letters_from_sequence(seq))
    except Exception:
        aas = [c for c in str(seq or "") if c.isalpha() and c.isupper()]
    aas = [a for a in aas if str(a).upper() not in ("AC", "NH")]
    return str(aas[-1]).strip() if aas else ""


def _v203_resin_loading_df(self, rows=None):
    rows = rows if rows is not None else _v203_pm_rows(self)
    out = []
    for r in rows:
        resin = _v203_normalize_resin_name(r.get("Resin", ""))
        if not _v203_is_trityl_resin(resin):
            continue
        copies = max(int(round(_v29_to_float(self, r.get("Copies"), 1))), 1)
        scale = _v29_to_float(self, r.get("Scale mmol"), 0.2)
        loading = _v29_to_float(self, r.get("Loading"), 0.0)
        resin_mmol = scale * copies
        resin_g = resin_mmol / loading if loading else 0.0
        cterm_aa = _v203_last_aa_from_sequence(self, r.get("Sequence", ""))
        loading_aa_mmol = resin_mmol * 2.0
        diea_mmol = resin_mmol * 4.0
        aa_mw = self._mw_for_token(cterm_aa) if cterm_aa else 0.0
        diea_mw = self._mw_for_token("DIEA") or 129.25
        diea_density = self._density_for_token("DIEA") or 0.742
        loading_aa_g = loading_aa_mmol * aa_mw / 1000.0 if aa_mw else 0.0
        diea_g = diea_mmol * diea_mw / 1000.0 if diea_mw else 0.0
        diea_ml = diea_g / diea_density if diea_density else 0.0
        solvent = "90% DCM / 10% DMF"
        out.append({
            "Category": "Resin loading",
            "Item": resin,
            "Solvent": "",
            "Count": copies,
            "Eq": 1,
            "Conc_M": "",
            "Calculated_mL": "",
            "Actual_mL": "",
            "MW": "",
            "Density": "",
            "Weight_g": _v201_round2(resin_g),
            "Volume_mL": "",
            "Note": f"loading rate used: resin_g = {resin_mmol:.2f} mmol / {loading:.2f} mmol/g" if loading else "loading rate missing; resin mass not calculated",
        })
        if cterm_aa:
            out.append({
                "Category": "Resin loading",
                "Item": cterm_aa,
                "Solvent": solvent,
                "Count": copies,
                "Eq": 2,
                "Conc_M": "",
                "Calculated_mL": "",
                "Actual_mL": "",
                "MW": _v201_round2(aa_mw) if aa_mw else "manual",
                "Density": "",
                "Weight_g": _v201_round2(loading_aa_g),
                "Volume_mL": "",
                "Note": "C-terminal loading amino acid for 2-CTC/Trityl; resin:AA:DIEA = 1:2:4",
            })
        out.append({
            "Category": "Resin loading",
            "Item": "DIEA",
            "Solvent": solvent,
            "Count": copies,
            "Eq": 4,
            "Conc_M": "",
            "Calculated_mL": _v201_round1(diea_ml),
            "Actual_mL": _v201_round1(diea_ml),
            "MW": _v201_round2(diea_mw),
            "Density": _v201_round2(diea_density),
            "Weight_g": _v201_round2(diea_g),
            "Volume_mL": _v201_round1(diea_ml),
            "Note": "DIEA for 2-CTC/Trityl loading; exact 4 eq shown without forced reserve",
        })
    return pd.DataFrame(out, columns=V29_BATCH_COLUMNS)


def _v203_calculate_batch_tables(self):
    """Compatibility route to the single V2.2.5 Batch calculator."""
    final = globals().get('_v225_calculate_batch_tables')
    if callable(final):
        return final(self)
    raise RuntimeError('V2.2.5 Batch calculator is not loaded yet')


def _v203_export_batch_tables(self):
    try:
        outdir = Path(getattr(self, "outdir", _v225_const_var("spps_output")).get() or "spps_output") / "batch_manager"
        outdir.mkdir(parents=True, exist_ok=True)
        tables = _v203_calculate_batch_tables(self)
        with pd.ExcelWriter(outdir / "batch_synthesizer_calculator.xlsx", engine="openpyxl") as writer:
            for name, df in tables.items():
                df.to_excel(writer, index=False, sheet_name=name[:31])
        messagebox.showinfo("Export complete", f"Batch calculator saved:\n{outdir}")
    except Exception as e:
        messagebox.showerror("Export error", str(e))


def _v203_build_batch_tab(self):
    fr = ttk.Frame(self.tabs)
    self.tabs.add(fr, text="Batch Manager")
    fr.rowconfigure(2, weight=1)
    fr.columnconfigure(0, weight=1)
    top = ttk.Frame(fr, padding=4)
    top.grid(row=0, column=0, sticky="ew")
    ttk.Label(top, text="Synthesizer stock/cocktail calculator - linked live from Project Manager").pack(side="left")
    ttk.Button(top, text="Refresh now", command=self.refresh_batch_workspace_preview).pack(side="right", padx=3)
    ttk.Button(top, text="Export batch tables", command=lambda: _v203_export_batch_tables(self)).pack(side="right", padx=3)
    defaults = ttk.Labelframe(fr, text="Preparation defaults", padding=5)
    defaults.grid(row=1, column=0, sticky="ew", padx=4, pady=3)
    self.batch_solution_conc = tk.StringVar(value="0.25")
    self.batch_coupling_eq = tk.StringVar(value="10")
    self.batch_actual_round_ml = tk.StringVar(value="10")
    self.batch_actual_extra_ml = tk.StringVar(value="10")
    self.batch_hbtu_eq = tk.StringVar(value="10")
    self.batch_hbtu_conc = tk.StringVar(value="0.4")
    fields = [
        ("Final AA stock conc. (M)", self.batch_solution_conc),
        ("AA eq", self.batch_coupling_eq),
        ("Actual round mL", self.batch_actual_round_ml),
        ("Extra reserve mL", self.batch_actual_extra_ml),
        ("HBTU eq", self.batch_hbtu_eq),
        ("HBTU final conc. (M)", self.batch_hbtu_conc),
    ]
    for i, (lab, var) in enumerate(fields):
        ttk.Label(defaults, text=lab).grid(row=0, column=i*2, sticky="w", padx=(3, 2))
        ttk.Entry(defaults, textvariable=var, width=10).grid(row=0, column=i*2+1, sticky="w", padx=(0, 10))
        try:
            var.trace_add("write", lambda *_: self.after_idle(self.refresh_batch_workspace_preview))
        except Exception:
            pass
    nb = ttk.Notebook(fr)
    nb.grid(row=2, column=0, sticky="nsew", padx=4, pady=4)
    self.v29_batch_trees = {}
    tabs = [
        ("AA stock", "AA stock"),
        ("Resin loading", "Resin loading"),
        ("Coupling reagents", "Coupling reagents"),
        ("Catalyst/additive", "Catalyst/additive"),
        ("Solvents", "Solvents"),
        ("Chemicals", "Chemicals"),
        ("Summary", "Summary"),
    ]
    for key, title in tabs:
        tab = ttk.Frame(nb)
        tab.rowconfigure(0, weight=1)
        tab.columnconfigure(0, weight=1)
        nb.add(tab, text=title)
        cols = V29_BATCH_COLUMNS if key != "Summary" else ["No", "Project", "Peptide name", "LOT No", "Sequence", "Copies", "Scale mmol", "Resin", "Loading", "Resin_g", "Chemistry"]
        tree = ttk.Treeview(tab, columns=cols, show="headings")
        y = ttk.Scrollbar(tab, orient="vertical", command=tree.yview)
        x = ttk.Scrollbar(tab, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=y.set, xscrollcommand=x.set)
        tree.grid(row=0, column=0, sticky="nsew")
        y.grid(row=0, column=1, sticky="ns")
        x.grid(row=1, column=0, sticky="ew")
        self.v29_batch_trees[key] = tree
        _v29_write_tree(self, tree, pd.DataFrame(columns=cols), cols)
    self.after_idle(self.refresh_batch_workspace_preview)


def _v203_refresh_batch_workspace_preview(self):
    try:
        tables = _v203_calculate_batch_tables(self)
        trees = getattr(self, "v29_batch_trees", {})
        for key, tree in trees.items():
            df = tables.get(key, pd.DataFrame())
            if key == "Summary":
                cols = ["No", "Project", "Peptide name", "LOT No", "Sequence", "Copies", "Scale mmol", "Resin", "Loading", "Resin_g", "Chemistry"]
            else:
                cols = V29_BATCH_COLUMNS
            _v29_write_tree(self, tree, df, cols)
    except Exception as e:
        _v29_safe_log(self, f"Batch refresh warning: {e}\n")


