def _v204_commit_editor_to_selected_item(self):
    idx = self.pm_selected_index() if hasattr(self, "pm_selected_index") else None
    if idx is None or idx < 0 or idx >= len(getattr(self, "pm_items", []) or []):
        return None
    item = self.pm_items[idx]
    def _get(name, default=""):
        try:
            return str(getattr(self, name).get()).strip()
        except Exception:
            return str(default)
    item.update({
        "project": _get("pm_project", item.get("project", "")),
        "peptide": _get("pm_peptide", item.get("peptide", "")),
        "sequence": _get("pm_sequence", item.get("sequence", "")),
        "scale": _get("pm_scale", item.get("scale", "0.2")),
        "resin": _v203_normalize_resin_name(_get("pm_resin", item.get("resin", "Rink Amide AM"))) if "_v203_normalize_resin_name" in globals() else _get("pm_resin", item.get("resin", "Rink Amide AM")),
        "loading": _get("pm_loading", item.get("loading", "0.8")),
        "lot": _get("pm_lot", item.get("lot", "")),
        "chemistry": _get("pm_chemistry", item.get("chemistry", "DIC/HOBt")),
        "copies": _get("pm_copies", item.get("copies", "1")),
        "status": item.get("status", "Ready"),
    })
    return item


def _v204_sync_everything(self):
    try:
        _v204_commit_editor_to_selected_item(self)
    except Exception:
        pass
    try:
        self.pm_refresh_list(keep=self.pm_selected_index())
    except Exception:
        pass
    try:
        self.refresh_outputs_from_tree()
    except Exception:
        pass
    try:
        if '_v201_clean_selected_plan_view' in globals():
            _v201_clean_selected_plan_view(self)
    except Exception:
        pass
    try:
        self.pm_refresh_batch_totals()
    except Exception:
        pass
    try:
        self.refresh_batch_workspace_preview()
    except Exception:
        pass
    try:
        self.schedule_autosave()
    except Exception:
        pass


