def _v205_to_float(v, default=0.0):
    try:
        if hasattr(v, 'get'):
            v = v.get()
        return float(str(v).strip())
    except Exception:
        return float(default)


def _v205_set_var(var, value):
    try:
        cur = str(var.get())
        new = str(value)
        if cur != new:
            var.set(new)
    except Exception:
        pass


def _v205_sync_eq_fields(self, source="batch"):
    """Keep PM setup eq and Batch Manager eq as one source of truth."""
    if getattr(self, '_v205_syncing_defaults', False):
        return
    self._v205_syncing_defaults = True
    try:
        # User-facing main eq. Prefer Batch Manager AA eq if present, otherwise PM Default AA eq.
        if source == "pm":
            eq = _v205_to_float(getattr(self, 'coupling_eq', None), 10.0)
        else:
            eq = _v205_to_float(getattr(self, 'batch_coupling_eq', None), _v205_to_float(getattr(self, 'coupling_eq', None), 10.0))
        # Solid synthesis stock/cocktail eqs are intentionally same-ratio by default.
        for name in ('coupling_eq', 'default_reagent_eq', 'default_catalyst_eq', 'batch_coupling_eq', 'batch_hbtu_eq'):
            if hasattr(self, name):
                var = getattr(self, name)
                try:
                    # DoubleVar prefers numeric; StringVar accepts string.
                    var.set(eq)
                except Exception:
                    _v205_set_var(var, eq)
        try:
            self.after_idle(self.refresh_batch_workspace_preview)
        except Exception:
            pass
        try:
            self.after_idle(lambda: _v204_sync_everything(self) if '_v204_sync_everything' in globals() else None)
        except Exception:
            pass
    finally:
        self._v205_syncing_defaults = False


def _v205_sync_conc_fields(self):
    # AA final stock concentration remains user-editable, default 0.25 M.
    if not hasattr(self, 'batch_solution_conc'):
        return
    try:
        self.after_idle(self.refresh_batch_workspace_preview)
    except Exception:
        pass
    try:
        self.schedule_autosave()
    except Exception:
        pass


def _v205_install_default_sync(self):
    """Attach traces after all widgets/variables exist."""
    if getattr(self, '_v205_default_sync_installed', False):
        return
    self._v205_default_sync_installed = True
    # Enforce current default: final AA stock 0.25 M and eq 10 unless user session restored another value.
    try:
        if hasattr(self, 'batch_solution_conc') and str(self.batch_solution_conc.get()).strip() in ('', '0', '0.0'):
            self.batch_solution_conc.set('0.25')
    except Exception:
        pass
    # If old V2.0.6 default carried 5 eq, upgrade it to 10 for production synthesizer stock/cocktail use.
    try:
        if hasattr(self, 'coupling_eq') and abs(float(self.coupling_eq.get()) - 5.0) < 1e-9:
            self.coupling_eq.set(10.0)
    except Exception:
        pass
    try:
        if hasattr(self, 'batch_coupling_eq') and abs(float(self.batch_coupling_eq.get()) - 5.0) < 1e-9:
            self.batch_coupling_eq.set('10')
    except Exception:
        pass
    _v205_sync_eq_fields(self, source='pm')
    # Trace both PM setup and Batch Manager defaults.
    pairs = [
        ('coupling_eq', 'pm'),
        ('default_reagent_eq', 'pm'),
        ('default_catalyst_eq', 'pm'),
        ('batch_coupling_eq', 'batch'),
        ('batch_hbtu_eq', 'batch'),
    ]
    for attr, src in pairs:
        try:
            var = getattr(self, attr)
            var.trace_add('write', lambda *_, _src=src: _v205_sync_eq_fields(self, source=_src))
        except Exception:
            pass
    for attr in ('batch_solution_conc', 'batch_actual_round_ml', 'batch_actual_extra_ml', 'batch_hbtu_conc'):
        try:
            var = getattr(self, attr)
            var.trace_add('write', lambda *_: _v205_sync_conc_fields(self))
        except Exception:
            pass


