# First-letter jump for all comboboxes/dropdowns; normal Entry/Text untouched.
def _v206_bind_combobox_jump(widget):
    try:
        if isinstance(widget, ttk.Combobox):
            vals = list(widget.cget("values") or [])
            def _jump(event, combo=widget):
                ch = getattr(event, "char", "") or ""
                if len(ch) != 1 or not ch.isalnum():
                    return None
                try:
                    vals_now = list(combo.cget("values") or [])
                    if not vals_now:
                        return None
                    cur = str(combo.get() or "")
                    start = 0
                    for i, v in enumerate(vals_now):
                        if str(v) == cur:
                            start = (i + 1) % len(vals_now)
                            break
                    letter = ch.lower()
                    ordered = vals_now[start:] + vals_now[:start]
                    for v in ordered:
                        if str(v).lower().startswith(letter):
                            combo.set(v)
                            combo.event_generate("<<ComboboxSelected>>")
                            return "break"
                    for v in ordered:
                        if letter in str(v).lower():
                            combo.set(v)
                            combo.event_generate("<<ComboboxSelected>>")
                            return "break"
                except Exception:
                    return None
            combo_bindings = str(widget.bind("<KeyPress>") or "")
            widget.bind("<KeyPress>", _jump, add="+")
    except Exception:
        pass
    try:
        for child in widget.winfo_children():
            _v206_bind_combobox_jump(child)
    except Exception:
        pass


def _v206_build_pm_setup_panel(self, parent):
    _v206_ensure_loading_ratio_vars(self)
    panel = ttk.Labelframe(parent, text="Setup defaults", padding=6)
    self.pm_setup_panel = panel
    nb = ttk.Notebook(panel)
    nb.pack(fill="x", expand=False)
