# Override GUI input to pass loading ratio into engine PlanInput.
def _v206_input(self):
    inp = PlanInput(
        sequence=self.seq.get().strip(),
        resin=self.resin.get(),
        scale_mmol=float(self.scale.get()),
        resin_loading_mmol_g=float(self.loading.get()),
        coupling_eq=float(self.coupling_eq.get()),
        ac_eq=float(self.modifier_eq.get()),
        default_coupling_repeats=int(self.coupling_repeats.get()),
        default_modifier_repeats=int(self.modifier_repeats.get()),
        default_coupling_reagent=self.default_reagent.get().strip(),
        default_catalyst=self.default_catalyst.get().strip(),
        default_base=self.default_base.get().strip(),
        default_reaction_solvent=self.default_solvent1.get().strip(),
        step_overrides_text="",
    )
    try:
        inp.loading_aa_eq = _v206_to_float_value(getattr(self, "loading_aa_eq", None), 2.0)
        inp.loading_diea_eq = _v206_to_float_value(getattr(self, "loading_diea_eq", None), 4.0)
    except Exception:
        pass
    return inp


# Resin loading batch tab uses user-editable loading AA/DIEA eq.
def _v206_resin_loading_df(self, rows=None):
    rows = rows if rows is not None else _v203_pm_rows(self)
    out = []
    aa_eq = _v206_to_float_value(getattr(self, "loading_aa_eq", None), 2.0)
    diea_eq = _v206_to_float_value(getattr(self, "loading_diea_eq", None), 4.0)
    for r in rows:
        resin = _v203_normalize_resin_name(r.get("Resin", ""))
        if not _v203_is_trityl_resin(resin):
            continue
        copies = max(int(round(_v29_to_float(self, r.get("Copies"), 1))), 1)
        scale = _v29_to_float(self, r.get("Scale mmol"), 0.2)
        loading = _v29_to_float(self, r.get("Loading"), 0.0)
        resin_mmol = scale * copies
        resin_g = resin_mmol / loading if loading else 0.0
        cterm_aa = _v203_last_aa_from_sequence(self, r.get("Sequence", ""))
        loading_aa_mmol = resin_mmol * aa_eq
        diea_mmol = resin_mmol * diea_eq
        aa_mw = self._mw_for_token(cterm_aa) if cterm_aa else 0.0
        diea_mw = self._mw_for_token("DIEA") or 129.25
        diea_density = self._density_for_token("DIEA") or 0.742
        loading_aa_g = loading_aa_mmol * aa_mw / 1000.0 if aa_mw else 0.0
        diea_g = diea_mmol * diea_mw / 1000.0 if diea_mw else 0.0
        diea_ml = diea_g / diea_density if diea_density else 0.0
        solvent = str(getattr(self, "default_loading_dissolve_solvent", _v225_const_var("90% DCM / 10% DMF")).get() or "90% DCM / 10% DMF")
        ratio_note = f"resin:AA:DIEA = 1:{aa_eq:g}:{diea_eq:g}"
        out.append({"Category":"Resin loading","Item":resin,"Solvent":"","Count":copies,"Eq":1,"Conc_M":"","Calculated_mL":"","Actual_mL":"","MW":"","Density":"","Weight_g":_v201_round2(resin_g),"Volume_mL":"","Note":f"loading rate used: resin_g = {resin_mmol:.2f} mmol / {loading:.2f} mmol/g" if loading else "loading rate missing; resin mass not calculated"})
        if cterm_aa:
            out.append({"Category":"Resin loading","Item":cterm_aa,"Solvent":solvent,"Count":copies,"Eq":aa_eq,"Conc_M":"","Calculated_mL":"","Actual_mL":"","MW":_v201_round2(aa_mw) if aa_mw else "manual","Density":"","Weight_g":_v201_round2(loading_aa_g),"Volume_mL":"","Note":f"C-terminal loading amino acid for 2-CTC/Trityl; {ratio_note}"})
        out.append({"Category":"Resin loading","Item":"DIEA","Solvent":solvent,"Count":copies,"Eq":diea_eq,"Conc_M":"","Calculated_mL":_v201_round1(diea_ml),"Actual_mL":_v201_round1(diea_ml),"MW":_v201_round2(diea_mw),"Density":_v201_round2(diea_density),"Weight_g":_v201_round2(diea_g),"Volume_mL":_v201_round1(diea_ml),"Note":f"DIEA for 2-CTC/Trityl loading; {ratio_note}"})
    return pd.DataFrame(out, columns=V29_BATCH_COLUMNS)


# Shift-click range selection for peptide items.  Tk extended selection does this natively;
# this small handler makes it stable even after the list is refreshed.
def _v206_pm_shift_click(self, event=None):
    try:
        lb = self.pm_list
        idx = lb.nearest(event.y)
        anchor = getattr(self, "_pm_shift_anchor", None)
        if anchor is None:
            sel = lb.curselection()
            anchor = int(sel[0]) if sel else idx
        lo, hi = sorted((int(anchor), int(idx)))
        lb.selection_clear(0, "end")
        lb.selection_set(lo, hi)
        lb.activate(idx)
        self._pm_shift_anchor = anchor
        self.pm_load_to_editor(idx)
        return "break"
    except Exception:
        return None


def _v206_pm_on_select(self, event=None):
    try:
        sel = self.pm_list.curselection()
        if sel:
            self._pm_shift_anchor = int(sel[0])
    except Exception:
        pass
    try:
        return _v206_old_pm_on_select(self, event)
    except Exception:
        idx = self.pm_current_index()
        if idx is not None:
            self.pm_load_to_editor(idx)


def _v206_pm_delete_peptide(self):
    try:
        sel = list(self.pm_list.curselection())
    except Exception:
        sel = []
    if not sel:
        idx = self.pm_current_index()
        sel = [idx] if idx is not None else []
    for idx in sorted([int(x) for x in sel if x is not None], reverse=True):
        if 0 <= idx < len(getattr(self, "pm_items", [])):
            del self.pm_items[idx]
    if not getattr(self, "pm_items", []):
        self.pm_add_peptide()
    self.pm_refresh_list()
    self.schedule_autosave()
    try:
        self.refresh_batch_workspace_preview()
    except Exception:
        pass


