def _v207_get_material_overrides(self):
    if not hasattr(self, "material_overrides") or self.material_overrides is None:
        self.material_overrides = {}
    return self.material_overrides


def _v207_normal_key(name):
    return str(name or "").strip().lower()


def _v207_base_material_name(name):
    text = str(name or "").strip()
    # Common displayed AA names are like Fmoc-Lys(Boc)-OH; use the exact display key
    # for overrides, but also store amino-acid one-letter aliases when possible.
    return text


try:
    _v207_old_mw_for_token = SPPSGui._mw_for_token
except Exception:
    _v207_old_mw_for_token = None


def _v207_mw_for_token(self, token: str) -> float:
    key = _v207_normal_key(_v207_base_material_name(token))
    overrides = _v207_get_material_overrides(self)
    try:
        if key in overrides and str(overrides[key].get("MW", "")).strip() != "":
            return float(overrides[key]["MW"])
    except Exception:
        pass
    # Also allow one-letter override for Fmoc-AA display names.
    try:
        aa = self._v28_extract_aa_from_unit(token) if hasattr(self, "_v28_extract_aa_from_unit") else None
        if aa and _v207_normal_key(aa) in overrides and str(overrides[_v207_normal_key(aa)].get("MW", "")).strip() != "":
            return float(overrides[_v207_normal_key(aa)]["MW"])
    except Exception:
        pass
    if _v207_old_mw_for_token:
        return _v207_old_mw_for_token(self, token)
    return 0.0


try:
    _v207_old_density_for_token = SPPSGui._density_for_token
except Exception:
    _v207_old_density_for_token = None
try:
    _v207_old_density_for = SPPSGui._density_for
except Exception:
    _v207_old_density_for = None


def _v207_density_for_token(self, token: str) -> float:
    key = _v207_normal_key(_v207_base_material_name(token))
    overrides = _v207_get_material_overrides(self)
    try:
        for k in [key, _v207_normal_key(str(token).replace("Acetic anhydride", "Ac2O"))]:
            if k in overrides and str(overrides[k].get("density_g_per_mL", overrides[k].get("Density", ""))).strip() != "":
                return float(overrides[k].get("density_g_per_mL", overrides[k].get("Density", "")))
    except Exception:
        pass
    if _v207_old_density_for_token:
        return _v207_old_density_for_token(self, token)
    return 0.0


def _v207_density_for(self, name: str) -> float:
    try:
        den = _v207_density_for_token(self, name)
        if den:
            return den
    except Exception:
        pass
    if _v207_old_density_for:
        return _v207_old_density_for(self, name)
    return 0.0


def _v207_material_density_column_name(cols):
    if "density_g_per_mL" in cols:
        return "density_g_per_mL"
    if "Density" in cols:
        return "Density"
    if "density" in cols:
        return "density"
    return "density_g_per_mL"


def _v207_enrich_material_df(self, df):
    if df is None:
        return pd.DataFrame()
    out = df.copy()
    if "material" not in out.columns:
        return out
    if "MW" not in out.columns:
        out.insert(min(3, len(out.columns)), "MW", "")
    density_col = _v207_material_density_column_name(list(out.columns))
    if density_col not in out.columns:
        try:
            insert_at = list(out.columns).index("MW") + 1
        except Exception:
            insert_at = min(4, len(out.columns))
        out.insert(insert_at, density_col, "")
    for i, row in out.iterrows():
        mat = row.get("material", "")
        try:
            mw = _v207_mw_for_token(self, mat)
            if mw:
                out.at[i, "MW"] = round(float(mw), 2)
        except Exception:
            pass
        try:
            den = _v207_density_for_token(self, mat)
            if den:
                out.at[i, density_col] = round(float(den), 3)
        except Exception:
            pass
    return out


def _v207_pm_material_columns(self):
    cols = list(getattr(self, "MATERIAL_COLUMNS", []))
    if not cols:
        cols = ["step", "material", "class", "MW", "planned_mmol", "planned_g", "planned_mL", "use_count", "repeat", "phase", "note", "source"]
    if "MW" not in cols:
        try:
            cols.insert(cols.index("class") + 1, "MW")
        except Exception:
            cols.insert(3, "MW")
    if "density_g_per_mL" not in cols:
        try:
            cols.insert(cols.index("MW") + 1, "density_g_per_mL")
        except Exception:
            cols.insert(4, "density_g_per_mL")
    # Remove duplicate column names while preserving order.
    seen = set(); cleaned = []
    for c in cols:
        if c not in seen:
            cleaned.append(c); seen.add(c)
    return cleaned


def _v207_rebuild_material_tree_columns(self):
    tree = getattr(self, "pm_selected_material_tree", None)
    if tree is None:
        return
    cols = _v207_pm_material_columns(self)
    try:
        tree.configure(columns=cols)
        for c in cols:
            tree.heading(c, text=c)
            width = 125
            if c in {"material", "note", "source", "phase"}:
                width = 190
            elif c in {"MW", "density_g_per_mL", "planned_g", "planned_mL", "planned_mmol"}:
                width = 110
            tree.column(c, width=width, minwidth=70, anchor="w", stretch=True)
    except Exception:
        pass


def _v207_update_material_override_from_tree(self, tree, row_id, col_name, new_value):
    if col_name not in {"MW", "density_g_per_mL", "Density", "density"}:
        return
    try:
        cols = list(tree["columns"])
        vals = list(tree.item(row_id, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals))
        material = str(row.get("material", row.get("Item", "")) or "").strip()
        if not material:
            return
        # validate numeric; blank removes override for that field
        overrides = _v207_get_material_overrides(self)
        key = _v207_normal_key(material)
        overrides.setdefault(key, {})
        field = "MW" if col_name == "MW" else "density_g_per_mL"
        txt = str(new_value).strip()
        if txt == "":
            overrides[key].pop(field, None)
        else:
            overrides[key][field] = float(txt)
        # Also bind one-letter amino-acid aliases when applicable.
        try:
            aa = self._v28_extract_aa_from_unit(material) if hasattr(self, "_v28_extract_aa_from_unit") else None
            if aa:
                overrides.setdefault(_v207_normal_key(aa), {})[field] = float(txt) if txt != "" else ""
        except Exception:
            pass
        if hasattr(self, "schedule_autosave"):
            self.schedule_autosave()
    except Exception as e:
        try:
            messagebox.showwarning("MW/density edit", f"Invalid MW/density value:\n{e}")
        except Exception:
            pass


try:
    _v207_old_selected_result_edit = SPPSGui._v28_on_selected_result_edit
except Exception:
    _v207_old_selected_result_edit = None


def _v207_on_selected_result_edit(self, tree, row_id, col_name, new_value):
    _v207_update_material_override_from_tree(self, tree, row_id, col_name, new_value)
    if _v207_old_selected_result_edit:
        try:
            _v207_old_selected_result_edit(self, tree, row_id, col_name, new_value)
        except Exception:
            pass
    try:
        # Recalculate current selected peptide so MW/density changes affect g/mL values.
        self.pm_generate_selected()
    except Exception:
        try:
            self.refresh_batch_workspace_preview()
        except Exception:
            pass


try:
    _v207_old_pm_generate = SPPSGui.pm_generate_selected
except Exception:
    _v207_old_pm_generate = None


def _v207_pm_generate_selected(self):
    if _v207_old_pm_generate:
        res = _v207_old_pm_generate(self)
    else:
        res = None
    try:
        _v207_rebuild_material_tree_columns(self)
        df = self.pm_tree_to_df(self.live_usage_tree) if hasattr(self, "pm_tree_to_df") and hasattr(self, "live_usage_tree") else pd.DataFrame()
        df = _v207_enrich_material_df(self, df)
        cols = _v207_pm_material_columns(self)
        for c in cols:
            if c not in df.columns:
                df[c] = ""
        self._write_tree(self.pm_selected_material_tree, df[cols], cols)
        _v28_make_tree_editable(self, self.pm_selected_material_tree, self._v28_on_selected_result_edit)
    except Exception:
        pass
    return res


def _v207_hide_tabs_recursive(widget, depth=0):
    try:
        if isinstance(widget, ttk.Notebook):
            for tab_id in list(widget.tabs()):
                try:
                    txt = widget.tab(tab_id, "text")
                    # Clean UI rule: remove only redundant Plan tab and non-working utility tabs.
                    # Keep Materials and Checklist because they are required bench-facing outputs.
                    if txt in {"Plan", "Project", "Log"}:
                        widget.forget(tab_id)
                    # Inside Project Manager, keep Selected Materials and Selected Checklist.
                    # Only Batch summary/total duplicate views are hidden here; full Batch Manager remains top-level.
                    elif txt in {"Batch Total Materials", "Batch Summary"}:
                        widget.forget(tab_id)
                except Exception:
                    pass
    except Exception:
        pass
    try:
        for child in widget.winfo_children():
            _v207_hide_tabs_recursive(child, depth + 1)
    except Exception:
        pass


