def _v208_ensure_loading_vars(self):
    try:
        if not hasattr(self, 'apply_loading_calc'):
            self.apply_loading_calc = tk.BooleanVar(value=False)
        if not hasattr(self, 'loading_aa_eq'):
            self.loading_aa_eq = tk.StringVar(value='2')
        if not hasattr(self, 'loading_diea_eq'):
            self.loading_diea_eq = tk.StringVar(value='4')
    except Exception:
        pass


def _v208_is_loading_resin(self, resin_value=None):
    try:
        val = resin_value if resin_value is not None else self.pm_resin.get()
        return _v203_is_trityl_resin(val)
    except Exception:
        try:
            return 'ctc' in str(resin_value or '').lower() or 'trityl' in str(resin_value or '').lower()
        except Exception:
            return False


def _v208_loading_applies(self, resin_value=None):
    try:
        _v208_ensure_loading_vars(self)
        return bool(self.apply_loading_calc.get()) and _v208_is_loading_resin(self, resin_value)
    except Exception:
        return False


def _v208_hide_main_loading_editor(self):
    """Hide the main-editor Loading label/entry. The values stay in pm_loading and are edited in setup."""
    try:
        # Locate widgets in selected peptide editor grid by their label text.
        for child in self.winfo_children():
            pass
        if not hasattr(self, 'pm_resin'):
            return
        # Walk all descendants and hide the label 'Loading' and the Entry bound to pm_loading in the editor area.
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget('text')).strip() == 'Loading':
                        c.grid_remove()
                    # A normal Entry whose textvariable is pm_loading should be hidden in main editor only.
                    if isinstance(c, ttk.Entry) and str(c.cget('textvariable')) == str(self.pm_loading):
                        # Do not hide if this entry is inside setup panel; setup panel path contains Setup defaults/Notebook descendants.
                        parent_chain = []
                        p = c.master
                        while p is not None:
                            parent_chain.append(str(p))
                            p = getattr(p, 'master', None)
                            if p is self: break
                        if not any('pm_setup_panel' in x for x in parent_chain):
                            try: c.grid_remove()
                            except Exception: pass
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass


