def _v209_enrich_selected_plan_df(self, df):
    if df is None:
        return pd.DataFrame()
    out = df.copy()
    if "MW" not in out.columns:
        insert_at = 2 if "Unit name" in out.columns else min(3, len(out.columns))
        out.insert(insert_at, "MW", "")
    if "density_g_per_mL" not in out.columns:
        insert_at = list(out.columns).index("MW") + 1 if "MW" in out.columns else min(4, len(out.columns))
        out.insert(insert_at, "density_g_per_mL", "")
    for i, row in out.iterrows():
        item = _v209_material_key_from_plan_row(row)
        try:
            mw = _v207_mw_for_token(self, item) if "_v207_mw_for_token" in globals() else self._mw_for_token(item)
            if mw:
                out.at[i, "MW"] = _v201_round2(float(mw)) if "_v201_round2" in globals() else round(float(mw), 2)
        except Exception:
            pass
        try:
            den = _v207_density_for_token(self, item) if "_v207_density_for_token" in globals() else self._density_for_token(item)
            if den:
                out.at[i, "density_g_per_mL"] = _v201_round2(float(den)) if "_v201_round2" in globals() else round(float(den), 2)
        except Exception:
            pass
    return out


def _v209_plan_columns_from_df(df):
    preferred = ["No", "Unit name", "MW", "density_g_per_mL", "Unit eq", "Unit amount(g)", "Coupling reagent 1", "Coupling cocktail solvent"]
    cols = [c for c in preferred if c in list(df.columns)]
    # Keep remaining useful columns but skip ambiguous solvent duplication in selected plan.
    for c in list(df.columns):
        if c in cols or c in {"Solvent 1", "Solvent 1 count", "Solvent 2", "Solvent 2 count"}:
            continue
        cols.append(c)
    return cols


def _v209_refresh_selected_plan_with_mw_density(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    try:
        df = self.pm_tree_to_df(getattr(self, "tree", None)) if hasattr(self, "pm_tree_to_df") else pd.DataFrame()
    except Exception:
        df = pd.DataFrame()
    if df is None or df.empty:
        try:
            df = _v28_dataframe_from_tree(tree) if "_v28_dataframe_from_tree" in globals() else pd.DataFrame()
        except Exception:
            df = pd.DataFrame()
    df = _v209_enrich_selected_plan_df(self, df)
    cols = _v209_plan_columns_from_df(df)
    if not cols:
        cols = ["No", "Unit name", "MW", "density_g_per_mL", "Unit eq", "Unit amount(g)"]
        df = pd.DataFrame(columns=cols)
    try:
        self._write_tree(tree, df[cols], cols)
        for c in cols:
            width = 110
            if c in {"Unit name", "Coupling reagent 1", "Coupling cocktail solvent", "note", "source"}:
                width = 190
            elif c in {"MW", "density_g_per_mL"}:
                width = 120
            tree.column(c, width=width, minwidth=70, stretch=True)
        _v28_make_tree_editable(self, tree, self._v28_on_selected_result_edit)
    except Exception:
        pass


def _v209_commit_mw_density_override_from_any_tree(self, tree, row_id, col_name, new_value):
    if col_name not in {"MW", "density_g_per_mL", "Density", "density"}:
        return False
    try:
        cols = list(tree["columns"])
        vals = list(tree.item(row_id, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals))
        item = _v209_material_key_from_plan_row(row)
        if not item:
            return False
        overrides = _v207_get_material_overrides(self) if "_v207_get_material_overrides" in globals() else getattr(self, "material_overrides", {})
        if not hasattr(self, "material_overrides"):
            self.material_overrides = overrides
        key = _v207_normal_key(item) if "_v207_normal_key" in globals() else item.lower().strip()
        field = "MW" if col_name == "MW" else "density_g_per_mL"
        txt = str(new_value).strip()
        overrides.setdefault(key, {})
        if txt:
            overrides[key][field] = float(txt)
        else:
            overrides[key].pop(field, None)
        # If the row is an Fmoc-AA display, also map the one-letter AA key.
        try:
            aa = self._v28_extract_aa_from_unit(item) if hasattr(self, "_v28_extract_aa_from_unit") else None
            if aa:
                akey = _v207_normal_key(aa) if "_v207_normal_key" in globals() else str(aa).lower()
                overrides.setdefault(akey, {})
                if txt:
                    overrides[akey][field] = float(txt)
                else:
                    overrides[akey].pop(field, None)
        except Exception:
            pass
        if hasattr(self, "schedule_autosave"):
            self.schedule_autosave()
        return True
    except Exception as e:
        try:
            messagebox.showwarning("MW/density edit", f"Invalid MW/density value:\n{e}")
        except Exception:
            pass
        return False

try:
    _v209_old_selected_edit = SPPSGui._v28_on_selected_result_edit
except Exception:
    _v209_old_selected_edit = None

def _v209_on_selected_result_edit(self, tree, row_id, col_name, new_value):
    handled = _v209_commit_mw_density_override_from_any_tree(self, tree, row_id, col_name, new_value)
    if _v209_old_selected_edit:
        try:
            _v209_old_selected_edit(self, tree, row_id, col_name, new_value)
        except Exception:
            pass
    if handled:
        try:
            _v209_refresh_selected_plan_with_mw_density(self)
        except Exception:
            pass
        try:
            _v207_rebuild_material_tree_columns(self)
        except Exception:
            pass
        try:
            self.refresh_batch_workspace_preview()
        except Exception:
            pass

