def _v209_build(self):
    if _v209_old_build:
        _v209_old_build(self)
    try:
        self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
        for child in self.winfo_children():
            for sub in child.winfo_children():
                try:
                    if isinstance(sub, ttk.Label) and str(sub.cget('text')).startswith('SPPS Planner'):
                        sub.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
                except Exception:
                    pass
    except Exception:
        pass
    try:
        # Top-level cleanup for speed and clarity.  Selected Materials/Checklist remain inside Workbench.
        tabs = getattr(self, 'tabs', None)
        if tabs is not None:
            for tid in list(tabs.tabs()):
                try:
                    txt = tabs.tab(tid, 'text')
                    if txt in {'Plan','Materials','Checklist','Project','Log'}:
                        tabs.forget(tid)
                    elif txt == 'Project Manager':
                        tabs.tab(tid, text='Workbench')
                except Exception:
                    pass
    except Exception:
        pass
    try:
        if hasattr(self, 'pm_resin') and self.pm_resin.get() not in SPPSGui.RESIN_VALUES:
            self.pm_resin.set(_v209_normalize_resin_name(self.pm_resin.get()))
    except Exception:
        pass
    try:
        _v209_refresh_selected_plan_with_mw_density(self)
    except Exception:
        pass

