# ======================= V2.0.10 PATCH: TRUE SELECTED PLAN MW/DENSITY + CHECKLIST TRANSFER + LAG FIX =======================
# User correction:
# - MW/density must be visible/editable in Selected Plan itself, not only Selected Materials.
# - The old top Checklist function is moved into Selected Checklist; top tabs stay hidden.
# - 2-CTC(합성기) is handled like Amide/preloaded resin, not like a direct-loading CTC resin.
# - Reduce lag by avoiding heavy batch refresh/autosave on every keystroke.
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'
APP_VERSION = 'V2.1.7'
try:
    SPPSGui.RESIN_VALUES = [
        "Amide", "Rink Amide", "Rink Amide AM", "Rink Amide MBHA",
        "Rink Amide ChemMatrix", "Rink Amide Tentagel", "Wang", "HMPB",
        "Sieber Amide", "PAL resin", "CTC/Trityl (2-CTC)", "2-CTC(합성기)",
        "Tentagel", "Manual"
    ]
except Exception:
    pass


def _v2010_is_synthesizer_ctc(name: str) -> bool:
    s = str(name or "").lower().replace(" ", "")
    return ("2-ctc" in s and "합성기" in s) or ("synthesizer" in s and "ctc" in s)


def _v2010_is_direct_loading_resin(name: str) -> bool:
    s = str(name or "").lower()
    if _v2010_is_synthesizer_ctc(s):
        return False
    keys = ["ctc", "trityl", "chlorotrityl", "wang", "hmpb", "sieber", "pal"]
    return any(k in s for k in keys)


def _v2010_loading_applies(self, resin=None) -> bool:
    try:
        if hasattr(self, "apply_loading_calc") and not bool(self.apply_loading_calc.get()):
            return False
    except Exception:
        return False
    try:
        r = resin if resin is not None else getattr(self, "pm_resin", _v225_const_var("")).get()
    except Exception:
        r = resin
    return _v2010_is_direct_loading_resin(r)


def _v2010_resin_family_text(self) -> str:
    try:
        r = self.resin.get()
    except Exception:
        try:
            r = self.pm_resin.get()
        except Exception:
            r = ""
    if _v2010_is_synthesizer_ctc(r):
        return "Amide"
    if _v2010_is_direct_loading_resin(r):
        # only direct-loading families are CTC/Trityl-like for swell/loading logic
        return "CTC/Trityl"
    return "Amide"


def _v2010_normalize_resin_name(name: str) -> str:
    s = str(name or "").strip()
    if _v2010_is_synthesizer_ctc(s):
        return "2-CTC(합성기)"
    low = s.lower()
    if ("ctc" in low) or ("trityl" in low) or ("2-chloro" in low):
        return "CTC/Trityl (2-CTC)"
    return s or "Rink Amide AM"

# Replace older global helpers used inside patch-level calculations.
try:
    _v208_loading_applies = _v2010_loading_applies
    _v209_loading_applies = _v2010_loading_applies
    _v203_normalize_resin_name = _v2010_normalize_resin_name
    _v28_normalize_resin_name = _v2010_normalize_resin_name
except Exception:
    pass


def _v2010_plan_material_key(row: dict) -> str:
    return str(row.get("Unit name") or row.get("material") or row.get("Item") or "").strip()


def _v2010_enrich_selected_plan_df(self, df):
    if df is None:
        return pd.DataFrame()
    out = df.copy()
    if "MW" not in out.columns:
        pos = list(out.columns).index("Unit name") + 1 if "Unit name" in out.columns else min(2, len(out.columns))
        out.insert(pos, "MW", "")
    if "density_g_per_mL" not in out.columns:
        pos = list(out.columns).index("MW") + 1
        out.insert(pos, "density_g_per_mL", "")
    for i, row in out.iterrows():
        item = _v2010_plan_material_key(row)
        try:
            mw = self._mw_for_token(item)
            if mw:
                out.at[i, "MW"] = round(float(mw), 2)
        except Exception:
            pass
        try:
            den = self._density_for_token(item) if hasattr(self, "_density_for_token") else self._density_for(item)
            if den:
                out.at[i, "density_g_per_mL"] = round(float(den), 3)
        except Exception:
            pass
    return out


def _v2010_selected_plan_columns(df):
    # Keep the selected plan compact but include MW/density where the user needs them.
    preferred = [
        "No", "Unit name", "MW", "density_g_per_mL", "Unit eq", "Unit amount(g)", "Unit volume(mL)",
        "Coupling reagent 1", "Coupling reagent 2 / catalyst", "Coupling base",
        "Coupling cocktail solvent", "Coupling cocktail volume(mL)", "Repeat", "Note"
    ]
    cols = [c for c in preferred if c in list(df.columns)]
    # Do not re-add redundant wash solvent columns in Selected Plan; Checklist carries operations.
    skip = {"Solvent 1", "Solvent 1 count", "Solvent 2", "Solvent 2 count"}
    for c in list(df.columns):
        if c not in cols and c not in skip:
            cols.append(c)
    return cols


def _v2010_refresh_selected_plan(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    try:
        df = self.pm_tree_to_df(self.tree)
    except Exception:
        df = pd.DataFrame()
    df = _v2010_enrich_selected_plan_df(self, df)
    cols = _v2010_selected_plan_columns(df) if not df.empty else ["No", "Unit name", "MW", "density_g_per_mL", "Unit eq", "Unit amount(g)"]
    for c in cols:
        if c not in df.columns:
            df[c] = ""
    try:
        self._write_tree(tree, df[cols], cols)
        # Fixed, compact widths reduce horizontal redraw lag in non-fullscreen windows.
        widths = {
            "No": 48, "Unit name": 210, "MW": 82, "density_g_per_mL": 115,
            "Unit eq": 80, "Unit amount(g)": 115, "Unit volume(mL)": 115,
            "Coupling reagent 1": 125, "Coupling reagent 2 / catalyst": 145,
            "Coupling base": 120, "Coupling cocktail solvent": 145,
            "Coupling cocktail volume(mL)": 150, "Repeat": 70, "Note": 220,
        }
        for c in cols:
            tree.column(c, width=widths.get(c, 110), minwidth=55, stretch=False, anchor="w")
        _v28_make_tree_editable(self, tree, self._v28_on_selected_result_edit)
    except Exception:
        pass


def _v2010_update_selected_checklist_from_top_function(self):
    txt = getattr(self, "pm_selected_check_text", None)
    if txt is None:
        return
    try:
        txt.delete("1.0", "end")
        # Use the old top Checklist content when available; this is the requested feature transfer.
        if hasattr(self, "check_text"):
            content = self.check_text.get("1.0", "end")
        else:
            content = ""
        if not str(content).strip() and hasattr(self, "short_step_text"):
            content = self.short_step_text.get("1.0", "end")
        txt.insert("end", content)
    except Exception:
        pass


def _v2010_commit_mw_density(self, tree, row_id, col_name, new_value):
    if col_name not in {"MW", "density_g_per_mL", "Density", "density"}:
        return False
    try:
        cols = list(tree["columns"])
        vals = list(tree.item(row_id, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals))
        item = _v2010_plan_material_key(row)
        if not item:
            return False
        if not hasattr(self, "material_overrides") or self.material_overrides is None:
            self.material_overrides = {}
        key = str(item).strip().lower()
        field = "MW" if col_name == "MW" else "density_g_per_mL"
        txt = str(new_value).strip()
        self.material_overrides.setdefault(key, {})
        if txt:
            self.material_overrides[key][field] = float(txt)
        else:
            self.material_overrides[key].pop(field, None)
        try:
            aa = self._v28_extract_aa_from_unit(item) if hasattr(self, "_v28_extract_aa_from_unit") else None
            if aa:
                akey = str(aa).strip().lower()
                self.material_overrides.setdefault(akey, {})
                if txt:
                    self.material_overrides[akey][field] = float(txt)
                else:
                    self.material_overrides[akey].pop(field, None)
        except Exception:
            pass
        return True
    except Exception as e:
        try:
            messagebox.showwarning("MW/density edit", f"Invalid MW/density value:\n{e}")
        except Exception:
            pass
        return False

