def _v2010_pm_live_sync_selected(self):
    """Lightweight editor sync. Avoid full Batch rebuild/autosave per keystroke to remove lag."""
    if getattr(self, "_pm_loading_editor", False):
        return
    idx = self.pm_current_index() if hasattr(self, "pm_list") else None
    if idx is None or idx < 0 or idx >= len(getattr(self, "pm_items", [])):
        return
    try:
        self.pm_items[idx].update({
            "project": self.pm_project.get().strip(),
            "peptide": self.pm_peptide.get().strip(),
            "sequence": self.pm_sequence.get().strip(),
            "scale": self.pm_scale.get().strip(),
            "resin": self.pm_resin.get().strip(),
            "loading": self.pm_loading.get().strip(),
            "lot": self.pm_lot.get().strip(),
            "chemistry": self.pm_chemistry.get().strip(),
            "copies": self.pm_copies.get().strip(),
            "status": self.pm_items[idx].get("status", "Ready"),
        })
        # Refresh only the visible list label. No batch/material rebuild here.
        try:
            cur = self.pm_list.curselection()
            label = f"{self.pm_items[idx].get('project','')} | {self.pm_items[idx].get('peptide','')}"
            self.pm_list.delete(idx)
            self.pm_list.insert(idx, label)
            self.pm_list.selection_set(idx)
            self.pm_list.activate(idx)
        except Exception:
            pass
        if hasattr(self, "pm_update_summary"):
            try:
                self.pm_update_summary()
            except Exception:
                pass
        # Debounced autosave only; no immediate disk/write or batch refresh.
        if hasattr(self, "schedule_autosave"):
            try:
                self.schedule_autosave()
            except Exception:
                pass
    except Exception:
        pass

