def _v2010_hide_top_tabs(self):
    """Keep one Workbench page internally but hide its top tab row."""
    try:
        tabs = getattr(self, "tabs", None)
        if tabs is not None:
            for tid in list(tabs.tabs()):
                try:
                    txt = tabs.tab(tid, "text")
                    if txt in {"Plan", "Materials", "Checklist", "Project", "Log", "Batch Manager"}:
                        tabs.forget(tid)
                    elif txt in {"Project Manager", "Workbench"}:
                        tabs.tab(tid, text="")
                except Exception:
                    pass
            try:
                style = ttk.Style(self)
                style.layout("V2010Hidden.TNotebook.Tab", [])
                tabs.configure(style="V2010Hidden.TNotebook")
            except Exception:
                pass
    except Exception:
        pass


