# ======================= V2.0.11 PATCH: VERIFIED PRELOADED + SELECTED CHECKLIST + BATCH TAB =======================
# User requirements fixed here:
# 1) 2-CTC(합성기) is a preloaded synthesizer use-case: first amino acid is already attached,
#    so it is handled like Amide/preloaded resin, never as a direct-loading CTC resin.
# 2) Only direct-loading resins use the Loading rate tab, and only when the checkbox is enabled.
# 3) Selected Plan must show MW and Density(g/mL) up front and both must be editable.
# 4) The old top Checklist working controls are moved into Selected Checklist; Batch Manager remains top-level.
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'
APP_VERSION = 'V2.1.7'

try:
    SPPSGui.RESIN_VALUES = [
        "Amide", "Rink Amide", "Rink Amide AM", "Rink Amide MBHA",
        "Rink Amide ChemMatrix", "Rink Amide Tentagel", "2-CTC(합성기)",
        "CTC/Trityl (2-CTC)", "Wang", "HMPB", "Sieber Amide", "PAL resin",
        "Tentagel", "Manual"
    ]
except Exception:
    pass


def _v211_is_synthesizer_ctc(name: str) -> bool:
    s = str(name or "").lower().replace(" ", "")
    return ("2-ctc" in s and "합성기" in s) or ("synthesizer" in s and "ctc" in s)


def _v211_is_direct_loading_resin(name: str) -> bool:
    s = str(name or "").lower()
    if _v211_is_synthesizer_ctc(s):
        return False
    # These are treated as direct-loading resin families only when the Loading-rate checkbox is ON.
    return any(k in s for k in ["ctc", "trityl", "chlorotrityl", "wang", "hmpb", "sieber", "pal"])


def _v211_loading_applies(self, resin_value=None) -> bool:
    try:
        if hasattr(self, "apply_loading_calc") and not bool(self.apply_loading_calc.get()):
            return False
    except Exception:
        return False
    try:
        resin = resin_value if resin_value is not None else getattr(self, "pm_resin", _v225_const_var("")).get()
    except Exception:
        resin = resin_value
    return _v211_is_direct_loading_resin(resin)


def _v211_resin_family_text(self) -> str:
    try:
        resin = self.resin.get()
    except Exception:
        try:
            resin = self.pm_resin.get()
        except Exception:
            resin = ""
    if _v211_is_synthesizer_ctc(resin):
        return "Amide"
    if _v211_is_direct_loading_resin(resin):
        return "CTC/Trityl"
    return "Amide"


def _v211_normalize_resin_name(name: str) -> str:
    s = str(name or "").strip()
    if _v211_is_synthesizer_ctc(s):
        return "2-CTC(합성기)"
    low = s.lower()
    if ("ctc" in low) or ("trityl" in low) or ("2-chloro" in low):
        return "CTC/Trityl (2-CTC)"
    return s or "Rink Amide AM"

# Override all patch-generation helpers that are used by batch and project calculations.
try:
    _v208_loading_applies = _v211_loading_applies
    _v209_loading_applies = _v211_loading_applies
    _v2010_loading_applies = _v211_loading_applies
    _v203_normalize_resin_name = _v211_normalize_resin_name
    _v28_normalize_resin_name = _v211_normalize_resin_name
except Exception:
    pass


def _v211_density_display_col() -> str:
    return "Density(g/mL)"


def _v211_internal_density_col(col_name: str) -> str:
    return "density_g_per_mL" if str(col_name) in {"Density(g/mL)", "Density", "density"} else str(col_name)


def _v211_plan_material_key(row: dict) -> str:
    return str(row.get("Unit name") or row.get("material") or row.get("Item") or row.get("AA") or "").strip()


def _v211_enrich_selected_plan_df(self, df):
    if df is None:
        df = pd.DataFrame()
    out = df.copy()
    # Normalize older internal density heading to the requested display heading.
    if "density_g_per_mL" in out.columns and "Density(g/mL)" not in out.columns:
        out = out.rename(columns={"density_g_per_mL": "Density(g/mL)"})
    if "MW" not in out.columns:
        pos = list(out.columns).index("Unit name") + 1 if "Unit name" in out.columns else min(2, len(out.columns))
        out.insert(pos, "MW", "")
    if "Density(g/mL)" not in out.columns:
        pos = list(out.columns).index("MW") + 1 if "MW" in out.columns else min(3, len(out.columns))
        out.insert(pos, "Density(g/mL)", "")
    for i, row in out.iterrows():
        item = _v211_plan_material_key(row)
        try:
            mw = self._mw_for_token(item) if hasattr(self, "_mw_for_token") else 0.0
            if mw:
                out.at[i, "MW"] = round(float(mw), 2)
        except Exception:
            pass
        try:
            if hasattr(self, "_density_for_token"):
                den = self._density_for_token(item)
            elif hasattr(self, "_density_for"):
                den = self._density_for(item)
            else:
                den = 0.0
            if den:
                out.at[i, "Density(g/mL)"] = round(float(den), 3)
        except Exception:
            pass
    return out


def _v211_selected_plan_columns(df):
    preferred = [
        "No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)", "Unit volume(mL)",
        "Coupling reagent 1", "Coupling reagent 2 / catalyst", "Coupling base",
        "Coupling cocktail solvent", "Coupling cocktail volume(mL)", "Repeat", "Note"
    ]
    cols = [c for c in preferred if c in list(df.columns)]
    skip = {"density_g_per_mL", "Solvent 1", "Solvent 1 count", "Solvent 2", "Solvent 2 count"}
    for c in list(df.columns):
        if c not in cols and c not in skip:
            cols.append(c)
    return cols


def _v211_refresh_selected_plan(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    try:
        df = self.pm_tree_to_df(self.tree)
    except Exception:
        try:
            df = _v28_dataframe_from_tree(tree)
        except Exception:
            df = pd.DataFrame()
    df = _v211_enrich_selected_plan_df(self, df)
    cols = _v211_selected_plan_columns(df) if not df.empty else ["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)"]
    for c in cols:
        if c not in df.columns:
            df[c] = ""
    try:
        self._write_tree(tree, df[cols], cols)
        widths = {
            "No": 48, "Unit name": 210, "MW": 90, "Density(g/mL)": 120,
            "Unit eq": 80, "Unit amount(g)": 120, "Unit volume(mL)": 120,
            "Coupling reagent 1": 130, "Coupling reagent 2 / catalyst": 160,
            "Coupling base": 120, "Coupling cocktail solvent": 150,
            "Coupling cocktail volume(mL)": 160, "Repeat": 70, "Note": 220,
        }
        for c in cols:
            tree.heading(c, text=c)
            tree.column(c, width=widths.get(c, 110), minwidth=55, stretch=False, anchor="w")
        _v28_make_tree_editable(self, tree, self._v28_on_selected_result_edit)
    except Exception:
        pass


def _v211_commit_mw_density(self, tree, row_id, col_name, new_value):
    if col_name not in {"MW", "Density(g/mL)", "density_g_per_mL", "Density", "density"}:
        return False
    try:
        cols = list(tree["columns"])
        vals = list(tree.item(row_id, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals))
        item = _v211_plan_material_key(row)
        if not item:
            return False
        if not hasattr(self, "material_overrides") or self.material_overrides is None:
            self.material_overrides = {}
        key = str(item).strip().lower()
        field = "MW" if col_name == "MW" else "density_g_per_mL"
        txt = str(new_value).strip()
        self.material_overrides.setdefault(key, {})
        if txt:
            self.material_overrides[key][field] = float(txt)
        else:
            self.material_overrides[key].pop(field, None)
        # Also map Fmoc-AA display names to one-letter AA override where possible.
        try:
            aa = self._v28_extract_aa_from_unit(item) if hasattr(self, "_v28_extract_aa_from_unit") else None
            if aa:
                akey = str(aa).strip().lower()
                self.material_overrides.setdefault(akey, {})
                if txt:
                    self.material_overrides[akey][field] = float(txt)
                else:
                    self.material_overrides[akey].pop(field, None)
        except Exception:
            pass
        if hasattr(self, "schedule_autosave"):
            self.schedule_autosave()
        return True
    except Exception as e:
        try:
            messagebox.showwarning("MW/Density edit", f"Invalid MW/Density value:\n{e}")
        except Exception:
            pass
        return False

