def _v212_var_bool(obj, attr, default=False):
    try:
        v = getattr(obj, attr)
        if hasattr(v, 'get'):
            return bool(v.get())
        return bool(v)
    except Exception:
        return bool(default)


def _v212_loading_applies(self, resin_value=None) -> bool:
    try:
        resin = resin_value if resin_value is not None else getattr(self, "pm_resin").get()
    except Exception:
        resin = resin_value
    if _v212_is_synthesizer_ctc(resin):
        return False
    checked = _v212_var_bool(self, "apply_loading_calc", False)
    return checked and _v212_is_direct_loading_resin(resin)


