def _v213_norm_resin_text(name):
    return str(name or "").strip().lower().replace(" ", "")

def _v213_is_preloaded_ctc(name) -> bool:
    s = _v213_norm_resin_text(name)
    return (("ctc" in s or "2-ctc" in s) and ("합성용" in s or "합성기" in s or "synthesizer" in s or "preloaded" in s))

def _v213_is_plain_2ctc(name) -> bool:
    s = _v213_norm_resin_text(name)
    return "2-ctc" in s and not _v213_is_preloaded_ctc(s)

def _v213_is_direct_loading_resin(name) -> bool:
    s = str(name or "").lower()
    if _v213_is_preloaded_ctc(s):
        return False
    return any(k in s for k in ["2-ctc", "ctc", "trityl", "chlorotrityl", "wang", "hmpb", "sieber", "pal"])

def _v213_loading_applies(self, resin_value=None) -> bool:
    try:
        resin = resin_value if resin_value is not None else getattr(self, "pm_resin").get()
    except Exception:
        resin = resin_value
    if _v213_is_preloaded_ctc(resin):
        return False
    try:
        checked = bool(getattr(self, "apply_loading_calc").get())
    except Exception:
        checked = False
    return checked and _v213_is_direct_loading_resin(resin)

def _v213_normalize_resin_name(name: str) -> str:
    raw = str(name or "").strip()
    if _v213_is_preloaded_ctc(raw):
        return "CTC(합성용)"
    if _v213_is_plain_2ctc(raw):
        return "2-CTC"
    low = raw.lower()
    if ("ctc" in low) or ("trityl" in low) or ("2-chloro" in low):
        return "CTC/Trityl"
    return raw or "Rink Amide AM"

def _v213_resin_family_text(self) -> str:
    try:
        resin = self.resin.get()
    except Exception:
        try:
            resin = self.pm_resin.get()
        except Exception:
            resin = ""
    if _v213_is_preloaded_ctc(resin):
        return "Amide"
    if _v213_loading_applies(self, resin):
        return "CTC/Trityl"
    return "Amide"

def _v213_ensure_resin_values(self):
    try:
        self.RESIN_VALUES = list(_V213_RESIN_VALUES)
        SPPSGui.RESIN_VALUES = list(_V213_RESIN_VALUES)
    except Exception:
        pass
    try:
        cur = self.pm_resin.get()
        if _v213_is_preloaded_ctc(cur) and cur != "CTC(합성용)":
            self.pm_resin.set("CTC(합성용)")
    except Exception:
        pass
    try:
        def walk(widget):
            for c in widget.winfo_children():
                try:
                    if isinstance(c, ttk.Combobox) and str(c.cget("textvariable")) in {str(getattr(self, "pm_resin", "")), str(getattr(self, "resin", ""))}:
                        c.configure(values=_V213_RESIN_VALUES)
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v213_extract_aa_from_unit_name(item: str) -> str:
    s = str(item or "")
    # Common protected Fmoc names.
    import re
    m = re.search(r"Fmoc-([A-Za-z]{3})", s)
    if m:
        tri = m.group(1).lower()
        tri_map = {
            "ala":"A", "arg":"R", "asn":"N", "asp":"D", "cys":"C", "gln":"Q", "glu":"E", "gly":"G", "his":"H", "ile":"I",
            "leu":"L", "lys":"K", "met":"M", "phe":"F", "pro":"P", "ser":"S", "thr":"T", "trp":"W", "tyr":"Y", "val":"V",
        }
        if tri in tri_map:
            return tri_map[tri]
    m = re.search(r"\b([ACDEFGHIKLMNPQRSTVWY])\b", s)
    return m.group(1) if m else ""

def _v213_display_mw(self, item):
    item = str(item or "").strip()
    if not item:
        return ""
    key_norm = item.strip().lower()
    try:
        o = (getattr(self, "material_overrides", {}) or {}).get(key_norm, {})
        if str(o.get("MW", "")).strip() != "":
            return round(float(o["MW"]), 2)
    except Exception:
        pass
    aa = _v213_extract_aa_from_unit_name(item)
    if aa in _V213_FMOC_MW:
        return _V213_FMOC_MW[aa]
    for name, mw in _V213_NAME_MW.items():
        if name.lower() == item.lower() or name.lower() in item.lower():
            return round(float(mw), 2)
    try:
        mw = self._mw_for_token(item)
        if mw:
            return round(float(mw), 2)
    except Exception:
        pass
    try:
        if aa:
            mw = self._mw_for_token(aa)
            if mw:
                return round(float(mw), 2)
    except Exception:
        pass
    return ""

def _v213_display_density(self, item):
    item = str(item or "").strip()
    if not item:
        return ""
    key_norm = item.strip().lower()
    try:
        o = (getattr(self, "material_overrides", {}) or {}).get(key_norm, {})
        if str(o.get("density_g_per_mL", "")).strip() != "":
            return round(float(o["density_g_per_mL"]), 3)
    except Exception:
        pass
    for name, den in _V213_DENSITY.items():
        if name.lower() == item.lower() or name.lower() in item.lower():
            return round(float(den), 3)
    try:
        den = self._density_for_token(item)
        if den:
            return round(float(den), 3)
    except Exception:
        pass
    try:
        den = self._density_for(item) if hasattr(self, "_density_for") else 0
        if den:
            return round(float(den), 3)
    except Exception:
        pass
    return ""

def _v213_plan_key(row: dict) -> str:
    return str(row.get("Unit name") or row.get("material") or row.get("Item") or row.get("AA") or "").strip()

def _v213_is_loading_plan_row(row: dict) -> bool:
    text = " ".join(str(v).lower() for v in row.values())
    if any(k in text for k in ["first loading", "resin loading", "c-terminal loading", "trityl/2-ctc first loading", "first attachment"]):
        return True
    # Legacy symptom: first C-terminal AA appears with loading AA eq and DIEA but no coupling reagent.
    try:
        unit_eq = float(str(row.get("Unit eq", "")).strip() or "0")
    except Exception:
        unit_eq = 0.0
    reagent = str(row.get("Coupling reagent 1", "") or "").strip()
    base = str(row.get("Coupling base", "") or "").lower()
    if not reagent and "diea" in base and abs(unit_eq - 2.0) < 1e-6:
        return True
    return False

def _v213_base_plan_df(self):
    try:
        df = self.pm_tree_to_df(self.tree)
    except Exception:
        df = pd.DataFrame()
    if df is None:
        df = pd.DataFrame()
    return df

def _v213_enrich_selected_plan_df(self, df):
    out = pd.DataFrame() if df is None else df.copy()
    if out.empty:
        return pd.DataFrame(columns=["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)"])
    # Remove forbidden loading row when loading is not applicable, especially CTC(합성용).
    try:
        resin = getattr(self, "pm_resin").get()
    except Exception:
        resin = ""
    if not _v213_loading_applies(self, resin):
        keep = []
        for _, r in out.iterrows():
            keep.append(not _v213_is_loading_plan_row(dict(r)))
        out = out.loc[keep].copy()
        if "No" in out.columns:
            out["No"] = list(range(1, len(out) + 1))
    if "density_g_per_mL" in out.columns and "Density(g/mL)" not in out.columns:
        out = out.rename(columns={"density_g_per_mL": "Density(g/mL)"})
    if "MW" not in out.columns:
        pos = list(out.columns).index("Unit name") + 1 if "Unit name" in out.columns else min(2, len(out.columns))
        out.insert(pos, "MW", "")
    if "Density(g/mL)" not in out.columns:
        pos = list(out.columns).index("MW") + 1 if "MW" in out.columns else min(3, len(out.columns))
        out.insert(pos, "Density(g/mL)", "")
    for i, row in out.iterrows():
        item = _v213_plan_key(row)
        if not item:
            continue
        mw = _v213_display_mw(self, item)
        den = _v213_display_density(self, item)
        if mw != "":
            out.at[i, "MW"] = mw
        if den != "":
            out.at[i, "Density(g/mL)"] = den
    return out

def _v213_selected_plan_columns(df):
    preferred = [
        "No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)", "Unit volume(mL)",
        "Coupling reagent 1", "Coupling reagent 2", "Coupling reagent 2 / catalyst", "Coupling base",
        "Coupling cocktail solvent", "Coupling cocktail volume(mL)", "Repeat", "Note"
    ]
    cols = [c for c in preferred if c in list(df.columns)]
    skip = {"density_g_per_mL", "Solvent 1", "Solvent 1 count", "Solvent 2", "Solvent 2 count"}
    for c in list(df.columns):
        if c not in cols and c not in skip:
            cols.append(c)
    return cols

def _v213_refresh_selected_plan(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    df = _v213_enrich_selected_plan_df(self, _v213_base_plan_df(self))
    cols = _v213_selected_plan_columns(df)
    for c in cols:
        if c not in df.columns:
            df[c] = ""
    self._write_tree(tree, df[cols], cols)
    widths = {"No": 48, "Unit name": 230, "MW": 90, "Density(g/mL)": 125, "Unit eq": 80, "Unit amount(g)": 120, "Unit volume(mL)": 120, "Note": 240}
    try:
        for c in cols:
            tree.heading(c, text=c)
            tree.column(c, width=widths.get(c, 125), minwidth=55, stretch=False, anchor="w")
        _v28_make_tree_editable(self, tree, self._v28_on_selected_result_edit)
    except Exception:
        pass

def _v213_commit_plan_mw_density_rows(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return 0
    if not hasattr(self, "material_overrides") or self.material_overrides is None:
        self.material_overrides = {}
    cols = list(tree["columns"])
    n = 0
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals))
        item = _v213_plan_key(row)
        if not item:
            continue
        keys = {item.strip().lower()}
        aa = _v213_extract_aa_from_unit_name(item)
        if aa:
            keys.add(aa.lower())
        for src, field in [("MW", "MW"), ("Density(g/mL)", "density_g_per_mL")]:
            txt = str(row.get(src, "")).strip()
            if not txt:
                continue
            try:
                val = float(txt)
            except Exception:
                continue
            for key in keys:
                self.material_overrides.setdefault(key, {})[field] = val
            n += 1
    try:
        if hasattr(self, "schedule_autosave"):
            self.schedule_autosave()
    except Exception:
        pass
    return n

def _v213_apply_plan(self):
    count = _v213_commit_plan_mw_density_rows(self)
    try:
        _v213_refresh_selected_plan(self)
    except Exception:
        pass
    try:
        _v207_rebuild_material_tree_columns(self)
    except Exception:
        pass
    try:
        if hasattr(self, "refresh_batch_workspace_preview"):
            self.refresh_batch_workspace_preview()
    except Exception:
        pass
    try:
        messagebox.showinfo("Apply Plan", f"Applied MW / Density(g/mL) values. ({count} fields)")
    except Exception:
        pass

def _v213_add_apply_plan_button(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None or getattr(self, "_v213_apply_plan_button_added", False):
        return
    parent = tree.master
    try:
        for child in list(parent.winfo_children()):
            try:
                info = child.grid_info()
                if info and int(info.get("row", 0)) >= 0:
                    child.grid_configure(row=int(info.get("row", 0)) + 1)
            except Exception:
                pass
        parent.rowconfigure(1, weight=1)
        toolbar = ttk.Frame(parent, padding=(4, 3))
        toolbar.grid(row=0, column=0, columnspan=2, sticky="ew")
        ttk.Button(toolbar, text="Apply Plan", command=lambda: _v213_apply_plan(self)).pack(side="left", padx=3)
        ttk.Label(toolbar, text="Edit MW / Density(g/mL), then Apply Plan to sync Selected Materials and Batch Manager.").pack(side="left", padx=(8, 0))
        self._v213_apply_plan_button_added = True
    except Exception:
        pass

def _v213_selected_edit(self, tree, row_id, col_name, new_value):
    try:
        cols = list(tree["columns"])
        vals = list(tree.item(row_id, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        if col_name in {"MW", "Density(g/mL)", "density_g_per_mL", "Density", "density"}:
            vals[cols.index(col_name)] = new_value
            tree.item(row_id, values=vals)
            return
    except Exception:
        pass
    try:
        _v211_on_selected_result_edit(self, tree, row_id, col_name, new_value)
    except Exception:
        pass

def _v213_resin_loading_df(self, rows):
    cols = globals().get("V29_BATCH_COLUMNS", ["Category", "Item", "Solvent", "Count", "Eq", "Conc_M", "Calculated_mL", "Actual_mL", "MW", "Density", "Weight_g", "Volume_mL", "Note"])
    out = []
    if not _v213_loading_applies(self, getattr(self, "pm_resin", _v225_const_var("")).get() if hasattr(self, "pm_resin") else None):
        return pd.DataFrame(out, columns=cols)
    aa_eq = _v29_to_float(self, getattr(self, "loading_aa_eq", None), 2.0)
    diea_eq = _v29_to_float(self, getattr(self, "loading_diea_eq", None), 4.0)
    try:
        solvent = getattr(self, "default_loading_dissolve_solvent").get() or "90% DCM / 10% DMF"
    except Exception:
        solvent = "90% DCM / 10% DMF"
    for r in rows:
        raw_resin = r.get("Resin", "")
        if not _v213_loading_applies(self, raw_resin):
            continue
        resin = _v213_normalize_resin_name(raw_resin)
        copies = max(int(round(_v29_to_float(self, r.get("Copies"), 1))), 1)
        scale = _v29_to_float(self, r.get("Scale mmol"), 0.2)
        loading = _v29_to_float(self, r.get("Loading"), 0.0)
        resin_mmol = scale * copies
        resin_g = resin_mmol / loading if loading else 0.0
        cterm_aa = _v203_last_aa_from_sequence(self, r.get("Sequence", ""))
        loading_aa_mmol = resin_mmol * aa_eq
        diea_mmol = resin_mmol * diea_eq
        aa_mw = _v213_display_mw(self, cterm_aa) or self._mw_for_token(cterm_aa) if cterm_aa else 0.0
        diea_mw = _v213_display_mw(self, "DIEA") or 129.25
        diea_density = _v213_display_density(self, "DIEA") or 0.742
        loading_aa_g = loading_aa_mmol * float(aa_mw) / 1000.0 if aa_mw else 0.0
        diea_g = diea_mmol * float(diea_mw) / 1000.0 if diea_mw else 0.0
        diea_ml = diea_g / float(diea_density) if diea_density else 0.0
        ratio_note = f"resin:AA:DIEA = 1:{aa_eq:g}:{diea_eq:g}; applied only because Loading rate checkbox is ON"
        out.append({"Category":"Resin loading","Item":resin,"Solvent":"","Count":copies,"Eq":1,"Conc_M":"","Calculated_mL":"","Actual_mL":"","MW":"","Density":"","Weight_g":_v201_round2(resin_g),"Volume_mL":"","Note":f"loading rate used: resin_g = {resin_mmol:.2f} mmol / {loading:.2f} mmol/g" if loading else "loading rate missing; resin mass not calculated"})
        if cterm_aa:
            out.append({"Category":"Resin loading","Item":cterm_aa,"Solvent":solvent,"Count":copies,"Eq":aa_eq,"Conc_M":"","Calculated_mL":"","Actual_mL":"","MW":_v201_round2(float(aa_mw)) if aa_mw else "manual","Density":"","Weight_g":_v201_round2(loading_aa_g),"Volume_mL":"","Note":f"C-terminal loading amino acid for {resin}; {ratio_note}"})
        out.append({"Category":"Resin loading","Item":"DIEA","Solvent":solvent,"Count":copies,"Eq":diea_eq,"Conc_M":"","Calculated_mL":_v201_round1(diea_ml),"Actual_mL":_v201_round1(diea_ml),"MW":_v201_round2(float(diea_mw)),"Density":_v201_round2(float(diea_density)),"Weight_g":_v201_round2(diea_g),"Volume_mL":_v201_round1(diea_ml),"Note":f"DIEA for {resin} loading; {ratio_note}"})
    return pd.DataFrame(out, columns=cols)

def _v213_remove_loading_rate_notes(self):
    try:
        phrases = [
            "Selected resin is controlled", "Default: resin", "Default loading ratio", "2-CTC(합성기)",
            "2-CTC(합성용)", "Edit eq fields when SOP differs"
        ]
        def walk(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label):
                        txt = str(c.cget("text"))
                        if any(p in txt for p in phrases):
                            c.destroy()
                            continue
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v213_pm_generate_selected(self):
    result = None
    try:
        result = _v212_pm_generate_selected(self)
    except Exception:
        try:
            result = _v211_pm_generate_selected(self)
        except Exception:
            pass
    try:
        _v213_refresh_selected_plan(self)
        _v213_add_apply_plan_button(self)
        _v213_remove_loading_rate_notes(self)
    except Exception:
        pass
    return result

