def _v213_build(self):
    global _v212_active_gui_instance
    _v212_active_gui_instance = self
    if _v213_old_build:
        _v213_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        _v213_ensure_resin_values(self)
        for child in self.winfo_children():
            for sub in child.winfo_children():
                try:
                    if isinstance(sub, ttk.Label) and str(sub.cget("text")).startswith("SPPS Planner"):
                        sub.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception:
                    pass
    except Exception:
        pass
    try:
        _v213_refresh_selected_plan(self)
        _v213_add_apply_plan_button(self)
        _v213_remove_loading_rate_notes(self)
    except Exception:
        pass

