def _v214_norm_text(x):
    return str(x or "").strip().lower().replace(" ", "")


def _v214_is_preloaded_ctc(name) -> bool:
    s = _v214_norm_text(name)
    # Exact synthesizer/preloaded CTC naming must not be classified as direct-loading by the CTC substring.
    return (("ctc" in s or "chlorotrityl" in s or "trityl" in s) and
            ("합성용" in s or "합성기" in s or "synth" in s or "preloaded" in s))


def _v214_is_plain_2ctc(name) -> bool:
    s = _v214_norm_text(name)
    return ("2-ctc" in s or "2chlorotrityl" in s or "2-chlorotrityl" in s) and not _v214_is_preloaded_ctc(s)


def _v214_is_direct_loading_resin(name) -> bool:
    s = _v214_norm_text(name)
    if _v214_is_preloaded_ctc(s):
        return False
    if _v214_is_plain_2ctc(s):
        return True
    return any(k in s for k in ["ctc/trityl", "trityl", "chlorotrityl", "wang", "hmpb", "sieber", "pal"])


def _v214_loading_checkbox_on(self) -> bool:
    try:
        return bool(getattr(self, "apply_loading_calc").get())
    except Exception:
        return False


def _v214_loading_applies(self, resin_value=None) -> bool:
    try:
        resin = resin_value if resin_value is not None else self.pm_resin.get()
    except Exception:
        resin = resin_value or ""
    if _v214_is_preloaded_ctc(resin):
        return False
    return _v214_loading_checkbox_on(self) and _v214_is_direct_loading_resin(resin)


def _v214_normalize_resin_name(name: str) -> str:
    raw = str(name or "").strip()
    if _v214_is_preloaded_ctc(raw):
        return "CTC(합성용)"
    if _v214_is_plain_2ctc(raw):
        return "2-CTC"
    return raw or "Rink Amide AM"


def _v214_resin_family_text(self) -> str:
    try:
        r = self.resin.get()
    except Exception:
        try:
            r = self.pm_resin.get()
        except Exception:
            r = ""
    if _v214_is_preloaded_ctc(r):
        return "Amide"
    if _v214_loading_applies(self, r):
        return "CTC/Trityl"
    return "Amide"


def _v214_ensure_resin_values(self):
    try:
        self.RESIN_VALUES = list(_V214_RESIN_VALUES)
        SPPSGui.RESIN_VALUES = list(_V214_RESIN_VALUES)
    except Exception:
        pass
    try:
        cur = self.pm_resin.get()
        norm = _v214_normalize_resin_name(cur)
        if norm != cur:
            self.pm_resin.set(norm)
    except Exception:
        pass
    def walk(w):
        try:
            children = w.winfo_children()
        except Exception:
            return
        for c in children:
            try:
                if isinstance(c, ttk.Combobox):
                    vals = [str(v) for v in (c.cget("values") or [])]
                    if any("CTC" in v or "Trityl" in v or "Amide" in v for v in vals):
                        c.configure(values=list(_V214_RESIN_VALUES))
            except Exception:
                pass
            walk(c)
    try:
        walk(self)
    except Exception:
        pass


def _v214_strip_loading_rate_input_row(self):
    """Remove only the resin loading mmol/g input row, not the Loading rate tab itself."""
    try:
        def walk(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label) and str(c.cget("text")).strip() == "Loading rate":
                        info = c.grid_info(); parent = c.master; row = int(info.get("row", -999))
                        # Destroy all widgets in that same grid row: label, entry, mmol/g label.
                        for sib in list(parent.winfo_children()):
                            try:
                                si = sib.grid_info()
                                if si and int(si.get("row", -1)) == row:
                                    sib.destroy()
                            except Exception:
                                pass
                        continue
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass


def _v214_remove_loading_help_notes(self):
    phrases = [
        "Selected resin is controlled", "Default: resin", "Default loading ratio",
        "Edit eq fields when SOP differs", "2-CTC(합성기)", "2-CTC(합성용)",
    ]
    try:
        def walk(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label):
                        txt = str(c.cget("text"))
                        if any(p in txt for p in phrases):
                            c.destroy(); continue
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass


def _v214_lookup_mw_density(self, unit_name):
    name = str(unit_name or "").strip()
    low = name.lower()
    if not name:
        return "", ""
    # Manual override has top priority.
    try:
        overrides = getattr(self, "material_overrides", {}) or {}
        for key in {low, low.replace(" ", ""), name.strip().lower()}:
            o = overrides.get(key, {})
            mw_o = o.get("MW", "")
            den_o = o.get("density_g_per_mL", "")
            if str(mw_o).strip() or str(den_o).strip():
                mw = round(float(mw_o), 2) if str(mw_o).strip() else ""
                den = round(float(den_o), 3) if str(den_o).strip() else ""
                return mw, den
    except Exception:
        pass
    # Protected Fmoc amino acids shown as reagent names.
    try:
        import re
        m = re.search(r"Fmoc[- ](?:D[- ]?)?([A-Za-z]{3})", name, flags=re.I)
        if m:
            key = m.group(1).lower()
            if key in _V214_FMOC_3LETTER_TO_MW:
                return round(float(_V214_FMOC_3LETTER_TO_MW[key]), 2), ""
    except Exception:
        pass
    # One-letter AA stock rows.
    if name.upper() in _V214_ONELETTER_TO_MW:
        return round(float(_V214_ONELETTER_TO_MW[name.upper()]), 2), ""
    # Reagents/solvents/liquids; MW applies to both solids and liquids.
    compact = low.replace(" ", "")
    for k, mw in _V214_REAGENT_MW.items():
        if k in low or k.replace(" ", "") in compact:
            den = ""
            for dk, dv in _V214_DENSITY.items():
                if dk in low or dk.replace(" ", "") in compact:
                    den = round(float(dv), 3)
                    break
            return round(float(mw), 2), den
    # Existing DB fallback.
    try:
        mw = self._mw_for_token(name)
    except Exception:
        mw = 0
    try:
        den = self._density_for_token(name)
    except Exception:
        den = 0
    return (round(float(mw), 2) if mw else "", round(float(den), 3) if den else "")


def _v214_plan_key(row: dict) -> str:
    return str(row.get("Unit name") or row.get("material") or row.get("Item") or row.get("AA") or "").strip()


def _v214_is_loading_plan_row(row: dict) -> bool:
    text = " ".join(str(v).lower() for v in row.values())
    if any(k in text for k in ["first loading", "resin loading", "c-terminal loading", "first attachment", "trityl/2-ctc"]):
        return True
    try:
        unit_eq = float(str(row.get("Unit eq", "")).strip() or "0")
    except Exception:
        unit_eq = 0.0
    reagent = str(row.get("Coupling reagent 1", "") or "").strip()
    base = str(row.get("Coupling base", "") or "").lower()
    # The observed wrong row: first Fmoc AA + Unit eq 2 + DIEA + no coupling reagent.
    if not reagent and "diea" in base and abs(unit_eq - 2.0) < 1e-6:
        return True
    return False


def _v214_dataframe_from_tree(tree):
    try:
        cols = list(tree["columns"])
        rows = []
        for iid in tree.get_children():
            vals = list(tree.item(iid, "values"))
            vals += [""] * max(0, len(cols) - len(vals))
            rows.append(dict(zip(cols, vals)))
        return pd.DataFrame(rows, columns=cols)
    except Exception:
        return pd.DataFrame()


def _v214_enrich_plan_df(self, df):
    out = pd.DataFrame() if df is None else df.copy()
    if out.empty:
        return pd.DataFrame(columns=["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)"])
    # Checkbox OFF: all direct-loading rows are removed. CTC(합성용): always remove them.
    try:
        resin = self.pm_resin.get()
    except Exception:
        resin = ""
    if not _v214_loading_applies(self, resin):
        out = out[[not _v214_is_loading_plan_row(dict(r)) for _, r in out.iterrows()]].copy()
        if "No" in out.columns:
            out["No"] = list(range(1, len(out) + 1))
    if "density_g_per_mL" in out.columns and "Density(g/mL)" not in out.columns:
        out = out.rename(columns={"density_g_per_mL": "Density(g/mL)"})
    if "MW" not in out.columns:
        pos = list(out.columns).index("Unit name") + 1 if "Unit name" in out.columns else min(2, len(out.columns))
        out.insert(pos, "MW", "")
    if "Density(g/mL)" not in out.columns:
        pos = list(out.columns).index("MW") + 1 if "MW" in out.columns else min(3, len(out.columns))
        out.insert(pos, "Density(g/mL)", "")
    for i, row in out.iterrows():
        unit = _v214_plan_key(row)
        mw, den = _v214_lookup_mw_density(self, unit)
        # Always pre-fill/refresh from DB or overrides. Edited values persist after Apply Plan because overrides win.
        out.at[i, "MW"] = mw
        out.at[i, "Density(g/mL)"] = den
    preferred = [
        "No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)", "Unit volume(mL)",
        "Coupling reagent 1", "Coupling reagent 2", "Coupling reagent 2 / catalyst", "Coupling base",
        "Coupling cocktail solvent", "Coupling cocktail volume(mL)", "Repeat", "Note",
    ]
    cols = [c for c in preferred if c in out.columns]
    for c in out.columns:
        if c not in cols and c not in {"density_g_per_mL", "Solvent 1", "Solvent 2", "Solvent 1 count", "Solvent 2 count"}:
            cols.append(c)
    return out[cols]


def _v214_write_plan_df_to_tree(self, df):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    cols = list(df.columns) if df is not None and not df.empty else ["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)"]
    try:
        tree.configure(columns=cols, show="headings")
        widths = {"No": 50, "Unit name": 230, "MW": 90, "Density(g/mL)": 125, "Unit eq": 85, "Unit amount(g)": 120, "Unit volume(mL)": 120, "Note": 260}
        for c in cols:
            tree.heading(c, text=c)
            tree.column(c, width=widths.get(c, 125), minwidth=55, stretch=False, anchor="w")
        for iid in list(tree.get_children()):
            tree.delete(iid)
        if df is not None and not df.empty:
            for _, row in df.iterrows():
                vals = []
                for c in cols:
                    v = row.get(c, "")
                    try:
                        if pd.isna(v): v = ""
                    except Exception:
                        pass
                    vals.append(v)
                tree.insert("", "end", values=vals)
        _v28_make_tree_editable(self, tree, self._v28_on_selected_result_edit)
    except Exception:
        pass


def _v214_refresh_selected_plan(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    df = _v214_dataframe_from_tree(tree)
    if df is None or df.empty:
        try:
            df = self.pm_tree_to_df(self.tree)
        except Exception:
            df = pd.DataFrame()
    df = _v214_enrich_plan_df(self, df)
    _v214_write_plan_df_to_tree(self, df)


def _v214_commit_plan_overrides(self) -> int:
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return 0
    if not hasattr(self, "material_overrides") or self.material_overrides is None:
        self.material_overrides = {}
    cols = list(tree["columns"])
    count = 0
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals))
        unit = _v214_plan_key(row)
        if not unit:
            continue
        keys = {unit.lower(), unit.lower().replace(" ", "")}
        # Also store one-letter AA override for Fmoc protected amino acid rows.
        try:
            import re
            m = re.search(r"Fmoc[- ](?:D[- ]?)?([A-Za-z]{3})", unit, flags=re.I)
            tri_to_one = {"ala":"A","arg":"R","asn":"N","asp":"D","cys":"C","gln":"Q","glu":"E","gly":"G","his":"H","ile":"I","leu":"L","lys":"K","met":"M","phe":"F","pro":"P","ser":"S","thr":"T","trp":"W","tyr":"Y","val":"V"}
            if m and m.group(1).lower() in tri_to_one:
                keys.add(tri_to_one[m.group(1).lower()].lower())
        except Exception:
            pass
        for col, field in [("MW", "MW"), ("Density(g/mL)", "density_g_per_mL")]:
            txt = str(row.get(col, "")).strip()
            if not txt:
                continue
            try:
                val = float(txt)
            except Exception:
                continue
            for k in keys:
                self.material_overrides.setdefault(k, {})[field] = val
                count += 1
    try:
        self.schedule_autosave()
    except Exception:
        pass
    return count


def _v214_apply_plan(self):
    _v214_commit_plan_overrides(self)
    _v214_refresh_selected_plan(self)
    try:
        # Rebuild Selected Materials using the same overrides.
        if hasattr(self, "refresh_outputs_from_tree"):
            self.refresh_outputs_from_tree()
    except Exception:
        pass
    try:
        if hasattr(self, "refresh_batch_workspace_preview"):
            self.refresh_batch_workspace_preview()
    except Exception:
        pass


def _v214_single_apply_plan_button(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    parent = tree.master
    try:
        # Remove all old duplicate Apply Plan toolbars/labels/buttons in this parent.
        for child in list(parent.winfo_children()):
            try:
                if isinstance(child, ttk.Frame):
                    texts = []
                    for sub in child.winfo_children():
                        try: texts.append(str(sub.cget("text")))
                        except Exception: pass
                    if any("Apply Plan" in t or "Density" in t for t in texts):
                        child.destroy()
                elif isinstance(child, ttk.Button) and str(child.cget("text")) == "Apply Plan":
                    child.destroy()
                elif isinstance(child, ttk.Label) and ("Apply Plan" in str(child.cget("text")) or "Density" in str(child.cget("text"))):
                    child.destroy()
            except Exception:
                pass
        # Move existing grid rows down once, only if no toolbar marker remains.
        for child in list(parent.winfo_children()):
            try:
                info = child.grid_info()
                if info:
                    child.grid_configure(row=int(info.get("row", 0)) + 1)
            except Exception:
                pass
        toolbar = ttk.Frame(parent, padding=(4, 3))
        toolbar._v214_apply_toolbar = True
        toolbar.grid(row=0, column=0, columnspan=2, sticky="ew")
        ttk.Button(toolbar, text="Apply Plan", command=lambda: _v214_apply_plan(self)).pack(side="left", padx=3)
        ttk.Label(toolbar, text="Edit MW / Density(g/mL), then Apply Plan.").pack(side="left", padx=(8, 0))
    except Exception:
        pass


def _v214_selected_edit(self, tree, row_id, col_name, new_value):
    try:
        cols = list(tree["columns"])
        vals = list(tree.item(row_id, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        if col_name in {"MW", "Density(g/mL)", "density_g_per_mL", "Density", "density"}:
            col_name = "Density(g/mL)" if col_name != "MW" else "MW"
            if col_name in cols:
                vals[cols.index(col_name)] = new_value
                tree.item(row_id, values=vals)
                return
    except Exception:
        pass
    try:
        _v213_selected_edit(self, tree, row_id, col_name, new_value)
    except Exception:
        pass


def _v214_resin_loading_df(self, rows):
    cols = globals().get("V29_BATCH_COLUMNS", ["Category", "Item", "Solvent", "Count", "Eq", "Conc_M", "Calculated_mL", "Actual_mL", "MW", "Density", "Weight_g", "Volume_mL", "Note"])
    # If the checkbox is off or the selected resin is preloaded CTC(합성용), no loading table is generated.
    try:
        selected_resin = self.pm_resin.get()
    except Exception:
        selected_resin = ""
    if not _v214_loading_applies(self, selected_resin):
        return pd.DataFrame([], columns=cols)
    try:
        return _v213_resin_loading_df(self, rows)
    except Exception:
        return pd.DataFrame([], columns=cols)


