def _v216_compact(x):
    return str(x or "").strip().lower().replace(" ", "").replace("_", "").replace("-", "")


def _v216_is_preloaded_ctc(name) -> bool:
    # CTC(합성용) is intentionally distinct from 2-CTC. It is preloaded and amide-like.
    s = _v216_compact(name)
    return "ctc(합성용)" in s or "합성용" in s or "합성기" in s or "preloaded" in s or "synthesizer" in s


def _v216_is_plain_2ctc(name) -> bool:
    s = _v216_compact(name)
    if _v216_is_preloaded_ctc(name):
        return False
    return s in {"2ctc", "ctctrityl(2ctc)"} or "2ctc" in s


def _v216_is_direct_loading_resin(name) -> bool:
    s = _v216_compact(name)
    if _v216_is_preloaded_ctc(name):
        return False
    if _v216_is_plain_2ctc(name):
        return True
    return any(k in s for k in ["ctctrityl", "tritylchloride", "wang", "hmpb", "sieber", "palresin"])


def _v216_loading_checkbox_on(self) -> bool:
    try:
        return bool(getattr(self, "apply_loading_calc").get())
    except Exception:
        return False


def _v216_loading_applies(self, resin_value=None) -> bool:
    try:
        resin = resin_value if resin_value is not None else self.pm_resin.get()
    except Exception:
        resin = resin_value or ""
    if _v216_is_preloaded_ctc(resin):
        return False
    return _v216_loading_checkbox_on(self) and _v216_is_direct_loading_resin(resin)


def _v216_normalize_resin_name(name: str) -> str:
    raw = str(name or "").strip()
    s = _v216_compact(raw)
    if _v216_is_preloaded_ctc(raw):
        return "CTC(합성용)"
    if "2chlorotritylchlorideresin" in s or "chlorotritylchloride" in s:
        return "2-CTC"
    if _v216_is_plain_2ctc(raw):
        return "2-CTC"
    return raw or "Rink Amide AM"


def _v216_resin_family_text(self) -> str:
    try:
        resin = self.pm_resin.get()
    except Exception:
        try:
            resin = self.resin.get()
        except Exception:
            resin = ""
    if _v216_is_preloaded_ctc(resin):
        return "Amide"
    if _v216_loading_applies(self, resin):
        return "CTC/Trityl"
    return "Amide"


def _v216_ensure_resin_values(self):
    try:
        self.RESIN_VALUES = list(_V216_RESIN_VALUES)
        SPPSGui.RESIN_VALUES = list(_V216_RESIN_VALUES)
    except Exception:
        pass
    for attr in ("pm_resin", "resin"):
        try:
            v = getattr(self, attr)
            cur = v.get()
            norm = _v216_normalize_resin_name(cur)
            if norm != cur:
                v.set(norm)
        except Exception:
            pass
    def walk(w):
        try:
            children = w.winfo_children()
        except Exception:
            return
        for c in children:
            try:
                if isinstance(c, ttk.Combobox):
                    vals = [str(v) for v in (c.cget("values") or [])]
                    if any(x in " ".join(vals) for x in ["CTC", "Trityl", "Amide", "Wang", "PAL", "HMPB", "Sieber"]):
                        c.configure(values=list(_V216_RESIN_VALUES))
            except Exception:
                pass
            walk(c)
    try:
        walk(self)
    except Exception:
        pass


def _v216_ensure_resin_loading_editor(self):
    """Create one visible Resin loading (mmol/g) entry next to the Resin selector."""
    try:
        if getattr(self, "_v216_resin_loading_editor_added", False):
            return
        # Find the Selected peptide editor frame through the pm_resin combobox.
        edit_frame = None
        def walk(w):
            nonlocal edit_frame
            if edit_frame is not None:
                return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Combobox) and str(c.cget("textvariable")) == str(self.pm_resin):
                        edit_frame = c.master
                        return
                except Exception:
                    pass
                walk(c)
        walk(self)
        if edit_frame is None:
            return
        # Remove/hide legacy "Loading" row widgets bound to pm_loading to prevent duplicates.
        for c in list(edit_frame.winfo_children()):
            try:
                if isinstance(c, ttk.Label) and str(c.cget("text")).strip() in {"Loading", "Loading rate"}:
                    c.grid_remove()
                if isinstance(c, ttk.Entry) and str(c.cget("textvariable")) == str(self.pm_loading):
                    c.grid_remove()
            except Exception:
                pass
        ttk.Label(edit_frame, text="Resin loading").grid(row=2, column=4, sticky="w", padx=(2, 4), pady=2)
        ttk.Entry(edit_frame, textvariable=self.pm_loading, width=10).grid(row=2, column=5, sticky="ew", padx=(0, 4), pady=2)
        ttk.Label(edit_frame, text="mmol/g").grid(row=2, column=6, sticky="w", padx=(0, 8), pady=2)
        self._v216_resin_loading_editor_added = True
    except Exception:
        pass


def _v216_clean_loading_setup_tab(self):
    """Keep AA eq/DIEA eq/solvent in setup. Remove duplicate resin/loading-rate rows there."""
    try:
        def walk(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label) and str(c.cget("text")).strip() in {"Selected resin", "Loading rate"}:
                        parent = c.master
                        row = int(c.grid_info().get("row", -999))
                        for sib in list(parent.winfo_children()):
                            try:
                                info = sib.grid_info()
                                if info and int(info.get("row", -1)) == row:
                                    sib.destroy()
                            except Exception:
                                pass
                        continue
                    if isinstance(c, ttk.Label) and "mmol/g" in str(c.cget("text")):
                        c.destroy(); continue
                    if isinstance(c, ttk.Label) and "Default loading ratio" in str(c.cget("text")):
                        c.destroy(); continue
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass


def _v216_plan_item_key(row: dict) -> str:
    return str(row.get("Unit name") or row.get("material") or row.get("Item") or row.get("AA") or "").strip()


def _v216_lookup_mw_density(self, unit_name):
    name = str(unit_name or "").strip()
    if not name:
        return "", ""
    low = name.lower()
    compact = low.replace(" ", "")
    # user overrides first; both exact display key and compact key are supported
    try:
        overrides = getattr(self, "material_overrides", {}) or {}
        for k in {low, compact, name.strip(), name.strip().lower().replace(" ", "")}:
            o = overrides.get(k, {})
            if o:
                mw = o.get("MW", "")
                den = o.get("density_g_per_mL", o.get("Density(g/mL)", ""))
                return (round(float(mw), 2) if str(mw).strip() else "", round(float(den), 3) if str(den).strip() else "")
    except Exception:
        pass
    # N-terminal Ac means Ac2O material for the plan display.
    if low in {"ac", "acetyl", "n-acetyl"}:
        return 102.09, 1.08
    # Direct known names / substring lookup.
    for k, mw in _V216_REAGENT_MW.items():
        kk = str(k).lower().replace(" ", "")
        if kk and (kk == compact or kk in compact):
            den = ""
            for dk, dv in _V216_DENSITY.items():
                dd = str(dk).lower().replace(" ", "")
                if dd and (dd == compact or dd in compact):
                    den = round(float(dv), 3); break
            return round(float(mw), 2), den
    # Fmoc-3letter protected AA names.
    try:
        m = re.search(r"Fmoc[- ](?:D[- ]?)?([A-Za-z]{3})", name, flags=re.I)
        tri = {"ala":"A","arg":"R","asn":"N","asp":"D","cys":"C","gln":"Q","glu":"E","gly":"G","his":"H","ile":"I","leu":"L","lys":"K","met":"M","phe":"F","pro":"P","ser":"S","thr":"T","trp":"W","tyr":"Y","val":"V"}
        if m and m.group(1).lower() in tri:
            aa = tri[m.group(1).lower()]
            if aa in _V216_FMOC_MW:
                return round(float(_V216_FMOC_MW[aa]), 2), ""
    except Exception:
        pass
    # One-letter AA unit means Fmoc-AA reagent MW for synthesizer prep.
    if name.upper() in _V216_FMOC_MW:
        return round(float(_V216_FMOC_MW[name.upper()]), 2), ""
    try:
        mw = self._mw_for_token(name)
    except Exception:
        mw = 0
    try:
        den = self._density_for_token(name)
    except Exception:
        den = 0
    return (round(float(mw), 2) if mw else "", round(float(den), 3) if den else "")


def _v216_is_loading_plan_row(row: dict) -> bool:
    text = " ".join(str(v).lower() for v in row.values())
    if any(k in text for k in ["first loading", "resin loading", "c-terminal loading", "first attachment", "trityl/2-ctc", "loading amino acid"]):
        return True
    def val(col):
        for k, v in row.items():
            if str(k).strip().lower() == col.lower():
                return v
        return ""
    try:
        unit_eq = float(str(val("Unit eq")).strip() or "0")
    except Exception:
        unit_eq = 0.0
    reagent1 = str(val("Coupling reagent 1") or "").strip()
    base = str(val("Coupling base") or "").lower()
    # Wrong observed row: first AA at 2 eq with DIEA and no DIC/HBTU reagent.
    if abs(unit_eq - 2.0) < 1e-6 and "diea" in base and not reagent1:
        return True
    return False


def _v216_tree_to_df(tree):
    try:
        cols = list(tree["columns"]); rows = []
        for iid in tree.get_children():
            vals = list(tree.item(iid, "values")); vals += [""] * max(0, len(cols) - len(vals))
            rows.append(dict(zip(cols, vals)))
        return pd.DataFrame(rows, columns=cols)
    except Exception:
        return pd.DataFrame()


def _v216_selected_plan_source_df(self):
    # Main generated plan tree is the source after Generate / Update. Fallback to selected plan tree if needed.
    try:
        main_tree = getattr(self, "tree", None)
        if main_tree is not None and len(main_tree.get_children()) > 0:
            return _v216_tree_to_df(main_tree)
    except Exception:
        pass
    try:
        sel_tree = getattr(self, "pm_selected_plan_tree", None)
        if sel_tree is not None:
            return _v216_tree_to_df(sel_tree)
    except Exception:
        pass
    return pd.DataFrame()


def _v216_enrich_plan_df(self, df):
    out = pd.DataFrame() if df is None else df.copy()
    if out.empty:
        return pd.DataFrame(columns=["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)"])
    try:
        resin = self.pm_resin.get()
    except Exception:
        resin = ""
    # Remove loading rows unless loading explicitly applies. CTC(합성용) always removes them.
    if not _v216_loading_applies(self, resin):
        keep = []
        for _, r in out.iterrows():
            keep.append(not _v216_is_loading_plan_row(dict(r)))
        out = out[keep].copy()
        if "No" in out.columns:
            out["No"] = list(range(1, len(out) + 1))
    if "density_g_per_mL" in out.columns and "Density(g/mL)" not in out.columns:
        out = out.rename(columns={"density_g_per_mL": "Density(g/mL)"})
    if "MW" not in out.columns:
        pos = list(out.columns).index("Unit name") + 1 if "Unit name" in out.columns else min(2, len(out.columns))
        out.insert(pos, "MW", "")
    if "Density(g/mL)" not in out.columns:
        pos = list(out.columns).index("MW") + 1 if "MW" in out.columns else min(3, len(out.columns))
        out.insert(pos, "Density(g/mL)", "")
    for i, row in out.iterrows():
        unit = _v216_plan_item_key(row)
        mw, den = _v216_lookup_mw_density(self, unit)
        out.at[i, "MW"] = mw
        out.at[i, "Density(g/mL)"] = den
    preferred = ["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)", "Unit volume(mL)",
                 "Coupling reagent 1", "Coupling reagent 2", "Coupling reagent 2 / catalyst", "Coupling base",
                 "Coupling cocktail solvent", "Coupling cocktail volume(mL)", "Repeat", "Note"]
    cols = [c for c in preferred if c in out.columns]
    for c in out.columns:
        if c not in cols and c not in {"density_g_per_mL", "Solvent 1", "Solvent 1 count", "Solvent 2", "Solvent 2 count"}:
            cols.append(c)
    return out[cols]


def _v216_write_df_to_tree(self, tree, df):
    cols = list(df.columns) if df is not None and not df.empty else ["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)"]
    tree.configure(columns=cols, show="headings")
    widths = {"No": 50, "Unit name": 245, "MW": 95, "Density(g/mL)": 135, "Unit eq": 85, "Unit amount(g)": 125, "Unit volume(mL)": 125, "Note": 260}
    for c in cols:
        tree.heading(c, text=c)
        tree.column(c, width=widths.get(c, 130), minwidth=55, stretch=False, anchor="w")
    for iid in list(tree.get_children()):
        tree.delete(iid)
    if df is not None and not df.empty:
        for _, row in df.iterrows():
            vals = []
            for c in cols:
                v = row.get(c, "")
                try:
                    if pd.isna(v):
                        v = ""
                except Exception:
                    pass
                vals.append(v)
            tree.insert("", "end", values=vals)
    try:
        _v28_make_tree_editable(self, tree, self._v28_on_selected_result_edit)
    except Exception:
        pass


def _v216_refresh_selected_plan(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    df = _v216_selected_plan_source_df(self)
    df = _v216_enrich_plan_df(self, df)
    _v216_write_df_to_tree(self, tree, df)


def _v216_commit_plan_overrides(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return 0
    if not hasattr(self, "material_overrides") or self.material_overrides is None:
        self.material_overrides = {}
    cols = list(tree["columns"]); n = 0
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values")); vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals)); unit = _v216_plan_item_key(row)
        if not unit:
            continue
        keys = {unit.lower(), unit.lower().replace(" ", "")}
        try:
            m = re.search(r"Fmoc[- ](?:D[- ]?)?([A-Za-z]{3})", unit, flags=re.I)
            tri = {"ala":"A","arg":"R","asn":"N","asp":"D","cys":"C","gln":"Q","glu":"E","gly":"G","his":"H","ile":"I","leu":"L","lys":"K","met":"M","phe":"F","pro":"P","ser":"S","thr":"T","trp":"W","tyr":"Y","val":"V"}
            if m and m.group(1).lower() in tri:
                keys.add(tri[m.group(1).lower()].lower())
        except Exception:
            pass
        for col, field in [("MW", "MW"), ("Density(g/mL)", "density_g_per_mL")]:
            txt = str(row.get(col, "")).strip()
            if not txt:
                continue
            try:
                val = float(txt)
            except Exception:
                continue
            for k in keys:
                self.material_overrides.setdefault(k, {})[field] = val
                n += 1
    try:
        self.schedule_autosave()
    except Exception:
        pass
    return n


def _v216_update_material_tree_mw_density(self):
    tree = getattr(self, "pm_selected_material_tree", None)
    if tree is None:
        return
    try:
        old_cols = list(tree["columns"])
        cols = list(old_cols)
        if "MW" not in cols:
            cols.insert(min(3, len(cols)), "MW")
        density_col = "Density(g/mL)" if "Density(g/mL)" in cols else "density_g_per_mL"
        if density_col not in cols:
            cols.insert(cols.index("MW") + 1 if "MW" in cols else min(4, len(cols)), density_col)
        rows = []
        for iid in tree.get_children():
            vals = list(tree.item(iid, "values")); vals += [""] * max(0, len(old_cols) - len(vals))
            row = dict(zip(old_cols, vals))
            key = str(row.get("material") or row.get("Unit name") or row.get("Item") or "").strip()
            mw, den = _v216_lookup_mw_density(self, key)
            row["MW"] = mw
            row[density_col] = den
            rows.append(row)
        df = pd.DataFrame(rows, columns=cols)
        _v216_write_df_to_tree(self, tree, df)
    except Exception:
        pass


def _v216_apply_plan(self):
    _v216_commit_plan_overrides(self)
    _v216_refresh_selected_plan(self)
    _v216_update_material_tree_mw_density(self)
    try:
        if hasattr(self, "refresh_batch_workspace_preview"):
            self.refresh_batch_workspace_preview()
    except Exception:
        pass
    try:
        self.schedule_autosave()
    except Exception:
        pass


def _v216_single_apply_plan_button(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    parent = tree.master
    try:
        # Remove every old Apply Plan toolbar/button/label first.
        for child in list(parent.winfo_children()):
            try:
                texts = []
                if isinstance(child, ttk.Frame):
                    for sub in child.winfo_children():
                        try: texts.append(str(sub.cget("text")))
                        except Exception: pass
                    if any("Apply Plan" in t or "Density" in t for t in texts):
                        child.destroy(); continue
                if isinstance(child, ttk.Button) and str(child.cget("text")) == "Apply Plan":
                    child.destroy(); continue
                if isinstance(child, ttk.Label) and ("Apply Plan" in str(child.cget("text")) or "Density" in str(child.cget("text"))):
                    child.destroy(); continue
            except Exception:
                pass
        for child in list(parent.winfo_children()):
            try:
                info = child.grid_info()
                if info and child is tree:
                    child.grid_configure(row=1)
            except Exception:
                pass
        toolbar = ttk.Frame(parent, padding=(4, 3)); toolbar.grid(row=0, column=0, columnspan=2, sticky="ew")
        ttk.Button(toolbar, text="Apply Plan", command=lambda: _v216_apply_plan(self)).pack(side="left", padx=3)
    except Exception:
        pass


def _v216_selected_edit(self, tree, row_id, col_name, new_value):
    try:
        cols = list(tree["columns"]); vals = list(tree.item(row_id, "values")); vals += [""] * max(0, len(cols) - len(vals))
        target = "Density(g/mL)" if str(col_name).lower() in {"density(g/ml)", "density", "density_g_per_ml"} else col_name
        if target in {"MW", "Density(g/mL)"} and target in cols:
            vals[cols.index(target)] = new_value
            tree.item(row_id, values=vals)
            return
    except Exception:
        pass
    try:
        _v215_selected_edit(self, tree, row_id, col_name, new_value)
    except Exception:
        pass


def _v216_resin_loading_df(self, rows=None):
    cols = globals().get("V29_BATCH_COLUMNS", ["Category", "Item", "Solvent", "Count", "Eq", "Conc_M", "Calculated_mL", "Actual_mL", "MW", "Density", "Weight_g", "Volume_mL", "Note"])
    out = []
    try:
        checked = _v216_loading_checkbox_on(self)
    except Exception:
        checked = False
    if not checked:
        return pd.DataFrame([], columns=cols)
    rows = rows or []
    aa_eq = _v29_to_float(self, getattr(self, "loading_aa_eq", None), 2.0)
    diea_eq = _v29_to_float(self, getattr(self, "loading_diea_eq", None), 4.0)
    try:
        solvent = getattr(self, "default_loading_dissolve_solvent").get() or "90% DCM / 10% DMF"
    except Exception:
        solvent = "90% DCM / 10% DMF"
    for r in rows:
        raw_resin = r.get("Resin", "") or r.get("resin", "")
        if not _v216_is_direct_loading_resin(raw_resin):
            continue
        resin = _v216_normalize_resin_name(raw_resin)
        if _v216_is_preloaded_ctc(resin):
            continue
        copies = max(int(round(_v29_to_float(self, r.get("Copies") or r.get("copies"), 1))), 1)
        scale = _v29_to_float(self, r.get("Scale mmol") or r.get("scale") or r.get("scale_mmol"), 0.2)
        loading = _v29_to_float(self, r.get("Loading") or r.get("loading") or r.get("loading_mmol_g"), 0.0)
        resin_mmol = scale * copies
        resin_g = resin_mmol / loading if loading else 0.0
        cterm_aa = _v203_last_aa_from_sequence(self, r.get("Sequence") or r.get("sequence") or "")
        aa_mmol = resin_mmol * aa_eq
        diea_mmol = resin_mmol * diea_eq
        aa_mw, _ = _v216_lookup_mw_density(self, cterm_aa)
        diea_mw, diea_den = _v216_lookup_mw_density(self, "DIEA")
        aa_mw = float(aa_mw or 0); diea_mw = float(diea_mw or 129.25); diea_den = float(diea_den or 0.742)
        aa_g = aa_mmol * aa_mw / 1000.0 if aa_mw else 0.0
        diea_g = diea_mmol * diea_mw / 1000.0
        diea_ml = diea_g / diea_den if diea_den else 0.0
        note = f"resin_g = resin_mmol/loading = {resin_mmol:.2f}/{loading:.2f}; resin:AA:DIEA = 1:{aa_eq:g}:{diea_eq:g}"
        out.append({"Category":"Resin loading", "Item":resin, "Solvent":"", "Count":copies, "Eq":1, "Conc_M":"", "Calculated_mL":"", "Actual_mL":"", "MW":"", "Density":"", "Weight_g":_v201_round2(resin_g), "Volume_mL":"", "Note":note if loading else "loading mmol/g missing; resin g cannot be calculated"})
        if cterm_aa:
            out.append({"Category":"Resin loading", "Item":cterm_aa, "Solvent":solvent, "Count":copies, "Eq":aa_eq, "Conc_M":"", "Calculated_mL":"", "Actual_mL":"", "MW":_v201_round2(aa_mw) if aa_mw else "manual", "Density":"", "Weight_g":_v201_round2(aa_g), "Volume_mL":"", "Note":"C-terminal loading amino acid"})
        out.append({"Category":"Resin loading", "Item":"DIEA", "Solvent":solvent, "Count":copies, "Eq":diea_eq, "Conc_M":"", "Calculated_mL":_v201_round1(diea_ml), "Actual_mL":_v201_round1(diea_ml), "MW":_v201_round2(diea_mw), "Density":_v201_round2(diea_den), "Weight_g":_v201_round2(diea_g), "Volume_mL":_v201_round1(diea_ml), "Note":"DIEA for resin loading"})
    return pd.DataFrame(out, columns=cols)


