# ======================= V2.0.18 GUI VALUE TYPE + RESIN LOADING VISIBILITY FIX =======================
# Fixes observed runtime error:
#   Invalid value '468.55' for dtype 'str'. Value should be a string or missing value, got 'float' instead.
# Cause: ttk/treeview wrapper rejects raw float values. All tree values must be rendered as strings.
# Also forces the Resin loading mmol/g entry to be visible next to Resin in the editor row.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v218_str(v):
    try:
        if pd.isna(v):
            return ""
    except Exception:
        pass
    if v is None:
        return ""
    if isinstance(v, float):
        # visible but compact; avoids dtype=str errors in Treeview.
        return f"{v:.4f}".rstrip("0").rstrip(".")
    return str(v)

def _v218_write_df_to_tree(self, tree, df):
    cols = list(df.columns) if df is not None and not getattr(df, "empty", True) else ["No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)"]
    cols = [str(c) for c in cols]
    tree.configure(columns=cols, show="headings")
    widths = {
        "No": 50, "Unit name": 245, "MW": 95, "Density(g/mL)": 135,
        "Unit eq": 85, "Unit amount(g)": 125, "Unit volume(mL)": 125,
        "planned_g": 105, "planned_mL": 105, "Note": 260, "note": 260
    }
    for c in cols:
        tree.heading(c, text=str(c))
        tree.column(c, width=widths.get(c, 130), minwidth=55, stretch=False, anchor="w")
    for iid in list(tree.get_children()):
        tree.delete(iid)
    if df is not None and not getattr(df, "empty", True):
        for _, row in df.iterrows():
            vals = [_v218_str(row.get(c, "")) for c in cols]
            tree.insert("", "end", values=vals)
    try:
        _v28_make_tree_editable(self, tree, self._v28_on_selected_result_edit)
    except Exception:
        pass

def _v218_force_resin_loading_editor(self):
    """Keep exactly one visible Resin loading entry next to the Resin combobox."""
    try:
        edit_frame = None
        def walk(w):
            nonlocal edit_frame
            if edit_frame is not None:
                return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Combobox) and str(c.cget("textvariable")) == str(self.pm_resin):
                        edit_frame = c.master
                        return
                except Exception:
                    pass
                walk(c)
        walk(self)
        if edit_frame is None:
            return
        # Hide any old Loading label, then create/grid fixed widgets.
        for c in list(edit_frame.winfo_children()):
            try:
                if isinstance(c, ttk.Label) and str(c.cget("text")).strip() in {"Loading", "Loading rate", "Resin loading"}:
                    c.grid_remove()
                if isinstance(c, ttk.Entry) and str(c.cget("textvariable")) == str(self.pm_loading):
                    c.grid_remove()
            except Exception:
                pass
        ttk.Label(edit_frame, text="Resin loading").grid(row=2, column=4, sticky="w", padx=(2, 4), pady=2)
        ttk.Entry(edit_frame, textvariable=self.pm_loading, width=10).grid(row=2, column=5, sticky="ew", padx=(0, 4), pady=2)
        # Keep mmol/g readable without colliding with Chemistry by placing it above the entry if the row is tight.
        ttk.Label(edit_frame, text="mmol/g").grid(row=3, column=5, sticky="w", padx=(0, 4), pady=(0, 2))
    except Exception:
        pass

