# ======================= V2.0.19 HARD GUI INSERT STRING PATCH =======================
# Runtime error still occurred from an older direct tree.insert path before the V2.0.18 writer.
# This patch hardens the GUI at the widget level: every ttk.Treeview.insert call stringifies values.
# Therefore floats such as 468.55 can no longer trigger "dtype str, got float" anywhere.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v219_stringify_tree_values(values):
    if values is None:
        return values
    try:
        seq = list(values)
    except Exception:
        return values
    out = []
    for v in seq:
        try:
            if pd.isna(v):
                out.append("")
                continue
        except Exception:
            pass
        if v is None:
            out.append("")
        elif isinstance(v, float):
            out.append(f"{v:.4f}".rstrip("0").rstrip("."))
        else:
            out.append(str(v))
    return out

try:
    if not getattr(ttk.Treeview, "_v219_insert_string_patch", False):
        _v219_original_treeview_insert = ttk.Treeview.insert
        def _v219_treeview_insert(self, parent, index, iid=None, **kw):
            if "values" in kw:
                kw["values"] = _v219_stringify_tree_values(kw.get("values"))
            return _v219_original_treeview_insert(self, parent, index, iid=iid, **kw)
        ttk.Treeview.insert = _v219_treeview_insert
        ttk.Treeview._v219_insert_string_patch = True
except Exception:
    pass

def _v219_stringify_df(df):
    try:
        if df is None:
            return df
        out = df.copy()
        for c in out.columns:
            out[c] = out[c].map(_v218_str)
        return out
    except Exception:
        return df

