    if tree is not None:
        mdf = _v217_materials_from_selected_plan(self)
        cols = ["step","material","class","MW","Density(g/mL)","planned_mmol","planned_g","planned_mL","use_count","repeat","phase","note","source"]
        mdf = mdf.reindex(columns=cols) if not mdf.empty else pd.DataFrame(columns=cols)
        _v218_write_df_to_tree(self, tree, _v219_stringify_df(mdf))
    _v217_refresh_totals_from_materials(self)
