def _v220_sanitize_legacy_tree_values(self):
    """Convert the legacy main plan tree rows to strings after rebuild_table."""
    try:
        tree = getattr(self, "tree", None)
        if tree is None:
            return
        cols = list(tree["columns"])
        for iid in tree.get_children():
            vals = list(tree.item(iid, "values"))
            vals += [""] * max(0, len(cols) - len(vals))
            tree.item(iid, values=[_v218_str(v) for v in vals])
    except Exception:
        pass

def _v220_rebuild_base_plan_only(self):
    """Run only the base table build, suppressing legacy output refresh errors."""
    # Temporarily replace refresh_outputs_from_tree so rebuild_table cannot enter the old broken path.
    old_refresh = getattr(self, "refresh_outputs_from_tree", None)
    try:
        self.refresh_outputs_from_tree = lambda *a, **k: None
        self.rebuild_table()
        _v220_sanitize_legacy_tree_values(self)
    finally:
        if old_refresh is not None:
            self.refresh_outputs_from_tree = old_refresh

