# ======================= V2.0.21 REAL FIX: NO FLOAT ASSIGNMENT INTO STRING DTYPE =======================
# Actual root cause of the repeated popup:
#   _v216_enrich_plan_df assigned float MW values (e.g. 610.7) into a DataFrame column
#   that pandas had inferred as string dtype. That raises:
#   "Invalid value '610.7' for dtype 'str'. Value should be a string or missing value, got 'float' instead."
# This version never calls _v216_enrich_plan_df for Project Manager Selected Plan.
# It rebuilds the visible Selected Plan from dictionaries and stores all visible values as strings.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V221_SELECTED_PLAN_COLUMNS = [
    "No", "Unit name", "MW", "Density(g/mL)", "Unit eq", "Unit amount(g)", "Unit volume(mL)",
    "Coupling reagent 1", "Coupling reagent 2 / catalyst", "Coupling base",
    "Coupling cocktail solvent", "Coupling cocktail volume(mL)", "Repeat", "Note"
]

def _v221_lookup_mw_density_text(self, unit_name):
    mw, den = _v216_lookup_mw_density(self, unit_name)
    return _v218_str(mw), _v218_str(den)

def _v221_legacy_plan_rows(self):
    """Read rows from the legacy hidden/base plan tree into ordinary dicts."""
    rows = []
    try:
        tree = getattr(self, "tree", None)
        if tree is None:
            return rows
        cols = list(tree["columns"])
        for iid in tree.get_children():
            vals = list(tree.item(iid, "values"))
            vals += [""] * max(0, len(cols) - len(vals))
            rows.append(dict(zip(cols, vals)))
    except Exception:
        pass
    return rows

def _v221_enriched_selected_plan_df(self):
    try:
        resin = self.pm_resin.get()
    except Exception:
        resin = ""
    out_rows = []
    for r in _v221_legacy_plan_rows(self):
        if not _v216_loading_applies(self, resin) and _v216_is_loading_plan_row(r):
            continue
        unit = str(r.get("Unit name", "") or r.get("unit", "") or "").strip()
        if not unit:
            continue
        mw, den = _v221_lookup_mw_density_text(self, unit)
        row = {c: "" for c in _V221_SELECTED_PLAN_COLUMNS}
        row.update({
            "No": str(len(out_rows) + 1),
            "Unit name": unit,
            "MW": mw,
            "Density(g/mL)": den,
            "Unit eq": _v218_str(r.get("Unit eq", "")),
            "Unit amount(g)": _v218_str(r.get("Unit amount(g)", "")),
            "Unit volume(mL)": _v218_str(r.get("Unit volume(mL)", "")),
            "Coupling reagent 1": _v218_str(r.get("Coupling reagent 1", "")),
            "Coupling reagent 2 / catalyst": _v218_str(r.get("Coupling reagent 2 / catalyst", r.get("Coupling reagent 2", ""))),
            "Coupling base": _v218_str(r.get("Coupling base", "")),
            "Coupling cocktail solvent": _v218_str(r.get("Coupling cocktail solvent", "")),
            "Coupling cocktail volume(mL)": _v218_str(r.get("Coupling cocktail volume(mL)", "")),
            "Repeat": _v218_str(r.get("Repeat", "")),
            "Note": _v218_str(r.get("Note", "")),
        })
        out_rows.append(row)
    return pd.DataFrame(out_rows, columns=_V221_SELECTED_PLAN_COLUMNS, dtype=str)

def _v221_refresh_all_linked_outputs(self, *, apply_overrides=False):
    if apply_overrides:
        _v216_commit_plan_overrides(self)
    df = _v221_enriched_selected_plan_df(self)
    _v218_write_df_to_tree(self, self.pm_selected_plan_tree, df)
    # Materials use selected plan tree, whose values are now strings.
    tree = getattr(self, "pm_selected_material_tree", None)
    if tree is not None:
        mdf = _v217_materials_from_selected_plan(self)
        cols = ["step","material","class","MW","Density(g/mL)","planned_mmol","planned_g","planned_mL","use_count","repeat","phase","note","source"]
        if mdf is None or getattr(mdf, "empty", True):
            mdf = pd.DataFrame(columns=cols, dtype=str)
        else:
            mdf = mdf.reindex(columns=cols)
            for c in mdf.columns:
                mdf[c] = mdf[c].map(_v218_str)
        _v218_write_df_to_tree(self, tree, mdf)
    _v217_refresh_totals_from_materials(self)
    _v217_refresh_selected_checklist(self)
    try:
        self.pm_update_summary()
    except Exception:
        pass
    try:
        self.refresh_batch_workspace_preview()
    except Exception:
        pass
    try:
        self.schedule_autosave()
    except Exception:
        pass

