# ======================= V2.0.24 MINIMAL REQUESTED FEATURE PATCH =======================
# Base: V2.0.21, because user confirmed V2.0.21 normalized the visible Selected Plan.
# Scope intentionally limited to the requested functions:
# 1) Keep Selected Plan MW / Density(g/mL) columns and V2.0.21 display.
# 2) Double-click edit MW / Density(g/mL), then Apply Plan stores material_overrides.
# 3) Autosave/load material_overrides so edits survive restart.
# 4) Apply Plan recalculates Selected Materials and refreshes Batch Manager / Batch Total.
# 5) Remove CTC/Trityl from dropdown; keep 2-CTC and CTC(합성용).
# No pandas DataFrame monkeypatch is used here, to avoid _get_axis_number parse errors.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V224_RESIN_VALUES = [
    "Rink Amide AM", "Rink Amide MBHA", "Rink Amide ChemMatrix", "Rink Amide Tentagel",
    "2-CTC", "CTC(합성용)", "Wang", "HMPB", "Sieber Amide", "PAL resin", "Tentagel", "Manual"
]

def _v224_norm_key(x):
    return re.sub(r"[^0-9a-z가-힣]+", "", str(x or "").lower())

def _v224_normalize_resin_name(name):
    raw = str(name or "").strip()
    n = _v224_norm_key(raw)
    if "합성용" in raw or "합성기" in raw or "preloaded" in n or "synthesizer" in n:
        return "CTC(합성용)"
    if n in {"ctctrityl", "tritylchlorideresin", "2chlorotritylchlorideresin"}:
        return "2-CTC"
    if "2ctc" in n:
        return "2-CTC"
    return raw or "Rink Amide AM"

def _v224_is_preloaded_ctc(name):
    return _v224_normalize_resin_name(name) == "CTC(합성용)"

def _v224_is_direct_loading_resin(name):
    r = _v224_normalize_resin_name(name)
    if r == "CTC(합성용)":
        return False
    if r == "2-CTC":
        return True
    n = _v224_norm_key(r)
    return any(k in n for k in ["wang", "hmpb", "sieber", "palresin"])

def _v224_loading_applies(self, resin_value=None):
    try:
        resin = resin_value if resin_value is not None else self.pm_resin.get()
    except Exception:
        resin = resin_value or ""
    if _v224_is_preloaded_ctc(resin):
        return False
    try:
        checked = bool(getattr(self, "apply_loading_calc").get())
    except Exception:
        checked = False
    return checked and _v224_is_direct_loading_resin(resin)

def _v224_set_resin_dropdowns(self):
    try:
        self.RESIN_VALUES = list(_V224_RESIN_VALUES)
        SPPSGui.RESIN_VALUES = list(_V224_RESIN_VALUES)
    except Exception:
        pass
    for attr in ("pm_resin", "resin"):
        try:
            v = getattr(self, attr)
            v.set(_v224_normalize_resin_name(v.get()))
        except Exception:
            pass
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Combobox):
                        vals = [str(x) for x in (c.cget("values") or [])]
                        joined = "|".join(vals)
                        if any(x in joined for x in ["CTC", "Trityl", "Amide", "Wang", "PAL", "HMPB", "Sieber"]):
                            c.configure(values=list(_V224_RESIN_VALUES))
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v224_get_overrides(self):
    if not hasattr(self, "material_overrides") or self.material_overrides is None:
        self.material_overrides = {}
    return self.material_overrides

def _v224_override_keys(unit):
    unit = str(unit or "").strip()
    keys = {unit, unit.lower(), unit.lower().replace(" ", ""), _v224_norm_key(unit)}
    try:
        m = re.search(r"Fmoc[- ](?:D[- ]?)?([A-Za-z]{3})", unit, flags=re.I)
        tri = {"ala":"A","arg":"R","asn":"N","asp":"D","cys":"C","gln":"Q","glu":"E","gly":"G","his":"H","ile":"I","leu":"L","lys":"K","met":"M","phe":"F","pro":"P","ser":"S","thr":"T","trp":"W","tyr":"Y","val":"V"}
        if m and m.group(1).lower() in tri:
            keys.add(tri[m.group(1).lower()].lower())
    except Exception:
        pass
    return {k for k in keys if k}

def _v224_lookup_mw_density(self, unit_name):
    ov = _v224_get_overrides(self)
    for k in _v224_override_keys(unit_name):
        val = ov.get(k)
        if isinstance(val, dict) and (str(val.get("MW", "")).strip() or str(val.get("density_g_per_mL", val.get("Density(g/mL)", ""))).strip()):
            return _v218_str(val.get("MW", "")), _v218_str(val.get("density_g_per_mL", val.get("Density(g/mL)", "")))
    # Use the V2.0.21 exact lookup implementation if present.
    try:
        return _v216_lookup_mw_density(self, unit_name)
    except RecursionError:
        return "", ""
    except Exception:
        return "", ""

def _v224_commit_plan_overrides(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return 0
    ov = _v224_get_overrides(self)
    cols = list(tree["columns"])
    n = 0
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values"))
        vals += [""] * max(0, len(cols) - len(vals))
        row = dict(zip(cols, vals))
        unit = str(row.get("Unit name", "")).strip()
        if not unit:
            continue
        mw = str(row.get("MW", "")).strip()
        den = str(row.get("Density(g/mL)", "")).strip()
        if not mw and not den:
            continue
        for k in _v224_override_keys(unit):
            ov.setdefault(k, {})
            if mw:
                ov[k]["MW"] = mw
            if den:
                ov[k]["density_g_per_mL"] = den
            n += 1
    return n

def _v224_enriched_selected_plan_df(self):
    # Start from the proven V2.0.21 selected plan dataframe, then replace MW/Density from overrides.
    try:
        df = _v221_enriched_selected_plan_df(self)
    except Exception:
        df = pd.DataFrame(columns=_V221_SELECTED_PLAN_COLUMNS, dtype=str)
    if df is None:
        df = pd.DataFrame(columns=_V221_SELECTED_PLAN_COLUMNS, dtype=str)
    df = df.copy()
    for c in _V221_SELECTED_PLAN_COLUMNS:
        if c not in df.columns:
            df[c] = ""
    # remove loading rows when CTC(합성용) or checkbox OFF
    try:
        resin = self.pm_resin.get()
    except Exception:
        resin = ""
    if not _v224_loading_applies(self, resin):
        keep = []
        for _, r in df.iterrows():
            keep.append(not _v216_is_loading_plan_row(dict(r)))
        df = df[keep].copy()
        if "No" in df.columns:
            df["No"] = [str(i) for i in range(1, len(df) + 1)]
    for i, row in df.iterrows():
        unit = str(row.get("Unit name", "")).strip()
        if unit:
            mw, den = _v224_lookup_mw_density(self, unit)
            df.at[i, "MW"] = _v218_str(mw)
            df.at[i, "Density(g/mL)"] = _v218_str(den)
    return df[_V221_SELECTED_PLAN_COLUMNS].astype(str)

def _v224_materials_from_selected_plan(self):
    rows = _v217_plan_tree_rows(self)
    out = []
    scale = _v217_safe_float(getattr(self, "pm_scale", _v225_const_var("0.2")).get(), 0.2)
    copies = max(int(round(_v217_safe_float(getattr(self, "pm_copies", _v225_const_var("1")).get(), 1))), 1)
    for r in rows:
        unit = str(r.get("Unit name", "")).strip()
        if not unit:
            continue
        mw = str(r.get("MW", "")).strip()
        den = str(r.get("Density(g/mL)", "")).strip()
        if not mw and not den:
            mw, den = _v224_lookup_mw_density(self, unit)
        eq = _v217_safe_float(r.get("Unit eq"), 0.0)
        planned_mmol = scale * copies * eq if eq else 0.0
        planned_g = planned_mmol * _v217_safe_float(mw, 0.0) / 1000.0 if mw not in {"", "N/A"} else 0.0
        planned_mL = planned_g / _v217_safe_float(den, 1.0) if planned_g and den not in {"", "N/A"} and _v217_safe_float(den, 0.0) else 0.0
        out.append({"step": r.get("No", ""), "material": unit, "class": "Selected Plan", "MW": mw, "Density(g/mL)": den,
                    "planned_mmol": _v218_str(round(planned_mmol, 4) if planned_mmol else ""), "planned_g": _v218_str(round(planned_g, 4) if planned_g else ""),
                    "planned_mL": _v218_str(round(planned_mL, 4) if planned_mL else ""), "use_count": _v218_str(copies),
                    "repeat": r.get("Repeat", ""), "phase": "", "note": r.get("Note", "linked from Selected Plan"), "source": "Selected Plan"})
        for col, cls in [("Coupling reagent 1","Coupling reagent"), ("Coupling reagent 2 / catalyst","Catalyst"), ("Coupling base","Base"), ("Coupling cocktail solvent","Solvent")]:
            val = str(r.get(col, "") or "").strip()
            if not val or val.lower() in {"none", "manual", "-"}:
                continue
            mw2, den2 = _v224_lookup_mw_density(self, val)
            out.append({"step": r.get("No", ""), "material": val, "class": cls, "MW": mw2, "Density(g/mL)": den2,
                        "planned_mmol": "", "planned_g": "", "planned_mL": "", "use_count": _v218_str(copies),
                        "repeat": r.get("Repeat", ""), "phase": "", "note": f"linked from Selected Plan column: {col}", "source": "Selected Plan"})
    try:
        resin = _v224_normalize_resin_name(self.pm_resin.get())
        loading = _v217_safe_float(self.pm_loading.get(), 0.0)
        resin_mmol = scale * copies
        resin_g = resin_mmol / loading if loading else 0.0
        out.insert(0, {"step": "resin", "material": resin, "class": "Resin", "MW": "N/A", "Density(g/mL)": "N/A",
                       "planned_mmol": _v218_str(round(resin_mmol, 4)), "planned_g": _v218_str(round(resin_g, 4) if resin_g else ""),
                       "planned_mL": "", "use_count": _v218_str(copies), "repeat": "", "phase": "preloaded/amide-like" if _v224_is_preloaded_ctc(resin) else "resin",
                       "note": "resin_g = scale_mmol × copies / resin_loading_mmol_g", "source": "Project Manager"})
    except Exception:
        pass
    return pd.DataFrame(out)

def _v224_refresh_all_linked_outputs(self, *, apply_overrides=False):
    if apply_overrides:
        _v224_commit_plan_overrides(self)
    df = _v224_enriched_selected_plan_df(self)
    _v218_write_df_to_tree(self, self.pm_selected_plan_tree, df)
    tree = getattr(self, "pm_selected_material_tree", None)
    if tree is not None:
        cols = ["step","material","class","MW","Density(g/mL)","planned_mmol","planned_g","planned_mL","use_count","repeat","phase","note","source"]
        mdf = _v224_materials_from_selected_plan(self)
        if mdf is None or getattr(mdf, "empty", True):
            mdf = pd.DataFrame(columns=cols)
        else:
            mdf = mdf.reindex(columns=cols)
            for c in mdf.columns:
                mdf[c] = mdf[c].map(_v218_str)
        _v218_write_df_to_tree(self, tree, mdf)
    _v217_refresh_totals_from_materials(self)
    _v217_refresh_selected_checklist(self)
    try:
        self.pm_update_summary()
    except Exception:
        pass
    try:
        self.refresh_batch_workspace_preview()
    except Exception:
        pass
    try:
        self.schedule_autosave()
    except Exception:
        pass

def _v224_apply_plan(self):
    try:
        _v224_commit_plan_overrides(self)
        _v224_refresh_all_linked_outputs(self, apply_overrides=False)
        self.save_autosave_state()
    except Exception as e:
        try:
            messagebox.showerror("Apply Plan", str(e))
        except Exception:
            pass

def _v224_pm_generate_selected(self):
    try:
        _v224_set_resin_dropdowns(self)
        item = _v217_save_editor_to_pm_item(self)
        item["resin"] = _v224_normalize_resin_name(item.get("resin", ""))
        self.pm_apply_item_to_single_plan(item)
        _v220_rebuild_base_plan_only(self)
        _v218_force_resin_loading_editor(self)
        _v224_refresh_all_linked_outputs(self, apply_overrides=False)
        try:
            idx = self.pm_current_index()
            if idx is not None:
                self.pm_items[idx]["status"] = "Calculated"
            self.pm_refresh_list()
        except Exception:
            pass
    except Exception as e:
        try:
            messagebox.showerror("Project Manager", str(e))
        except Exception:
            pass

