def _v224_build(self):
    if _v224_old_build:
        _v224_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        _v224_set_resin_dropdowns(self)
        if hasattr(self, "pm_selected_plan_tree"):
            self.pm_selected_plan_tree.configure(columns=_V221_SELECTED_PLAN_COLUMNS, show="headings")
            for c in _V221_SELECTED_PLAN_COLUMNS:
                self.pm_selected_plan_tree.heading(c, text=c)
                self.pm_selected_plan_tree.column(c, width=145 if c not in {"No","Unit eq","MW"} else 75, anchor="w", stretch=False)
        _v218_force_resin_loading_editor(self)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v224_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

