# ======================= V2.0.25 SYNTHESIS ORDER + FULL MATERIAL VISIBILITY PATCH =======================
# User corrections:
# - CTC(합성용) remains only as record label. Treat it like Amide/preloaded except resin family notes.
# - For entered elongation sequence AEKIRKELEKQ, first synthesis unit must be Q.
# - Selected Plan / Selected Materials must show HBTU/HOBt/DIC/DIEA eq, mmol, g/mL where applicable.
# - DMF/DCM/NMP and other solvents must show planned mL.
# - Cleavage cocktail recommendation must be visible again: Ac-EEMQRR-NH2 amide resin uses 30 eq TFA rule.
# - Keep V2.0.21 selected plan display stability and V2.0.24 Apply Plan persistence.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V225_AA_FULL = {
    "A":"Ala", "R":"Arg", "N":"Asn", "D":"Asp", "C":"Cys", "Q":"Gln", "E":"Glu", "G":"Gly",
    "H":"His", "I":"Ile", "L":"Leu", "K":"Lys", "M":"Met", "F":"Phe", "P":"Pro", "S":"Ser",
    "T":"Thr", "W":"Trp", "Y":"Tyr", "V":"Val"
}
_V225_PROTECTED = {
    "A":"Fmoc-Ala-OH", "R":"Fmoc-Arg(Pbf)-OH", "N":"Fmoc-Asn(Trt)-OH", "D":"Fmoc-Asp(OtBu)-OH",
    "C":"Fmoc-Cys(Trt)-OH", "Q":"Fmoc-Gln(Trt)-OH", "E":"Fmoc-Glu(OtBu)-OH", "G":"Fmoc-Gly-OH",
    "H":"Fmoc-His(Trt)-OH", "I":"Fmoc-Ile-OH", "L":"Fmoc-Leu-OH", "K":"Fmoc-Lys(Boc)-OH",
    "M":"Fmoc-Met-OH", "F":"Fmoc-Phe-OH", "P":"Fmoc-Pro-OH", "S":"Fmoc-Ser(tBu)-OH",
    "T":"Fmoc-Thr(tBu)-OH", "W":"Fmoc-Trp(Boc)-OH", "Y":"Fmoc-Tyr(tBu)-OH", "V":"Fmoc-Val-OH"
}

def _v225_sequence_tokens_ntoc(self):
    try:
        seq = self.pm_sequence.get()
    except Exception:
        try:
            seq = self.seq.get()
        except Exception:
            seq = ""
    try:
        return [str(x) for x in self._aa_letters_from_sequence(seq)]
    except Exception:
        return []

def _v225_unit_name(tok):
    t = str(tok or "").strip()
    if len(t) == 1 and t.upper() in _V225_PROTECTED:
        return _V225_PROTECTED[t.upper()]
    # Already named nonnatural/D form; leave readable.
    if t.startswith("D-"):
        base = t[2:]
        return f"Fmoc-D-{base}-OH"
    return f"Fmoc-{t}-OH"

def _v225_selected_plan_from_sequence(self):
    """Build stable Selected Plan directly from entered sequence, C-terminus to N-terminus."""
    tokens = _v225_sequence_tokens_ntoc(self)
    # SPPS coupling order is C -> N, so reverse the typed N -> C sequence.
    synth_tokens = list(reversed(tokens))
    rows = []
    try:
        resin = self.pm_resin.get()
    except Exception:
        resin = ""
    loading_applies = _v224_loading_applies(self, resin) if "_v224_loading_applies" in globals() else False
    chem = ""
    try:
        chem = self.pm_chemistry.get()
    except Exception:
        pass
    if "HBTU" in str(chem).upper():
        reagent1, reagent2, base, solvent = "HBTU", "HOBt", "", "NMP"
        default_eq = 10
        try:
            self.default_reagent.set("HBTU"); self.default_catalyst.set("HOBt"); self.default_coupling_solution_solvent.set("NMP")
        except Exception:
            pass
    else:
        reagent1, reagent2, base, solvent = "DIC", "HOBt", "", "DMF"
        default_eq = 10
    for idx, tok in enumerate(synth_tokens, start=1):
        unit = _v225_unit_name(tok)
        if idx == 1 and loading_applies:
            unit_eq = _v218_str(getattr(self, "loading_aa_eq", _v225_const_var("2")).get())
            row_base = "DIEA"
            row_reagent1 = ""
            row_reagent2 = ""
            row_solvent = "90% DCM / 10% DMF"
        else:
            unit_eq = _v218_str(default_eq)
            row_base = base
            row_reagent1 = reagent1
            row_reagent2 = reagent2
            row_solvent = solvent
        mw, den = _v224_lookup_mw_density(self, unit) if "_v224_lookup_mw_density" in globals() else ("","")
        scale = _v217_safe_float(getattr(self, "pm_scale", _v225_const_var("0.2")).get(), 0.2)
        copies = max(int(round(_v217_safe_float(getattr(self, "pm_copies", _v225_const_var("1")).get(), 1))), 1)
        mmol = scale * copies * _v217_safe_float(unit_eq, 0)
        amt_g = mmol * _v217_safe_float(mw, 0) / 1000.0 if mw else 0
        rows.append({
            "No": str(len(rows)+1), "Unit name": unit, "MW": _v218_str(mw), "Density(g/mL)": _v218_str(den),
            "Unit eq": _v218_str(unit_eq), "Unit amount(g)": _v218_str(round(amt_g,4) if amt_g else ""),
            "Unit volume(mL)": "", "Coupling reagent 1": row_reagent1, "Coupling reagent 2 / catalyst": row_reagent2,
            "Coupling base": row_base, "Coupling cocktail solvent": row_solvent, "Coupling cocktail volume(mL)": _v218_str(scale * _v217_safe_float(getattr(self, "ml_per_mmol", _v225_const_var("10")).get(), 10)),
            "Repeat": "1", "Note": "direct loading first unit" if idx == 1 and loading_applies else "Regular AA coupling"
        })
    # N-term Ac cap, if typed sequence has Ac-
    try:
        has_ac = self._sequence_has_nterm_ac(self.pm_sequence.get())
    except Exception:
        has_ac = False
    if has_ac:
        mw, den = _v224_lookup_mw_density(self, "Acetic anhydride (Ac2O)") if "_v224_lookup_mw_density" in globals() else ("102.09","1.08")
        scale = _v217_safe_float(getattr(self, "pm_scale", _v225_const_var("0.2")).get(), 0.2)
        copies = max(int(round(_v217_safe_float(getattr(self, "pm_copies", _v225_const_var("1")).get(), 1))), 1)
        eq = _v217_safe_float(getattr(self, "modifier_eq", _v225_const_var("3")).get(), 3)
        mmol = scale * copies * eq
        g = mmol * _v217_safe_float(mw,0) / 1000
        ml = g / _v217_safe_float(den,1) if den else 0
        rows.append({"No": str(len(rows)+1), "Unit name": "Acetic anhydride (Ac2O) for N-terminal acetylation", "MW": _v218_str(mw), "Density(g/mL)": _v218_str(den),
                     "Unit eq": _v218_str(eq), "Unit amount(g)": _v218_str(round(g,4)), "Unit volume(mL)": _v218_str(round(ml,4)), "Coupling reagent 1": "", "Coupling reagent 2 / catalyst": "",
                     "Coupling base": "DIEA", "Coupling cocktail solvent": "DMF", "Coupling cocktail volume(mL)": _v218_str(scale * _v217_safe_float(getattr(self, "ml_per_mmol", _v225_const_var("10")).get(), 10)),
                     "Repeat": "1", "Note": "N-terminal Ac cap"})
    return pd.DataFrame(rows, columns=_V221_SELECTED_PLAN_COLUMNS).astype(str)

def _v225_enriched_selected_plan_df(self):
    # Prefer explicit sequence-built Selected Plan so CTC(합성용) starts at C-terminal Q.
    return _v225_selected_plan_from_sequence(self)

def _v225_add_material(out, material, cls, eq="", mmol="", g="", ml="", count="", source="", note=""):
    if not str(material or "").strip():
        return
    out.append({
        "step": "", "material": str(material), "class": cls,
        "MW": "", "Density(g/mL)": "", "Eq": _v218_str(eq), "planned_mmol": _v218_str(mmol),
        "planned_g": _v218_str(g), "planned_mL": _v218_str(ml), "use_count": _v218_str(count),
        "repeat": "", "phase": "", "note": note, "source": source
    })

def _v225_materials_from_selected_plan(self):
    rows = _v217_plan_tree_rows(self)
    out = []
    scale = _v217_safe_float(getattr(self, "pm_scale", _v225_const_var("0.2")).get(), 0.2)
    copies = max(int(round(_v217_safe_float(getattr(self, "pm_copies", _v225_const_var("1")).get(), 1))), 1)
    per_use_ml = scale * _v217_safe_float(getattr(self, "ml_per_mmol", _v225_const_var("10")).get(), 10)
    # resin row
    try:
        resin = _v224_normalize_resin_name(self.pm_resin.get()) if "_v224_normalize_resin_name" in globals() else self.pm_resin.get()
        loading = _v217_safe_float(self.pm_loading.get(), 0.0)
        resin_mmol = scale * copies
        resin_g = resin_mmol / loading if loading else 0.0
        _v225_add_material(out, resin, "Resin", eq=1, mmol=round(resin_mmol,4), g=round(resin_g,4) if resin_g else "", count=copies, source="Project Manager", note="resin_g = scale_mmol × copies / resin_loading_mmol_g")
    except Exception:
        pass
    for r in rows:
        unit = str(r.get("Unit name","")).strip()
        if not unit:
            continue
        eq = _v217_safe_float(r.get("Unit eq"), 0)
        mmol = scale * copies * eq
        mw = str(r.get("MW","")).strip()
        den = str(r.get("Density(g/mL)","")).strip()
        if not mw and "_v224_lookup_mw_density" in globals():
            mw, den = _v224_lookup_mw_density(self, unit)
        g = mmol * _v217_safe_float(mw,0)/1000 if mw not in {"","N/A"} else 0
        ml = g / _v217_safe_float(den,1) if g and den not in {"","N/A"} and _v217_safe_float(den,0) else 0
        _v225_add_material(out, unit, "AA/Chemical", eq=eq, mmol=round(mmol,4), g=round(g,4) if g else "", ml=round(ml,4) if ml else "", count=copies, source="Selected Plan", note=r.get("Note",""))
        # coupling reagent 1/2/base with eq/mmol/g/mL
        for col, eq_col, cls in [("Coupling reagent 1","Coupling reagent 1 eq","Coupling reagent"), ("Coupling reagent 2 / catalyst","Coupling reagent 2 / catalyst eq","Catalyst"), ("Coupling base","Coupling base eq","Base")]:
            name = str(r.get(col,"")).strip()
            if not name:
                continue
            req = _v217_safe_float(r.get(eq_col), 0)
            if req <= 0:
                if name.upper() in {"HBTU","DIC","HOBT"}:
                    req = eq
                elif name.upper() in {"DIEA","DIPEA"}:
                    req = _v217_safe_float(getattr(self, "default_base_eq", _v225_const_var("5")).get(), 5)
            rmmol = scale * copies * req
            mw2, den2 = _v224_lookup_mw_density(self, name) if "_v224_lookup_mw_density" in globals() else ("","")
            rg = rmmol * _v217_safe_float(mw2,0)/1000 if mw2 else 0
            rml = rg / _v217_safe_float(den2,1) if rg and den2 and _v217_safe_float(den2,0) else 0
            rec = {"step": r.get("No",""), "material": name, "class": cls, "MW": _v218_str(mw2), "Density(g/mL)": _v218_str(den2),
                   "Eq": _v218_str(req), "planned_mmol": _v218_str(round(rmmol,4) if rmmol else ""), "planned_g": _v218_str(round(rg,4) if rg else ""),
                   "planned_mL": _v218_str(round(rml,4) if rml else ""), "use_count": _v218_str(copies), "repeat": r.get("Repeat",""), "phase": "", "note": f"{col} for step {r.get('No','')}", "source": "Selected Plan"}
            out.append(rec)
        # coupling solvent and split solvents
        solv = str(r.get("Coupling cocktail solvent","")).strip()
        vol = _v217_safe_float(r.get("Coupling cocktail volume(mL)"), per_use_ml) * copies
        if solv and vol:
            try:
                splits = self._split_solution_name(solv, vol)
            except Exception:
                splits = [(solv, vol, "")]
            for sname, sml, snote in splits:
                rec = {"step": r.get("No",""), "material": sname, "class": "Solvent", "MW": "", "Density(g/mL)": "", "Eq": "",
                       "planned_mmol": "", "planned_g": "", "planned_mL": _v218_str(round(_v217_safe_float(sml,0),4)), "use_count": _v218_str(copies), "repeat": r.get("Repeat",""), "phase": "coupling solvent", "note": snote or f"{solv} for step {r.get('No','')}", "source": "Selected Plan"}
                out.append(rec)
    # cleavage cocktail recommendation
    try:
        cdf = _v225_cleavage_recommendation_df(self)
        for _, cr in cdf.iterrows():
            out.append({"step": "cleavage", "material": cr.get("component",""), "class": "Cleavage cocktail", "MW": "", "Density(g/mL)": "", "Eq": cr.get("equiv",""),
                        "planned_mmol": cr.get("estimated_mmol",""), "planned_g": "", "planned_mL": cr.get("estimated_mL",""), "use_count": "1", "repeat": "", "phase": "cleavage", "note": cr.get("note",""), "source": "Cleavage recommendation"})
    except Exception:
        pass
    return pd.DataFrame(out)

def _v225_cleavage_recommendation_df(self):
    scale = _v217_safe_float(getattr(self, "pm_scale", _v225_const_var("0.2")).get(), 0.2)
    try:
        seq = self.pm_sequence.get()
    except Exception:
        seq = ""
    aa_count = len(_v225_sequence_tokens_ntoc(self))
    cys_count = sum(1 for x in _v225_sequence_tokens_ntoc(self) if str(x).upper()=="C")
    # User rule: STD Ac-EEMQRR-NH2 / amide scale 기준 30 eq; 15mer 80eq, 22mer 100eq, +100eq/Cys.
    if aa_count >= 22:
        eq = 100
    elif aa_count >= 15:
        eq = 80
    else:
        eq = 30
    eq += 100 * cys_count
    mmol = scale * eq
    # TFA equivalent volume using MW/density only for practical estimate.
    tfa_ml = (mmol * 114.02 / 1000.0) / 1.489 if mmol else 0
    return pd.DataFrame([
        {"component":"TFA", "equiv":eq, "estimated_mmol":round(mmol,4), "estimated_mL":round(tfa_ml,4), "note":"Cleavage cocktail recommendation: STD short peptide uses 30 eq; 15mer 80 eq; 22mer 100 eq; +100 eq per Cys"},
        {"component":"TIS", "equiv":"editable", "estimated_mmol":"", "estimated_mL":"", "note":"scavenger; fill according to SOP"},
        {"component":"Water", "equiv":"editable", "estimated_mmol":"", "estimated_mL":"", "note":"scavenger; fill according to SOP"},
    ])

def _v225_refresh_all_linked_outputs(self, *, apply_overrides=False):
    if apply_overrides and "_v224_commit_plan_overrides" in globals():
        _v224_commit_plan_overrides(self)
    df = _v225_enriched_selected_plan_df(self)
    _v218_write_df_to_tree(self, self.pm_selected_plan_tree, df)
    tree = getattr(self, "pm_selected_material_tree", None)
    if tree is not None:
        cols = ["step","material","class","MW","Density(g/mL)","Eq","planned_mmol","planned_g","planned_mL","use_count","repeat","phase","note","source"]
        mdf = _v225_materials_from_selected_plan(self)
        if mdf is None or getattr(mdf,"empty",True):
            mdf = pd.DataFrame(columns=cols)
        else:
            mdf = mdf.reindex(columns=cols)
            for c in mdf.columns:
                mdf[c] = mdf[c].map(_v218_str)
        _v218_write_df_to_tree(self, tree, mdf)
    _v217_refresh_totals_from_materials(self)
    _v217_refresh_selected_checklist(self)
    try:
        self.pm_update_summary()
    except Exception:
        pass
    try:
        self.refresh_batch_workspace_preview()
    except Exception:
        pass
    try:
        self.schedule_autosave()
    except Exception:
        pass

def _v225_pm_generate_selected(self):
    try:
        if "_v224_set_resin_dropdowns" in globals():
            _v224_set_resin_dropdowns(self)
        item = _v217_save_editor_to_pm_item(self)
        if "_v224_normalize_resin_name" in globals():
            item["resin"] = _v224_normalize_resin_name(item.get("resin",""))
        self.pm_apply_item_to_single_plan(item)
        # legacy table still generated in the background for checklist compatibility, but visible selected plan is sequence-built.
        try:
            _v220_rebuild_base_plan_only(self)
        except Exception:
            pass
        _v218_force_resin_loading_editor(self)
        _v225_refresh_all_linked_outputs(self, apply_overrides=False)
        try:
            idx = self.pm_current_index()
            if idx is not None:
                self.pm_items[idx]["status"] = "Calculated"
            self.pm_refresh_list()
        except Exception:
            pass
    except Exception as e:
        try:
            messagebox.showerror("Project Manager", str(e))
        except Exception:
            pass

def _v225_apply_plan(self):
    try:
        if "_v224_commit_plan_overrides" in globals():
            _v224_commit_plan_overrides(self)
        _v225_refresh_all_linked_outputs(self, apply_overrides=False)
        self.save_autosave_state()
    except Exception as e:
        try:
            messagebox.showerror("Apply Plan", str(e))
        except Exception:
            pass

try:
    _v225_old_build = SPPSGui._build
except Exception:
    _v225_old_build = None

def _v225_build(self):
    if _v225_old_build:
        _v225_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v225_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

# Final bindings
_v224_enriched_selected_plan_df = _v225_enriched_selected_plan_df
_v224_materials_from_selected_plan = _v225_materials_from_selected_plan
_v224_refresh_all_linked_outputs = _v225_refresh_all_linked_outputs
SPPSGui.pm_generate_selected = _v225_pm_generate_selected
