# ======================= V2.0.30 COMPACT DISPLAY + SOLVENT/WASH/PRESET PATCH =======================
# Based on V2.0.29.
# - Combine eq and mmol display: "10 eq / 200 mmol"
# - For amount display: liquid -> mL only, solid -> g only
# - Keep MW/Density(g/mL) visible as preset columns
# - Integrate range/coupling rule controls into Unit defaults and Reagents tabs; remove standalone tab from view when found
# - Add separate checkboxes for unit rules and reagent/catalyst coupled rules
# - Fix labels: Scale(mmol), Resin loading (mmol/g), ensure editable resin loading entry
# - Add wash solvent reservoir rule: 2-CTC/direct CTC = scale*5 mL, Amide/preloaded/CTC(합성용)=scale*10 mL
# - HBTU/NMP solution prep: HBTU/NMP is diluted in DMF; NMP is 0.8 M in DMF-based solution.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V230_PLAN_COLS = [
    "No","Unit name","MW","Density(g/mL)","Unit eq/mmol","Unit amount",
    "Coupling reagent 1","Reagent 1 eq/mmol","Reagent 1 amount",
    "Coupling reagent 2","Reagent 2 eq/mmol","Reagent 2 amount",
    "Coupling base","Base eq/mmol","Base amount",
    "Coupling cocktail solvent","Solvent mL","Repeat","Note"
]
_V230_MAT_COLS = ["step","material","class","MW","Density(g/mL)","Eq/mmol","Amount","use_count","repeat","phase","note","source"]
_V230_TOTAL_COLS = ["material","class","MW","Density(g/mL)","total mmol","total amount","use_count","note"]

def _v230_is_liquid_name(name, density=""):
    n = str(name or "").strip()
    if str(density or "").strip() and n not in {"HOBt", "HBTU"}:
        return True
    return n.upper() in {"DIEA","DIPEA","DMF","DCM","NMP","TFA","TIS","WATER","AC2O"} or "anhydride" in n.lower()

def _v230_eqmmol(eq, mmol):
    eqs = _v228_s(eq) if "_v228_s" in globals() else str(eq or "")
    mm = _v228_s(round(_v228_f(mmol,0),4) if "_v228_f" in globals() else mmol)
    if eqs and mm:
        return f"{eqs} eq / {mm} mmol"
    return eqs or mm

def _v230_amount(name, g="", ml="", density=""):
    if _v230_is_liquid_name(name, density):
        return (f"{_v228_s(ml)} mL" if str(ml).strip() else "")
    return (f"{_v228_s(g)} g" if str(g).strip() else "")

def _v230_force_labels_and_resin_loading(self):
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label):
                        t = str(c.cget("text"))
                        if t == "Scale mmol":
                            c.configure(text="Scale(mmol)")
                        elif t == "Resin loading":
                            c.configure(text="Resin loading (mmol/g)")
                    # ensure pm_loading entry is visible and editable
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass
    try:
        # Find Resin combobox master and create/replace label/entry next to it.
        parent = None
        def find_parent(w):
            nonlocal parent
            if parent is not None:
                return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Combobox) and str(c.cget("textvariable")) == str(self.pm_resin):
                        parent = c.master
                        return
                except Exception:
                    pass
                find_parent(c)
        find_parent(self)
        if parent is not None and hasattr(self, "pm_loading"):
            # Do not destroy old widgets; just place a reliable pair in the known grid area.
            ttk.Label(parent, text="Resin loading (mmol/g)").grid(row=2, column=4, sticky="w", padx=(2,4), pady=2)
            ttk.Entry(parent, textvariable=self.pm_loading, width=12).grid(row=2, column=5, sticky="ew", padx=(0,4), pady=2)
    except Exception:
        pass

def _v230_integrate_rules_tabs(self):
    # Variables: unit checkbox controls AA/repeat ranges. reagent checkbox ties reagent/catalyst eq to unit range.
    if not hasattr(self, "unit_rule_enable"):
        self.unit_rule_enable = tk.BooleanVar(value=False)
    if not hasattr(self, "reagent_rule_enable"):
        self.reagent_rule_enable = tk.BooleanVar(value=False)
    if not hasattr(self, "rule_eq_rules"):
        self.rule_eq_rules = tk.StringVar(value="")
    if not hasattr(self, "rule_repeat_rules"):
        self.rule_repeat_rules = tk.StringVar(value="")
    # Keep old v228 checkbox in sync for old helpers.
    if not hasattr(self, "rule_enable"):
        self.rule_enable = tk.BooleanVar(value=False)
    try:
        self.rule_enable.set(bool(self.unit_rule_enable.get() or self.reagent_rule_enable.get()))
    except Exception:
        pass
    try:
        nb = None
        def walk(w):
            nonlocal nb
            if nb is not None:
                return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Notebook):
                        texts = [str(c.tab(t, "text")) for t in c.tabs()]
                        if "Unit defaults" in texts and "Reagents" in texts:
                            nb = c
                            return
                except Exception:
                    pass
                walk(c)
        walk(self)
        if nb is None:
            return
        # remove standalone Range tab because controls are integrated.
        for tab_id in list(nb.tabs()):
            try:
                if str(nb.tab(tab_id, "text")) == "Range / Coupling Rules":
                    nb.forget(tab_id)
            except Exception:
                pass
        unit_fr = None; reagent_fr = None
        for tab_id in nb.tabs():
            text = str(nb.tab(tab_id, "text"))
            if text == "Unit defaults":
                unit_fr = nb.nametowidget(tab_id)
            elif text == "Reagents":
                reagent_fr = nb.nametowidget(tab_id)
        if unit_fr is not None and not hasattr(self, "_v230_unit_rules_added"):
            self._v230_unit_rules_added = True
            row = 20
            ttk.Separator(unit_fr, orient="horizontal").grid(row=row, column=0, columnspan=6, sticky="ew", pady=(10,4)); row += 1
            ttk.Checkbutton(unit_fr, text="Use range eq/repeat rules for AA units", variable=self.unit_rule_enable).grid(row=row, column=0, columnspan=3, sticky="w", padx=8, pady=2); row += 1
            ttk.Label(unit_fr, text="AA eq range").grid(row=row, column=0, sticky="w", padx=8, pady=2)
            ttk.Entry(unit_fr, textvariable=self.rule_eq_rules, width=32).grid(row=row, column=1, sticky="ew", padx=4, pady=2)
            ttk.Label(unit_fr, text="ex) 2-10:3, 11-20:5").grid(row=row, column=2, sticky="w", padx=4, pady=2); row += 1
            ttk.Label(unit_fr, text="AA repeat/doubling range").grid(row=row, column=0, sticky="w", padx=8, pady=2)
            ttk.Entry(unit_fr, textvariable=self.rule_repeat_rules, width=32).grid(row=row, column=1, sticky="ew", padx=4, pady=2)
            ttk.Label(unit_fr, text="ex) 18-25:2").grid(row=row, column=2, sticky="w", padx=4, pady=2)
        if reagent_fr is not None and not hasattr(self, "_v230_reagent_rules_added"):
            self._v230_reagent_rules_added = True
            row = 20
            ttk.Separator(reagent_fr, orient="horizontal").grid(row=row, column=0, columnspan=6, sticky="ew", pady=(10,4)); row += 1
            ttk.Checkbutton(reagent_fr, text="Tie reagent/catalyst eq to AA range eq", variable=self.reagent_rule_enable).grid(row=row, column=0, columnspan=4, sticky="w", padx=8, pady=2); row += 1
            ttk.Label(reagent_fr, text="Uses Unit defaults AA eq range").grid(row=row, column=0, sticky="w", padx=8, pady=2)
            ttk.Entry(reagent_fr, textvariable=self.rule_eq_rules, width=32).grid(row=row, column=1, sticky="ew", padx=4, pady=2)
            ttk.Label(reagent_fr, text="same range controls as AA").grid(row=row, column=2, sticky="w", padx=4, pady=2); row += 1
            ttk.Label(reagent_fr, text="Reagent repeat follows AA repeat").grid(row=row, column=0, sticky="w", padx=8, pady=2)
            ttk.Entry(reagent_fr, textvariable=self.rule_repeat_rules, width=32).grid(row=row, column=1, sticky="ew", padx=4, pady=2)
    except Exception:
        pass

def _v230_rule_eq(self, step, default):
    try:
        enabled = bool(self.unit_rule_enable.get())
    except Exception:
        enabled = False
    if not enabled:
        return default
    try:
        st = int(float(step))
        for a,b,val in _v228_parse_range_rules(self.rule_eq_rules.get()):
            if a <= st <= b:
                return val
    except Exception:
        pass
    return default

def _v230_rule_repeat(self, step, default=1):
    try:
        enabled = bool(self.unit_rule_enable.get())
    except Exception:
        enabled = False
    if not enabled:
        return default
    try:
        st = int(float(step))
        for a,b,val in _v228_parse_range_rules(self.rule_repeat_rules.get()):
            if a <= st <= b:
                return max(1, int(round(val)))
    except Exception:
        pass
    return default

def _v230_reagent_eq(self, step, default):
    try:
        enabled = bool(self.reagent_rule_enable.get())
    except Exception:
        enabled = False
    if not enabled:
        return default
    return _v230_rule_eq(self, step, default)

def _v230_plan_detailed(self):
    # Use v229 detailed plan then normalize rule checkboxes and ensure compact-friendly data.
    try:
        base = _v229_plan_df(self).copy()
    except Exception:
        base = pd.DataFrame(columns=_V229_PLAN_COLS if "_V229_PLAN_COLS" in globals() else [])
    scale = _v228_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2)
    copies = max(int(round(_v228_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))), 1)
    # Recalculate unit/reagent/base if the integrated checkboxes changed.
    for i, r in base.iterrows():
        step = r.get("No","")
        note = str(r.get("Note","")).lower()
        if "direct loading" not in note and "Acetic anhydride" not in str(r.get("Unit name","")):
            old_eq = _v228_f(r.get("Unit eq"), 0)
            new_eq = _v230_rule_eq(self, step, old_eq)
            repeat = _v230_rule_repeat(self, step, _v228_f(r.get("Repeat"), 1))
            base.at[i, "Unit eq"] = _v228_s(new_eq)
            base.at[i, "Repeat"] = _v228_s(repeat)
            mw = _v228_f(r.get("MW"), 0)
            base.at[i, "Unit amount(g)"] = _v228_s(round(scale*copies*new_eq*repeat*mw/1000.0,4) if mw else "")
        # reagent/base amount recalc
        repeat = max(int(round(_v228_f(base.at[i, "Repeat"], 1))), 1)
        unit_eq = _v228_f(base.at[i, "Unit eq"], 0)
        for prefix, name_col in [("Reagent 1", "Coupling reagent 1"), ("Reagent 2", "Coupling reagent 2 / catalyst"), ("Base", "Coupling base")]:
            name = str(base.at[i, name_col]) if name_col in base.columns else ""
            if not name:
                continue
            if prefix == "Base" and "direct loading" in note:
                eq = _v228_f(getattr(self, "loading_diea_eq", _v225_const_var("4")).get(), 4)
            elif prefix == "Base":
                eq = _v230_reagent_eq(self, step, unit_eq)
            else:
                eq = _v230_reagent_eq(self, step, unit_eq)
            eq_s, mmol_s, g_s, ml_s, _ = _v229_calc_reagent_amount(self, name, eq, scale, copies, repeat)
            base.at[i, f"{prefix} eq"] = eq_s
            base.at[i, f"{prefix} mmol"] = mmol_s
            base.at[i, f"{prefix} g"] = g_s
            base.at[i, f"{prefix} mL"] = ml_s
    return base.astype(str)

def _v230_plan_display_df(self):
    base = _v230_plan_detailed(self)
    rows = []
    for _, r in base.iterrows():
        unit_mmol = _v228_f(r.get("Unit eq"),0) * _v228_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0,0) * _v228_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1,1) * max(int(round(_v228_f(r.get("Repeat"),1))),1)
        unit_amt = _v230_amount(r.get("Unit name",""), r.get("Unit amount(g)",""), r.get("Unit volume(mL)",""), r.get("Density(g/mL)",""))
        row = {
            "No": r.get("No",""), "Unit name": r.get("Unit name",""), "MW": r.get("MW",""), "Density(g/mL)": r.get("Density(g/mL)",""),
            "Unit eq/mmol": _v230_eqmmol(r.get("Unit eq",""), unit_mmol), "Unit amount": unit_amt,
            "Coupling reagent 1": r.get("Coupling reagent 1",""),
            "Reagent 1 eq/mmol": _v230_eqmmol(r.get("Reagent 1 eq",""), r.get("Reagent 1 mmol","")),
            "Reagent 1 amount": _v230_amount(r.get("Coupling reagent 1",""), r.get("Reagent 1 g",""), r.get("Reagent 1 mL",""), _v228_lookup(self, r.get("Coupling reagent 1",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling reagent 2": r.get("Coupling reagent 2 / catalyst",""),
            "Reagent 2 eq/mmol": _v230_eqmmol(r.get("Reagent 2 eq",""), r.get("Reagent 2 mmol","")),
            "Reagent 2 amount": _v230_amount(r.get("Coupling reagent 2 / catalyst",""), r.get("Reagent 2 g",""), r.get("Reagent 2 mL",""), _v228_lookup(self, r.get("Coupling reagent 2 / catalyst",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling base": r.get("Coupling base",""),
            "Base eq/mmol": _v230_eqmmol(r.get("Base eq",""), r.get("Base mmol","")),
            "Base amount": _v230_amount(r.get("Coupling base",""), r.get("Base g",""), r.get("Base mL",""), _v228_lookup(self, r.get("Coupling base",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling cocktail solvent": r.get("Coupling cocktail solvent",""),
            "Solvent mL": r.get("Coupling cocktail volume(mL)",""),
            "Repeat": r.get("Repeat",""), "Note": r.get("Note","")
        }
        rows.append(row)
    return pd.DataFrame(rows, columns=_V230_PLAN_COLS).astype(str)

def _v230_wash_rows(self):
    out = []
    scale = _v228_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2)
    copies = max(int(round(_v228_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))), 1)
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self, "pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    direct_ctc = (resin == "2-CTC")
    factor = 5 if direct_ctc else 10
    mL = scale * copies * factor
    for solv in ["DMF", "DCM"]:
        mw, den = _v228_lookup(self, solv) if "_v228_lookup" in globals() else ("","")
        out.append({"step":"wash","material":solv,"class":"Wash solvent reservoir","MW":mw,"Density(g/mL)":den,"Eq/mmol":"",
                    "Amount":f"{_v228_s(round(mL,4))} mL","_mmol":0.0,"_g":0.0,"_mL":mL,
                    "use_count":_v228_s(copies),"repeat":"","phase":"wash reservoir","note":f"{resin}: scale × {factor} mL rule","source":"Solvent/Wash rule"})
    return out

def _v230_materials_detailed(self):
    # Build from detailed plan, not compact display.
    plan = _v230_plan_detailed(self)
    out = []
    scale = _v228_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2)
    copies = max(int(round(_v228_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))), 1)
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self, "pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    loading = _v228_f(self.pm_loading.get() if hasattr(self, "pm_loading") else 0, 0)
    resin_g = scale * copies / loading if loading else 0
    out.append({"step":"resin","material":resin,"class":"Resin","MW":"N/A","Density(g/mL)":"N/A","Eq/mmol":_v230_eqmmol(1, scale*copies),
                "Amount":f"{_v228_s(round(resin_g,4))} g" if resin_g else "", "_mmol":scale*copies, "_g":resin_g, "_mL":0.0,
                "use_count":_v228_s(copies),"repeat":"","phase":"resin","note":"resin_g = scale_mmol × copies / resin_loading_mmol_g","source":"Project Manager"})
    for _, r in plan.iterrows():
        step = r.get("No","")
        rep = max(int(round(_v228_f(r.get("Repeat"),1))),1)
        unit = str(r.get("Unit name",""))
        eq = _v228_f(r.get("Unit eq"),0)
        unit_mmol = scale * copies * eq * rep
        g = _v228_f(r.get("Unit amount(g)"),0)
        ml = _v228_f(r.get("Unit volume(mL)"),0)
        amount = _v230_amount(unit, g, ml, r.get("Density(g/mL)",""))
        out.append({"step":step,"material":unit,"class":"AA/Chemical","MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                    "Eq/mmol":_v230_eqmmol(eq, unit_mmol),"Amount":amount,"_mmol":unit_mmol,"_g":g,"_mL":ml,
                    "use_count":_v228_s(copies),"repeat":_v228_s(rep),"phase":"coupling","note":r.get("Note",""),"source":"Selected Plan"})
        for name_col, prefix, cls in [("Coupling reagent 1","Reagent 1","Coupling reagent"),("Coupling reagent 2 / catalyst","Reagent 2","Catalyst/additive"),("Coupling base","Base","Base")]:
            name = str(r.get(name_col,"")).strip()
            if not name:
                continue
            mw, den = _v228_lookup(self, name) if "_v228_lookup" in globals() else ("","")
            eq = r.get(f"{prefix} eq","")
            mmol = _v228_f(r.get(f"{prefix} mmol"),0)
            g = _v228_f(r.get(f"{prefix} g"),0)
            ml = _v228_f(r.get(f"{prefix} mL"),0)
            out.append({"step":step,"material":name,"class":cls,"MW":mw,"Density(g/mL)":den,
                        "Eq/mmol":_v230_eqmmol(eq, mmol),"Amount":_v230_amount(name, g, ml, den),
                        "_mmol":mmol,"_g":g,"_mL":ml,"use_count":_v228_s(copies),"repeat":_v228_s(rep),
                        "phase":"coupling reagent/base","note":f"{name_col}; step {step}","source":"Selected Plan"})
        # solvent / HBTU-NMP-DMF prep
        solv = str(r.get("Coupling cocktail solvent","")).strip()
        vol = _v228_f(r.get("Coupling cocktail volume(mL)"),0) * copies * rep
        is_hbtu_nmp = str(r.get("Coupling reagent 1","")).strip().upper() == "HBTU" and "NMP" in solv.upper()
        if is_hbtu_nmp and vol:
            # NMP final 0.8 M in DMF solution: mmol = 0.8 * mL, mL from MW/density. DMF is remainder.
            nmp_mmol = 0.8 * vol
            nmp_g = nmp_mmol * 99.13 / 1000.0
            nmp_ml = nmp_g / 1.028
            dmf_ml = max(vol - nmp_ml, 0)
            for name, mlv, note in [("NMP", nmp_ml, "0.8 M NMP in DMF-based HBTU/NMP solution"), ("DMF", dmf_ml, "DMF diluent for HBTU/NMP solution")]:
                mw, den = _v228_lookup(self, name) if "_v228_lookup" in globals() else ("","")
                out.append({"step":step,"material":name,"class":"Coupling solution solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"",
                            "Amount":f"{_v228_s(round(mlv,4))} mL","_mmol":0.0,"_g":0.0,"_mL":mlv,
                            "use_count":_v228_s(copies),"repeat":_v228_s(rep),"phase":"HBTU/NMP prep","note":note,"source":"HBTU/NMP solution rule"})
        elif solv and vol:
            try:
                splits = self._split_solution_name(solv, vol)
            except Exception:
                splits = [(solv, vol, "")]
            for sname, sml, snote in splits:
                mw, den = _v228_lookup(self, sname) if "_v228_lookup" in globals() else ("","")
                out.append({"step":step,"material":sname,"class":"Coupling solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"",
                            "Amount":f"{_v228_s(round(_v228_f(sml,0),4))} mL","_mmol":0.0,"_g":0.0,"_mL":_v228_f(sml,0),
                            "use_count":_v228_s(copies),"repeat":_v228_s(rep),"phase":"coupling solvent","note":snote or f"{solv}; step {step}","source":"Selected Plan"})
    out.extend(_v230_wash_rows(self))
    # cleavage TFA
    try:
        aa_count = len(_v228_tokens(self)); cys_count = sum(1 for x in _v228_tokens(self) if x == "C")
    except Exception:
        aa_count = 0; cys_count = 0
    ceq = 100 if aa_count >= 22 else 80 if aa_count >= 15 else 30
    ceq += 100*cys_count
    cmmol = scale*ceq
    tfa_ml = (cmmol*114.02/1000.0)/1.489 if cmmol else 0
    out.append({"step":"cleavage","material":"TFA","class":"Cleavage cocktail","MW":"114.02","Density(g/mL)":"1.489",
                "Eq/mmol":_v230_eqmmol(ceq, cmmol),"Amount":f"{_v228_s(round(tfa_ml,4))} mL",
                "_mmol":cmmol,"_g":0.0,"_mL":tfa_ml,"use_count":"1","repeat":"","phase":"cleavage",
                "note":"STD short peptide 30 eq; 15mer 80 eq; 22mer 100 eq; +100 eq/Cys","source":"Cleavage recommendation"})
    return pd.DataFrame(out)

def _v230_material_display_df(self):
    df = _v230_materials_detailed(self)
    return df[_V230_MAT_COLS].astype(str)

def _v230_total_df(self):
    df = _v230_materials_detailed(self)
    if df.empty:
        return pd.DataFrame(columns=_V230_TOTAL_COLS)
    for c in ["_mmol","_g","_mL"]:
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0)
    grp = df.groupby(["material","class"], dropna=False).agg({"MW":"first","Density(g/mL)":"first","_mmol":"sum","_g":"sum","_mL":"sum","use_count":"first","note":"first"}).reset_index()
    rows = []
    for _, r in grp.iterrows():
        amt = _v230_amount(r.get("material",""), round(float(r.get("_g",0)),4) if r.get("_g",0) else "", round(float(r.get("_mL",0)),4) if r.get("_mL",0) else "", r.get("Density(g/mL)",""))
        rows.append({"material":r.get("material",""),"class":r.get("class",""),"MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                     "total mmol":_v228_s(round(float(r.get("_mmol",0)),4) if r.get("_mmol",0) else ""),
                     "total amount":amt,"use_count":r.get("use_count",""),"note":r.get("note","")})
    return pd.DataFrame(rows, columns=_V230_TOTAL_COLS).astype(str)

def _v230_write_tree(self, tree, df):
    cols = list(df.columns)
    tree.configure(columns=cols, show="headings")
    widths = {"No":55,"Unit name":230,"MW":80,"Density(g/mL)":120,"Unit eq/mmol":135,"Unit amount":120,
              "Reagent 1 eq/mmol":145,"Reagent 2 eq/mmol":145,"Base eq/mmol":145,
              "Reagent 1 amount":120,"Reagent 2 amount":120,"Base amount":120,
              "Coupling cocktail solvent":165,"Solvent mL":100,"Repeat":70,"Note":260,
              "material":220,"class":160,"Eq/mmol":150,"Amount":130,"phase":150,"note":260,"source":190}
    for c in cols:
        tree.heading(c, text=c)
        tree.column(c, width=widths.get(c, 135), minwidth=70, anchor="w", stretch=False)
    for iid in list(tree.get_children()):
        tree.delete(iid)
    for _, row in df.iterrows():
        tree.insert("", "end", values=[_v230_amount(row.get(c,''), '', row.get(c,''), '') if False else _v228_s(row.get(c,"")) for c in cols])
    # Ensure scrollbars are active if they exist.
    try:
        tree.configure(xscrollcommand=tree.cget("xscrollcommand"))
    except Exception:
        pass

def _v230_refresh(self, commit=False):
    if commit and "_v228_commit_overrides" in globals():
        _v228_commit_overrides(self)
    _v230_write_tree(self, self.pm_selected_plan_tree, _v230_plan_display_df(self))
    _v230_write_tree(self, self.pm_selected_material_tree, _v230_material_display_df(self))
    if "_v228_ensure_total_tab" in globals():
        _v228_ensure_total_tab(self)
    if hasattr(self, "pm_selected_total_tree"):
        _v230_write_tree(self, self.pm_selected_total_tree, _v230_total_df(self))
    try: _v217_refresh_selected_checklist(self)
    except Exception: pass
    try: self.refresh_batch_workspace_preview()
    except Exception: pass
    try: self.schedule_autosave()
    except Exception: pass

def _v230_generate(self):
    try:
        _v230_integrate_rules_tabs(self)
        _v230_force_labels_and_resin_loading(self)
        if "_v228_set_resin_dropdowns" in globals():
            _v228_set_resin_dropdowns(self)
        try:
            item = _v217_save_editor_to_pm_item(self)
        except Exception:
            pass
        _v230_refresh(self, commit=False)
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v230_apply_plan(self):
    try:
        _v230_refresh(self, commit=True)
        self.save_autosave_state()
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass

try: _v230_old_collect_state = SPPSGui._collect_state
except Exception: _v230_old_collect_state = None
try: _v230_old_load_state = SPPSGui.load_autosave_state
except Exception: _v230_old_load_state = None
try: _v230_old_build = SPPSGui._build
except Exception: _v230_old_build = None

def _v230_collect_state(self):
    state = _v230_old_collect_state(self) if _v230_old_collect_state else {}
    try:
        state["unit_rule_enable"] = bool(self.unit_rule_enable.get()) if hasattr(self,"unit_rule_enable") else False
        state["reagent_rule_enable"] = bool(self.reagent_rule_enable.get()) if hasattr(self,"reagent_rule_enable") else False
        state["rule_eq_rules"] = self.rule_eq_rules.get() if hasattr(self,"rule_eq_rules") else ""
        state["rule_repeat_rules"] = self.rule_repeat_rules.get() if hasattr(self,"rule_repeat_rules") else ""
    except Exception: pass
    return state

def _v230_load_state(self):
    try:
        if _v230_old_load_state:
            _v230_old_load_state(self)
    except Exception: pass
    try:
        _v230_integrate_rules_tabs(self)
        if self.state_file.exists():
            st = json.loads(self.state_file.read_text(encoding="utf-8"))
            if hasattr(self,"unit_rule_enable"): self.unit_rule_enable.set(bool(st.get("unit_rule_enable", st.get("rule_enable", False))))
            if hasattr(self,"reagent_rule_enable"): self.reagent_rule_enable.set(bool(st.get("reagent_rule_enable", st.get("rule_enable", False))))
            if hasattr(self,"rule_eq_rules"): self.rule_eq_rules.set(st.get("rule_eq_rules",""))
            if hasattr(self,"rule_repeat_rules"): self.rule_repeat_rules.set(st.get("rule_repeat_rules",""))
    except Exception: pass

def _v230_build(self):
    if _v230_old_build:
        _v230_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        _v230_integrate_rules_tabs(self)
        _v230_force_labels_and_resin_loading(self)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v230_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception: pass
                walk(c)
        walk(self)
    except Exception: pass

SPPSGui.pm_generate_selected = _v230_generate
SPPSGui.pm_calculate_all = _v230_generate
SPPSGui.apply_plan_mw_density = _v230_apply_plan
SPPSGui._collect_state = _v230_collect_state
SPPSGui.load_autosave_state = _v230_load_state
SPPSGui._build = _v230_build
