# ======================= V2.0.32 FROM USER-UPLOADED V2.0.30: UI/FORMULA FIX PATCH =======================
# Built directly on the user-uploaded V2.0.30 ZIP.
# Do not remove previous core functions. This patch only overrides the broken/unclear parts:
# - Resin loading (mmol/g) entry is forced to exist beside the label and is used for resin_g.
# - Old scattered range controls are hidden; new grouped two-choice checkbox controls are added.
# - Display formula is "eq × scale(mmol) → mmol", because eq is a multiplier, not a unit.
# - No forced Ac-EEMQRR-NH2 reset on Generate; initial default sequence is cleared only when it is the built-in placeholder default.
# - Horizontal scroll/fixed column widths are forced for Selected tables.
# - Selected Total Materials stays material-name merged and focuses on total amount.
# - Cleavage cocktail split TFA:TIS:DW = 0.95:0.025:0.025 is included.
# =====================================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V232_PLAN_COLS = [
    "No","Unit name","MW","Density(g/mL)","Unit eq×scale→mmol","Unit amount",
    "Coupling reagent 1","Reagent 1 eq×scale→mmol","Reagent 1 amount",
    "Coupling reagent 2","Reagent 2 eq×scale→mmol","Reagent 2 amount",
    "Coupling base","Base eq×scale→mmol","Base amount",
    "Coupling cocktail solvent","Solvent mL","Repeat","Note"
]
_V232_TOTAL_COLS = ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]

def _v232_s(v):
    return _v228_s(v) if "_v228_s" in globals() else ("" if v is None else str(v))

def _v232_f(v, default=0.0):
    return _v228_f(v, default) if "_v228_f" in globals() else default

def _v232_eq_scale_mmol(eq, scale, repeat=1, copies=1):
    e = _v232_f(eq, 0.0)
    s = _v232_f(scale, 0.0)
    r = max(1, int(round(_v232_f(repeat, 1))))
    c = max(1, int(round(_v232_f(copies, 1))))
    mmol = e * s * r * c
    if r == 1 and c == 1:
        return f"{_v232_s(e)} × {_v232_s(s)} → {_v232_s(round(mmol,4))} mmol"
    return f"{_v232_s(e)} × {_v232_s(s)} × rep{r} × copy{c} → {_v232_s(round(mmol,4))} mmol"

def _v232_hide_old_rule_widgets(self):
    old_texts = {
        "Use range-based eq / coupling repeat rules",
        "Use range eq/repeat rules for AA units",
        "Tie reagent/catalyst eq to AA range eq",
        "Uses Unit defaults AA eq range",
        "Reagent repeat follows AA repeat",
        "AA eq range",
        "AA repeat/doubling range",
    }
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, (ttk.Label, ttk.Checkbutton)) and str(c.cget("text")).strip() in old_texts:
                        c.grid_remove()
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v232_modevar(self, name, default):
    if not hasattr(self, name):
        setattr(self, name, tk.StringVar(value=default))
    return getattr(self, name)

def _v232_add_pair_checkbuttons(parent, row, title, var, left_text, left_value, right_text, right_value):
    box = ttk.Labelframe(parent, text=title, padding=6)
    box.grid(row=row, column=0, columnspan=5, sticky="ew", padx=8, pady=4)
    box.columnconfigure(2, weight=1)
    def set_left():
        var.set(left_value)
    def set_right():
        var.set(right_value)
    ttk.Checkbutton(box, text=left_text, command=set_left).grid(row=0, column=0, sticky="w", padx=6, pady=2)
    ttk.Checkbutton(box, text=right_text, command=set_right).grid(row=0, column=1, sticky="w", padx=6, pady=2)
    # Keep checkbutton visual state synchronized by small labels, because ttk checkbutton variable sharing with different onvalues is fragile across themes.
    ttk.Label(box, textvariable=var).grid(row=0, column=3, sticky="e", padx=6)
    return box

def _v232_add_grouped_controls(self):
    _v232_hide_old_rule_widgets(self)
    # Modes: each row is two-choice.
    _v232_modevar(self, "aa_eq_mode", "default")
    _v232_modevar(self, "aa_repeat_mode", "default")
    _v232_modevar(self, "r1_eq_mode", "own")
    _v232_modevar(self, "r1_count_mode", "own")
    _v232_modevar(self, "cat_eq_mode", "own")
    _v232_modevar(self, "cat_count_mode", "own")
    _v232_modevar(self, "base_eq_mode", "own")
    _v232_modevar(self, "base_count_mode", "own")
    if not hasattr(self, "rule_eq_rules"):
        self.rule_eq_rules = tk.StringVar(value="")
    if not hasattr(self, "rule_repeat_rules"):
        self.rule_repeat_rules = tk.StringVar(value="")
    try:
        nb = None
        def walk(w):
            nonlocal nb
            if nb is not None:
                return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Notebook):
                        texts = [str(c.tab(t, "text")) for t in c.tabs()]
                        if "Unit defaults" in texts and "Reagents" in texts:
                            nb = c
                            return
                except Exception:
                    pass
                walk(c)
        walk(self)
        if nb is None:
            return
        for tab_id in list(nb.tabs()):
            try:
                if str(nb.tab(tab_id, "text")) == "Range / Coupling Rules":
                    nb.forget(tab_id)
            except Exception:
                pass
        unit_fr = reagent_fr = None
        for tab_id in nb.tabs():
            try:
                t = str(nb.tab(tab_id, "text"))
                if t == "Unit defaults": unit_fr = nb.nametowidget(tab_id)
                if t == "Reagents": reagent_fr = nb.nametowidget(tab_id)
            except Exception:
                pass
        if unit_fr is not None and not hasattr(self, "_v232_unit_group_added"):
            self._v232_unit_group_added = True
            row = 32
            sep = ttk.Separator(unit_fr, orient="horizontal"); sep.grid(row=row, column=0, columnspan=6, sticky="ew", pady=(10,4)); row += 1
            b = _v232_add_pair_checkbuttons(unit_fr, row, "AA eq control", self.aa_eq_mode, "Use Default AA eq", "default", "Use AA eq range", "range"); row += 1
            ttk.Label(b, text="AA eq range").grid(row=1, column=0, sticky="w", padx=6, pady=2)
            ttk.Entry(b, textvariable=self.rule_eq_rules, width=34).grid(row=1, column=1, columnspan=2, sticky="ew", padx=6, pady=2)
            ttk.Label(b, text="ex) 2-10:3, 11-20:5").grid(row=1, column=3, sticky="w", padx=6, pady=2)
            b = _v232_add_pair_checkbuttons(unit_fr, row, "AA repeat control", self.aa_repeat_mode, "Use Default AA repeat", "default", "Use AA repeat/doubling range", "range"); row += 1
            ttk.Label(b, text="AA repeat range").grid(row=1, column=0, sticky="w", padx=6, pady=2)
            ttk.Entry(b, textvariable=self.rule_repeat_rules, width=34).grid(row=1, column=1, columnspan=2, sticky="ew", padx=6, pady=2)
            ttk.Label(b, text="ex) 18-25:2").grid(row=1, column=3, sticky="w", padx=6, pady=2)
        if reagent_fr is not None and not hasattr(self, "_v232_reagent_group_added"):
            self._v232_reagent_group_added = True
            row = 32
            ttk.Separator(reagent_fr, orient="horizontal").grid(row=row, column=0, columnspan=8, sticky="ew", pady=(10,4)); row += 1
            _v232_add_pair_checkbuttons(reagent_fr, row, "Reagent 1 eq control", self.r1_eq_mode, "Use Reagent 1 eq", "own", "Tie to AA range eq", "tie"); row += 1
            _v232_add_pair_checkbuttons(reagent_fr, row, "Reagent 1 count/repeat control", self.r1_count_mode, "Use Reagent 1 count", "own", "Follow AA repeat", "aa_repeat"); row += 1
            _v232_add_pair_checkbuttons(reagent_fr, row, "Catalyst eq control", self.cat_eq_mode, "Use Catalyst eq", "own", "Tie to AA range eq", "tie"); row += 1
            _v232_add_pair_checkbuttons(reagent_fr, row, "Catalyst count/repeat control", self.cat_count_mode, "Use Catalyst count", "own", "Follow AA repeat", "aa_repeat"); row += 1
            _v232_add_pair_checkbuttons(reagent_fr, row, "Base eq control", self.base_eq_mode, "Use Base eq", "own", "Tie to AA range eq", "tie"); row += 1
            _v232_add_pair_checkbuttons(reagent_fr, row, "Base count/repeat control", self.base_count_mode, "Use Base count", "own", "Follow AA repeat", "aa_repeat")
    except Exception:
        pass

def _v232_force_resin_loading_entry(self):
    try:
        # Remove only the orphan old below-label.
        def remove_orphan(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label) and str(c.cget("text")).strip() == "mmol/g":
                        c.grid_remove()
                except Exception:
                    pass
                remove_orphan(c)
        remove_orphan(self)
        parent = None
        def find_editor(w):
            nonlocal parent
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Labelframe) and str(c.cget("text")).strip() == "Selected peptide editor":
                        parent = c
                        return
                except Exception:
                    pass
                find_editor(c)
        find_editor(self)
        if parent is not None and hasattr(self, "pm_loading"):
            # Original grid: label col4, entry col5. Force min width and place real editable Entry.
            try:
                parent.columnconfigure(5, minsize=120, weight=1)
            except Exception:
                pass
            ttk.Label(parent, text="Resin loading (mmol/g)", width=22).grid(row=2, column=4, sticky="w", padx=(2,4), pady=2)
            e = ttk.Entry(parent, textvariable=self.pm_loading, width=12)
            e.grid(row=2, column=5, sticky="ew", padx=(0,8), pady=2)
            self._v232_pm_loading_entry = e
            # Scale label fix
            for c in parent.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget("text")).strip() == "Scale mmol":
                        c.configure(text="Scale(mmol)")
                except Exception:
                    pass
    except Exception:
        pass

def _v232_clear_builtin_default_sequence(self):
    # Do not force Ac-EEMQRR-NH2 as default.
    try:
        if hasattr(self, "seq") and self.seq.get().strip() == "Ac-EEMQRR-NH2":
            self.seq.set("")
    except Exception:
        pass
    try:
        if hasattr(self, "pm_sequence") and self.pm_sequence.get().strip() == "Ac-EEMQRR-NH2":
            self.pm_sequence.set("")
    except Exception:
        pass

def _v232_range_value(text, step, default):
    try:
        st = int(float(step))
        parser = _v228_parse_range_rules if "_v228_parse_range_rules" in globals() else None
        if parser:
            for a,b,val in parser(text):
                if a <= st <= b:
                    return val
    except Exception:
        pass
    return default

def _v232_aa_eq(self, step):
    default = _v232_f(getattr(self, "default_reagent_eq", _v225_const_var("10")).get(), 10)
    try:
        if self.aa_eq_mode.get() == "range":
            return _v232_range_value(self.rule_eq_rules.get(), step, default)
    except Exception:
        pass
    return default

def _v232_aa_repeat(self, step):
    default = max(1, int(round(_v232_f(getattr(self, "default_repeat", _v225_const_var("1")).get(), 1))))
    try:
        if self.aa_repeat_mode.get() == "range":
            return max(1, int(round(_v232_range_value(self.rule_repeat_rules.get(), step, default))))
    except Exception:
        pass
    return default

def _v232_reg_eq(self, step, mode_name, default):
    try:
        if getattr(self, mode_name).get() == "tie":
            return _v232_aa_eq(self, step)
    except Exception:
        pass
    return default

def _v232_reg_count(self, step, mode_name, default):
    try:
        if getattr(self, mode_name).get() == "aa_repeat":
            return _v232_aa_repeat(self, step)
    except Exception:
        pass
    return max(1, int(round(_v232_f(default, 1))))

def _v232_solvent_ml_for_scale(self):
    # SPPS working solution mL from practical concentration window. Keep V2.0.30 behavior if present.
    try:
        return _v231_practical_coupling_ml(_v232_f(self.pm_scale.get(), 0.2))
    except Exception:
        pass
    try:
        return _v230_wash_rows  # intentionally unreachable except name check
    except Exception:
        pass
    scale = _v232_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2)
    if scale <= 0.2: return max(3.0*scale/0.2, 1.0)
    pts = [(0.2,3.0),(0.4,6.5),(1.0,12.5),(10.0,150.0)]
    for (x1,y1),(x2,y2) in zip(pts, pts[1:]):
        if x1 <= scale <= x2:
            return y1 + (y2-y1)*(scale-x1)/(x2-x1)
    return scale*15.0

def _v232_plan_detailed(self):
    # Start from V2.0.29/V2.0.30 detailed plan, then apply corrected modes and formulas.
    base = _v229_plan_df(self).copy() if "_v229_plan_df" in globals() else pd.DataFrame()
    scale = _v232_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2, 0.2)
    copies = max(1, int(round(_v232_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1, 1))))
    solvent_ml = _v232_solvent_ml_for_scale(self)
    for i, r in base.iterrows():
        step = r.get("No","")
        note = str(r.get("Note","")).lower()
        direct_loading = "direct loading" in note
        if direct_loading:
            eq = _v232_f(r.get("Unit eq"), 2)
            repeat = 1
        else:
            eq = _v232_aa_eq(self, step)
            repeat = _v232_aa_repeat(self, step)
        base.at[i, "Unit eq"] = _v232_s(eq)
        base.at[i, "Repeat"] = _v232_s(repeat)
        mw = _v232_f(r.get("MW"), 0)
        base.at[i, "Unit amount(g)"] = _v232_s(round(eq*scale*copies*repeat*mw/1000.0,4) if mw else "")
        base.at[i, "Coupling cocktail volume(mL)"] = _v232_s(round(solvent_ml,4))
        # Own defaults
        r1_def = _v232_f(getattr(self, "default_reagent_eq", _v225_const_var("10")).get(), 10)
        r2_def = _v232_f(getattr(self, "default_catalyst_eq", _v225_const_var("10")).get(), 10)
        b_def = _v232_f(getattr(self, "default_base_eq", _v225_const_var("5")).get(), 5)
        if direct_loading:
            b_eq = _v232_f(getattr(self, "loading_diea_eq", _v225_const_var("4")).get(), 4)
        else:
            b_eq = _v232_reg_eq(self, step, "base_eq_mode", b_def)
        vals = [
            ("Reagent 1", "Coupling reagent 1", _v232_reg_eq(self, step, "r1_eq_mode", r1_def), _v232_reg_count(self, step, "r1_count_mode", getattr(self, "default_reagent_count", _v225_const_var("1")).get() if hasattr(self, "default_reagent_count") else 1)),
            ("Reagent 2", "Coupling reagent 2 / catalyst", _v232_reg_eq(self, step, "cat_eq_mode", r2_def), _v232_reg_count(self, step, "cat_count_mode", getattr(self, "default_catalyst_count", _v225_const_var("1")).get() if hasattr(self, "default_catalyst_count") else 1)),
            ("Base", "Coupling base", b_eq, _v232_reg_count(self, step, "base_count_mode", getattr(self, "default_base_count", _v225_const_var("1")).get() if hasattr(self, "default_base_count") else 1)),
        ]
        for prefix, name_col, eqv, count in vals:
            name = str(base.at[i, name_col]) if name_col in base.columns else ""
            if not name:
                continue
            total_repeat = repeat * count
            eq_s, mmol_s, g_s, ml_s, _ = _v229_calc_reagent_amount(self, name, eqv, scale, copies, total_repeat)
            base.at[i, f"{prefix} eq"] = eq_s
            base.at[i, f"{prefix} mmol"] = mmol_s
            base.at[i, f"{prefix} g"] = g_s
            base.at[i, f"{prefix} mL"] = ml_s
    return base.astype(str)

def _v232_amount(name, g="", ml="", density=""):
    return _v230_amount(name, g, ml, density) if "_v230_amount" in globals() else (f"{g} g" if str(g).strip() else "")

def _v232_plan_display_df(self):
    base = _v232_plan_detailed(self)
    rows = []
    scale = _v232_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0,0)
    copies = max(1, int(round(_v232_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1,1))))
    for _, r in base.iterrows():
        rep = max(1, int(round(_v232_f(r.get("Repeat"),1))))
        rows.append({
            "No": r.get("No",""), "Unit name": r.get("Unit name",""), "MW": r.get("MW",""), "Density(g/mL)": r.get("Density(g/mL)",""),
            "Unit eq×scale→mmol": _v232_eq_scale_mmol(r.get("Unit eq",""), scale, rep, copies),
            "Unit amount": _v232_amount(r.get("Unit name",""), r.get("Unit amount(g)",""), r.get("Unit volume(mL)",""), r.get("Density(g/mL)","")),
            "Coupling reagent 1": r.get("Coupling reagent 1",""),
            "Reagent 1 eq×scale→mmol": _v232_eq_scale_mmol(r.get("Reagent 1 eq",""), scale, rep, copies) if str(r.get("Coupling reagent 1","")).strip() else "",
            "Reagent 1 amount": _v232_amount(r.get("Coupling reagent 1",""), r.get("Reagent 1 g",""), r.get("Reagent 1 mL",""), _v228_lookup(self, r.get("Coupling reagent 1",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling reagent 2": r.get("Coupling reagent 2 / catalyst",""),
            "Reagent 2 eq×scale→mmol": _v232_eq_scale_mmol(r.get("Reagent 2 eq",""), scale, rep, copies) if str(r.get("Coupling reagent 2 / catalyst","")).strip() else "",
            "Reagent 2 amount": _v232_amount(r.get("Coupling reagent 2 / catalyst",""), r.get("Reagent 2 g",""), r.get("Reagent 2 mL",""), _v228_lookup(self, r.get("Coupling reagent 2 / catalyst",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling base": r.get("Coupling base",""),
            "Base eq×scale→mmol": _v232_eq_scale_mmol(r.get("Base eq",""), scale, rep, copies) if str(r.get("Coupling base","")).strip() else "",
            "Base amount": _v232_amount(r.get("Coupling base",""), r.get("Base g",""), r.get("Base mL",""), _v228_lookup(self, r.get("Coupling base",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling cocktail solvent": r.get("Coupling cocktail solvent",""),
            "Solvent mL": r.get("Coupling cocktail volume(mL)",""),
            "Repeat": r.get("Repeat",""), "Note": r.get("Note","")
        })
    return pd.DataFrame(rows, columns=_V232_PLAN_COLS).astype(str)

def _v232_cleavage_rows(self):
    scale = _v232_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2,0.2)
    try:
        aa_count = len(_v228_tokens(self)); cys_count = sum(1 for x in _v228_tokens(self) if x == "C")
    except Exception:
        aa_count = 0; cys_count = 0
    ceq = 100 if aa_count >= 22 else 80 if aa_count >= 15 else 30
    ceq += 100*cys_count
    tfa_mmol = scale * ceq
    tfa_g = tfa_mmol * 114.02 / 1000.0
    tfa_ml = tfa_g / 1.489 if tfa_g else 0
    total_ml = tfa_ml / 0.95 if tfa_ml else 0
    rows = []
    for name, frac in [("TFA",0.95), ("TIS",0.025), ("Water",0.025)]:
        mw, den = _v228_lookup(self, name) if "_v228_lookup" in globals() else ("","")
        ml = total_ml*frac
        mmol = (ml*_v232_f(den,0)*1000.0/_v232_f(mw,1)) if mw and den else 0
        rows.append({"step":"cleavage","material":name,"class":"Cleavage cocktail","MW":mw,"Density(g/mL)":den,
                     "Eq/mmol": _v232_eq_scale_mmol(ceq, scale) if name=="TFA" else _v232_s(round(mmol,4))+" mmol",
                     "Amount": f"{_v232_s(round(ml,4))} mL" if ml else "",
                     "_mmol":mmol, "_g":0.0, "_mL":ml, "use_count":"1","repeat":"","phase":"cleavage",
                     "note":"Cleavage cocktail TFA:TIS:DW = 0.95:0.025:0.025","source":"Cleavage recommendation"})
    return rows

def _v232_materials_detailed(self):
    plan = _v232_plan_detailed(self)
    out = []
    scale = _v232_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2,0.2)
    copies = max(1, int(round(_v232_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1,1))))
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self,"pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    loading = _v232_f(self.pm_loading.get() if hasattr(self,"pm_loading") else 0, 0)
    resin_g = scale*copies/loading if loading else 0
    out.append({"step":"resin","material":resin,"class":"Resin","MW":"N/A","Density(g/mL)":"N/A",
                "Eq/mmol":_v232_eq_scale_mmol(1, scale, 1, copies),
                "Amount":f"{_v232_s(round(resin_g,4))} g" if resin_g else "",
                "_mmol":scale*copies,"_g":resin_g,"_mL":0.0,"use_count":_v232_s(copies),"repeat":"","phase":"resin",
                "note":"resin_g = scale_mmol × copies / resin_loading_mmol_g","source":"Project Manager"})
    for _, r in plan.iterrows():
        step = r.get("No",""); rep = max(1, int(round(_v232_f(r.get("Repeat"),1))))
        unit = str(r.get("Unit name","")); eq = _v232_f(r.get("Unit eq"),0)
        mmol = scale*copies*eq*rep
        g = _v232_f(r.get("Unit amount(g)"),0); ml = _v232_f(r.get("Unit volume(mL)"),0)
        out.append({"step":step,"material":unit,"class":"AA/Chemical","MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                    "Eq/mmol":_v232_eq_scale_mmol(eq, scale, rep, copies),
                    "Amount":_v232_amount(unit,g,ml,r.get("Density(g/mL)","")),
                    "_mmol":mmol,"_g":g,"_mL":ml,"use_count":_v232_s(copies),"repeat":_v232_s(rep),"phase":"coupling","note":r.get("Note",""),"source":"Selected Plan"})
        for name_col,prefix,cls in [("Coupling reagent 1","Reagent 1","Coupling reagent"),("Coupling reagent 2 / catalyst","Reagent 2","Catalyst/additive"),("Coupling base","Base","Base")]:
            name = str(r.get(name_col,"")).strip()
            if not name: continue
            mw, den = _v228_lookup(self, name) if "_v228_lookup" in globals() else ("","")
            eqv = r.get(f"{prefix} eq",""); mm = _v232_f(r.get(f"{prefix} mmol"),0); g = _v232_f(r.get(f"{prefix} g"),0); ml = _v232_f(r.get(f"{prefix} mL"),0)
            if mm == 0 and g == 0 and ml == 0:
                continue
            out.append({"step":step,"material":name,"class":cls,"MW":mw,"Density(g/mL)":den,
                        "Eq/mmol":_v232_eq_scale_mmol(eqv, scale, rep, copies),
                        "Amount":_v232_amount(name,g,ml,den),"_mmol":mm,"_g":g,"_mL":ml,"use_count":_v232_s(copies),"repeat":_v232_s(rep),
                        "phase":"coupling reagent/base","note":f"{name_col}; step {step}","source":"Selected Plan"})
        # solvent
        solv = str(r.get("Coupling cocktail solvent","")).strip()
        vol = _v232_f(r.get("Coupling cocktail volume(mL)"),0)*copies*rep
        is_hbtu = str(r.get("Coupling reagent 1","")).strip().upper()=="HBTU" and "NMP" in solv.upper()
        if is_hbtu and vol:
            nmp_mmol = 0.8*vol
            nmp_g = nmp_mmol*99.13/1000.0
            nmp_ml = nmp_g/1.028
            dmf_ml = max(vol-nmp_ml,0)
            for name, mlv, note in [("NMP", nmp_ml, "0.8 M NMP in DMF-based HBTU/NMP solution"), ("DMF", dmf_ml, "DMF diluent for HBTU/NMP solution")]:
                mw, den = _v228_lookup(self,name) if "_v228_lookup" in globals() else ("","")
                out.append({"step":step,"material":name,"class":"Coupling solution solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"","Amount":f"{_v232_s(round(mlv,4))} mL",
                            "_mmol":0.0,"_g":0.0,"_mL":mlv,"use_count":_v232_s(copies),"repeat":_v232_s(rep),"phase":"HBTU/NMP prep","note":note,"source":"HBTU/NMP solution rule"})
        elif solv and vol:
            try: splits = self._split_solution_name(solv, vol)
            except Exception: splits = [(solv,vol,"")]
            for sname,sml,snote in splits:
                mw, den = _v228_lookup(self,sname) if "_v228_lookup" in globals() else ("","")
                out.append({"step":step,"material":sname,"class":"Coupling solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"","Amount":f"{_v232_s(round(_v232_f(sml,0),4))} mL",
                            "_mmol":0.0,"_g":0.0,"_mL":_v232_f(sml,0),"use_count":_v232_s(copies),"repeat":_v232_s(rep),"phase":"coupling solvent","note":snote or f"{solv}; step {step}","source":"Selected Plan"})
    # Existing V2.0.30 wash rows are preserved.
    if "_v230_wash_rows" in globals():
        out.extend(_v230_wash_rows(self))
    out.extend(_v232_cleavage_rows(self))
    return pd.DataFrame(out)

def _v232_material_display_df(self):
    df = _v232_materials_detailed(self)
    return df[_V230_MAT_COLS].astype(str) if "_V230_MAT_COLS" in globals() else df.astype(str)

def _v232_total_df(self):
    # Merge by material name only; total amount is the main quantitative field.
    df = _v232_materials_detailed(self)
    if df.empty: return pd.DataFrame(columns=_V232_TOTAL_COLS)
    for c in ["_mmol","_g","_mL"]:
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0)
    grp = df.groupby(["material"], dropna=False).agg({"class":"first","MW":"first","Density(g/mL)":"first","_mmol":"sum","_g":"sum","_mL":"sum","note":"first"}).reset_index()
    rows = []
    for _, r in grp.iterrows():
        amount = _v232_amount(r.get("material",""), round(float(r.get("_g",0)),4) if float(r.get("_g",0)) else "", round(float(r.get("_mL",0)),4) if float(r.get("_mL",0)) else "", r.get("Density(g/mL)",""))
        rows.append({"material":r.get("material",""),"class":r.get("class",""),"MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                     "total mmol":_v232_s(round(float(r.get("_mmol",0)),4) if float(r.get("_mmol",0)) else ""),
                     "total amount":amount,"note":r.get("note","")})
    return pd.DataFrame(rows, columns=_V232_TOTAL_COLS).astype(str)

def _v232_write_tree(self, tree, df):
    cols = list(df.columns)
    tree.configure(columns=cols, show="headings")
    widths = {
        "No":55,"Unit name":230,"MW":80,"Density(g/mL)":125,
        "Unit eq×scale→mmol":170,"Reagent 1 eq×scale→mmol":185,"Reagent 2 eq×scale→mmol":185,"Base eq×scale→mmol":170,
        "Unit amount":120,"Reagent 1 amount":125,"Reagent 2 amount":125,"Base amount":120,
        "Coupling reagent 1":155,"Coupling reagent 2":155,"Coupling base":130,"Coupling cocktail solvent":170,"Solvent mL":100,
        "Repeat":70,"Note":300,"material":220,"class":170,"Eq/mmol":185,"Amount":135,"phase":160,"note":300,"source":190,
        "total amount":150,"total mmol":110
    }
    for c in cols:
        tree.heading(c, text=c)
        tree.column(c, width=widths.get(c,140), minwidth=70, anchor="w", stretch=False)
    for iid in list(tree.get_children()):
        tree.delete(iid)
    for _, row in df.iterrows():
        tree.insert("", "end", values=[_v232_s(row.get(c,"")) for c in cols])
    try:
        # Force horizontal scrolling behavior.
        tree.xview_moveto(0)
    except Exception:
        pass

def _v232_refresh(self, commit=False):
    if commit and "_v228_commit_overrides" in globals():
        _v228_commit_overrides(self)
    _v232_write_tree(self, self.pm_selected_plan_tree, _v232_plan_display_df(self))
    _v232_write_tree(self, self.pm_selected_material_tree, _v232_material_display_df(self))
    if "_v228_ensure_total_tab" in globals():
        _v228_ensure_total_tab(self)
    if hasattr(self, "pm_selected_total_tree"):
        _v232_write_tree(self, self.pm_selected_total_tree, _v232_total_df(self))
    try: _v217_refresh_selected_checklist(self)
    except Exception: pass
    try: self.refresh_batch_workspace_preview()
    except Exception: pass
    try: self.schedule_autosave()
    except Exception: pass

def _v232_generate(self):
    try:
        _v232_add_grouped_controls(self)
        _v232_force_resin_loading_entry(self)
        if "_v228_set_resin_dropdowns" in globals(): _v228_set_resin_dropdowns(self)
        try: _v217_save_editor_to_pm_item(self)
        except Exception: pass
        _v232_refresh(self, commit=False)
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v232_apply_plan(self):
    try:
        _v232_refresh(self, commit=True)
        self.save_autosave_state()
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass

try: _v232_old_collect = SPPSGui._collect_state
except Exception: _v232_old_collect = None
try: _v232_old_load = SPPSGui.load_autosave_state
except Exception: _v232_old_load = None
try: _v232_old_build = SPPSGui._build
except Exception: _v232_old_build = None

def _v232_collect_state(self):
    state = _v232_old_collect(self) if _v232_old_collect else {}
    for name in ["aa_eq_mode","aa_repeat_mode","r1_eq_mode","r1_count_mode","cat_eq_mode","cat_count_mode","base_eq_mode","base_count_mode"]:
        try: state[name] = getattr(self,name).get()
        except Exception: pass
    try:
        state["rule_eq_rules"] = self.rule_eq_rules.get()
        state["rule_repeat_rules"] = self.rule_repeat_rules.get()
    except Exception: pass
    return state

def _v232_load_state(self):
    try:
        if _v232_old_load: _v232_old_load(self)
    except Exception: pass
    try:
        _v232_add_grouped_controls(self)
        if self.state_file.exists():
            st = json.loads(self.state_file.read_text(encoding="utf-8"))
            for name in ["aa_eq_mode","aa_repeat_mode","r1_eq_mode","r1_count_mode","cat_eq_mode","cat_count_mode","base_eq_mode","base_count_mode"]:
                if name in st and hasattr(self,name):
                    getattr(self,name).set(st[name])
            if hasattr(self,"rule_eq_rules"): self.rule_eq_rules.set(st.get("rule_eq_rules",""))
            if hasattr(self,"rule_repeat_rules"): self.rule_repeat_rules.set(st.get("rule_repeat_rules",""))
    except Exception: pass

def _v232_build(self):
    if _v232_old_build: _v232_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        _v232_clear_builtin_default_sequence(self)
        _v232_add_grouped_controls(self)
        _v232_force_resin_loading_entry(self)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v232_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception: pass
                walk(c)
        walk(self)
    except Exception: pass

SPPSGui.pm_generate_selected = _v232_generate
SPPSGui.pm_calculate_all = _v232_generate
SPPSGui.apply_plan_mw_density = _v232_apply_plan
SPPSGui._collect_state = _v232_collect_state
SPPSGui.load_autosave_state = _v232_load_state
SPPSGui._build = _v232_build
# ======================= END V2.0.32 PATCH =======================



# ======================= V2.0.33 BLANK-SEQUENCE + FLUID COLUMNS + WORKING mL PATCH =======================
# Based on V2.0.32.
# - Blank sequence is a valid natural idle state. Generate does not raise "Core sequence is empty".
# - Empty sequence shows empty Selected Plan and only non-placeholder project-level rows where meaningful.
# - Selected table columns are fluid/stretching again while horizontal scrollbar remains available.
# - SPPS solvent volume uses one working solution mL basis from concentration/practical scale, then coupling/wash/swell/deprotection rows use that basis.
# - No placeholder peptide sequence is injected.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v233_has_sequence(self):
    try:
        seq = str(self.pm_sequence.get() or "").strip()
    except Exception:
        seq = ""
    if not seq:
        return False
    try:
        toks = _v228_tokens(self) if "_v228_tokens" in globals() else []
        return bool(toks)
    except Exception:
        cleaned = re.sub(r"(?i)Ac|NH2|COOH|OH", "", seq)
        return any(ch.upper() in "ARNDCQEGHILKMFPSTWYV" for ch in cleaned)

def _v233_empty_plan_df():
    return pd.DataFrame(columns=_V232_PLAN_COLS if "_V232_PLAN_COLS" in globals() else [])

def _v233_empty_material_df():
    cols = _V230_MAT_COLS if "_V230_MAT_COLS" in globals() else ["step","material","class","MW","Density(g/mL)","Eq/mmol","Amount","use_count","repeat","phase","note","source"]
    return pd.DataFrame(columns=cols)

def _v233_empty_total_df():
    return pd.DataFrame(columns=_V232_TOTAL_COLS if "_V232_TOTAL_COLS" in globals() else ["material","class","MW","Density(g/mL)","total mmol","total amount","note"])

def _v233_working_ml(self):
    # One SPPS working solution mL basis. This is the volume basis used for coupling/wash/swell/deprotection.
    scale = _v232_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2) if "_v232_f" in globals() else 0.2
    try:
        ml = _v232_solvent_ml_for_scale(self)
    except Exception:
        ml = 0
    if not ml:
        # fallback practical interpolation
        if scale <= 0.2:
            ml = max(3.0 * scale / 0.2, 1.0)
        else:
            pts = [(0.2,3.0),(0.4,6.5),(1.0,12.5),(10.0,150.0)]
            ml = None
            for (x1,y1),(x2,y2) in zip(pts, pts[1:]):
                if x1 <= scale <= x2:
                    ml = y1 + (y2-y1)*(scale-x1)/(x2-x1)
                    break
            if ml is None:
                ml = scale * 15.0
    return float(ml)

def _v233_plan_detailed(self):
    if not _v233_has_sequence(self):
        # blank is natural; no parse error, no placeholder.
        return pd.DataFrame(columns=_V229_PLAN_COLS if "_V229_PLAN_COLS" in globals() else [])
    base = _v232_plan_detailed(self).copy() if "_v232_plan_detailed" in globals() else pd.DataFrame()
    working_ml = _v233_working_ml(self)
    # force every coupling row to use the same working mL basis
    if "Coupling cocktail volume(mL)" in base.columns:
        base["Coupling cocktail volume(mL)"] = _v232_s(round(working_ml,4)) if "_v232_s" in globals() else str(round(working_ml,4))
    return base.astype(str)

def _v233_plan_display_df(self):
    if not _v233_has_sequence(self):
        return _v233_empty_plan_df()
    # Reuse v232 display, but based on v233 detailed plan via local conversion.
    base = _v233_plan_detailed(self)
    rows = []
    scale = _v232_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0,0)
    copies = max(1, int(round(_v232_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1,1))))
    for _, r in base.iterrows():
        rep = max(1, int(round(_v232_f(r.get("Repeat"),1))))
        rows.append({
            "No": r.get("No",""), "Unit name": r.get("Unit name",""), "MW": r.get("MW",""), "Density(g/mL)": r.get("Density(g/mL)",""),
            "Unit eq×scale→mmol": _v232_eq_scale_mmol(r.get("Unit eq",""), scale, rep, copies),
            "Unit amount": _v232_amount(r.get("Unit name",""), r.get("Unit amount(g)",""), r.get("Unit volume(mL)",""), r.get("Density(g/mL)","")),
            "Coupling reagent 1": r.get("Coupling reagent 1",""),
            "Reagent 1 eq×scale→mmol": _v232_eq_scale_mmol(r.get("Reagent 1 eq",""), scale, rep, copies) if str(r.get("Coupling reagent 1","")).strip() else "",
            "Reagent 1 amount": _v232_amount(r.get("Coupling reagent 1",""), r.get("Reagent 1 g",""), r.get("Reagent 1 mL",""), _v228_lookup(self, r.get("Coupling reagent 1",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling reagent 2": r.get("Coupling reagent 2 / catalyst",""),
            "Reagent 2 eq×scale→mmol": _v232_eq_scale_mmol(r.get("Reagent 2 eq",""), scale, rep, copies) if str(r.get("Coupling reagent 2 / catalyst","")).strip() else "",
            "Reagent 2 amount": _v232_amount(r.get("Coupling reagent 2 / catalyst",""), r.get("Reagent 2 g",""), r.get("Reagent 2 mL",""), _v228_lookup(self, r.get("Coupling reagent 2 / catalyst",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling base": r.get("Coupling base",""),
            "Base eq×scale→mmol": _v232_eq_scale_mmol(r.get("Base eq",""), scale, rep, copies) if str(r.get("Coupling base","")).strip() else "",
            "Base amount": _v232_amount(r.get("Coupling base",""), r.get("Base g",""), r.get("Base mL",""), _v228_lookup(self, r.get("Coupling base",""))[1] if "_v228_lookup" in globals() else ""),
            "Coupling cocktail solvent": r.get("Coupling cocktail solvent",""),
            "Solvent mL": r.get("Coupling cocktail volume(mL)",""),
            "Repeat": r.get("Repeat",""), "Note": r.get("Note","")
        })
    return pd.DataFrame(rows, columns=_V232_PLAN_COLS).astype(str)

def _v233_process_solvent_rows(self, working_ml):
    # Process solvent estimates using the same working mL basis.
    rows = []
    scale = _v232_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2,0.2)
    copies = max(1, int(round(_v232_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1,1))))
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self,"pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    steps = [
        ("swell", "DMF" if "Amide" in resin or "합성용" in resin else "DCM", 1, "swell = working mL × 1"),
        ("deprotection", "20% piperidine/DMF", 2, "deprotection = working mL × 2"),
        ("wash", "DMF", 6, "DMF wash = working mL × 6"),
        ("final wash", "DCM", 3, "DCM final wash = working mL × 3"),
    ]
    for phase, solvent, count, note in steps:
        total_ml = working_ml * count * copies
        try:
            splits = self._split_solution_name(solvent, total_ml)
        except Exception:
            splits = [(solvent, total_ml, "")]
        for sname, sml, snote in splits:
            mw, den = _v228_lookup(self, sname) if "_v228_lookup" in globals() else ("","")
            rows.append({"step":phase,"material":sname,"class":"Process solvent","MW":mw,"Density(g/mL)":den,
                         "Eq/mmol":"","Amount":f"{_v232_s(round(_v232_f(sml,0),4))} mL",
                         "_mmol":0.0,"_g":0.0,"_mL":_v232_f(sml,0),
                         "use_count":str(count),"repeat":"","phase":phase,
                         "note":snote or note,"source":"SPPS working mL rule"})
    return rows

def _v233_materials_detailed(self):
    if not _v233_has_sequence(self):
        return _v233_empty_material_df()
    # Mostly v232, but with v233 detailed plan and process solvent basis.
    plan = _v233_plan_detailed(self)
    out = []
    scale = _v232_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2,0.2)
    copies = max(1, int(round(_v232_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1,1))))
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self,"pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    loading = _v232_f(self.pm_loading.get() if hasattr(self,"pm_loading") else 0, 0)
    resin_g = scale*copies/loading if loading else 0
    out.append({"step":"resin","material":resin,"class":"Resin","MW":"N/A","Density(g/mL)":"N/A",
                "Eq/mmol":_v232_eq_scale_mmol(1, scale, 1, copies),
                "Amount":f"{_v232_s(round(resin_g,4))} g" if resin_g else "",
                "_mmol":scale*copies,"_g":resin_g,"_mL":0.0,"use_count":_v232_s(copies),"repeat":"","phase":"resin",
                "note":"resin_g = scale_mmol × copies / resin_loading_mmol_g","source":"Project Manager"})
    for _, r in plan.iterrows():
        step = r.get("No",""); rep = max(1, int(round(_v232_f(r.get("Repeat"),1))))
        unit = str(r.get("Unit name","")); eq = _v232_f(r.get("Unit eq"),0)
        mmol = scale*copies*eq*rep
        g = _v232_f(r.get("Unit amount(g)"),0); ml = _v232_f(r.get("Unit volume(mL)"),0)
        out.append({"step":step,"material":unit,"class":"AA/Chemical","MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                    "Eq/mmol":_v232_eq_scale_mmol(eq, scale, rep, copies),
                    "Amount":_v232_amount(unit,g,ml,r.get("Density(g/mL)","")),
                    "_mmol":mmol,"_g":g,"_mL":ml,"use_count":_v232_s(copies),"repeat":_v232_s(rep),"phase":"coupling","note":r.get("Note",""),"source":"Selected Plan"})
        for name_col,prefix,cls in [("Coupling reagent 1","Reagent 1","Coupling reagent"),("Coupling reagent 2 / catalyst","Reagent 2","Catalyst/additive"),("Coupling base","Base","Base")]:
            name = str(r.get(name_col,"")).strip()
            if not name: continue
            mw, den = _v228_lookup(self, name) if "_v228_lookup" in globals() else ("","")
            eqv = r.get(f"{prefix} eq",""); mm = _v232_f(r.get(f"{prefix} mmol"),0); g = _v232_f(r.get(f"{prefix} g"),0); ml = _v232_f(r.get(f"{prefix} mL"),0)
            if mm == 0 and g == 0 and ml == 0:
                continue
            out.append({"step":step,"material":name,"class":cls,"MW":mw,"Density(g/mL)":den,
                        "Eq/mmol":_v232_eq_scale_mmol(eqv, scale, rep, copies),
                        "Amount":_v232_amount(name,g,ml,den),"_mmol":mm,"_g":g,"_mL":ml,"use_count":_v232_s(copies),"repeat":_v232_s(rep),
                        "phase":"coupling reagent/base","note":f"{name_col}; step {step}","source":"Selected Plan"})
        # coupling solution solvent
        solv = str(r.get("Coupling cocktail solvent","")).strip()
        vol = _v232_f(r.get("Coupling cocktail volume(mL)"),0)*copies*rep
        is_hbtu = str(r.get("Coupling reagent 1","")).strip().upper()=="HBTU" and "NMP" in solv.upper()
        if is_hbtu and vol:
            nmp_mmol = 0.8*vol
            nmp_g = nmp_mmol*99.13/1000.0
            nmp_ml = nmp_g/1.028
            dmf_ml = max(vol-nmp_ml,0)
            for name, mlv, note in [("NMP", nmp_ml, "0.8 M NMP in DMF-based HBTU/NMP solution"), ("DMF", dmf_ml, "DMF diluent for HBTU/NMP solution")]:
                mw, den = _v228_lookup(self,name) if "_v228_lookup" in globals() else ("","")
                out.append({"step":step,"material":name,"class":"Coupling solution solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"","Amount":f"{_v232_s(round(mlv,4))} mL",
                            "_mmol":0.0,"_g":0.0,"_mL":mlv,"use_count":_v232_s(copies),"repeat":_v232_s(rep),"phase":"HBTU/NMP prep","note":note,"source":"HBTU/NMP solution rule"})
        elif solv and vol:
            try: splits = self._split_solution_name(solv, vol)
            except Exception: splits = [(solv,vol,"")]
            for sname,sml,snote in splits:
                mw, den = _v228_lookup(self,sname) if "_v228_lookup" in globals() else ("","")
                out.append({"step":step,"material":sname,"class":"Coupling solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"","Amount":f"{_v232_s(round(_v232_f(sml,0),4))} mL",
                            "_mmol":0.0,"_g":0.0,"_mL":_v232_f(sml,0),"use_count":_v232_s(copies),"repeat":_v232_s(rep),"phase":"coupling solvent","note":snote or f"{solv}; step {step}","source":"Selected Plan"})
    out.extend(_v233_process_solvent_rows(self, _v233_working_ml(self)))
    if "_v232_cleavage_rows" in globals():
        out.extend(_v232_cleavage_rows(self))
    return pd.DataFrame(out)

def _v233_material_display_df(self):
    if not _v233_has_sequence(self):
        return _v233_empty_material_df()
    df = _v233_materials_detailed(self)
    return df[_V230_MAT_COLS].astype(str) if "_V230_MAT_COLS" in globals() else df.astype(str)

def _v233_total_df(self):
    if not _v233_has_sequence(self):
        return _v233_empty_total_df()
    df = _v233_materials_detailed(self)
    if df.empty: return _v233_empty_total_df()
    for c in ["_mmol","_g","_mL"]:
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0)
    grp = df.groupby(["material"], dropna=False).agg({"class":"first","MW":"first","Density(g/mL)":"first","_mmol":"sum","_g":"sum","_mL":"sum","note":"first"}).reset_index()
    rows = []
    for _, r in grp.iterrows():
        amount = _v232_amount(r.get("material",""), round(float(r.get("_g",0)),4) if float(r.get("_g",0)) else "", round(float(r.get("_mL",0)),4) if float(r.get("_mL",0)) else "", r.get("Density(g/mL)",""))
        rows.append({"material":r.get("material",""),"class":r.get("class",""),"MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                     "total mmol":_v232_s(round(float(r.get("_mmol",0)),4) if float(r.get("_mmol",0)) else ""),
                     "total amount":amount,"note":r.get("note","")})
    return pd.DataFrame(rows, columns=_V232_TOTAL_COLS).astype(str)

def _v233_write_tree(self, tree, df):
    cols = list(df.columns)
    tree.configure(columns=cols, show="headings")
    widths = {
        "No":55,"Unit name":230,"MW":80,"Density(g/mL)":125,
        "Unit eq×scale→mmol":170,"Reagent 1 eq×scale→mmol":185,"Reagent 2 eq×scale→mmol":185,"Base eq×scale→mmol":170,
        "Unit amount":120,"Reagent 1 amount":125,"Reagent 2 amount":125,"Base amount":120,
        "Coupling reagent 1":155,"Coupling reagent 2":155,"Coupling base":130,"Coupling cocktail solvent":170,"Solvent mL":100,
        "Repeat":70,"Note":300,"material":220,"class":170,"Eq/mmol":185,"Amount":135,"phase":160,"note":300,"source":190,
        "total amount":150,"total mmol":110
    }
    for c in cols:
        tree.heading(c, text=c)
        # user preference: fluid columns, not fixed. Keep minimum for readability and horizontal scrollbar from original tree.
        tree.column(c, width=widths.get(c,140), minwidth=70, anchor="w", stretch=True)
    for iid in list(tree.get_children()):
        tree.delete(iid)
    for _, row in df.iterrows():
        tree.insert("", "end", values=[_v232_s(row.get(c,"")) for c in cols])

def _v233_refresh(self, commit=False):
    if commit and "_v228_commit_overrides" in globals():
        _v228_commit_overrides(self)
    _v233_write_tree(self, self.pm_selected_plan_tree, _v233_plan_display_df(self))
    _v233_write_tree(self, self.pm_selected_material_tree, _v233_material_display_df(self))
    if "_v228_ensure_total_tab" in globals():
        _v228_ensure_total_tab(self)
    if hasattr(self, "pm_selected_total_tree"):
        _v233_write_tree(self, self.pm_selected_total_tree, _v233_total_df(self))
    try:
        if _v233_has_sequence(self):
            _v217_refresh_selected_checklist(self)
        else:
            # blank state: clear checklist tree if present
            tree = getattr(self, "pm_selected_check_tree", None)
            if tree is not None:
                for iid in list(tree.get_children()):
                    tree.delete(iid)
    except Exception: pass
    try: self.refresh_batch_workspace_preview()
    except Exception: pass
    try: self.schedule_autosave()
    except Exception: pass

def _v233_generate(self):
    try:
        if "_v232_add_grouped_controls" in globals(): _v232_add_grouped_controls(self)
        if "_v232_force_resin_loading_entry" in globals(): _v232_force_resin_loading_entry(self)
        if "_v228_set_resin_dropdowns" in globals(): _v228_set_resin_dropdowns(self)
        try: _v217_save_editor_to_pm_item(self)
        except Exception: pass
        _v233_refresh(self, commit=False)
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v233_apply_plan(self):
    try:
        _v233_refresh(self, commit=True)
        self.save_autosave_state()
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass

try: _v233_old_build = SPPSGui._build
except Exception: _v233_old_build = None

def _v233_build(self):
    if _v233_old_build: _v233_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        # blank is natural; do not inject placeholder sequence
        try:
            if hasattr(self, "pm_sequence") and str(self.pm_sequence.get()).strip() == "Ac-EEMQRR-NH2":
                self.pm_sequence.set("")
            if hasattr(self, "seq") and str(self.seq.get()).strip() == "Ac-EEMQRR-NH2":
                self.seq.set("")
        except Exception:
            pass
        if "_v232_add_grouped_controls" in globals(): _v232_add_grouped_controls(self)
        if "_v232_force_resin_loading_entry" in globals(): _v232_force_resin_loading_entry(self)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v233_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception: pass
                walk(c)
        walk(self)
    except Exception: pass

SPPSGui.pm_generate_selected = _v233_generate
SPPSGui.pm_calculate_all = _v233_generate
