    try:
        if hasattr(self, "pm_sequence") and not str(self.pm_sequence.get() or "").strip():
            self.pm_sequence.set(_V234_DEFAULT_SEQUENCE)
    except Exception:
        pass
    try:
        if hasattr(self, "seq") and not str(self.seq.get() or "").strip():
            self.seq.set(_V234_DEFAULT_SEQUENCE)
    except Exception:
        pass

