# ======================= V2.0.36 FROM V2.0.35: SIMPLE DEFAULT/RANGE + SCROLL + mmol DISPLAY =======================
# Based directly on V2.0.35.
# User feedback target:
# - Make controls simpler: one Default block and one Range block in Unit defaults; same in Reagents.
# - Do not show eq×scale formula in Selected Plan; show calculated mmol only.
# - Keep MW/Density preset visible for unit and also reagent/catalyst/base rows.
# - Restore bottom horizontal scroll usability by using non-stretch columns with xscrollbars.
# - Keep resin loading entry, material-name total merge, SPPS working mL, and cleavage split/formula.
# - No placeholder sequence injection; blank state is allowed and does not error.
# ===============================================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V236_PLAN_COLS = [
    "No","Unit name","MW","Density(g/mL)","Unit mmol","Unit amount",
    "Reagent 1","R1 MW","R1 Density","R1 mmol","R1 amount",
    "Reagent 2 / catalyst","R2 MW","R2 Density","R2 mmol","R2 amount",
    "Base","Base MW","Base Density","Base mmol","Base amount",
    "Coupling solvent","Solvent mL","Repeat","Note"
]
_V236_TOTAL_COLS = ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]

def _v236_f(v, default=0.0):
    try:
        if callable(v) or v is None or str(v).strip() == "":
            return default
        return float(str(v).replace(",", "").strip())
    except Exception:
        return default

def _v236_s(v):
    try:
        if pd.isna(v): return ""
    except Exception:
        pass
    if isinstance(v, float):
        return f"{v:.4f}".rstrip("0").rstrip(".")
    return "" if v is None else str(v)

def _v236_lookup(self, name):
    if "_v228_lookup" in globals():
        return _v228_lookup(self, name)
    return "", ""

def _v236_amount(name, g="", ml="", density=""):
    if "_v230_amount" in globals():
        return _v230_amount(name, g, ml, density)
    return f"{_v236_s(g)} g" if str(g).strip() else ""

def _v236_has_seq(self):
    try:
        seq = str(self.pm_sequence.get() or "").strip()
    except Exception:
        return False
    if not seq:
        return False
    try:
        return bool(_v228_tokens(self)) if "_v228_tokens" in globals() else True
    except Exception:
        cleaned = re.sub(r"(?i)Ac|NH2|COOH|OH", "", seq)
        return any(ch.upper() in "ARNDCQEGHILKMFPSTWYV" for ch in cleaned)

def _v236_hide_old_rule_ui(self):
    # Hide previous complicated controls. Do not destroy variables/functions.
    hide_fragments = [
        "AA eq control", "AA repeat control", "Reagent 1 eq control", "Reagent 1 count/repeat control",
        "Catalyst eq control", "Catalyst count/repeat control", "Base eq control", "Base count/repeat control",
        "Use Default AA eq", "Use AA eq range", "Use Default AA repeat", "Use AA repeat/doubling range",
        "Use Reagent 1 eq", "Tie to AA range eq", "Use Reagent 1 count", "Follow AA repeat",
        "Use Catalyst eq", "Use Catalyst count", "Use Base eq", "Use Base count",
        "same range controls as AA", "AA repeat range", "AA eq range"
    ]
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    text = str(c.cget("text"))
                    if any(h in text for h in hide_fragments):
                        c.grid_remove()
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v236_add_simple_controls(self):
    _v236_hide_old_rule_ui(self)
    if not hasattr(self, "unit_calc_mode"):
        self.unit_calc_mode = tk.StringVar(value="default")  # default or range
    if not hasattr(self, "reagent_calc_mode"):
        self.reagent_calc_mode = tk.StringVar(value="default")  # default or range/tied
    if not hasattr(self, "rule_eq_rules"):
        self.rule_eq_rules = tk.StringVar(value="")
    if not hasattr(self, "rule_repeat_rules"):
        self.rule_repeat_rules = tk.StringVar(value="")
    try:
        nb = None
        def walk(w):
            nonlocal nb
            if nb is not None: return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Notebook):
                        texts = [str(c.tab(t, "text")) for t in c.tabs()]
                        if "Unit defaults" in texts and "Reagents" in texts:
                            nb = c; return
                except Exception:
                    pass
                walk(c)
        walk(self)
        if nb is None: return
        for tab_id in list(nb.tabs()):
            try:
                if str(nb.tab(tab_id, "text")) == "Range / Coupling Rules":
                    nb.forget(tab_id)
            except Exception:
                pass
        unit_fr = reagent_fr = None
        for tab_id in nb.tabs():
            try:
                t = str(nb.tab(tab_id, "text"))
                if t == "Unit defaults": unit_fr = nb.nametowidget(tab_id)
                if t == "Reagents": reagent_fr = nb.nametowidget(tab_id)
            except Exception:
                pass

        if unit_fr is not None and not hasattr(self, "_v236_unit_simple_added"):
            self._v236_unit_simple_added = True
            row = 44
            ttk.Separator(unit_fr, orient="horizontal").grid(row=row, column=0, columnspan=8, sticky="ew", pady=(10,4)); row += 1
            default_box = ttk.Labelframe(unit_fr, text="Default AA settings", padding=6)
            default_box.grid(row=row, column=0, columnspan=5, sticky="ew", padx=8, pady=4); row += 1
            ttk.Radiobutton(default_box, text="Use Default AA eq/repeat", variable=self.unit_calc_mode, value="default").grid(row=0, column=0, sticky="w", padx=6)
            ttk.Label(default_box, text="Uses Default AA eq and Default AA repeat above").grid(row=0, column=1, sticky="w", padx=8)
            range_box = ttk.Labelframe(unit_fr, text="Range AA settings", padding=6)
            range_box.grid(row=row, column=0, columnspan=5, sticky="ew", padx=8, pady=4); row += 1
            ttk.Radiobutton(range_box, text="Use AA range eq/repeat", variable=self.unit_calc_mode, value="range").grid(row=0, column=0, sticky="w", padx=6)
            ttk.Label(range_box, text="Eq range").grid(row=1, column=0, sticky="w", padx=6, pady=2)
            ttk.Entry(range_box, textvariable=self.rule_eq_rules, width=42).grid(row=1, column=1, sticky="ew", padx=6, pady=2)
            ttk.Label(range_box, text="ex) 2-10:3, 11-20:5").grid(row=1, column=2, sticky="w", padx=6)
            ttk.Label(range_box, text="Repeat range").grid(row=2, column=0, sticky="w", padx=6, pady=2)
            ttk.Entry(range_box, textvariable=self.rule_repeat_rules, width=42).grid(row=2, column=1, sticky="ew", padx=6, pady=2)
            ttk.Label(range_box, text="ex) 18-25:2").grid(row=2, column=2, sticky="w", padx=6)
            range_box.columnconfigure(1, weight=1)

        if reagent_fr is not None and not hasattr(self, "_v236_reagent_simple_added"):
            self._v236_reagent_simple_added = True
            row = 44
            ttk.Separator(reagent_fr, orient="horizontal").grid(row=row, column=0, columnspan=8, sticky="ew", pady=(10,4)); row += 1
            default_box = ttk.Labelframe(reagent_fr, text="Default reagent settings", padding=6)
            default_box.grid(row=row, column=0, columnspan=5, sticky="ew", padx=8, pady=4); row += 1
            ttk.Radiobutton(default_box, text="Use Reagent/Catalyst/Base defaults", variable=self.reagent_calc_mode, value="default").grid(row=0, column=0, sticky="w", padx=6)
            ttk.Label(default_box, text="Uses Reagent 1 eq/count, Catalyst eq/count, Base eq/count above").grid(row=0, column=1, sticky="w", padx=8)
            range_box = ttk.Labelframe(reagent_fr, text="Range-linked reagent settings", padding=6)
            range_box.grid(row=row, column=0, columnspan=5, sticky="ew", padx=8, pady=4); row += 1
            ttk.Radiobutton(range_box, text="Tie Reagent/Catalyst/Base to AA range", variable=self.reagent_calc_mode, value="range").grid(row=0, column=0, sticky="w", padx=6)
            ttk.Label(range_box, text="Uses Unit defaults → Range AA settings").grid(row=0, column=1, sticky="w", padx=8)
    except Exception:
        pass

def _v236_force_resin_loading(self):
    try:
        if "_v232_force_resin_loading_entry" in globals():
            _v232_force_resin_loading_entry(self)
        def remove_orphan(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label) and str(c.cget("text")).strip() == "mmol/g":
                        c.grid_remove()
                except Exception:
                    pass
                remove_orphan(c)
        remove_orphan(self)
    except Exception:
        pass

def _v236_default_seq_behavior(self):
    # No placeholder injection. If old default exists, keep it only when user already has it;
    # do not auto-fill blank values.
    try:
        if hasattr(self, "pm_sequence") and str(self.pm_sequence.get()).strip() == "Ac-EEMQRR-NH2":
            pass
    except Exception:
        pass

def _v236_parse_rules(text):
    if "_v228_parse_range_rules" in globals():
        return _v228_parse_range_rules(text)
    out = []
    for p in re.split(r"[,;\n]+", str(text or "")):
        m = re.match(r"^\s*(\d+)\s*[-~]\s*(\d+)\s*[:=]\s*([0-9.]+)\s*$", p.strip())
        if m:
            a,b,v = int(m.group(1)), int(m.group(2)), float(m.group(3))
            if b < a: a,b = b,a
            out.append((a,b,v))
    return out

def _v236_range_value(text, step, default):
    try:
        st = int(float(step))
        for a,b,v in _v236_parse_rules(text):
            if a <= st <= b:
                return v
    except Exception:
        pass
    return default

def _v236_unit_eq(self, step):
    default = _v236_f(getattr(self, "default_reagent_eq", _v225_const_var("10")).get(), 10)
    try:
        if self.unit_calc_mode.get() == "range":
            return _v236_range_value(self.rule_eq_rules.get(), step, default)
    except Exception:
        pass
    return default

def _v236_unit_repeat(self, step):
    default = max(1, int(round(_v236_f(getattr(self, "default_repeat", _v225_const_var("1")).get(), 1))))
    try:
        if self.unit_calc_mode.get() == "range":
            return max(1, int(round(_v236_range_value(self.rule_repeat_rules.get(), step, default))))
    except Exception:
        pass
    return default

def _v236_reagent_eq(self, step, default):
    try:
        if self.reagent_calc_mode.get() == "range":
            return _v236_unit_eq(self, step)
    except Exception:
        pass
    return default

def _v236_reagent_count(self, step, default):
    try:
        if self.reagent_calc_mode.get() == "range":
            return _v236_unit_repeat(self, step)
    except Exception:
        pass
    return max(1, int(round(_v236_f(default, 1))))

def _v236_working_ml(self):
    if "_v235_solvent_ml_for_scale" in globals():
        return float(_v235_solvent_ml_for_scale(self))
    if "_v233_working_ml" in globals():
        ml = _v233_working_ml(self)
        return float(ml) if not callable(ml) else 3.0
    return 3.0

def _v236_plan_detailed(self):
    if not _v236_has_seq(self):
        return pd.DataFrame(columns=_V229_PLAN_COLS if "_V229_PLAN_COLS" in globals() else [])
    base = _v229_plan_df(self).copy() if "_v229_plan_df" in globals() else pd.DataFrame()
    scale = _v236_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2)
    copies = max(1, int(round(_v236_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))))
    solvent_ml = _v236_working_ml(self)
    for i, r in base.iterrows():
        step = r.get("No","")
        note = str(r.get("Note","")).lower()
        direct = "direct loading" in note
        if direct:
            eq = _v236_f(r.get("Unit eq"), 2)
            repeat = 1
        else:
            eq = _v236_unit_eq(self, step)
            repeat = _v236_unit_repeat(self, step)
        base.at[i, "Unit eq"] = _v236_s(eq)
        base.at[i, "Repeat"] = _v236_s(repeat)
        mw = _v236_f(r.get("MW"), 0)
        base.at[i, "Unit amount(g)"] = _v236_s(round(eq * scale * copies * repeat * mw / 1000.0, 4) if mw else "")
        base.at[i, "Coupling cocktail volume(mL)"] = _v236_s(round(solvent_ml, 4))
        # reagent eq/count mode
        r1_default_eq = _v236_f(getattr(self, "default_reagent_eq", _v225_const_var("10")).get(), 10)
        r2_default_eq = _v236_f(getattr(self, "default_catalyst_eq", _v225_const_var("10")).get(), 10)
        b_default_eq = _v236_f(getattr(self, "default_base_eq", _v225_const_var("5")).get(), 5)
        r1_count = _v236_reagent_count(self, step, getattr(self, "default_reagent_count", _v225_const_var("1")).get() if hasattr(self, "default_reagent_count") else 1)
        r2_count = _v236_reagent_count(self, step, getattr(self, "default_catalyst_count", _v225_const_var("1")).get() if hasattr(self, "default_catalyst_count") else 1)
        b_count = _v236_reagent_count(self, step, getattr(self, "default_base_count", _v225_const_var("1")).get() if hasattr(self, "default_base_count") else 1)
        vals = [
            ("Reagent 1", "Coupling reagent 1", _v236_reagent_eq(self, step, r1_default_eq), r1_count),
            ("Reagent 2", "Coupling reagent 2 / catalyst", _v236_reagent_eq(self, step, r2_default_eq), r2_count),
            ("Base", "Coupling base", (_v236_f(getattr(self, "loading_diea_eq", _v225_const_var("4")).get(), 4) if direct else _v236_reagent_eq(self, step, b_default_eq)), b_count),
        ]
        for prefix, name_col, eqv, cnt in vals:
            name = str(base.at[i, name_col]) if name_col in base.columns else ""
            if not name:
                continue
            total_repeat = repeat * cnt
            if "_v229_calc_reagent_amount" in globals():
                eq_s, mmol_s, g_s, ml_s, _ = _v229_calc_reagent_amount(self, name, eqv, scale, copies, total_repeat)
            else:
                mw2, den2 = _v236_lookup(self, name)
                mmol = eqv * scale * copies * total_repeat
                g = mmol * _v236_f(mw2,0)/1000.0 if mw2 else 0
                ml = g / _v236_f(den2,1) if g and den2 else 0
                eq_s, mmol_s, g_s, ml_s = _v236_s(eqv), _v236_s(mmol), _v236_s(g), _v236_s(ml)
            base.at[i, f"{prefix} eq"] = eq_s
            base.at[i, f"{prefix} mmol"] = mmol_s
            base.at[i, f"{prefix} g"] = g_s
            base.at[i, f"{prefix} mL"] = ml_s
    return base.astype(str)

def _v236_plan_display_df(self):
    if not _v236_has_seq(self):
        return pd.DataFrame(columns=_V236_PLAN_COLS)
    base = _v236_plan_detailed(self)
    rows = []
    for _, r in base.iterrows():
        def rd(prefix, namecol):
            name = str(r.get(namecol, "")).strip()
            mw, den = _v236_lookup(self, name) if name else ("","")
            mmol = r.get(f"{prefix} mmol", "")
            g = r.get(f"{prefix} g", "")
            ml = r.get(f"{prefix} mL", "")
            return name, mw, den, mmol, _v236_amount(name, g, ml, den)
        r1n,r1mw,r1d,r1mm,r1amt = rd("Reagent 1", "Coupling reagent 1")
        r2n,r2mw,r2d,r2mm,r2amt = rd("Reagent 2", "Coupling reagent 2 / catalyst")
        bn,bmw,bd,bmm,bamt = rd("Base", "Coupling base")
        scale = _v236_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2, 0.2)
        copies = max(1, int(round(_v236_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1, 1))))
        repeat = max(1, int(round(_v236_f(r.get("Repeat"), 1))))
        unit_mmol = _v236_f(r.get("Unit eq"),0) * scale * copies * repeat
        rows.append({
            "No": r.get("No",""),
            "Unit name": r.get("Unit name",""),
            "MW": r.get("MW",""),
            "Density(g/mL)": r.get("Density(g/mL)",""),
            "Unit mmol": _v236_s(round(unit_mmol,4)),
            "Unit amount": _v236_amount(r.get("Unit name",""), r.get("Unit amount(g)",""), r.get("Unit volume(mL)",""), r.get("Density(g/mL)","")),
            "Reagent 1": r1n, "R1 MW": r1mw, "R1 Density": r1d, "R1 mmol": r1mm, "R1 amount": r1amt,
            "Reagent 2 / catalyst": r2n, "R2 MW": r2mw, "R2 Density": r2d, "R2 mmol": r2mm, "R2 amount": r2amt,
            "Base": bn, "Base MW": bmw, "Base Density": bd, "Base mmol": bmm, "Base amount": bamt,
            "Coupling solvent": r.get("Coupling cocktail solvent",""),
            "Solvent mL": r.get("Coupling cocktail volume(mL)",""),
            "Repeat": r.get("Repeat",""),
            "Note": r.get("Note","")
        })
    return pd.DataFrame(rows, columns=_V236_PLAN_COLS).astype(str)

def _v236_cleavage_rows(self):
    scale = _v236_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2, 0.2)
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self,"pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    try:
        aa_count = len(_v228_tokens(self)); cys_count = sum(1 for x in _v228_tokens(self) if x == "C")
    except Exception:
        aa_count = 0; cys_count = 0
    xeq = 100 if aa_count >= 22 else 80 if aa_count >= 15 else 30
    xeq += 100*cys_count
    # user rule: trityl/2-CTC total basis = resin scale/2 * x eq, amide/preloaded = resin scale * x eq
    basis = scale/2.0 if ("2-CTC" in resin or "Trityl" in resin) and "합성용" not in resin else scale
    tfa_mmol = basis * xeq
    tfa_g = tfa_mmol * 114.02 / 1000.0
    tfa_ml = tfa_g / 1.489 if tfa_g else 0
    total_ml = tfa_ml / 0.95 if tfa_ml else 0
    rows = []
    for name, frac in [("TFA",0.95),("TIS",0.025),("Water",0.025)]:
        mw, den = _v236_lookup(self, name)
        ml = total_ml * frac
        mmol = (ml * _v236_f(den,0) * 1000.0 / _v236_f(mw,1)) if mw and den else 0
        rows.append({"step":"cleavage","material":name,"class":"Cleavage cocktail","MW":mw,"Density(g/mL)":den,
                     "Eq/mmol": _v236_s(round(mmol,4)) + " mmol",
                     "Amount": f"{_v236_s(round(ml,4))} mL" if ml else "",
                     "_mmol":mmol,"_g":0.0,"_mL":ml,"use_count":"1","repeat":"","phase":"cleavage",
                     "note":"Cleavage total V basis: 2-CTC/trityl=(scale/2)*x eq, amide/preloaded=scale*x eq; TFA:TIS:DW=0.95:0.025:0.025",
                     "source":"Cleavage recommendation"})
    return rows

def _v236_process_solvent_rows(self, working_ml):
    # Preserve v2.33 working volume concept.
    if "_v233_process_solvent_rows" in globals():
        return _v233_process_solvent_rows(self, working_ml)
    return []

def _v236_materials_detailed(self):
    if not _v236_has_seq(self):
        return pd.DataFrame(columns=_V230_MAT_COLS if "_V230_MAT_COLS" in globals() else [])
    plan = _v236_plan_detailed(self)
    out = []
    scale = _v236_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2, 0.2)
    copies = max(1, int(round(_v236_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1, 1))))
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self,"pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    loading = _v236_f(self.pm_loading.get() if hasattr(self,"pm_loading") else 0, 0)
    resin_g = scale*copies/loading if loading else 0
    out.append({"step":"resin","material":resin,"class":"Resin","MW":"N/A","Density(g/mL)":"N/A","Eq/mmol":_v236_s(round(scale*copies,4))+" mmol",
                "Amount":f"{_v236_s(round(resin_g,4))} g" if resin_g else "",
                "_mmol":scale*copies,"_g":resin_g,"_mL":0.0,"use_count":_v236_s(copies),"repeat":"","phase":"resin",
                "note":"resin_g = scale_mmol × copies / resin_loading_mmol_g","source":"Project Manager"})
    for _, r in plan.iterrows():
        step = r.get("No",""); rep = max(1, int(round(_v236_f(r.get("Repeat"),1))))
        unit = str(r.get("Unit name","")); eq = _v236_f(r.get("Unit eq"),0)
        mmol = scale*copies*eq*rep
        g = _v236_f(r.get("Unit amount(g)"),0); ml = _v236_f(r.get("Unit volume(mL)"),0)
        out.append({"step":step,"material":unit,"class":"AA/Chemical","MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                    "Eq/mmol":_v236_s(round(mmol,4))+" mmol","Amount":_v236_amount(unit,g,ml,r.get("Density(g/mL)","")),
                    "_mmol":mmol,"_g":g,"_mL":ml,"use_count":_v236_s(copies),"repeat":_v236_s(rep),"phase":"coupling","note":r.get("Note",""),"source":"Selected Plan"})
        for name_col,prefix,cls in [("Coupling reagent 1","Reagent 1","Coupling reagent"),("Coupling reagent 2 / catalyst","Reagent 2","Catalyst/additive"),("Coupling base","Base","Base")]:
            name = str(r.get(name_col,"")).strip()
            if not name: continue
            mw, den = _v236_lookup(self, name)
            mm = _v236_f(r.get(f"{prefix} mmol"),0); g = _v236_f(r.get(f"{prefix} g"),0); ml = _v236_f(r.get(f"{prefix} mL"),0)
            if mm == 0 and g == 0 and ml == 0: continue
            out.append({"step":step,"material":name,"class":cls,"MW":mw,"Density(g/mL)":den,
                        "Eq/mmol":_v236_s(round(mm,4))+" mmol","Amount":_v236_amount(name,g,ml,den),
                        "_mmol":mm,"_g":g,"_mL":ml,"use_count":_v236_s(copies),"repeat":_v236_s(rep),
                        "phase":"coupling reagent/base","note":f"{name_col}; step {step}","source":"Selected Plan"})
        # Coupling solvent / HBTU-NMP-DMF
        solv = str(r.get("Coupling cocktail solvent","")).strip()
        vol = _v236_f(r.get("Coupling cocktail volume(mL)"),0)*copies*rep
        is_hbtu = str(r.get("Coupling reagent 1","")).strip().upper()=="HBTU" and "NMP" in solv.upper()
        if is_hbtu and vol:
            nmp_mmol = 0.8*vol
            nmp_g = nmp_mmol*99.13/1000.0
            nmp_ml = nmp_g/1.028
            dmf_ml = max(vol-nmp_ml,0)
            for name, mlv, note in [("NMP",nmp_ml,"0.8 M NMP in DMF-based HBTU/NMP solution"),("DMF",dmf_ml,"DMF diluent for HBTU/NMP solution")]:
                mw, den = _v236_lookup(self, name)
                out.append({"step":step,"material":name,"class":"Coupling solution solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"",
                            "Amount":f"{_v236_s(round(mlv,4))} mL","_mmol":0.0,"_g":0.0,"_mL":mlv,
                            "use_count":_v236_s(copies),"repeat":_v236_s(rep),"phase":"HBTU/NMP prep","note":note,"source":"HBTU/NMP solution rule"})
        elif solv and vol:
            try: splits = self._split_solution_name(solv, vol)
            except Exception: splits = [(solv,vol,"")]
            for sname,sml,snote in splits:
                mw, den = _v236_lookup(self, sname)
                out.append({"step":step,"material":sname,"class":"Coupling solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"",
                            "Amount":f"{_v236_s(round(_v236_f(sml,0),4))} mL","_mmol":0.0,"_g":0.0,"_mL":_v236_f(sml,0),
                            "use_count":_v236_s(copies),"repeat":_v236_s(rep),"phase":"coupling solvent","note":snote or f"{solv}; step {step}","source":"Selected Plan"})
    out.extend(_v236_process_solvent_rows(self, _v236_working_ml(self)))
    out.extend(_v236_cleavage_rows(self))
    return pd.DataFrame(out)

def _v236_material_display_df(self):
    if not _v236_has_seq(self):
        return pd.DataFrame(columns=_V230_MAT_COLS if "_V230_MAT_COLS" in globals() else [])
    df = _v236_materials_detailed(self)
    return df[_V230_MAT_COLS].astype(str) if "_V230_MAT_COLS" in globals() else df.astype(str)

def _v236_total_df(self):
    if not _v236_has_seq(self):
        return pd.DataFrame(columns=_V236_TOTAL_COLS)
    df = _v236_materials_detailed(self)
    if df.empty: return pd.DataFrame(columns=_V236_TOTAL_COLS)
    for c in ["_mmol","_g","_mL"]:
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0)
    grp = df.groupby(["material"], dropna=False).agg({"class":"first","MW":"first","Density(g/mL)":"first","_mmol":"sum","_g":"sum","_mL":"sum","note":"first"}).reset_index()
    rows = []
    for _, r in grp.iterrows():
        amt = _v236_amount(r.get("material",""), round(float(r.get("_g",0)),4) if float(r.get("_g",0)) else "", round(float(r.get("_mL",0)),4) if float(r.get("_mL",0)) else "", r.get("Density(g/mL)",""))
        rows.append({"material":r.get("material",""),"class":r.get("class",""),"MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                     "total mmol":_v236_s(round(float(r.get("_mmol",0)),4) if float(r.get("_mmol",0)) else ""),
                     "total amount":amt,"note":r.get("note","")})
    return pd.DataFrame(rows, columns=_V236_TOTAL_COLS).astype(str)

def _v236_write_tree(self, tree, df):
    cols = list(df.columns)
    tree.configure(columns=cols, show="headings")
    widths = {"No":55,"Unit name":230,"MW":80,"Density(g/mL)":125,
              "Unit mmol":105,"Unit amount":120,"Reagent 1":130,"R1 MW":80,"R1 Density":95,"R1 mmol":105,"R1 amount":115,
              "Reagent 2 / catalyst":155,"R2 MW":80,"R2 Density":95,"R2 mmol":105,"R2 amount":115,
              "Base":115,"Base MW":80,"Base Density":95,"Base mmol":105,"Base amount":115,
              "Coupling solvent":155,"Solvent mL":95,"Repeat":70,"Note":300,
              "material":220,"class":160,"Eq/mmol":130,"Amount":130,"phase":150,"note":300,"source":190,
              "total mmol":110,"total amount":150}
    for c in cols:
        tree.heading(c, text=c)
        # restore bottom horizontal scrollbar: total requested width intentionally exceeds viewport
        tree.column(c, width=widths.get(c,140), minwidth=70, anchor="w", stretch=False)
    for iid in list(tree.get_children()):
        tree.delete(iid)
    for _, row in df.iterrows():
        tree.insert("", "end", values=[_v236_s(row.get(c,"")) for c in cols])
    try:
        tree.xview_moveto(0)
    except Exception:
        pass

def _v236_refresh(self, commit=False):
    if commit and "_v228_commit_overrides" in globals():
        _v228_commit_overrides(self)
    _v236_write_tree(self, self.pm_selected_plan_tree, _v236_plan_display_df(self))
    _v236_write_tree(self, self.pm_selected_material_tree, _v236_material_display_df(self))
    if "_v228_ensure_total_tab" in globals(): _v228_ensure_total_tab(self)
    if hasattr(self, "pm_selected_total_tree"):
        _v236_write_tree(self, self.pm_selected_total_tree, _v236_total_df(self))
    try:
        if _v236_has_seq(self): _v217_refresh_selected_checklist(self)
    except Exception: pass
    try: self.refresh_batch_workspace_preview()
    except Exception: pass
    try: self.schedule_autosave()
    except Exception: pass

def _v236_generate(self):
    try:
        _v236_add_simple_controls(self)
        _v236_force_resin_loading(self)
        if "_v228_set_resin_dropdowns" in globals(): _v228_set_resin_dropdowns(self)
        try: _v217_save_editor_to_pm_item(self)
        except Exception: pass
        _v236_refresh(self, commit=False)
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v236_apply_plan(self):
    try:
        _v236_refresh(self, commit=True)
        self.save_autosave_state()
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass

try: _v236_old_collect = SPPSGui._collect_state
except Exception: _v236_old_collect = None
try: _v236_old_load = SPPSGui.load_autosave_state
except Exception: _v236_old_load = None
try: _v236_old_build = SPPSGui._build
except Exception: _v236_old_build = None

def _v236_collect_state(self):
    state = _v236_old_collect(self) if _v236_old_collect else {}
    try:
        state["unit_calc_mode"] = self.unit_calc_mode.get() if hasattr(self, "unit_calc_mode") else "default"
        state["reagent_calc_mode"] = self.reagent_calc_mode.get() if hasattr(self, "reagent_calc_mode") else "default"
        state["rule_eq_rules"] = self.rule_eq_rules.get() if hasattr(self, "rule_eq_rules") else ""
        state["rule_repeat_rules"] = self.rule_repeat_rules.get() if hasattr(self, "rule_repeat_rules") else ""
    except Exception: pass
    return state

def _v236_load_state(self):
    try:
        if _v236_old_load: _v236_old_load(self)
    except Exception: pass
    try:
        _v236_add_simple_controls(self)
        if self.state_file.exists():
            st = json.loads(self.state_file.read_text(encoding="utf-8"))
            if hasattr(self, "unit_calc_mode"): self.unit_calc_mode.set(st.get("unit_calc_mode","default"))
            if hasattr(self, "reagent_calc_mode"): self.reagent_calc_mode.set(st.get("reagent_calc_mode","default"))
            if hasattr(self, "rule_eq_rules"): self.rule_eq_rules.set(st.get("rule_eq_rules",""))
            if hasattr(self, "rule_repeat_rules"): self.rule_repeat_rules.set(st.get("rule_repeat_rules",""))
    except Exception: pass

def _v236_build(self):
    if _v236_old_build: _v236_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        # no placeholder sequence injection here
        _v236_add_simple_controls(self)
        _v236_force_resin_loading(self)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v236_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception: pass
                walk(c)
        walk(self)
    except Exception: pass

SPPSGui.pm_generate_selected = _v236_generate
SPPSGui.pm_calculate_all = _v236_generate
SPPSGui.apply_plan_mw_density = _v236_apply_plan
SPPSGui._collect_state = _v236_collect_state
SPPSGui.load_autosave_state = _v236_load_state
SPPSGui._build = _v236_build
# ======================= END V2.0.36 PATCH =======================



# ======================= V2.0.37 AC/HOBT/CLEAVAGE/EDIT PATCH =======================
# Based directly on V2.0.36.
# Scope:
# 1) UI cleanup: use the simple default/range blocks and hide leftover orphan range rows.
# 2) Ac-/AC- prefix parsing: Ac- or AC- is acetylation only; it must not become Ala+Cys or Ala.
# 3) N-term Ac row includes Ac2O and DIEA. DIEA mmol = Ac2O mmol.
# 4) HOBt Anhydrous and HOBt hydrate are added with correct MW.
# 5) Cleavage cocktail total mL rule:
#    - AEKIRKELEKQ/short peptide: 30-40 eq still allowed by user; default short rule 30 eq.
#    - Ac-EEMQRR-NH2, 300 mmol, 30 eq -> total cocktail 9000 mL.
#    - GHK, 500 mmol, 18 eq -> total cocktail 4500 mL.
#    General: total cocktail mL = basis_mmol * cleavage_eq. TFA/TIS/DW split = 0.95/0.025/0.025.
#    2-CTC/trityl basis = scale/2 unless user selects otherwise; amide/preloaded = scale.
# 6) Selected Plan: unit name can be changed from a dropdown/edit dialog and selected rows can be deleted.
# Existing functions are not removed; later bindings override only the necessary paths.
# ================================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V237_CHEM_MW = {
    "HOBt Anhydrous": 135.12,
    "HOBt hydrate": 153.14,
    "HOBt": 135.12,
    "Acetic anhydride (Ac2O)": 102.09,
    "Ac2O": 102.09,
    "DIEA": 129.25,
    "DIPEA": 129.25,
    "TFA": 114.02,
    "TIS": 132.28,
    "Water": 18.02,
}
_V237_CHEM_DEN = {
    "Acetic anhydride (Ac2O)": 1.08,
    "Ac2O": 1.08,
    "DIEA": 0.742,
    "DIPEA": 0.742,
    "TFA": 1.489,
    "TIS": 0.82,
    "Water": 1.0,
}

def _v237_f(v, default=0.0):
    try:
        if callable(v) or v is None or str(v).strip() == "":
            return default
        return float(str(v).replace(",", "").strip())
    except Exception:
        return default

def _v237_s(v):
    try:
        if pd.isna(v):
            return ""
    except Exception:
        pass
    if isinstance(v, float):
        return f"{v:.4f}".rstrip("0").rstrip(".")
    return "" if v is None else str(v)

def _v237_norm(x):
    return re.sub(r"[^0-9a-z가-힣]+", "", str(x or "").lower())

def _v237_lookup(self, name):
    nm = str(name or "").strip()
    # exact new chemicals first
    if nm in _V237_CHEM_MW:
        return _v237_s(_V237_CHEM_MW[nm]), _v237_s(_V237_CHEM_DEN.get(nm, ""))
    low = _v237_norm(nm)
    if low in {"hobtanhydrous","hobtanhydrate","hobtmonohydrate"}:
        key = "HOBt hydrate" if "hydrate" in low or "mono" in low else "HOBt Anhydrous"
        return _v237_s(_V237_CHEM_MW[key]), _v237_s(_V237_CHEM_DEN.get(key, ""))
    if "_v236_lookup" in globals():
        mw, den = _v236_lookup(self, name)
        if str(mw).strip():
            # normalize old HOBt to anhydrous by default
            if _v237_norm(nm) == "hobt":
                return "135.12", ""
            return mw, den
    if "_v228_lookup" in globals():
        mw, den = _v228_lookup(self, name)
        if str(mw).strip():
            if _v237_norm(nm) == "hobt":
                return "135.12", ""
            return mw, den
    return "", ""

def _v237_has_ac_prefix(seq):
    s = str(seq or "").strip()
    return bool(re.match(r"^\s*(Ac|AC)\s*[-_]", s))

def _v237_strip_ac_prefix(seq):
    return re.sub(r"^\s*(Ac|AC)\s*[-_]\s*", "", str(seq or "").strip(), flags=re.I)

def _v237_tokens(self):
    try:
        raw = str(self.pm_sequence.get() or "")
    except Exception:
        raw = ""
    raw2 = _v237_strip_ac_prefix(raw)
    # Call original parser on string without Ac/AC prefix so AC- never becomes Ala+Cys.
    try:
        if hasattr(self, "_aa_letters_from_sequence"):
            return list(self._aa_letters_from_sequence(raw2))
    except Exception:
        pass
    cleaned = re.sub(r"(?i)NH2|COOH|OH", "", raw2)
    return [ch.upper() for ch in cleaned if ch.upper() in "ARNDCQEGHILKMFPSTWYV"]

def _v237_has_seq(self):
    return bool(_v237_tokens(self))

def _v237_default_seq_behavior(self):
    # Do not inject placeholder. If user typed sequence, use it.
    pass

def _v237_hide_orphan_ui(self):
    # Hide old leftover range labels/entries added by previous patches while keeping simple boxes.
    hide_fragments = [
        "Default AA repeat", "mL per mmol", "ex) 2-10:3, 11-20:5", "ex) 18-25:2",
        "Uses Default AA eq and Default AA repeat above", "Uses Reagent 1 eq/count",
    ]
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    text = str(c.cget("text"))
                    # hide only duplicate labels in lower rows, not original top setup labels
                    info = c.grid_info()
                    row = int(info.get("row", 0)) if info else 0
                    if row >= 40 and any(h == text or h in text for h in hide_fragments):
                        c.grid_remove()
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v237_add_simple_ui(self):
    if "_v236_add_simple_controls" in globals():
        _v236_add_simple_controls(self)
    _v237_hide_orphan_ui(self)

def _v237_aa_name_map():
    return {
        "A":"Fmoc-Ala-OH","R":"Fmoc-Arg(Pbf)-OH","N":"Fmoc-Asn(Trt)-OH","D":"Fmoc-Asp(OtBu)-OH",
        "C":"Fmoc-Cys(Trt)-OH","Q":"Fmoc-Gln(Trt)-OH","E":"Fmoc-Glu(OtBu)-OH","G":"Fmoc-Gly-OH",
        "H":"Fmoc-His(Trt)-OH","I":"Fmoc-Ile-OH","L":"Fmoc-Leu-OH","K":"Fmoc-Lys(Boc)-OH",
        "M":"Fmoc-Met-OH","F":"Fmoc-Phe-OH","P":"Fmoc-Pro-OH","S":"Fmoc-Ser(tBu)-OH",
        "T":"Fmoc-Thr(tBu)-OH","W":"Fmoc-Trp(Boc)-OH","Y":"Fmoc-Tyr(tBu)-OH","V":"Fmoc-Val-OH",
    }

def _v237_unit_eq(self, step):
    return _v236_unit_eq(self, step) if "_v236_unit_eq" in globals() else _v237_f(getattr(self, "default_reagent_eq", _v225_const_var("10")).get(), 10)

def _v237_unit_repeat(self, step):
    return _v236_unit_repeat(self, step) if "_v236_unit_repeat" in globals() else 1

def _v237_reagent_eq(self, step, default):
    return _v236_reagent_eq(self, step, default) if "_v236_reagent_eq" in globals() else default

def _v237_reagent_count(self, step, default):
    return _v236_reagent_count(self, step, default) if "_v236_reagent_count" in globals() else max(1, int(round(_v237_f(default, 1))))

def _v237_working_ml(self):
    if "_v236_working_ml" in globals():
        return float(_v236_working_ml(self))
    if "_v235_solvent_ml_for_scale" in globals():
        return float(_v235_solvent_ml_for_scale(self))
    return 3.0

def _v237_plan_detailed(self):
    if not _v237_has_seq(self):
        return pd.DataFrame(columns=_V229_PLAN_COLS if "_V229_PLAN_COLS" in globals() else [])
    tokens = list(reversed(_v237_tokens(self)))
    aa_map = _v237_aa_name_map()
    scale = _v237_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2)
    copies = max(1, int(round(_v237_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))))
    resin = self.pm_resin.get() if hasattr(self, "pm_resin") else "Rink Amide AM"
    chem = self.pm_chemistry.get() if hasattr(self, "pm_chemistry") else "DIC/HOBt"
    working_ml = _v237_working_ml(self)
    load_on = False
    try:
        load_on = _v228_is_loading_applicable(self, resin)
    except Exception:
        try:
            load_on = _v216_loading_applies(self, resin)
        except Exception:
            load_on = False
    if "HBTU" in str(chem).upper():
        r1, r2, solv = "HBTU", "HOBt Anhydrous", "NMP"
    else:
        r1, r2, solv = "DIC", "HOBt Anhydrous", "DMF"
    rows = []
    for idx, aa in enumerate(tokens, start=1):
        unit = aa_map.get(aa, aa)
        if idx == 1 and load_on:
            eq = _v237_f(getattr(self, "loading_aa_eq", _v225_const_var("2")).get(), 2)
            repeat = 1
            cr1, cr2, base, csolv = "", "", "DIEA", "90% DCM / 10% DMF"
            note = "direct loading first unit"
        else:
            eq = _v237_unit_eq(self, idx)
            repeat = _v237_unit_repeat(self, idx)
            cr1, cr2, base, csolv = r1, r2, "", solv
            note = "Regular AA coupling"
        mw, den = _v237_lookup(self, unit)
        unit_mmol = scale * copies * eq * repeat
        unit_g = unit_mmol * _v237_f(mw, 0) / 1000.0 if mw else 0
        row = {
            "No": _v237_s(idx), "Unit name": unit, "MW": mw, "Density(g/mL)": den,
            "Unit eq": _v237_s(eq), "Unit amount(g)": _v237_s(round(unit_g,4) if unit_g else ""),
            "Unit volume(mL)": "", "Coupling reagent 1": cr1, "Coupling reagent 2 / catalyst": cr2,
            "Coupling base": base, "Coupling cocktail solvent": csolv,
            "Coupling cocktail volume(mL)": _v237_s(round(working_ml,4)), "Repeat": _v237_s(repeat), "Note": note,
        }
        # reagent amounts
        for prefix, name_col, default_eq, count_default in [
            ("Reagent 1", "Coupling reagent 1", _v237_f(getattr(self, "default_reagent_eq", _v225_const_var("10")).get(), 10), getattr(self, "default_reagent_count", _v225_const_var("1")).get() if hasattr(self, "default_reagent_count") else 1),
            ("Reagent 2", "Coupling reagent 2 / catalyst", _v237_f(getattr(self, "default_catalyst_eq", _v225_const_var("10")).get(), 10), getattr(self, "default_catalyst_count", _v225_const_var("1")).get() if hasattr(self, "default_catalyst_count") else 1),
            ("Base", "Coupling base", _v237_f(getattr(self, "loading_diea_eq", _v225_const_var("4")).get(), 4) if base else _v237_f(getattr(self, "default_base_eq", _v225_const_var("5")).get(), 5), getattr(self, "default_base_count", _v225_const_var("1")).get() if hasattr(self, "default_base_count") else 1),
        ]:
            name = row.get(name_col, "")
            if not name:
                row[f"{prefix} eq"] = row[f"{prefix} mmol"] = row[f"{prefix} g"] = row[f"{prefix} mL"] = ""
                continue
            eqv = _v237_reagent_eq(self, idx, default_eq) if prefix != "Base" or base == "" else default_eq
            cnt = _v237_reagent_count(self, idx, count_default)
            mm = scale * copies * eqv * repeat * cnt
            mw2, den2 = _v237_lookup(self, name)
            g = mm * _v237_f(mw2, 0) / 1000.0 if mw2 else 0
            ml = g / _v237_f(den2, 1) if g and den2 else 0
            row[f"{prefix} eq"] = _v237_s(eqv)
            row[f"{prefix} mmol"] = _v237_s(round(mm,4) if mm else "")
            row[f"{prefix} g"] = _v237_s(round(g,4) if g else "")
            row[f"{prefix} mL"] = _v237_s(round(ml,4) if ml else "")
        rows.append(row)
    # N-terminal acetylation when Ac-/AC- prefix exists.
    if _v237_has_ac_prefix(self.pm_sequence.get() if hasattr(self, "pm_sequence") else ""):
        no = len(rows) + 1
        eq = _v237_f(getattr(self, "modifier_eq", _v225_const_var("3")).get(), 3)
        repeat = max(1, int(round(_v237_f(getattr(self, "modifier_repeats", _v225_const_var("1")).get(), 1))))
        ac_mw, ac_den = _v237_lookup(self, "Acetic anhydride (Ac2O)")
        ac_mmol = scale * copies * eq * repeat
        ac_g = ac_mmol * _v237_f(ac_mw, 0) / 1000.0
        ac_ml = ac_g / _v237_f(ac_den, 1) if ac_den else 0
        diea_mw, diea_den = _v237_lookup(self, "DIEA")
        diea_mmol = ac_mmol  # user: same mol count as Ac2O
        diea_g = diea_mmol * _v237_f(diea_mw, 0) / 1000.0
        diea_ml = diea_g / _v237_f(diea_den, 1)
        rows.append({
            "No": _v237_s(no), "Unit name": "Acetic anhydride (Ac2O) for N-terminal acetylation",
            "MW": ac_mw, "Density(g/mL)": ac_den, "Unit eq": _v237_s(eq),
            "Unit amount(g)": _v237_s(round(ac_g,4)), "Unit volume(mL)": _v237_s(round(ac_ml,4)),
            "Coupling reagent 1": "", "Reagent 1 eq": "", "Reagent 1 mmol": "", "Reagent 1 g": "", "Reagent 1 mL": "",
            "Coupling reagent 2 / catalyst": "", "Reagent 2 eq": "", "Reagent 2 mmol": "", "Reagent 2 g": "", "Reagent 2 mL": "",
            "Coupling base": "DIEA", "Base eq": _v237_s(eq), "Base mmol": _v237_s(round(diea_mmol,4)),
            "Base g": _v237_s(round(diea_g,4)), "Base mL": _v237_s(round(diea_ml,4)),
            "Coupling cocktail solvent": "DMF", "Coupling cocktail volume(mL)": _v237_s(round(working_ml,4)),
            "Repeat": _v237_s(repeat), "Note": "N-terminal Ac cap; Ac2O + DIEA same mol",
        })
    return pd.DataFrame(rows).astype(str)

def _v237_plan_display_df(self):
    base = _v237_plan_detailed(self)
    if base.empty:
        return pd.DataFrame(columns=_V236_PLAN_COLS if "_V236_PLAN_COLS" in globals() else [])
    rows = []
    for _, r in base.iterrows():
        def rd(prefix, namecol):
            name = str(r.get(namecol, "")).strip()
            mw, den = _v237_lookup(self, name) if name else ("","")
            mmol = r.get(f"{prefix} mmol", "")
            g = r.get(f"{prefix} g", "")
            ml = r.get(f"{prefix} mL", "")
            amt = _v236_amount(name, g, ml, den) if "_v236_amount" in globals() else (g or ml)
            return name, mw, den, mmol, amt
        r1n,r1mw,r1d,r1mm,r1amt = rd("Reagent 1", "Coupling reagent 1")
        r2n,r2mw,r2d,r2mm,r2amt = rd("Reagent 2", "Coupling reagent 2 / catalyst")
        bn,bmw,bd,bmm,bamt = rd("Base", "Coupling base")
        rows.append({
            "No": r.get("No",""),
            "Unit name": r.get("Unit name",""),
            "MW": r.get("MW",""),
            "Density(g/mL)": r.get("Density(g/mL)",""),
            "Unit mmol": _v237_s(round(_v237_f(r.get("Unit eq"),0) * _v237_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2) * _v237_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1) * max(1,int(round(_v237_f(r.get("Repeat"),1)))),4)),
            "Unit amount": _v236_amount(r.get("Unit name",""), r.get("Unit amount(g)",""), r.get("Unit volume(mL)",""), r.get("Density(g/mL)","")) if "_v236_amount" in globals() else r.get("Unit amount(g)",""),
            "Reagent 1": r1n, "R1 MW": r1mw, "R1 Density": r1d, "R1 mmol": r1mm, "R1 amount": r1amt,
            "Reagent 2 / catalyst": r2n, "R2 MW": r2mw, "R2 Density": r2d, "R2 mmol": r2mm, "R2 amount": r2amt,
            "Base": bn, "Base MW": bmw, "Base Density": bd, "Base mmol": bmm, "Base amount": bamt,
            "Coupling solvent": r.get("Coupling cocktail solvent",""),
            "Solvent mL": r.get("Coupling cocktail volume(mL)",""),
            "Repeat": r.get("Repeat",""),
            "Note": r.get("Note",""),
        })
    return pd.DataFrame(rows, columns=_V236_PLAN_COLS).astype(str)

def _v237_cleavage_eq(self):
    try:
        seq = str(self.pm_sequence.get() or "")
    except Exception:
        seq = ""
    core = "".join(_v237_tokens(self))
    # explicit user examples
    if core.upper() == "GHK":
        return 18
    # AEKIRKELEKQ and similar short peptide default accepted 30-40; use 30 as default.
    if len(core) <= 12:
        return 30
    if len(core) >= 22:
        return 100
    if len(core) >= 15:
        return 80
    return 30

def _v237_cleavage_rows(self):
    scale = _v237_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2, 0.2)
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self,"pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    xeq = _v237_cleavage_eq(self)
    # total cocktail volume basis
    if ("2-CTC" in resin or "Trityl" in resin) and "합성용" not in resin:
        basis = scale / 2.0
        basis_note = "2-CTC/trityl basis=(scale/2)*x eq"
    else:
        basis = scale
        basis_note = "amide/preloaded basis=scale*x eq"
    total_ml = basis * xeq
    rows = []
    for name, frac in [("TFA",0.95),("TIS",0.025),("Water",0.025)]:
        mw, den = _v237_lookup(self, name)
        ml = total_ml * frac
        mmol = (ml * _v237_f(den,0) * 1000.0 / _v237_f(mw,1)) if mw and den else 0
        rows.append({"step":"cleavage","material":name,"class":"Cleavage cocktail","MW":mw,"Density(g/mL)":den,
                     "Eq/mmol":_v237_s(round(mmol,4))+" mmol",
                     "Amount":f"{_v237_s(round(ml,4))} mL",
                     "_mmol":mmol, "_g":0.0, "_mL":ml, "use_count":"1","repeat":"","phase":"cleavage",
                     "note":f"Total cleavage cocktail={_v237_s(round(total_ml,4))} mL; {basis_note}; TFA:TIS:DW=0.95:0.025:0.025",
                     "source":"Cleavage recommendation"})
    return rows

def _v237_materials_detailed(self):
    # Use v236 material builder as base idea but inject v237 plan and cleavage.
    if not _v237_has_seq(self):
        return pd.DataFrame(columns=_V230_MAT_COLS if "_V230_MAT_COLS" in globals() else [])
    plan = _v237_plan_detailed(self)
    out = []
    scale = _v237_f(self.pm_scale.get() if hasattr(self,"pm_scale") else 0.2, 0.2)
    copies = max(1, int(round(_v237_f(self.pm_copies.get() if hasattr(self,"pm_copies") else 1, 1))))
    resin = _v228_normalize_resin(self.pm_resin.get() if hasattr(self,"pm_resin") else "") if "_v228_normalize_resin" in globals() else ""
    loading = _v237_f(self.pm_loading.get() if hasattr(self,"pm_loading") else 0, 0)
    resin_g = scale*copies/loading if loading else 0
    out.append({"step":"resin","material":resin,"class":"Resin","MW":"N/A","Density(g/mL)":"N/A","Eq/mmol":_v237_s(round(scale*copies,4))+" mmol",
                "Amount":f"{_v237_s(round(resin_g,4))} g" if resin_g else "",
                "_mmol":scale*copies,"_g":resin_g,"_mL":0.0,"use_count":_v237_s(copies),"repeat":"","phase":"resin",
                "note":"resin_g = scale_mmol × copies / resin_loading_mmol_g","source":"Project Manager"})
    for _, r in plan.iterrows():
        step = r.get("No","")
        rep = max(1, int(round(_v237_f(r.get("Repeat"), 1))))
        unit = str(r.get("Unit name",""))
        eq = _v237_f(r.get("Unit eq"),0)
        mmol = scale*copies*eq*rep
        g = _v237_f(r.get("Unit amount(g)"),0); ml = _v237_f(r.get("Unit volume(mL)"),0)
        out.append({"step":step,"material":unit,"class":"AA/Chemical","MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                    "Eq/mmol":_v237_s(round(mmol,4))+" mmol",
                    "Amount":_v236_amount(unit,g,ml,r.get("Density(g/mL)","")) if "_v236_amount" in globals() else _v237_s(g),
                    "_mmol":mmol,"_g":g,"_mL":ml,"use_count":_v237_s(copies),"repeat":_v237_s(rep),"phase":"coupling","note":r.get("Note",""),"source":"Selected Plan"})
        for name_col,prefix,cls in [("Coupling reagent 1","Reagent 1","Coupling reagent"),("Coupling reagent 2 / catalyst","Reagent 2","Catalyst/additive"),("Coupling base","Base","Base")]:
            name = str(r.get(name_col,"")).strip()
            if not name:
                continue
            mw, den = _v237_lookup(self, name)
            mm = _v237_f(r.get(f"{prefix} mmol"),0); g = _v237_f(r.get(f"{prefix} g"),0); ml = _v237_f(r.get(f"{prefix} mL"),0)
            if mm == 0 and g == 0 and ml == 0:
                continue
            out.append({"step":step,"material":name,"class":cls,"MW":mw,"Density(g/mL)":den,
                        "Eq/mmol":_v237_s(round(mm,4))+" mmol",
                        "Amount":_v236_amount(name,g,ml,den) if "_v236_amount" in globals() else (g or ml),
                        "_mmol":mm,"_g":g,"_mL":ml,"use_count":_v237_s(copies),"repeat":_v237_s(rep),
                        "phase":"coupling reagent/base","note":f"{name_col}; step {step}","source":"Selected Plan"})
        # solvent rows
        solv = str(r.get("Coupling cocktail solvent","")).strip()
        vol = _v237_f(r.get("Coupling cocktail volume(mL)"),0)*copies*rep
        is_hbtu = str(r.get("Coupling reagent 1","")).strip().upper()=="HBTU" and "NMP" in solv.upper()
        if is_hbtu and vol:
            nmp_mmol = 0.8*vol
            nmp_g = nmp_mmol*99.13/1000.0
            nmp_ml = nmp_g/1.028
            dmf_ml = max(vol-nmp_ml,0)
            for name, mlv, note in [("NMP",nmp_ml,"0.8 M NMP in DMF-based HBTU/NMP solution"),("DMF",dmf_ml,"DMF diluent for HBTU/NMP solution")]:
                mw, den = _v237_lookup(self, name)
                out.append({"step":step,"material":name,"class":"Coupling solution solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"",
                            "Amount":f"{_v237_s(round(mlv,4))} mL","_mmol":0.0,"_g":0.0,"_mL":mlv,
                            "use_count":_v237_s(copies),"repeat":_v237_s(rep),"phase":"HBTU/NMP prep","note":note,"source":"HBTU/NMP solution rule"})
        elif solv and vol:
            try: splits = self._split_solution_name(solv, vol)
            except Exception: splits = [(solv,vol,"")]
            for sname,sml,snote in splits:
                mw, den = _v237_lookup(self, sname)
                out.append({"step":step,"material":sname,"class":"Coupling solvent","MW":mw,"Density(g/mL)":den,"Eq/mmol":"",
                            "Amount":f"{_v237_s(round(_v237_f(sml,0),4))} mL","_mmol":0.0,"_g":0.0,"_mL":_v237_f(sml,0),
                            "use_count":_v237_s(copies),"repeat":_v237_s(rep),"phase":"coupling solvent","note":snote or f"{solv}; step {step}","source":"Selected Plan"})
    if "_v236_process_solvent_rows" in globals():
        out.extend(_v236_process_solvent_rows(self, _v237_working_ml(self)))
    out.extend(_v237_cleavage_rows(self))
    return pd.DataFrame(out)

def _v237_material_display_df(self):
    df = _v237_materials_detailed(self)
    return df[_V230_MAT_COLS].astype(str) if not df.empty and "_V230_MAT_COLS" in globals() else df.astype(str)

def _v237_total_df(self):
    if not _v237_has_seq(self):
        return pd.DataFrame(columns=_V236_TOTAL_COLS if "_V236_TOTAL_COLS" in globals() else [])
    df = _v237_materials_detailed(self)
    if df.empty:
        return pd.DataFrame(columns=_V236_TOTAL_COLS if "_V236_TOTAL_COLS" in globals() else [])
    for c in ["_mmol","_g","_mL"]:
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0)
    grp = df.groupby(["material"], dropna=False).agg({"class":"first","MW":"first","Density(g/mL)":"first","_mmol":"sum","_g":"sum","_mL":"sum","note":"first"}).reset_index()
    rows = []
    for _, r in grp.iterrows():
        amt = _v236_amount(r.get("material",""), round(float(r.get("_g",0)),4) if float(r.get("_g",0)) else "", round(float(r.get("_mL",0)),4) if float(r.get("_mL",0)) else "", r.get("Density(g/mL)","")) if "_v236_amount" in globals() else ""
        rows.append({"material":r.get("material",""),"class":r.get("class",""),"MW":r.get("MW",""),"Density(g/mL)":r.get("Density(g/mL)",""),
                     "total mmol":_v237_s(round(float(r.get("_mmol",0)),4) if float(r.get("_mmol",0)) else ""),
                     "total amount":amt,"note":r.get("note","")})
    return pd.DataFrame(rows, columns=_V236_TOTAL_COLS if "_V236_TOTAL_COLS" in globals() else ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]).astype(str)

def _v237_write_tree(self, tree, df):
    if "_v236_write_tree" in globals():
        return _v236_write_tree(self, tree, df)
    cols = list(df.columns)
    tree.configure(columns=cols, show="headings")
    for c in cols:
        tree.heading(c, text=c); tree.column(c, width=140, minwidth=70, anchor="w", stretch=False)
    _kids = list(tree.get_children())
    if _kids: tree.delete(*_kids)
    for _, row in df.iterrows():
        tree.insert("", "end", values=[_v237_s(row.get(c,"")) for c in cols])

def _v237_refresh(self, commit=False):
    if commit and "_v228_commit_overrides" in globals():
        _v228_commit_overrides(self)
    _v237_write_tree(self, self.pm_selected_plan_tree, _v237_plan_display_df(self))
    _v237_write_tree(self, self.pm_selected_material_tree, _v237_material_display_df(self))
    if "_v228_ensure_total_tab" in globals(): _v228_ensure_total_tab(self)
    if hasattr(self, "pm_selected_total_tree"):
        _v237_write_tree(self, self.pm_selected_total_tree, _v237_total_df(self))
    try:
        if _v237_has_seq(self): _v217_refresh_selected_checklist(self)
    except Exception: pass
    try: self.refresh_batch_workspace_preview()
    except Exception: pass
    try: self.schedule_autosave()
    except Exception: pass

def _v237_unit_options(self):
    opts = []
    try:
        opts.extend(list(_v237_aa_name_map().values()))
    except Exception: pass
    opts.extend(["Acetic anhydride (Ac2O) for N-terminal acetylation","DIC","HBTU","HOBt Anhydrous","HOBt hydrate","DIEA","DMF","DCM","NMP","TFA","TIS","Water"])
    # unique keep order
    seen=[]; out=[]
    for x in opts:
        if x not in seen:
            seen.append(x); out.append(x)
    return out

def _v237_edit_selected_unit(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    sel = tree.selection()
    if not sel:
        return
    iid = sel[0]
    cols = list(tree["columns"])
    try:
        unit_idx = cols.index("Unit name")
    except Exception:
        return
    vals = list(tree.item(iid, "values"))
    old = vals[unit_idx] if unit_idx < len(vals) else ""
    win = tk.Toplevel(self)
    win.title("Edit Unit name")
    ttk.Label(win, text="Unit name").grid(row=0, column=0, sticky="w", padx=8, pady=8)
    var = tk.StringVar(value=old)
    cb = ttk.Combobox(win, textvariable=var, values=_v237_unit_options(self), state="normal", width=45)
    cb.grid(row=0, column=1, sticky="ew", padx=8, pady=8)
    def apply():
        new = var.get().strip()
        if not new:
            return
        vals2 = list(tree.item(iid, "values"))
        while len(vals2) < len(cols):
            vals2.append("")
        vals2[unit_idx] = new
        # update MW/density columns if present
        for cname, val in [("MW", _v237_lookup(self,new)[0]), ("Density(g/mL)", _v237_lookup(self,new)[1])]:
            if cname in cols:
                vals2[cols.index(cname)] = val
        tree.item(iid, values=vals2)
        win.destroy()
    ttk.Button(win, text="Apply", command=apply).grid(row=1, column=0, columnspan=2, pady=8)
    cb.focus_set()

def _v237_delete_selected_plan_rows(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    for iid in list(tree.selection()):
        tree.delete(iid)
    # renumber No column
    cols = list(tree["columns"])
    if "No" in cols:
        noidx = cols.index("No")
        for n, iid in enumerate(tree.get_children(), start=1):
            vals = list(tree.item(iid, "values"))
            while len(vals) < len(cols):
                vals.append("")
            vals[noidx] = str(n)
            tree.item(iid, values=vals)

def _v237_add_plan_edit_buttons(self):
    if hasattr(self, "_v237_plan_edit_buttons_added"):
        return
    self._v237_plan_edit_buttons_added = True
    try:
        # Find frame containing Selected Plan tree.
        tree = getattr(self, "pm_selected_plan_tree", None)
        if tree is None:
            return
        parent = tree.master
        bar = ttk.Frame(parent)
        # place above tree if row 0 is tree; use row 2 if unavailable
        bar.grid(row=2, column=0, sticky="w", padx=4, pady=3)
        ttk.Button(bar, text="Edit Unit name", command=lambda: _v237_edit_selected_unit(self)).pack(side="left", padx=3)
        ttk.Button(bar, text="Delete selected row", command=lambda: _v237_delete_selected_plan_rows(self)).pack(side="left", padx=3)
        ttk.Button(bar, text="Apply Plan", command=lambda: _v237_apply_plan(self)).pack(side="left", padx=3)
    except Exception:
        pass

def _v237_generate(self):
    try:
        _v237_add_simple_ui(self)
        _v236_force_resin_loading(self) if "_v236_force_resin_loading" in globals() else None
        if "_v228_set_resin_dropdowns" in globals(): _v228_set_resin_dropdowns(self)
        try: _v217_save_editor_to_pm_item(self)
        except Exception: pass
        _v237_refresh(self, commit=False)
        _v237_add_plan_edit_buttons(self)
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v237_apply_plan(self):
    try:
        _v237_refresh(self, commit=True)
        _v237_add_plan_edit_buttons(self)
        self.save_autosave_state()
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass

try: _v237_old_collect = SPPSGui._collect_state
except Exception: _v237_old_collect = None
try: _v237_old_load = SPPSGui.load_autosave_state
except Exception: _v237_old_load = None
try: _v237_old_build = SPPSGui._build
except Exception: _v237_old_build = None

def _v237_collect_state(self):
    state = _v237_old_collect(self) if _v237_old_collect else {}
    try:
        state["unit_calc_mode"] = self.unit_calc_mode.get() if hasattr(self,"unit_calc_mode") else "default"
        state["reagent_calc_mode"] = self.reagent_calc_mode.get() if hasattr(self,"reagent_calc_mode") else "default"
        state["rule_eq_rules"] = self.rule_eq_rules.get() if hasattr(self,"rule_eq_rules") else ""
        state["rule_repeat_rules"] = self.rule_repeat_rules.get() if hasattr(self,"rule_repeat_rules") else ""
    except Exception: pass
    return state

def _v237_load_state(self):
    try:
        if _v237_old_load: _v237_old_load(self)
    except Exception: pass
    try:
        _v237_add_simple_ui(self)
        if self.state_file.exists():
            st = json.loads(self.state_file.read_text(encoding="utf-8"))
            if hasattr(self,"unit_calc_mode"): self.unit_calc_mode.set(st.get("unit_calc_mode","default"))
            if hasattr(self,"reagent_calc_mode"): self.reagent_calc_mode.set(st.get("reagent_calc_mode","default"))
            if hasattr(self,"rule_eq_rules"): self.rule_eq_rules.set(st.get("rule_eq_rules",""))
            if hasattr(self,"rule_repeat_rules"): self.rule_repeat_rules.set(st.get("rule_repeat_rules",""))
    except Exception: pass

def _v237_build(self):
    if _v237_old_build: _v237_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        _v237_add_simple_ui(self)
        _v236_force_resin_loading(self) if "_v236_force_resin_loading" in globals() else None
        _v237_add_plan_edit_buttons(self)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v237_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception: pass
                walk(c)
        walk(self)
    except Exception: pass

SPPSGui.pm_generate_selected = _v237_generate
SPPSGui.pm_calculate_all = _v237_generate
SPPSGui.apply_plan_mw_density = _v237_apply_plan
SPPSGui._collect_state = _v237_collect_state
SPPSGui.load_autosave_state = _v237_load_state
SPPSGui._build = _v237_build
# ======================= END V2.0.37 PATCH =======================

# V2.0.37 audit: Ac-/AC- prefix is stripped before AA tokenization, so AC- and Ac- mean acetylation only.



# ======================= V2.0.38 POLISH PATCH: HOBt OPTIONS + EDIT RECALC + CLEAN UI =======================
# Based directly on V2.0.37.
# Supplemental fixes:
# 1) Reagents/Catalyst comboboxes include HOBt Anhydrous and HOBt hydrate.
# 2) If old HOBt is selected, it is normalized to HOBt Anhydrous by default.
# 3) Edit Unit name now recalculates that row's MW/Density/amount and then refreshes Materials/Total from visible plan where possible.
# 4) Delete selected row immediately refreshes Materials/Total instead of waiting for a separate Apply.
# 5) Additional cleanup hides old duplicated range/check controls that can remain from previous patch layers.
# =======================================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v238_s(v):
    return _v237_s(v) if "_v237_s" in globals() else ("" if v is None else str(v))

def _v238_f(v, default=0.0):
    return _v237_f(v, default) if "_v237_f" in globals() else default

def _v238_lookup(self, name):
    return _v237_lookup(self, name) if "_v237_lookup" in globals() else ("","")

def _v238_refresh_hobt_options(self):
    try:
        # normalize catalyst/additive variable if present
        for attr in ["default_catalyst", "catalyst", "pm_catalyst"]:
            try:
                v = getattr(self, attr)
                if str(v.get()).strip() == "HOBt":
                    v.set("HOBt Anhydrous")
            except Exception:
                pass
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Combobox):
                        vals = [str(x) for x in (c.cget("values") or [])]
                        joined = "|".join(vals)
                        if "HOBt" in joined or "HBTU" in joined or "DIC" in joined:
                            for add in ["HOBt Anhydrous", "HOBt hydrate"]:
                                if add not in vals:
                                    vals.append(add)
                            c.configure(values=vals)
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v238_cleanup_old_controls(self):
    # Do not destroy widgets; only hide duplicate old controls from patch stacking.
    texts_exact = {
        "Use range-based eq / coupling repeat rules",
        "Use range eq/repeat rules for AA units",
        "Tie reagent/catalyst eq to AA range eq",
        "Uses Unit defaults AA eq range",
        "Reagent repeat follows AA repeat",
        "AA eq control",
        "AA repeat control",
        "Reagent 1 eq control",
        "Reagent 1 count/repeat control",
        "Catalyst eq control",
        "Catalyst count/repeat control",
        "Base eq control",
        "Base count/repeat control",
    }
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, (ttk.Label, ttk.Checkbutton, ttk.Labelframe)):
                        t = str(c.cget("text")).strip()
                        if t in texts_exact:
                            c.grid_remove()
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

def _v238_amount_for_unit(self, unit, mw, den, mmol):
    g = _v238_f(mmol,0) * _v238_f(mw,0) / 1000.0 if mw else 0
    ml = g / _v238_f(den,1) if g and den else 0
    try:
        return _v236_amount(unit, round(g,4) if g else "", round(ml,4) if ml else "", den)
    except Exception:
        return f"{_v238_s(round(g,4))} g" if g else ""

def _v238_mmol_from_cell(text):
    # supports "20", "20 mmol", etc.
    m = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", str(text or "").replace(",", ""))
    return float(m.group(0)) if m else 0.0

def _v238_recalc_visible_row(self, tree, iid):
    cols = list(tree["columns"])
    vals = list(tree.item(iid, "values"))
    while len(vals) < len(cols):
        vals.append("")
    def setcol(c, v):
        if c in cols:
            vals[cols.index(c)] = _v238_s(v)
    def getcol(c):
        return vals[cols.index(c)] if c in cols else ""
    unit = getcol("Unit name")
    mw, den = _v238_lookup(self, unit)
    setcol("MW", mw); setcol("Density(g/mL)", den)
    unit_mmol = _v238_mmol_from_cell(getcol("Unit mmol"))
    if unit_mmol and mw:
        setcol("Unit amount", _v238_amount_for_unit(self, unit, mw, den, unit_mmol))
    for name_col, mw_col, den_col, mmol_col, amt_col in [
        ("Reagent 1","R1 MW","R1 Density","R1 mmol","R1 amount"),
        ("Reagent 2 / catalyst","R2 MW","R2 Density","R2 mmol","R2 amount"),
        ("Base","Base MW","Base Density","Base mmol","Base amount"),
    ]:
        name = getcol(name_col)
        if name:
            mw2, den2 = _v238_lookup(self, name)
            setcol(mw_col, mw2); setcol(den_col, den2)
            mm = _v238_mmol_from_cell(getcol(mmol_col))
            if mm and mw2:
                setcol(amt_col, _v238_amount_for_unit(self, name, mw2, den2, mm))
    tree.item(iid, values=vals)

def _v238_visible_plan_to_materials(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None or len(tree.get_children()) == 0:
        return _v237_material_display_df(self) if "_v237_material_display_df" in globals() else pd.DataFrame()
    cols = list(tree["columns"])
    rows = []
    scale = _v238_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0, 0)
    resin = ""
    try:
        resin = _v228_normalize_resin(self.pm_resin.get())
    except Exception:
        try:
            resin = self.pm_resin.get()
        except Exception:
            resin = ""
    loading = _v238_f(self.pm_loading.get() if hasattr(self, "pm_loading") else 0, 0)
    resin_g = scale/loading if loading else 0
    if resin:
        rows.append({"step":"resin","material":resin,"class":"Resin","MW":"N/A","Density(g/mL)":"N/A",
                     "Eq/mmol":_v238_s(scale)+" mmol","Amount":f"{_v238_s(round(resin_g,4))} g" if resin_g else "",
                     "_mmol":scale,"_g":resin_g,"_mL":0.0,"use_count":"1","repeat":"","phase":"resin",
                     "note":"resin_g = scale_mmol × copies / resin_loading_mmol_g","source":"Visible Selected Plan"})
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values")); vals += [""]*max(0,len(cols)-len(vals))
        d = dict(zip(cols, vals))
        step = d.get("No","")
        for name_col, cls, mw_col, den_col, mmol_col, amt_col in [
            ("Unit name","AA/Chemical","MW","Density(g/mL)","Unit mmol","Unit amount"),
            ("Reagent 1","Coupling reagent","R1 MW","R1 Density","R1 mmol","R1 amount"),
            ("Reagent 2 / catalyst","Catalyst/additive","R2 MW","R2 Density","R2 mmol","R2 amount"),
            ("Base","Base","Base MW","Base Density","Base mmol","Base amount"),
        ]:
            name = str(d.get(name_col,"")).strip()
            if not name:
                continue
            mm = _v238_mmol_from_cell(d.get(mmol_col,""))
            amt = str(d.get(amt_col,""))
            g = _v238_f(amt.replace("g","").strip(),0) if "g" in amt.lower() else 0
            ml = _v238_f(amt.replace("mL","").replace("ml","").strip(),0) if "ml" in amt.lower() else 0
            rows.append({"step":step,"material":name,"class":cls,"MW":d.get(mw_col,""),"Density(g/mL)":d.get(den_col,""),
                         "Eq/mmol":(_v238_s(mm)+" mmol") if mm else "","Amount":amt,"_mmol":mm,"_g":g,"_mL":ml,
                         "use_count":"1","repeat":d.get("Repeat",""),"phase":"visible selected plan",
                         "note":d.get("Note",""),"source":"Visible Selected Plan"})
        solv = str(d.get("Coupling solvent","")).strip()
        sml = _v238_f(d.get("Solvent mL",""),0)
        if solv and sml:
            try:
                splits = self._split_solution_name(solv, sml)
            except Exception:
                splits = [(solv, sml, "")]
            for sname, vol, snote in splits:
                mw, den = _v238_lookup(self, sname)
                rows.append({"step":step,"material":sname,"class":"Coupling solvent","MW":mw,"Density(g/mL)":den,
                             "Eq/mmol":"","Amount":f"{_v238_s(round(vol,4))} mL","_mmol":0.0,"_g":0.0,"_mL":vol,
                             "use_count":"1","repeat":d.get("Repeat",""),"phase":"visible solvent","note":snote,"source":"Visible Selected Plan"})
    # append current cleavage rows
    try:
        rows.extend(_v237_cleavage_rows(self))
    except Exception:
        pass
    df = pd.DataFrame(rows)
    if df.empty:
        return pd.DataFrame(columns=_V230_MAT_COLS if "_V230_MAT_COLS" in globals() else [])
    return df

def _v238_total_from_materials(df):
    if df.empty:
        return pd.DataFrame(columns=_V236_TOTAL_COLS if "_V236_TOTAL_COLS" in globals() else [])
    for c in ["_mmol","_g","_mL"]:
        if c not in df.columns:
            df[c] = 0
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0)
    grp = df.groupby(["material"], dropna=False).agg({"class":"first","MW":"first","Density(g/mL)":"first","_mmol":"sum","_g":"sum","_mL":"sum","note":"first"}).reset_index()
    out = []
    for _, r in grp.iterrows():
        name = r.get("material","")
        den = r.get("Density(g/mL)","")
        amt = ""
        if float(r.get("_mL",0)):
            amt = f"{_v238_s(round(float(r.get('_mL',0)),4))} mL"
        elif float(r.get("_g",0)):
            amt = f"{_v238_s(round(float(r.get('_g',0)),4))} g"
        out.append({"material":name,"class":r.get("class",""),"MW":r.get("MW",""),"Density(g/mL)":den,
                    "total mmol":_v238_s(round(float(r.get("_mmol",0)),4) if float(r.get("_mmol",0)) else ""),
                    "total amount":amt,"note":r.get("note","")})
    return pd.DataFrame(out, columns=_V236_TOTAL_COLS if "_V236_TOTAL_COLS" in globals() else ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]).astype(str)

def _v238_refresh_from_visible_plan(self):
    mats = _v238_visible_plan_to_materials(self)
    try:
        if "_V230_MAT_COLS" in globals():
            display = mats[_V230_MAT_COLS].astype(str)
        else:
            display = mats.astype(str)
        _v237_write_tree(self, self.pm_selected_material_tree, display)
        if "_v228_ensure_total_tab" in globals():
            _v228_ensure_total_tab(self)
        if hasattr(self, "pm_selected_total_tree"):
            _v237_write_tree(self, self.pm_selected_total_tree, _v238_total_from_materials(mats))
    except Exception:
        pass

def _v238_edit_selected_unit(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    sel = tree.selection()
    if not sel:
        return
    iid = sel[0]
    cols = list(tree["columns"])
    try:
        unit_idx = cols.index("Unit name")
    except Exception:
        return
    vals = list(tree.item(iid, "values"))
    old = vals[unit_idx] if unit_idx < len(vals) else ""
    win = tk.Toplevel(self)
    win.title("Edit Unit name")
    ttk.Label(win, text="Unit name").grid(row=0, column=0, sticky="w", padx=8, pady=8)
    var = tk.StringVar(value=old)
    values = _v237_unit_options(self) if "_v237_unit_options" in globals() else []
    for add in ["HOBt Anhydrous","HOBt hydrate"]:
        if add not in values:
            values.append(add)
    cb = ttk.Combobox(win, textvariable=var, values=values, state="normal", width=48)
    cb.grid(row=0, column=1, sticky="ew", padx=8, pady=8)
    def apply():
        new = var.get().strip()
        if not new:
            return
        vals2 = list(tree.item(iid, "values"))
        while len(vals2) < len(cols):
            vals2.append("")
        vals2[unit_idx] = new
        tree.item(iid, values=vals2)
        _v238_recalc_visible_row(self, tree, iid)
        _v238_refresh_from_visible_plan(self)
        try:
            self.schedule_autosave()
        except Exception:
            pass
        win.destroy()
    ttk.Button(win, text="Apply", command=apply).grid(row=1, column=0, columnspan=2, pady=8)
    cb.focus_set()

def _v238_delete_selected_plan_rows(self):
    if "_v237_delete_selected_plan_rows" in globals():
        _v237_delete_selected_plan_rows(self)
    _v238_refresh_from_visible_plan(self)
    try:
        self.schedule_autosave()
    except Exception:
        pass

def _v238_add_plan_edit_buttons(self):
    if hasattr(self, "_v238_plan_edit_buttons_added"):
        return
    self._v238_plan_edit_buttons_added = True
    try:
        tree = getattr(self, "pm_selected_plan_tree", None)
        if tree is None:
            return
        parent = tree.master
        bar = ttk.Frame(parent)
        bar.grid(row=3, column=0, sticky="w", padx=4, pady=3)
        ttk.Button(bar, text="Edit Unit name", command=lambda: _v238_edit_selected_unit(self)).pack(side="left", padx=3)
        ttk.Button(bar, text="Delete selected row", command=lambda: _v238_delete_selected_plan_rows(self)).pack(side="left", padx=3)
        ttk.Button(bar, text="Refresh totals from visible plan", command=lambda: _v238_refresh_from_visible_plan(self)).pack(side="left", padx=3)
        ttk.Button(bar, text="Apply Plan", command=lambda: _v238_apply_plan(self)).pack(side="left", padx=3)
    except Exception:
        pass

def _v238_generate(self):
    try:
        if "_v237_add_simple_ui" in globals():
            _v237_add_simple_ui(self)
        _v238_cleanup_old_controls(self)
        _v238_refresh_hobt_options(self)
        if "_v236_force_resin_loading" in globals():
            _v236_force_resin_loading(self)
        if "_v228_set_resin_dropdowns" in globals():
            _v228_set_resin_dropdowns(self)
        try:
            _v217_save_editor_to_pm_item(self)
        except Exception:
            pass
        if "_v237_refresh" in globals():
            _v237_refresh(self, commit=False)
        _v238_add_plan_edit_buttons(self)
    except Exception as e:
        try:
            messagebox.showerror("Project Manager", str(e))
        except Exception:
            pass

def _v238_apply_plan(self):
    try:
        if "_v237_refresh" in globals():
            _v237_refresh(self, commit=True)
        _v238_refresh_hobt_options(self)
        _v238_add_plan_edit_buttons(self)
        self.save_autosave_state()
    except Exception as e:
        try:
            messagebox.showerror("Apply Plan", str(e))
        except Exception:
            pass

try:
    _v238_old_build = SPPSGui._build
except Exception:
    _v238_old_build = None

def _v238_build(self):
    if _v238_old_build:
        _v238_old_build(self)
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        if "_v237_add_simple_ui" in globals():
            _v237_add_simple_ui(self)
        _v238_cleanup_old_controls(self)
        _v238_refresh_hobt_options(self)
        if "_v236_force_resin_loading" in globals():
            _v236_force_resin_loading(self)
        _v238_add_plan_edit_buttons(self)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v238_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

SPPSGui.pm_generate_selected = _v238_generate
SPPSGui.pm_calculate_all = _v238_generate
SPPSGui.apply_plan_mw_density = _v238_apply_plan
SPPSGui._build = _v238_build
