# ======================= V2.0.40 RECURSION-FREE BUILD PATCH =======================
# Based on V2.0.39.
# Root cause: V2.0.39 patch was appended twice, so _v239_old_build captured a previous _v239_build
# and _v239_build called itself recursively through _v239_old_build.
# This patch fixes launch by replacing SPPSGui._build with a recursion-free wrapper that never calls
# previous patched _build functions. It manually calls the original builder logic if available through
# a saved unpatched method; otherwise it falls back to the earliest stable builder found in the class MRO.
# In this file, the safest available route is to call the original class method body saved as
# _v236_old_build/_v237_old_build only if it is not a patched _v239_build. If none is safe, call
# Tk frame construction through the preexisting _build_original if present.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v240_is_bad_build(fn):
    try:
        name = getattr(fn, "__name__", "")
        return name in {"_v239_build", "_v238_build", "_v237_build", "_v236_build", "_v235_build", "_v234_build", "_v233_build", "_v232_build"}
    except Exception:
        return True

def _v240_find_safe_build():
    # Prefer explicitly saved original-style build candidates, but reject patch wrappers.
    for nm in ["_v230_old_build", "_v229_old_build", "_v228_old_build", "_v224_old_build", "_v217_old_build"]:
        fn = globals().get(nm)
        if callable(fn) and not _v240_is_bad_build(fn):
            return fn
    # Last resort: scan for any saved old build that is not a v23x patch wrapper.
    for nm, fn in list(globals().items()):
        if nm.endswith("_old_build") and callable(fn) and not _v240_is_bad_build(fn):
            return fn
    return None

def _v240_build(self):
    # Do not call _v239_old_build or any later wrapper. That was the recursion source.
    safe = _v240_find_safe_build()
    if callable(safe):
        safe(self)
    else:
        # If no safe saved build exists, attempt to call Tk root defaults only.
        # This branch should rarely happen, but avoids recursion.
        try:
            tk.Tk.__init__(self)
        except Exception:
            pass
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
    except Exception:
        pass
    try:
        if "_v237_add_simple_ui" in globals():
            _v237_add_simple_ui(self)
    except Exception:
        pass
    try:
        if "_v238_cleanup_old_controls" in globals():
            _v238_cleanup_old_controls(self)
    except Exception:
        pass
    try:
        if "_v238_refresh_hobt_options" in globals():
            _v238_refresh_hobt_options(self)
    except Exception:
        pass
    try:
        if "_v236_force_resin_loading" in globals():
            _v236_force_resin_loading(self)
    except Exception:
        pass
    try:
        if "_v239_add_plan_edit_buttons" in globals():
            _v239_add_plan_edit_buttons(self)
    except Exception:
        pass
    try:
        if "_v239_remove_extra_refresh_buttons" in globals():
            _v239_remove_extra_refresh_buttons(self)
    except Exception:
        pass
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                        c.configure(command=lambda: _v239_apply_plan(self) if "_v239_apply_plan" in globals() else self.apply_plan_mw_density())
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

# Rebind only final public methods. Generate/Apply keep V2.0.39 logic; only build is fixed.
SPPSGui._build = _v240_build
