def _v244_norm(x):
    return re.sub(r"[^0-9a-z가-힣]+", "", str(x or "").lower())

def _v244_canon(name):
    raw = str(name or "").strip()
    n = _v244_norm(raw)
    aliases = {
        "hobt": "HOBt Anhydrous",
        "hobtanhydrous": "HOBt Anhydrous",
        "hobtanhydrate": "HOBt hydrate",
        "hobthydrate": "HOBt hydrate",
        "hobtmonohydrate": "HOBt hydrate",
        "pal": "Palmitic acid", "palmitic": "Palmitic acid", "palmiticacid": "Palmitic acid",
        "gal": "Gallic acid", "gallic": "Gallic acid", "gallicacid": "Gallic acid",
        "ac": "Acetic anhydride (Ac2O)", "ac2o": "Acetic anhydride (Ac2O)", "aceticanhydride": "Acetic anhydride (Ac2O)",
    }
    return aliases.get(n, raw)

def _v244_f(v, default=0.0):
    try:
        if callable(v) or v is None or str(v).strip() == "":
            return default
        return float(str(v).replace(",", "").strip())
    except Exception:
        return default

def _v244_s(v):
    if v is None:
        return ""
    try:
        f = float(v)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f"{f:.6f}".rstrip("0").rstrip(".")
    except Exception:
        return str(v)

def _v244_lookup(self, name):
    # use the hard-safe direct lookup from V2.0.43 if present; never call old late alias loops.
    canon = _v244_canon(name)
    try:
        if "_v243_lookup" in globals():
            return _v243_lookup(self, canon)
    except Exception:
        pass
    try:
        if "_v216_lookup_mw_density" in globals():
            mw, den = _v216_lookup_mw_density(self, canon)
            if str(mw).strip():
                return str(mw), str(den)
    except Exception:
        pass
    return "", ""

def _v244_getvar(self, names, default=""):
    for nm in names:
        try:
            return getattr(self, nm).get()
        except Exception:
            pass
    return default

def _v244_setvar(self, names, value):
    for nm in names:
        try:
            getattr(self, nm).set(value)
            return True
        except Exception:
            pass
    return False

def _v244_vars(self):
    if not hasattr(self, "aa_default_mode"):
        self.aa_default_mode = tk.BooleanVar(value=True)
    if not hasattr(self, "aa_range_mode"):
        self.aa_range_mode = tk.BooleanVar(value=False)
    if not hasattr(self, "reagent_default_mode"):
        self.reagent_default_mode = tk.BooleanVar(value=True)
    if not hasattr(self, "reagent_range_mode"):
        self.reagent_range_mode = tk.BooleanVar(value=False)
    if not hasattr(self, "rule_eq_rules"):
        self.rule_eq_rules = tk.StringVar(value="")
    if not hasattr(self, "rule_repeat_rules"):
        self.rule_repeat_rules = tk.StringVar(value="")

def _v244_set_aa_mode(self, mode):
    _v244_vars(self)
    self.aa_default_mode.set(mode == "default")
    self.aa_range_mode.set(mode == "range")
    try:
        if hasattr(self, "unit_calc_mode"):
            self.unit_calc_mode.set(mode)
    except Exception:
        pass

def _v244_set_reagent_mode(self, mode):
    _v244_vars(self)
    self.reagent_default_mode.set(mode == "default")
    self.reagent_range_mode.set(mode == "range")
    try:
        if hasattr(self, "reagent_calc_mode"):
            self.reagent_calc_mode.set(mode)
    except Exception:
        pass

