# ======================= V2.0.46 CUSTOM DB LIVE REFLECT + CONCENTRATION VOLUME PATCH =======================
# Based directly on V2.0.45 working tree.
# Adds/strengthens:
# 1) Custom materials are immediately reflected in all dropdowns and current selected plan row recalculation.
# 2) Add AA solution concentration (M) setting under Solvents / Wash setup.
# 3) Coupling solution volume uses: solution_mL = unit_mmol / concentration_M.
#    Because 1 M = 1 mmol/mL. Example: 2000 mmol at 0.5 M -> 4000 mL.
# 4) Process solvent/wash basis uses the same concentration-derived working mL when possible.
# 5) Apply Plan remains the single route for full Materials/Total reflection; Add/Update custom DB also triggers dropdown refresh and visible row recalc.
# ==========================================================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v246_f(v, default=0.0):
    try:
        if callable(v) or v is None or str(v).strip() == "":
            return default
        return float(str(v).replace(",", "").strip())
    except Exception:
        return default

def _v246_s(v):
    try:
        if v is None:
            return ""
        f = float(v)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f"{f:.6f}".rstrip("0").rstrip(".")
    except Exception:
        return "" if v is None else str(v)

def _v246_init_conc(self):
    if not hasattr(self, "aa_solution_conc_m"):
        self.aa_solution_conc_m = tk.StringVar(value="0.5")

def _v246_add_conc_control(self):
    _v246_init_conc(self)
    if hasattr(self, "_v246_conc_control_added"):
        return
    try:
        nb = None
        def walk(w):
            nonlocal nb
            if nb is not None:
                return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Notebook):
                        tabs = [str(c.tab(t, "text")) for t in c.tabs()]
                        if "Solvents / Wash" in tabs:
                            nb = c
                            return
                except Exception:
                    pass
                walk(c)
        walk(self)
        if nb is None:
            return
        solvent_fr = None
        for tab_id in nb.tabs():
            try:
                if str(nb.tab(tab_id, "text")) == "Solvents / Wash":
                    solvent_fr = nb.nametowidget(tab_id)
                    break
            except Exception:
                pass
        if solvent_fr is None:
            return
        self._v246_conc_control_added = True
        box = ttk.Labelframe(solvent_fr, text="Solution concentration basis", padding=6)
        box.grid(row=8, column=0, columnspan=8, sticky="ew", padx=8, pady=(10,4))
        ttk.Label(box, text="AA solution concentration").grid(row=0, column=0, sticky="w", padx=6, pady=3)
        ttk.Entry(box, textvariable=self.aa_solution_conc_m, width=14).grid(row=0, column=1, sticky="w", padx=6, pady=3)
        ttk.Label(box, text="M  (solution mL = planned mmol / M; also used as wash/working volume basis)").grid(row=0, column=2, sticky="w", padx=6, pady=3)
    except Exception:
        pass

def _v246_solution_conc(self):
    _v246_init_conc(self)
    c = _v246_f(self.aa_solution_conc_m.get(), 0.5)
    if c <= 0:
        c = 0.5
        try:
            self.aa_solution_conc_m.set("0.5")
        except Exception:
            pass
    return c

def _v246_working_ml_for_unit(self, scale_mmol=None, unit_eq=None, repeat=1, copies=1):
    try:
        if scale_mmol is None:
            scale_mmol = self.pm_scale.get()
    except Exception:
        scale_mmol = 0
    if unit_eq is None:
        try:
            unit_eq = _v244_unit_eq(self, 1) if "_v244_unit_eq" in globals() else 2
        except Exception:
            unit_eq = 2
    mmol = _v246_f(scale_mmol, 0) * _v246_f(unit_eq, 0) * max(1, int(round(_v246_f(repeat, 1)))) * max(1, int(round(_v246_f(copies, 1))))
    conc = _v246_solution_conc(self)
    if conc <= 0:
        return 0.0
    return mmol / conc

def _v246_rebuild_plan_volumes(self, df):
    if df is None or df.empty:
        return df
    try:
        scale = _v246_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0, 0)
        copies = max(1, int(round(_v246_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))))
        out = df.copy()
        for i, r in out.iterrows():
            eq = _v246_f(r.get("Unit eq", 0), 0)
            rep = max(1, int(round(_v246_f(r.get("Repeat", 1), 1))))
            ml = _v246_working_ml_for_unit(self, scale, eq, rep, copies)
            if "Coupling cocktail volume(mL)" in out.columns:
                out.at[i, "Coupling cocktail volume(mL)"] = _v246_s(ml)
        return out
    except Exception:
        return df

# Wrap plan generation so solvent volume follows concentration field.
