# ======================= V2.0.47 ONE-USE WORKING VOLUME PATCH =======================
# Based directly on V2.0.46.
# User clarification:
# The concentration-derived SPPS solution mL is effectively the "1회 사용량" working volume.
# Therefore user can either:
#   A) calculate 1-use volume from AA solution concentration M
#   B) directly set manual 1-use working volume mL
# Coupling, swell, deprotection, wash, final wash use this same 1-use working volume basis.
# ================================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v247_f(v, default=0.0):
    try:
        if callable(v) or v is None or str(v).strip() == "":
            return default
        return float(str(v).replace(",", "").strip())
    except Exception:
        return default

def _v247_s(v):
    try:
        if v is None:
            return ""
        f = float(v)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f"{f:.6f}".rstrip("0").rstrip(".")
    except Exception:
        return "" if v is None else str(v)

def _v247_init_working_volume(self):
    if not hasattr(self, "working_volume_mode"):
        self.working_volume_mode = tk.StringVar(value="concentration")
    if not hasattr(self, "one_use_working_ml"):
        self.one_use_working_ml = tk.StringVar(value="")
    if not hasattr(self, "aa_solution_conc_m"):
        self.aa_solution_conc_m = tk.StringVar(value="0.5")

def _v247_set_working_volume_mode(self, mode):
    _v247_init_working_volume(self)
    self.working_volume_mode.set(mode)

def _v247_add_working_volume_controls(self):
    _v247_init_working_volume(self)
    if hasattr(self, "_v247_working_volume_controls_added"):
        return
    try:
        nb = None
        def walk(w):
            nonlocal nb
            if nb is not None:
                return
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Notebook):
                        tabs = [str(c.tab(t, "text")) for t in c.tabs()]
                        if "Solvents / Wash" in tabs:
                            nb = c
                            return
                except Exception:
                    pass
                walk(c)
        walk(self)
        if nb is None:
            return
        solvent_fr = None
        for tab_id in nb.tabs():
            try:
                if str(nb.tab(tab_id, "text")) == "Solvents / Wash":
                    solvent_fr = nb.nametowidget(tab_id)
                    break
            except Exception:
                pass
        if solvent_fr is None:
            return
        self._v247_working_volume_controls_added = True
        box = ttk.Labelframe(solvent_fr, text="SPPS 1-use working volume", padding=6)
        box.grid(row=12, column=0, columnspan=8, sticky="ew", padx=8, pady=(10,4))
        ttk.Radiobutton(box, text="Calculate from AA solution concentration", variable=self.working_volume_mode, value="concentration").grid(row=0, column=0, sticky="w", padx=6, pady=2)
        ttk.Label(box, text="AA solution concentration").grid(row=1, column=0, sticky="w", padx=6, pady=2)
        ttk.Entry(box, textvariable=self.aa_solution_conc_m, width=12).grid(row=1, column=1, sticky="w", padx=6, pady=2)
        ttk.Label(box, text="M  →  1-use mL = planned mmol / M").grid(row=1, column=2, sticky="w", padx=6, pady=2)
        ttk.Radiobutton(box, text="Use manual 1-use working volume", variable=self.working_volume_mode, value="manual").grid(row=2, column=0, sticky="w", padx=6, pady=2)
        ttk.Label(box, text="Manual 1-use volume").grid(row=3, column=0, sticky="w", padx=6, pady=2)
        ttk.Entry(box, textvariable=self.one_use_working_ml, width=12).grid(row=3, column=1, sticky="w", padx=6, pady=2)
        ttk.Label(box, text="mL per one SPPS operation; coupling/wash/swell/deprotection uses this basis").grid(row=3, column=2, sticky="w", padx=6, pady=2)
        box.columnconfigure(2, weight=1)
    except Exception:
        pass

def _v247_one_use_ml(self, scale_mmol=None, unit_eq=None, repeat=1, copies=1):
    _v247_init_working_volume(self)
    mode = self.working_volume_mode.get()
    manual = _v247_f(self.one_use_working_ml.get(), 0)
    if mode == "manual" and manual > 0:
        return manual
    try:
        conc = _v247_f(self.aa_solution_conc_m.get(), 0.5)
    except Exception:
        conc = 0.5
    if conc <= 0:
        conc = 0.5
        try:
            self.aa_solution_conc_m.set("0.5")
        except Exception:
            pass
    if scale_mmol is None:
        try:
            scale_mmol = self.pm_scale.get()
        except Exception:
            scale_mmol = 0
    if unit_eq is None:
        try:
            unit_eq = _v244_unit_eq(self, 1) if "_v244_unit_eq" in globals() else 2
        except Exception:
            unit_eq = 2
    mmol = _v247_f(scale_mmol, 0) * _v247_f(unit_eq, 0) * max(1, int(round(_v247_f(repeat, 1)))) * max(1, int(round(_v247_f(copies, 1))))
    return mmol / conc if conc > 0 else 0

def _v247_rebuild_plan_volumes(self, df):
    if df is None or df.empty:
        return df
    try:
        scale = _v247_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0, 0)
        copies = max(1, int(round(_v247_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))))
        out = df.copy()
        for i, r in out.iterrows():
            eq = _v247_f(r.get("Unit eq", 0), 0)
            rep = max(1, int(round(_v247_f(r.get("Repeat", 1), 1))))
            ml = _v247_one_use_ml(self, scale, eq, rep, copies)
            if "Coupling cocktail volume(mL)" in out.columns:
                out.at[i, "Coupling cocktail volume(mL)"] = _v247_s(ml)
        return out
    except Exception:
        return df

try:
    _v247_base_plan_detailed = _v246_old_plan_detailed if "_v246_old_plan_detailed" in globals() else None
except Exception:
    _v247_base_plan_detailed = None

def _v247_plan_detailed(self):
    if callable(_v247_base_plan_detailed):
        return _v247_rebuild_plan_volumes(self, _v247_base_plan_detailed(self))
    try:
        if "_v244_plan_detailed" in globals() and _v244_plan_detailed is not _v247_plan_detailed:
            return _v247_rebuild_plan_volumes(self, _v244_plan_detailed(self))
    except Exception:
        pass
    return pd.DataFrame()

def _v247_process_solvent_rows(self, working_ml):
    # working_ml is one-use volume; process rows multiply by operation count.
    rows = []
    try:
        copies = max(1, int(round(_v247_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))))
    except Exception:
        copies = 1
    steps = [
        ("swell", "DMF", 1, "swell = one-use working mL × 1"),
        ("deprotection", "20% piperidine/DMF", 2, "deprotection = one-use working mL × 2"),
        ("wash", "DMF", 6, "DMF wash = one-use working mL × 6"),
        ("final wash", "DCM", 3, "DCM final wash = one-use working mL × 3"),
    ]
    for phase, solvent, count, note in steps:
        total_ml = _v247_f(working_ml, 0) * count * copies
        try:
            splits = self._split_solution_name(solvent, total_ml)
        except Exception:
            splits = [(solvent, total_ml, "")]
        for sname, sml, snote in splits:
            try:
                mw, den = _v245_lookup(self, sname) if "_v245_lookup" in globals() else ("","")
            except Exception:
                mw, den = "", ""
            rows.append({"step":phase,"material":sname,"class":"Process solvent","MW":mw,"Density(g/mL)":den,
                         "Eq/mmol":"","Amount":f"{_v247_s(sml)} mL",
                         "_mmol":0.0,"_g":0.0,"_mL":_v247_f(sml,0),
                         "use_count":str(count),"repeat":"","phase":phase,"note":snote or note,"source":"SPPS 1-use working volume"})
    return rows

# Override process solvent rows if older material builders call it.
_v236_process_solvent_rows = _v247_process_solvent_rows
_v233_process_solvent_rows = _v247_process_solvent_rows

