def _v247_collect_state(self):
    state = _v247_old_collect(self) if callable(_v247_old_collect) else {}
    try:
        _v247_init_working_volume(self)
        state["working_volume_mode"] = self.working_volume_mode.get()
        state["one_use_working_ml"] = self.one_use_working_ml.get()
        state["aa_solution_conc_m"] = self.aa_solution_conc_m.get()
    except Exception:
        pass
    return state

def _v247_load_state(self):
    try:
        if callable(_v247_old_load):
            _v247_old_load(self)
    except Exception:
        pass
    try:
        _v247_init_working_volume(self)
        if self.state_file.exists():
            data = json.loads(self.state_file.read_text(encoding="utf-8"))
            self.working_volume_mode.set(str(data.get("working_volume_mode", self.working_volume_mode.get())))
            self.one_use_working_ml.set(str(data.get("one_use_working_ml", self.one_use_working_ml.get())))
            self.aa_solution_conc_m.set(str(data.get("aa_solution_conc_m", self.aa_solution_conc_m.get())))
    except Exception:
        pass

def _v247_generate(self):
    _v247_init_working_volume(self)
    _v247_add_working_volume_controls(self)
    globals()["_v244_plan_detailed"] = _v247_plan_detailed
    globals()["_v246_plan_detailed"] = _v247_plan_detailed
    try:
        if callable(_v247_old_generate):
            _v247_old_generate(self)
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v247_apply_plan(self):
    _v247_init_working_volume(self)
    globals()["_v244_plan_detailed"] = _v247_plan_detailed
    globals()["_v246_plan_detailed"] = _v247_plan_detailed
    try:
        if callable(_v247_old_apply):
            _v247_old_apply(self)
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass

def _v247_build(self):
    if getattr(self, "_v247_build_running", False):
        return
    self._v247_build_running = True
    try:
        if callable(_v247_old_build):
            _v247_old_build(self)
        try:
            self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        except Exception:
            pass
        _v247_init_working_volume(self)
        _v247_add_working_volume_controls(self)
        try:
            def walk(w):
                for c in w.winfo_children():
                    try:
                        if isinstance(c, ttk.Button) and str(c.cget("text")) == "Apply Plan":
                            c.configure(command=lambda: _v247_apply_plan(self))
                        if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                            c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                    except Exception:
                        pass
                    walk(c)
            walk(self)
        except Exception:
            pass
    finally:
        self._v247_build_running = False

SPPSGui._collect_state = _v247_collect_state
SPPSGui.load_autosave_state = _v247_load_state
SPPSGui.pm_generate_selected = _v247_generate
SPPSGui.pm_calculate_all = _v247_generate
SPPSGui.apply_plan_mw_density = _v247_apply_plan
SPPSGui._build = _v247_build
globals()["_v244_plan_detailed"] = _v247_plan_detailed
globals()["_v246_plan_detailed"] = _v247_plan_detailed
