_V248_SOLVENT_OPTIONS = ["DMF", "NMP", "DCM", "90% DCM / 10% DMF", "20% piperidine/DMF", "TFA:TIS:DW"]

def _v248_norm(x):
    return re.sub(r"[^0-9a-z가-힣]+", "", str(x or "").lower())

def _v248_canon(name):
    raw = str(name or "").strip()
    n = _v248_norm(raw)
    aliases = {
        "hobt": "HOBt Anhydrous", "hobtanhydrous": "HOBt Anhydrous",
        "hobtanhydrate": "HOBt hydrate", "hobthydrate": "HOBt hydrate", "hobtmonohydrate": "HOBt hydrate",
        "pal": "Palmitic acid", "palmitic": "Palmitic acid", "palmiticacid": "Palmitic acid",
        "gal": "Gallic acid", "gallic": "Gallic acid", "gallicacid": "Gallic acid",
        "ac": "Acetic anhydride (Ac2O)", "ac2o": "Acetic anhydride (Ac2O)", "aceticanhydride": "Acetic anhydride (Ac2O)",
    }
    return aliases.get(n, raw)

def _v248_f(v, default=0.0):
    try:
        if callable(v) or v is None or str(v).strip() == "":
            return default
        return float(str(v).replace(",", "").strip())
    except Exception:
        return default

def _v248_s(v):
    try:
        if v is None: return ""
        f = float(v)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f"{f:.6f}".rstrip("0").rstrip(".")
    except Exception:
        return "" if v is None else str(v)

def _v248_init_state(self):
    if not hasattr(self, "custom_materials") or not isinstance(getattr(self, "custom_materials", None), dict):
        self.custom_materials = {}
    if not hasattr(self, "working_volume_mode"):
        self.working_volume_mode = tk.StringVar(value="concentration")
    if not hasattr(self, "one_use_working_ml"):
        self.one_use_working_ml = tk.StringVar(value="")
    if not hasattr(self, "aa_solution_conc_m"):
        self.aa_solution_conc_m = tk.StringVar(value="0.5")

def _v248_lookup(self, name):
    canon = _v248_canon(name)
    key = _v248_norm(canon)
    try:
        _v248_init_state(self)
        rec = self.custom_materials.get(key)
        if rec:
            return str(rec.get("mw", "") or ""), str(rec.get("density", "") or "")
    except Exception:
        pass
    if key in _V248_LOOKUP_TABLE:
        return _V248_LOOKUP_TABLE[key]
    # only oldest stable fallback; never call v23x/v24x lookup aliases
    try:
        old = globals().get("_v216_lookup_mw_density")
        if callable(old):
            mw, den = old(self, canon)
            if str(mw).strip():
                return str(mw), str(den)
    except Exception:
        pass
    return "", ""

def _v248_custom_options(self, cls=None):
    try:
        _v248_init_state(self)
        out=[]
        for rec in self.custom_materials.values():
            if cls is None or rec.get("class","") == cls:
                nm = rec.get("name","")
                if nm:
                    out.append(nm)
        return sorted(set(out), key=lambda x: x.lower())
    except Exception:
        return []

def _v248_options_for_col(self, col):
    if col == "Unit name":
        base = list(_V248_AA_OPTIONS) + _v248_custom_options(self, "AA/Chemical") + _v248_custom_options(self, "Other")
    elif col == "Reagent 1":
        base = list(_V248_REAGENT_OPTIONS) + _v248_custom_options(self, "Coupling reagent")
    elif col == "Reagent 2 / catalyst":
        base = list(_V248_CATALYST_OPTIONS) + _v248_custom_options(self, "Catalyst/additive")
    elif col == "Base":
        base = list(_V248_BASE_OPTIONS) + _v248_custom_options(self, "Base")
    elif col == "Coupling solvent":
        base = list(_V248_SOLVENT_OPTIONS) + _v248_custom_options(self, "Solvent")
    else:
        base = []
    out=[]; seen=set()
    for v in base:
        cv = _v248_canon(v)
        if cv and cv != "HOBt" and cv not in seen:
            out.append(cv); seen.add(cv)
    return out

def _v248_getvar(self, names, default=""):
    for nm in names:
        try:
            return getattr(self, nm).get()
        except Exception:
            pass
    return default

def _v248_setvar(self, names, value):
    for nm in names:
        try:
            getattr(self, nm).set(value)
            return True
        except Exception:
            pass
    return False

def _v248_aa_map():
    if "_v237_aa_name_map" in globals():
        return _v237_aa_name_map()
    return {"A":"Fmoc-Ala-OH","R":"Fmoc-Arg(Pbf)-OH","N":"Fmoc-Asn(Trt)-OH","D":"Fmoc-Asp(OtBu)-OH","C":"Fmoc-Cys(Trt)-OH","Q":"Fmoc-Gln(Trt)-OH","E":"Fmoc-Glu(OtBu)-OH","G":"Fmoc-Gly-OH","H":"Fmoc-His(Trt)-OH","I":"Fmoc-Ile-OH","L":"Fmoc-Leu-OH","K":"Fmoc-Lys(Boc)-OH","M":"Fmoc-Met-OH","F":"Fmoc-Phe-OH","P":"Fmoc-Pro-OH","S":"Fmoc-Ser(tBu)-OH","T":"Fmoc-Thr(tBu)-OH","W":"Fmoc-Trp(Boc)-OH","Y":"Fmoc-Tyr(tBu)-OH","V":"Fmoc-Val-OH"}

def _v248_tokens(self):
    try:
        seq = self.pm_sequence.get()
    except Exception:
        seq = ""
    seq = re.sub(r"^\s*(Ac|AC)\s*[-_]\s*", "", str(seq), flags=re.I)
    try:
        if hasattr(self, "_aa_letters_from_sequence"):
            return list(self._aa_letters_from_sequence(seq))
    except Exception:
        pass
    cleaned = re.sub(r"(?i)NH2|COOH|OH", "", str(seq))
    return [c.upper() for c in cleaned if c.upper() in "ARNDCQEGHILKMFPSTWYV"]

def _v248_range_value(self, text, step, default):
    try:
        for p in re.split(r"[,;\n]+", str(text or "")):
            m = re.match(r"^\s*(\d+)\s*[-~]\s*(\d+)\s*[:=]\s*([0-9.]+)\s*$", p.strip())
            if m:
                a,b,v = int(m.group(1)), int(m.group(2)), float(m.group(3))
                if b < a: a,b = b,a
                if a <= int(step) <= b:
                    return v
    except Exception:
        pass
    return default

def _v248_unit_eq(self, step):
    default = _v248_f(_v248_getvar(self, ["coupling_eq"], "2"), 2)
    try:
        if hasattr(self, "aa_range_mode") and self.aa_range_mode.get():
            return _v248_range_value(self, self.rule_eq_rules.get(), step, default)
    except Exception:
        pass
    return default

def _v248_unit_repeat(self, step):
    default = max(1, int(round(_v248_f(_v248_getvar(self, ["coupling_repeats"], "1"), 1))))
    try:
        if hasattr(self, "aa_range_mode") and self.aa_range_mode.get():
            return max(1, int(round(_v248_range_value(self, self.rule_repeat_rules.get(), step, default))))
    except Exception:
        pass
    return default

def _v248_reagent_eq(self, step, default):
    try:
        if hasattr(self, "reagent_range_mode") and self.reagent_range_mode.get():
            return _v248_unit_eq(self, step)
    except Exception:
        pass
    return default

def _v248_reagent_count(self, step, default):
    try:
        if hasattr(self, "reagent_range_mode") and self.reagent_range_mode.get():
            return _v248_unit_repeat(self, step)
    except Exception:
        pass
    return max(1, int(round(_v248_f(default, 1))))

def _v248_one_use_ml(self, scale_mmol, unit_eq, repeat=1, copies=1):
    _v248_init_state(self)
    if self.working_volume_mode.get() == "manual":
        manual = _v248_f(self.one_use_working_ml.get(), 0)
        if manual > 0:
            return manual
    conc = _v248_f(self.aa_solution_conc_m.get(), 0.5)
    if conc <= 0:
        conc = 0.5
        try: self.aa_solution_conc_m.set("0.5")
        except Exception: pass
    mmol = _v248_f(scale_mmol, 0) * _v248_f(unit_eq, 0) * max(1,int(round(_v248_f(repeat,1)))) * max(1,int(round(_v248_f(copies,1))))
    return mmol / conc if conc > 0 else 0

def _v248_calc_amount(self, name, mmol):
    mw, den = _v248_lookup(self, name)
    g = _v248_f(mmol, 0) * _v248_f(mw, 0) / 1000.0 if mw else 0
    ml = g / _v248_f(den, 1) if g and den else 0
    return mw, den, _v248_s(g), _v248_s(ml)

def _v248_plan_detailed(self):
    toks = list(reversed(_v248_tokens(self)))
    if not toks:
        return pd.DataFrame()
    aa_map = _v248_aa_map()
    scale = _v248_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2, 0.2)
    copies = max(1, int(round(_v248_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))))
    resin = self.pm_resin.get() if hasattr(self, "pm_resin") else ""
    load_on = False
    try: load_on = _v228_is_loading_applicable(self, resin)
    except Exception: pass
    rows = []
    for idx, aa in enumerate(toks, start=1):
        unit = aa_map.get(aa, aa)
        direct = idx == 1 and load_on
        if direct:
            unit_eq = _v248_f(_v248_getvar(self, ["loading_aa_eq"], "2"), 2)
            repeat = 1
            r1 = ""; r2 = ""; base = "DIEA"
            solvent = _v248_getvar(self, ["default_loading_dissolve_solvent"], "90% DCM / 10% DMF") or "90% DCM / 10% DMF"
            note = "direct loading first unit"
        else:
            unit_eq = _v248_unit_eq(self, idx)
            repeat = _v248_unit_repeat(self, idx)
            r1 = _v248_canon(_v248_getvar(self, ["default_reagent"], "DIC")) or "DIC"
            r2 = _v248_canon(_v248_getvar(self, ["default_catalyst"], "HOBt Anhydrous")) or "HOBt Anhydrous"
            if r2 == "HOBt": r2 = "HOBt Anhydrous"
            base = _v248_canon(_v248_getvar(self, ["default_base"], ""))
            solvent = _v248_canon(_v248_getvar(self, ["default_coupling_solution_solvent"], "DMF")) or "DMF"
            note = "Regular AA coupling"
        unit_mmol = unit_eq * scale * copies * repeat
        mw, den, g, ml = _v248_calc_amount(self, unit, unit_mmol)
        working_ml = _v248_one_use_ml(self, scale, unit_eq, repeat, copies)
        row = {"No":str(idx), "Unit name":unit, "MW":mw, "Density(g/mL)":den, "Unit eq":_v248_s(unit_eq), "Unit amount(g)":g, "Unit volume(mL)":ml,
               "Coupling reagent 1":r1, "Coupling reagent 2 / catalyst":r2, "Coupling base":base,
               "Coupling cocktail solvent":solvent, "Coupling cocktail volume(mL)":_v248_s(working_ml), "Repeat":_v248_s(repeat), "Note":note}
        setup = [
            ("Reagent 1", r1, _v248_f(_v248_getvar(self, ["default_reagent_eq"], "10"), 10), _v248_getvar(self, ["default_reagent_count"], "1")),
            ("Reagent 2", r2, _v248_f(_v248_getvar(self, ["default_catalyst_eq"], "10"), 10), _v248_getvar(self, ["default_catalyst_count"], "1")),
            ("Base", base, (_v248_f(_v248_getvar(self, ["loading_diea_eq"], "4"), 4) if direct else _v248_f(_v248_getvar(self, ["default_base_eq"], "5"), 5)), _v248_getvar(self, ["default_base_count"], "1")),
        ]
        for prefix, name, eq_def, count_def in setup:
            if not name:
                row[f"{prefix} eq"] = row[f"{prefix} mmol"] = row[f"{prefix} g"] = row[f"{prefix} mL"] = ""
                continue
            eqv = eq_def if direct and prefix=="Base" else _v248_reagent_eq(self, idx, eq_def)
            cnt = _v248_reagent_count(self, idx, count_def)
            mm = eqv * scale * copies * repeat * cnt
            mw2, den2, g2, ml2 = _v248_calc_amount(self, name, mm)
            row[f"{prefix} eq"] = _v248_s(eqv)
            row[f"{prefix} mmol"] = _v248_s(mm)
            row[f"{prefix} g"] = g2
            row[f"{prefix} mL"] = ml2
        rows.append(row)
    try: seq = self.pm_sequence.get()
    except Exception: seq = ""
    if re.match(r"^\s*(Ac|AC)\s*[-_]", str(seq), flags=re.I):
        idx = len(rows)+1
        eq = _v248_f(_v248_getvar(self, ["modifier_eq"], "3"), 3)
        rep = max(1, int(round(_v248_f(_v248_getvar(self, ["modifier_repeats"], "1"), 1))))
        mm = eq * scale * copies * rep
        mw, den, g, ml = _v248_calc_amount(self, "Acetic anhydride (Ac2O)", mm)
        bmw, bden, bg, bml = _v248_calc_amount(self, "DIEA", mm)
        rows.append({"No":str(idx), "Unit name":"Acetic anhydride (Ac2O) for N-terminal acetylation",
                     "MW":mw, "Density(g/mL)":den, "Unit eq":_v248_s(eq), "Unit amount(g)":g, "Unit volume(mL)":ml,
                     "Coupling reagent 1":"", "Reagent 1 eq":"", "Reagent 1 mmol":"", "Reagent 1 g":"", "Reagent 1 mL":"",
                     "Coupling reagent 2 / catalyst":"", "Reagent 2 eq":"", "Reagent 2 mmol":"", "Reagent 2 g":"", "Reagent 2 mL":"",
                     "Coupling base":"DIEA", "Base eq":_v248_s(eq), "Base mmol":_v248_s(mm), "Base g":bg, "Base mL":bml,
                     "Coupling cocktail solvent":_v248_getvar(self, ["default_coupling_solution_solvent"], "DMF") or "DMF",
                     "Coupling cocktail volume(mL)":_v248_s(_v248_one_use_ml(self, scale, eq, rep, copies)),
                     "Repeat":_v248_s(rep), "Note":"N-terminal Ac cap; Ac2O + DIEA same mol"})
    return pd.DataFrame(rows).astype(str)

def _v248_amount(name, g="", ml="", density=""):
    if str(ml).strip() and _v248_f(ml,0):
        return f"{_v248_s(ml)} mL"
    if str(g).strip() and _v248_f(g,0):
        return f"{_v248_s(g)} g"
    return ""

def _v248_plan_display_df(self):
    base = _v248_plan_detailed(self)
    cols = _V236_PLAN_COLS if "_V236_PLAN_COLS" in globals() else []
    if base.empty:
        return pd.DataFrame(columns=cols)
    scale = _v248_f(self.pm_scale.get() if hasattr(self, "pm_scale") else 0.2)
    copies = max(1, int(round(_v248_f(self.pm_copies.get() if hasattr(self, "pm_copies") else 1, 1))))
    rows=[]
    for _, r in base.iterrows():
        def rdat(prefix, col):
            nm = _v248_canon(r.get(col,""))
            mw, den = _v248_lookup(self, nm) if nm else ("","")
            return nm, mw, den, r.get(f"{prefix} mmol",""), _v248_amount(nm, r.get(f"{prefix} g",""), r.get(f"{prefix} mL",""), den)
        r1n,r1mw,r1d,r1mm,r1amt = rdat("Reagent 1","Coupling reagent 1")
        r2n,r2mw,r2d,r2mm,r2amt = rdat("Reagent 2","Coupling reagent 2 / catalyst")
        bn,bmw,bd,bmm,bamt = rdat("Base","Coupling base")
        rep = max(1, int(round(_v248_f(r.get("Repeat"),1))))
        unit_mmol = _v248_f(r.get("Unit eq"),0) * scale * copies * rep
        rows.append({"No":r.get("No",""), "Unit name":r.get("Unit name",""), "MW":r.get("MW",""), "Density(g/mL)":r.get("Density(g/mL)",""),
                     "Unit mmol":_v248_s(unit_mmol), "Unit amount":_v248_amount(r.get("Unit name",""), r.get("Unit amount(g)",""), r.get("Unit volume(mL)",""), r.get("Density(g/mL)","")),
                     "Reagent 1":r1n, "R1 MW":r1mw, "R1 Density":r1d, "R1 mmol":r1mm, "R1 amount":r1amt,
                     "Reagent 2 / catalyst":r2n, "R2 MW":r2mw, "R2 Density":r2d, "R2 mmol":r2mm, "R2 amount":r2amt,
                     "Base":bn, "Base MW":bmw, "Base Density":bd, "Base mmol":bmm, "Base amount":bamt,
                     "Coupling solvent":r.get("Coupling cocktail solvent",""), "Solvent mL":r.get("Coupling cocktail volume(mL)",""),
                     "Repeat":r.get("Repeat",""), "Note":r.get("Note","")})
    return pd.DataFrame(rows, columns=cols).astype(str)

def _v248_write_tree(tree, df):
    cols = list(df.columns)
    tree.configure(columns=cols, show="headings")
    widths={"No":50,"Unit name":230,"MW":85,"Density(g/mL)":120,"Unit mmol":110,"Unit amount":120,
            "Reagent 1":120,"R1 MW":85,"R1 Density":100,"R1 mmol":110,"R1 amount":120,
            "Reagent 2 / catalyst":165,"R2 MW":85,"R2 Density":100,"R2 mmol":110,"R2 amount":120,
            "Base":110,"Base MW":85,"Base Density":100,"Base mmol":110,"Base amount":120,
            "Coupling solvent":160,"Solvent mL":100,"Repeat":70,"Note":300}
    for c in cols:
        tree.heading(c, text=c)
        tree.column(c, width=widths.get(c,140), minwidth=70, anchor="w", stretch=False)
    for iid in list(tree.get_children()):
        tree.delete(iid)
    for _, row in df.iterrows():
        tree.insert("", "end", values=[str(row.get(c,"")) for c in cols])

def _v248_recalc_visible_row(self, tree, iid):
    cols=list(tree["columns"])
    vals=list(tree.item(iid,"values"))
    while len(vals)<len(cols): vals.append("")
    def get(c): return vals[cols.index(c)] if c in cols else ""
    def setc(c,v):
        if c in cols: vals[cols.index(c)] = _v248_s(v)
    for c in ["Unit name","Reagent 1","Reagent 2 / catalyst","Base","Coupling solvent"]:
        if c in cols: setc(c, _v248_canon(get(c)))
    for name_col, mw_col, den_col, mmol_col, amt_col in [
        ("Unit name","MW","Density(g/mL)","Unit mmol","Unit amount"),
        ("Reagent 1","R1 MW","R1 Density","R1 mmol","R1 amount"),
        ("Reagent 2 / catalyst","R2 MW","R2 Density","R2 mmol","R2 amount"),
        ("Base","Base MW","Base Density","Base mmol","Base amount"),
    ]:
        nm=get(name_col)
        if not nm: continue
        mw,den=_v248_lookup(self,nm)
        setc(mw_col,mw); setc(den_col,den)
        mm=_v248_f(get(mmol_col),0)
        if mm and mw:
            g=mm*_v248_f(mw,0)/1000.0
            ml=g/_v248_f(den,1) if g and den else 0
            setc(amt_col, _v248_amount(nm, g, ml, den))
    tree.item(iid, values=vals)

def _v248_refresh_from_visible(self):
    try:
        if "_v238_visible_plan_to_materials" in globals():
            mats = _v238_visible_plan_to_materials(self)
        else:
            mats = pd.DataFrame()
        if hasattr(self, "pm_selected_material_tree"):
            display = mats[_V230_MAT_COLS].astype(str) if not mats.empty and "_V230_MAT_COLS" in globals() else mats.astype(str)
            _v248_write_tree(self.pm_selected_material_tree, display)
        if "_v228_ensure_total_tab" in globals(): _v228_ensure_total_tab(self)
        if hasattr(self, "pm_selected_total_tree") and "_v238_total_from_materials" in globals():
            _v248_write_tree(self.pm_selected_total_tree, _v238_total_from_materials(mats))
    except Exception:
        pass

def _v248_apply_plan(self):
    try:
        tree = getattr(self, "pm_selected_plan_tree", None)
        if tree is not None:
            for iid in tree.get_children():
                _v248_recalc_visible_row(self, tree, iid)
        _v248_refresh_from_visible(self)
        try: self.save_autosave_state()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass

def _v248_cell_dropdown(self, event):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None: return
    rowid = tree.identify_row(event.y)
    colid = tree.identify_column(event.x)
    if not rowid or not colid: return
    try:
        idx = int(colid.replace("#","")) - 1
        cols = list(tree["columns"])
        col = cols[idx]
    except Exception:
        return
    choices = _v248_options_for_col(self, col)
    if not choices: return
    bbox = tree.bbox(rowid, colid)
    if not bbox: return
    x,y,w,h = bbox
    vals = list(tree.item(rowid, "values"))
    cur = vals[idx] if idx < len(vals) else ""
    cb = ttk.Combobox(tree, values=choices, state="normal")
    cb.place(x=x, y=y, width=max(w, 200), height=h+4)
    cb.set(cur); cb.focus_set()
    def apply(_=None):
        vals2=list(tree.item(rowid, "values"))
        while len(vals2)<len(cols): vals2.append("")
        vals2[idx]=_v248_canon(cb.get())
        tree.item(rowid, values=vals2)
        cb.destroy()
        _v248_recalc_visible_row(self, tree, rowid)
    cb.bind("<<ComboboxSelected>>", apply)
    cb.bind("<Return>", apply)
    cb.bind("<FocusOut>", lambda e: cb.destroy())

def _v248_generate(self):
    try:
        _v248_init_state(self)
        if "_v244_add_mode_checkboxes" in globals(): _v244_add_mode_checkboxes(self)
        if "_v245_add_custom_db_tab" in globals(): _v245_add_custom_db_tab(self)
        if "_v247_add_working_volume_controls" in globals(): _v247_add_working_volume_controls(self)
        _v248_write_tree(self.pm_selected_plan_tree, _v248_plan_display_df(self))
        try: self.pm_selected_plan_tree.bind("<Double-1>", lambda e: _v248_cell_dropdown(self, e))
        except Exception: pass
        _v248_apply_plan(self)
        try:
            if "_v217_refresh_selected_checklist" in globals(): _v217_refresh_selected_checklist(self)
        except Exception: pass
        try: self.schedule_autosave()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v248_hide_duplicate_buttons(self):
    # Keep the first visible command button in selected plan area; hide duplicate patch-layer buttons.
    try:
        seen = {}
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button):
                        t = str(c.cget("text"))
                        if t in {"Apply Plan","Edit selected cell","Delete selected row","Refresh totals from visible plan"}:
                            if t == "Refresh totals from visible plan" or seen.get(t, 0) >= 1:
                                try: c.grid_remove()
                                except Exception: pass
                                try: c.pack_forget()
                                except Exception: pass
                            else:
                                seen[t] = seen.get(t,0) + 1
                                if t == "Apply Plan":
                                    c.configure(command=lambda: _v248_apply_plan(self))
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

try: _v248_old_build = SPPSGui._build
except Exception: _v248_old_build = None
try: _v248_old_collect = SPPSGui._collect_state
except Exception: _v248_old_collect = None
try: _v248_old_load = SPPSGui.load_autosave_state
except Exception: _v248_old_load = None

def _v248_collect_state(self):
    state = _v248_old_collect(self) if callable(_v248_old_collect) else {}
    try:
        _v248_init_state(self)
        state["custom_materials"] = self.custom_materials
        state["working_volume_mode"] = self.working_volume_mode.get()
        state["one_use_working_ml"] = self.one_use_working_ml.get()
        state["aa_solution_conc_m"] = self.aa_solution_conc_m.get()
    except Exception:
        pass
    return state

def _v248_load_state(self):
    try:
        if callable(_v248_old_load): _v248_old_load(self)
    except Exception:
        pass
    try:
        _v248_init_state(self)
        if self.state_file.exists():
            data = json.loads(self.state_file.read_text(encoding="utf-8"))
            cm = data.get("custom_materials", {})
            if isinstance(cm, dict): self.custom_materials = cm
            self.working_volume_mode.set(str(data.get("working_volume_mode", self.working_volume_mode.get())))
            self.one_use_working_ml.set(str(data.get("one_use_working_ml", self.one_use_working_ml.get())))
            self.aa_solution_conc_m.set(str(data.get("aa_solution_conc_m", self.aa_solution_conc_m.get())))
    except Exception:
        pass

def _v248_build(self):
    if getattr(self, "_v248_build_running", False): return
    self._v248_build_running = True
    try:
        # One controlled legacy build call to create UI, then all core logic is rebound to V2.0.48.
        if callable(_v248_old_build): _v248_old_build(self)
        try: self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        except Exception: pass
        _v248_init_state(self)
        try:
            if "_v244_add_mode_checkboxes" in globals(): _v244_add_mode_checkboxes(self)
            if "_v245_add_custom_db_tab" in globals(): _v245_add_custom_db_tab(self)
            if "_v247_add_working_volume_controls" in globals(): _v247_add_working_volume_controls(self)
        except Exception:
            pass
        try:
            if hasattr(self, "pm_selected_plan_tree"):
                self.pm_selected_plan_tree.bind("<Double-1>", lambda e: _v248_cell_dropdown(self, e))
                for c in list(self.pm_selected_plan_tree["columns"]):
                    self.pm_selected_plan_tree.column(c, stretch=False, minwidth=70)
        except Exception:
            pass
        _v248_hide_duplicate_buttons(self)
    finally:
        self._v248_build_running = False

# Critical final rebindings. None of these functions call previous v24x lookup/plan aliases.
_v237_lookup = _v248_lookup
_v238_lookup = _v248_lookup
_v239_lookup = _v248_lookup
_v241_lookup = _v248_lookup
_v242_lookup = _v248_lookup
_v243_lookup = _v248_lookup
_v244_lookup = _v248_lookup
_v245_lookup = _v248_lookup
