_v247_plan_detailed = _v248_plan_detailed
_v244_plan_detailed = _v248_plan_detailed
_v244_plan_display_df = _v248_plan_display_df
_v244_options_for_col = _v248_options_for_col
_v244_cell_dropdown = _v248_cell_dropdown
SPPSGui._collect_state = _v248_collect_state
SPPSGui.load_autosave_state = _v248_load_state
SPPSGui.pm_generate_selected = _v248_generate
SPPSGui.pm_calculate_all = _v248_generate
