def _v250_generate(self):
    try:
        if hasattr(self,"default_coupling_solution_solvent") and str(self.default_coupling_solution_solvent.get()).strip().upper() in {"","NMP"}:
            self.default_coupling_solution_solvent.set("DMF")
    except Exception: pass
    try:
        if callable(_v250_old_generate): _v250_old_generate(self)
    except Exception:
        try:
            if "_v248_generate" in globals(): _v248_generate(self)
        except Exception: pass
    try:
        tree=getattr(self,"pm_selected_plan_tree",None)
        if tree is not None:
            _v250_ensure_selected_plan_columns(self)
            tree.bind("<Double-1>", lambda e:_v250_cell_editor(self,e))
            for iid in tree.get_children(): _v250_recalc_visible_row(self,tree,iid)
        _v250_add_buttons(self)
        _v250_apply_plan(self)
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass

def _v250_build(self):
    if getattr(self,"_v250_build_running",False): return
    self._v250_build_running=True
    try:
        if callable(_v250_old_build): _v250_old_build(self)
        try: self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        except Exception: pass
        try:
            if hasattr(self,"default_coupling_solution_solvent") and str(self.default_coupling_solution_solvent.get()).strip().upper() in {"","NMP"}:
                self.default_coupling_solution_solvent.set("DMF")
        except Exception: pass
        try:
            if hasattr(self,"pm_selected_plan_tree"):
                _v250_ensure_selected_plan_columns(self)
                self.pm_selected_plan_tree.bind("<Double-1>", lambda e:_v250_cell_editor(self,e))
        except Exception: pass
        _v250_add_buttons(self)
        try:
            def walk(w):
                for c in w.winfo_children():
                    try:
                        if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                            c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                    except Exception: pass
                    walk(c)
            walk(self)
        except Exception: pass
    finally:
        self._v250_build_running=False

