# ======================= V2.0.51 SELECTED PLAN HARD FIX =======================
# Based on V2.0.50 package uploaded by user.
# Fix scope:
# - Remove V2.0.50 lookup alias recursion completely.
# - Keep MW / Density(g/mL) visible from the first generated Selected Plan view.
# - Keep double-click editing from wiping Treeview values.
# - Apply Plan rebuilds Materials/Total from the visible selected plan without deleting Selected Plan rows.
# - Use direct stable generator path to avoid slow nested legacy generate chains.
# ============================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V251_DISPLAY_COLS = list(_V250_DISPLAY_COLS) if "_V250_DISPLAY_COLS" in globals() else [
    "No","Unit name","MW","Density(g/mL)","Unit mmol","Unit amount",
    "Reagent 1","R1 MW","R1 Density","R1 mmol","R1 amount",
    "Reagent 2 / catalyst","R2 MW","R2 Density","R2 mmol","R2 amount",
    "Base","Base MW","Base Density","Base mmol","Base amount",
    "Coupling solvent","Solvent mL","Repeat","Note"
]

_V251_SYNONYMS = {
    "Unit eq": "Unit mmol",
    "Unit amount(g)": "Unit amount",
    "Unit volume(mL)": "Unit amount",
    "Coupling reagent 1": "Reagent 1",
    "Coupling reagent 2 / catalyst": "Reagent 2 / catalyst",
    "Coupling base": "Base",
    "Coupling cocktail solvent": "Coupling solvent",
    "Coupling cocktail volume(mL)": "Solvent mL",
    "Reagent 1 g": "R1 amount",
    "Reagent 1 mL": "R1 amount",
    "Reagent 2 g": "R2 amount",
    "Reagent 2 mL": "R2 amount",
    "Base g": "Base amount",
    "Base mL": "Base amount",
}


def _v251_norm(x):
    return re.sub(r"[^0-9a-z가-힣]+", "", str(x or "").lower())


def _v251_canon(x):
    raw = str(x or "").strip()
    n = _v251_norm(raw)
    try:
        for opt in _V250_AC_AA_OPTIONS:
            if n == _v251_norm(opt):
                return opt
    except Exception:
        pass
    aliases = {
        "hobt":"HOBt Anhydrous", "hobtanhydrous":"HOBt Anhydrous",
        "hobthydrate":"HOBt hydrate", "hobtmonohydrate":"HOBt hydrate",
        "gal":"Gallic acid", "gallic":"Gallic acid", "gallicacid":"Gallic acid",
        "pal":"Palmitic acid", "palmitic":"Palmitic acid", "palmiticacid":"Palmitic acid",
        "myr":"Myristic acid", "myristic":"Myristic acid", "myristicacid":"Myristic acid",
        "nic":"Nicotinic acid", "nicotinic":"Nicotinic acid", "nicotinicacid":"Nicotinic acid",
        "caf":"Caffeic acid", "caffeic":"Caffeic acid", "caffeicacid":"Caffeic acid",
        "ac":"Acetic anhydride (Ac2O)", "ac2o":"Acetic anhydride (Ac2O)",
        "aceticanhydride":"Acetic anhydride (Ac2O)",
        "cy55":"CY5.5", "strepii":"StrepII", "twinstrep":"TwinStrep", "avitag":"AviTag", "spytag":"SpyTag",
        "bala":"bAla", "gala":"gAla", "gly_gly":"Gly-Gly", "glygly":"Gly-Gly", "glyglygly":"Gly-Gly-Gly",
    }
    return aliases.get(n, raw)


def _v251_f(v, default=0.0):
    try:
        if callable(v) or v is None or str(v).strip() == "":
            return default
        return float(str(v).replace(",", "").replace("mL", "").replace("ml", "").replace("g", "").strip())
    except Exception:
        return default


def _v251_s(v):
    try:
        if v is None:
            return ""
        f = float(v)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f"{f:.6f}".rstrip("0").rstrip(".")
    except Exception:
        return "" if v is None else str(v)


def _v251_lookup(self, name):
    """Recursion-free MW/density lookup. Never calls _v248/_v249/_v250 aliases."""
    canon = _v251_canon(name)
    key = _v251_norm(canon)
    try:
        if hasattr(self, "custom_materials") and isinstance(self.custom_materials, dict):
            rec = self.custom_materials.get(key)
            if rec:
                return str(rec.get("mw", "") or ""), str(rec.get("density", "") or "")
    except Exception:
        pass
    try:
        if key in _V250_AC_AA_MW:
            return str(_V250_AC_AA_MW[key]), ""
    except Exception:
        pass
    try:
        if key in _V249_EXTRA_LOOKUP:
            mw, den = _V249_EXTRA_LOOKUP[key]
            return str(mw), str(den)
    except Exception:
        pass
    try:
        if key in _V248_LOOKUP_TABLE:
            mw, den = _V248_LOOKUP_TABLE[key]
            return str(mw), str(den)
    except Exception:
        pass
    try:
        old = globals().get("_v216_lookup_mw_density")
        if callable(old):
            mw, den = old(self, canon)
            if str(mw).strip():
                return str(mw), str(den)
    except Exception:
        pass
    return "", ""


def _v251_options_for_col(self, col):
    base = []
    try:
        if col == "Unit name":
            base += list(_V248_AA_OPTIONS)
            base += list(_V249_D_AA_OPTIONS) + list(_V249_NON_NAT_AA_OPTIONS) + list(_V249_CHEM_OPTIONS)
            base += list(_V249_LINKER_OPTIONS) + list(_V249_LABEL_OPTIONS) + list(_V249_TAG_OPTIONS)
            base += list(_V250_AC_AA_OPTIONS)
            try:
                base += _v248_custom_options(self, "AA/Chemical") + _v248_custom_options(self, "Other")
            except Exception:
                pass
        elif col == "Reagent 1":
            base += list(_V249_REAGENT_OPTIONS)
            try: base += _v248_custom_options(self, "Coupling reagent")
            except Exception: pass
        elif col == "Reagent 2 / catalyst":
            base += list(_V249_CATALYST_OPTIONS)
            try: base += _v248_custom_options(self, "Catalyst/additive")
            except Exception: pass
        elif col == "Base":
            base += list(_V249_BASE_OPTIONS)
            try: base += _v248_custom_options(self, "Base")
            except Exception: pass
        elif col == "Coupling solvent":
            base += list(_V249_SOLVENT_OPTIONS)
            try: base += _v248_custom_options(self, "Solvent")
            except Exception: pass
    except Exception:
        base = []
    out = []
    seen = set()
    for v in base:
        cv = _v251_canon(v)
        if cv and cv not in seen:
            out.append(cv); seen.add(cv)
    return out


def _v251_amount(name, g="", ml="", density=""):
    if str(ml).strip() and _v251_f(ml, 0):
        return f"{_v251_s(_v251_f(ml,0))} mL"
    if str(g).strip() and _v251_f(g, 0):
        return f"{_v251_s(_v251_f(g,0))} g"
    return ""


def _v251_ensure_selected_plan_columns(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    old_cols = list(tree["columns"] or [])
    old_iids = list(tree.get_children())
    old_rows = [list(tree.item(iid, "values")) for iid in old_iids]
    new_cols = list(_V251_DISPLAY_COLS)
    for c in old_cols:
        mapped = _V251_SYNONYMS.get(c, c)
        if mapped not in new_cols:
            new_cols.append(mapped)
    tree.configure(columns=new_cols, show="headings")
    widths = {
        "No":50, "Unit name":280, "MW":90, "Density(g/mL)":125, "Unit mmol":110, "Unit amount":130,
        "Reagent 1":125, "R1 MW":90, "R1 Density":110, "R1 mmol":110, "R1 amount":125,
        "Reagent 2 / catalyst":175, "R2 MW":90, "R2 Density":110, "R2 mmol":110, "R2 amount":125,
        "Base":115, "Base MW":90, "Base Density":110, "Base mmol":110, "Base amount":125,
        "Coupling solvent":170, "Solvent mL":115, "Repeat":75, "Note":330,
    }
    for c in new_cols:
        tree.heading(c, text=c)
        tree.column(c, width=widths.get(c, 130), minwidth=60, anchor="w", stretch=False)
    if old_rows and old_cols != new_cols:
        for iid in old_iids:
            try: tree.delete(iid)
            except Exception: pass
        for row in old_rows:
            m = {}
            for i, c in enumerate(old_cols):
                if i >= len(row):
                    continue
                mapped = _V251_SYNONYMS.get(c, c)
                if mapped not in m or not str(m.get(mapped, "")).strip():
                    m[mapped] = row[i]
            tree.insert("", "end", values=[m.get(c, "") for c in new_cols])


def _v251_recalc_visible_row(self, tree, iid, changed_col=None):
    cols = list(tree["columns"])
    vals = list(tree.item(iid, "values"))
    while len(vals) < len(cols):
        vals.append("")
    def get(c):
        return vals[cols.index(c)] if c in cols else ""
    def setc(c, v):
        if c in cols:
            vals[cols.index(c)] = _v251_s(v)
    dropdown_cols = ["Unit name", "Reagent 1", "Reagent 2 / catalyst", "Base", "Coupling solvent"]
    for c in dropdown_cols:
        if c in cols:
            setc(c, _v251_canon(get(c)))
    maps = [
        ("Unit name", "MW", "Density(g/mL)", "Unit mmol", "Unit amount"),
        ("Reagent 1", "R1 MW", "R1 Density", "R1 mmol", "R1 amount"),
        ("Reagent 2 / catalyst", "R2 MW", "R2 Density", "R2 mmol", "R2 amount"),
        ("Base", "Base MW", "Base Density", "Base mmol", "Base amount"),
    ]
    for name_col, mw_col, den_col, mmol_col, amt_col in maps:
        nm = get(name_col)
        if not str(nm).strip():
            continue
        mw = get(mw_col); den = get(den_col)
        # Re-lookup MW/Density when material changed or when MW/Density is blank. Preserve manual numeric edits otherwise.
        if changed_col == name_col or not str(mw).strip():
            lm, ld = _v251_lookup(self, nm)
            if lm: setc(mw_col, lm); mw = lm
            if ld or changed_col == name_col:
                setc(den_col, ld); den = ld
        elif not str(den).strip():
            _, ld = _v251_lookup(self, nm)
            if ld: setc(den_col, ld); den = ld
        mm = _v251_f(get(mmol_col), 0)
        mwf = _v251_f(get(mw_col), 0)
        denf = _v251_f(get(den_col), 0)
        if mm and mwf:
            g = mm * mwf / 1000.0
            ml = g / denf if denf else 0
            setc(amt_col, _v251_amount(nm, g, ml, denf))
    tree.item(iid, values=vals)


def _v251_write_tree(tree, df):
    if df is None:
        df = pd.DataFrame()
    cols = list(df.columns)
    tree.configure(columns=cols, show="headings")
    widths = {"material":230,"class":170,"MW":90,"Density(g/mL)":125,"total mmol":115,"total amount":155,"note":340}
    for c in cols:
        tree.heading(c, text=c)
        tree.column(c, width=widths.get(c, 130), minwidth=60, anchor="w", stretch=False)
    for iid in list(tree.get_children()):
        tree.delete(iid)
    for _, r in df.iterrows():
        tree.insert("", "end", values=[str(r.get(c, "")) for c in cols])


def _v251_visible_plan_to_materials(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return pd.DataFrame(columns=["material","class","MW","Density(g/mL)","total mmol","total amount","note","_mmol","_g","_mL"])
    _v251_ensure_selected_plan_columns(self)
    cols = list(tree["columns"])
    rows = []
    def val(vals, c):
        return vals[cols.index(c)] if c in cols and cols.index(c) < len(vals) else ""
    def add(material, cls, mw, den, mmol, amount, note):
        if not str(material).strip():
            return
        amount = str(amount or "")
        g = 0.0; ml = 0.0
        m = re.search(r"([-+]?\d*\.?\d+)", amount)
        if m:
            num = float(m.group(1))
            if "ml" in amount.lower(): ml = num
            elif "g" in amount.lower(): g = num
            else: g = num
        rows.append({"material": material, "class": cls, "MW": mw, "Density(g/mL)": den,
                     "total mmol": _v251_s(_v251_f(mmol,0)) if str(mmol).strip() else "",
                     "total amount": amount, "note": note, "_mmol": _v251_f(mmol,0), "_g": g, "_mL": ml})
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values"))
        add(val(vals,"Unit name"), "AA/Chemical", val(vals,"MW"), val(vals,"Density(g/mL)"), val(vals,"Unit mmol"), val(vals,"Unit amount"), "Visible Selected Plan")
        add(val(vals,"Reagent 1"), "Coupling reagent", val(vals,"R1 MW"), val(vals,"R1 Density"), val(vals,"R1 mmol"), val(vals,"R1 amount"), "Visible Selected Plan")
        add(val(vals,"Reagent 2 / catalyst"), "Catalyst/additive", val(vals,"R2 MW"), val(vals,"R2 Density"), val(vals,"R2 mmol"), val(vals,"R2 amount"), "Visible Selected Plan")
        add(val(vals,"Base"), "Base", val(vals,"Base MW"), val(vals,"Base Density"), val(vals,"Base mmol"), val(vals,"Base amount"), "Visible Selected Plan")
        solvent = val(vals,"Coupling solvent")
        smL = val(vals,"Solvent mL")
        if solvent and _v251_f(smL, 0):
            add(solvent, "Coupling solvent", "", "", "", f"{_v251_s(_v251_f(smL,0))} mL", "Visible/manual solvent mL")
    return pd.DataFrame(rows)


def _v251_total_from_materials(mats):
    cols = ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]
    if mats is None or mats.empty:
        return pd.DataFrame(columns=cols)
    out = []
    for mat, gp in mats.groupby("material", dropna=False):
        cls = " / ".join(sorted(set(str(x) for x in gp.get("class", []) if str(x).strip())))
        mw = next((str(x) for x in gp.get("MW", []) if str(x).strip()), "")
        den = next((str(x) for x in gp.get("Density(g/mL)", []) if str(x).strip()), "")
        mmol = sum(_v251_f(x,0) for x in gp.get("_mmol", []))
        grams = sum(_v251_f(x,0) for x in gp.get("_g", []))
        mls = sum(_v251_f(x,0) for x in gp.get("_mL", []))
        if grams and mls: amount = f"{_v251_s(grams)} g / {_v251_s(mls)} mL"
        elif mls: amount = f"{_v251_s(mls)} mL"
        elif grams: amount = f"{_v251_s(grams)} g"
        else: amount = ""
        out.append({"material": mat, "class": cls, "MW": mw, "Density(g/mL)": den,
                    "total mmol": _v251_s(mmol) if mmol else "", "total amount": amount,
                    "note": "Merged from visible Selected Plan"})
    return pd.DataFrame(out, columns=cols)


def _v251_apply_plan(self):
    try:
        tree = getattr(self, "pm_selected_plan_tree", None)
        if tree is not None:
            _v251_ensure_selected_plan_columns(self)
            for iid in list(tree.get_children()):
                _v251_recalc_visible_row(self, tree, iid)
        mats = _v251_visible_plan_to_materials(self)
        show_cols = ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]
        if hasattr(self, "pm_selected_material_tree"):
            _v251_write_tree(self.pm_selected_material_tree, mats[show_cols] if not mats.empty else pd.DataFrame(columns=show_cols))
        try:
            if "_v228_ensure_total_tab" in globals(): _v228_ensure_total_tab(self)
        except Exception:
            pass
        if hasattr(self, "pm_selected_total_tree"):
            _v251_write_tree(self.pm_selected_total_tree, _v251_total_from_materials(mats))
        try: self.save_autosave_state()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass


def _v251_cell_editor(self, event):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    _v251_ensure_selected_plan_columns(self)
    rowid = tree.identify_row(event.y); colid = tree.identify_column(event.x)
    if not rowid or not colid:
        return
    try:
        idx = int(colid.replace("#", "")) - 1
        cols = list(tree["columns"])
        if idx < 0 or idx >= len(cols):
            return
        col = cols[idx]
    except Exception:
        return
    bbox = tree.bbox(rowid, colid)
    if not bbox:
        return
    x, y, w, h = bbox
    vals = list(tree.item(rowid, "values"))
    while len(vals) < len(cols): vals.append("")
    cur = vals[idx]
    dropdown_cols = {"Unit name", "Reagent 1", "Reagent 2 / catalyst", "Base", "Coupling solvent"}
    text_cols = {"MW","Density(g/mL)","Unit mmol","Unit amount","R1 MW","R1 Density","R1 mmol","R1 amount",
                 "R2 MW","R2 Density","R2 mmol","R2 amount","Base MW","Base Density","Base mmol","Base amount",
                 "Solvent mL","Repeat","Note"}
    if col in dropdown_cols:
        widget = ttk.Combobox(tree, values=_v251_options_for_col(self, col), state="normal")
        widget.set(cur)
    elif col in text_cols:
        widget = ttk.Entry(tree)
        widget.insert(0, cur)
    else:
        return
    widget.place(x=x, y=y, width=max(w, 190), height=h+4)
    widget.focus_set()
    done = {"v": False}
    def apply(_=None):
        if done["v"]:
            return
        done["v"] = True
        try:
            vals2 = list(tree.item(rowid, "values"))
            while len(vals2) < len(cols): vals2.append("")
            new = widget.get()
            if col in dropdown_cols:
                new = _v251_canon(new)
            vals2[idx] = new
            tree.item(rowid, values=vals2)
            _v251_recalc_visible_row(self, tree, rowid, changed_col=(col if col in dropdown_cols else None))
        finally:
            try: widget.destroy()
            except Exception: pass
    widget.bind("<Return>", apply)
    widget.bind("<Escape>", lambda e: widget.destroy())
    if isinstance(widget, ttk.Combobox):
        widget.bind("<<ComboboxSelected>>", apply)
    # FocusOut applies instead of just destroying; this prevents the blank/wipe behavior seen in V2.0.50.
    widget.bind("<FocusOut>", apply)


def _v251_delete_selected_rows(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    sel = list(tree.selection())
    if not sel:
        return
    for iid in sel:
        try: tree.delete(iid)
        except Exception: pass
    cols = list(tree["columns"])
    if "No" in cols:
        idx = cols.index("No")
        for n, iid in enumerate(tree.get_children(), 1):
            vals = list(tree.item(iid, "values"))
            while len(vals) < len(cols): vals.append("")
            vals[idx] = str(n)
            tree.item(iid, values=vals)
    _v251_apply_plan(self)


def _v251_add_buttons(self):
    try:
        tree = getattr(self, "pm_selected_plan_tree", None)
        if tree is None:
            return
        parent = tree.master
        if not hasattr(self, "_v251_buttons_added"):
            self._v251_buttons_added = True
            bar = ttk.Frame(parent)
            try: bar.grid(row=4, column=0, sticky="w", padx=4, pady=2)
            except Exception: bar.pack(anchor="w", padx=4, pady=2)
            ttk.Button(bar, text="Delete selected row", command=lambda:_v251_delete_selected_rows(self)).pack(side="left", padx=3)
            ttk.Button(bar, text="Apply Plan", command=lambda:_v251_apply_plan(self)).pack(side="left", padx=3)
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Button):
                        t = str(c.cget("text"))
                        if t == "Apply Plan": c.configure(command=lambda:_v251_apply_plan(self))
                        elif t == "Delete selected row": c.configure(command=lambda:_v251_delete_selected_rows(self))
                except Exception: pass
                walk(c)
        walk(parent)
    except Exception:
        pass


def _v251_generate(self):
    try:
        if hasattr(self, "default_coupling_solution_solvent") and str(self.default_coupling_solution_solvent.get()).strip().upper() in {"", "NMP"}:
            self.default_coupling_solution_solvent.set("DMF")
    except Exception:
        pass
    try:
        # Fast, stable, non-nested generation path from V2.0.48. Lookup/options are rebound below to V2.0.51.
        _v248_init_state(self)
        if "_v244_add_mode_checkboxes" in globals(): _v244_add_mode_checkboxes(self)
        if "_v245_add_custom_db_tab" in globals(): _v245_add_custom_db_tab(self)
        if "_v247_add_working_volume_controls" in globals(): _v247_add_working_volume_controls(self)
        df = _v248_plan_display_df(self) if "_v248_plan_display_df" in globals() else pd.DataFrame(columns=_V251_DISPLAY_COLS)
        if df is None or df.empty:
            df = pd.DataFrame(columns=_V251_DISPLAY_COLS)
        # Guarantee V2.0.51 visible columns even if older plan function returns a previous shape.
        for c in _V251_DISPLAY_COLS:
            if c not in df.columns: df[c] = ""
        df = df[_V251_DISPLAY_COLS].astype(str)
        _v251_write_tree(self.pm_selected_plan_tree, df)
        _v251_ensure_selected_plan_columns(self)
        self.pm_selected_plan_tree.bind("<Double-1>", lambda e:_v251_cell_editor(self, e))
        for iid in list(self.pm_selected_plan_tree.get_children()):
            _v251_recalc_visible_row(self, self.pm_selected_plan_tree, iid)
        _v251_add_buttons(self)
        _v251_apply_plan(self)
        try:
            if "_v217_refresh_selected_checklist" in globals(): _v217_refresh_selected_checklist(self)
        except Exception: pass
        try: self.schedule_autosave()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass


def _v251_build(self):
    if getattr(self, "_v251_build_running", False):
        return
    self._v251_build_running = True
    try:
        if callable(_v250_old_build):
            _v250_old_build(self)
        try: self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        except Exception: pass
        try:
            if hasattr(self, "default_coupling_solution_solvent") and str(self.default_coupling_solution_solvent.get()).strip().upper() in {"", "NMP"}:
                self.default_coupling_solution_solvent.set("DMF")
        except Exception: pass
        try:
            if hasattr(self, "pm_selected_plan_tree"):
                _v251_ensure_selected_plan_columns(self)
                self.pm_selected_plan_tree.bind("<Double-1>", lambda e:_v251_cell_editor(self, e))
        except Exception: pass
        _v251_add_buttons(self)
        try:
            def walk(w):
                for c in w.winfo_children():
                    try:
                        if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                            c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                    except Exception: pass
                    walk(c)
            walk(self)
        except Exception: pass
    finally:
        self._v251_build_running = False

