# ======================= V2.0.52 SOLVENT TOTALS + INPUT UX FIX =======================
# Based on V2.0.51. Preserves all V2.0.51 selected-plan/edit/delete/custom DB behavior.
# Fix scope requested by user:
# - Selected Total Materials includes DCM final wash.
# - Mixed solvent "90% DCM / 10% DMF" is split by volume into DCM and DMF totals.
# - Solvent totals are merged by actual solvent species, not by mixture label.
# - Last DCM x3 wash is added as a material total because it exists in Selected Checklist/workflow.
# - Default AA eq Entry uses StringVar so typing "1" stays "1" instead of auto-becoming "1.0".
# ====================================================================================

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v252_get_float_var(self, names, default=0.0):
    for name in names:
        try:
            if hasattr(self, name):
                v = getattr(self, name).get()
                return _v251_f(v, default)
        except Exception:
            pass
    return default


def _v252_norm_solvent_name(name):
    raw = str(name or "").strip()
    u = re.sub(r"\s+", "", raw.upper())
    aliases = {
        "MECN": "ACN", "H2O": "Water", "DW": "Water", "DIWATER": "Water",
        "DICHLOROMETHANE": "DCM", "METHYLENECHLORIDE": "DCM",
        "DIMETHYLFORMAMIDE": "DMF", "N-METHYL-2-PYRROLIDONE": "NMP",
    }
    if u in aliases:
        return aliases[u]
    standard = {"DMF":"DMF", "DCM":"DCM", "NMP":"NMP", "ACN":"ACN", "MECN":"ACN", "TFA":"TFA", "TIS":"TIS", "EDT":"EDT", "PIPERIDINE":"Piperidine", "WATER":"Water"}
    return standard.get(u, raw)


def _v252_split_solvent(solvent, total_ml):
    """Return [(material, ml, note)] with mixed solvents split by volume ratio."""
    name = str(solvent or "").strip()
    ml = _v251_f(total_ml, 0)
    if not name or not ml:
        return []
    u = re.sub(r"\s+", "", name.upper())
    if ("90%DCM" in u and "10%DMF" in u) or ("10%DMF" in u and "DCM" in u):
        return [("DCM", ml * 0.90, "Split from 90% DCM / 10% DMF by volume"),
                ("DMF", ml * 0.10, "Split from 90% DCM / 10% DMF by volume")]
    if "20%PIPERIDINE" in u and "DMF" in u:
        return [("Piperidine", ml * 0.20, "Split from 20% piperidine/DMF by volume"),
                ("DMF", ml * 0.80, "Split from 20% piperidine/DMF by volume")]
    if "TFA" in u and ("TIS" in u or "DW" in u or "WATER" in u) and ":" in name:
        parts = re.split(r"[:/]", name)
        nums = [float(x) for x in re.findall(r"(\d+(?:\.\d+)?)", name)]
        labels = []
        for part in parts:
            pp = part.upper()
            if "TFA" in pp: labels.append("TFA")
            elif "TIS" in pp: labels.append("TIS")
            elif "DW" in pp or "WATER" in pp or "H2O" in pp: labels.append("Water")
        if len(nums) == len(labels) and sum(nums) > 0:
            s = sum(nums)
            return [(lab, ml * n / s, f"Split from {name} by stated ratio") for lab, n in zip(labels, nums)]
        return [(name, ml, "Cocktail kept as label because exact ratio was not specified")]
    return [(_v252_norm_solvent_name(name), ml, "Solvent total from Selected Plan")]


def _v252_add_material_row(rows, material, cls, mw, den, mmol, amount, note, *, forced_ml=None, forced_g=None):
    if not str(material).strip():
        return
    amount = str(amount or "")
    g = 0.0; ml = 0.0
    if forced_ml is not None:
        ml = _v251_f(forced_ml, 0)
        amount = f"{_v251_s(ml)} mL" if ml else amount
    elif forced_g is not None:
        g = _v251_f(forced_g, 0)
        amount = f"{_v251_s(g)} g" if g else amount
    else:
        m = re.search(r"([-+]?\d*\.?\d+)", amount)
        if m:
            num = float(m.group(1))
            if "ml" in amount.lower(): ml = num
            elif "g" in amount.lower(): g = num
            else: g = num
    rows.append({"material": material, "class": cls, "MW": mw, "Density(g/mL)": den,
                 "total mmol": _v251_s(_v251_f(mmol,0)) if str(mmol).strip() else "",
                 "total amount": amount, "note": note, "_mmol": _v251_f(mmol,0), "_g": g, "_mL": ml})


def _v252_add_final_wash_solvents(self, rows):
    scale = _v252_get_float_var(self, ["pm_scale", "scale"], 0.0)
    copies = max(int(round(_v252_get_float_var(self, ["pm_copies"], 1))), 1)
    ml_per = _v252_get_float_var(self, ["ml_per_mmol"], 10.0)
    if not scale or not ml_per:
        return
    working_ml = scale * ml_per * copies
    for solvent in ["DMF", "DCM"]:
        _v252_add_material_row(rows, solvent, "Final wash solvent", "", "", "", f"{_v251_s(working_ml * 3)} mL",
                               f"Selected Checklist final wash {solvent} x3; working mL={_v251_s(working_ml)}", forced_ml=working_ml * 3)


def _v252_visible_plan_to_materials(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return pd.DataFrame(columns=["material","class","MW","Density(g/mL)","total mmol","total amount","note","_mmol","_g","_mL"])
    _v251_ensure_selected_plan_columns(self)
    cols = list(tree["columns"])
    rows = []
    def val(vals, c):
        return vals[cols.index(c)] if c in cols and cols.index(c) < len(vals) else ""
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values"))
        _v252_add_material_row(rows, val(vals,"Unit name"), "AA/Chemical", val(vals,"MW"), val(vals,"Density(g/mL)"), val(vals,"Unit mmol"), val(vals,"Unit amount"), "Visible Selected Plan")
        _v252_add_material_row(rows, val(vals,"Reagent 1"), "Coupling reagent", val(vals,"R1 MW"), val(vals,"R1 Density"), val(vals,"R1 mmol"), val(vals,"R1 amount"), "Visible Selected Plan")
        _v252_add_material_row(rows, val(vals,"Reagent 2 / catalyst"), "Catalyst/additive", val(vals,"R2 MW"), val(vals,"R2 Density"), val(vals,"R2 mmol"), val(vals,"R2 amount"), "Visible Selected Plan")
        _v252_add_material_row(rows, val(vals,"Base"), "Base", val(vals,"Base MW"), val(vals,"Base Density"), val(vals,"Base mmol"), val(vals,"Base amount"), "Visible Selected Plan")
        solvent = val(vals,"Coupling solvent")
        smL = _v251_f(val(vals,"Solvent mL"), 0)
        if solvent and smL:
            for mat, split_ml, split_note in _v252_split_solvent(solvent, smL):
                _v252_add_material_row(rows, mat, "Solvent/wash", "", "", "", f"{_v251_s(split_ml)} mL", split_note, forced_ml=split_ml)
    if tree.get_children():
        _v252_add_final_wash_solvents(self, rows)
    return pd.DataFrame(rows)


def _v252_total_from_materials(mats):
    cols = ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]
    if mats is None or mats.empty:
        return pd.DataFrame(columns=cols)
    out = []
    for mat, gp in mats.groupby("material", dropna=False, sort=False):
        cls = " / ".join(sorted(set(str(x) for x in gp.get("class", []) if str(x).strip())))
        mw = next((str(x) for x in gp.get("MW", []) if str(x).strip()), "")
        den = next((str(x) for x in gp.get("Density(g/mL)", []) if str(x).strip()), "")
        mmol = sum(_v251_f(x,0) for x in gp.get("_mmol", []))
        grams = sum(_v251_f(x,0) for x in gp.get("_g", []))
        mls = sum(_v251_f(x,0) for x in gp.get("_mL", []))
        if grams and mls: amount = f"{_v251_s(grams)} g / {_v251_s(mls)} mL"
        elif mls: amount = f"{_v251_s(mls)} mL"
        elif grams: amount = f"{_v251_s(grams)} g"
        else: amount = ""
        notes = []
        for n in gp.get("note", []):
            ns = str(n).strip()
            if ns and ns not in notes:
                notes.append(ns)
        out.append({"material": mat, "class": cls, "MW": mw, "Density(g/mL)": den,
                    "total mmol": _v251_s(mmol) if mmol else "", "total amount": amount,
                    "note": " | ".join(notes[:4])})
    return pd.DataFrame(out, columns=cols)


def _v252_apply_plan(self):
    try:
        tree = getattr(self, "pm_selected_plan_tree", None)
        if tree is not None:
            _v251_ensure_selected_plan_columns(self)
            for iid in list(tree.get_children()):
                _v251_recalc_visible_row(self, tree, iid)
        mats = _v252_visible_plan_to_materials(self)
        show_cols = ["material","class","MW","Density(g/mL)","total mmol","total amount","note"]
        if hasattr(self, "pm_selected_material_tree"):
            _v251_write_tree(self.pm_selected_material_tree, mats[show_cols] if not mats.empty else pd.DataFrame(columns=show_cols))
        try:
            if "_v228_ensure_total_tab" in globals(): _v228_ensure_total_tab(self)
        except Exception:
            pass
        if hasattr(self, "pm_selected_total_tree"):
            _v251_write_tree(self.pm_selected_total_tree, _v252_total_from_materials(mats))
        try: self.save_autosave_state()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass


def _v252_generate(self):
    try:
        if hasattr(self, "default_coupling_solution_solvent") and str(self.default_coupling_solution_solvent.get()).strip().upper() in {"", "NMP"}:
            self.default_coupling_solution_solvent.set("DMF")
    except Exception:
        pass
    try:
        _v248_init_state(self)
        if "_v244_add_mode_checkboxes" in globals(): _v244_add_mode_checkboxes(self)
        if "_v245_add_custom_db_tab" in globals(): _v245_add_custom_db_tab(self)
        if "_v247_add_working_volume_controls" in globals(): _v247_add_working_volume_controls(self)
        df = _v248_plan_display_df(self) if "_v248_plan_display_df" in globals() else pd.DataFrame(columns=_V251_DISPLAY_COLS)
        if df is None or df.empty:
            df = pd.DataFrame(columns=_V251_DISPLAY_COLS)
        for c in _V251_DISPLAY_COLS:
            if c not in df.columns: df[c] = ""
        df = df[_V251_DISPLAY_COLS].astype(str)
        _v251_write_tree(self.pm_selected_plan_tree, df)
        _v251_ensure_selected_plan_columns(self)
        self.pm_selected_plan_tree.bind("<Double-1>", lambda e:_v251_cell_editor(self, e))
        for iid in list(self.pm_selected_plan_tree.get_children()):
            _v251_recalc_visible_row(self, self.pm_selected_plan_tree, iid)
        _v251_add_buttons(self)
        try:
            if "_v217_refresh_selected_checklist" in globals(): _v217_refresh_selected_checklist(self)
        except Exception: pass
        _v252_apply_plan(self)
        try: self.schedule_autosave()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror("Project Manager", str(e))
        except Exception: pass


def _v252_build(self):
    if getattr(self, "_v252_build_running", False):
        return
    self._v252_build_running = True
    try:
        if callable(_v250_old_build):
            _v250_old_build(self)
        try:
            if hasattr(self, "coupling_eq") and not isinstance(self.coupling_eq, tk.StringVar):
                self.coupling_eq = tk.StringVar(value=_v251_s(self.coupling_eq.get()))
        except Exception:
            pass
        try: self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        except Exception: pass
        try:
            if hasattr(self, "default_coupling_solution_solvent") and str(self.default_coupling_solution_solvent.get()).strip().upper() in {"", "NMP"}:
                self.default_coupling_solution_solvent.set("DMF")
        except Exception: pass
        try:
            if hasattr(self, "pm_selected_plan_tree"):
                _v251_ensure_selected_plan_columns(self)
                self.pm_selected_plan_tree.bind("<Double-1>", lambda e:_v251_cell_editor(self, e))
        except Exception: pass
        _v251_add_buttons(self)
        try:
            def walk(w):
                for c in w.winfo_children():
                    try:
                        if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                            c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                    except Exception: pass
                    walk(c)
            walk(self)
        except Exception: pass
    finally:
        self._v252_build_running = False

SPPSGui.pm_generate_selected = _v252_generate
SPPSGui.pm_calculate_all = _v252_generate
