# ======================= V2.0.53 DEFAULT AA EQ TYPING HARD FIX =======================
# Fix target: typing "1" in Default AA eq must stay "1".  The older V2.0.5 sync
# path treated a temporarily empty Entry as invalid and immediately restored the
# fallback 10.0, so normal select/delete/type workflows could become 10.0.

def _v253_eq_text(var):
    try:
        s = str(var.get()).strip()
    except Exception:
        return None
    if s == "":
        return None
    # Allow natural in-progress numeric typing such as "1." or ".5" without
    # replacing the text.  Reject only truly non-numeric values.
    try:
        f = float(s)
    except Exception:
        return None
    if f <= 0:
        return None
    return s


def _v253_set_eq_var(var, text):
    if text is None:
        return
    try:
        f = float(str(text).strip())
    except Exception:
        return
    try:
        if isinstance(var, tk.StringVar):
            # Keep the exact user-facing text: "1" remains "1", not "1.0" or "10.0".
            cur = str(var.get())
            if cur != str(text):
                var.set(str(text))
        else:
            cur = float(var.get())
            if abs(cur - f) > 1e-12:
                var.set(f)
    except Exception:
        try:
            var.set(str(text))
        except Exception:
            pass


def _v205_sync_eq_fields(self, source="pm"):
    """V2.0.53: non-destructive eq sync.

    - Empty/in-progress Entry text is ignored instead of restored to fallback 10.0.
    - Default AA eq StringVar preserves the typed string exactly.
    - Existing linked defaults remain connected, but user typing is not overwritten.
    """
    if getattr(self, '_v205_syncing_defaults', False):
        return
    self._v205_syncing_defaults = True
    try:
        if source == "batch":
            text = _v253_eq_text(getattr(self, 'batch_coupling_eq', None))
            if text is None:
                text = _v253_eq_text(getattr(self, 'coupling_eq', None))
        else:
            text = _v253_eq_text(getattr(self, 'coupling_eq', None))
        if text is None:
            return
        for name in ('coupling_eq', 'default_reagent_eq', 'default_catalyst_eq', 'batch_coupling_eq', 'batch_hbtu_eq'):
            if hasattr(self, name):
                _v253_set_eq_var(getattr(self, name), text)
        try:
            self.after_idle(self.refresh_batch_workspace_preview)
        except Exception:
            pass
        try:
            self.after_idle(lambda: _v204_sync_everything(self) if '_v204_sync_everything' in globals() else None)
        except Exception:
            pass
    finally:
        self._v205_syncing_defaults = False


def _v205_install_default_sync(self):
    """V2.0.53: install safe traces without forcing 5/blank to 10.0."""
    if getattr(self, '_v205_default_sync_installed', False):
        return
    self._v205_default_sync_installed = True
    try:
        if hasattr(self, 'batch_solution_conc') and str(self.batch_solution_conc.get()).strip() in ('', '0', '0.0'):
            self.batch_solution_conc.set('0.25')
    except Exception:
        pass
    # Initial sync only when a valid explicit value already exists.  No 5->10 forced upgrade.
    try:
        _v205_sync_eq_fields(self, source='pm')
    except Exception:
        pass
    # Bind only the two AA-ratio source fields.  Reagent/catalyst fields stay editable
    # and are updated from Default AA eq, but do not hijack Default AA eq while typing.
    pairs = [
        ('coupling_eq', 'pm'),
        ('batch_coupling_eq', 'batch'),
        ('batch_hbtu_eq', 'batch'),
    ]
    for attr, src in pairs:
        try:
            var = getattr(self, attr)
            var.trace_add('write', lambda *_, _src=src: _v205_sync_eq_fields(self, source=_src))
        except Exception:
            pass
    for attr in ('batch_solution_conc', 'batch_actual_round_ml', 'batch_actual_extra_ml', 'batch_hbtu_conc'):
        try:
            var = getattr(self, attr)
            var.trace_add('write', lambda *_: _v205_sync_conc_fields(self))
        except Exception:
            pass


def _v253_build(self):
    if callable(_v252_build):
        _v252_build(self)
    try:
        if hasattr(self, "coupling_eq") and not isinstance(self.coupling_eq, tk.StringVar):
            self.coupling_eq = tk.StringVar(value=_v251_s(self.coupling_eq.get()))
    except Exception:
        pass
    try:
        self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
    except Exception:
        pass
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception:
                    pass
                walk(c)
        walk(self)
    except Exception:
        pass

SPPSGui._build = _v253_build
