# ======================= V2.0.54 BUTTON + DROPDOWN + CHECKLIST FINAL FIX =======================
# Based on V2.0.53.  This patch keeps the existing V2.0.51/52/53 feature chain and only fixes
# the requested final UI/data-linkage issues:
# 1) exactly one Apply Plan and one Delete selected row button in the Selected Plan top toolbar,
# 2) Unit name/Reagent/Base/Solvent dropdown opens immediately and is removed on cancel/click-away,
# 3) Set defaults edits are applied to Selected Plan on Apply Plan without regenerating the entire UI,
# 4) Selected Checklist is refreshed from the current Selected Plan on Apply Plan,
# 5) unnecessary View controls inside Selected Checklist are removed.
# ===============================================================================================
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v254_widget_text(widget):
    try:
        return str(widget.cget("text"))
    except Exception:
        return ""


def _v254_tree_parent(tree):
    try:
        return tree.master
    except Exception:
        return None


def _v254_destroy_legacy_selected_plan_buttons(self):
    """Remove duplicated legacy Selected Plan Apply/Delete buttons while keeping global-action buttons."""
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    parent = _v254_tree_parent(tree)
    if parent is None:
        return
    keep = getattr(self, "_v254_plan_toolbar", None)
    kill_text = {"Apply Plan", "Delete selected row", "Refresh totals from visible plan", "Edit selected cell"}

    def walk(w):
        for child in list(w.winfo_children()):
            if child is keep:
                continue
            try:
                if isinstance(child, ttk.Button) and _v254_widget_text(child) in kill_text:
                    child.destroy()
                    continue
            except Exception:
                pass
            try:
                kids = list(child.winfo_children())
                labels = [_v254_widget_text(k) for k in kids if isinstance(k, ttk.Button)]
                if labels and all(t in kill_text for t in labels):
                    child.destroy()
                    continue
            except Exception:
                pass
            try:
                walk(child)
            except Exception:
                pass
    try:
        walk(parent)
    except Exception:
        pass


def _v254_install_selected_plan_toolbar(self):
    """Create the one authoritative Selected Plan toolbar above the tree."""
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    parent = _v254_tree_parent(tree)
    if parent is None:
        return
    _v254_destroy_legacy_selected_plan_buttons(self)
    try:
        parent.grid_rowconfigure(0, weight=0)
        parent.grid_rowconfigure(1, weight=1)
        parent.grid_rowconfigure(2, weight=0)
        parent.grid_columnconfigure(0, weight=1)
        parent.grid_columnconfigure(1, weight=0)
    except Exception:
        pass
    vbar = hbar = None
    try:
        for child in parent.winfo_children():
            if isinstance(child, ttk.Scrollbar):
                orient = str(child.cget("orient")).lower()
                if orient == "vertical": vbar = child
                elif orient == "horizontal": hbar = child
    except Exception:
        pass
    try: tree.grid(row=1, column=0, sticky="nsew")
    except Exception: pass
    try:
        if vbar is not None: vbar.grid(row=1, column=1, sticky="ns")
        if hbar is not None: hbar.grid(row=2, column=0, sticky="ew")
    except Exception: pass
    old = getattr(self, "_v254_plan_toolbar", None)
    try:
        if old is not None and old.winfo_exists(): old.destroy()
    except Exception:
        pass
    toolbar = ttk.Frame(parent)
    self._v254_plan_toolbar = toolbar
    try: toolbar.grid(row=0, column=0, sticky="w", padx=6, pady=(4, 4))
    except Exception: toolbar.pack(anchor="w", padx=6, pady=(4, 4))
    ttk.Button(toolbar, text="Apply Plan", command=lambda: _v254_apply_plan(self)).pack(side="left", padx=(0, 6))
    ttk.Button(toolbar, text="Delete selected row", command=lambda: _v254_delete_selected_rows(self)).pack(side="left", padx=(0, 6))


def _v254_delete_selected_rows(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return
    for iid in list(tree.selection()):
        try: tree.delete(iid)
        except Exception: pass
    cols = list(tree["columns"])
    if "No" in cols:
        idx = cols.index("No")
        for n, iid in enumerate(tree.get_children(), 1):
            vals = list(tree.item(iid, "values"))
            while len(vals) < len(cols): vals.append("")
            vals[idx] = str(n)
            tree.item(iid, values=vals)
    _v254_apply_plan(self)


def _v254_get_default_snapshot(self):
    names = [
        "coupling_eq", "coupling_repeats", "modifier_eq", "modifier_repeats", "ml_per_mmol",
        "default_reagent", "default_reagent_eq", "default_reagent_count",
        "default_catalyst", "default_catalyst_eq", "default_catalyst_count",
        "default_base", "default_base_eq", "default_base_count",
        "default_coupling_solution_solvent", "default_solvent1", "default_solvent1_count",
        "default_solvent2", "default_solvent2_count", "default_loading_dissolve_solvent",
        "default_depro", "default_depro_ratio", "default_depro_count",
    ]
    out = {}
    for name in names:
        try:
            if hasattr(self, name): out[name] = str(getattr(self, name).get())
        except Exception:
            pass
    return out


def _v254_mark_defaults_dirty(self, *_):
    try: self._v254_defaults_dirty = True
    except Exception: pass


def _v254_install_default_traces(self):
    if getattr(self, "_v254_default_traces_installed", False):
        return
    self._v254_default_traces_installed = True
    for name in _v254_get_default_snapshot(self).keys():
        try:
            var = getattr(self, name)
            var.trace_add("write", lambda *args, _self=self: _v254_mark_defaults_dirty(_self))
        except Exception:
            pass
    try: self._v254_defaults_dirty = False
    except Exception: pass


def _v254_apply_defaults_to_selected_plan(self):
    """Apply Set defaults changes to the existing selected plan rows.

    We do not destroy/recreate the Selected Plan table.  Instead we build a fresh default-derived
    plan with the current defaults, then copy default-controlled fields by row index.  Unit names
    and manually edited MW/Density values are kept, while eq/mmol/reagent/base/solvent fields are
    updated from the current setup defaults.
    """
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None or not tree.get_children():
        return
    try: _v251_ensure_selected_plan_columns(self)
    except Exception: pass
    cols = list(tree["columns"])
    try:
        fresh = _v248_plan_display_df(self) if "_v248_plan_display_df" in globals() else pd.DataFrame()
    except Exception:
        fresh = pd.DataFrame()
    if fresh is None or fresh.empty:
        return
    for c in cols:
        if c not in fresh.columns: fresh[c] = ""
    default_fields = [
        "Unit mmol", "Reagent 1", "R1 MW", "R1 Density", "R1 mmol", "R1 amount",
        "Reagent 2 / catalyst", "R2 MW", "R2 Density", "R2 mmol", "R2 amount",
        "Base", "Base MW", "Base Density", "Base mmol", "Base amount",
        "Coupling solvent", "Solvent mL", "Repeat", "Note",
    ]
    # Unit amount is recalculated after Unit mmol changes, so do not copy stale amount from a different Unit name.
    iids = list(tree.get_children())
    for pos, iid in enumerate(iids):
        if pos >= len(fresh): break
        vals = list(tree.item(iid, "values"))
        while len(vals) < len(cols): vals.append("")
        row = fresh.iloc[pos]
        for field in default_fields:
            if field in cols:
                vals[cols.index(field)] = _v251_s(row.get(field, ""))
        tree.item(iid, values=vals)
        try: _v251_recalc_visible_row(self, tree, iid)
        except Exception: pass
    try: self._v254_defaults_dirty = False
    except Exception: pass


def _v254_refresh_selected_checklist_from_plan(self):
    """Refresh Selected Checklist from the visible Selected Plan so Apply Plan is reflected."""
    txt = getattr(self, "pm_selected_check_text", None)
    tree = getattr(self, "pm_selected_plan_tree", None)
    if txt is None or tree is None:
        return
    try: _v251_ensure_selected_plan_columns(self)
    except Exception: pass
    cols = list(tree["columns"])
    def val(vals, c):
        return vals[cols.index(c)] if c in cols and cols.index(c) < len(vals) else ""
    lines = []
    try:
        lines.append(f"Project: {self.pm_project.get()} | Peptide: {self.pm_peptide.get()} | LOT: {self.pm_lot.get()}")
        lines.append(f"Sequence: {self.pm_sequence.get()} | Scale: {self.pm_scale.get()} mmol | Resin: {self.pm_resin.get()} | Loading: {self.pm_loading.get()} mmol/g")
        lines.append("")
    except Exception:
        pass
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values"))
        no = val(vals, "No")
        unit = val(vals, "Unit name")
        if not str(unit).strip(): continue
        r1 = val(vals, "Reagent 1")
        r2 = val(vals, "Reagent 2 / catalyst")
        base = val(vals, "Base")
        solvent = val(vals, "Coupling solvent")
        sml = val(vals, "Solvent mL")
        rep = val(vals, "Repeat")
        uamt = val(vals, "Unit amount")
        reagents = " / ".join([x for x in [r1, r2, base] if str(x).strip()]) or "No reagent/base"
        lines.append(f"□ Step {no}. Coupling: {unit}")
        lines.append(f"   - Unit amount: {uamt}")
        lines.append(f"   - Reagent/base: {reagents}")
        lines.append(f"   - Coupling solvent: {solvent} {sml} mL | Repeat: {rep}")
    if tree.get_children():
        lines.append("")
        lines.append("□ Final wash: DMF x3")
        lines.append("□ Final wash: DCM x3")
    try:
        txt.delete("1.0", "end")
        txt.insert("end", "\n".join(lines).strip() + "\n")
    except Exception:
        pass


def _v254_apply_plan(self):
    try:
        # Always install/clean toolbar first so duplicate older buttons disappear after any Apply.
        _v254_install_selected_plan_toolbar(self)
    except Exception:
        pass
    try:
        if getattr(self, "_v254_defaults_dirty", False):
            _v254_apply_defaults_to_selected_plan(self)
        else:
            tree = getattr(self, "pm_selected_plan_tree", None)
            if tree is not None:
                try: _v251_ensure_selected_plan_columns(self)
                except Exception: pass
                for iid in list(tree.get_children()):
                    try: _v251_recalc_visible_row(self, tree, iid)
                    except Exception: pass
        # Keep V2.0.52 solvent splitting/final DCM/DMF wash totals.
        _v252_apply_plan(self)
        _v254_refresh_selected_checklist_from_plan(self)
        try: self.save_autosave_state()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror("Apply Plan", str(e))
        except Exception: pass


def _v254_cell_editor(self, event):
    """Stable Selected Plan editor: immediate dropdown post, clean cancel, no row wipe."""
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None:
        return "break"
    try:
        if tree.identify("region", event.x, event.y) != "cell": return "break"
    except Exception:
        return "break"
    rowid = tree.identify_row(event.y); colid = tree.identify_column(event.x)
    if not rowid or not colid: return "break"
    try:
        idx = int(str(colid).replace("#", "")) - 1
        cols = list(tree["columns"])
    except Exception:
        return "break"
    if idx < 0 or idx >= len(cols): return "break"
    col = cols[idx]
    if col == "No": return "break"
    bbox = tree.bbox(rowid, colid)
    if not bbox: return "break"
    x, y, w, h = bbox
    vals = list(tree.item(rowid, "values"))
    while len(vals) < len(cols): vals.append("")
    old = str(vals[idx])
    try:
        ed = getattr(tree, "_v254_editor", None)
        if ed is not None and ed.winfo_exists(): ed.destroy()
    except Exception:
        pass
    dropdown_cols = {"Unit name", "Reagent 1", "Reagent 2 / catalyst", "Base", "Coupling solvent"}
    text_cols = {"MW", "Density(g/mL)", "Unit mmol", "Unit amount", "R1 MW", "R1 Density", "R1 mmol", "R1 amount",
                 "R2 MW", "R2 Density", "R2 mmol", "R2 amount", "Base MW", "Base Density", "Base mmol", "Base amount",
                 "Solvent mL", "Repeat", "Note"}
    if col in dropdown_cols:
        widget = ttk.Combobox(tree, values=_v251_options_for_col(self, col), state="normal")
        try: bind_combobox_first_letter_jump(widget)
        except Exception: pass
        widget.set(old); is_combo = True
    elif col in text_cols:
        widget = ttk.Entry(tree); widget.insert(0, old)
        try: widget.select_range(0, "end")
        except Exception: pass
        is_combo = False
    else:
        return "break"
    tree._v254_editor = widget
    widget.place(x=x, y=y, width=max(w, 280 if col == "Unit name" else 190), height=h + 4)
    widget.focus_set()
    done = {"v": False}
    def cleanup():
        try:
            if widget.winfo_exists(): widget.destroy()
        except Exception: pass
        try:
            if getattr(tree, "_v254_editor", None) is widget: tree._v254_editor = None
        except Exception: pass
    def commit(_event=None):
        if done["v"]: return "break"
        done["v"] = True
        try:
            new = widget.get()
            if col in dropdown_cols: new = _v251_canon(new)
            vals2 = list(tree.item(rowid, "values"))
            while len(vals2) < len(cols): vals2.append("")
            vals2[idx] = new
            tree.item(rowid, values=vals2)
            _v251_recalc_visible_row(self, tree, rowid, changed_col=(col if col in dropdown_cols else None))
            try: self._v254_defaults_dirty = False
            except Exception: pass
        finally:
            cleanup()
        return "break"
    def cancel(_event=None):
        if done["v"]: return "break"
        done["v"] = True
        cleanup()
        return "break"
    def focus_out(_event=None):
        def later():
            if done["v"]: return
            try: current = widget.get()
            except Exception: current = old
            # Dropdown opened and no selection/change: cancel and remove it. Text edits still commit.
            if is_combo and str(current) == old: cancel()
            else: commit()
        try: widget.after(120, later)
        except Exception: later()
        return None
    widget.bind("<Return>", commit, add="+")
    widget.bind("<Escape>", cancel, add="+")
    widget.bind("<FocusOut>", focus_out, add="+")
    if is_combo:
        widget.bind("<<ComboboxSelected>>", commit, add="+")
        # Open the dropdown list immediately after the editor is made.  If the user clicks away,
        # FocusOut above destroys it instead of leaving a combobox widget stuck on the tree.
        def post_combo():
            if done["v"]: return
            try:
                widget.focus_set()
                widget.tk.call("ttk::combobox::Post", widget)
            except Exception:
                try: widget.event_generate("<Alt-Down>")
                except Exception: pass
        try: widget.after(80, post_combo)
        except Exception: pass
    return "break"


def _v254_bind_selected_plan_editor(self):
    tree = getattr(self, "pm_selected_plan_tree", None)
    if tree is None: return
    try: tree.bind("<Double-1>", lambda e: _v254_cell_editor(self, e))
    except Exception: pass
    def close_stale(event):
        try:
            ed = getattr(tree, "_v254_editor", None)
            if ed is not None and ed.winfo_exists():
                # Normal click outside the active editor cancels it. Double-click will recreate it.
                if tree.identify("region", event.x, event.y) != "cell":
                    ed.destroy(); tree._v254_editor = None
        except Exception: pass
    try: tree.bind("<Button-1>", close_stale, add="+")
    except Exception: pass


def _v254_cleanup_selected_checklist_view(self):
    """Remove unnecessary View controls from the Selected Checklist panel only."""
    txt = getattr(self, "pm_selected_check_text", None)
    if txt is None:
        return
    # Search only around the selected checklist widget, not the main/global setup UI.
    root = txt.master
    removable_values = {"Balanced", "Progress full", "Sheet full"}
    def walk(w):
        for child in list(w.winfo_children()):
            try:
                if isinstance(child, ttk.Label) and str(child.cget("text")).strip() == "View":
                    child.destroy(); continue
            except Exception: pass
            try:
                if isinstance(child, ttk.Combobox):
                    vals = set(str(v) for v in child.cget("values"))
                    if vals and vals.issubset(removable_values):
                        child.destroy(); continue
            except Exception: pass
            try: walk(child)
            except Exception: pass
    try: walk(root)
    except Exception: pass


def _v254_generate(self):
    try:
        _v252_generate(self)
        try: self._v254_defaults_dirty = False
        except Exception: pass
    finally:
        try: _v254_install_selected_plan_toolbar(self)
        except Exception: pass
        try: _v254_bind_selected_plan_editor(self)
        except Exception: pass
        try: _v254_cleanup_selected_checklist_view(self)
        except Exception: pass
        try: _v254_refresh_selected_checklist_from_plan(self)
        except Exception: pass
        try: self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
        except Exception: pass


def _v254_build(self):
    if callable(_v253_build):
        _v253_build(self)
    try: _v254_install_default_traces(self)
    except Exception: pass
    try: _v254_install_selected_plan_toolbar(self)
    except Exception: pass
    try: _v254_bind_selected_plan_editor(self)
    except Exception: pass
    try: _v254_cleanup_selected_checklist_view(self)
    except Exception: pass
    try: self.title("SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
    except Exception: pass
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget("text")).startswith("SPPS Planner"):
                        c.configure(text="SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout")
                except Exception: pass
                try: walk(c)
                except Exception: pass
        walk(self)
    except Exception:
        pass


