def _v255_safe_sheet_name(name, used=None):
    used = used if used is not None else set()
    raw = str(name or 'Sheet').strip() or 'Sheet'
    safe = re.sub(r'[\\/*?:\[\]]+', '_', raw)
    safe = safe.replace("'", '')
    safe = re.sub(r'\s+', ' ', safe).strip() or 'Sheet'
    base = safe[:31]
    out = base
    n = 1
    while out in used:
        suffix = f'_{n}'
        out = (base[:31-len(suffix)] + suffix)[:31]
        n += 1
    used.add(out)
    return out


def _v255_export_batch_tables(self):
    try:
        outdir = Path((self.outdir.get() if hasattr(self, 'outdir') else 'spps_output') or 'spps_output') / 'batch_manager'
        outdir.mkdir(parents=True, exist_ok=True)
        if '_v203_calculate_batch_tables' in globals():
            tables = _v203_calculate_batch_tables(self)
        elif '_v29_calculate_batch_tables' in globals():
            tables = _v29_calculate_batch_tables(self)
        else:
            tables = {}
        xlsx = outdir / 'batch_synthesizer_calculator.xlsx'
        used = set()
        with pd.ExcelWriter(xlsx, engine='openpyxl') as writer:
            for name, df in tables.items():
                sheet = _v255_safe_sheet_name(name, used)
                (df if df is not None else pd.DataFrame()).to_excel(writer, index=False, sheet_name=sheet)
        messagebox.showinfo('Export complete', f'Batch calculator saved:\n{xlsx}')
    except Exception as e:
        try: messagebox.showerror('Export error', str(e))
        except Exception: pass

