# ======================= V2.0.58 STABLE_GENERATE_TABLE_SWITCH_FIX =======================
# User feedback target:
# 1) Generate/Update must always produce the same Selected Plan display table, not alternate
#    between legacy raw columns and MW/Density display columns.
# 2) DIC/HOBt and HBTU/NMP must use the same visible table shape.
# 3) Peptide item switching/double-click must be responsive and reliable.
# 4) Preserve V2.0.57 apply/delete/solvent/load-project fixes.

APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V258_STABLE_PLAN_COLS = list(_V251_DISPLAY_COLS) if '_V251_DISPLAY_COLS' in globals() else [
    "No","Unit name","MW","Density(g/mL)","Unit mmol","Unit amount",
    "Reagent 1","R1 MW","R1 Density","R1 mmol","R1 amount",
    "Reagent 2 / catalyst","R2 MW","R2 Density","R2 mmol","R2 amount",
    "Base","Base MW","Base Density","Base mmol","Base amount",
    "Coupling solvent","Solvent mL","Repeat","Note"
]


def _v258_write_stable_selected_plan(self, df=None):
    """Write one stable Selected Plan shape for every chemistry preset."""
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return pd.DataFrame(columns=_V258_STABLE_PLAN_COLS)
    if df is None:
        try:
            df = _v248_plan_display_df(self)
        except Exception:
            df = pd.DataFrame(columns=_V258_STABLE_PLAN_COLS)
    if df is None:
        df = pd.DataFrame(columns=_V258_STABLE_PLAN_COLS)
    # Normalize/rename legacy columns if any old callback still supplied them.
    try:
        synonyms = globals().get('_V251_SYNONYMS', {}) or {}
        df = df.copy()
        for old, new in list(synonyms.items()):
            if old in df.columns and new not in df.columns:
                df[new] = df[old]
    except Exception:
        pass
    for c in _V258_STABLE_PLAN_COLS:
        if c not in df.columns:
            df[c] = ''
    df = df[_V258_STABLE_PLAN_COLS].astype(str)
    try:
        _v251_write_tree(tree, df)
    except Exception:
        # fallback writer with fixed widths
        tree.configure(columns=_V258_STABLE_PLAN_COLS, show='headings')
        widths = {
            "No":50, "Unit name":280, "MW":90, "Density(g/mL)":125, "Unit mmol":110, "Unit amount":130,
            "Reagent 1":125, "R1 MW":90, "R1 Density":110, "R1 mmol":110, "R1 amount":125,
            "Reagent 2 / catalyst":175, "R2 MW":90, "R2 Density":110, "R2 mmol":110, "R2 amount":125,
            "Base":115, "Base MW":90, "Base Density":110, "Base mmol":110, "Base amount":125,
            "Coupling solvent":170, "Solvent mL":115, "Repeat":75, "Note":330,
        }
        for c in _V258_STABLE_PLAN_COLS:
            tree.heading(c, text=c)
            tree.column(c, width=widths.get(c, 130), minwidth=60, anchor='w', stretch=False)
        for iid in list(tree.get_children()):
            tree.delete(iid)
        for _, r in df.iterrows():
            tree.insert('', 'end', values=[str(r.get(c, '')) for c in _V258_STABLE_PLAN_COLS])
    try:
        _v251_ensure_selected_plan_columns(self)
    except Exception:
        pass
    try:
        if '_v254_bind_selected_plan_editor' in globals():
            _v254_bind_selected_plan_editor(self)
    except Exception:
        pass
    return df


def _v258_commit_editor_to_item_fast(self):
    try:
        if hasattr(self, 'pm_save_selected'):
            self.pm_save_selected()
    except Exception:
        pass
    try:
        idx = self.pm_current_index() if hasattr(self, 'pm_current_index') else None
        if idx is not None and hasattr(self, 'pm_items') and 0 <= idx < len(self.pm_items):
            self.pm_items[idx].update({
                'project': self.pm_project.get().strip(),
                'peptide': self.pm_peptide.get().strip(),
                'sequence': self.pm_sequence.get().strip(),
                'scale': self.pm_scale.get().strip(),
                'resin': self.pm_resin.get().strip(),
                'loading': self.pm_loading.get().strip(),
                'lot': self.pm_lot.get().strip(),
                'chemistry': self.pm_chemistry.get().strip(),
                'copies': self.pm_copies.get().strip(),
                'status': self.pm_items[idx].get('status', 'Ready'),
            })
    except Exception:
        pass


def _v258_generate_selected_stable(self):
    """Final Generate/Update callback: no legacy raw-tree copy, no alternating columns."""
    if getattr(self, '_v258_generate_running', False):
        return
    self._v258_generate_running = True
    try:
        try:
            _v257_init_solvent_basis(self)
        except Exception:
            pass
        _v258_commit_editor_to_item_fast(self)
        try:
            idx = self.pm_current_index() if hasattr(self, 'pm_current_index') else None
            if idx is not None and hasattr(self, 'pm_items') and 0 <= idx < len(self.pm_items):
                item = self.pm_items[idx]
                self.pm_apply_item_to_single_plan(item)
                item['status'] = 'Calculated'
        except Exception:
            pass
        _v258_write_stable_selected_plan(self)
        try:
            _v257_apply_volume_to_plan(self)
        except Exception:
            pass
        try:
            _v257_rebuild_materials_total(self)
        except Exception:
            try: _v248_refresh_from_visible(self)
            except Exception: pass
        try:
            _v257_refresh_checklist(self)
        except Exception:
            pass
        try:
            self.pm_refresh_list(keep_index=self.pm_current_index(), reload_editor=False)
        except TypeError:
            try: self.pm_refresh_list()
            except Exception: pass
        except Exception:
            pass
        try:
            self.pm_update_summary()
        except Exception:
            pass
        try:
            self.schedule_autosave()
        except Exception:
            pass
        try:
            _v258_rebind_buttons_and_list(self)
        except Exception:
            pass
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v258_generate_running = False


def _v258_apply_plan(self):
    """Apply keeps the same stable table shape and then rebuilds linked outputs."""
    if getattr(self, '_v258_apply_running', False):
        return
    self._v258_apply_running = True
    try:
        try: _v257_init_solvent_basis(self)
        except Exception: pass
        try: _v257_save_editor_and_defaults(self)
        except Exception: _v258_commit_editor_to_item_fast(self)
        # Apply should reflect current editor/default values, but with stable columns only.
        _v258_generate_selected_stable(self)
    finally:
        self._v258_apply_running = False


def _v258_use_dic_hobt(self):
    try:
        if '_v205_apply_dic_hobt_preset' in globals():
            _v205_apply_dic_hobt_preset(self)
        elif hasattr(SPPSGui, 'apply_dic_hobt_preset'):
            SPPSGui.apply_dic_hobt_preset(self)
    except Exception:
        try:
            self.default_reagent.set('DIC'); self.default_catalyst.set('HOBt'); self.default_base.set('')
            self.default_coupling_solution_solvent.set('DMF'); self.pm_chemistry.set('DIC/HOBt')
        except Exception: pass
    _v258_generate_selected_stable(self)


def _v258_use_hbtu_nmp(self):
    try:
        if '_v205_apply_hbtu_nmp_preset' in globals():
            _v205_apply_hbtu_nmp_preset(self)
        elif hasattr(SPPSGui, 'apply_hbtu_nmp_preset'):
            SPPSGui.apply_hbtu_nmp_preset(self)
    except Exception:
        try:
            self.default_reagent.set('HBTU'); self.default_catalyst.set('')
            self.default_base.set('DIPEA'); self.default_coupling_solution_solvent.set('NMP')
            self.pm_chemistry.set('HBTU/NMP 10eq')
        except Exception: pass
    _v258_generate_selected_stable(self)


def _v258_fast_load_item(self, idx, generate=True):
    try:
        if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
            return 'break'
        try:
            self.pm_load_to_editor(idx)
        except Exception:
            pass
        if generate:
            _v258_generate_selected_stable(self)
        return 'break'
    except Exception as e:
        try: messagebox.showerror('Project Manager', f'Failed to open selected peptide:\n{e}')
        except Exception: pass
        return 'break'


def _v258_pm_on_select_fast(self, event=None):
    # Avoid heavy repeated generation while Listbox selection events are firing.
    try:
        idx = self.pm_current_index() if hasattr(self, 'pm_current_index') else None
        if idx is None:
            return 'break'
        try:
            self.pm_load_to_editor(idx)
        except Exception:
            pass
        # Debounce one stable generation for normal click selection.
        try:
            old = getattr(self, '_v258_select_after_id', None)
            if old:
                self.after_cancel(old)
        except Exception:
            pass
        try:
            self._v258_select_after_id = self.after(180, lambda _idx=idx: _v258_fast_load_item(self, _idx, generate=True))
        except Exception:
            pass
        return 'break'
    except Exception:
        return 'break'


def _v258_pm_double_click(self, event=None):
    try:
        lb = getattr(self, 'pm_list', None)
        if lb is None:
            return 'break'
        idx = lb.nearest(event.y) if event is not None else self.pm_current_index()
        try:
            lb.selection_clear(0, 'end')
            lb.selection_set(idx)
            lb.activate(idx)
        except Exception:
            pass
        try:
            old = getattr(self, '_v258_select_after_id', None)
            if old:
                self.after_cancel(old)
                self._v258_select_after_id = None
        except Exception:
            pass
        return _v258_fast_load_item(self, idx, generate=True)
    except Exception:
        return 'break'


def _v258_rebind_buttons_and_list(self):
    """Route existing already-created buttons to final callbacks, including Generate/Update."""
    def walk(w):
        try: children = list(w.winfo_children())
        except Exception: children = []
        for c in children:
            try:
                if isinstance(c, ttk.Button):
                    t = str(c.cget('text')).strip()
                    if t == 'Generate / Update':
                        c.configure(command=lambda _self=self: _v258_generate_selected_stable(_self))
                    elif t == 'Apply Plan':
                        c.configure(command=lambda _self=self: _v258_apply_plan(_self))
                    elif t == 'Delete selected row':
                        c.configure(command=lambda _self=self: _v257_delete_selected_rows(_self))
                    elif t == 'Use DIC/HOBt':
                        c.configure(command=lambda _self=self: _v258_use_dic_hobt(_self))
                    elif t == 'Use HBTU/NMP 10eq':
                        c.configure(command=lambda _self=self: _v258_use_hbtu_nmp(_self))
                    elif t == 'Load Project':
                        c.configure(command=lambda _self=self: _v257_load_project(_self))
                    elif t == 'Export batch tables':
                        c.configure(command=lambda _self=self: _v255_export_batch_tables(_self))
            except Exception:
                pass
            walk(c)
    try: walk(self)
    except Exception: pass
    try:
        lb = getattr(self, 'pm_list', None)
        if lb is not None:
            lb.bind('<<ListboxSelect>>', lambda e, _self=self: _v258_pm_on_select_fast(_self, e))
            lb.bind('<Double-Button-1>', lambda e, _self=self: _v258_pm_double_click(_self, e))
            lb.bind('<Return>', lambda e, _self=self: _v258_fast_load_item(_self, _self.pm_current_index(), generate=True))
    except Exception:
        pass


def _v258_after_build(self):
    try: _v257_after_build(self)
    except Exception: pass
    try: _v258_rebind_buttons_and_list(self)
    except Exception: pass
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass


try:
    _v258_previous_build = SPPSGui._build
    def _v258_build(self):
        _v258_previous_build(self)
        _v258_after_build(self)
        try: self.after(350, lambda: _v258_after_build(self))
        except Exception: pass
    SPPSGui._build = _v258_build
except Exception:
    pass

# Final class routing.  Already-created buttons are also re-bound in _v258_rebind_buttons_and_list().
SPPSGui.pm_generate_selected = _v258_generate_selected_stable
SPPSGui.pm_calculate_all = _v258_generate_selected_stable
