# ======================= V2.0.60 PROTOCOL_BATCH_SMOOTH_FIX =======================
# User feedback target:
# 1) Apply Plan must keep the current Selected Plan as source, but Selected Materials,
#    Selected Total Materials, and Selected Checklist must still contain the full SPPS
#    protocol items: deprotection, DMF depro/wash, post-coupling wash, final DMF/DCM wash.
# 2) Batch Manager numeric/default Entry editing must replace the selected value instead
#    of prefixing new text in front of the old value.
# 3) Keep the already-satisfactory V2.0.59 functions and make redraws smoother.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v260_float(x, default=0.0):
    try:
        return float(str(x).replace(',', '').replace('mL','').replace('ml','').replace('g','').strip())
    except Exception:
        return default


def _v260_str(x):
    try:
        return _v251_s(x) if '_v251_s' in globals() else ("%g" % float(x))
    except Exception:
        return str(x)


def _v260_lookup(self, name):
    try:
        return _v251_lookup(self, name)
    except Exception:
        try:
            return _v248_lookup(self, name)
        except Exception:
            return ('', '')


def _v260_tree_rows(tree):
    cols = list(tree['columns'])
    out = []
    for iid in list(tree.get_children()):
        vals = list(tree.item(iid, 'values'))
        vals += [''] * max(0, len(cols) - len(vals))
        out.append(dict(zip(cols, vals)))
    return out


def _v260_is_ctc_resin(self):
    try:
        r = str(getattr(self, 'pm_resin', getattr(self, 'resin', _v225_const_var(''))).get()).lower()
    except Exception:
        r = ''
    return ('ctc' in r) or ('trityl' in r)


def _v260_is_nonfmoc_terminal(unit):
    u = str(unit or '').strip().upper()
    if not u:
        return False
    if u.startswith('FMOC-'):
        return False
    terminal_markers = ['ACETIC ANHYDRIDE', 'AC2O', 'AC-', 'FITC', 'FAM', 'TAMRA', 'BIOTIN', 'CY3', 'CY5', 'CY5.5', 'CY7', 'PAL', 'MYR', 'GAL', 'CAFFEIC', 'N-TERM', 'LABEL', 'TAG']
    return any(m in u for m in terminal_markers)


def _v260_visible_plan_protocol_materials(self):
    """Build detailed material rows from the current visible Selected Plan plus SPPS protocol steps."""
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return pd.DataFrame(columns=['material','class','MW','Density(g/mL)','total mmol','total amount','note','_mmol','_g','_mL'])
    try: _v251_ensure_selected_plan_columns(self)
    except Exception: pass
    rows_in = _v260_tree_rows(tree)
    mats = []
    working_ml = 0.0
    try:
        working_ml = _v257_working_ml(self) if '_v257_working_ml' in globals() else 0.0
    except Exception:
        working_ml = 0.0
    if not working_ml:
        try: working_ml = _v255_working_ml(self)
        except Exception: working_ml = 0.0
    if not working_ml:
        try:
            scale = _v260_float(getattr(self, 'pm_scale', _v225_const_var('0.2')).get(), 0.2)
            working_ml = scale * (5.0 if _v260_is_ctc_resin(self) else 10.0)
        except Exception:
            working_ml = 2.0

    depro_base = 'Piperidine'
    depro_ratio = '20% in DMF'
    depro_count = 2
    try: depro_base = str(self.default_depro.get() or depro_base)
    except Exception: pass
    try: depro_ratio = str(self.default_depro_ratio.get() or depro_ratio)
    except Exception: pass
    try: depro_count = int(float(str(self.default_depro_count.get())))
    except Exception: depro_count = 2
    dmfwash_after_depro = 6
    post_wash_count = 2
    final_wash_count = 3
    try:
        post_wash_count = int(float(str(getattr(self, 'default_solvent1_count', _v225_const_var('2')).get())))
    except Exception:
        post_wash_count = 2

    terminal_steps = {i for i, r in enumerate(rows_in) if _v260_is_nonfmoc_terminal(r.get('Unit name',''))}
    last_idx = len(rows_in) - 1
    last_fmoc_idx = None
    for i, r in enumerate(rows_in):
        if not _v260_is_nonfmoc_terminal(r.get('Unit name','')):
            last_fmoc_idx = i

    def add(material, cls, mw='', den='', mmol='', amount='', note='', forced_ml=None, forced_g=None):
        try:
            if (not mw) or (not den):
                lm, ld = _v260_lookup(self, material)
                mw = mw or lm
                den = den or ld
        except Exception:
            pass
        _v252_add_material_row(mats, material, cls, mw, den, mmol, amount, note, forced_ml=forced_ml, forced_g=forced_g)

    def add_split_solvent(solvent_name, total_ml, cls, note):
        try:
            split = _v252_split_solvent(solvent_name, total_ml)
        except Exception:
            split = [(solvent_name, total_ml, '')]
        for mat, ml, split_note in split:
            add(mat, cls, '', '', '', f'{_v260_str(ml)} mL', (note + ('; ' + split_note if split_note else '')).strip('; '), forced_ml=ml)

    def add_depro_block(step_no, unit, phase_note):
        if depro_count <= 0:
            return
        # 20% piperidine / 80% DMF deprotection solution, then DMF wash x6.
        total_solution_ml = working_ml * depro_count
        piperidine_ml = total_solution_ml * 0.20 if '20' in depro_ratio else total_solution_ml
        dmf_solution_ml = total_solution_ml * 0.80 if '20' in depro_ratio else 0
        add(depro_base, 'Deprotection base', '', '', '', f'{_v260_str(piperidine_ml)} mL', f'SPPS protocol step {step_no}: {phase_note}; {depro_base} {depro_ratio} x{depro_count}', forced_ml=piperidine_ml)
        if dmf_solution_ml:
            add('DMF', 'Deprotection solvent', '', '', '', f'{_v260_str(dmf_solution_ml)} mL', f'SPPS protocol step {step_no}: DMF component of {depro_ratio}', forced_ml=dmf_solution_ml)
        add('DMF', 'Deprotection wash solvent', '', '', '', f'{_v260_str(working_ml * dmfwash_after_depro)} mL', f'SPPS protocol step {step_no}: DMF wash x6 after deprotection before {unit}', forced_ml=working_ml * dmfwash_after_depro)

    for idx, r in enumerate(rows_in):
        step = r.get('No') or str(idx + 1)
        unit = r.get('Unit name','')
        if not str(unit).strip():
            continue
        is_terminal = idx in terminal_steps
        # Pre-coupling Fmoc deprotection: skip only first CTC/trityl loading row.
        if not (idx == 0 and _v260_is_ctc_resin(self)):
            add_depro_block(step, unit, 'pre-coupling Fmoc deprotection')

        add(unit, 'AA/Chemical', r.get('MW',''), r.get('Density(g/mL)',''), r.get('Unit mmol',''), r.get('Unit amount',''), 'Visible Selected Plan unit')
        add(r.get('Reagent 1',''), 'Coupling reagent', r.get('R1 MW',''), r.get('R1 Density',''), r.get('R1 mmol',''), r.get('R1 amount',''), 'Visible Selected Plan coupling reagent')
        add(r.get('Reagent 2 / catalyst',''), 'Catalyst/additive', r.get('R2 MW',''), r.get('R2 Density',''), r.get('R2 mmol',''), r.get('R2 amount',''), 'Visible Selected Plan catalyst/additive')
        add(r.get('Base',''), 'Base', r.get('Base MW',''), r.get('Base Density',''), r.get('Base mmol',''), r.get('Base amount',''), 'Visible Selected Plan base')
        solvent = r.get('Coupling solvent','')
        smL = _v260_float(r.get('Solvent mL',''), 0.0)
        if solvent and smL:
            add_split_solvent(solvent, smL, 'Coupling solvent', f'SPPS protocol step {step}: coupling cocktail solvent')

        # Post-coupling transition wash is skipped for terminal non-Fmoc rows and for the final Fmoc row if no terminal modifier follows.
        has_terminal_after = any(j > idx for j in terminal_steps)
        skip_post = is_terminal or (idx == last_fmoc_idx and not has_terminal_after)
        if not skip_post and post_wash_count > 0:
            add('DMF', 'Post-coupling wash solvent', '', '', '', f'{_v260_str(working_ml * post_wash_count)} mL', f'SPPS protocol step {step}: DMF wash x{post_wash_count} after coupling', forced_ml=working_ml * post_wash_count)

        # Final Fmoc removal when the last Fmoc-AA is the terminal synthesis unit.
        if idx == last_fmoc_idx and not has_terminal_after and not is_terminal:
            add_depro_block(step, unit, 'final Fmoc deprotection after last Fmoc-AA coupling')
            add('DMF', 'Final wash solvent', '', '', '', f'{_v260_str(working_ml * final_wash_count)} mL', 'SPPS protocol final wash: DMF x3', forced_ml=working_ml * final_wash_count)
            add('DCM', 'Final wash solvent', '', '', '', f'{_v260_str(working_ml * final_wash_count)} mL', 'SPPS protocol final wash: DCM x3', forced_ml=working_ml * final_wash_count)
        elif is_terminal:
            add('DMF', 'Final wash solvent', '', '', '', f'{_v260_str(working_ml * final_wash_count)} mL', 'SPPS protocol last wash after terminal chemical/label/cap: DMF x3', forced_ml=working_ml * final_wash_count)
            add('DCM', 'Final wash solvent', '', '', '', f'{_v260_str(working_ml * final_wash_count)} mL', 'SPPS protocol last wash after terminal chemical/label/cap: DCM x3', forced_ml=working_ml * final_wash_count)

    return pd.DataFrame(mats)


def _v260_refresh_materials_total_protocol(self):
    mats = _v260_visible_plan_protocol_materials(self)
    show_cols = ['material','class','MW','Density(g/mL)','total mmol','total amount','note']
    try:
        if hasattr(self, 'pm_selected_material_tree'):
            _v251_write_tree(self.pm_selected_material_tree, mats[show_cols] if mats is not None and not mats.empty else pd.DataFrame(columns=show_cols))
    except Exception:
        pass
    try:
        if '_v228_ensure_total_tab' in globals(): _v228_ensure_total_tab(self)
    except Exception:
        pass
    try:
        if hasattr(self, 'pm_selected_total_tree'):
            _v251_write_tree(self.pm_selected_total_tree, _v252_total_from_materials(mats))
    except Exception:
        pass
    return mats


def _v260_refresh_checklist_protocol(self):
    tree = getattr(self, 'pm_selected_plan_tree', None)
    prog = getattr(self, 'progress_tree', None)
    if tree is None or prog is None:
        try:
            if '_v257_refresh_checklist' in globals(): _v257_refresh_checklist(self)
        except Exception: pass
        return
    rows_in = _v260_tree_rows(tree)
    working_ml = 0.0
    try: working_ml = _v257_working_ml(self)
    except Exception: pass
    if not working_ml:
        try:
            scale = _v260_float(getattr(self, 'pm_scale', _v225_const_var('0.2')).get(), 0.2)
            working_ml = scale * (5.0 if _v260_is_ctc_resin(self) else 10.0)
        except Exception:
            working_ml = 2.0
    try: depro_count = int(float(str(self.default_depro_count.get())))
    except Exception: depro_count = 2
    try: depro = str(self.default_depro.get() or 'Piperidine')
    except Exception: depro = 'Piperidine'
    try: ratio = str(self.default_depro_ratio.get() or '20% in DMF')
    except Exception: ratio = '20% in DMF'
    try: post_wash_count = int(float(str(getattr(self, 'default_solvent1_count', _v225_const_var('2')).get())))
    except Exception: post_wash_count = 2
    terminal_steps = {i for i, r in enumerate(rows_in) if _v260_is_nonfmoc_terminal(r.get('Unit name',''))}
    last_fmoc_idx = None
    for i, r in enumerate(rows_in):
        if not _v260_is_nonfmoc_terminal(r.get('Unit name','')):
            last_fmoc_idx = i
    checklist = []
    line = 1
    def row(op, unit, next_step='', note=''):
        nonlocal line
        checklist.append([line, 'No', '', op, unit, next_step, note])
        line += 1
    row('Resin swell', getattr(self, 'pm_resin', _v225_const_var('Resin')).get(), 'First deprotection/loading', 'SPPS protocol start')
    for idx, r in enumerate(rows_in):
        step = r.get('No') or str(idx+1)
        unit = r.get('Unit name','')
        if not str(unit).strip():
            continue
        is_terminal = idx in terminal_steps
        has_terminal_after = any(j > idx for j in terminal_steps)
        if not (idx == 0 and _v260_is_ctc_resin(self)):
            for i in range(max(depro_count,0)):
                row('Deprotection', unit, f'DMF wash after deprotection / {unit}', f'{depro} ({ratio}) #{i+1}')
            for i in range(6):
                row('DMF wash after deprotection', unit, f'Coupling / {unit}', f'DMF wash x6 before coupling; working mL={_v260_str(working_ml)}')
        r1 = r.get('Reagent 1',''); r2 = r.get('Reagent 2 / catalyst',''); base = r.get('Base',''); solv = r.get('Coupling solvent',''); sml = r.get('Solvent mL','')
        op = 'Final chemical / label / modifier coupling' if is_terminal else ('Last coupling step' if idx == last_fmoc_idx else 'Coupling reaction')
        row(op, unit, 'Post-coupling wash or final wash', f'{unit} + {r1} + {r2} + {base} in {solv} ({sml} mL)')
        skip_post = is_terminal or (idx == last_fmoc_idx and not has_terminal_after)
        if not skip_post and post_wash_count > 0:
            row('Post-coupling wash', unit, 'Next cycle', f'DMF wash x{post_wash_count} after coupling')
        if idx == last_fmoc_idx and not has_terminal_after and not is_terminal:
            for i in range(max(depro_count,0)):
                row('Final deprotection', unit, 'Final wash', f'{depro} ({ratio}) #{i+1}')
            row('Final wash', unit, 'Final wash / DCM', 'DMF x3')
            row('Final wash', unit, 'Complete', 'DCM x3')
        elif is_terminal:
            row('Final wash', unit, 'Final wash / DCM', 'DMF x3 after terminal chemical/label/cap')
            row('Final wash', unit, 'Complete', 'DCM x3 after terminal chemical/label/cap')
    try:
        prog.delete(*prog.get_children())
        for r in checklist:
            prog.insert('', 'end', values=r)
        try: self._update_progress_widgets()
        except Exception: pass
        try: self._write_df(self.next_text, self.next_step_df())
        except Exception: pass
    except Exception:
        pass


def _v260_refresh_linked_outputs_from_visible_plan(self):
    if getattr(self, '_v260_refreshing_visible', False):
        return
    self._v260_refreshing_visible = True
    try:
        try: _v259_commit_open_selected_plan_editor(self)
        except Exception: pass
        try: _v251_ensure_selected_plan_columns(self)
        except Exception: pass
        tree = getattr(self, 'pm_selected_plan_tree', None)
        if tree is not None:
            for iid in list(tree.get_children()):
                try: _v251_recalc_visible_row(self, tree, iid)
                except Exception: pass
        try: _v257_apply_volume_to_plan(self)
        except Exception: pass
        _v260_refresh_materials_total_protocol(self)
        _v260_refresh_checklist_protocol(self)
        try:
            if hasattr(self, '_v260_schedule_batch_refresh'):
                self._v260_schedule_batch_refresh()
            elif hasattr(self, 'refresh_batch_workspace_preview'):
                self.after_idle(self.refresh_batch_workspace_preview)
        except Exception: pass
        try: _v254_bind_selected_plan_editor(self)
        except Exception: pass
    finally:
        self._v260_refreshing_visible = False


def _v260_apply_plan(self):
    if getattr(self, '_v260_apply_running', False):
        return
    self._v260_apply_running = True
    try:
        _v260_refresh_linked_outputs_from_visible_plan(self)
        try: _v260_rebind_buttons(self)
        except Exception: pass
        try: self.save_autosave_state()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Apply Plan', str(e))
        except Exception: pass
    finally:
        self._v260_apply_running = False


def _v260_delete_selected_rows(self):
    try:
        tree = getattr(self, 'pm_selected_plan_tree', None)
        if tree is None: return
        sel = list(tree.selection())
        if not sel: return
        for iid in sel:
            try: tree.delete(iid)
            except Exception: pass
        try:
            cols = list(tree['columns'])
            if 'No' in cols:
                ni = cols.index('No')
                for n, iid in enumerate(tree.get_children(), 1):
                    vals = list(tree.item(iid, 'values')); vals += [''] * max(0, len(cols)-len(vals))
                    vals[ni] = str(n); tree.item(iid, values=vals)
        except Exception: pass
        _v260_refresh_linked_outputs_from_visible_plan(self)
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass


def _v260_patch_editable_tree():
    def _begin_edit_replace(self, event):
        if self.identify('region', event.x, event.y) != 'cell':
            return
        row_id = self.identify_row(event.y); col_id = self.identify_column(event.x)
        if not row_id or not col_id: return
        try: col_index = int(col_id.replace('#','')) - 1
        except Exception: return
        cols = list(self['columns'])
        if col_index < 0 or col_index >= len(cols): return
        col_name = cols[col_index]
        if col_name in {'No'}: return
        bbox = self.bbox(row_id, col_id)
        if not bbox: return
        x,y,w,h = bbox
        vals = list(self.item(row_id,'values')); vals += [''] * max(0, len(cols)-len(vals))
        old = vals[col_index]
        try:
            if getattr(self, '_edit_entry', None) is not None:
                self._edit_entry.destroy()
        except Exception: pass
        choices = getattr(self, '_combo_values', {}).get(col_name)
        if choices:
            e = ttk.Combobox(self, values=choices, state='normal')
            try: bind_combobox_first_letter_jump(e)
            except Exception: pass
            e.set(str(old))
        else:
            e = ttk.Entry(self)
            e.insert(0, str(old))
        e.place(x=x, y=y, width=w, height=h+2)
        e.focus_set()
        try: e.select_range(0, 'end'); e.icursor('end')
        except Exception: pass
        self._edit_entry = e
        replace_next = {'v': True}
        done = {'v': False}
        def first_key(ev):
            if not replace_next['v']:
                return None
            replace_next['v'] = False
            try:
                if ev.keysym in ('BackSpace','Delete'):
                    e.delete(0, 'end')
                    return 'break'
                if len(ev.char) == 1 and ev.char.isprintable():
                    e.delete(0, 'end')
            except Exception: pass
            return None
        def commit(_event=None):
            if done['v']: return 'break'
            done['v'] = True
            try:
                new = e.get()
                cur = list(self.item(row_id,'values')); cur += [''] * max(0, len(cols)-len(cur))
                cur[col_index] = new
                self.item(row_id, values=cur)
                if getattr(self, '_on_edit', None):
                    self._on_edit(row_id, col_name, new)
            finally:
                try: e.destroy()
                except Exception: pass
                self._edit_entry = None
            return 'break'
        def cancel(_event=None):
            try: e.destroy()
            except Exception: pass
            self._edit_entry = None
            return 'break'
        e.bind('<KeyPress>', first_key, add='+')
        e.bind('<Return>', commit)
        e.bind('<FocusOut>', commit)
        e.bind('<Escape>', cancel)
        e.bind('<Control-a>', lambda ev: (e.select_range(0,'end'), 'break'))
        if choices:
            try: e.after(10, e.event_generate, '<Button-1>')
            except Exception: pass
            e.bind('<<ComboboxSelected>>', commit, add='+')
        return 'break'
    try:
        EditableTree._begin_edit = _begin_edit_replace
    except Exception:
        pass


def _v260_bind_batch_default_entries(self):
    names = {'batch_solution_conc','batch_coupling_eq','batch_actual_round_ml','batch_actual_extra_ml','batch_hbtu_eq','batch_hbtu_conc'}
    tvs = set()
    for n in names:
        try: tvs.add(str(getattr(self, n)))
        except Exception: pass
    def walk(w):
        try: children = list(w.winfo_children())
        except Exception: children = []
        for c in children:
            try:
                if isinstance(c, ttk.Entry) and str(c.cget('textvariable')) in tvs:
                    if not getattr(c, '_v260_replace_bind', False):
                        c._v260_replace_bind = True
                        state = {'replace': False}
                        def mark(ev, _c=c, _s=state):
                            _s['replace'] = True
                            try: _c.after_idle(lambda: (_c.focus_set(), _c.select_range(0,'end'), _c.icursor('end')))
                            except Exception: pass
                            return None
                        def key(ev, _c=c, _s=state):
                            if not _s.get('replace'):
                                return None
                            _s['replace'] = False
                            try:
                                if ev.keysym in ('BackSpace','Delete'):
                                    _c.delete(0, 'end')
                                    return 'break'
                                if len(ev.char) == 1 and ev.char.isprintable():
                                    _c.delete(0, 'end')
                            except Exception: pass
                            return None
                        c.bind('<Double-Button-1>', mark, add='+')
                        c.bind('<Control-a>', lambda ev, _c=c: (_c.select_range(0,'end'), 'break'), add='+')
                        c.bind('<KeyPress>', key, add='+')
            except Exception: pass
            walk(c)
    try: walk(self)
    except Exception: pass


def _v260_install_smooth_batch_refresh(self):
    if getattr(self, '_v260_batch_smooth_installed', False):
        return
    self._v260_batch_smooth_installed = True
    old = getattr(self, 'refresh_batch_workspace_preview', None)
    if not callable(old):
        return
    self._v260_old_refresh_batch_workspace_preview = old
    def schedule():
        try:
            pending = getattr(self, '_v260_batch_after_id', None)
            if pending:
                self.after_cancel(pending)
        except Exception: pass
        def run():
            try: self._v260_batch_after_id = None
            except Exception: pass
            try: self._v260_old_refresh_batch_workspace_preview()
            except Exception: pass
        try: self._v260_batch_after_id = self.after(90, run)
        except Exception:
            try: old()
            except Exception: pass
    self._v260_schedule_batch_refresh = schedule
    def debounced_refresh(*args, **kwargs):
        schedule()
    self.refresh_batch_workspace_preview = debounced_refresh


def _v260_rebind_buttons(self):
    def walk(w):
        try: children = list(w.winfo_children())
        except Exception: children = []
        for c in children:
            try:
                if isinstance(c, ttk.Button):
                    t = str(c.cget('text')).strip()
                    if t == 'Apply Plan':
                        c.configure(command=lambda _self=self: _v260_apply_plan(_self))
                    elif t == 'Delete selected row':
                        c.configure(command=lambda _self=self: _v260_delete_selected_rows(_self))
                    elif t == 'Generate / Update':
                        c.configure(command=lambda _self=self: _v259_generate_selected_stable(_self))
            except Exception: pass
            walk(c)
    try: walk(self)
    except Exception: pass
    try: _v260_bind_batch_default_entries(self)
    except Exception: pass


