# ======================= V2.0.61 APPLY_EDITOR_DEFAULTS_LOADING_FINAL_FIX =======================
# User feedback target:
# - Apply Plan must keep the manually edited Selected Plan unit list, but it must also reflect
#   selected peptide editor fields (scale, resin, resin loading, chemistry/copies) and setup defaults.
# - Resin loading mmol/g must be used in material totals (required resin g = scale / loading).
# - Do not remove the working V2.0.60 visible-plan behavior; repair only the missing connections.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v261_f(x, default=0.0):
    try:
        if x is None: return default
        s = str(x).replace(',', '').replace('mL','').replace('ml','').replace('g','').strip()
        if s == '': return default
        return float(s)
    except Exception:
        return default


def _v261_s(x):
    try:
        f = float(x)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return (f"{f:.6f}".rstrip('0').rstrip('.'))
    except Exception:
        return '' if x is None else str(x)


def _v261_var(self, name, default=''):
    try:
        v = getattr(self, name)
        return v.get() if hasattr(v, 'get') else v
    except Exception:
        return default


def _v261_save_editor_light(self):
    """Save editor values to the active PM item without regenerating the Selected Plan."""
    try:
        if hasattr(self, 'pm_save_selected'):
            self.pm_save_selected()
    except Exception:
        pass
    try:
        idx = self.pm_current_index() if hasattr(self, 'pm_current_index') else None
        if idx is not None and hasattr(self, 'pm_items') and 0 <= idx < len(self.pm_items):
            self.pm_items[idx].update({
                'project': _v261_var(self, 'pm_project', ''),
                'peptide': _v261_var(self, 'pm_peptide', ''),
                'sequence': _v261_var(self, 'pm_sequence', ''),
                'scale': str(_v261_var(self, 'pm_scale', '0.2')),
                'resin': str(_v261_var(self, 'pm_resin', 'Rink Amide AM')),
                'loading': str(_v261_var(self, 'pm_loading', '0.8')),
                'lot': str(_v261_var(self, 'pm_lot', '')),
                'chemistry': str(_v261_var(self, 'pm_chemistry', 'DIC/HOBt')),
                'copies': str(_v261_var(self, 'pm_copies', '1')),
            })
    except Exception:
        pass
    try:
        # Keep legacy single-plan variables in sync for old helper functions that still read them.
        if hasattr(self, 'scale'): self.scale.set(_v261_f(_v261_var(self, 'pm_scale', '0.2'), 0.2))
        if hasattr(self, 'resin'): self.resin.set(str(_v261_var(self, 'pm_resin', 'Rink Amide AM')))
        if hasattr(self, 'loading'): self.loading.set(_v261_f(_v261_var(self, 'pm_loading', '0.8'), 0.8))
        if hasattr(self, 'seq'): self.seq.set(str(_v261_var(self, 'pm_sequence', '')))
    except Exception:
        pass
    try:
        _v257_sync_ml_per_mmol(self)
    except Exception:
        pass


def _v261_lookup(self, name):
    try:
        return _v251_lookup(self, name)
    except Exception:
        try: return _v260_lookup(self, name)
        except Exception: return ('','')


def _v261_is_terminal_unit(unit):
    s = str(unit or '').lower()
    if not s.strip(): return False
    if s.startswith('fmoc-'): return False
    # Ac cap, N-term chemicals, labels/tags/linkers should use modifier defaults.
    return any(k in s for k in ['acetic anhydride','ac2o','palmitic','myristic','nicotinic','caffeic','gallic','biotin','fitc','fam','tamra','cy','alexa','his','flag','ha','myc','strep','tag','peg','ahx'])


def _v261_amount(name, mmol, mw, density=''):
    mwf = _v261_f(mw, 0)
    denf = _v261_f(density, 0)
    if not mmol or not mwf:
        return ''
    g = mmol * mwf / 1000.0
    nm = str(name or '').lower()
    liquid_hint = any(k in nm for k in ['dic','diea','dipea','tea','nmm','pyridine','acetic anhydride','ac2o','dmf','dcm','nmp','tfa','tis','water','acn','meoh','dmso'])
    if denf and liquid_hint:
        return f"{_v261_s(g/denf)} mL"
    return f"{_v261_s(g)} g"


def _v261_get_cols_vals(tree, iid):
    cols = list(tree['columns'])
    vals = list(tree.item(iid, 'values'))
    vals += [''] * max(0, len(cols)-len(vals))
    return cols, vals


def _v261_get(vals, cols, c, default=''):
    try:
        return vals[cols.index(c)] if c in cols else default
    except Exception:
        return default


def _v261_set(vals, cols, c, v):
    try:
        if c in cols: vals[cols.index(c)] = _v261_s(v)
    except Exception:
        pass


def _v261_recalc_visible_plan_from_editor_defaults(self):
    """Recalculate existing visible rows from current editor/defaults without rebuilding unit names."""
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return
    try: _v251_ensure_selected_plan_columns(self)
    except Exception: pass
    try: _v259_commit_open_selected_plan_editor(self)
    except Exception: pass
    scale = _v261_f(_v261_var(self, 'pm_scale', '0.2'), 0.2)
    copies = max(1, int(round(_v261_f(_v261_var(self, 'pm_copies', '1'), 1))))
    aa_eq = _v261_f(_v261_var(self, 'coupling_eq', '5'), 5)
    mod_eq = _v261_f(_v261_var(self, 'modifier_eq', '3'), 3)
    aa_rep = max(1, int(round(_v261_f(_v261_var(self, 'coupling_repeats', '1'), 1))))
    mod_rep = max(1, int(round(_v261_f(_v261_var(self, 'modifier_repeats', '1'), 1))))
    r1 = str(_v261_var(self, 'default_reagent', 'DIC') or '').strip()
    r1_eq = _v261_f(_v261_var(self, 'default_reagent_eq', aa_eq), aa_eq)
    r1_count = max(0, int(round(_v261_f(_v261_var(self, 'default_reagent_count', '1'), 1))))
    r2 = str(_v261_var(self, 'default_catalyst', 'HOBt') or '').strip()
    r2_eq = _v261_f(_v261_var(self, 'default_catalyst_eq', aa_eq), aa_eq)
    r2_count = max(0, int(round(_v261_f(_v261_var(self, 'default_catalyst_count', '1'), 1))))
    base = str(_v261_var(self, 'default_base', '') or '').strip()
    base_eq = _v261_f(_v261_var(self, 'default_base_eq', '0'), 0)
    base_count = max(0, int(round(_v261_f(_v261_var(self, 'default_base_count', '0'), 0))))
    solvent = str(_v261_var(self, 'default_coupling_solution_solvent', 'DMF') or 'DMF').strip()

    for n, iid in enumerate(list(tree.get_children()), 1):
        cols, vals = _v261_get_cols_vals(tree, iid)
        unit = str(_v261_get(vals, cols, 'Unit name', '')).strip()
        terminal = _v261_is_terminal_unit(unit)
        eq = mod_eq if terminal else aa_eq
        rep = mod_rep if terminal else aa_rep
        unit_mmol = scale * copies * eq * rep
        umw, uden = _v261_lookup(self, unit)
        if not umw: umw = _v261_get(vals, cols, 'MW', '')
        if not uden: uden = _v261_get(vals, cols, 'Density(g/mL)', '')
        _v261_set(vals, cols, 'No', n)
        _v261_set(vals, cols, 'MW', umw)
        _v261_set(vals, cols, 'Density(g/mL)', uden)
        _v261_set(vals, cols, 'Unit mmol', unit_mmol)
        _v261_set(vals, cols, 'Unit amount', _v261_amount(unit, unit_mmol, umw, uden))
        # Apply setup defaults to coupling rows; terminal cap/label rows do not use regular DIC/HOBt unless user set them manually.
        if terminal:
            _v261_set(vals, cols, 'Reagent 1', '')
            _v261_set(vals, cols, 'R1 MW', '')
            _v261_set(vals, cols, 'R1 Density', '')
            _v261_set(vals, cols, 'R1 mmol', '')
            _v261_set(vals, cols, 'R1 amount', '')
            _v261_set(vals, cols, 'Reagent 2 / catalyst', '')
            _v261_set(vals, cols, 'R2 MW', '')
            _v261_set(vals, cols, 'R2 Density', '')
            _v261_set(vals, cols, 'R2 mmol', '')
            _v261_set(vals, cols, 'R2 amount', '')
            bname = 'DIEA' if ('acetic anhydride' in unit.lower() or 'ac2o' in unit.lower()) else base
            bmmol = scale * copies * mod_eq * mod_rep if bname else 0
            bmw, bden = _v261_lookup(self, bname)
            _v261_set(vals, cols, 'Base', bname)
            _v261_set(vals, cols, 'Base MW', bmw)
            _v261_set(vals, cols, 'Base Density', bden)
            _v261_set(vals, cols, 'Base mmol', bmmol if bname else '')
            _v261_set(vals, cols, 'Base amount', _v261_amount(bname, bmmol, bmw, bden) if bname else '')
        else:
            r1mm = scale * copies * r1_eq * max(r1_count, 0) * rep if r1 else 0
            r2mm = scale * copies * r2_eq * max(r2_count, 0) * rep if r2 else 0
            bmm = scale * copies * base_eq * max(base_count, 0) * rep if base else 0
            r1mw, r1den = _v261_lookup(self, r1)
            r2mw, r2den = _v261_lookup(self, r2)
            bmw, bden = _v261_lookup(self, base)
            _v261_set(vals, cols, 'Reagent 1', r1)
            _v261_set(vals, cols, 'R1 MW', r1mw)
            _v261_set(vals, cols, 'R1 Density', r1den)
            _v261_set(vals, cols, 'R1 mmol', r1mm if r1 else '')
            _v261_set(vals, cols, 'R1 amount', _v261_amount(r1, r1mm, r1mw, r1den) if r1 else '')
            _v261_set(vals, cols, 'Reagent 2 / catalyst', r2)
            _v261_set(vals, cols, 'R2 MW', r2mw)
            _v261_set(vals, cols, 'R2 Density', r2den)
            _v261_set(vals, cols, 'R2 mmol', r2mm if r2 else '')
            _v261_set(vals, cols, 'R2 amount', _v261_amount(r2, r2mm, r2mw, r2den) if r2 else '')
            _v261_set(vals, cols, 'Base', base)
            _v261_set(vals, cols, 'Base MW', bmw)
            _v261_set(vals, cols, 'Base Density', bden)
            _v261_set(vals, cols, 'Base mmol', bmm if base else '')
            _v261_set(vals, cols, 'Base amount', _v261_amount(base, bmm, bmw, bden) if base else '')
        _v261_set(vals, cols, 'Coupling solvent', solvent)
        try:
            if solvent:
                if hasattr(self, 'solvent_volume_mode') and self.solvent_volume_mode.get() == 'molarity':
                    vol = _v257_working_ml(self, unit_mmol=unit_mmol)
                else:
                    vol = _v257_working_ml(self)
                _v261_set(vals, cols, 'Solvent mL', vol)
        except Exception:
            pass
        _v261_set(vals, cols, 'Repeat', rep)
        tree.item(iid, values=vals)


def _v261_resin_material_row(self):
    resin = str(_v261_var(self, 'pm_resin', _v261_var(self, 'resin', 'Rink Amide AM')) or '').strip()
    scale = _v261_f(_v261_var(self, 'pm_scale', _v261_var(self, 'scale', '0.2')), 0.2)
    loading = _v261_f(_v261_var(self, 'pm_loading', _v261_var(self, 'loading', '0.8')), 0.8)
    resin_g = scale / loading if loading > 0 else 0.0
    return {'material': resin, 'class': 'Resin', 'MW': '', 'Density(g/mL)': '', 'total mmol': _v261_s(scale),
            'total amount': f"{_v261_s(resin_g)} g" if resin_g else '',
            'note': f"Resin loading { _v261_s(loading) } mmol/g; required resin = scale/loading",
            '_mmol': scale, '_g': resin_g, '_mL': 0.0}


def _v261_materials_with_resin_and_protocol(self):
    try:
        mats = _v260_visible_plan_protocol_materials(self)
    except Exception:
        try: mats = _v251_visible_plan_to_materials(self)
        except Exception: mats = pd.DataFrame()
    try:
        resin_row = _v261_resin_material_row(self)
        if mats is None or mats.empty:
            mats = pd.DataFrame([resin_row])
        else:
            # Remove stale resin rows, then prepend the current one.
            if 'class' in mats.columns:
                mats = mats[mats['class'].astype(str).str.lower() != 'resin'].copy()
            mats = pd.concat([pd.DataFrame([resin_row]), mats], ignore_index=True)
    except Exception:
        pass
    return mats


def _v261_refresh_materials_total_protocol(self):
    mats = _v261_materials_with_resin_and_protocol(self)
    show_cols = ['material','class','MW','Density(g/mL)','total mmol','total amount','note']
    try:
        for c in ['_mmol','_g','_mL']:
            if c not in mats.columns: mats[c] = 0.0
    except Exception: pass
    try:
        if hasattr(self, 'pm_selected_material_tree'):
            _v251_write_tree(self.pm_selected_material_tree, mats[show_cols] if mats is not None and not mats.empty else pd.DataFrame(columns=show_cols))
    except Exception: pass
    try:
        if '_v228_ensure_total_tab' in globals(): _v228_ensure_total_tab(self)
    except Exception: pass
    try:
        if hasattr(self, 'pm_selected_total_tree'):
            _v251_write_tree(self.pm_selected_total_tree, _v252_total_from_materials(mats))
    except Exception: pass


