def _v261_apply_plan(self):
    if getattr(self, '_v261_apply_running', False):
        return
    self._v261_apply_running = True
    try:
        _v261_refresh_outputs_from_visible_plan(self)
        try: _v261_rebind_buttons(self)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Apply Plan', str(e))
        except Exception: pass
    finally:
        self._v261_apply_running = False


def _v261_delete_selected_rows(self):
    try:
        tree = getattr(self, 'pm_selected_plan_tree', None)
        if tree is None: return
        sel = list(tree.selection())
        if not sel: return
        for iid in sel:
            try: tree.delete(iid)
            except Exception: pass
        try:
            cols = list(tree['columns'])
            if 'No' in cols:
                ni = cols.index('No')
                for n, iid in enumerate(tree.get_children(), 1):
                    vals = list(tree.item(iid, 'values')); vals += [''] * max(0, len(cols)-len(vals))
                    vals[ni] = str(n); tree.item(iid, values=vals)
        except Exception: pass
        _v261_refresh_outputs_from_visible_plan(self)
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass


def _v261_relabel_resin_loading(self):
    # Rename old short "Loading" label in the selected peptide editor so the field is explicit.
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget('text')).strip() == 'Loading':
                        c.configure(text='Resin loading (mmol/g)')
                except Exception: pass
                try: walk(c)
                except Exception: pass
        walk(self)
    except Exception:
        pass


def _v261_rebind_buttons(self):
    def walk(w):
        try: children = list(w.winfo_children())
        except Exception: children = []
        for c in children:
            try:
                if isinstance(c, ttk.Button):
                    t = str(c.cget('text')).strip()
                    if t == 'Apply Plan':
                        c.configure(command=lambda _self=self: _v261_apply_plan(_self))
                    elif t == 'Delete selected row':
                        c.configure(command=lambda _self=self: _v261_delete_selected_rows(_self))
                    elif t == 'Generate / Update':
                        c.configure(command=lambda _self=self: _v259_generate_selected_stable(_self))
                    elif t == 'Load Project':
                        c.configure(command=lambda _self=self: _v257_load_project(_self))
                    elif t == 'Export batch tables':
                        c.configure(command=lambda _self=self: _v255_export_batch_tables(_self))
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass
    try: _v260_bind_batch_default_entries(self)
    except Exception: pass
    try: _v261_relabel_resin_loading(self)
    except Exception: pass


def _v261_after_build(self):
    try: _v260_patch_editable_tree()
    except Exception: pass
    try: _v259_add_solvent_basis_controls(self)
    except Exception: pass
    try: _v259_hide_solvent_explanation(self)
    except Exception: pass
    try: _v260_install_smooth_batch_refresh(self)
    except Exception: pass
    try: _v261_relabel_resin_loading(self)
    except Exception: pass
    try: _v261_rebind_buttons(self)
    except Exception: pass
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget('text')).startswith('SPPS Planner'):
                        c.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
                except Exception: pass
                try: walk(c)
                except Exception: pass
        walk(self)
    except Exception: pass

