# ======================= V2.0.63 FINAL APPLY RANGE CHECKLIST CALLBACK REPAIR =======================
# Purpose: one stable final connection layer on top of v2.0.62.
# - Fix stray no-self after_idle callback error from old v2.0.1 refresh route.
# - Apply Plan keeps visible Selected Plan row edits, but recalculates scale/loading/defaults/range.
# - AA eq range reads every historical UI variable: aa_range_mode, unit_calc_mode, aa_eq_mode,
#   unit_rule_enable, rule_enable.
# - Ac-AA-OH has no deprotection step, but is still listed in coupling order.
# - Materials/Checklist/Total/Batch are refreshed from the same visible Selected Plan source.
# - Duplicate Apply/Delete buttons are hidden; remaining buttons are rebound to this final route.
# ==================================================================================================
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

def _v263_float(x, default=0.0):
    try:
        if hasattr(x, 'get'):
            x = x.get()
        if x is None or str(x).strip() == '':
            return default
        return float(str(x).replace(',', '').strip())
    except Exception:
        return default

def _v263_str(x):
    try:
        f = float(x)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f"{f:.6f}".rstrip('0').rstrip('.')
    except Exception:
        return '' if x is None else str(x)

def _v263_var(self, name, default=''):
    try:
        v = getattr(self, name)
        return v.get() if hasattr(v, 'get') else v
    except Exception:
        return default

def _v263_bool_var(self, name, default=False):
    try:
        v = getattr(self, name)
        g = v.get() if hasattr(v, 'get') else v
        if isinstance(g, bool):
            return g
        return str(g).strip().lower() in {'1','true','yes','on','range'}
    except Exception:
        return default

def _v263_lookup(self, name):
    for fn in ('_v262_lookup','_v261_lookup','_v250_lookup','_v244_lookup','_v243_lookup','_v216_lookup_mw_density'):
        try:
            f = globals().get(fn)
            if f:
                out = f(self, name)
                if out and (str(out[0]).strip() or str(out[1]).strip()):
                    return out
        except Exception:
            pass
    return '', ''

def _v263_amount(name, mmol, mw, density=''):
    try:
        return _v262_amount(name, mmol, mw, density)
    except Exception:
        mwf = _v263_float(mw, 0); denf = _v263_float(density, 0); mm = _v263_float(mmol, 0)
        if not mm or not mwf:
            return ''
        g = mm * mwf / 1000.0
        low = str(name).lower()
        liquid = any(k in low for k in ['dic','diea','dipea','dmf','dcm','nmp','ac2o','acetic anhydride','piperidine','tfa','tis'])
        return f"{_v263_str(g/denf)} mL" if liquid and denf else f"{_v263_str(g)} g"

def _v263_parse_ranges(text):
    try:
        return _v262_parse_ranges(text)
    except Exception:
        out=[]
        for part in str(text or '').replace(';', ',').split(','):
            part=part.strip()
            if not part or ':' not in part:
                continue
            rng,val=part.split(':',1)
            try: v=float(val.strip())
            except Exception: continue
            try:
                if '-' in rng:
                    a,b=rng.split('-',1); a=int(float(a.strip())); b=int(float(b.strip()))
                else:
                    a=b=int(float(rng.strip()))
                if b<a: a,b=b,a
                out.append((a,b,v))
            except Exception:
                pass
        return out

def _v263_range_value(text, step, default):
    try: st=int(float(step))
    except Exception: st=1
    for a,b,v in _v263_parse_ranges(text):
        if a <= st <= b:
            return v
    return default

def _v263_aa_range_on(self):
    # v2 lineage used many UI variables. Treat any enabled/range one as the same AA range mode.
    if _v263_bool_var(self, 'aa_range_mode', False): return True
    if str(_v263_var(self, 'unit_calc_mode', '')).strip().lower() == 'range': return True
    if str(_v263_var(self, 'aa_eq_mode', '')).strip().lower() == 'range': return True
    if _v263_bool_var(self, 'unit_rule_enable', False): return True
    if _v263_bool_var(self, 'rule_enable', False): return True
    return False

def _v263_reagent_range_on(self):
    if _v263_bool_var(self, 'reagent_range_mode', False): return True
    if str(_v263_var(self, 'reagent_calc_mode', '')).strip().lower() == 'range': return True
    if _v263_bool_var(self, 'reagent_rule_enable', False): return True
    return False

def _v263_aa_eq_for_step(self, step, default):
    if _v263_aa_range_on(self):
        return _v263_range_value(_v263_var(self, 'rule_eq_rules', ''), step, default)
    return default

def _v263_repeat_for_step(self, step, default):
    if _v263_aa_range_on(self):
        return max(1, int(round(_v263_range_value(_v263_var(self, 'rule_repeat_rules', ''), step, default))))
    return default

def _v263_is_ac_aa_oh(unit):
    s = str(unit or '').strip().lower()
    return s.startswith('ac-') and s.endswith('-oh') and 'acetic anhydride' not in s and 'ac2o' not in s

def _v263_is_terminal_modifier(unit):
    if _v263_is_ac_aa_oh(unit):
        return False
    try:
        return _v262_is_terminal_modifier(unit)
    except Exception:
        s=str(unit or '').lower()
        return (not s.startswith('fmoc-')) and any(k in s for k in ['acetic anhydride','ac2o','palmitic','myristic','nicotinic','caffeic','gallic','biotin','fitc','cy','tag','his6','flag','ha'])

def _v263_needs_depro(unit):
    if _v263_is_ac_aa_oh(unit):
        return False
    return True

def _v263_tree_rows(self):
    tree=getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return []
    try:
        _v251_ensure_selected_plan_columns(self)
    except Exception:
        pass
    cols=list(tree['columns'])
    rows=[]
    for iid in tree.get_children():
        vals=list(tree.item(iid, 'values'))
        vals += [''] * max(0, len(cols)-len(vals))
        rows.append((iid, cols, vals, {c: vals[i] for i,c in enumerate(cols)}))
    return rows

def _v263_set(vals, cols, col, val):
    try:
        if col in cols:
            vals[cols.index(col)] = _v263_str(val)
    except Exception:
        pass

def _v263_scale_copies(self):
    scale=_v263_float(_v263_var(self, 'pm_scale', _v263_var(self, 'scale', '0.2')), 0.2)
    copies=max(1, int(round(_v263_float(_v263_var(self, 'pm_copies', '1'), 1))))
    return scale, copies

def _v263_working_ml(self, unit_mmol=None):
    try:
        return _v257_working_ml(self, unit_mmol=unit_mmol)
    except Exception:
        scale, copies = _v263_scale_copies(self)
        resin = str(_v263_var(self, 'pm_resin', _v263_var(self, 'resin', 'Rink Amide AM'))).lower()
        factor = 5.0 if ('ctc' in resin or 'trityl' in resin) else 10.0
        return scale * copies * factor

def _v263_commit_open_editors(self):
    for fn in ('_v259_commit_open_selected_plan_editor','_v261_save_editor_light'):
        try:
            f=globals().get(fn)
            if f: f(self)
        except Exception:
            pass

def _v263_recalc_visible_plan(self):
    tree=getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return
    _v263_commit_open_editors(self)
    try: _v251_ensure_selected_plan_columns(self)
    except Exception: pass
    scale, copies = _v263_scale_copies(self)
    default_aa_eq = _v263_float(_v263_var(self, 'coupling_eq', '5'), 5)
    default_mod_eq = _v263_float(_v263_var(self, 'modifier_eq', '3'), 3)
    default_aa_rep = max(1, int(round(_v263_float(_v263_var(self, 'coupling_repeats', '1'), 1))))
    default_mod_rep = max(1, int(round(_v263_float(_v263_var(self, 'modifier_repeats', '1'), 1))))
    r1 = str(_v263_var(self, 'default_reagent', 'DIC') or '').strip()
    r2 = str(_v263_var(self, 'default_catalyst', 'HOBt hydrate') or '').strip()
    base_default = str(_v263_var(self, 'default_base', '') or '').strip()
    solvent = str(_v263_var(self, 'default_coupling_solution_solvent', 'DMF') or 'DMF').strip()
    r1_eq_default = _v263_float(_v263_var(self, 'default_reagent_eq', default_aa_eq), default_aa_eq)
    r2_eq_default = _v263_float(_v263_var(self, 'default_catalyst_eq', default_aa_eq), default_aa_eq)
    base_eq_default = _v263_float(_v263_var(self, 'default_base_eq', '0'), 0)
    r1_count = max(0, int(round(_v263_float(_v263_var(self, 'default_reagent_count', '1'), 1))))
    r2_count = max(0, int(round(_v263_float(_v263_var(self, 'default_catalyst_count', '1'), 1))))
    base_count = max(0, int(round(_v263_float(_v263_var(self, 'default_base_count', '0'), 0))))
    for n,(iid, cols, vals, row) in enumerate(_v263_tree_rows(self), 1):
        unit=str(row.get('Unit name','')).strip()
        if not unit: continue
        terminal=_v263_is_terminal_modifier(unit)
        if terminal:
            eq=default_mod_eq; rep=default_mod_rep
        else:
            eq=_v263_aa_eq_for_step(self, n, default_aa_eq)
            rep=_v263_repeat_for_step(self, n, default_aa_rep)
        unit_mmol=scale * copies * eq * rep
        mw,den=_v263_lookup(self, unit)
        mw = mw or row.get('MW','')
        den = den or row.get('Density(g/mL)','')
        _v263_set(vals, cols, 'No', n)
        _v263_set(vals, cols, 'MW', mw)
        _v263_set(vals, cols, 'Density(g/mL)', den)
        _v263_set(vals, cols, 'Unit mmol', unit_mmol)
        _v263_set(vals, cols, 'Unit amount', _v263_amount(unit, unit_mmol, mw, den))
        if terminal:
            for c in ['Reagent 1','R1 MW','R1 Density','R1 mmol','R1 amount','Reagent 2 / catalyst','R2 MW','R2 Density','R2 mmol','R2 amount']:
                _v263_set(vals, cols, c, '')
            bname = 'DIEA' if ('acetic anhydride' in unit.lower() or 'ac2o' in unit.lower()) else base_default
            bmm = scale * copies * default_mod_eq * default_mod_rep if bname else 0
            bmw,bden=_v263_lookup(self, bname)
            _v263_set(vals, cols, 'Base', bname)
            _v263_set(vals, cols, 'Base MW', bmw)
            _v263_set(vals, cols, 'Base Density', bden)
            _v263_set(vals, cols, 'Base mmol', bmm if bname else '')
            _v263_set(vals, cols, 'Base amount', _v263_amount(bname, bmm, bmw, bden) if bname else '')
        else:
            if _v263_reagent_range_on(self):
                r1_eq = eq; r2_eq = eq; base_eq = base_eq_default
            else:
                r1_eq = r1_eq_default; r2_eq = r2_eq_default; base_eq = base_eq_default
            r1mm=scale*copies*r1_eq*r1_count*rep if r1 else 0
            r2mm=scale*copies*r2_eq*r2_count*rep if r2 else 0
            bmm=scale*copies*base_eq*base_count*rep if base_default else 0
            r1mw,r1den=_v263_lookup(self, r1); r2mw,r2den=_v263_lookup(self, r2); bmw,bden=_v263_lookup(self, base_default)
            _v263_set(vals, cols, 'Reagent 1', r1)
            _v263_set(vals, cols, 'R1 MW', r1mw)
            _v263_set(vals, cols, 'R1 Density', r1den)
            _v263_set(vals, cols, 'R1 mmol', r1mm if r1 else '')
            _v263_set(vals, cols, 'R1 amount', _v263_amount(r1, r1mm, r1mw, r1den) if r1 else '')
            _v263_set(vals, cols, 'Reagent 2 / catalyst', r2)
            _v263_set(vals, cols, 'R2 MW', r2mw)
            _v263_set(vals, cols, 'R2 Density', r2den)
            _v263_set(vals, cols, 'R2 mmol', r2mm if r2 else '')
            _v263_set(vals, cols, 'R2 amount', _v263_amount(r2, r2mm, r2mw, r2den) if r2 else '')
            _v263_set(vals, cols, 'Base', base_default)
            _v263_set(vals, cols, 'Base MW', bmw)
            _v263_set(vals, cols, 'Base Density', bden)
            _v263_set(vals, cols, 'Base mmol', bmm if base_default else '')
            _v263_set(vals, cols, 'Base amount', _v263_amount(base_default, bmm, bmw, bden) if base_default else '')
        _v263_set(vals, cols, 'Coupling solvent', solvent)
        _v263_set(vals, cols, 'Solvent mL', _v263_working_ml(self, unit_mmol=unit_mmol))
        _v263_set(vals, cols, 'Repeat', rep)
        tree.item(iid, values=vals)

def _v263_add_material(rows, material, cls, mw='', den='', mmol='', amount='', note='', forced_g=0.0, forced_ml=0.0):
    if not str(material or '').strip():
        return
    rows.append({'material':material,'class':cls,'MW':mw,'Density(g/mL)':den,
                 'total mmol':_v263_str(mmol) if str(mmol).strip() else '',
                 'total amount':amount,'note':note,
                 '_mmol':_v263_float(mmol,0),'_g':_v263_float(forced_g,0),'_mL':_v263_float(forced_ml,0)})

def _v263_add_split_solvent(self, rows, solvent, ml, cls, note):
    parts=[]
    try:
        parts=_v252_split_solvent(str(solvent), _v263_float(ml,0))
    except Exception:
        s=str(solvent or '').strip(); m=_v263_float(ml,0)
        if '90' in s and 'dcm' in s.lower() and 'dmf' in s.lower(): parts=[('DCM', m*0.9), ('DMF', m*0.1)]
        else: parts=[(s, m)]
    for name, part_ml in parts:
        if not name or not part_ml: continue
        mw,den=_v263_lookup(self, name)
        _v263_add_material(rows, name, cls, mw, den, '', f'{_v263_str(part_ml)} mL', note, forced_ml=part_ml)

def _v263_resin_row(self):
    resin=str(_v263_var(self, 'pm_resin', _v263_var(self, 'resin', 'Rink Amide AM')) or '').strip()
    scale,_copies=_v263_scale_copies(self)
    loading=_v263_float(_v263_var(self, 'pm_loading', _v263_var(self, 'loading', '0.8')), 0.8)
    g = scale/loading if loading else 0
    return {'material':resin,'class':'Resin','MW':'','Density(g/mL)':'','total mmol':_v263_str(scale),
            'total amount':f'{_v263_str(g)} g' if g else '', 'note':f'Resin loading {_v263_str(loading)} mmol/g',
            '_mmol':scale, '_g':g, '_mL':0.0}

def _v263_materials_in_synthesis_order(self):
    rows=[]
    rows.append(_v263_resin_row(self))
    work=_v263_working_ml(self)
    depro_count=max(0, int(round(_v263_float(_v263_var(self, 'default_depro_count', '2'), 2))))
    post_count=max(0, int(round(_v263_float(_v263_var(self, 'default_solvent1_count', '2'), 2))))
    final_count=3
    depro_total=work*depro_count
    piper=depro_total*0.20
    dmf_depro=depro_total*0.80
    dmf_wash6=work*6
    dmf_post=work*post_count
    valid=[(i,r) for i,(_,_,_,r) in enumerate(_v263_tree_rows(self)) if str(r.get('Unit name','')).strip()]
    last_index=valid[-1][0] if valid else -1
    for idx,r in valid:
        step = r.get('No') or str(idx+1)
        unit=str(r.get('Unit name','')).strip()
        if _v263_needs_depro(unit):
            _v263_add_material(rows, 'Piperidine', 'Deprotection base', '', '', '', f'{_v263_str(piper)} mL', f'Step {step}: 20% piperidine/DMF deprotection x{depro_count}', forced_ml=piper)
            _v263_add_material(rows, 'DMF', 'Deprotection solvent', '', '', '', f'{_v263_str(dmf_depro)} mL', f'Step {step}: DMF component of deprotection solution', forced_ml=dmf_depro)
            _v263_add_material(rows, 'DMF', 'Deprotection wash solvent', '', '', '', f'{_v263_str(dmf_wash6)} mL', f'Step {step}: DMF wash x6 after deprotection', forced_ml=dmf_wash6)
        _v263_add_material(rows, unit, 'AA/Chemical', r.get('MW',''), r.get('Density(g/mL)',''), r.get('Unit mmol',''), r.get('Unit amount',''), f'Step {step}: coupling unit')
        _v263_add_material(rows, r.get('Reagent 1',''), 'Coupling reagent', r.get('R1 MW',''), r.get('R1 Density',''), r.get('R1 mmol',''), r.get('R1 amount',''), f'Step {step}: reagent 1')
        _v263_add_material(rows, r.get('Reagent 2 / catalyst',''), 'Catalyst/additive', r.get('R2 MW',''), r.get('R2 Density',''), r.get('R2 mmol',''), r.get('R2 amount',''), f'Step {step}: reagent 2/catalyst')
        _v263_add_material(rows, r.get('Base',''), 'Base', r.get('Base MW',''), r.get('Base Density',''), r.get('Base mmol',''), r.get('Base amount',''), f'Step {step}: base')
        _v263_add_split_solvent(self, rows, r.get('Coupling solvent',''), _v263_float(r.get('Solvent mL',''),0), 'Coupling solvent', f'Step {step}: coupling cocktail solvent')
        if idx == last_index:
            _v263_add_material(rows, 'DMF', 'Final wash solvent', '', '', '', f'{_v263_str(work*final_count)} mL', 'Final wash: DMF x3', forced_ml=work*final_count)
            _v263_add_material(rows, 'DCM', 'Final wash solvent', '', '', '', f'{_v263_str(work*final_count)} mL', 'Final wash: DCM x3', forced_ml=work*final_count)
        else:
            if post_count:
                _v263_add_material(rows, 'DMF', 'Post-coupling wash solvent', '', '', '', f'{_v263_str(dmf_post)} mL', f'Step {step}: DMF wash x{post_count} after coupling', forced_ml=dmf_post)
    return pd.DataFrame(rows)

def _v263_refresh_materials_and_total(self):
    mats=_v263_materials_in_synthesis_order(self)
    show_cols=['material','class','MW','Density(g/mL)','total mmol','total amount','note']
    try:
        if hasattr(self, 'pm_selected_material_tree'):
            _v251_write_tree(self.pm_selected_material_tree, mats[show_cols] if mats is not None and not mats.empty else pd.DataFrame(columns=show_cols))
    except Exception: pass
    try:
        if '_v228_ensure_total_tab' in globals(): _v228_ensure_total_tab(self)
    except Exception: pass
    try:
        if hasattr(self, 'pm_selected_total_tree'):
            _v251_write_tree(self.pm_selected_total_tree, _v252_total_from_materials(mats))
    except Exception: pass
    return mats

def _v263_checklist_df(self):
    work=_v263_working_ml(self)
    rows=[]; line=1
    def add(op, unit, next_step='', note=''):
        nonlocal line
        rows.append({'line':line,'done':'No','checked_at':'','operation':op,'unit':unit,'next_step':next_step,'note':note}); line+=1
    add('Resin swell', str(_v263_var(self, 'pm_resin', 'Resin')), 'First cycle', f'working volume={_v263_str(work)} mL')
    valid=[(i,r) for i,(_,_,_,r) in enumerate(_v263_tree_rows(self)) if str(r.get('Unit name','')).strip()]
    last_index=valid[-1][0] if valid else -1
    for idx,r in valid:
        unit=str(r.get('Unit name','')).strip(); step=r.get('No') or str(idx+1)
        if _v263_needs_depro(unit):
            add('Deprotection', unit, 'DMF wash after deprotection', f'Step {step}: 20% piperidine/DMF x2')
            add('DMF wash after deprotection', unit, 'Coupling reaction', f'Step {step}: DMF wash x6')
        else:
            add('No deprotection required', unit, 'Coupling reaction', f'Step {step}: Ac-AA-OH')
        add('Coupling reaction', unit, 'Post-coupling wash or final wash', f"{r.get('Reagent 1','')} / {r.get('Reagent 2 / catalyst','')} / {r.get('Base','')}; solvent={r.get('Coupling solvent','')} {r.get('Solvent mL','')} mL")
        if idx == last_index:
            add('Final wash', unit, 'End', 'DMF x3')
            add('Final wash', unit, 'End', 'DCM x3')
        else:
            add('Post-coupling wash', unit, 'Next cycle', 'DMF wash x2')
    return pd.DataFrame(rows, columns=['line','done','checked_at','operation','unit','next_step','note'])

def _v263_refresh_checklist(self):
    df=_v263_checklist_df(self)
    try:
        if hasattr(self, 'progress_tree'):
            _v251_write_tree(self.progress_tree, df)
    except Exception:
        pass
    try:
        tree=getattr(self, 'pm_selected_check_tree', None)
        if tree is not None:
            _v251_write_tree(tree, df)
    except Exception:
        pass
    try:
        txt=getattr(self, 'pm_selected_check_text', None)
        if txt is not None:
            lines=[]
            for _,r in df.iterrows():
                lines.append(f"{r.get('line')}. {r.get('operation')} | {r.get('unit')} | {r.get('next_step')} | {r.get('note')}")
            txt.delete('1.0', 'end')
            txt.insert('end', '\n'.join(lines))
    except Exception:
        pass

def _v263_refresh_batch(self):
    try:
        if hasattr(self, '_v260_schedule_batch_refresh'):
            self._v260_schedule_batch_refresh()
        elif hasattr(self, 'refresh_batch_workspace_preview'):
            self.refresh_batch_workspace_preview()
    except Exception:
        pass

def _v263_apply_plan(self):
    if getattr(self, '_v263_apply_running', False):
        return
    self._v263_apply_running=True
    try:
        _v263_recalc_visible_plan(self)
        _v263_refresh_materials_and_total(self)
        _v263_refresh_checklist(self)
        _v263_refresh_batch(self)
        try: _v263_rebind_buttons(self)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Apply Plan', str(e))
        except Exception: pass
    finally:
        self._v263_apply_running=False

def _v263_delete_selected_rows(self):
    try:
        tree=getattr(self, 'pm_selected_plan_tree', None)
        if tree is None: return
        sel=list(tree.selection())
        if not sel: return
        for iid in sel: tree.delete(iid)
        try:
            cols=list(tree['columns']); ni=cols.index('No') if 'No' in cols else -1
            if ni >= 0:
                for n,iid in enumerate(tree.get_children(), 1):
                    vals=list(tree.item(iid, 'values')); vals += ['']*max(0, len(cols)-len(vals)); vals[ni]=str(n); tree.item(iid, values=vals)
        except Exception: pass
        _v263_apply_plan(self)
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass

def _v263_hide_duplicate_action_buttons(self):
    buttons=[]
    def walk(w):
        try: children=list(w.winfo_children())
        except Exception: children=[]
        for c in children:
            try:
                if isinstance(c, ttk.Button):
                    t=str(c.cget('text')).strip()
                    if t in {'Apply Plan','Delete selected row'}:
                        buttons.append((t,c))
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass
    seen=set()
    for t,b in buttons:
        if t not in seen:
            seen.add(t); continue
        try: b.grid_remove()
        except Exception:
            try: b.pack_forget()
            except Exception:
                try: b.place_forget()
                except Exception: pass

def _v263_bind_entry_replace_on_focus(self):
    # Keep Batch Manager numeric typing smooth: first number replaces selected old value, not prefixes it.
    names=['batch_coupling_eq','batch_solution_conc','batch_actual_round_ml','batch_actual_extra_ml','batch_hbtu_eq','batch_hbtu_conc']
    targets=set()
    for nm in names:
        try:
            v=getattr(self, nm)
            def walk(w):
                try: children=list(w.winfo_children())
                except Exception: children=[]
                for c in children:
                    try:
                        if isinstance(c, ttk.Entry) and str(c.cget('textvariable')) == str(v):
                            targets.add(c)
                    except Exception: pass
                    try: walk(c)
                    except Exception: pass
            walk(self)
        except Exception:
            pass
    def select_all(event):
        try:
            event.widget.selection_range(0, 'end')
            event.widget.icursor('end')
        except Exception: pass
        return None
    for e in list(targets):
        try:
            e.bind('<FocusIn>', select_all, add='+')
            e.bind('<Double-1>', select_all, add='+')
        except Exception: pass

def _v263_rebind_buttons(self):
    def walk(w):
        try: children=list(w.winfo_children())
        except Exception: children=[]
        for c in children:
            try:
                if isinstance(c, ttk.Button):
                    t=str(c.cget('text')).strip()
                    if t == 'Apply Plan': c.configure(command=lambda _self=self: _v263_apply_plan(_self))
                    elif t == 'Delete selected row': c.configure(command=lambda _self=self: _v263_delete_selected_rows(_self))
                    elif t == 'Generate / Update': c.configure(command=lambda _self=self: _v259_generate_selected_stable(_self))
                    elif t == 'Load Project' and '_v257_load_project' in globals(): c.configure(command=lambda _self=self: _v257_load_project(_self))
                    elif t == 'Export batch tables' and '_v255_export_batch_tables' in globals(): c.configure(command=lambda _self=self: _v255_export_batch_tables(_self))
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass
    try: _v263_hide_duplicate_action_buttons(self)
    except Exception: pass
    try: _v263_bind_entry_replace_on_focus(self)
    except Exception: pass
    try: _v261_relabel_resin_loading(self)
    except Exception: pass

def _v263_after_build(self):
    try: _v260_patch_editable_tree()
    except Exception: pass
    try: _v259_add_solvent_basis_controls(self)
    except Exception: pass
    try: _v259_hide_solvent_explanation(self)
    except Exception: pass
    try: _v260_install_smooth_batch_refresh(self)
    except Exception: pass
    try: _v263_rebind_buttons(self)
    except Exception: pass
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        def walk(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget('text')).startswith('SPPS Planner'):
                        c.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
                except Exception: pass
                try: walk(c)
                except Exception: pass
        walk(self)
    except Exception: pass

try:
    _v263_previous_build = SPPSGui._build
    def _v263_build(self):
        _v263_previous_build(self)
        _v263_after_build(self)
        try: self.after(250, lambda _self=self: _v263_after_build(_self))
        except Exception: pass
    SPPSGui._build = _v263_build
except Exception:
    pass

SPPSGui.apply_plan_mw_density = _v263_apply_plan
try:
    for _nm in ['_v251_apply_plan','_v252_apply_plan','_v254_apply_plan','_v255_apply_plan','_v257_apply_plan','_v258_apply_plan','_v259_apply_plan','_v260_apply_plan','_v261_apply_plan','_v262_apply_plan']:
        globals()[_nm] = _v263_apply_plan
    for _nm in ['_v249_delete_selected_rows','_v250_delete_selected_rows','_v251_delete_selected_rows','_v254_delete_selected_rows','_v257_delete_selected_rows','_v259_delete_selected_rows','_v260_delete_selected_rows','_v261_delete_selected_rows','_v262_delete_selected_rows']:
        globals()[_nm] = _v263_delete_selected_rows
except Exception:
    pass
