# ======================= V2.0.63a HOTFIX: solvent tuple compatibility =======================
def _v263_add_split_solvent(self, rows, solvent, ml, cls, note):
    parts=[]
    try:
        parts=_v252_split_solvent(str(solvent), _v263_float(ml,0))
    except Exception:
        s=str(solvent or '').strip(); m=_v263_float(ml,0)
        if '90' in s and 'dcm' in s.lower() and 'dmf' in s.lower(): parts=[('DCM', m*0.9, 'Split from 90% DCM / 10% DMF') , ('DMF', m*0.1, 'Split from 90% DCM / 10% DMF')]
        else: parts=[(s, m, note)]
    for item in parts:
        try:
            name = item[0]; part_ml = item[1]; part_note = item[2] if len(item) > 2 and str(item[2]).strip() else note
        except Exception:
            continue
        if not name or not part_ml: continue
        mw,den=_v263_lookup(self, name)
        _v263_add_material(rows, name, cls, mw, den, '', f'{_v263_str(part_ml)} mL', part_note, forced_ml=part_ml)
