# ======================= V2.0.64 FINAL STABLE GENERATE + BUTTON CLEANUP =======================
# User feedback target:
# - Generate / Update must never fall back to legacy raw Selected Plan columns.
# - Apply Plan must preserve the visible Selected Plan unit rows, while recalculating editor/default/range values.
# - Remove hidden duplicate legacy action buttons/callbacks instead of merely hiding them.
# - Keep V2.0.63 Apply/Materials/Checklist/Total/Batch, AA range, Ac-AA-OH and protocol-order fixes.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

_V264_PLAN_COLS = [
    "No","Unit name","MW","Density(g/mL)","Unit mmol","Unit amount",
    "Reagent 1","R1 MW","R1 Density","R1 mmol","R1 amount",
    "Reagent 2 / catalyst","R2 MW","R2 Density","R2 mmol","R2 amount",
    "Base","Base MW","Base Density","Base mmol","Base amount",
    "Coupling solvent","Solvent mL","Repeat","Note"
]

_V264_SYNONYMS = dict(globals().get('_V251_SYNONYMS', {}) or {})
_V264_SYNONYMS.update({
    "Unit eq": "Unit mmol",
    "Unit amount(g)": "Unit amount",
    "Unit volume(mL)": "Unit amount",
    "Coupling reagent 1": "Reagent 1",
    "Coupling reagent 2 / catalyst": "Reagent 2 / catalyst",
    "Coupling base": "Base",
    "Coupling cocktail solvent": "Coupling solvent",
    "Coupling cocktail volume(mL)": "Solvent mL",
})


def _v264_str(x):
    try:
        f = float(x)
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f"{f:.6f}".rstrip('0').rstrip('.')
    except Exception:
        return '' if x is None else str(x)


def _v264_tree_to_df(tree):
    cols = list(tree['columns'] or [])
    out = []
    for iid in list(tree.get_children()):
        vals = list(tree.item(iid, 'values'))
        vals += [''] * max(0, len(cols) - len(vals))
        row = {}
        for i, c in enumerate(cols):
            mapped = _V264_SYNONYMS.get(c, c)
            if mapped in _V264_PLAN_COLS and not str(row.get(mapped, '')).strip():
                row[mapped] = vals[i]
        out.append(row)
    return pd.DataFrame(out)


def _v264_normalize_plan_df(self, df=None, *, preserve_visible=True):
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if df is None:
        if preserve_visible and tree is not None and len(list(tree.get_children())):
            df = _v264_tree_to_df(tree)
        else:
            try:
                df = _v248_plan_display_df(self)
            except Exception:
                df = pd.DataFrame(columns=_V264_PLAN_COLS)
    if df is None:
        df = pd.DataFrame(columns=_V264_PLAN_COLS)
    try:
        df = df.copy()
    except Exception:
        df = pd.DataFrame(df)
    # Rename old/legacy columns into the final visible contract.
    for old, new in list(_V264_SYNONYMS.items()):
        if old in df.columns:
            if new not in df.columns:
                df[new] = df[old]
            else:
                try:
                    df[new] = df[new].where(df[new].astype(str).str.strip() != '', df[old])
                except Exception:
                    pass
    for c in _V264_PLAN_COLS:
        if c not in df.columns:
            df[c] = ''
    df = df[_V264_PLAN_COLS].fillna('')
    # Stable No values.
    if len(df):
        try:
            df['No'] = [str(i) for i in range(1, len(df) + 1)]
        except Exception:
            pass
    return df.astype(str)


def _v264_write_selected_plan(self, df=None, *, preserve_visible=True):
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return pd.DataFrame(columns=_V264_PLAN_COLS)
    df = _v264_normalize_plan_df(self, df, preserve_visible=preserve_visible)
    try:
        tree.configure(columns=_V264_PLAN_COLS, show='headings')
        widths = {
            "No": 50, "Unit name": 285, "MW": 90, "Density(g/mL)": 125,
            "Unit mmol": 110, "Unit amount": 130,
            "Reagent 1": 125, "R1 MW": 90, "R1 Density": 110, "R1 mmol": 110, "R1 amount": 125,
            "Reagent 2 / catalyst": 175, "R2 MW": 90, "R2 Density": 110, "R2 mmol": 110, "R2 amount": 125,
            "Base": 115, "Base MW": 90, "Base Density": 110, "Base mmol": 110, "Base amount": 125,
            "Coupling solvent": 170, "Solvent mL": 115, "Repeat": 75, "Note": 330,
        }
        for c in _V264_PLAN_COLS:
            tree.heading(c, text=c)
            tree.column(c, width=widths.get(c, 130), minwidth=60, anchor='w', stretch=False)
        _kids = list(tree.get_children())
        if _kids: tree.delete(*_kids)
        for _, r in df.iterrows():
            tree.insert('', 'end', values=[str(r.get(c, '')) for c in _V264_PLAN_COLS])
    except Exception:
        try:
            _v251_write_tree(tree, df)
        except Exception:
            pass
    try:
        tree.bind('<Double-1>', lambda e, _self=self: _v251_cell_editor(_self, e))
    except Exception:
        pass
    return df


def _v264_commit_editor_defaults(self):
    for fn in ('_v257_save_editor_and_defaults', '_v258_commit_editor_to_item_fast', '_v263_commit_open_editors'):
        try:
            f = globals().get(fn)
            if f:
                f(self)
        except Exception:
            pass
    try:
        if hasattr(self, 'pm_save_selected'):
            self.pm_save_selected()
    except Exception:
        pass
    try:
        if '_v257_sync_ml_per_mmol' in globals():
            _v257_sync_ml_per_mmol(self)
    except Exception:
        pass


def _v264_generate_selected(self):
    """Explicit rebuild from editor/sequence/defaults, but always final V2.0.64 table contract."""
    if getattr(self, '_v264_generate_running', False):
        return
    self._v264_generate_running = True
    try:
        try: _v257_init_solvent_basis(self)
        except Exception: pass
        _v264_commit_editor_defaults(self)
        # Build a fresh plan without letting older functions leave legacy columns behind.
        df = None
        try:
            idx = self.pm_current_index() if hasattr(self, 'pm_current_index') else None
            if idx is not None and hasattr(self, 'pm_items') and 0 <= idx < len(self.pm_items):
                try:
                    self.pm_apply_item_to_single_plan(self.pm_items[idx])
                    self.pm_items[idx]['status'] = 'Calculated'
                except Exception:
                    pass
        except Exception:
            pass
        try:
            df = _v248_plan_display_df(self)
        except Exception:
            # Last resort: convert whatever tree has, then keep only final columns.
            try: df = _v264_tree_to_df(getattr(self, 'pm_selected_plan_tree'))
            except Exception: df = pd.DataFrame(columns=_V264_PLAN_COLS)
        _v264_write_selected_plan(self, df, preserve_visible=False)
        # Apply the latest editor/default/range/solvent values to the final table only.
        try: _v263_recalc_visible_plan(self)
        except Exception: pass
        try: _v263_refresh_materials_and_total(self)
        except Exception: pass
        try: _v263_refresh_checklist(self)
        except Exception: pass
        try: _v263_refresh_batch(self)
        except Exception: pass
        try:
            if hasattr(self, 'pm_refresh_list'):
                self.pm_refresh_list(keep_index=self.pm_current_index(), reload_editor=False)
        except TypeError:
            try: self.pm_refresh_list()
            except Exception: pass
        except Exception:
            pass
        try: self.pm_update_summary()
        except Exception: pass
        try: self.schedule_autosave()
        except Exception: pass
        try: _v264_clean_action_buttons(self)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v264_generate_running = False


def _v264_apply_plan(self):
    """Apply visible rows only; do not regenerate sequence, but recalc scale/default/range/loading and outputs."""
    if getattr(self, '_v264_apply_running', False):
        return
    self._v264_apply_running = True
    try:
        try: _v257_init_solvent_basis(self)
        except Exception: pass
        _v264_commit_editor_defaults(self)
        # Preserve current rows and manual Unit name edits, but force final table columns.
        _v264_write_selected_plan(self, preserve_visible=True)
        try: _v263_recalc_visible_plan(self)
        except Exception: pass
        try: _v263_refresh_materials_and_total(self)
        except Exception: pass
        try: _v263_refresh_checklist(self)
        except Exception: pass
        try: _v263_refresh_batch(self)
        except Exception: pass
        try: self.schedule_autosave()
        except Exception: pass
        try: _v264_clean_action_buttons(self)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Apply Plan', str(e))
        except Exception: pass
    finally:
        self._v264_apply_running = False


def _v264_delete_selected_rows(self):
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return
    sel = list(tree.selection())
    if not sel:
        return
    try:
        for iid in sel:
            tree.delete(iid)
        _v264_write_selected_plan(self, preserve_visible=True)
        _v264_apply_plan(self)
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass


def _v264_clean_action_buttons(self):
    # Keep the first visible action button of each type and destroy legacy duplicates, including hidden ones.
    keep = {}
    labels = {'Apply Plan', 'Delete selected row', 'Generate / Update', 'Load Project'}
    def walk(w):
        try: children = list(w.winfo_children())
        except Exception: children = []
        for c in children:
            try:
                if isinstance(c, ttk.Button):
                    text = str(c.cget('text')).strip()
                    if text in labels:
                        if text not in keep:
                            keep[text] = c
                        else:
                            try: c.destroy()
                            except Exception:
                                try: c.grid_remove()
                                except Exception:
                                    try: c.pack_forget()
                                    except Exception: pass
                            continue
                walk(c)
            except Exception:
                try: walk(c)
                except Exception: pass
    try: walk(self)
    except Exception: pass
    # Rebind the kept buttons to the final V2.0.64 callbacks.
    for text, btn in list(keep.items()):
        try:
            if text == 'Apply Plan': btn.configure(command=lambda _self=self: _v264_apply_plan(_self))
            elif text == 'Delete selected row': btn.configure(command=lambda _self=self: _v264_delete_selected_rows(_self))
            elif text == 'Generate / Update': btn.configure(command=lambda _self=self: _v264_generate_selected(_self))
            elif text == 'Load Project' and '_v257_load_project' in globals(): btn.configure(command=lambda _self=self: _v257_load_project(_self))
        except Exception:
            pass
    try: _v263_bind_entry_replace_on_focus(self)
    except Exception: pass
    try: _v261_relabel_resin_loading(self)
    except Exception: pass


def _v264_after_build(self):
    try: _v260_patch_editable_tree()
    except Exception: pass
    try: _v259_add_solvent_basis_controls(self)
    except Exception: pass
    try: _v259_hide_solvent_explanation(self)
    except Exception: pass
    try: _v260_install_smooth_batch_refresh(self)
    except Exception: pass
    try: _v264_write_selected_plan(self, preserve_visible=True)
    except Exception: pass
    try: _v264_clean_action_buttons(self)
    except Exception: pass
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        def walk_label(w):
            for c in w.winfo_children():
                try:
                    if isinstance(c, ttk.Label) and str(c.cget('text')).startswith('SPPS Planner'):
                        c.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
                except Exception: pass
                try: walk_label(c)
                except Exception: pass
        walk_label(self)
    except Exception: pass

