def _v264d_rebind_buttons(self):
    try: _v264_clean_action_buttons(self)
    except Exception: pass
    def walk(w):
        try: children=list(w.winfo_children())
        except Exception: children=[]
        for c in children:
            try:
                if isinstance(c, ttk.Button):
                    t=str(c.cget('text')).strip()
                    if t == 'Generate / Update': c.configure(command=lambda _self=self: _v264d_generate_selected(_self))
                    elif t == 'Apply Plan': c.configure(command=lambda _self=self: _v264d_apply_plan(_self))
                    elif t == 'Delete selected row': c.configure(command=lambda _self=self: _v264d_delete_selected_rows(_self))
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass


