def _v264j_cancel_idle_callbacks(self):
    try:
        ids = self.tk.call('after', 'info')
        if isinstance(ids, str):
            ids = ids.split()
        for aid in ids:
            try:
                info = self.tk.call('after', 'info', aid)
                if len(info) >= 2 and str(info[1]) == 'idle':
                    self.after_cancel(aid)
            except Exception:
                pass
    except Exception:
        pass


