def _v265_select_all_entry(e):
    try:
        w=e.widget; w.focus_set(); w.selection_range(0,'end'); w.icursor('end')
    except Exception: pass
    return None


def _v265_entry_key_replace(e):
    try:
        w=e.widget
        # printable keys replace current selection fully
        if e.char and len(e.char)==1 and (str(e.state) not in ('4','8')):
            try:
                if w.selection_present():
                    w.delete('sel.first','sel.last'); w.insert('insert', e.char); return 'break'
            except Exception: pass
    except Exception: pass
    return None


def _v265_patch_entry_editing(self):
    def walk(w):
        for c in list(w.winfo_children()):
            try:
                if isinstance(c, ttk.Entry) or isinstance(c, tk.Entry):
                    c.bind('<Double-Button-1>', _v265_select_all_entry, add=False)
                    c.bind('<FocusIn>', _v265_select_all_entry, add=True)
                    c.bind('<KeyPress>', _v265_entry_key_replace, add=False)
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass


def _v265_ensure_resin_loading_editor(self):
    try:
        if not hasattr(self,'pm_loading'): self.pm_loading=tk.StringVar(value='0.8')
    except Exception: pass
    found_entry=False
    labels=[]
    def walk(w):
        nonlocal found_entry
        for c in list(w.winfo_children()):
            try:
                if isinstance(c, ttk.Entry) or isinstance(c, tk.Entry):
                    if str(c.cget('textvariable')) == str(getattr(self,'pm_loading','')):
                        found_entry=True
                if isinstance(c, ttk.Label):
                    txt=str(c.cget('text'))
                    if txt in ('Loading','Resin loading','Resin loading (mmol/g)'):
                        labels.append(c)
                        c.configure(text='Resin loading (mmol/g)')
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass
    if (not found_entry) and labels:
        lab=labels[0]
        try:
            parent=lab.master; info=lab.grid_info(); row=int(info.get('row',0)); col=int(info.get('column',0))
            ent=ttk.Entry(parent, textvariable=self.pm_loading, width=10)
            ent.grid(row=row, column=col+1, sticky='ew', padx=(0,8), pady=2)
            found_entry=True
        except Exception: pass
    return found_entry


def _v265_rebind_action_buttons(self):
    seen={}
    def walk(w):
        for c in list(w.winfo_children()):
            try:
                if isinstance(c, ttk.Button) or isinstance(c, tk.Button):
                    t=str(c.cget('text')).strip()
                    if t=='Generate / Update':
                        if seen.get(t): c.grid_remove() if c.winfo_manager()=='grid' else c.pack_forget()
                        else: c.configure(command=lambda _self=self: _v265_generate_selected(_self)); seen[t]=1
                    elif t=='Apply Plan':
                        if seen.get(t): c.grid_remove() if c.winfo_manager()=='grid' else c.pack_forget()
                        else: c.configure(command=lambda _self=self: _v265_apply_plan(_self)); seen[t]=1
                    elif t=='Delete selected row':
                        if seen.get(t): c.grid_remove() if c.winfo_manager()=='grid' else c.pack_forget()
                        else: c.configure(command=lambda _self=self: _v265_delete_selected_rows(_self)); seen[t]=1
                    elif t=='Use HBTU/NMP 10eq': c.configure(command=lambda _self=self: _v265_hbtu_nmp_preset(_self))
                    elif t=='Use DIC/HOBt': c.configure(command=lambda _self=self: _v265_dic_hobt_preset(_self))
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass


def _v265_fast_pm_on_select(self, event=None):
    # only load editor; no automatic heavy generate while moving selection/sash
    try:
        idx=self.pm_current_index()
        if idx is None: return
        if hasattr(self,'pm_load_item_to_editor'): self.pm_load_item_to_editor(idx)
    except Exception: pass


def _v265_fast_pm_on_double_click(self, event=None):
    try: _v265_fast_pm_on_select(self,event)
    except Exception: pass
    # do not auto-generate; user can press Generate. This keeps item switching instant.
    return 'break'


