def _v265a_rebind_action_buttons(self):
    buckets={'Generate / Update':[], 'Apply Plan':[], 'Delete selected row':[]}
    def walk(w):
        for c in list(w.winfo_children()):
            try:
                if isinstance(c, ttk.Button) or isinstance(c, tk.Button):
                    t=str(c.cget('text')).strip()
                    if t in buckets: buckets[t].append(c)
                    elif t=='Use HBTU/NMP 10eq': c.configure(command=lambda _self=self: _v265_hbtu_nmp_preset(_self))
                    elif t=='Use DIC/HOBt': c.configure(command=lambda _self=self: _v265_dic_hobt_preset(_self))
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass
    cmds={'Generate / Update':lambda _self=self: _v265_generate_selected(_self), 'Apply Plan':lambda _self=self: _v265_apply_plan(_self), 'Delete selected row':lambda _self=self: _v265_delete_selected_rows(_self)}
    keep={}
    for t,lst in buckets.items():
        if not lst: continue
        mapped=[b for b in lst if b.winfo_ismapped()]
        b=(mapped[0] if mapped else lst[0]); keep[t]=b
        try: b.configure(command=cmds[t])
        except Exception: pass
        for other in lst:
            if other is b: continue
            try:
                if other.winfo_manager()=='grid': other.grid_remove()
                elif other.winfo_manager()=='pack': other.pack_forget()
                elif other.winfo_manager()=='place': other.place_forget()
            except Exception: pass
    # Ensure Delete selected row exists next to Apply Plan if all old delete buttons were hidden/unmapped.
    try:
        vis_delete = keep.get('Delete selected row') if keep.get('Delete selected row') and keep.get('Delete selected row').winfo_ismapped() else None
        apply_btn = keep.get('Apply Plan')
        if vis_delete is None and apply_btn is not None:
            parent=apply_btn.master
            mgr=apply_btn.winfo_manager()
            nb=ttk.Button(parent, text='Delete selected row', command=lambda _self=self: _v265_delete_selected_rows(_self))
            if mgr=='pack': nb.pack(side='left', padx=3)
            elif mgr=='grid':
                info=apply_btn.grid_info(); nb.grid(row=int(info.get('row',0)), column=int(info.get('column',0))+1, sticky='w', padx=3)
            else: nb.pack(side='left', padx=3)
            keep['Delete selected row']=nb
    except Exception: pass

# replace earlier rebinder with visibility-safe rebinder
_v265_rebind_action_buttons = _v265a_rebind_action_buttons
