# ======================= V2.0.67 SEQUENCE_GENERATE_ACAA_TOTAL_CLASS_FIX =======================
# User-facing fixes:
# - Generate / Update must use the currently visible sequence, not stale STD item data.
# - Selected Total Materials class labels: DMF -> Reaction solvent 1, DCM -> Reaction solvent 2.
# - Ac-AA-OH terminal coupling: deprotect the previous Fmoc-AA before Ac-AA coupling, but do not
#   add a deprotection step after Ac-AA-OH itself; final DMF/DCM wash still applies.
# - Keep v2.0.66 UI/performance/Add/Duplicate/resin-loading/batch-entry fixes intact.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v267_strip_sequence(seq):
    import re as _re
    raw = str(seq or '').strip()
    has_ac = bool(_re.match(r'^\s*Ac\s*[-_]', raw, flags=_re.I))
    raw = _re.sub(r'^\s*Ac\s*[-_]\s*', '', raw, flags=_re.I)
    raw = _re.sub(r'[-_]?\s*(NH2|CONH2|COOH|OH)\s*$', '', raw, flags=_re.I)
    return raw, has_ac


def _v267_sequence_letters(self):
    raw, has_ac = _v267_strip_sequence(_v266_getvar(self, 'pm_sequence', ''))
    toks = []
    try:
        if hasattr(self, '_aa_letters_from_sequence'):
            toks = [str(x).upper() for x in self._aa_letters_from_sequence(raw)]
    except Exception:
        toks = []
    if not toks:
        valid = set('ARNDCQEGHILKMFPSTWYV')
        toks = [c.upper() for c in str(raw) if c.upper() in valid]
    return toks, has_ac


def _v267_generate_units_from_editor(self):
    toks, has_ac = _v267_sequence_letters(self)
    aa_map = _v248_aa_map() if '_v248_aa_map' in globals() else {
        'A':'Fmoc-Ala-OH','R':'Fmoc-Arg(Pbf)-OH','N':'Fmoc-Asn(Trt)-OH','D':'Fmoc-Asp(OtBu)-OH','C':'Fmoc-Cys(Trt)-OH',
        'Q':'Fmoc-Gln(Trt)-OH','E':'Fmoc-Glu(OtBu)-OH','G':'Fmoc-Gly-OH','H':'Fmoc-His(Trt)-OH','I':'Fmoc-Ile-OH',
        'L':'Fmoc-Leu-OH','K':'Fmoc-Lys(Boc)-OH','M':'Fmoc-Met-OH','F':'Fmoc-Phe-OH','P':'Fmoc-Pro-OH','S':'Fmoc-Ser(tBu)-OH',
        'T':'Fmoc-Thr(tBu)-OH','W':'Fmoc-Trp(Boc)-OH','Y':'Fmoc-Tyr(tBu)-OH','V':'Fmoc-Val-OH'}
    # SPPS build order is C -> N, so reverse the N->C sequence input.
    units = [aa_map.get(x, x) for x in reversed(toks)]
    if has_ac and units:
        units.append('Acetic anhydride (Ac2O) for N-terminal acetylation')
    return units


def _v267_generate_selected(self):
    if getattr(self, '_v267_gen_busy', False):
        return
    self._v267_gen_busy = True
    try:
        _v265_cancel_legacy_after(self)
        try:
            _v266_save_editor_to_current_item(self)
        except Exception:
            pass
        import pandas as _pd
        units = _v267_generate_units_from_editor(self)
        rows = []
        for i, unit in enumerate(units, 1):
            rows.append({c: '' for c in _V265_PLAN_COLS})
            rows[-1]['No'] = str(i)
            rows[-1]['Unit name'] = unit
        df = _pd.DataFrame(rows, columns=_V265_PLAN_COLS)
        _v265_write_selected_plan(self, df, preserve_visible=False)
        _v265_apply_plan(self)
        _v265_cancel_legacy_after(self)
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v267_gen_busy = False


def _v267_prev_fmoc_record(valid, pos):
    try:
        if pos <= 0: return None, None
        pidx, pr = valid[pos-1]
        pu = str(pr.get('Unit name','')).strip()
        if pu.lower().startswith('fmoc-'):
            return pidx, pr
    except Exception:
        pass
    return None, None


def _v267_add_depro_block(rows, work, depro_count, step, note_target):
    total = work * depro_count
    pip = total * 0.20
    dmf = total * 0.80
    _v265_add_material(rows, 'Piperidine', 'Deprotection base', '', '', '', f'{_v265_s(pip)} mL', f'Step {step}: 20% piperidine/DMF deprotection x{depro_count} before {note_target}', forced_ml=pip)
    _v265_add_material(rows, 'DMF', 'Deprotection solvent', '', '', '', f'{_v265_s(dmf)} mL', f'Step {step}: DMF component of deprotection solution before {note_target}', forced_ml=dmf)
    _v265_add_material(rows, 'DMF', 'Deprotection wash solvent', '', '', '', f'{_v265_s(work*6)} mL', f'Step {step}: DMF wash x6 after deprotection before {note_target}', forced_ml=work*6)


def _v267_materials_df(self):
    import pandas as _pd
    rows = [_v265_resin_row(self)]
    work = _v265_working_ml(self)
    depro_count = max(0, int(round(_v265_f(getattr(self, 'default_depro_count', None), 2))))
    post_count = max(0, int(round(_v265_f(getattr(self, 'default_solvent1_count', None), 2))))
    valid = _v265_plan_records(self)
    if not valid:
        return _pd.DataFrame(rows)
    last_i = valid[-1][0]
    for pos, (idx, r) in enumerate(valid):
        step = str(r.get('No') or idx + 1)
        unit = str(r.get('Unit name','')).strip()
        is_last = (idx == last_i)
        acaa = _v265_is_ac_aa_oh(unit)
        # Normal coupling rows: deprotect their own Fmoc before coupling.
        # Ac-AA-OH row: no Ac-AA deprotection, but the previous Fmoc-AA must be deprotected before this terminal Ac-AA coupling.
        if acaa:
            pidx, pr = _v267_prev_fmoc_record(valid, pos)
            if pr is not None and depro_count:
                pstep = str(pr.get('No') or pidx + 1)
                _v267_add_depro_block(rows, work, depro_count, pstep, f'Ac-AA-OH coupling step {step}')
        else:
            if depro_count:
                _v267_add_depro_block(rows, work, depro_count, step, 'coupling')
        _v265_add_material(rows, unit, 'AA/Chemical', r.get('MW',''), r.get('Density(g/mL)',''), r.get('Unit mmol',''), r.get('Unit amount',''), f'Step {step}: coupling unit')
        _v265_add_material(rows, r.get('Reagent 1',''), 'Coupling reagent', r.get('R1 MW',''), r.get('R1 Density',''), r.get('R1 mmol',''), r.get('R1 amount',''), f'Step {step}: reagent 1')
        _v265_add_material(rows, r.get('Reagent 2 / catalyst',''), 'Catalyst/additive', r.get('R2 MW',''), r.get('R2 Density',''), r.get('R2 mmol',''), r.get('R2 amount',''), f'Step {step}: reagent 2/catalyst')
        _v265_add_material(rows, r.get('Base',''), 'Base', r.get('Base MW',''), r.get('Base Density',''), r.get('Base mmol',''), r.get('Base amount',''), f'Step {step}: base')
        _v265_add_solvent(self, rows, r.get('Coupling solvent',''), r.get('Solvent mL',''), 'Coupling solvent', f'Step {step}: coupling cocktail solvent')
        if is_last:
            # Last Fmoc-AA needs final deprotection; Ac-AA-OH does not. Both receive final DMF/DCM wash.
            if (not acaa) and str(unit).lower().startswith('fmoc-') and depro_count:
                total = work * depro_count
                pip = total * 0.20
                dmf = total * 0.80
                _v265_add_material(rows, 'Piperidine', 'Final deprotection base', '', '', '', f'{_v265_s(pip)} mL', f'After last Fmoc coupling step {step}: 20% piperidine/DMF x{depro_count}', forced_ml=pip)
                _v265_add_material(rows, 'DMF', 'Final deprotection solvent', '', '', '', f'{_v265_s(dmf)} mL', f'After last Fmoc coupling step {step}: DMF component', forced_ml=dmf)
                _v265_add_material(rows, 'DMF', 'Final deprotection wash solvent', '', '', '', f'{_v265_s(work*6)} mL', f'After last Fmoc coupling step {step}: DMF wash x6', forced_ml=work*6)
            _v265_add_material(rows, 'DMF', 'Final wash solvent', '', '', '', f'{_v265_s(work*3)} mL', 'Final wash: DMF x3', forced_ml=work*3)
            _v265_add_material(rows, 'DCM', 'Final wash solvent', '', '', '', f'{_v265_s(work*3)} mL', 'Final wash: DCM x3', forced_ml=work*3)
        else:
            if post_count:
                _v265_add_material(rows, 'DMF', 'Post-coupling wash solvent', '', '', '', f'{_v265_s(work*post_count)} mL', f'Step {step}: DMF wash x{post_count} after coupling', forced_ml=work*post_count)
    return _pd.DataFrame(rows)


def _v267_total_from_materials(mats):
    import pandas as _pd
    if mats is None or len(mats) == 0:
        return _pd.DataFrame(columns=['material','class','MW','Density(g/mL)','total mmol','total amount','note'])
    grouped = []
    for name, grp in mats.groupby('material', sort=False):
        nlow = str(name).strip().lower()
        if nlow == 'dmf':
            cls = 'Reaction solvent 1'
        elif nlow == 'dcm':
            cls = 'Reaction solvent 2'
        else:
            cls = str(grp.iloc[0].get('class',''))
        mw = str(grp.iloc[0].get('MW',''))
        den = str(grp.iloc[0].get('Density(g/mL)',''))
        mmol = sum(_v265_f(x,0) for x in grp.get('_mmol',[]))
        g = sum(_v265_f(x,0) for x in grp.get('_g',[]))
        ml = sum(_v265_f(x,0) for x in grp.get('_mL',[]))
        amount = ''
        if g and ml: amount = f'{_v265_s(g)} g / {_v265_s(ml)} mL'
        elif g: amount = f'{_v265_s(g)} g'
        elif ml: amount = f'{_v265_s(ml)} mL'
        else:
            vals = [str(v) for v in grp.get('total amount',[]) if str(v).strip()]
            amount = '; '.join(vals[:3])
        grouped.append({'material': name, 'class': cls, 'MW': mw, 'Density(g/mL)': den,
                        'total mmol': _v265_s(mmol) if mmol else '', 'total amount': amount,
                        'note': 'Total from ordered Selected Materials'})
    return _pd.DataFrame(grouped)


def _v267_refresh_materials_total(self):
    mats = _v267_materials_df(self)
    show = ['material','class','MW','Density(g/mL)','total mmol','total amount','note']
    try: _v265_write_tree(getattr(self,'pm_selected_material_tree'), mats[show], show)
    except Exception: pass
    total = _v267_total_from_materials(mats)
    try:
        tree = getattr(self,'pm_selected_total_tree',None) or getattr(self,'pm_total_tree',None)
        if tree is not None: _v265_write_tree(tree, total, show)
    except Exception: pass
    return mats, total


def _v267_checklist_df(self):
    import pandas as _pd
    rows = []
    line = 1
    work = _v265_working_ml(self)
    def add(op, unit, next_step='', note=''):
        nonlocal line
        rows.append({'line': line, 'done': 'No', 'checked_at': '', 'operation': op, 'unit': unit, 'next_step': next_step, 'note': note})
        line += 1
    add('Resin swell', str(getattr(self,'pm_resin',_v225_const_var('Resin')).get() if hasattr(self,'pm_resin') else 'Resin'), 'First coupling', f'working volume={_v265_s(work)} mL')
    valid = _v265_plan_records(self)
    last_i = valid[-1][0] if valid else -1
    for pos, (idx, r) in enumerate(valid):
        unit = str(r.get('Unit name','')).strip()
        step = str(r.get('No') or idx + 1)
        acaa = _v265_is_ac_aa_oh(unit)
        is_last = (idx == last_i)
        if acaa:
            pidx, pr = _v267_prev_fmoc_record(valid, pos)
            if pr is not None:
                pstep = str(pr.get('No') or pidx + 1)
                add('Deprotection', str(pr.get('Unit name','')), 'DMF wash after deprotection', f'Step {pstep}: deprotect previous Fmoc-AA before Ac-AA-OH coupling step {step}')
                add('DMF wash after deprotection', str(pr.get('Unit name','')), 'Ac-AA-OH coupling reaction', f'Step {pstep}: DMF wash x6 before Ac-AA-OH coupling step {step}')
        else:
            add('Deprotection', unit, 'DMF wash after deprotection', f'Step {step}: 20% piperidine/DMF x2')
            add('DMF wash after deprotection', unit, 'Coupling reaction', f'Step {step}: DMF wash x6')
        add('Coupling reaction', unit, 'Post-coupling wash or final treatment', f"{r.get('Reagent 1','')} / {r.get('Reagent 2 / catalyst','')} / {r.get('Base','')}; solvent={r.get('Coupling solvent','')} {r.get('Solvent mL','')} mL")
        if is_last:
            if (not acaa) and str(unit).lower().startswith('fmoc-'):
                add('Final deprotection after last Fmoc coupling', unit, 'Final wash', '20% piperidine/DMF x2')
            add('Final wash', unit, 'End', 'DMF x3')
            add('Final wash', unit, 'End', 'DCM x3')
        else:
            add('Post-coupling wash', unit, 'Next cycle', 'DMF wash x2')
    return _pd.DataFrame(rows, columns=['line','done','checked_at','operation','unit','next_step','note'])


def _v267_refresh_checklist(self):
    df = _v267_checklist_df(self)
    for attr in ('progress_tree','pm_selected_check_tree'):
        try:
            tree = getattr(self, attr, None)
            if tree is not None: _v265_write_tree(tree, df, list(df.columns))
        except Exception: pass
    try:
        txt = getattr(self,'pm_selected_check_text',None)
        if txt is not None:
            txt.delete('1.0','end')
            txt.insert('end','\n'.join(f"{r['line']}. {r['operation']} | {r['unit']} | {r['next_step']} | {r['note']}" for _,r in df.iterrows()))
    except Exception: pass
    return df


def _v267_apply_plan(self):
    if getattr(self, '_v267_busy', False): return
    self._v267_busy = True
    try:
        _v265_cancel_legacy_after(self)
        _v265_recalc_visible_plan(self)
        _v267_refresh_materials_total(self)
        _v267_refresh_checklist(self)
        _v265_refresh_batch(self)
        _v265_cancel_legacy_after(self)
        try: self.update_idletasks()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Apply Plan', str(e))
        except Exception: pass
    finally:
        self._v267_busy = False


def _v267_delete_selected_rows(self):
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None: return
    sel = list(tree.selection())
    if not sel: return
    try:
        tree.focus('')
        for iid in sel:
            try: tree.delete(iid)
            except Exception: pass
        _v265_write_selected_plan(self, preserve_visible=True)
        _v267_apply_plan(self)
        try:
            tree.selection_remove(tree.selection())
            tree.update_idletasks()
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass


def _v267_rebind_action_buttons(self):
    try:
        _v265_rebind_action_buttons(self)
    except Exception:
        pass
    seen = {}
    def walk(w):
        for c in list(w.winfo_children()):
            try:
                if isinstance(c, ttk.Button) or isinstance(c, tk.Button):
                    t = str(c.cget('text')).strip()
                    if t == 'Generate / Update':
                        if seen.get(t):
                            try: c.grid_remove() if c.winfo_manager()=='grid' else c.pack_forget()
                            except Exception: pass
                        else:
                            c.configure(command=lambda _self=self: _v267_generate_selected(_self)); seen[t]=1
                    elif t == 'Apply Plan':
                        if seen.get(t):
                            try: c.grid_remove() if c.winfo_manager()=='grid' else c.pack_forget()
                            except Exception: pass
                        else:
                            c.configure(command=lambda _self=self: _v267_apply_plan(_self)); seen[t]=1
                    elif t == 'Delete selected row':
                        if seen.get(t):
                            try: c.grid_remove() if c.winfo_manager()=='grid' else c.pack_forget()
                            except Exception: pass
                        else:
                            c.configure(command=lambda _self=self: _v267_delete_selected_rows(_self)); seen[t]=1
            except Exception: pass
            try: walk(c)
            except Exception: pass
    try: walk(self)
    except Exception: pass


def _v267_after_build(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        def walk_label(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label) and str(c.cget('text')).startswith('SPPS Planner'):
                        c.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
                except Exception: pass
                try: walk_label(c)
                except Exception: pass
        walk_label(self)
    except Exception: pass
    try: _v267_rebind_action_buttons(self)
    except Exception: pass
    try: _v265_patch_entry_editing(self)
    except Exception: pass
    try: _v265_ensure_resin_loading_editor(self)
    except Exception: pass
    try:
        if hasattr(self,'pm_list'):
            self.pm_list.bind('<<ListboxSelect>>', lambda e, _self=self: _v265_fast_pm_on_select(_self, e))
            self.pm_list.bind('<Double-Button-1>', lambda e, _self=self: _v265_fast_pm_on_double_click(_self, e))
            self.pm_list.bind('<Return>', lambda e, _self=self: _v265_fast_pm_on_double_click(_self, e))
    except Exception: pass
    try: _v265_cancel_legacy_after(self)
    except Exception: pass

