# ======================= V2.0.68 FEATURE RESTORE + STABILITY FIX =======================
# Goal: keep the working v2.0.67 chemistry/calculation path, but restore UI functions
# that became hidden by global de-duplication (Load Project, Delete selected row, etc.).
# This patch is deliberately additive and scoped: it does not remove user-facing working
# UI features unless a replacement button/command is installed in the same visible area.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v268_walk_widgets(root):
    try:
        children = list(root.winfo_children())
    except Exception:
        return
    for ch in children:
        yield ch
        try:
            yield from _v268_walk_widgets(ch)
        except Exception:
            pass


def _v268_btn_text(btn):
    try:
        return str(btn.cget('text')).strip()
    except Exception:
        return ''


def _v268_is_button(w):
    try:
        return isinstance(w, ttk.Button) or isinstance(w, tk.Button)
    except Exception:
        return False


def _v268_hide_button(btn):
    try:
        mgr = btn.winfo_manager()
        if mgr == 'grid':
            btn.grid_remove()
        elif mgr == 'pack':
            btn.pack_forget()
        elif mgr == 'place':
            btn.place_forget()
    except Exception:
        pass


def _v268_pack_button(btn, **kw):
    try:
        if btn.winfo_manager() == 'grid':
            return
    except Exception:
        pass
    try:
        btn.pack(**kw)
    except Exception:
        try:
            btn.pack(side='left', padx=3)
        except Exception:
            pass


def _v268_button_command(self, text):
    if text == 'Generate / Update':
        return lambda _self=self: _v267_generate_selected(_self)
    if text == 'Apply Plan':
        return lambda _self=self: _v267_apply_plan(_self)
    if text == 'Delete selected row':
        return lambda _self=self: _v267_delete_selected_rows(_self)
    if text == 'Load Project':
        if '_v257_load_project' in globals():
            return lambda _self=self: _v257_load_project(_self)
        return lambda _self=self: _self.load_project()
    if text == 'Import Output':
        return getattr(self, 'load_output_folder', None)
    if text == 'Export':
        return getattr(self, 'export_outputs', None)
    if text == 'Show setup':
        return getattr(self, 'toggle_setup_panel', None)
    if text == 'Use DIC/HOBt':
        return getattr(self, 'apply_dic_hobt_preset', None)
    if text == 'Use HBTU/NMP 10eq':
        return getattr(self, 'apply_hbtu_nmp_preset', None)
    return None


def _v268_find_visible_button(self, text, parent_filter=None):
    for w in _v268_walk_widgets(self):
        if _v268_is_button(w) and _v268_btn_text(w) == text:
            try:
                if parent_filter is not None and not parent_filter(w):
                    continue
            except Exception:
                pass
            try:
                if w.winfo_ismapped():
                    return w
            except Exception:
                pass
    return None


def _v268_find_buttons(self, text):
    out = []
    for w in _v268_walk_widgets(self):
        if _v268_is_button(w) and _v268_btn_text(w) == text:
            out.append(w)
    return out


def _v268_is_under_selected_plan(widget):
    # Identify the Selected Plan area by walking from the plan tree upward.
    try:
        tree = getattr(widget.winfo_toplevel(), 'pm_selected_plan_tree', None)
    except Exception:
        tree = None
    if tree is None:
        return False
    try:
        ancestors = set()
        w = tree
        while w is not None:
            ancestors.add(str(w))
            w = w.master
        w = widget
        while w is not None:
            if str(w) in ancestors:
                return True
            w = w.master
    except Exception:
        pass
    return False


def _v268_selected_plan_toolbar(self):
    # Prefer the visible Apply Plan toolbar already created in the Selected Plan tab.
    for w in _v268_walk_widgets(self):
        if _v268_is_button(w) and _v268_btn_text(w) == 'Apply Plan':
            try:
                if w.winfo_ismapped() and _v268_is_under_selected_plan(w):
                    return w.master
            except Exception:
                pass
    # Fallback: use parent of existing Edit Unit name or tree's parent; create a toolbar if needed.
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None:
        return None
    parent = getattr(tree, 'master', None)
    if parent is None:
        return None
    try:
        bar = ttk.Frame(parent)
        # the tree helper usually packs children; put toolbar before the tree if possible.
        try:
            bar.pack(side='top', fill='x', pady=(0,2), before=tree)
        except Exception:
            bar.pack(side='top', fill='x', pady=(0,2))
        return bar
    except Exception:
        return parent


def _v268_restore_selected_plan_buttons(self):
    bar = _v268_selected_plan_toolbar(self)
    if bar is None:
        return
    wanted = ['Apply Plan', 'Delete selected row', 'Edit Unit name']
    existing = {t: [] for t in wanted}
    for w in _v268_walk_widgets(self):
        if _v268_is_button(w):
            t = _v268_btn_text(w)
            if t in existing:
                existing[t].append(w)
    # Install exactly one mapped button for each wanted command in the Selected Plan toolbar.
    for text in wanted:
        btn = None
        # First reuse a button already in the toolbar.
        for b in existing.get(text, []):
            if getattr(b, 'master', None) is bar:
                btn = b; break
        # Then reuse any hidden existing button by moving/packing it in the toolbar only if possible.
        if btn is None:
            for b in existing.get(text, []):
                try:
                    if b.master is bar:
                        btn = b; break
                except Exception:
                    pass
        # Else create a replacement.
        if btn is None:
            try:
                if text == 'Edit Unit name':
                    cmd = getattr(self, 'pm_edit_selected_unit_name', None) or getattr(self, 'pm_edit_unit_name', None)
                    if cmd is None:
                        cmd = lambda _self=self: None
                else:
                    cmd = _v268_button_command(self, text)
                btn = ttk.Button(bar, text=text, command=cmd)
            except Exception:
                continue
        cmd = _v268_button_command(self, text)
        if text == 'Edit Unit name':
            cmd = getattr(self, 'pm_edit_selected_unit_name', None) or getattr(self, 'pm_edit_unit_name', None) or cmd
        try:
            if cmd is not None:
                btn.configure(command=cmd)
        except Exception:
            pass
        try:
            if not btn.winfo_ismapped():
                _v268_pack_button(btn, side='left', padx=3)
        except Exception:
            pass
    # Hide duplicate Selected Plan action buttons outside the toolbar, but do not touch old standalone app controls.
    for text in wanted:
        primary = None
        for b in _v268_find_buttons(self, text):
            if getattr(b, 'master', None) is bar:
                primary = b; break
        for b in _v268_find_buttons(self, text):
            if b is primary:
                continue
            if _v268_is_under_selected_plan(b):
                _v268_hide_button(b)


def _v268_restore_global_actions(self):
    # The selected-peptide editor must expose all global action buttons, especially Load Project.
    # Find the visible global action row by looking for Import Output/Export/Show setup.
    visible_import = _v268_find_visible_button(self, 'Import Output')
    visible_export = _v268_find_visible_button(self, 'Export')
    visible_setup = _v268_find_visible_button(self, 'Show setup')
    row = None
    for b in (visible_import, visible_export, visible_setup):
        if b is not None:
            row = b.master; break
    if row is None:
        return
    order = ['Use DIC/HOBt', 'Use HBTU/NMP 10eq', 'Load Project', 'Import Output', 'Export', 'Show setup']
    # Make a visible button per command in this row. Do not globally hide same text elsewhere.
    row_buttons = { _v268_btn_text(c): c for c in row.winfo_children() if _v268_is_button(c) }
    for text in order:
        btn = row_buttons.get(text)
        if btn is None:
            try:
                cmd = _v268_button_command(self, text)
                btn = ttk.Button(row, text=text, command=cmd)
                # Insert Load Project before Import Output if possible.
                if text == 'Load Project' and visible_import is not None:
                    try: btn.pack(side='left', padx=3, before=visible_import)
                    except Exception: btn.pack(side='left', padx=3)
                else:
                    btn.pack(side='left', padx=3)
            except Exception:
                continue
        else:
            try:
                cmd = _v268_button_command(self, text)
                if cmd is not None:
                    btn.configure(command=cmd)
            except Exception:
                pass
            try:
                if not btn.winfo_ismapped():
                    _v268_pack_button(btn, side='left', padx=3)
            except Exception:
                pass


def _v268_fix_rebind_without_global_hiding(self):
    # Rebind commands while avoiding the old global seen-dict de-duplication that hid valid buttons.
    for w in _v268_walk_widgets(self):
        if not _v268_is_button(w):
            continue
        t = _v268_btn_text(w)
        cmd = _v268_button_command(self, t)
        if cmd is not None:
            try:
                w.configure(command=cmd)
            except Exception:
                pass
    _v268_restore_global_actions(self)
    _v268_restore_selected_plan_buttons(self)


def _v268_feature_audit(self):
    # Store a lightweight, user-facing-auditable summary for debugging without adding UI clutter.
    try:
        visible_buttons = []
        tabs = []
        for w in _v268_walk_widgets(self):
            if _v268_is_button(w):
                try:
                    if w.winfo_ismapped():
                        visible_buttons.append(_v268_btn_text(w))
                except Exception:
                    pass
            try:
                if isinstance(w, ttk.Notebook):
                    tabs.append([w.tab(t, 'text') for t in w.tabs()])
            except Exception:
                pass
        self._v268_feature_audit = {'visible_buttons': visible_buttons, 'notebooks': tabs}
    except Exception:
        self._v268_feature_audit = {'error': 'audit failed'}


def _v268_after_build(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        for w in _v268_walk_widgets(self):
            try:
                if isinstance(w, ttk.Label) and str(w.cget('text')).startswith('SPPS Planner'):
                    w.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
            except Exception:
                pass
    except Exception:
        pass
    try: _v265_cancel_legacy_after(self)
    except Exception: pass
    try: _v268_fix_rebind_without_global_hiding(self)
    except Exception: pass
    try: _v265_patch_entry_editing(self)
    except Exception: pass
    try: _v265_ensure_resin_loading_editor(self)
    except Exception: pass
    # Run once more after geometry settles; this restores buttons if older after_idle code hid them.
    try: self.after_idle(lambda _self=self: (_v268_fix_rebind_without_global_hiding(_self), _v268_feature_audit(_self)))
    except Exception: pass
    try: _v268_feature_audit(self)
    except Exception: pass


# Final routing for v2.0.68.
