# ======================= V2.0.69 SMOOTH PM + PROTOCOL + DROPDOWN FIX =======================
# User-facing fixes:
# - Peptide items listbox reliably loads the selected item into the right editor on select/double-click.
# - Remove delayed legacy rescue callbacks that caused visible input/tab delay.
# - Entry editing now replaces selected text instead of prepending/appending (Batch Manager AA eq: 2 -> 5, not 52).
# - Selected Plan Unit name combobox opens on the first double-click and cleans up when canceled.
# - Terminal protocol corrected:
#   Fmoc-AA-OH last: depro x2 -> DMF wash x6 -> coupling -> DMF wash x2 -> final depro x2 -> DMF wash x3 -> DCM wash x3.
#   Ac-AA-OH / chemical / tag last: depro x2 -> DMF wash x6 -> coupling -> DMF wash x3 -> DCM wash x3.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v269_cancel_pending_after(self):
    """Cancel legacy delayed redraw/rescue callbacks once the final UI is wired."""
    try:
        ids = self.tk.call('after', 'info')
        if isinstance(ids, str):
            ids = ids.split()
        for aid in list(ids):
            try: self.after_cancel(aid)
            except Exception: pass
    except Exception:
        pass


def _v269_set_title(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        def walk(w):
            for c in list(w.winfo_children()):
                try:
                    if isinstance(c, ttk.Label) and str(c.cget('text')).startswith('SPPS Planner'):
                        c.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
                except Exception: pass
                try: walk(c)
                except Exception: pass
        walk(self)
    except Exception: pass


def _v269_is_button(w):
    try: return isinstance(w, (ttk.Button, tk.Button))
    except Exception: return False


def _v269_button_text(w):
    try: return str(w.cget('text')).strip()
    except Exception: return ''


def _v269_walk(w):
    try: children = list(w.winfo_children())
    except Exception: children = []
    for c in children:
        yield c
        yield from _v269_walk(c)


def _v269_pm_select_current(self, event=None):
    """Fast, reliable item selection: editor load only, no generate and no heavy batch refresh."""
    try:
        idx = self.pm_current_index() if hasattr(self, 'pm_current_index') else None
    except Exception:
        idx = None
    if idx is None:
        return 'break' if event is not None and str(getattr(event, 'type', '')) else None
    try:
        # Do not call pm_live_sync_selected here: after Listbox selection changes, it can save the
        # old editor into the newly selected item. Explicit Generate/Save/Add/Duplicate still sync.
        self.pm_load_to_editor(idx)
        self._v269_active_pm_index = idx
        try: self.pm_update_summary()
        except Exception: pass
    except Exception:
        pass
    return 'break' if event is not None and getattr(event, 'num', None) == 1 else None


def _v269_pm_double_click(self, event=None):
    _v269_pm_select_current(self, event)
    return 'break'


def _v269_refresh_pm_list_fast(self, select_idx=None):
    try:
        if not hasattr(self, 'pm_list'): return
        old_y = self.pm_list.yview()
        self.pm_list.delete(0, 'end')
        for item in list(getattr(self, 'pm_items', []) or []):
            try: name = self.pm_display_name(item)
            except Exception: name = f"{item.get('project','')} | {item.get('peptide','')}"
            self.pm_list.insert('end', name)
        if getattr(self, 'pm_items', []):
            if select_idx is None:
                try: select_idx = self._v269_active_pm_index
                except Exception: select_idx = 0
            select_idx = max(0, min(int(select_idx or 0), len(self.pm_items)-1))
            self.pm_list.selection_clear(0, 'end')
            self.pm_list.selection_set(select_idx)
            self.pm_list.activate(select_idx)
            self.pm_list.see(select_idx)
            self.pm_load_to_editor(select_idx)
            self._v269_active_pm_index = select_idx
        try: self.pm_update_summary()
        except Exception: pass
    except Exception:
        try: self.pm_refresh_list(keep_index=select_idx if select_idx is not None else 0, reload_editor=True)
        except Exception: pass


def _v269_pm_add_peptide(self, item=None):
    if not hasattr(self, 'pm_items'):
        self.pm_items = []
    try: _v266_save_editor_to_current_item(self)
    except Exception: pass
    n = len(self.pm_items) + 1
    if item is None:
        try: base = _v266_current_editor_snapshot(self)
        except Exception:
            base = {'project': f'Project-{n:03d}', 'peptide': f'Peptide-{n:03d}', 'sequence': '', 'copies': '1', 'scale': '0.2', 'resin': 'Rink Amide AM', 'loading': '0.8', 'chemistry': 'DIC/HOBt'}
        try: base['project'] = _v266_unique_name(self.pm_items, f'Project-{n:03d}', 'project')
        except Exception: base['project'] = f'Project-{n:03d}'
        try: base['peptide'] = _v266_unique_name(self.pm_items, f'Peptide-{n:03d}', 'peptide')
        except Exception: base['peptide'] = f'Peptide-{n:03d}'
        base['sequence'] = ''
        try: base['lot'] = _v266_make_lot(self, n)
        except Exception: base['lot'] = f'SPPS-{n:03d}'
        item = base
    self.pm_items.append(dict(item))
    _v269_refresh_pm_list_fast(self, len(self.pm_items)-1)
    try: self.schedule_autosave()
    except Exception: pass


def _v269_pm_duplicate_peptide(self):
    if not hasattr(self, 'pm_items'):
        self.pm_items = []
    try: idx = _v266_save_editor_to_current_item(self)
    except Exception: idx = None
    if idx is None:
        try: idx = self.pm_current_index()
        except Exception: idx = None
    if idx is None or idx < 0 or idx >= len(self.pm_items):
        return
    item = dict(self.pm_items[idx])
    try: item['project'] = _v266_unique_name(self.pm_items, str(item.get('project','Project')) + '_copy', 'project')
    except Exception: item['project'] = str(item.get('project','Project')) + '_copy'
    try: item['peptide'] = _v266_unique_name(self.pm_items, str(item.get('peptide','Peptide')) + '_copy', 'peptide')
    except Exception: item['peptide'] = str(item.get('peptide','Peptide')) + '_copy'
    try: item['lot'] = _v266_make_lot(self, len(self.pm_items)+1)
    except Exception: pass
    self.pm_items.append(item)
    _v269_refresh_pm_list_fast(self, len(self.pm_items)-1)
    try: self.schedule_autosave()
    except Exception: pass


def _v269_pm_delete_peptide(self):
    try: idx = self.pm_current_index()
    except Exception: idx = None
    if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
        return
    try: del self.pm_items[idx]
    except Exception: return
    if not getattr(self, 'pm_items', []):
        _v269_pm_add_peptide(self)
        return
    _v269_refresh_pm_list_fast(self, min(idx, len(self.pm_items)-1))
    try: self.schedule_autosave()
    except Exception: pass


def _v269_patch_pm_list(self):
    try:
        if hasattr(self, 'pm_list'):
            self.pm_list.bind('<<ListboxSelect>>', lambda e, _self=self: _v269_pm_select_current(_self, e), add=False)
            self.pm_list.bind('<Double-Button-1>', lambda e, _self=self: _v269_pm_double_click(_self, e), add=False)
            self.pm_list.bind('<Return>', lambda e, _self=self: _v269_pm_double_click(_self, e), add=False)
            try: self._v269_active_pm_index = self.pm_current_index() or 0
            except Exception: self._v269_active_pm_index = 0
    except Exception:
        pass


def _v269_entry_select_all(event):
    try:
        w = event.widget
        w.focus_set()
        def select_all(_w=w):
            try:
                _w.selection_range(0, 'end')
                _w.icursor('end')
            except Exception:
                pass
        # FocusIn can be immediate; double-click runs once after Tk's own selection behavior.
        if str(getattr(event, 'type', '')) == '9':
            select_all()
        else:
            try: w.after_idle(select_all)
            except Exception: select_all()
    except Exception:
        pass
    return None


def _v269_entry_key_replace(event):
    try:
        w = event.widget
        ks = str(getattr(event, 'keysym', ''))
        # Delete selected text explicitly.
        if ks in ('BackSpace', 'Delete'):
            try:
                if w.selection_present():
                    w.delete('sel.first', 'sel.last')
                    return 'break'
            except Exception: pass
            return None
        # Printable key replaces the current selected text. This fixes Batch Manager 2 -> 5 becoming 52.
        if getattr(event, 'char', '') and len(event.char) == 1 and event.char.isprintable():
            try:
                if w.selection_present():
                    w.delete('sel.first', 'sel.last')
                    w.insert('insert', event.char)
                    return 'break'
            except Exception: pass
    except Exception:
        pass
    return None


def _v269_patch_entry_editing(self):
    try:
        for w in _v269_walk(self):
            try:
                if isinstance(w, (ttk.Entry, tk.Entry)):
                    w.bind('<Double-Button-1>', _v269_entry_select_all, add=False)
                    w.bind('<FocusIn>', _v269_entry_select_all, add=True)
                    w.bind('<KeyPress>', _v269_entry_key_replace, add=False)
            except Exception: pass
    except Exception:
        pass


def _v269_editabletree_begin_edit(tree, event):
    try:
        if tree.identify('region', event.x, event.y) != 'cell':
            return 'break'
        row_id = tree.identify_row(event.y)
        col_id = tree.identify_column(event.x)
        if not row_id or not col_id:
            return 'break'
        col_index = int(str(col_id).replace('#','')) - 1
        cols = list(tree['columns'])
        if col_index < 0 or col_index >= len(cols):
            return 'break'
        col_name = cols[col_index]
        if col_name in {'No', 'line'}:
            return 'break'
        bbox = tree.bbox(row_id, col_id)
        if not bbox:
            return 'break'
        x, y, w, h = bbox
        vals = list(tree.item(row_id, 'values'))
        vals += [''] * max(0, len(cols)-len(vals))
        old = str(vals[col_index])
        try:
            ed = getattr(tree, '_edit_entry', None) or getattr(tree, '_v269_editor', None)
            if ed is not None and ed.winfo_exists(): ed.destroy()
        except Exception: pass
        choices = getattr(tree, '_combo_values', {}).get(col_name)
        if choices:
            ed = ttk.Combobox(tree, values=list(choices), state='normal')
            try: bind_combobox_first_letter_jump(ed)
            except Exception: pass
            ed.set(old)
            is_combo = True
        else:
            ed = ttk.Entry(tree)
            ed.insert(0, old)
            is_combo = False
        ed.place(x=x, y=y, width=max(w, 260 if col_name == 'Unit name' else w), height=h+3)
        ed.focus_set()
        try: ed.select_range(0, 'end'); ed.icursor('end')
        except Exception: pass
        tree._edit_entry = ed
        tree._v269_editor = ed
        done = {'v': False}
        def cleanup():
            try:
                if ed.winfo_exists(): ed.destroy()
            except Exception: pass
            try:
                if getattr(tree, '_edit_entry', None) is ed: tree._edit_entry = None
                if getattr(tree, '_v269_editor', None) is ed: tree._v269_editor = None
            except Exception: pass
        def commit(_event=None):
            if done['v']: return 'break'
            done['v'] = True
            try:
                new = ed.get()
                vals2 = list(tree.item(row_id, 'values'))
                vals2 += [''] * max(0, len(cols)-len(vals2))
                vals2[col_index] = new
                tree.item(row_id, values=vals2)
                try:
                    cb = getattr(tree, '_on_edit', None)
                    if cb: cb(row_id, col_name, new)
                except Exception: pass
            finally:
                cleanup()
            return 'break'
        def cancel(_event=None):
            if done['v']: return 'break'
            done['v'] = True
            cleanup()
            return 'break'
        def focus_out(_event=None):
            def later():
                if done['v']: return
                try: cur = ed.get()
                except Exception: cur = old
                if is_combo and str(cur) == old:
                    cancel()
                else:
                    commit()
            try: ed.after(250, later)
            except Exception: later()
            return None
        ed.bind('<Return>', commit, add=False)
        ed.bind('<Escape>', cancel, add=False)
        ed.bind('<FocusOut>', focus_out, add=False)
        ed.bind('<KeyPress>', _v269_entry_key_replace, add=False)
        ed.bind('<Control-a>', lambda e: (ed.select_range(0,'end'), ed.icursor('end'), 'break'), add=False)
        if is_combo:
            ed.bind('<<ComboboxSelected>>', commit, add=False)
            def post():
                if done['v']: return
                try:
                    ed.focus_set()
                    ed.tk.call('ttk::combobox::Post', ed)
                except Exception:
                    try: ed.event_generate('<Alt-Down>')
                    except Exception: pass
            try: ed.after(20, post)
            except Exception: pass
        return 'break'
    except Exception:
        return 'break'


def _v269_selected_plan_options(self, col):
    try: return _v251_options_for_col(self, col)
    except Exception:
        if col == 'Unit name':
            vals = []
            for name in ('UNIT_OPTIONS','unit_options','AA_OPTIONS'):
                try: vals += list(getattr(self, name))
                except Exception: pass
            if vals: return vals
        if col == 'Reagent 1': return list(getattr(self, 'REAGENT_VALUES', []))
        if col == 'Reagent 2 / catalyst': return list(getattr(self, 'CATALYST_VALUES', []))
        if col == 'Base': return list(getattr(self, 'BASE_VALUES', []))
        if col == 'Coupling solvent': return list(getattr(self, 'SOLVENT_VALUES', []))
    return []


def _v269_selected_plan_edit(self, event):
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None: return 'break'
    try:
        if tree.identify('region', event.x, event.y) != 'cell': return 'break'
        row_id = tree.identify_row(event.y); col_id = tree.identify_column(event.x)
        if not row_id or not col_id: return 'break'
        idx = int(str(col_id).replace('#','')) - 1
        cols = list(tree['columns'])
        if idx < 0 or idx >= len(cols): return 'break'
        col = cols[idx]
        if col in {'No'}: return 'break'
        bbox = tree.bbox(row_id, col_id)
        if not bbox: return 'break'
        x,y,w,h = bbox
        vals = list(tree.item(row_id,'values')); vals += [''] * max(0, len(cols)-len(vals))
        old = str(vals[idx])
        try:
            ed = getattr(tree, '_v269_editor', None) or getattr(tree, '_v254_editor', None)
            if ed is not None and ed.winfo_exists(): ed.destroy()
        except Exception: pass
        dropdown_cols = {'Unit name','Reagent 1','Reagent 2 / catalyst','Base','Coupling solvent'}
        text_cols = {'MW','Density(g/mL)','Unit mmol','Unit amount','R1 MW','R1 Density','R1 mmol','R1 amount','R2 MW','R2 Density','R2 mmol','R2 amount','Base MW','Base Density','Base mmol','Base amount','Solvent mL','Repeat','Note'}
        if col in dropdown_cols:
            ed = ttk.Combobox(tree, values=_v269_selected_plan_options(self, col), state='normal')
            try: bind_combobox_first_letter_jump(ed)
            except Exception: pass
            ed.set(old); is_combo = True
        elif col in text_cols:
            ed = ttk.Entry(tree); ed.insert(0, old); is_combo = False
        else:
            return 'break'
        ed.place(x=x, y=y, width=max(w, 300 if col=='Unit name' else 180), height=h+4)
        ed.focus_set()
        try: ed.select_range(0,'end'); ed.icursor('end')
        except Exception: pass
        tree._v269_editor = ed
        tree._v254_editor = ed
        done = {'v': False}
        def cleanup():
            try:
                if ed.winfo_exists(): ed.destroy()
            except Exception: pass
            try:
                if getattr(tree, '_v269_editor', None) is ed: tree._v269_editor = None
                if getattr(tree, '_v254_editor', None) is ed: tree._v254_editor = None
            except Exception: pass
        def commit(_event=None):
            if done['v']: return 'break'
            done['v'] = True
            try:
                new = ed.get()
                try:
                    if col in dropdown_cols and '_v251_canon' in globals():
                        new = _v251_canon(new)
                except Exception: pass
                vals2 = list(tree.item(row_id,'values')); vals2 += [''] * max(0, len(cols)-len(vals2))
                vals2[idx] = new
                tree.item(row_id, values=vals2)
                try:
                    _v265_recalc_visible_plan(self)
                except Exception: pass
            finally:
                cleanup()
            return 'break'
        def cancel(_event=None):
            if done['v']: return 'break'
            done['v'] = True
            cleanup()
            return 'break'
        def focus_out(_event=None):
            def later():
                if done['v']: return
                try: cur = ed.get()
                except Exception: cur = old
                if is_combo and str(cur) == old:
                    cancel()
                else:
                    commit()
            try: ed.after(250, later)
            except Exception: later()
            return None
        ed.bind('<Return>', commit, add=False)
        ed.bind('<Escape>', cancel, add=False)
        ed.bind('<FocusOut>', focus_out, add=False)
        ed.bind('<KeyPress>', _v269_entry_key_replace, add=False)
        ed.bind('<Control-a>', lambda e: (ed.select_range(0,'end'), ed.icursor('end'), 'break'), add=False)
        if is_combo:
            ed.bind('<<ComboboxSelected>>', commit, add=False)
            def post():
                if done['v']: return
                try:
                    ed.focus_set()
                    ed.tk.call('ttk::combobox::Post', ed)
                except Exception:
                    try: ed.event_generate('<Alt-Down>')
                    except Exception: pass
            try: ed.after(20, post)
            except Exception: pass
        return 'break'
    except Exception:
        return 'break'


def _v269_bind_selected_plan_editor(self):
    try:
        tree = getattr(self, 'pm_selected_plan_tree', None)
        if tree is None: return
        tree.bind('<Double-1>', lambda e, _self=self: _v269_selected_plan_edit(_self, e), add=False)
        # Do not keep older Button-1 handlers that destroy the first combobox before it can post.
        tree.bind('<Button-1>', lambda e: None, add=False)
    except Exception:
        pass


def _v269_pre_depro_rows(rows, work, depro_count, step, target_note):
    total = work * depro_count
    pip = total * 0.20
    dmf = total * 0.80
    _v265_add_material(rows, 'Piperidine', 'Deprotection base', '', '', '', f'{_v265_s(pip)} mL', f'Step {step}: 20% piperidine/DMF deprotection x{depro_count} before {target_note}', forced_ml=pip)
    _v265_add_material(rows, 'DMF', 'Deprotection solvent', '', '', '', f'{_v265_s(dmf)} mL', f'Step {step}: DMF component of deprotection solution before {target_note}', forced_ml=dmf)
    _v265_add_material(rows, 'DMF', 'Deprotection wash solvent', '', '', '', f'{_v265_s(work*6)} mL', f'Step {step}: DMF wash x6 after deprotection before {target_note}', forced_ml=work*6)


def _v269_materials_df(self):
    import pandas as _pd
    rows = [_v265_resin_row(self)]
    work = _v265_working_ml(self)
    depro_count = max(0, int(round(_v265_f(getattr(self, 'default_depro_count', None), 2))))
    post_count = max(0, int(round(_v265_f(getattr(self, 'default_solvent1_count', None), 2))))
    valid = _v265_plan_records(self)
    if not valid:
        return _pd.DataFrame(rows)
    last_i = valid[-1][0]
    for pos, (idx, r) in enumerate(valid):
        step = str(r.get('No') or idx + 1)
        unit = str(r.get('Unit name','')).strip()
        if not unit: continue
        is_last = (idx == last_i)
        acaa = _v265_is_ac_aa_oh(unit)
        is_fmoc = unit.lower().startswith('fmoc-')
        # Pre-coupling deprotection: for Ac-AA-OH this is the previous Fmoc-AA deprotection, not Ac-AA itself.
        if depro_count:
            if acaa:
                try: pidx, pr = _v267_prev_fmoc_record(valid, pos)
                except Exception: pidx, pr = (None, None)
                if pr is not None:
                    pstep = str(pr.get('No') or (pidx + 1))
                    _v269_pre_depro_rows(rows, work, depro_count, pstep, f'Ac-AA-OH coupling step {step}')
            else:
                _v269_pre_depro_rows(rows, work, depro_count, step, 'coupling')
        _v265_add_material(rows, unit, 'AA/Chemical', r.get('MW',''), r.get('Density(g/mL)',''), r.get('Unit mmol',''), r.get('Unit amount',''), f'Step {step}: coupling unit')
        _v265_add_material(rows, r.get('Reagent 1',''), 'Coupling reagent', r.get('R1 MW',''), r.get('R1 Density',''), r.get('R1 mmol',''), r.get('R1 amount',''), f'Step {step}: reagent 1')
        _v265_add_material(rows, r.get('Reagent 2 / catalyst',''), 'Catalyst/additive', r.get('R2 MW',''), r.get('R2 Density',''), r.get('R2 mmol',''), r.get('R2 amount',''), f'Step {step}: reagent 2/catalyst')
        _v265_add_material(rows, r.get('Base',''), 'Base', r.get('Base MW',''), r.get('Base Density',''), r.get('Base mmol',''), r.get('Base amount',''), f'Step {step}: base')
        _v265_add_solvent(self, rows, r.get('Coupling solvent',''), r.get('Solvent mL',''), 'Coupling solvent', f'Step {step}: coupling cocktail solvent')
        if is_last:
            if is_fmoc:
                if post_count:
                    _v265_add_material(rows, 'DMF', 'Post-coupling wash solvent', '', '', '', f'{_v265_s(work*post_count)} mL', f'Step {step}: DMF wash x{post_count} after last Fmoc coupling before final deprotection', forced_ml=work*post_count)
                if depro_count:
                    total = work * depro_count
                    pip = total * 0.20
                    dmf = total * 0.80
                    _v265_add_material(rows, 'Piperidine', 'Final deprotection base', '', '', '', f'{_v265_s(pip)} mL', f'After last Fmoc coupling step {step}: 20% piperidine/DMF x{depro_count}', forced_ml=pip)
                    _v265_add_material(rows, 'DMF', 'Final deprotection solvent', '', '', '', f'{_v265_s(dmf)} mL', f'After last Fmoc coupling step {step}: DMF component', forced_ml=dmf)
            # For Fmoc final and Ac-AA/chemical/tag final, finish with DMF x3 + DCM x3.
            _v265_add_material(rows, 'DMF', 'Final wash solvent', '', '', '', f'{_v265_s(work*3)} mL', 'Final wash: DMF x3', forced_ml=work*3)
            _v265_add_material(rows, 'DCM', 'Final wash solvent', '', '', '', f'{_v265_s(work*3)} mL', 'Final wash: DCM x3', forced_ml=work*3)
        else:
            if post_count:
                _v265_add_material(rows, 'DMF', 'Post-coupling wash solvent', '', '', '', f'{_v265_s(work*post_count)} mL', f'Step {step}: DMF wash x{post_count} after coupling', forced_ml=work*post_count)
    return _pd.DataFrame(rows)


def _v269_total_from_materials(mats):
    # Keep v2.0.67 solvent class labels in Total Materials.
    return _v267_total_from_materials(mats)


def _v269_refresh_materials_total(self):
    mats = _v269_materials_df(self)
    show = ['material','class','MW','Density(g/mL)','total mmol','total amount','note']
    try: _v265_write_tree(getattr(self, 'pm_selected_material_tree'), mats[show], show)
    except Exception: pass
    total = _v269_total_from_materials(mats)
    try:
        tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        if tree is not None: _v265_write_tree(tree, total, show)
    except Exception: pass
    return mats, total


def _v269_checklist_df(self):
    import pandas as _pd
    rows = []
    line = 1
    def add(op, unit, next_step='', note=''):
        nonlocal line
        rows.append({'line': line, 'done': 'No', 'checked_at': '', 'operation': op, 'unit': unit, 'next_step': next_step, 'note': note})
        line += 1
    try: resin_name = str(self.pm_resin.get())
    except Exception: resin_name = 'Resin'
    add('Resin swell', resin_name, 'First deprotection/coupling', 'Prepare resin before synthesis')
    valid = _v265_plan_records(self)
    if not valid:
        return _pd.DataFrame(rows, columns=['line','done','checked_at','operation','unit','next_step','note'])
    last_i = valid[-1][0]
    for pos, (idx, r) in enumerate(valid):
        unit = str(r.get('Unit name','')).strip()
        step = str(r.get('No') or idx + 1)
        acaa = _v265_is_ac_aa_oh(unit)
        is_fmoc = unit.lower().startswith('fmoc-')
        is_last = (idx == last_i)
        if acaa:
            try: pidx, pr = _v267_prev_fmoc_record(valid, pos)
            except Exception: pidx, pr = (None, None)
            if pr is not None:
                punit = str(pr.get('Unit name',''))
                pstep = str(pr.get('No') or (pidx + 1))
                add('Deprotection', punit, 'DMF wash after deprotection', f'Step {pstep}: 20% piperidine/DMF x2 before Ac-AA-OH coupling step {step}')
                add('DMF wash after deprotection', punit, 'Ac-AA-OH coupling', f'Step {pstep}: DMF wash x6 before Ac-AA-OH coupling step {step}')
        else:
            add('Deprotection', unit, 'DMF wash after deprotection', f'Step {step}: 20% piperidine/DMF x2')
            add('DMF wash after deprotection', unit, 'Coupling reaction', f'Step {step}: DMF wash x6')
        add('Coupling reaction', unit, 'Wash/final treatment', f"{r.get('Reagent 1','')} / {r.get('Reagent 2 / catalyst','')} / {r.get('Base','')}; solvent={r.get('Coupling solvent','')} {r.get('Solvent mL','')} mL")
        if is_last:
            if is_fmoc:
                add('DMF wash after last Fmoc coupling', unit, 'Final deprotection', 'DMF wash x2')
                add('Final deprotection after last Fmoc coupling', unit, 'Final wash', '20% piperidine/DMF x2')
            add('Final wash', unit, 'End', 'DMF x3')
            add('Final wash', unit, 'End', 'DCM x3')
        else:
            add('Post-coupling wash', unit, 'Next cycle', 'DMF wash x2')
    return _pd.DataFrame(rows, columns=['line','done','checked_at','operation','unit','next_step','note'])


def _v269_refresh_checklist(self):
    df = _v269_checklist_df(self)
    for attr in ('progress_tree','pm_selected_check_tree'):
        try:
            tree = getattr(self, attr, None)
            if tree is not None: _v265_write_tree(tree, df, list(df.columns))
        except Exception: pass
    try:
        txt = getattr(self, 'pm_selected_check_text', None)
        if txt is not None:
            txt.delete('1.0','end')
            txt.insert('end', '\n'.join(f"{r['line']}. {r['operation']} | {r['unit']} | {r['next_step']} | {r['note']}" for _, r in df.iterrows()))
    except Exception: pass
    return df


def _v269_apply_plan(self):
    if getattr(self, '_v269_apply_busy', False): return
    self._v269_apply_busy = True
    try:
        _v269_cancel_pending_after(self)
        try: _v265_recalc_visible_plan(self)
        except Exception: pass
        _v269_refresh_materials_total(self)
        _v269_refresh_checklist(self)
        try: _v265_refresh_batch(self)
        except Exception: pass
        _v269_bind_selected_plan_editor(self)
        _v269_cancel_pending_after(self)
    except Exception as e:
        try: messagebox.showerror('Apply Plan', str(e))
        except Exception: pass
    finally:
        self._v269_apply_busy = False


def _v269_generate_selected(self):
    if getattr(self, '_v269_gen_busy', False): return
    self._v269_gen_busy = True
    try:
        _v269_cancel_pending_after(self)
        try: _v266_save_editor_to_current_item(self)
        except Exception: pass
        import pandas as _pd
        units = _v267_generate_units_from_editor(self)
        rows = []
        for i, unit in enumerate(units, 1):
            row = {c: '' for c in _V265_PLAN_COLS}
            row['No'] = str(i); row['Unit name'] = unit
            rows.append(row)
        _v265_write_selected_plan(self, _pd.DataFrame(rows, columns=_V265_PLAN_COLS), preserve_visible=False)
        _v269_apply_plan(self)
        _v269_cancel_pending_after(self)
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v269_gen_busy = False


def _v269_delete_selected_rows(self):
    tree = getattr(self, 'pm_selected_plan_tree', None)
    if tree is None: return
    sel = list(tree.selection())
    if not sel: return
    try:
        for iid in sel:
            try: tree.delete(iid)
            except Exception: pass
        # Renumber in place without recreating ghost rows.
        cols = list(tree['columns'])
        if 'No' in cols:
            ni = cols.index('No')
            for n, iid in enumerate(tree.get_children(), 1):
                vals = list(tree.item(iid, 'values')); vals += [''] * max(0, len(cols)-len(vals))
                vals[ni] = str(n)
                tree.item(iid, values=vals)
        try: tree.selection_remove(tree.selection())
        except Exception: pass
        _v269_apply_plan(self)
        _v269_bind_selected_plan_editor(self)
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass


def _v269_rebind_buttons(self):
    # Rebind only commands; avoid repeatedly hiding/scanning with delayed callbacks.
    for w in list(_v269_walk(self)):
        if not _v269_is_button(w): continue
        t = _v269_button_text(w)
        try:
            if t == 'Generate / Update': w.configure(command=lambda _self=self: _v269_generate_selected(_self))
            elif t == 'Apply Plan': w.configure(command=lambda _self=self: _v269_apply_plan(_self))
            elif t == 'Delete selected row': w.configure(command=lambda _self=self: _v269_delete_selected_rows(_self))
            elif t == 'Add': w.configure(command=lambda _self=self: _v269_pm_add_peptide(_self))
            elif t.startswith('Duplic'): w.configure(command=lambda _self=self: _v269_pm_duplicate_peptide(_self))
            elif t == 'Delete': w.configure(command=lambda _self=self: _v269_pm_delete_peptide(_self))
        except Exception: pass


def _v269_after_build(self):
    _v269_cancel_pending_after(self)
    _v269_set_title(self)
    _v269_patch_entry_editing(self)
    try: _v265_ensure_resin_loading_editor(self)
    except Exception: pass
    _v269_patch_pm_list(self)
    _v269_bind_selected_plan_editor(self)
    _v269_rebind_buttons(self)
    # Final cancel removes old v2.0.68 delayed rescue loops that made typing/tab changes lag.
    _v269_cancel_pending_after(self)


