# ======================= V2.0.70 ITEM STATE + LEAN EXPORT FIX =======================
# Fixes:
# - Peptide item switching must keep/load the matching Selected Plan/Materials/Checklist/Total,
#   not leave stale Ac-EEMQRR-NH2 output under a newly loaded editor.
# - Export must use current Project Manager selected outputs, not the legacy main tree.
# - Export now writes only the essential files: one XLSX workbook + project_state.json.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v270_df_from_tree(tree):
    import pandas as _pd
    try:
        if tree is None:
            return _pd.DataFrame()
        cols = list(tree['columns'] or [])
        rows = []
        for iid in list(tree.get_children()):
            vals = list(tree.item(iid, 'values'))
            vals += [''] * max(0, len(cols) - len(vals))
            rows.append({c: vals[i] for i, c in enumerate(cols)})
        return _pd.DataFrame(rows, columns=cols)
    except Exception:
        return _pd.DataFrame()


def _v270_records_from_tree(tree):
    try:
        return _v270_df_from_tree(tree).fillna('').astype(str).to_dict('records')
    except Exception:
        return []


def _v270_editor_snapshot(self):
    try:
        return {
            'project': self.pm_project.get().strip(),
            'peptide': self.pm_peptide.get().strip(),
            'sequence': self.pm_sequence.get().strip(),
            'scale': self.pm_scale.get().strip(),
            'resin': self.pm_resin.get().strip(),
            'loading': self.pm_loading.get().strip(),
            'lot': self.pm_lot.get().strip(),
            'chemistry': self.pm_chemistry.get().strip(),
            'copies': self.pm_copies.get().strip(),
        }
    except Exception:
        return {}


def _v270_save_item_state(self, idx=None, include_editor=True, include_tables=True):
    """Persist the visible editor and current result panes into the active pm_items row."""
    try:
        if not hasattr(self, 'pm_items'):
            return None
        if idx is None:
            idx = getattr(self, '_v270_active_pm_index', None)
        if idx is None:
            try: idx = self.pm_current_index()
            except Exception: idx = None
        if idx is None or idx < 0 or idx >= len(self.pm_items):
            return None
        item = self.pm_items[idx]
        if include_editor:
            item.update(_v270_editor_snapshot(self))
            item['status'] = item.get('status', 'Ready')
        if include_tables:
            try: item['selected_plan_records'] = _v270_records_from_tree(getattr(self, 'pm_selected_plan_tree', None))
            except Exception: pass
            try: item['selected_materials_records'] = _v270_records_from_tree(getattr(self, 'pm_selected_material_tree', None))
            except Exception: pass
            try:
                total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
                item['selected_total_records'] = _v270_records_from_tree(total_tree)
            except Exception: pass
            try:
                check_tree = getattr(self, 'progress_tree', None) or getattr(self, 'pm_selected_check_tree', None)
                item['selected_checklist_records'] = _v270_records_from_tree(check_tree)
            except Exception: pass
        return idx
    except Exception:
        return None


def _v270_write_records_to_tree(tree, records, columns=None):
    import pandas as _pd
    if records is None:
        records = []
    if columns is None:
        columns = []
        try:
            for r in records:
                for k in r.keys():
                    if k not in columns:
                        columns.append(k)
        except Exception:
            pass
    df = _pd.DataFrame(records, columns=columns if columns else None).fillna('').astype(str)
    try: _v265_write_tree(tree, df, list(df.columns))
    except Exception: pass
    return df


def _v270_clear_outputs(self):
    for attr in ('pm_selected_plan_tree', 'pm_selected_material_tree', 'pm_selected_total_tree', 'pm_total_tree', 'progress_tree', 'pm_selected_check_tree'):
        try:
            tree = getattr(self, attr, None)
            if tree is not None:
                _kids = list(tree.get_children())
                if _kids: tree.delete(*_kids)
        except Exception:
            pass
    try:
        txt = getattr(self, 'pm_selected_check_text', None)
        if txt is not None:
            txt.delete('1.0', 'end')
    except Exception:
        pass


def _v270_load_item_outputs(self, idx):
    """Load stored result panes for item; generate once if none exist and sequence is non-empty."""
    import pandas as _pd
    try:
        item = self.pm_items[idx]
    except Exception:
        return
    plan_records = item.get('selected_plan_records') or item.get('manual_plan') or []
    if plan_records:
        try:
            df = _pd.DataFrame(plan_records).fillna('').astype(str)
            for c in _V265_PLAN_COLS:
                if c not in df.columns:
                    df[c] = ''
            df = df[_V265_PLAN_COLS]
            _v265_write_selected_plan(self, df, preserve_visible=False)
        except Exception:
            pass
        # Recalculate from the loaded plan and the freshly loaded editor values.  This preserves
        # modified Unit names while updating scale/loading/defaults.
        try: _v269_apply_plan(self)
        except Exception: pass
        try: _v270_save_item_state(self, idx, include_editor=False, include_tables=True)
        except Exception: pass
        return
    seq = str(item.get('sequence', '')).strip()
    if seq:
        try: _v269_generate_selected(self)
        except Exception: pass
        try: _v270_save_item_state(self, idx, include_editor=False, include_tables=True)
        except Exception: pass
    else:
        _v270_clear_outputs(self)


def _v270_pm_select_current(self, event=None):
    """Switch peptide items reliably: save previous result panes, load editor, then load/generate matching panes."""
    try:
        idx = self.pm_current_index()
    except Exception:
        idx = None
    if idx is None:
        return 'break' if event is not None else None
    prev = getattr(self, '_v270_active_pm_index', getattr(self, '_v269_active_pm_index', None))
    # Save the previously opened item before replacing editor fields.
    if prev is not None and prev != idx:
        try: _v270_save_item_state(self, prev, include_editor=True, include_tables=True)
        except Exception: pass
    try:
        self.pm_load_to_editor(idx)
    except Exception:
        pass
    self._v270_active_pm_index = idx
    self._v269_active_pm_index = idx
    try: _v270_load_item_outputs(self, idx)
    except Exception: pass
    try: self.pm_update_summary()
    except Exception: pass
    try: self.schedule_autosave()
    except Exception: pass
    return 'break' if event is not None else None


def _v270_pm_double_click(self, event=None):
    return _v270_pm_select_current(self, event)


def _v270_generate_selected(self):
    """Generate from the current editor sequence, then persist panes into the current peptide item."""
    if getattr(self, '_v270_gen_busy', False):
        return
    self._v270_gen_busy = True
    try:
        _v269_generate_selected(self)
        idx = getattr(self, '_v270_active_pm_index', None)
        if idx is None:
            try: idx = self.pm_current_index()
            except Exception: idx = None
        _v270_save_item_state(self, idx, include_editor=True, include_tables=True)
    finally:
        self._v270_gen_busy = False


def _v270_apply_plan(self):
    """Apply current visible plan and persist it to the active peptide item."""
    if getattr(self, '_v270_apply_busy', False):
        return
    self._v270_apply_busy = True
    try:
        _v269_apply_plan(self)
        idx = getattr(self, '_v270_active_pm_index', None)
        if idx is None:
            try: idx = self.pm_current_index()
            except Exception: idx = None
        _v270_save_item_state(self, idx, include_editor=True, include_tables=True)
    finally:
        self._v270_apply_busy = False


def _v270_delete_selected_rows(self):
    try:
        _v269_delete_selected_rows(self)
        idx = getattr(self, '_v270_active_pm_index', None)
        if idx is None:
            try: idx = self.pm_current_index()
            except Exception: idx = None
        _v270_save_item_state(self, idx, include_editor=True, include_tables=True)
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass


def _v270_export_outputs(self):
    """Lean Project Manager export: use visible selected panes; do not call legacy STD main tree."""
    try:
        import pandas as _pd
        from pathlib import Path as _Path
        try: _v270_apply_plan(self)
        except Exception: pass
        idx = getattr(self, '_v270_active_pm_index', None)
        if idx is None:
            try: idx = self.pm_current_index()
            except Exception: idx = None
        try: _v270_save_item_state(self, idx, include_editor=True, include_tables=True)
        except Exception: pass
        summary = _v270_editor_snapshot(self)
        base = _Path(self.outdir.get() if hasattr(self, 'outdir') else ROOT / 'outputs')
        try:
            safe = self._safe_name((summary.get('project') or summary.get('peptide') or summary.get('sequence') or 'SPPS_Project'))
        except Exception:
            import re as _re
            safe = _re.sub(r'[^A-Za-z0-9_.-]+', '_', (summary.get('project') or summary.get('peptide') or 'SPPS_Project')).strip('_') or 'SPPS_Project'
        outdir = base / (safe + '_' + datetime.now().strftime('%Y-%m-%d_%H-%M-%S'))
        outdir.mkdir(parents=True, exist_ok=True)
        plan = _v270_df_from_tree(getattr(self, 'pm_selected_plan_tree', None))
        materials = _v270_df_from_tree(getattr(self, 'pm_selected_material_tree', None))
        total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        total = _v270_df_from_tree(total_tree)
        check_tree = getattr(self, 'progress_tree', None) or getattr(self, 'pm_selected_check_tree', None)
        checklist = _v270_df_from_tree(check_tree)
        summary_df = _pd.DataFrame([summary])
        xlsx = outdir / 'spps_selected_outputs.xlsx'
        with _pd.ExcelWriter(xlsx, engine='openpyxl') as writer:
            summary_df.to_excel(writer, index=False, sheet_name='00_EDITOR_SUMMARY')
            plan.to_excel(writer, index=False, sheet_name='01_SELECTED_PLAN')
            materials.to_excel(writer, index=False, sheet_name='02_SELECTED_MATERIALS')
            total.to_excel(writer, index=False, sheet_name='03_TOTAL_MATERIALS')
            checklist.to_excel(writer, index=False, sheet_name='04_SELECTED_CHECKLIST')
        try:
            self.save_project_state(outdir / 'project_state.json')
        except Exception:
            try:
                import json as _json
                (outdir / 'project_state.json').write_text(_json.dumps({'pm_items': getattr(self, 'pm_items', []), 'active_index': idx}, ensure_ascii=False, indent=2), encoding='utf-8')
            except Exception:
                pass
        self.last_outdir = outdir
        try: self._log(f'Exported selected Project Manager outputs: {outdir}\n')
        except Exception: pass
        try: messagebox.showinfo('Export complete', f'Exported essential files only:\n{xlsx}\nproject_state.json')
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Export error', str(e))
        except Exception: pass
        try: self._log('ERROR export: ' + str(e) + '\n')
        except Exception: pass


def _v270_rebind_buttons(self):
    for w in list(_v269_walk(self)):
        if not _v269_is_button(w):
            continue
        t = _v269_button_text(w)
        try:
            if t == 'Generate / Update': w.configure(command=lambda _self=self: _v270_generate_selected(_self))
            elif t == 'Apply Plan': w.configure(command=lambda _self=self: _v270_apply_plan(_self))
            elif t == 'Delete selected row': w.configure(command=lambda _self=self: _v270_delete_selected_rows(_self))
            elif t == 'Export': w.configure(command=lambda _self=self: _v270_export_outputs(_self))
        except Exception:
            pass


