# --- END V2.0.70 active-index hotfix ---

# --- V2.0.70 selected-item pane load fix: never let legacy apply regenerate STD during item switch. ---
def _v270_load_item_outputs_fixed(self, idx):
    import pandas as _pd
    try:
        item = self.pm_items[idx]
    except Exception:
        return
    plan_records = item.get('selected_plan_records') or item.get('manual_plan') or []
    if plan_records:
        df = _pd.DataFrame(plan_records).fillna('').astype(str)
        for c in _V265_PLAN_COLS:
            if c not in df.columns:
                df[c] = ''
        df = df[_V265_PLAN_COLS]
        _v265_write_selected_plan(self, df, preserve_visible=False)
        # Refresh dependent panes from the written tree only.  Do not call Apply here because
        # older live-sync code can rebuild from the default STD sequence during list switching.
        try: _v269_refresh_materials_total(self)
        except Exception: pass
        try: _v269_refresh_checklist(self)
        except Exception: pass
        try: _v265_refresh_batch(self)
        except Exception: pass
        try: _v269_bind_selected_plan_editor(self)
        except Exception: pass
        try: _v269_cancel_pending_after(self)
        except Exception: pass
        return
    seq = str(item.get('sequence', '')).strip()
    if seq:
        try: _v269_generate_selected(self)
        except Exception: pass
        try: _v270_save_item_state(self, idx, include_editor=False, include_tables=True)
        except Exception: pass
    else:
        _v270_clear_outputs(self)

# Replace the loader symbol used by v2.0.70 selection code.
_v270_load_item_outputs = _v270_load_item_outputs_fixed
# --- END V2.0.70 selected-item pane load fix ---

