# ======================= V2.0.72 STATE PARSER SPEED APPLYCHANGE FIX =======================
# Final connection clean-up requested after V2.0.71:
# - Robust sequence parsing: terminal -NH2/-CONH2/-COOH/-OH never becomes amino-acid tokens.
# - Peptide item switching/generate never falls back to the STD Ac-EEMQRR-NH2 output unless that item actually uses it.
# - Editor typing only saves lightweight state; it does not regenerate/redraw Project/Batch panes on every keystroke.
# - Apply Plan button is promoted near Show setup and renamed Apply Change; calculation behavior is unchanged.
# - Existing Project Manager, Batch Manager, Export, Load Project, Custom DB, selected plan editing functions are preserved.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

import re as _v272_re

_V272_AA_SET = set('ARNDCQEGHILKMFPSTWYV')
_V272_AA_MAP_FALLBACK = {
    'A':'Fmoc-Ala-OH','R':'Fmoc-Arg(Pbf)-OH','N':'Fmoc-Asn(Trt)-OH','D':'Fmoc-Asp(OtBu)-OH','C':'Fmoc-Cys(Trt)-OH',
    'Q':'Fmoc-Gln(Trt)-OH','E':'Fmoc-Glu(OtBu)-OH','G':'Fmoc-Gly-OH','H':'Fmoc-His(Trt)-OH','I':'Fmoc-Ile-OH',
    'L':'Fmoc-Leu-OH','K':'Fmoc-Lys(Boc)-OH','M':'Fmoc-Met-OH','F':'Fmoc-Phe-OH','P':'Fmoc-Pro-OH','S':'Fmoc-Ser(tBu)-OH',
    'T':'Fmoc-Thr(tBu)-OH','W':'Fmoc-Trp(Boc)-OH','Y':'Fmoc-Tyr(tBu)-OH','V':'Fmoc-Val-OH'
}
_V272_THREE_TO_ONE = {
    'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I',
    'LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'
}
_V272_IGNORE_TOKENS = {'', 'AC', 'NH', 'NH2', 'CONH2', 'COOH', 'OH', 'AMIDE', 'ACID'}


def _v272_clean_sequence(seq):
    s = str(seq or '').strip()
    # Normalize common separators but do not remove internal AA letters.
    s = _v272_re.sub(r'[\u2010-\u2015−–—]', '-', s)
    # N-terminal Ac must be an actual token/prefix (Ac- / Ac_ / Ac space), not the A+C residues in ACD.
    has_ac = bool(_v272_re.match(r'^\s*Ac(?:[-_\s]+|$)', s, flags=_v272_re.I))
    if has_ac:
        s = _v272_re.sub(r'^\s*Ac(?:[-_\s]+|$)', '', s, count=1, flags=_v272_re.I)
    # Remove C-terminal labels repeatedly before tokenizing. This is the -NH2 bug fix.
    prev = None
    while prev != s:
        prev = s
        s = _v272_re.sub(r'(?:[-_\s]+)?(?:CONH2|NH2|COOH|OH)\s*$', '', s, flags=_v272_re.I).strip()
    s = s.strip('-_ ,;/')
    return s, has_ac


def _v272_letters_from_sequence(seq):
    core, has_ac = _v272_clean_sequence(seq)
    if not core:
        return [], has_ac
    letters = []
    # If delimiters are present, respect explicit tokens first; otherwise split continuous one-letter sequence.
    pieces = [p for p in _v272_re.split(r'[-_\s,;/()\[\]{}]+', core) if p]
    if len(pieces) <= 1:
        compact = _v272_re.sub(r'[^A-Za-z]', '', core).upper()
        if compact in _V272_IGNORE_TOKENS:
            return [], has_ac
        if compact in _V272_THREE_TO_ONE:
            return [_V272_THREE_TO_ONE[compact]], has_ac
        return [c for c in compact if c in _V272_AA_SET], has_ac
    for p in pieces:
        key = _v272_re.sub(r'[^A-Za-z0-9]', '', str(p)).upper()
        if key in _V272_IGNORE_TOKENS:
            continue
        if key in _V272_THREE_TO_ONE:
            letters.append(_V272_THREE_TO_ONE[key]); continue
        # D-Ala-like notation may be split as D + Ala by the delimiter parser. Keep regular AA letters only here.
        if len(key) == 1 and key in _V272_AA_SET:
            letters.append(key); continue
        if len(key) > 1 and all(c in _V272_AA_SET for c in key):
            letters.extend(list(key)); continue
    return letters, has_ac


def _v272_aa_letters_method(self, seq):
    letters, _has_ac = _v272_letters_from_sequence(seq)
    return letters


def _v272_units(seq):
    letters, has_ac = _v272_letters_from_sequence(seq)
    try:
        amap = _v248_aa_map()
    except Exception:
        amap = _V272_AA_MAP_FALLBACK
    units = [amap.get(x, x) for x in reversed(letters)]
    if has_ac and units:
        units.append('Acetic anhydride (Ac2O) for N-terminal acetylation')
    return units


def _v272_get(var, default=''):
    try:
        v = var.get() if hasattr(var, 'get') else var
        v = str(v)
        return v if v != '' else default
    except Exception:
        return default


def _v272_idx(self):
    try:
        sel = self.pm_list.curselection()
        if sel:
            i = int(sel[0])
            if 0 <= i < len(getattr(self, 'pm_items', [])):
                return i
    except Exception:
        pass
    for a in ('_v272_active_pm_index', '_v271_active_pm_index', '_v270_active_pm_index', '_v269_active_pm_index'):
        try:
            i = int(getattr(self, a))
            if 0 <= i < len(getattr(self, 'pm_items', [])):
                return i
        except Exception:
            pass
    return None


def _v272_editor(self):
    return {
        'project': _v272_get(getattr(self, 'pm_project', None), ''),
        'peptide': _v272_get(getattr(self, 'pm_peptide', None), ''),
        'sequence': _v272_get(getattr(self, 'pm_sequence', None), ''),
        'scale': _v272_get(getattr(self, 'pm_scale', None), '0.2'),
        'resin': _v272_get(getattr(self, 'pm_resin', None), 'Rink Amide AM'),
        'loading': _v272_get(getattr(self, 'pm_loading', None), '0.8'),
        'lot': _v272_get(getattr(self, 'pm_lot', None), ''),
        'chemistry': _v272_get(getattr(self, 'pm_chemistry', None), 'DIC/HOBt'),
        'copies': _v272_get(getattr(self, 'pm_copies', None), '1'),
    }


def _v272_records(tree):
    try:
        return _v270_records_from_tree(tree)
    except Exception:
        rows = []
        try:
            cols = list(tree['columns'])
            for iid in tree.get_children():
                vals = list(tree.item(iid, 'values'))
                vals += [''] * max(0, len(cols) - len(vals))
                rows.append(dict(zip(cols, vals)))
        except Exception:
            pass
        return rows


def _v272_save(self, idx=None, editor=True, tables=True):
    try:
        if idx is None:
            idx = _v272_idx(self)
        if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
            return None
        item = self.pm_items[idx]
        if editor:
            ed = _v272_editor(self)
            item.update(ed)
            item['status'] = item.get('status', 'Ready')
        if tables:
            plan = _v272_records(getattr(self, 'pm_selected_plan_tree', None))
            mats = _v272_records(getattr(self, 'pm_selected_material_tree', None))
            tt = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
            chk_tree = getattr(self, 'progress_tree', None) or getattr(self, 'pm_selected_check_tree', None)
            total = _v272_records(tt)
            chk = _v272_records(chk_tree)
            if plan: item['selected_plan_records'] = plan
            if mats: item['selected_materials_records'] = mats
            if total: item['selected_total_records'] = total
            if chk: item['selected_checklist_records'] = chk
        if item.get('sequence') and item.get('selected_plan_records'):
            item.setdefault('generated_sequence', item.get('sequence'))
        return idx
    except Exception:
        return None


def _v272_write_units(self, units):
    import pandas as _pd
    rows = []
    for i, u in enumerate(units, 1):
        r = {c: '' for c in _V265_PLAN_COLS}
        r['No'] = str(i)
        r['Unit name'] = u
        rows.append(r)
    df = _pd.DataFrame(rows, columns=_V265_PLAN_COLS)
    _v265_write_selected_plan(self, df, preserve_visible=False)
    return df


def _v272_clear_outputs(self):
    for attr in ('pm_selected_plan_tree', 'pm_selected_material_tree', 'pm_selected_total_tree', 'pm_total_tree', 'progress_tree', 'pm_selected_check_tree'):
        try:
            tree = getattr(self, attr, None)
            if tree is not None:
                for iid in list(tree.get_children()):
                    tree.delete(iid)
        except Exception:
            pass
    try:
        txt = getattr(self, 'pm_selected_check_text', None)
        if txt is not None:
            txt.delete('1.0', 'end')
    except Exception:
        pass


def _v272_write_records(tree, records, preferred_cols=None):
    if tree is None or not records:
        return False
    try:
        cols = preferred_cols or list(records[0].keys())
        _v270_write_records_to_tree(tree, records, cols)
        return True
    except Exception:
        try:
            import pandas as _pd
            cols = preferred_cols or list(records[0].keys())
            _v265_write_tree(tree, _pd.DataFrame(records).fillna('').astype(str), cols)
            return True
        except Exception:
            return False


def _v272_restore_outputs(self, item):
    rec = item.get('selected_plan_records') or item.get('manual_plan') or []
    if not rec:
        return False
    import pandas as _pd
    df = _pd.DataFrame(rec).fillna('').astype(str)
    for c in _V265_PLAN_COLS:
        if c not in df.columns:
            df[c] = ''
    df = df[_V265_PLAN_COLS]
    try:
        _v265_write_tree(getattr(self, 'pm_selected_plan_tree', None), df, _V265_PLAN_COLS)
    except Exception:
        try: _v265_write_selected_plan(self, df, preserve_visible=False)
        except Exception: pass
    try:
        mats = item.get('selected_materials_records') or []
        if mats: _v272_write_records(getattr(self, 'pm_selected_material_tree', None), mats, list(mats[0].keys()))
        else: _v269_refresh_materials_total(self)
    except Exception:
        try: _v269_refresh_materials_total(self)
        except Exception: pass
    try:
        total = item.get('selected_total_records') or []
        tt = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        if total: _v272_write_records(tt, total, list(total[0].keys()))
    except Exception:
        pass
    try:
        chk = item.get('selected_checklist_records') or []
        ct = getattr(self, 'progress_tree', None) or getattr(self, 'pm_selected_check_tree', None)
        if chk: _v272_write_records(ct, chk, list(chk[0].keys()))
        else: _v269_refresh_checklist(self)
    except Exception:
        try: _v269_refresh_checklist(self)
        except Exception: pass
    try: _v269_bind_selected_plan_editor(self)
    except Exception: pass
    return True


def _v272_load_item(self, idx, generate_missing=True):
    if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
        return
    item = self.pm_items[idx]
    try:
        self._pm_loading_editor = True
        for name, key, default in [
            ('pm_project', 'project', ''), ('pm_peptide', 'peptide', ''), ('pm_sequence', 'sequence', ''),
            ('pm_scale', 'scale', '0.2'), ('pm_resin', 'resin', 'Rink Amide AM'), ('pm_loading', 'loading', '0.8'),
            ('pm_lot', 'lot', ''), ('pm_chemistry', 'chemistry', 'DIC/HOBt'), ('pm_copies', 'copies', '1')]:
            try: getattr(self, name).set(str(item.get(key, default)))
            except Exception: pass
    finally:
        try: self._pm_loading_editor = False
        except Exception: pass
    for a in ('_v272_active_pm_index', '_v271_active_pm_index', '_v270_active_pm_index', '_v269_active_pm_index'):
        try: setattr(self, a, idx)
        except Exception: pass
    try:
        self.pm_list.selection_clear(0, 'end'); self.pm_list.selection_set(idx); self.pm_list.activate(idx)
    except Exception:
        pass
    restored = _v272_restore_outputs(self, item)
    if not restored:
        if generate_missing and str(item.get('sequence', '')).strip():
            _v272_generate(self, force=True)
        else:
            _v272_clear_outputs(self)
    try: self.pm_update_summary()
    except Exception: pass
    try: _v269_cancel_pending_after(self)
    except Exception: pass


def _v272_light_live_sync(self):
    if getattr(self, '_pm_loading_editor', False):
        return
    idx = _v272_idx(self)
    if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
        return
    try:
        ed = _v272_editor(self)
        self.pm_items[idx].update(ed)
        self.pm_items[idx]['status'] = self.pm_items[idx].get('status', 'Ready')
        # Keep the visible list text reasonably current, but do not redraw summary/batch/output panes per key.
        try:
            label = self.pm_display_name(self.pm_items[idx])
            old = self.pm_list.get(idx)
            if old != label:
                self.pm_list.delete(idx); self.pm_list.insert(idx, label); self.pm_list.selection_set(idx); self.pm_list.activate(idx)
        except Exception:
            pass
        # Slower autosave debounce removes visible typing lag.
        try: _v272_schedule_autosave(self, 2200)
        except Exception: pass
    except Exception:
        pass


def _v272_schedule_autosave(self, delay=2200):
    if getattr(self, '_restoring_state', False):
        return
    try:
        if getattr(self, '_autosave_after_id', None):
            self.after_cancel(self._autosave_after_id)
        self._autosave_after_id = self.after(int(delay), self.save_autosave_state)
    except Exception:
        pass


def _v272_pm_select(self, event=None):
    try: idx = self.pm_current_index()
    except Exception: idx = _v272_idx(self)
    if idx is None:
        return 'break' if event is not None else None
    prev = getattr(self, '_v272_active_pm_index', getattr(self, '_v271_active_pm_index', None))
    if prev is not None and prev != idx:
        try: _v272_save(self, prev, True, True)
        except Exception: pass
    _v272_load_item(self, idx, generate_missing=True)
    return 'break' if event is not None else None


def _v272_generate(self, force=False):
    if getattr(self, '_v272_gen_busy', False):
        return
    self._v272_gen_busy = True
    try:
        try: _v269_cancel_pending_after(self)
        except Exception: pass
        idx = _v272_idx(self)
        cur = _v272_editor(self)
        cur_seq = str(cur.get('sequence', '')).strip()
        item = None
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            item = self.pm_items[idx]
            item.update(cur)
        if not cur_seq:
            _v272_clear_outputs(self)
            if item is not None:
                for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','manual_plan','generated_sequence'):
                    item.pop(k, None)
            return
        generated_seq = str((item or {}).get('generated_sequence', '')).strip()
        saved_plan = bool((item or {}).get('selected_plan_records'))
        # Same sequence: Generate behaves like Apply Change to preserve manual Selected Plan edits.
        if (not force) and item is not None and saved_plan and generated_seq == cur_seq:
            _v272_restore_outputs(self, item)
        else:
            units = _v272_units(cur_seq)
            if not units:
                _v272_clear_outputs(self)
            else:
                _v272_write_units(self, units)
            if item is not None:
                item['generated_sequence'] = cur_seq
                for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','manual_plan'):
                    item.pop(k, None)
        try: _v269_apply_plan(self)
        except Exception: pass
        _v272_save(self, idx, True, True)
        try: _v269_cancel_pending_after(self)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v272_gen_busy = False


def _v272_generate_selected(self):
    _v272_generate(self, force=False)


def _v272_apply_change(self):
    if getattr(self, '_v272_apply_busy', False):
        return
    self._v272_apply_busy = True
    try:
        try: _v269_cancel_pending_after(self)
        except Exception: pass
        idx = _v272_idx(self)
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            self.pm_items[idx].update(_v272_editor(self))
        try: _v269_apply_plan(self)
        except Exception as e:
            try: messagebox.showerror('Apply Change', str(e))
            except Exception: pass
        _v272_save(self, idx, True, True)
        try: _v269_cancel_pending_after(self)
        except Exception: pass
    finally:
        self._v272_apply_busy = False


def _v272_delete_selected_rows(self):
    try: _v269_delete_selected_rows(self)
    finally:
        try: _v272_save(self, _v272_idx(self), True, True)
        except Exception: pass


def _v272_add_item(self, item=None):
    try: _v272_save(self, _v272_idx(self), True, True)
    except Exception: pass
    try:
        n = len(getattr(self, 'pm_items', [])) + 1
        if item is None:
            item = _v272_editor(self)
            item.update({'project': item.get('project') or f'Project-{n:03d}', 'peptide': f'Peptide-{n:03d}', 'sequence': '', 'lot': f"SPPS-{datetime.now().strftime('%y%m%d')}-{n:02d}", 'status': 'Ready'})
        self.pm_items.append(dict(item))
        idx = len(self.pm_items) - 1
        self.pm_refresh_list(keep_index=idx, reload_editor=False)
        _v272_load_item(self, idx, generate_missing=False)
        try: _v272_schedule_autosave(self, 1200)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Add peptide', str(e))
        except Exception: pass


def _v272_duplicate_item(self):
    try:
        idx = _v272_idx(self)
        if idx is None: return
        _v272_save(self, idx, True, True)
        new = dict(self.pm_items[idx])
        new['peptide'] = str(new.get('peptide', 'Peptide')) + '_copy'
        new['lot'] = f"SPPS-{datetime.now().strftime('%y%m%d')}-{len(self.pm_items)+1:02d}"
        self.pm_items.append(new)
        nidx = len(self.pm_items) - 1
        self.pm_refresh_list(keep_index=nidx, reload_editor=False)
        _v272_load_item(self, nidx, generate_missing=False)
        try: _v272_schedule_autosave(self, 1200)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Duplicate peptide', str(e))
        except Exception: pass


def _v272_delete_item(self):
    try:
        idx = _v272_idx(self)
        if idx is None: return
        del self.pm_items[idx]
        if not self.pm_items:
            _v272_add_item(self); return
        nidx = min(idx, len(self.pm_items)-1)
        self.pm_refresh_list(keep_index=nidx, reload_editor=False)
        _v272_load_item(self, nidx, generate_missing=True)
        try: _v272_schedule_autosave(self, 1200)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Delete peptide', str(e))
        except Exception: pass


def _v272_install_apply_change_button(self):
    # Place a single Apply Change next to Show setup, and hide old lower Apply Plan buttons.
    show_btn = None
    try:
        for w in list(_v269_walk(self)):
            if _v269_is_button(w) and _v269_button_text(w) == 'Show setup' and w.winfo_ismapped():
                show_btn = w; break
    except Exception:
        show_btn = None
    if show_btn is not None:
        try:
            parent = show_btn.master
            if not getattr(self, '_v272_apply_change_button', None) or not self._v272_apply_change_button.winfo_exists():
                self._v272_apply_change_button = ttk.Button(parent, text='Apply Change', command=lambda _self=self: _v272_apply_change(_self))
                self._v272_apply_change_button.pack(side='left', padx=3)
            else:
                self._v272_apply_change_button.configure(command=lambda _self=self: _v272_apply_change(_self), text='Apply Change')
        except Exception:
            pass
    # Hide/rename legacy Apply Plan buttons except our new one.
    try:
        for w in list(_v269_walk(self)):
            if not _v269_is_button(w):
                continue
            if w is getattr(self, '_v272_apply_change_button', None):
                continue
            t = _v269_button_text(w)
            if t in ('Apply Plan', 'Apply Change'):
                try: w.pack_forget()
                except Exception: pass
                try: w.grid_remove()
                except Exception: pass
                try: w.place_forget()
                except Exception: pass
    except Exception:
        pass


def _v272_rebind_buttons(self):
    try:
        for w in list(_v269_walk(self)):
            if not _v269_is_button(w):
                continue
            t = _v269_button_text(w)
            try:
                if t == 'Generate / Update': w.configure(command=lambda _self=self: _v272_generate_selected(_self))
                elif t in ('Apply Plan', 'Apply Change'): w.configure(command=lambda _self=self: _v272_apply_change(_self))
                elif t == 'Delete selected row': w.configure(command=lambda _self=self: _v272_delete_selected_rows(_self))
                elif t == 'Export': w.configure(command=lambda _self=self: _v271_export_project(_self))
                elif t == 'Export batch tables': w.configure(command=lambda _self=self: _v271_export_batch(_self))
                elif t == 'Add': w.configure(command=lambda _self=self: _v272_add_item(_self))
                elif t.startswith('Duplic'): w.configure(command=lambda _self=self: _v272_duplicate_item(_self))
                elif t == 'Delete': w.configure(command=lambda _self=self: _v272_delete_item(_self))
            except Exception:
                pass
    except Exception:
        pass
    try: _v272_install_apply_change_button(self)
    except Exception: pass


def _v272_on_tab_changed(self, event=None):
    # Very light tab handler: no global rescans or generate calls.
    try: _v269_cancel_pending_after(self)
    except Exception: pass
    try: _v272_install_apply_change_button(self)
    except Exception: pass


def _v272_after_build(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try: _v269_cancel_pending_after(self)
    except Exception: pass
    try:
        if hasattr(self, 'pm_list'):
            self.pm_list.bind('<<ListboxSelect>>', lambda e, _self=self: _v272_pm_select(_self, e), add=False)
            self.pm_list.bind('<Double-Button-1>', lambda e, _self=self: _v272_pm_select(_self, e), add=False)
            self.pm_list.bind('<Return>', lambda e, _self=self: _v272_pm_select(_self, e), add=False)
            i = _v272_idx(self)
            if i is not None:
                self._v272_active_pm_index = i
    except Exception:
        pass
    try: _v272_rebind_buttons(self)
    except Exception: pass
    try: _v269_patch_entry_editing(self)
    except Exception: pass
    try: _v269_bind_selected_plan_editor(self)
    except Exception: pass
    try:
        if hasattr(self, 'tabs'):
            self.tabs.bind('<<NotebookTabChanged>>', lambda e, _self=self: _v272_on_tab_changed(_self, e), add=False)
    except Exception:
        pass
    try: _v269_cancel_pending_after(self)
    except Exception: pass


