# ======================= V2.0.73 FINAL FUNCTION RESTORE + STATE STABILITY FIX =======================
# User-facing goal:
# - Do not remove working UI features. Rewire them to a single stable Project Manager state model.
# - Stop peptide editor typing from falling back to Ac-EEMQRR-NH2.
# - Restore reliable peptide item switching for all items.
# - Keep Generate / Update and Apply Change distinct but compatible.
# - Remove visible typing lag from trace-heavy legacy live-sync.
# - Keep Selected Plan / Materials / Checklist / Total / Batch / Export in sync with the selected peptide item.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

import re as _v273_re
import json as _v273_json
from pathlib import Path as _v273_Path

_V273_EDITOR_FIELDS = (
    ('pm_project','project','Project-001'),
    ('pm_peptide','peptide','Peptide-001'),
    ('pm_sequence','sequence',''),
    ('pm_scale','scale','0.2'),
    ('pm_resin','resin','Rink Amide AM'),
    ('pm_loading','loading','0.8'),
    ('pm_lot','lot',''),
    ('pm_chemistry','chemistry','DIC/HOBt'),
    ('pm_copies','copies','1'),
)


def _v273_get_var(self, attr, default=''):
    try:
        v = getattr(self, attr, None)
        if v is not None and hasattr(v, 'get'):
            return str(v.get())
    except Exception:
        pass
    return str(default)


def _v273_set_var(self, attr, value):
    try:
        v = getattr(self, attr, None)
        if v is not None and hasattr(v, 'set'):
            v.set('' if value is None else str(value))
    except Exception:
        pass


def _v273_editor_snapshot(self):
    d = {}
    for attr, key, default in _V273_EDITOR_FIELDS:
        d[key] = _v273_get_var(self, attr, default).strip()
    if not d.get('project'):
        d['project'] = 'Project-001'
    if not d.get('peptide'):
        try:
            d['peptide'] = f"Peptide-{(_v273_current_index(self) or 0)+1:03d}"
        except Exception:
            d['peptide'] = 'Peptide-001'
    if not d.get('scale'):
        d['scale'] = '0.2'
    if not d.get('loading'):
        d['loading'] = '0.8'
    if not d.get('resin'):
        d['resin'] = 'Rink Amide AM'
    if not d.get('chemistry'):
        d['chemistry'] = 'DIC/HOBt'
    if not d.get('copies'):
        d['copies'] = '1'
    return d


def _v273_current_index(self):
    try:
        sel = list(self.pm_list.curselection())
        if sel:
            return int(sel[0])
    except Exception:
        pass
    for a in ('_v273_active_index','_v272_active_pm_index','_v271_active_pm_index','_v270_active_pm_index','_v269_active_pm_index'):
        try:
            i = getattr(self, a)
            if i is not None:
                i = int(i)
                if 0 <= i < len(getattr(self, 'pm_items', [])):
                    return i
        except Exception:
            pass
    try:
        return self.pm_current_index()
    except Exception:
        return 0 if getattr(self, 'pm_items', []) else None


def _v273_records_from_tree(tree):
    rows = []
    try:
        cols = list(tree['columns'] or [])
        for iid in tree.get_children():
            vals = list(tree.item(iid, 'values'))
            vals += [''] * max(0, len(cols)-len(vals))
            rows.append({c: vals[i] for i, c in enumerate(cols)})
    except Exception:
        pass
    return rows


def _v273_write_records_to_tree(tree, rows, fallback_cols=None):
    try:
        if rows:
            cols = list(rows[0].keys())
        else:
            cols = list(fallback_cols or getattr(tree, 'columns', []) or [])
    except Exception:
        cols = list(fallback_cols or [])
    try:
        tree.configure(columns=cols, show='headings')
        for c in cols:
            try:
                tree.heading(c, text=c)
                width = 90
                if c in ('Unit name','Reagent 2 / catalyst','Coupling solvent','Note','note','operation','next_step','material','class'):
                    width = 180
                if c in ('No','line','done'):
                    width = 55
                tree.column(c, width=width, minwidth=45, anchor='w', stretch=False)
            except Exception:
                pass
        try:
            _kids = list(tree.get_children())
            if _kids: tree.delete(*_kids)
        except Exception:
            for iid in list(tree.get_children()):
                try: tree.delete(iid)
                except Exception: pass
        for r in rows or []:
            tree.insert('', 'end', values=[str(r.get(c, '')) for c in cols])
    except Exception:
        pass


def _v273_tree_payload(self):
    total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
    check_tree = getattr(self, 'pm_selected_check_tree', None) or getattr(self, 'progress_tree', None)
    return {
        'selected_plan_records': _v273_records_from_tree(getattr(self, 'pm_selected_plan_tree', None)),
        'selected_materials_records': _v273_records_from_tree(getattr(self, 'pm_selected_material_tree', None)),
        'selected_total_records': _v273_records_from_tree(total_tree),
        'selected_checklist_records': _v273_records_from_tree(check_tree),
    }


def _v273_save_item(self, idx=None, include_tables=True):
    try:
        if idx is None:
            idx = _v273_current_index(self)
        if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
            return None
        item = self.pm_items[idx]
        item.update(_v273_editor_snapshot(self))
        item['status'] = item.get('status', 'Ready') or 'Ready'
        if include_tables:
            item.update(_v273_tree_payload(self))
            if item.get('selected_plan_records'):
                item['manual_plan'] = True
        return idx
    except Exception:
        return None


def _v273_set_active_index(self, idx):
    try:
        idx = int(idx)
    except Exception:
        idx = 0
    for a in ('_v273_active_index','_v272_active_pm_index','_v271_active_pm_index','_v270_active_pm_index','_v269_active_pm_index'):
        try: setattr(self, a, idx)
        except Exception: pass


def _v273_select_list_index(self, idx):
    try:
        self.pm_list.selection_clear(0, 'end')
        if idx is not None and idx >= 0:
            self.pm_list.selection_set(idx)
            self.pm_list.activate(idx)
            self.pm_list.see(idx)
    except Exception:
        pass
    _v273_set_active_index(self, idx if idx is not None else 0)


def _v273_display_name(self, item):
    try:
        return self.pm_display_name(item)
    except Exception:
        p = str(item.get('project','')).strip()
        n = str(item.get('peptide','')).strip()
        s = str(item.get('sequence','')).strip()
        return ' | '.join(x for x in (p, n, s) if x) or 'Peptide'


def _v273_refresh_list(self, idx=None, load=False):
    try:
        if not hasattr(self, 'pm_list'):
            return
        y = self.pm_list.yview()
        self.pm_list.delete(0, 'end')
        for it in list(getattr(self, 'pm_items', []) or []):
            self.pm_list.insert('end', _v273_display_name(self, it))
        if getattr(self, 'pm_items', []):
            if idx is None:
                idx = _v273_current_index(self)
            idx = max(0, min(int(idx or 0), len(self.pm_items)-1))
            _v273_select_list_index(self, idx)
        try:
            self.pm_list.yview_moveto(y[0])
        except Exception:
            pass
        if load and idx is not None:
            _v273_load_item(self, idx, restore_outputs=True)
    except Exception:
        try: self.pm_refresh_list(keep_index=idx or 0, reload_editor=bool(load))
        except Exception: pass


def _v273_clear_outputs(self):
    for attr in ('pm_selected_plan_tree','pm_selected_material_tree','pm_selected_total_tree','pm_total_tree','pm_selected_check_tree','progress_tree'):
        try:
            tree = getattr(self, attr, None)
            if tree is not None:
                for iid in list(tree.get_children()):
                    tree.delete(iid)
        except Exception:
            pass
    try:
        txt = getattr(self, 'pm_selected_check_text', None)
        if txt is not None:
            txt.delete('1.0', 'end')
    except Exception:
        pass


def _v273_restore_outputs(self, item):
    ok = False
    try:
        plan = item.get('selected_plan_records') or []
        if plan:
            _v273_write_records_to_tree(getattr(self, 'pm_selected_plan_tree', None), plan, globals().get('_V265_PLAN_COLS'))
            ok = True
    except Exception:
        pass
    try:
        mats = item.get('selected_materials_records') or []
        if mats:
            _v273_write_records_to_tree(getattr(self, 'pm_selected_material_tree', None), mats)
    except Exception:
        pass
    try:
        total = item.get('selected_total_records') or []
        tt = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        if total and tt is not None:
            _v273_write_records_to_tree(tt, total)
    except Exception:
        pass
    try:
        chk = item.get('selected_checklist_records') or []
        ct = getattr(self, 'pm_selected_check_tree', None) or getattr(self, 'progress_tree', None)
        if chk and ct is not None:
            _v273_write_records_to_tree(ct, chk)
        txt = getattr(self, 'pm_selected_check_text', None)
        if txt is not None:
            txt.delete('1.0','end')
            for r in chk:
                txt.insert('end', f"{r.get('line','')}. {r.get('operation','')} | {r.get('unit','')} | {r.get('next_step','')} | {r.get('note','')}\n")
    except Exception:
        pass
    try:
        if ok and '_v269_bind_selected_plan_editor' in globals():
            _v269_bind_selected_plan_editor(self)
    except Exception:
        pass
    return ok


def _v273_load_item(self, idx, restore_outputs=True):
    try:
        if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
            return
        item = self.pm_items[idx]
        self._pm_loading_editor = True
        for attr, key, default in _V273_EDITOR_FIELDS:
            _v273_set_var(self, attr, item.get(key, default))
        self._pm_loading_editor = False
        _v273_select_list_index(self, idx)
        if restore_outputs:
            if not _v273_restore_outputs(self, item):
                _v273_clear_outputs(self)
        try: self.pm_update_summary()
        except Exception: pass
    except Exception:
        try: self._pm_loading_editor = False
        except Exception: pass


def _v273_clean_sequence(raw):
    s = str(raw or '').strip()
    s = _v273_re.sub(r'[\u2010-\u2015−–—]', '-', s)
    has_ac = bool(_v273_re.match(r'^\s*Ac(?:[-_\s]+|$)', s, flags=_v273_re.I))
    s = _v273_re.sub(r'^\s*Ac(?:[-_\s]+|$)', '', s, flags=_v273_re.I)
    # Remove terminal protecting/terminus labels before tokenizing.
    old = None
    while old != s:
        old = s
        s = _v273_re.sub(r'(?:[-_\s]+)?(?:CONH2|NH2|COOH|CO2H|OH)\s*$', '', s, flags=_v273_re.I).strip()
    return s, has_ac


def _v273_letters_from_sequence(seq):
    core, has_ac = _v273_clean_sequence(seq)
    valid = set('ARNDCQEGHILKMFPSTWYV')
    letters = []
    # Accept compact one-letter sequences first.
    compact = _v273_re.sub(r'[^A-Za-z]', '', core).upper()
    if compact and all(ch in valid for ch in compact):
        letters = list(compact)
    else:
        for p in [x for x in _v273_re.split(r'[-_\s,;/()\[\]{}]+', core) if x]:
            key = _v273_re.sub(r'[^A-Za-z0-9]', '', p).upper()
            if key in ('', 'AC', 'NH', 'NH2', 'CONH2', 'COOH', 'CO2H', 'OH'):
                continue
            if len(key) == 1 and key in valid:
                letters.append(key)
            elif len(key) == 3:
                mp = {'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
                if key in mp: letters.append(mp[key])
    return letters, has_ac


def _v273_units_from_sequence(seq):
    try:
        letters, has_ac = _v273_letters_from_sequence(seq)
        aa_to_fmoc = {
            'A':'Fmoc-Ala-OH','R':'Fmoc-Arg(Pbf)-OH','N':'Fmoc-Asn(Trt)-OH','D':'Fmoc-Asp(OtBu)-OH','C':'Fmoc-Cys(Trt)-OH',
            'Q':'Fmoc-Gln(Trt)-OH','E':'Fmoc-Glu(OtBu)-OH','G':'Fmoc-Gly-OH','H':'Fmoc-His(Trt)-OH','I':'Fmoc-Ile-OH',
            'L':'Fmoc-Leu-OH','K':'Fmoc-Lys(Boc)-OH','M':'Fmoc-Met-OH','F':'Fmoc-Phe-OH','P':'Fmoc-Pro-OH',
            'S':'Fmoc-Ser(tBu)-OH','T':'Fmoc-Thr(tBu)-OH','W':'Fmoc-Trp(Boc)-OH','Y':'Fmoc-Tyr(tBu)-OH','V':'Fmoc-Val-OH'
        }
        units = [aa_to_fmoc[a] for a in reversed(letters) if a in aa_to_fmoc]
        if has_ac and units:
            units.append('Acetic anhydride (Ac2O) for N-terminal acetylation')
        return units
    except Exception:
        try: return _v272_units(seq)
        except Exception: return []


def _v273_write_units_to_plan(self, units):
    try:
        import pandas as _pd
        rows = []
        cols = list(globals().get('_V265_PLAN_COLS', []))
        for i, u in enumerate(units, 1):
            row = {c: '' for c in cols}
            row['No'] = str(i)
            row['Unit name'] = u
            rows.append(row)
        if '_v265_write_selected_plan' in globals():
            _v265_write_selected_plan(self, _pd.DataFrame(rows, columns=cols), preserve_visible=False)
        else:
            _v273_write_records_to_tree(getattr(self, 'pm_selected_plan_tree', None), rows, cols)
    except Exception:
        pass


def _v273_apply_change(self):
    if getattr(self, '_v273_apply_busy', False):
        return
    self._v273_apply_busy = True
    try:
        idx = _v273_current_index(self)
        if idx is not None:
            _v273_save_item(self, idx, include_tables=False)
        try:
            if '_v269_apply_plan' in globals():
                _v269_apply_plan(self)
            elif hasattr(self, 'apply_plan_mw_density'):
                self.apply_plan_mw_density()
        except Exception as e:
            try: messagebox.showerror('Apply Change', str(e))
            except Exception: pass
        if idx is not None:
            item = self.pm_items[idx]
            item['generated_sequence'] = _v273_get_var(self, 'pm_sequence', '')
            _v273_save_item(self, idx, include_tables=True)
        try: _v273_refresh_list(self, idx, load=False)
        except Exception: pass
        try: _v273_schedule_autosave(self, 1800)
        except Exception: pass
    finally:
        self._v273_apply_busy = False


def _v273_generate(self, force=False):
    if getattr(self, '_v273_gen_busy', False):
        return
    self._v273_gen_busy = True
    try:
        idx = _v273_current_index(self)
        if idx is None:
            return
        if idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
            return
        cur = _v273_editor_snapshot(self)
        seq = cur.get('sequence','').strip()
        item = self.pm_items[idx]
        item.update(cur)
        if not seq:
            _v273_clear_outputs(self)
            for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','generated_sequence','manual_plan'):
                item.pop(k, None)
            _v273_save_item(self, idx, include_tables=True)
            return
        same_seq = (str(item.get('generated_sequence','')).strip() == seq)
        has_plan = bool(item.get('selected_plan_records'))
        if (not force) and same_seq and has_plan:
            _v273_restore_outputs(self, item)
            _v273_apply_change(self)
        else:
            units = _v273_units_from_sequence(seq)
            if not units:
                _v273_clear_outputs(self)
                for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','manual_plan'):
                    item.pop(k, None)
            else:
                _v273_write_units_to_plan(self, units)
                item['generated_sequence'] = seq
                item.pop('manual_plan', None)
                _v273_apply_change(self)
        item['status'] = 'Calculated' if seq else 'Ready'
        _v273_save_item(self, idx, include_tables=True)
        _v273_refresh_list(self, idx, load=False)
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v273_gen_busy = False


def _v273_pm_select(self, event=None):
    try:
        new_idx = self.pm_current_index()
    except Exception:
        new_idx = _v273_current_index(self)
    if new_idx is None:
        return 'break' if event is not None else None
    old_idx = getattr(self, '_v273_active_index', None)
    if old_idx is None:
        for a in ('_v272_active_pm_index','_v271_active_pm_index','_v270_active_pm_index','_v269_active_pm_index'):
            try:
                old_idx = getattr(self, a)
                break
            except Exception:
                pass
    if old_idx is not None and old_idx != new_idx:
        _v273_save_item(self, int(old_idx), include_tables=True)
    _v273_load_item(self, int(new_idx), restore_outputs=True)
    return 'break' if event is not None else None


def _v273_add_item(self, item=None):
    try: _v273_save_item(self, _v273_current_index(self), include_tables=True)
    except Exception: pass
    if not hasattr(self, 'pm_items'):
        self.pm_items = []
    n = len(self.pm_items) + 1
    if item is None:
        base = _v273_editor_snapshot(self)
        # New Add should be blank for sequence but preserve practical setup fields.
        item = {
            'project': base.get('project') or f'Project-{n:03d}',
            'peptide': f'Peptide-{n:03d}',
            'sequence': '',
            'scale': base.get('scale','0.2'),
            'resin': base.get('resin','Rink Amide AM'),
            'loading': base.get('loading','0.8'),
            'lot': f"SPPS-{datetime.now().strftime('%y%m%d')}-{n:02d}",
            'chemistry': base.get('chemistry','DIC/HOBt'),
            'copies': base.get('copies','1'),
            'status': 'Ready'
        }
    self.pm_items.append(dict(item))
    idx = len(self.pm_items) - 1
    _v273_refresh_list(self, idx, load=False)
    _v273_load_item(self, idx, restore_outputs=False)
    _v273_clear_outputs(self)
    try: _v273_schedule_autosave(self, 1200)
    except Exception: pass


def _v273_duplicate_item(self):
    idx = _v273_current_index(self)
    if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
        return
    _v273_save_item(self, idx, include_tables=True)
    new = dict(self.pm_items[idx])
    new['peptide'] = str(new.get('peptide','Peptide')) + '_copy'
    new['lot'] = f"SPPS-{datetime.now().strftime('%y%m%d')}-{len(self.pm_items)+1:02d}"
    new['status'] = new.get('status','Ready')
    self.pm_items.append(new)
    nidx = len(self.pm_items) - 1
    _v273_refresh_list(self, nidx, load=False)
    _v273_load_item(self, nidx, restore_outputs=True)
    try: _v273_schedule_autosave(self, 1200)
    except Exception: pass


def _v273_delete_item(self):
    idx = _v273_current_index(self)
    if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
        return
    try: del self.pm_items[idx]
    except Exception: return
    if not self.pm_items:
        _v273_add_item(self)
        return
    nidx = min(idx, len(self.pm_items)-1)
    _v273_refresh_list(self, nidx, load=False)
    _v273_load_item(self, nidx, restore_outputs=True)
    try: _v273_schedule_autosave(self, 1200)
    except Exception: pass


def _v273_delete_selected_rows(self):
    try:
        if '_v269_delete_selected_rows' in globals():
            _v269_delete_selected_rows(self)
        else:
            tree = getattr(self, 'pm_selected_plan_tree', None)
            if tree is None: return
            for iid in list(tree.selection()):
                tree.delete(iid)
    finally:
        try: _v273_apply_change(self)
        except Exception: pass


def _v273_light_editor_changed(self):
    if getattr(self, '_pm_loading_editor', False):
        return
    if getattr(self, '_v273_editor_sync_busy', False):
        return
    self._v273_editor_sync_busy = True
    try:
        idx = _v273_current_index(self)
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            cur = _v273_editor_snapshot(self)
            item = self.pm_items[idx]
            old_seq = str(item.get('sequence','')).strip()
            item.update(cur)
            if str(cur.get('sequence','')).strip() != old_seq:
                item['status'] = 'Edited'
            # Update only selected label; do not redraw output panes or batch tables while typing.
            try:
                label = _v273_display_name(self, item)
                old = self.pm_list.get(idx)
                if old != label:
                    self.pm_list.delete(idx)
                    self.pm_list.insert(idx, label)
                    _v273_select_list_index(self, idx)
            except Exception:
                pass
    finally:
        self._v273_editor_sync_busy = False
    try: _v273_schedule_autosave(self, 2500)
    except Exception: pass


def _v273_schedule_editor_sync(self, delay=250):
    try:
        if getattr(self, '_v273_editor_after_id', None):
            self.after_cancel(self._v273_editor_after_id)
        self._v273_editor_after_id = self.after(delay, lambda _self=self: _v273_light_editor_changed(_self))
    except Exception:
        pass


def _v273_schedule_autosave(self, delay=2200):
    if getattr(self, '_restoring_state', False):
        return
    try:
        if getattr(self, '_autosave_after_id', None):
            self.after_cancel(self._autosave_after_id)
        self._autosave_after_id = self.after(int(delay), self.save_autosave_state)
    except Exception:
        pass


def _v273_remove_pm_var_traces(self):
    # Stop old trace callbacks that triggered heavy refreshes and occasional STD fallback while typing.
    for attr, _key, _default in _V273_EDITOR_FIELDS:
        try:
            var = getattr(self, attr, None)
            if var is not None and hasattr(var, 'trace_info'):
                for info in list(var.trace_info()):
                    try:
                        mode = info[0]
                        cb = info[1]
                        var.trace_remove(mode, cb)
                    except Exception:
                        pass
        except Exception:
            pass


def _v273_patch_editor_widgets(self):
    try:
        _v273_remove_pm_var_traces(self)
        def bind_widget(w):
            try:
                if isinstance(w, (ttk.Entry, tk.Entry, ttk.Combobox)):
                    # Only bind widgets backed by the PM editor variables.
                    tv = str(w.cget('textvariable')) if 'textvariable' in w.keys() else ''
                    pm_vars = [str(getattr(self, a). _name) for a,_,_ in _V273_EDITOR_FIELDS if hasattr(getattr(self, a, None), '_name')]
                    if tv in pm_vars:
                        w.bind('<KeyRelease>', lambda e, _self=self: _v273_schedule_editor_sync(_self), add=False)
                        w.bind('<FocusOut>', lambda e, _self=self: _v273_light_editor_changed(_self), add=True)
                        w.bind('<<ComboboxSelected>>', lambda e, _self=self: _v273_light_editor_changed(_self), add=True)
            except Exception:
                pass
            for c in getattr(w, 'winfo_children', lambda: [])():
                bind_widget(c)
        bind_widget(self)
    except Exception:
        pass


def _v273_install_apply_change_button(self):
    try:
        target_parent = None
        for w in _v269_walk(self) if '_v269_walk' in globals() else []:
            try:
                if isinstance(w, (ttk.Button, tk.Button)) and str(w.cget('text')).strip() == 'Show setup' and w.winfo_ismapped():
                    target_parent = w.master
                    break
            except Exception:
                pass
        if target_parent is None:
            for w in _v269_walk(self) if '_v269_walk' in globals() else []:
                try:
                    if isinstance(w, (ttk.Button, tk.Button)) and str(w.cget('text')).strip() == 'Show setup':
                        target_parent = w.master
                        break
                except Exception:
                    pass
        if target_parent is not None:
            btn = getattr(self, '_v273_apply_change_button', None)
            if btn is None or not btn.winfo_exists():
                btn = ttk.Button(target_parent, text='Apply Change', command=lambda _self=self: _v273_apply_change(_self))
                self._v273_apply_change_button = btn
                btn.pack(side='left', padx=3)
            else:
                try: btn.configure(text='Apply Change', command=lambda _self=self: _v273_apply_change(_self))
                except Exception: pass
                try:
                    if not btn.winfo_manager(): btn.pack(side='left', padx=3)
                except Exception: pass
            try: btn.lift()
            except Exception: pass
        # Hide lower legacy Apply Plan / duplicate Apply Change buttons, keep only our promoted button.
        for w in _v269_walk(self) if '_v269_walk' in globals() else []:
            try:
                if isinstance(w, (ttk.Button, tk.Button)):
                    t = str(w.cget('text')).strip()
                    if t == 'Apply Plan' or (t == 'Apply Change' and w is not getattr(self, '_v273_apply_change_button', None)):
                        try: w.pack_forget()
                        except Exception: pass
                        try: w.grid_remove()
                        except Exception: pass
                    elif t == 'Apply Change':
                        w.configure(command=lambda _self=self: _v273_apply_change(_self))
            except Exception:
                pass
    except Exception:
        pass


def _v273_patch_buttons(self):
    try:
        for w in _v269_walk(self) if '_v269_walk' in globals() else []:
            try:
                if not isinstance(w, (ttk.Button, tk.Button)):
                    continue
                t = str(w.cget('text')).strip()
                if t == 'Generate / Update':
                    w.configure(command=lambda _self=self: _v273_generate(_self, force=False))
                elif t in ('Apply Plan','Apply Change'):
                    w.configure(command=lambda _self=self: _v273_apply_change(_self))
                elif t == 'Delete selected row':
                    w.configure(command=lambda _self=self: _v273_delete_selected_rows(_self))
                elif t == 'Add':
                    w.configure(command=lambda _self=self: _v273_add_item(_self))
                elif t.startswith('Duplic'):
                    w.configure(command=lambda _self=self: _v273_duplicate_item(_self))
                elif t == 'Delete':
                    w.configure(command=lambda _self=self: _v273_delete_item(_self))
            except Exception:
                pass
        _v273_install_apply_change_button(self)
    except Exception:
        pass


def _v273_patch_pm_list(self):
    try:
        if hasattr(self, 'pm_list'):
            self.pm_list.configure(selectmode=tk.BROWSE)
            self.pm_list.bind('<<ListboxSelect>>', lambda e, _self=self: _v273_pm_select(_self, e), add=False)
            self.pm_list.bind('<Double-Button-1>', lambda e, _self=self: _v273_pm_select(_self, e), add=False)
            self.pm_list.bind('<Return>', lambda e, _self=self: _v273_pm_select(_self, e), add=False)
            idx = _v273_current_index(self)
            _v273_set_active_index(self, idx if idx is not None else 0)
    except Exception:
        pass


def _v273_save_autosave_state(self):
    try:
        _v273_save_item(self, _v273_current_index(self), include_tables=True)
    except Exception:
        pass
    try:
        state = self._collect_state() if hasattr(self, '_collect_state') else {}
        state['app_version'] = APP_VERSION
        state['pm_items'] = list(getattr(self, 'pm_items', []))
        state['selected_pm_index'] = _v273_current_index(self) or 0
        self.state_file.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.state_file.with_suffix('.tmp')
        tmp.write_text(_v273_json.dumps(state, ensure_ascii=False, indent=2), encoding='utf-8')
        tmp.replace(self.state_file)
        self._autosave_after_id = None
    except Exception as exc:
        try: self._log(f'Autosave warning: {exc}\n')
        except Exception: pass


def _v273_export_project_manager(self):
    try:
        _v273_apply_change(self)
    except Exception:
        pass
    try:
        if 'pd' in globals():
            _pd = pd
        else:
            import pandas as _pd
        out = _v273_get_var(self, 'pm_project_output_dir', '') or _v273_get_var(self, 'outdir', '') or str(_v273_Path.cwd() / 'outputs')
        out = _v273_Path(out); out.mkdir(parents=True, exist_ok=True)
        xlsx = out / 'project_manager_selected_outputs.xlsx'
        idx = _v273_current_index(self)
        editor = _v273_editor_snapshot(self)
        with _pd.ExcelWriter(xlsx) as writer:
            _pd.DataFrame([editor]).to_excel(writer, sheet_name='00_EDITOR_SUMMARY', index=False)
            for sheet, attr in [('01_SELECTED_PLAN','pm_selected_plan_tree'),('02_SELECTED_MATERIALS','pm_selected_material_tree')]:
                rows = _v273_records_from_tree(getattr(self, attr, None))
                _pd.DataFrame(rows).to_excel(writer, sheet_name=sheet, index=False)
            tt = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
            _pd.DataFrame(_v273_records_from_tree(tt)).to_excel(writer, sheet_name='03_TOTAL_MATERIALS', index=False)
            ct = getattr(self, 'pm_selected_check_tree', None) or getattr(self, 'progress_tree', None)
            _pd.DataFrame(_v273_records_from_tree(ct)).to_excel(writer, sheet_name='04_SELECTED_CHECKLIST', index=False)
        state = {'app_version':APP_VERSION,'active_index':idx,'pm_items':getattr(self,'pm_items',[])}
        (out/'project_manager_state.json').write_text(_v273_json.dumps(state, ensure_ascii=False, indent=2), encoding='utf-8')
        try: messagebox.showinfo('Export', f'Project Manager export completed:\n{out}')
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Export', str(e))
        except Exception: pass


def _v273_after_build(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    _v273_patch_pm_list(self)
    _v273_patch_editor_widgets(self)
    _v273_patch_buttons(self)
    try:
        if hasattr(self, 'pm_items') and self.pm_items:
            idx = _v273_current_index(self)
            _v273_load_item(self, idx if idx is not None else 0, restore_outputs=True)
    except Exception:
        pass
    # No blanket after-cancel here; it can break user-visible UI jobs. The heavy editor traces were removed instead.


