def _v274b_patch_editor_widgets(self):
    try: _v273_remove_pm_var_traces(self)
    except Exception: pass
    try:
        names=[]
        for a,_,_ in _V273_EDITOR_FIELDS:
            v=getattr(self,a,None)
            if hasattr(v,'_name'): names.append(str(v._name))
        def bind(w):
            try:
                if isinstance(w,(ttk.Entry,tk.Entry,ttk.Combobox)):
                    tv=str(w.cget('textvariable')) if 'textvariable' in w.keys() else ''
                    if tv in names:
                        # Remove legacy KeyRelease redraws that cause visible typing delay.
                        try: w.unbind('<KeyRelease>')
                        except Exception: pass
                        w.bind('<FocusOut>',lambda e,_self=self:_v274_light_editor_changed(_self),add=False)
                        w.bind('<<ComboboxSelected>>',lambda e,_self=self:_v274_light_editor_changed(_self),add=False)
            except Exception: pass
            for c in getattr(w,'winfo_children',lambda:[])(): bind(c)
        bind(self)
    except Exception: pass


