# ======================= V2.0.75 APPLY BUTTON + FEATURE RESTORE FIX =======================
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v275_walk(w):
    try:
        yield w
        for c in w.winfo_children():
            yield from _v275_walk(c)
    except Exception:
        return


def _v275_is_button(w):
    try:
        return isinstance(w, (ttk.Button, tk.Button))
    except Exception:
        return False


def _v275_button_text(w):
    try:
        return str(w.cget('text')).strip()
    except Exception:
        return ''


def _v275_visible_buttons(self, text=None):
    out=[]
    for w in _v275_walk(self):
        try:
            if _v275_is_button(w) and w.winfo_ismapped():
                if text is None or _v275_button_text(w)==text:
                    out.append(w)
        except Exception:
            pass
    return out


def _v275_find_button(self, texts, visible_first=True):
    if isinstance(texts, str): texts={texts}
    else: texts=set(texts)
    candidates=[]
    for w in _v275_walk(self):
        try:
            if _v275_is_button(w) and _v275_button_text(w) in texts:
                candidates.append(w)
        except Exception:
            pass
    if visible_first:
        for w in candidates:
            try:
                if w.winfo_ismapped(): return w
            except Exception:
                pass
    return candidates[0] if candidates else None


def _v275_parent_near(self, texts):
    b=_v275_find_button(self, texts, True)
    try:
        if b is not None: return b.master
    except Exception:
        pass
    b=_v275_find_button(self, texts, False)
    try:
        if b is not None: return b.master
    except Exception:
        pass
    return None


def _v275_button_in_parent(parent, text):
    try:
        for c in parent.winfo_children():
            if _v275_is_button(c) and _v275_button_text(c)==text:
                return c
    except Exception:
        pass
    return None


def _v275_ensure_button(parent, text, command, padx=3):
    if parent is None: return None
    btn=_v275_button_in_parent(parent, text)
    try:
        if btn is None or not btn.winfo_exists():
            btn=ttk.Button(parent, text=text, command=command)
            btn.pack(side='left', padx=padx)
        else:
            try: btn.configure(command=command)
            except Exception: pass
            if not btn.winfo_ismapped():
                try: btn.pack(side='left', padx=padx)
                except Exception:
                    try: btn.grid()
                    except Exception: pass
        try: btn.lift()
        except Exception: pass
        return btn
    except Exception:
        return None


def _v275_get_var_value(self, attr, default=''):
    try:
        v=getattr(self, attr, None)
        if hasattr(v, 'get'): return str(v.get())
    except Exception:
        pass
    return str(default or '')


def _v275_set_var(self, attr, value):
    try:
        v=getattr(self, attr, None)
        if hasattr(v, 'set'):
            v.set(str(value))
            return
    except Exception:
        pass
    try:
        setattr(self, attr, tk.StringVar(value=str(value)))
    except Exception:
        pass


def _v275_ensure_outvars(self):
    try:
        from pathlib import Path
        base = Path(_v275_get_var_value(self, 'outdir', str(ROOT/'outputs')))
    except Exception:
        from pathlib import Path
        base = Path('outputs')
    try:
        if not hasattr(self, 'project_outdir') or not hasattr(getattr(self,'project_outdir',None),'get'):
            self.project_outdir = tk.StringVar(value=str(base/'project_manager_exports'))
    except Exception:
        pass
    try:
        if not hasattr(self, 'pm_project_output_dir') or not hasattr(getattr(self,'pm_project_output_dir',None),'get'):
            self.pm_project_output_dir = self.project_outdir
    except Exception:
        pass
    try:
        if not hasattr(self, 'batch_outdir') or not hasattr(getattr(self,'batch_outdir',None),'get'):
            self.batch_outdir = tk.StringVar(value=str(base/'batch_manager_exports'))
    except Exception:
        pass


def _v275_open_dir(path):
    try:
        import os, sys, subprocess
        p=str(path or '') or 'outputs'
        os.makedirs(p, exist_ok=True)
        if sys.platform.startswith('win'):
            os.startfile(p)
        elif sys.platform == 'darwin':
            subprocess.Popen(['open', p])
        else:
            subprocess.Popen(['xdg-open', p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def _v275_browse_dir(self, var, title):
    try:
        start = var.get() if hasattr(var, 'get') and var.get() else _v275_get_var_value(self, 'outdir', str(ROOT/'outputs'))
        p = filedialog.askdirectory(title=title, initialdir=start)
        if p: var.set(p)
    except Exception:
        pass


