        if cmd:
            _v275_ensure_button(parent, 'Edit Unit name', cmd)
        elif '_v269_open_unit_picker' in globals():
            _v275_ensure_button(parent, 'Edit Unit name', lambda _self=self: _v269_open_unit_picker(_self))


