def _v275_patch_pm_list(self):
    try:
        if hasattr(self, 'pm_list'):
            self.pm_list.configure(selectmode=tk.BROWSE)
            if '_v274_pm_select' in globals():
                self.pm_list.bind('<<ListboxSelect>>', lambda e, _self=self: _v274_pm_select(_self, e), add=False)
                self.pm_list.bind('<Double-Button-1>', lambda e, _self=self: _v274_pm_select(_self, e), add=False)
                self.pm_list.bind('<Return>', lambda e, _self=self: _v274_pm_select(_self, e), add=False)
            elif '_v273_pm_select' in globals():
                self.pm_list.bind('<<ListboxSelect>>', lambda e, _self=self: _v273_pm_select(_self, e), add=False)
                self.pm_list.bind('<Double-Button-1>', lambda e, _self=self: _v273_pm_select(_self, e), add=False)
                self.pm_list.bind('<Return>', lambda e, _self=self: _v273_pm_select(_self, e), add=False)
    except Exception:
        pass


def _v275_restore_all_features(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    _v275_ensure_outvars(self)
    _v275_configure_existing_buttons(self)
    _v275_install_project_controls(self)
    _v275_install_peptide_item_controls(self)
    _v275_install_selected_plan_controls(self)
    _v275_install_batch_controls(self)
    _v275_patch_pm_list(self)


def _v275_on_tab_change(self, event=None):
    try: _v275_restore_all_features(self)
    except Exception: pass


