# --- V2.0.75b recursion-safe Generate/Apply core ---
def _v275_apply_change_core(self, save_state=True, refresh_batch=True):
    if getattr(self, '_v275_apply_busy', False): return
    self._v275_apply_busy = True
    try:
        try: _v265_cancel_legacy_after(self)
        except Exception: pass
        try: _v265_recalc_visible_plan(self)
        except Exception:
            try: _v265_write_selected_plan(self, preserve_visible=True)
            except Exception: pass
        try: _v269_refresh_materials_total(self)
        except Exception:
            try: _v265_refresh_materials_total(self)
            except Exception: pass
        try: _v269_refresh_checklist(self)
        except Exception:
            try: _v265_refresh_checklist(self)
            except Exception: pass
        if refresh_batch:
            try: self.after_idle(lambda _self=self: _v265_refresh_batch(_self))
            except Exception: pass
        try:
            if '_v269_bind_selected_plan_editor' in globals(): _v269_bind_selected_plan_editor(self)
        except Exception: pass
        idx = _v274_idx(self) if '_v274_idx' in globals() else (_v273_current_index(self) if '_v273_current_index' in globals() else None)
        if save_state and idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            item = self.pm_items[idx]
            try: item.update(_v274_editor(self) if '_v274_editor' in globals() else _v273_editor_snapshot(self))
            except Exception: pass
            item['generated_sequence'] = item.get('generated_sequence') or item.get('sequence','')
            item['manual_plan'] = True
            try: item.update(_v274_tree_payload(self))
            except Exception:
                try: item.update({
                    'selected_plan_records': _v273_records_from_tree(getattr(self,'pm_selected_plan_tree',None)),
                    'selected_materials_records': _v273_records_from_tree(getattr(self,'pm_selected_material_tree',None)),
                })
                except Exception: pass
        try:
            if '_v274_refresh_list' in globals(): _v274_refresh_list(self, idx, False)
            elif '_v273_refresh_list' in globals(): _v273_refresh_list(self, idx, False)
        except Exception: pass
        try: _v273_schedule_autosave(self, 2000)
        except Exception: pass
    finally:
        self._v275_apply_busy = False


def _v275_generate_core(self, force=False):
    if getattr(self, '_v275_gen_busy', False): return
    self._v275_gen_busy = True
    try:
        try: _v265_cancel_legacy_after(self)
        except Exception: pass
        idx = _v274_idx(self) if '_v274_idx' in globals() else (_v273_current_index(self) if '_v273_current_index' in globals() else None)
        if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])): return
        cur = _v274_editor(self) if '_v274_editor' in globals() else _v273_editor_snapshot(self)
        seq = str(cur.get('sequence','')).strip()
        item = self.pm_items[idx]
        old_generated = str(item.get('generated_sequence','')).strip()
        item.update(cur)
        if not seq:
            try: _v274_clear_outputs(self)
            except Exception:
                try: _v273_clear_outputs(self)
                except Exception: pass
            for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','generated_sequence','manual_plan'):
                item.pop(k, None)
            item['status'] = 'Ready'
            try: _v274_save_item(self, idx, True)
            except Exception: pass
            return
        same_seq = (old_generated == seq)
        has_plan = bool(item.get('selected_plan_records'))
        if (not force) and same_seq and has_plan and item.get('manual_plan'):
            try: _v274_restore_outputs(self, item)
            except Exception:
                try: _v273_restore_outputs(self, item)
                except Exception: pass
            _v275_apply_change_core(self, save_state=True, refresh_batch=True)
        else:
            units = _v273_units_from_sequence(seq) if '_v273_units_from_sequence' in globals() else []
            if not units:
                try: _v274_clear_outputs(self)
                except Exception:
                    try: _v273_clear_outputs(self)
                    except Exception: pass
                for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','manual_plan'):
                    item.pop(k, None)
            else:
                try: _v274_write_units_to_plan(self, units)
                except Exception: _v273_write_units_to_plan(self, units)
                item['generated_sequence'] = seq
                item.pop('manual_plan', None)
                _v275_apply_change_core(self, save_state=True, refresh_batch=True)
        item['status'] = 'Calculated' if seq else 'Ready'
        try: _v274_save_item(self, idx, True)
        except Exception: pass
        try: _v274_refresh_list(self, idx, False)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v275_gen_busy = False

# Rebind all public and legacy aliases to recursion-safe core implementations.
try:
    _v275_apply_change = _v275_apply_change_core
    _v275_generate = _v275_generate_core
    _v274_apply_change = _v275_apply_change_core
    _v273_apply_change = _v275_apply_change_core
    _v269_apply_plan = _v275_apply_change_core
    _v249_apply_plan = _v275_apply_change_core
    _v272_apply_change = _v275_apply_change_core
    _v274_generate = _v275_generate_core
    _v273_generate = _v275_generate_core
    _v269_generate_selected = lambda self, _force=False: _v275_generate_core(self, False)
    _v272_generate_selected = lambda self, _force=False: _v275_generate_core(self, False)
    _v249_generate = lambda self, _force=False: _v275_generate_core(self, False)
    SPPSGui.pm_generate_selected = lambda self: _v275_generate_core(self, False)
    SPPSGui.pm_calculate_all = lambda self: _v275_generate_core(self, False)
    SPPSGui.pm_apply_plan = _v275_apply_change_core
    SPPSGui.apply_plan_mw_density = _v275_apply_change_core
except Exception:
    pass
# --- END V2.0.75b ---

# --- V2.0.75c startup-compatible Add wrapper ---
def _v275_add_item_compat(self, item=None):
    try:
        if '_v274_add_item' in globals(): return _v274_add_item(self, item)
        if '_v273_add_item' in globals(): return _v273_add_item(self, item)
    except TypeError:
        try:
            # Fall back to old no-arg path, then merge the provided item if needed.
            res = _v274_add_item(self) if '_v274_add_item' in globals() else _v273_add_item(self)
            if item is not None and getattr(self, 'pm_items', None):
                self.pm_items[-1].update(dict(item))
                try: _v274_load_item(self, len(self.pm_items)-1, restore_outputs=False)
                except Exception: pass
            return res
        except Exception as e:
            try: messagebox.showerror('Add peptide', str(e))
            except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Add peptide', str(e))
        except Exception: pass

try:
    _v275_add_item = _v275_add_item_compat
    SPPSGui.pm_add_peptide = _v275_add_item_compat
except Exception:
    pass
# --- END V2.0.75c ---

# --- V2.0.75d force-visible user controls in the correct visible PM action rows ---
def _v275d_visible_button_in_parent(parent, text):
    try:
        for c in parent.winfo_children():
            if _v275_is_button(c) and _v275_button_text(c)==text and c.winfo_ismapped(): return c
    except Exception: pass
    return None


def _v275d_action_parent(self):
    # Prefer the visible row containing Show setup / Export / Load Project because that is where the user expects Apply.
    for key in ('Show setup','Export','Load Project','Import Output'):
        b=_v275_find_button(self, key, True)
        try:
            if b is not None and b.winfo_ismapped(): return b.master
        except Exception: pass
    return _v275_parent_near(self, ['Generate / Update','Show setup','Export'])


def _v275d_ensure_button(parent, text, command, padx=3):
    if parent is None: return None
    btn=_v275d_visible_button_in_parent(parent, text)
    if btn is not None:
        try: btn.configure(command=command)
        except Exception: pass
        return btn
    # Reuse a hidden same-text button only if it is in this parent and can be packed visibly; otherwise make a fresh button.
    hidden=None
    try:
        for c in parent.winfo_children():
            if _v275_is_button(c) and _v275_button_text(c)==text:
                hidden=c; break
    except Exception: pass
    try:
        if hidden is not None:
            try: hidden.configure(command=command)
            except Exception: pass
            try: hidden.pack_forget()
            except Exception: pass
            try: hidden.grid_remove()
            except Exception: pass
            try: hidden.place_forget()
            except Exception: pass
        btn=ttk.Button(parent, text=text, command=command)
        btn.pack(side='left', padx=padx)
        return btn
    except Exception:
        return None


def _v275d_install_project_controls(self):
    _v275_ensure_outvars(self)
    p=_v275d_action_parent(self)
    if p is None: return
    _v275d_ensure_button(p, 'Apply Change', lambda _self=self: _v275_apply_change_core(_self))
    _v275d_ensure_button(p, 'Save Project', lambda _self=self: _v275_save_project(_self, True))
    if not getattr(self,'_v275d_project_output_controls',False):
        try:
            ttk.Label(p,text='Project output').pack(side='left',padx=(8,2))
            ttk.Entry(p,textvariable=self.project_outdir,width=24).pack(side='left',padx=2)
            ttk.Button(p,text='Browse',command=lambda _self=self:_v275_browse_dir(_self,_self.project_outdir,'Choose Project output')).pack(side='left',padx=2)
            ttk.Button(p,text='Open Output',command=lambda _self=self:_v275_open_dir(_self.project_outdir.get())).pack(side='left',padx=2)
            self._v275d_project_output_controls=True
        except Exception: pass


def _v275d_install_peptide_delete(self):
    p=_v275_parent_near(self,['Add','Duplicate'])
    if p is None: return
    # Force a fresh visible Delete item button because the legacy Delete button can remain width=1 even with pack manager.
    has=False
    try:
        for c in p.winfo_children():
            if _v275_is_button(c) and _v275_button_text(c) in ('Delete item','Delete peptide') and c.winfo_ismapped():
                c.configure(command=lambda _self=self:_v275_delete_item(_self)); has=True
    except Exception: pass
    if not has:
        try:
            ttk.Button(p,text='Delete item',command=lambda _self=self:_v275_delete_item(_self)).pack(side='left',padx=2)
        except Exception: pass


