def _v275e_install_peptide_item_controls(self):
    p=_v275_parent_near(self,['Add','Duplicate'])
    if p is None: return
    try:
        for c in p.winfo_children():
            if _v275_is_button(c):
                t=_v275_button_text(c)
                if t=='Add': c.configure(width=5, command=lambda _self=self:_v275_add_item_compat(_self))
                elif t.startswith('Duplic'): c.configure(width=9, command=lambda _self=self:_v275_duplicate_item(_self))
                elif t in ('Delete','Delete item','Delete peptide'): c.configure(width=7, command=lambda _self=self:_v275_delete_item(_self))
    except Exception: pass
    # Use a second row inside the peptide-items panel if the horizontal row is too narrow.
    try:
        if not getattr(self,'_v275e_item_delete_row',None) or not self._v275e_item_delete_row.winfo_exists():
            row=ttk.Frame(p.master); self._v275e_item_delete_row=row; row.pack(fill='x', padx=2, pady=(2,2))
            ttk.Button(row,text='Delete item',width=12,command=lambda _self=self:_v275_delete_item(_self)).pack(side='left',padx=2)
        else:
            row=self._v275e_item_delete_row
            if not row.winfo_ismapped(): row.pack(fill='x', padx=2, pady=(2,2))
    except Exception: pass


