        row=ttk.Frame(parent.master); row.pack(fill='x', padx=2, pady=(2,2)); self._v275f_batch_row=row
        ttk.Button(row,text='Export batch tables',command=lambda _self=self:_v275_export_batch(_self)).pack(side='left',padx=2)
        ttk.Label(row,text='Batch output').pack(side='left',padx=(8,2))
