# --- V2.0.75j lazy-on-update control restore for widgets created/mapped late ---
def _v275j_lazy_controls(self):
    if getattr(self, '_v275j_restoring', False): return
    self._v275j_restoring=True
    try:
        if not getattr(self, '_v275j_project_done', False):
            _v275i_project_controls(self)
            try:
                p=_v275d_action_parent(self)
                self._v275j_project_done = bool(p and any(_v275_is_button(c) and _v275_button_text(c)=='Save Project' and c.winfo_ismapped() for c in p.winfo_children()))
            except Exception: pass
        # Batch controls are only installed once the Batch tab is mapped.
        try: _v275i_batch_controls(self)
        except Exception: pass
    finally:
        self._v275j_restoring=False
try:
    _v275j_old_update = SPPSGui.update
    def _v275j_update(self, *args, **kwargs):
        res = _v275j_old_update(self, *args, **kwargs)
        try: _v275j_lazy_controls(self)
        except Exception: pass
        return res
    SPPSGui.update = _v275j_update
except Exception: pass
try:
    _v275j_old_update_idletasks = SPPSGui.update_idletasks
    def _v275j_update_idletasks(self, *args, **kwargs):
        res = _v275j_old_update_idletasks(self, *args, **kwargs)
        try: _v275j_lazy_controls(self)
        except Exception: pass
        return res
    SPPSGui.update_idletasks = _v275j_update_idletasks
except Exception: pass
# --- END V2.0.75j ---

# ======================= V2.0.76 FINAL UI DEDUPE + BLANK START + GENERATE FIX =======================
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

# This final patch intentionally does not remove existing user-facing capabilities.
# It normalizes the visible UI so each action appears once, keeps Project output in
# Setup defaults > Output, fixes blank startup, and makes Generate/Apply Change use
# the active peptide sequence instead of stale/default STD state.

def _v276_walk(root):
    try:
        yield root
        for c in root.winfo_children():
            yield from _v276_walk(c)
    except Exception:
        return


def _v276_is_button(w):
    try:
        return w.winfo_class() in ('TButton','Button')
    except Exception:
        return False


def _v276_is_label(w):
    try:
        return w.winfo_class() in ('TLabel','Label')
    except Exception:
        return False


def _v276_text(w):
    try:
        return str(w.cget('text')).strip()
    except Exception:
        return ''


def _v276_hide(w):
    try: w.pack_forget()
    except Exception: pass
    try: w.grid_remove()
    except Exception: pass
    try: w.place_forget()
    except Exception: pass


def _v276_show_pack(w, **kw):
    try:
        w.pack(**kw)
    except Exception:
        try: w.grid()
        except Exception: pass


def _v276_hide_parent_tail_from_label(parent, label_text):
    """Hide label + subsequent widgets in the same row/container. Used for duplicate ad-hoc output controls."""
    try:
        children = list(parent.winfo_children())
        idxs = [i for i,c in enumerate(children) if _v276_is_label(c) and _v276_text(c) == label_text]
        if not idxs:
            return
        for start in idxs:
            for c in children[start:]:
                _v276_hide(c)
    except Exception:
        pass


def _v276_find_visible_button(self, text):
    for w in _v276_walk(self):
        try:
            if _v276_is_button(w) and _v276_text(w) == text and w.winfo_ismapped():
                return w
        except Exception:
            pass
    return None


def _v276_find_button(self, text):
    for w in _v276_walk(self):
        try:
            if _v276_is_button(w) and _v276_text(w) == text:
                return w
        except Exception:
            pass
    return None


def _v276_action_parent(self):
    # Global actions row containing Show setup is the intended location for Apply Change.
    for key in ('Show setup','Hide setup','Export','Import Output','Load Project'):
        b = _v276_find_visible_button(self, key) or _v276_find_button(self, key)
        try:
            if b is not None:
                return b.master
        except Exception:
            pass
    return None


def _v276_selected_plan_toolbar_parent(self):
    # Reuse the original Selected Plan toolbar parent if present.
    for key in ('Delete selected row','Edit Unit name'):
        b = _v276_find_button(self, key)
        try:
            if b is not None:
                return b.master
        except Exception:
            pass
    try:
        return getattr(self, 'pm_selected_plan_tree').master
    except Exception:
        return None


def _v276_batch_parent(self):
    for key in ('Export batch tables','Refresh now','Sync from Project Manager','Generate Batch Workspace'):
        b = _v276_find_visible_button(self, key) or _v276_find_button(self, key)
        try:
            if b is not None:
                return b.master
        except Exception:
            pass
    return None


def _v276_ensure_outvars(self):
    import os as _os
    try:
        if hasattr(self, 'outdir') and hasattr(self.outdir, 'get'):
            base = self.outdir.get()
        else:
            base = _os.path.join(_os.getcwd(), 'outputs')
    except Exception:
        base = _os.path.join(_os.getcwd(), 'outputs')
    try:
        if not hasattr(self, 'outdir') or not hasattr(self.outdir, 'get'):
            self.outdir = tk.StringVar(value=base)
    except Exception:
        pass
    try:
        # Keep old project_outdir references aliased to the Setup defaults > Output variable.
        self.project_outdir = self.outdir
        self.pm_project_output_dir = self.outdir
    except Exception:
        pass
    try:
        if not hasattr(self, 'batch_outdir') or not hasattr(self.batch_outdir, 'get'):
            self.batch_outdir = tk.StringVar(value=_os.path.join(base, 'batch_manager'))
    except Exception:
        pass


def _v276_browse_outdir(self):
    try:
        return self.browse_outdir()
    except Exception:
        try:
            from tkinter import filedialog
            p = filedialog.askdirectory(title='Choose output folder')
            if p: self.outdir.set(p)
        except Exception:
            pass


def _v276_open_outdir(self):
    try:
        return self.open_output()
    except Exception:
        try:
            import os, subprocess, sys
            p = self.outdir.get()
            if sys.platform.startswith('win'):
                os.startfile(p)
            elif sys.platform == 'darwin':
                subprocess.Popen(['open', p])
            else:
                subprocess.Popen(['xdg-open', p])
        except Exception:
            pass


def _v276_browse_batch(self):
    try:
        from tkinter import filedialog
        p = filedialog.askdirectory(title='Choose Batch output')
        if p: self.batch_outdir.set(p)
    except Exception:
        pass


def _v276_open_batch(self):
    try:
        import os, subprocess, sys
        p = self.batch_outdir.get()
        if sys.platform.startswith('win'):
            os.startfile(p)
        elif sys.platform == 'darwin':
            subprocess.Popen(['open', p])
        else:
            subprocess.Popen(['xdg-open', p])
    except Exception:
        pass


def _v276_save_project(self, show=True):
    try:
        if '_v275_save_project' in globals():
            return _v275_save_project(self, show)
        if '_v274_export_project_manager' in globals():
            return _v274_export_project_manager(self)
    except Exception as e:
        try: messagebox.showerror('Save Project', str(e))
        except Exception: pass


def _v276_apply_change(self, save_state=True, refresh_batch=True):
    try:
        if '_v275_apply_change_core' in globals():
            return _v275_apply_change_core(self, save_state, refresh_batch)
        if '_v274_apply_change' in globals():
            return _v274_apply_change(self, save_state, refresh_batch)
    except Exception as e:
        try: messagebox.showerror('Apply Change', str(e))
        except Exception: pass


def _v276_units_from_sequence(seq):
    try:
        if '_v273_units_from_sequence' in globals():
            return _v273_units_from_sequence(seq)
    except Exception:
        pass
    # conservative fallback parser; strips caps and C-terminal modifiers.
    s = str(seq or '').strip()
    import re as _re
    s = _re.sub(r'(?i)^\s*Ac[-_ ]*', '', s)
    s = _re.sub(r'(?i)[-_ ]*(NH2|CONH2|COOH|OH)\s*$', '', s)
    aa = {'A':'Fmoc-Ala-OH','R':'Fmoc-Arg(Pbf)-OH','N':'Fmoc-Asn(Trt)-OH','D':'Fmoc-Asp(OtBu)-OH','C':'Fmoc-Cys(Trt)-OH','Q':'Fmoc-Gln(Trt)-OH','E':'Fmoc-Glu(OtBu)-OH','G':'Fmoc-Gly-OH','H':'Fmoc-His(Trt)-OH','I':'Fmoc-Ile-OH','L':'Fmoc-Leu-OH','K':'Fmoc-Lys(Boc)-OH','M':'Fmoc-Met-OH','F':'Fmoc-Phe-OH','P':'Fmoc-Pro-OH','S':'Fmoc-Ser(tBu)-OH','T':'Fmoc-Thr(tBu)-OH','W':'Fmoc-Trp(Boc)-OH','Y':'Fmoc-Tyr(tBu)-OH','V':'Fmoc-Val-OH'}
    return [aa[ch] for ch in reversed(s.upper()) if ch in aa]


def _v276_current_idx(self):
    try:
        if '_v274_idx' in globals():
            return _v274_idx(self)
    except Exception:
        pass
    try:
        sel = list(self.pm_list.curselection())
        return int(sel[0]) if sel else 0
    except Exception:
        return 0 if getattr(self, 'pm_items', None) else None


def _v276_editor_snapshot(self):
    try:
        if '_v274_editor' in globals():
            return _v274_editor(self)
    except Exception:
        pass
    def g(a, d=''):
        try: return str(getattr(self,a).get()).strip()
        except Exception: return d
    return {'project':g('pm_project','Project-001'),'peptide':g('pm_peptide','Peptide-001'),'sequence':g('pm_sequence',''),'scale':g('pm_scale','0.2'),'resin':g('pm_resin','Rink Amide AM'),'loading':g('pm_loading','0.8'),'lot':g('pm_lot',''),'chemistry':g('pm_chemistry','DIC/HOBt'),'copies':g('pm_copies','1')}


def _v276_save_item(self, idx=None, include_tables=True):
    try:
        if idx is None: idx = _v276_current_idx(self)
        if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])): return None
        item = self.pm_items[idx]
        item.update(_v276_editor_snapshot(self))
        if include_tables:
            if '_v274_tree_payload' in globals():
                item.update(_v274_tree_payload(self))
            else:
                item['selected_plan_records'] = _v274_records(getattr(self,'pm_selected_plan_tree',None)) if '_v274_records' in globals() else []
            if item.get('selected_plan_records'):
                item['manual_plan'] = True
        return idx
    except Exception:
        return None


def _v276_clear_outputs(self):
    try:
        if '_v274_clear_outputs' in globals(): return _v274_clear_outputs(self)
    except Exception:
        pass
    for attr in ('pm_selected_plan_tree','pm_selected_material_tree','pm_total_tree','pm_selected_total_tree','pm_selected_check_tree','progress_tree'):
        try:
            t = getattr(self, attr, None)
            if t is not None:
                for iid in t.get_children(): t.delete(iid)
        except Exception:
            pass
    try:
        txt = getattr(self,'pm_selected_check_text',None)
        if txt: txt.delete('1.0','end')
    except Exception:
        pass


def _v276_write_units(self, units):
    try:
        if '_v274_write_units_to_plan' in globals():
            return _v274_write_units_to_plan(self, units)
    except Exception:
        pass
    try:
        import pandas as _pd
        cols = list(globals().get('_V265_PLAN_COLS', [])) or list(getattr(self,'pm_selected_plan_tree')['columns'])
        rows=[]
        for i,u in enumerate(units,1):
            r={c:'' for c in cols}; r['No']=str(i); r['Unit name']=u; rows.append(r)
        if '_v265_write_selected_plan' in globals():
            return _v265_write_selected_plan(self, _pd.DataFrame(rows, columns=cols), preserve_visible=False)
        tree=getattr(self,'pm_selected_plan_tree',None)
        for iid in tree.get_children(): tree.delete(iid)
        for r in rows: tree.insert('', 'end', values=[r.get(c,'') for c in cols])
    except Exception:
        pass


def _v276_generate(self, force=False):
    if getattr(self, '_v276_gen_busy', False): return
    self._v276_gen_busy = True
    try:
        try:
            if '_v265_cancel_legacy_after' in globals(): _v265_cancel_legacy_after(self)
        except Exception:
            pass
        idx = _v276_current_idx(self)
        if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])):
            return
        cur = _v276_editor_snapshot(self)
        seq = str(cur.get('sequence','')).strip()
        item = self.pm_items[idx]
        # If the editor sequence differs from the last generated sequence, force a fresh plan.
        old_generated = str(item.get('generated_sequence','')).strip()
        item.update(cur)
        if not seq:
            _v276_clear_outputs(self)
            for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','generated_sequence','manual_plan'):
                item.pop(k, None)
            item['status'] = 'Ready'
            _v276_save_item(self, idx, True)
            try: _v274_refresh_list(self, idx, False)
            except Exception: pass
            return
        existing_plan = bool(item.get('selected_plan_records')) or bool(_v274_records(getattr(self,'pm_selected_plan_tree',None)) if '_v274_records' in globals() else [])
        if (not force) and old_generated == seq and item.get('manual_plan') and existing_plan:
            # Keep the user's manually edited plan; just recalculate linked views.
            try:
                if item.get('selected_plan_records') and '_v274_restore_outputs' in globals(): _v274_restore_outputs(self, item)
            except Exception: pass
            _v276_apply_change(self, True, True)
        else:
            units = _v276_units_from_sequence(seq)
            if not units:
                _v276_clear_outputs(self)
                for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','manual_plan'):
                    item.pop(k, None)
                item['status'] = 'Ready'
            else:
                _v276_write_units(self, units)
                item['generated_sequence'] = seq
                item.pop('manual_plan', None)
                item['status'] = 'Calculated'
                _v276_apply_change(self, True, True)
        _v276_save_item(self, idx, True)
        try: _v274_refresh_list(self, idx, False)
        except Exception: pass
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
    finally:
        self._v276_gen_busy = False


def _v276_item_changed_light(self):
    if getattr(self, '_pm_loading_editor', False): return
    idx = _v276_current_idx(self)
    if idx is None or idx < 0 or idx >= len(getattr(self, 'pm_items', [])): return
    try:
        cur = _v276_editor_snapshot(self)
        item = self.pm_items[idx]
        old_seq = str(item.get('sequence','')).strip()
        new_seq = str(cur.get('sequence','')).strip()
        item.update(cur)
        # Mark saved plan stale when sequence changes; do not regenerate while typing.
        if new_seq != old_seq and new_seq != str(item.get('generated_sequence','')).strip():
            item.pop('manual_plan', None)
        try:
            label = _v273_display_name(self, item) if '_v273_display_name' in globals() else f"{item.get('project','')} | {item.get('peptide','')}"
            self.pm_list.delete(idx); self.pm_list.insert(idx, label); self.pm_list.selection_set(idx); self.pm_list.activate(idx)
        except Exception:
            pass
    except Exception:
        pass


def _v276_patch_editor_events(self):
    # Keep input light. No table redraw on every key stroke.
    try:
        for w in _v276_walk(self):
            if w.winfo_class() in ('TEntry','Entry','TCombobox'):
                try:
                    var = str(w.cget('textvariable'))
                    if var and any(str(getattr(self,a,'')).split()[-1] in var for a in ('pm_project','pm_peptide','pm_sequence','pm_scale','pm_resin','pm_loading','pm_lot','pm_chemistry','pm_copies')):
                        w.bind('<FocusOut>', lambda e,_self=self: _v276_item_changed_light(_self), add=False)
                        w.bind('<<ComboboxSelected>>', lambda e,_self=self: _v276_item_changed_light(_self), add=False)
                except Exception:
                    pass
    except Exception:
        pass


def _v276_pm_select(self, event=None):
    try:
        new_idx = int(list(self.pm_list.curselection())[0])
    except Exception:
        new_idx = _v276_current_idx(self)
    old_idx = getattr(self, '_v276_active_index', None)
    if old_idx is None:
        old_idx = _v276_current_idx(self)
    try:
        if old_idx is not None and old_idx != new_idx: _v276_save_item(self, old_idx, True)
    except Exception:
        pass
    try:
        if '_v274_load_item' in globals(): _v274_load_item(self, new_idx, True)
        elif '_v273_load_item' in globals(): _v273_load_item(self, new_idx, True)
    except Exception:
        pass
    self._v276_active_index = new_idx


def _v276_add_item(self, item=None):
    try: _v276_save_item(self, _v276_current_idx(self), True)
    except Exception: pass
    try:
        idx = len(getattr(self, 'pm_items', []))
        base = _v276_editor_snapshot(self)
        if item:
            base.update(dict(item))
        else:
            base.update({'project': f'Project-{idx+1:03d}', 'peptide': f'Peptide-{idx+1:03d}', 'sequence': '', 'lot': ''})
        for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','manual_plan','generated_sequence'):
            base.pop(k, None)
        base['status'] = 'Ready'
        self.pm_items.append(base)
        if '_v274_refresh_list' in globals(): _v274_refresh_list(self, idx, False)
        _v276_load_item(self, idx, clear_if_no_outputs=True)
    except Exception as e:
        try: messagebox.showerror('Add peptide', str(e))
        except Exception: pass


def _v276_duplicate_item(self):
    try:
        idx = _v276_current_idx(self)
        _v276_save_item(self, idx, True)
        new = dict(self.pm_items[idx])
        n = len(self.pm_items) + 1
        new['project'] = f"{new.get('project','Project')}_copy"
        new['peptide'] = f"{new.get('peptide','Peptide')}_copy"
        try: new['lot'] = self._generate_lot_no()
        except Exception: pass
        self.pm_items.append(new)
        ni = len(self.pm_items) - 1
        if '_v274_refresh_list' in globals(): _v274_refresh_list(self, ni, False)
        _v276_load_item(self, ni, clear_if_no_outputs=False)
    except Exception as e:
        try: messagebox.showerror('Duplicate peptide', str(e))
        except Exception: pass


def _v276_delete_item(self):
    try:
        idx = _v276_current_idx(self)
        if idx is None or idx < 0 or idx >= len(self.pm_items): return
        del self.pm_items[idx]
        if not self.pm_items:
            _v276_add_item(self); return
        ni = min(idx, len(self.pm_items)-1)
        if '_v274_refresh_list' in globals(): _v274_refresh_list(self, ni, False)
        _v276_load_item(self, ni, clear_if_no_outputs=False)
    except Exception as e:
        try: messagebox.showerror('Delete peptide', str(e))
        except Exception: pass


def _v276_load_item(self, idx, clear_if_no_outputs=False):
    try:
        if idx is None or idx < 0 or idx >= len(getattr(self,'pm_items',[])): return
        if '_v274_load_item' in globals():
            _v274_load_item(self, idx, True)
        else:
            item = self.pm_items[idx]
            self._pm_loading_editor = True
            for attr,key,default in globals().get('_V273_EDITOR_FIELDS',[]):
                try: getattr(self,attr).set(item.get(key,default))
                except Exception: pass
            self._pm_loading_editor = False
        self._v276_active_index = idx
        if clear_if_no_outputs and not self.pm_items[idx].get('selected_plan_records'):
            _v276_clear_outputs(self)
    except Exception:
        try: self._pm_loading_editor = False
        except Exception: pass


def _v276_delete_selected_rows(self):
    try:
        if '_v274_delete_selected_rows' in globals():
            return _v274_delete_selected_rows(self)
        if '_v273_delete_selected_rows' in globals():
            return _v273_delete_selected_rows(self)
    except Exception as e:
        try: messagebox.showerror('Delete selected row', str(e))
        except Exception: pass


def _v276_export_project(self):
    try:
        if '_v274_export_project_manager' in globals():
            return _v274_export_project_manager(self)
        if '_v271_export_project' in globals():
            return _v271_export_project(self)
    except Exception as e:
        try: messagebox.showerror('Export error', str(e))
        except Exception: pass


def _v276_export_batch(self):
    try:
        if '_v271_export_batch' in globals(): return _v271_export_batch(self)
        if '_v29_export_batch_tables' in globals(): return _v29_export_batch_tables(self)
    except Exception as e:
        try: messagebox.showerror('Batch export error', str(e))
        except Exception: pass


def _v276_cancel_legacy_after(self):
    # Old restore patches re-add duplicate buttons after 0.5~8 s.  Cancel them once after build.
    try:
        ids = list(self.tk.call('after', 'info'))
        for aid in ids:
            try: self.after_cancel(aid)
            except Exception: pass
    except Exception:
        pass


def _v276_hide_duplicate_output_controls(self):
    # Project output belongs only to Setup defaults > Output tab as Output folder.
    for w in list(_v276_walk(self)):
        try:
            if _v276_is_label(w) and _v276_text(w) == 'Project output':
                _v276_hide_parent_tail_from_label(w.master, 'Project output')
            if _v276_is_label(w) and _v276_text(w) == 'Batch output':
                _v276_hide_parent_tail_from_label(w.master, 'Batch output')
        except Exception:
            pass
    # Hide old second-row restoration frames entirely.
    for attr in ('_v275e_project_row','_v275g_project_row','_v275e_batch_row','_v275g_batch_row','_v275h_project_controls_added','_v275h_batch_controls_added'):
        try:
            obj = getattr(self, attr)
            if hasattr(obj, 'winfo_exists') and obj.winfo_exists(): _v276_hide(obj)
        except Exception:
            pass


def _v276_button_normalize_parent(parent, specs):
    """For each text in specs keep/create exactly one button in parent; hide duplicates everywhere else."""
    if parent is None: return {}
    kept = {}
    wanted = set(specs.keys())
    # Hide all existing wanted buttons globally first, remembering one in the desired parent when possible.
    for w in list(_v276_walk(parent.winfo_toplevel())):
        try:
            if _v276_is_button(w) and _v276_text(w) in wanted:
                txt = _v276_text(w)
                if w.master is parent and txt not in kept:
                    kept[txt] = w
                else:
                    _v276_hide(w)
        except Exception:
            pass
    for txt, cmd in specs.items():
        b = kept.get(txt)
        try:
            if b is None or not b.winfo_exists():
                b = ttk.Button(parent, text=txt)
            b.configure(command=cmd)
            if not b.winfo_ismapped():
                b.pack(side='left', padx=3)
            kept[txt] = b
        except Exception:
            pass
    return kept


def _v276_normalize_ui(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        for w in _v276_walk(self):
            if _v276_is_label(w) and str(_v276_text(w)).startswith('SPPS Planner GitHub'):
                w.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception:
        pass
    _v276_ensure_outvars(self)
    _v276_hide_duplicate_output_controls(self)
    # Global action row: exactly one Apply Change, no top Project output controls.
    ap = _v276_action_parent(self)
    _v276_button_normalize_parent(ap, {
        'Apply Change': lambda _self=self: _v276_apply_change(_self, True, True),
        'Save Project': lambda _self=self: _v276_save_project(_self, True),
    })
    # Selected Plan toolbar: exactly one Delete selected row + Edit Unit name.
    sp = _v276_selected_plan_toolbar_parent(self)
    specs = {'Delete selected row': lambda _self=self: _v276_delete_selected_rows(_self)}
    if '_v269_open_unit_picker' in globals():
        specs['Edit Unit name'] = lambda _self=self: _v269_open_unit_picker(_self)
    else:
        old = _v276_find_button(self, 'Edit Unit name')
        try: specs['Edit Unit name'] = old.cget('command')
        except Exception: specs.pop('Edit Unit name', None)
    _v276_button_normalize_parent(sp, specs)
    # Peptide item controls: exactly one Add/Duplicate/Delete in their own row.
    pi = None
    try:
        for t in ('Add','Duplicate','Delete'):
            b = _v276_find_button(self,t)
            if b is not None: pi = b.master; break
    except Exception:
        pass
    _v276_button_normalize_parent(pi, {
        'Add': lambda _self=self: _v276_add_item(_self),
        'Duplicate': lambda _self=self: _v276_duplicate_item(_self),
        'Delete': lambda _self=self: _v276_delete_item(_self),
    })
    # Batch: keep one export button and one output set.
    bp = _v276_batch_parent(self)
    _v276_button_normalize_parent(bp, {'Export batch tables': lambda _self=self: _v276_export_batch(_self)})
    try:
        if bp is not None and not getattr(self, '_v276_batch_row_added', False):
            ttk.Label(bp, text='Batch output').pack(side='left', padx=(8,2))
            ttk.Entry(bp, textvariable=self.batch_outdir, width=30).pack(side='left', padx=2)
            ttk.Button(bp, text='Browse', command=lambda _self=self: _v276_browse_batch(_self)).pack(side='left', padx=2)
            ttk.Button(bp, text='Open Output', command=lambda _self=self: _v276_open_batch(_self)).pack(side='left', padx=2)
            self._v276_batch_row_added = True
    except Exception:
        pass
    # Rebind primary existing buttons.
    for w in _v276_walk(self):
        try:
            if not _v276_is_button(w): continue
            t = _v276_text(w)
            if t == 'Generate / Update': w.configure(command=lambda _self=self: _v276_generate(_self, False))
            elif t == 'Export': w.configure(command=lambda _self=self: _v276_export_project(_self))
            elif t == 'Load Project':
                if hasattr(self, 'load_project'): w.configure(command=self.load_project)
            elif t == 'Import Output':
                if hasattr(self, 'load_output_folder'): w.configure(command=self.load_output_folder)
            elif t == 'Browse' and getattr(w.master, 'winfo_exists', lambda:False)():
                # Only the setup Output-tab Browse should call outdir browse. Batch browse was installed with its own command.
                pass
        except Exception:
            pass
    _v276_patch_editor_events(self)
    try:
        if hasattr(self, 'pm_list'):
            self.pm_list.configure(selectmode=tk.BROWSE)
            self.pm_list.bind('<<ListboxSelect>>', lambda e,_self=self: _v276_pm_select(_self,e), add=False)
            self.pm_list.bind('<Double-Button-1>', lambda e,_self=self: _v276_pm_select(_self,e), add=False)
            self.pm_list.bind('<Return>', lambda e,_self=self: _v276_pm_select(_self,e), add=False)
    except Exception:
        pass


def _v276_blank_initial_default(self):
    try:
        if getattr(self, '_v276_blank_done', False): return
        items = getattr(self, 'pm_items', [])
        # Only clear the built-in first-run placeholder. Do not touch loaded/user projects.
        if len(items) == 1 and str(items[0].get('sequence','')).strip() == 'Ac-EEMQRR-NH2' and str(items[0].get('project','')) == 'Project-001':
            items[0]['sequence'] = ''
            for k in ('selected_plan_records','selected_materials_records','selected_total_records','selected_checklist_records','manual_plan','generated_sequence'):
                items[0].pop(k, None)
            try: self.pm_sequence.set('')
            except Exception: pass
            # Keep the legacy single-plan seq populated until after startup rebuild_table; Project Manager sequence is blanked only.
            _v276_clear_outputs(self)
            try: _v274_refresh_list(self, 0, False)
            except Exception: pass
        self._v276_blank_done = True
    except Exception:
        pass


