def _v276c_edit_unit(self):
    for nm in ('_v239_edit_selected_unit','_v238_edit_selected_unit','_v237_edit_selected_unit'):
        try:
            fn=globals().get(nm)
            if fn is not None: return fn(self)
        except Exception:
            pass
    try:
        # Fallback: rely on the double-click editor already bound to the tree.
        tree=getattr(self,'pm_selected_plan_tree',None)
        sel=tree.selection() if tree is not None else []
        if not sel:
            try: messagebox.showinfo('Edit Unit name','Select a row first, or double-click Unit name directly.')
            except Exception: pass
    except Exception: pass

