# --- V2.0.76d definitive visible-row layout: no duplicates, no missing Apply ---
def _v276d_global_actions_parent(self):
    # Exact Project Manager global-actions row: visible label text, not old hidden frames.
    for w in _v276_walk(self):
        try:
            if _v276_is_label(w) and _v276_text(w) == 'Global actions:' and w.winfo_ismapped():
                return w.master
        except Exception: pass
    # fallback to visible Show setup parent
    for w in _v276_walk(self):
        try:
            if _v276_is_button(w) and _v276_text(w) in ('Show setup','Hide setup') and w.winfo_ismapped():
                return w.master
        except Exception: pass
    return None


def _v276d_hide_project_top_controls(self):
    # Hide any top-row Project output controls; project output is controlled only by Setup defaults > Output.
    for w in list(_v276_walk(self)):
        try:
            if _v276_is_label(w) and _v276_text(w) == 'Project output':
                parent=w.master
                for c in list(parent.winfo_children()):
                    if _v276_text(c) in ('Project output','Browse','Open Output') or c.winfo_class() in ('TEntry','Entry'):
                        _v276_hide(c)
        except Exception: pass


def _v276d_project_buttons(self):
    parent=_v276d_global_actions_parent(self)
    if parent is None: return
    # Hide all legacy Apply/Save buttons globally, then add exactly one each to the correct row.
    for w in list(_v276_walk(self)):
        try:
            if _v276_is_button(w) and _v276_text(w) in ('Apply Change','Apply Plan','Save Project'):
                _v276_hide(w)
        except Exception: pass
    try:
        btn=getattr(self,'_v276d_apply_btn',None)
        if btn is None or not btn.winfo_exists() or btn.master is not parent:
            btn=ttk.Button(parent,text='Apply Change',command=lambda _self=self:_v276_apply_change(_self,True,True)); self._v276d_apply_btn=btn
        else: btn.configure(command=lambda _self=self:_v276_apply_change(_self,True,True))
        btn.pack(side='left',padx=3)
    except Exception: pass
    try:
        sav=getattr(self,'_v276d_save_btn',None)
        if sav is None or not sav.winfo_exists() or sav.master is not parent:
            sav=ttk.Button(parent,text='Save Project',command=lambda _self=self:_v276_save_project(_self,True)); self._v276d_save_btn=sav
        else: sav.configure(command=lambda _self=self:_v276_save_project(_self,True))
        sav.pack(side='left',padx=3)
    except Exception: pass
    _v276d_hide_project_top_controls(self)


def _v276d_batch_top_parent(self):
    for w in _v276_walk(self):
        try:
            if _v276_is_label(w) and _v276_text(w).startswith('Synthesizer stock/cocktail'):
                return w.master
        except Exception: pass
    return None


def _v276d_batch_buttons(self):
    _v276_ensure_outvars(self)
    parent=_v276d_batch_top_parent(self)
    if parent is None: return
    try:
        # Hide all old batch top controls; keep/repack the title label only.
        title=None
        for c in list(parent.winfo_children()):
            if _v276_is_label(c) and _v276_text(c).startswith('Synthesizer stock/cocktail'):
                title=c
            else:
                _v276_hide(c)
        if title is not None and not title.winfo_ismapped():
            title.pack(side='left',padx=(0,12))
        exp=getattr(self,'_v276d_batch_export_btn',None)
        if exp is None or not exp.winfo_exists() or exp.master is not parent:
            exp=ttk.Button(parent,text='Export batch tables',command=lambda _self=self:_v276_export_batch(_self)); self._v276d_batch_export_btn=exp
        exp.pack(side='left',padx=3)
        ref=getattr(self,'_v276d_batch_refresh_btn',None)
        if ref is None or not ref.winfo_exists() or ref.master is not parent:
            ref=ttk.Button(parent,text='Refresh now',command=self.refresh_batch_workspace_preview); self._v276d_batch_refresh_btn=ref
        ref.pack(side='left',padx=3)
        ttk.Label(parent,text='Batch output').pack(side='left',padx=(8,2))
        ttk.Entry(parent,textvariable=self.batch_outdir,width=30).pack(side='left',padx=2)
        ttk.Button(parent,text='Browse',command=lambda _self=self:_v276_browse_batch(_self)).pack(side='left',padx=2)
        ttk.Button(parent,text='Open Output',command=lambda _self=self:_v276_open_batch(_self)).pack(side='left',padx=2)
    except Exception: pass


def _v276d_plan_toolbar(self):
    # Rebuild exactly one toolbar in the Selected Plan tab.
    for w in list(_v276_walk(self)):
        try:
            if _v276_is_button(w) and _v276_text(w) in ('Delete selected row','Edit Unit name'):
                _v276_hide(w)
        except Exception: pass
    try:
        tree=getattr(self,'pm_selected_plan_tree',None)
        if tree is None: return
        parent=tree.master
        if not getattr(self,'_v276d_plan_toolbar_done',False):
            for c in list(parent.winfo_children()):
                try:
                    info=c.grid_info()
                    if info: c.grid_configure(row=int(info.get('row',0))+1)
                except Exception: pass
            bar=ttk.Frame(parent); bar.grid(row=0,column=0,columnspan=2,sticky='ew',pady=(0,2)); self._v276d_plan_toolbar=bar; self._v276d_plan_toolbar_done=True
        bar=self._v276d_plan_toolbar
        for c in list(bar.winfo_children()): c.destroy()
        ttk.Button(bar,text='Delete selected row',command=lambda _self=self:_v276_delete_selected_rows(_self)).pack(side='left',padx=3)
        ttk.Button(bar,text='Edit Unit name',command=lambda _self=self:_v276c_edit_unit(_self)).pack(side='left',padx=3)
    except Exception: pass


def _v276d_normalize(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    _v276_ensure_outvars(self)
    _v276d_hide_project_top_controls(self)
    _v276d_project_buttons(self)
    _v276d_plan_toolbar(self)
    try:
        # If Batch Manager has been constructed, normalize its top row; it only maps on batch tab.
        _v276d_batch_buttons(self)
    except Exception: pass
    try:
        if hasattr(self,'pm_list'):
            self.pm_list.configure(selectmode=tk.BROWSE)
            self.pm_list.bind('<<ListboxSelect>>',lambda e,_self=self:_v276_pm_select(_self,e),add=False)
            self.pm_list.bind('<Double-Button-1>',lambda e,_self=self:_v276_pm_select(_self,e),add=False)
            self.pm_list.bind('<Return>',lambda e,_self=self:_v276_pm_select(_self,e),add=False)
    except Exception: pass
    try:
        for w in _v276_walk(self):
            if _v276_is_button(w):
                t=_v276_text(w)
                if t=='Generate / Update': w.configure(command=lambda _self=self:_v276_generate(_self,False))
                elif t=='Export': w.configure(command=lambda _self=self:_v276_export_project(_self))
                elif t=='Add': w.configure(command=lambda _self=self:_v276_add_item(_self))
                elif t=='Duplicate': w.configure(command=lambda _self=self:_v276_duplicate_item(_self))
                elif t=='Delete': w.configure(command=lambda _self=self:_v276_delete_item(_self))
    except Exception: pass
    _v276_patch_editor_events(self)

