# --- V2.0.76g throttled final UI assertion during redraws ---
def _v276g_light_assert(self):
    try:
        import time as _time
        now=_time.monotonic()
        if now - float(getattr(self,'_v276g_last_assert',0.0)) < 0.35:
            return
        self._v276g_last_assert=now
    except Exception:
        pass
    try:
        if _v276_find_visible_button(self,'Apply Change') is None: _v276d_project_buttons(self)
        if _v276_find_visible_button(self,'Delete selected row') is None and _v276_find_visible_button(self,'Generate / Update') is not None: _v276d_plan_toolbar(self)
        # If Batch Manager is selected and its export is missing, restore batch top controls.
        try:
            selected = self.nametowidget(self.tabs.select())
            if self.tabs.tab(selected, 'text') == 'Batch Manager' and _v276_find_visible_button(self,'Export batch tables') is None:
                _v276d_batch_buttons(self)
        except Exception: pass
    except Exception: pass

try:
    def _v276g_update(self,*args,**kwargs):
        res=tk.Tk.update(self,*args,**kwargs)
        try: _v276g_light_assert(self)
        except Exception: pass
        return res
    def _v276g_update_idletasks(self,*args,**kwargs):
        res=tk.Tk.update_idletasks(self,*args,**kwargs)
        try: _v276g_light_assert(self)
        except Exception: pass
        return res
    SPPSGui.update=_v276g_update
    SPPSGui.update_idletasks=_v276g_update_idletasks
except Exception: pass
# --- END V2.0.76g ---


# ======================= V2.0.77 CLEAN UI LAYOUT + MULTI-SELECT ITEMS FIX =======================
# Goal: make the currently used UI path deterministic without removing user-facing features.
# - One visible control for each action.
# - Apply Change is next to Generate / Update.
# - Show/Hide setup is the right-most Global action with spacing.
# - Selected Plan toolbar is compact and directly above the table.
# - peptide items supports Shift/Ctrl multi-selection for Duplicate/Delete.
# - Save Project and Export remain separate: Save Project stores state JSON; Export writes workbook + state.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'

try:
    _V277_SPACER_TEXT = '    '
except Exception:
    pass


def _v277_safe_text(w):
    try:
        return str(w.cget('text'))
    except Exception:
        return ''


def _v277_is_button(w):
    try:
        return w.winfo_class() in ('TButton','Button')
    except Exception:
        return False


def _v277_is_label(w):
    try:
        return w.winfo_class() in ('TLabel','Label')
    except Exception:
        return False


def _v277_hide(w):
    try: w.pack_forget()
    except Exception: pass
    try: w.grid_forget()
    except Exception: pass
    try: w.place_forget()
    except Exception: pass


def _v277_walk(root):
    try:
        return list(_v276_walk(root))
    except Exception:
        out=[]
        def rec(w):
            out.append(w)
            try:
                for c in w.winfo_children(): rec(c)
            except Exception: pass
        try: rec(root)
        except Exception: pass
        return out


def _v277_visible_button(self, text):
    for w in _v277_walk(self):
        try:
            if _v277_is_button(w) and _v277_safe_text(w)==text and w.winfo_ismapped():
                return w
        except Exception: pass
    return None


def _v277_all_buttons(self, texts):
    texts=set(texts)
    out=[]
    for w in _v277_walk(self):
        try:
            if _v277_is_button(w) and _v277_safe_text(w) in texts:
                out.append(w)
        except Exception: pass
    return out


def _v277_find_generate_row(self):
    # The editor action row contains Generate / Update and Save Session Now.
    btn=_v277_visible_button(self,'Generate / Update')
    if btn is not None:
        return btn.master
    for w in _v277_walk(self):
        try:
            if _v277_is_button(w) and _v277_safe_text(w)=='Generate / Update': return w.master
        except Exception: pass
    return None


def _v277_find_global_row(self):
    # The global row has a visible label "Global actions:".
    for w in _v277_walk(self):
        try:
            if _v277_is_label(w) and _v277_safe_text(w)=='Global actions:' and w.winfo_ismapped():
                return w.master
        except Exception: pass
    # fallback to a visible Use DIC/HOBt button parent
    b=_v277_visible_button(self,'Use DIC/HOBt')
    if b is not None: return b.master
    return None


def _v277_find_setup_button(self):
    for txt in ('Hide setup','Show setup'):
        b=_v277_visible_button(self,txt)
        if b is not None: return b
    for w in _v277_walk(self):
        try:
            if _v277_is_button(w) and _v277_safe_text(w) in ('Hide setup','Show setup'):
                return w
        except Exception: pass
    return None


def _v277_repack_editor_actions(self):
    row=_v277_find_generate_row(self)
    if row is None: return
    # Hide all legacy Apply controls anywhere. We recreate one, next to Generate.
    for w in _v277_all_buttons(self, ('Apply Change','Apply Plan')):
        _v277_hide(w)
    gen=None; save=None
    try:
        for c in row.winfo_children():
            if _v277_is_button(c):
                t=_v277_safe_text(c)
                if t=='Generate / Update': gen=c
                elif t=='Save Session Now': save=c
        if gen is not None:
            try: gen.configure(command=lambda _self=self:_v276_generate(_self,False))
            except Exception: pass
            _v277_hide(gen)
        if save is not None:
            _v277_hide(save)
        app=getattr(self,'_v277_apply_change_btn',None)
        if app is None or (hasattr(app,'winfo_exists') and not app.winfo_exists()) or getattr(app,'master',None) is not row:
            app=ttk.Button(row,text='Apply Change',command=lambda _self=self:_v276_apply_change(_self,True,True))
            self._v277_apply_change_btn=app
        else:
            try: app.configure(text='Apply Change',command=lambda _self=self:_v276_apply_change(_self,True,True))
            except Exception: pass
        if gen is not None: gen.pack(side='left',padx=(0,4))
        app.pack(side='left',padx=(0,4))
        if save is not None: save.pack(side='left',padx=(0,4))
    except Exception:
        pass


def _v277_repack_global_actions(self):
    row=_v277_find_global_row(self)
    if row is None: return
    try:
        # Hide project-output top duplicates; output path remains in Setup defaults > Output only.
        if '_v276d_hide_project_top_controls' in globals(): _v276d_hide_project_top_controls(self)
    except Exception: pass
    # Hide any old setup button and recreate/repack a single right-most one.
    for w in _v277_all_buttons(self, ('Show setup','Hide setup')):
        _v277_hide(w)
    try:
        # Keep the main global action buttons packed left in a fixed order.
        keep_order=('Use DIC/HOBt','Use HBTU/NMP 10eq','Load Project','Import Output','Export','Save Project')
        found={}
        for c in row.winfo_children():
            if _v277_is_button(c) and _v277_safe_text(c) in keep_order:
                found.setdefault(_v277_safe_text(c),c)
        # Save Project may have been removed by older clean-up patches; recreate it in the Global actions row.
        if 'Save Project' not in found:
            try:
                found['Save Project']=ttk.Button(row,text='Save Project',command=lambda _self=self:_v276_save_project(_self,True))
            except Exception:
                pass
        for t in keep_order:
            b=found.get(t)
            if b is None: continue
            try:
                if t=='Export': b.configure(command=lambda _self=self:_v276_export_project(_self))
                elif t=='Save Project': b.configure(command=lambda _self=self:_v276_save_project(_self,True))
            except Exception: pass
            _v277_hide(b)
            b.pack(side='left',padx=3)
        # One-button-sized blank before the right-most setup toggle.
        spacer=getattr(self,'_v277_global_spacer',None)
        if spacer is None or (hasattr(spacer,'winfo_exists') and not spacer.winfo_exists()) or getattr(spacer,'master',None) is not row:
            spacer=ttk.Frame(row,width=90)
            self._v277_global_spacer=spacer
        spacer.pack(side='right',padx=(12,0))
        setup=getattr(self,'_v277_setup_btn',None)
        old=_v277_find_setup_button(self)
        label='Hide setup' if _v277_setup_visible(self) else 'Show setup'
        cmd=None
        if old is not None:
            try: cmd=old.cget('command')
            except Exception: cmd=None
        if setup is None or (hasattr(setup,'winfo_exists') and not setup.winfo_exists()) or getattr(setup,'master',None) is not row:
            setup=ttk.Button(row,text=label)
            self._v277_setup_btn=setup
        try:
            if cmd: setup.configure(text=label,command=cmd)
        except Exception: pass
        # If command could not be copied, use the original show_setup method if present.
        try:
            if not setup.cget('command') and hasattr(self,'toggle_setup'):
                setup.configure(command=self.toggle_setup)
        except Exception: pass
        setup.pack(side='right',padx=(0,3))
    except Exception:
        pass


def _v277_setup_visible(self):
    try:
        nb=getattr(self,'pm_setup_notebook',None)
        if nb is not None and nb.winfo_ismapped(): return True
    except Exception: pass
    try:
        for w in _v277_walk(self):
            if _v277_is_button(w) and _v277_safe_text(w)=='Hide setup' and w.winfo_ismapped(): return True
    except Exception: pass
    return False


def _v277_compact_selected_plan(self):
    tree=getattr(self,'pm_selected_plan_tree',None)
    if tree is None: return
    try:
        parent=tree.master
        # Remove all old toolbar/button rows inside the Selected Plan frame.
        for c in list(parent.winfo_children()):
            if c is tree: continue
            cls=c.winfo_class()
            txt=_v277_safe_text(c)
            if cls in ('TFrame','Frame'):
                # old toolbar frames get forgotten; scrollbars are not frames.
                _v277_hide(c)
            elif _v277_is_button(c) or txt in ('Delete selected row','Edit Unit name'):
                _v277_hide(c)
        bar=getattr(self,'_v277_plan_toolbar',None)
        if bar is None or (hasattr(bar,'winfo_exists') and not bar.winfo_exists()) or getattr(bar,'master',None) is not parent:
            bar=ttk.Frame(parent)
            self._v277_plan_toolbar=bar
        # Rebuild toolbar content only here, with compact pady.
        for c in list(bar.winfo_children()): c.destroy()
        ttk.Button(bar,text='Delete selected row',command=lambda _self=self:_v276_delete_selected_rows(_self)).pack(side='left',padx=(0,4),pady=0)
        ttk.Button(bar,text='Edit Unit name',command=lambda _self=self:_v276c_edit_unit(_self)).pack(side='left',padx=(0,4),pady=0)
        # Find scrollbars belonging to this tree by command path/name.
        scrollbars=[c for c in parent.winfo_children() if c.winfo_class() in ('TScrollbar','Scrollbar')]
        vbar=None; hbar=None
        for s in scrollbars:
            try:
                orient=str(s.cget('orient')).lower()
                if orient=='vertical': vbar=s
                elif orient=='horizontal': hbar=s
            except Exception: pass
        # Clear grid geometry in this parent and rebuild a compact grid.
        for c in list(parent.winfo_children()):
            try: c.grid_forget()
            except Exception: pass
        parent.rowconfigure(0,weight=0,minsize=0)
        parent.rowconfigure(1,weight=1,minsize=0)
        parent.rowconfigure(2,weight=0,minsize=0)
        parent.columnconfigure(0,weight=1)
        parent.columnconfigure(1,weight=0)
        bar.grid(row=0,column=0,columnspan=2,sticky='w',pady=(0,1))
        tree.configure(height=max(14,int(getattr(tree,'cget')('height') or 18)))
        tree.grid(row=1,column=0,sticky='nsew',pady=(0,0))
        if vbar is not None: vbar.grid(row=1,column=1,sticky='ns')
        if hbar is not None: hbar.grid(row=2,column=0,sticky='ew')
    except Exception:
        pass


def _v277_refresh_list(self, select_idx=None):
    try:
        lb=getattr(self,'pm_list',None)
        if lb is None: return
        lb.delete(0,'end')
        for item in getattr(self,'pm_items',[]):
            p=str(item.get('project','Project')).strip() or 'Project'
            pep=str(item.get('peptide','Peptide')).strip() or 'Peptide'
            lb.insert('end',f'{p} | {pep}')
        if select_idx is not None and getattr(self,'pm_items',[]):
            select_idx=max(0,min(int(select_idx),len(self.pm_items)-1))
            lb.selection_clear(0,'end')
            lb.selection_set(select_idx)
            lb.activate(select_idx)
            try: lb.see(select_idx)
            except Exception: pass
    except Exception:
        pass


def _v277_selected_indices(self):
    try:
        sels=[int(i) for i in self.pm_list.curselection()]
        if sels: return sorted(set(sels))
    except Exception: pass
    try:
        i=_v276_current_idx(self)
        if i is not None: return [int(i)]
    except Exception: pass
    return []


def _v277_duplicate_item(self):
    import copy as _copy
    try:
        sels=_v277_selected_indices(self)
        if not sels: return
        try: _v276_save_item(self,_v276_current_idx(self),True)
        except Exception: pass
        new_indices=[]
        for idx in sels:
            if idx<0 or idx>=len(getattr(self,'pm_items',[])): continue
            new=_copy.deepcopy(self.pm_items[idx])
            base_project=str(new.get('project') or f'Project-{idx+1:03d}')
            base_pep=str(new.get('peptide') or f'Peptide-{idx+1:03d}')
            new['project']=base_project+'_copy'
            new['peptide']=base_pep+'_copy'
            try: new['lot']=self._generate_lot_no()
            except Exception: pass
            self.pm_items.append(new)
            new_indices.append(len(self.pm_items)-1)
        if new_indices:
            _v277_refresh_list(self,new_indices[0])
            try:
                self.pm_list.selection_clear(0,'end')
                for i in new_indices: self.pm_list.selection_set(i)
                self.pm_list.activate(new_indices[0]); self.pm_list.see(new_indices[0])
            except Exception: pass
            _v276_load_item(self,new_indices[0],clear_if_no_outputs=False)
    except Exception as e:
        try: messagebox.showerror('Duplicate peptide',str(e))
        except Exception: pass


def _v277_blank_item(n=1):
    return {'project':f'Project-{n:03d}','peptide':f'Peptide-{n:03d}','sequence':'','scale':'0.2','resin':'','loading':'','lot':'','chemistry':'DIC/HOBt','copies':'1','status':'Ready'}


def _v277_delete_item(self):
    try:
        sels=_v277_selected_indices(self)
        if not sels: return
        # Save non-deleted active item only if it is not in the delete set.
        try:
            cur=_v276_current_idx(self)
            if cur not in sels: _v276_save_item(self,cur,True)
        except Exception: pass
        for idx in sorted(sels,reverse=True):
            if 0 <= idx < len(getattr(self,'pm_items',[])):
                del self.pm_items[idx]
        if not getattr(self,'pm_items',[]):
            self.pm_items=[_v277_blank_item(1)]
            try: _v276_clear_outputs(self)
            except Exception: pass
        ni=min(sels[0],len(self.pm_items)-1)
        _v277_refresh_list(self,ni)
        _v276_load_item(self,ni,clear_if_no_outputs=True)
    except Exception as e:
        try: messagebox.showerror('Delete peptide',str(e))
        except Exception: pass


def _v277_apply_core_bindings(self):
    try:
        if hasattr(self,'pm_list'):
            self.pm_list.configure(selectmode=tk.EXTENDED, exportselection=False)
            self.pm_list.bind('<<ListboxSelect>>',lambda e,_self=self:_v276_pm_select(_self,e),add=False)
            self.pm_list.bind('<Double-Button-1>',lambda e,_self=self:_v276_pm_select(_self,e),add=False)
            self.pm_list.bind('<Return>',lambda e,_self=self:_v276_pm_select(_self,e),add=False)
    except Exception: pass
    try:
        for w in _v277_walk(self):
            if _v277_is_button(w):
                t=_v277_safe_text(w)
                if t=='Generate / Update': w.configure(command=lambda _self=self:_v276_generate(_self,False))
                elif t=='Apply Change': w.configure(command=lambda _self=self:_v276_apply_change(_self,True,True))
                elif t=='Export': w.configure(command=lambda _self=self:_v276_export_project(_self))
                elif t=='Save Project': w.configure(command=lambda _self=self:_v276_save_project(_self,True))
                elif t=='Duplicate': w.configure(command=lambda _self=self:_v277_duplicate_item(_self))
                elif t=='Delete': w.configure(command=lambda _self=self:_v277_delete_item(_self))
                elif t=='Add': w.configure(command=lambda _self=self:_v276_add_item(_self))
    except Exception: pass


def _v277_normalize_ui(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        if hasattr(self,'title_label'):
            self.title_label.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    # Do not cancel here: this function can be scheduled by v2.0.77 itself.
    _v277_repack_editor_actions(self)
    _v277_repack_global_actions(self)
    _v277_compact_selected_plan(self)
    _v277_apply_core_bindings(self)

# Replace old single-item Duplicate/Delete handlers with multi-select versions.
try:
    _v276_duplicate_item = _v277_duplicate_item
    _v276_delete_item = _v277_delete_item
except Exception: pass

try:
    _v277_prev_build=SPPSGui._build
    def _v277_build(self):
        _v277_prev_build(self)
        try: _v276_cancel_legacy_after(self)
        except Exception: pass
        _v277_normalize_ui(self)
        # delayed one-shot only, not continuous redraw. Keeps startup clean without causing input lag.
        for delay in (120, 600):
            try: self.after(delay, lambda _self=self:_v277_normalize_ui(_self))
            except Exception: pass
        try: self.tabs.bind('<<NotebookTabChanged>>',lambda e,_self=self:_self.after(40,lambda:_v277_normalize_ui(_self)),add=False)
        except Exception: pass
    SPPSGui._build=_v277_build
except Exception: pass

# Keep update/update_idletasks light: no UI rebuilding on every keystroke/paint.
try:
    SPPSGui.update = tk.Tk.update
    SPPSGui.update_idletasks = tk.Tk.update_idletasks
except Exception: pass
# ======================= END V2.0.77 CLEAN UI LAYOUT + MULTI-SELECT ITEMS FIX =======================

# ======================= V2.0.78 SETUP RESTORE + CLEANUP FIX =======================
# Goal: keep the v2.0.77 layout/user-facing behavior, but make Show/Hide setup
# deterministic, remove visible duplicate controls, and restore action wiring without
# continuous UI redraw callbacks.
APP_VERSION = 'V2.1.7'
VERSION_LABEL = 'SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout'


def _v278_text(w):
    try: return str(w.cget('text'))
    except Exception: return ''


def _v278_is_button(w):
    try: return w.winfo_class() in ('TButton', 'Button')
    except Exception: return False


def _v278_is_label(w):
    try: return w.winfo_class() in ('TLabel', 'Label')
    except Exception: return False


def _v278_walk(root):
    out=[]
    def rec(w):
        out.append(w)
        try:
            for c in w.winfo_children(): rec(c)
        except Exception: pass
    try: rec(root)
    except Exception: pass
    return out


def _v278_hide(w):
    for fn in ('pack_forget','grid_forget','place_forget'):
        try: getattr(w,fn)()
        except Exception: pass


def _v278_forget_or_destroy(w, destroy=False):
    try:
        if destroy: w.destroy(); return
    except Exception: pass
    _v278_hide(w)


def _v278_visible_buttons(self, text=None):
    out=[]
    for w in _v278_walk(self):
        try:
            if _v278_is_button(w) and w.winfo_ismapped() and (text is None or _v278_text(w)==text):
                out.append(w)
        except Exception: pass
    return out


def _v278_find_visible_button(self, text):
    bs=_v278_visible_buttons(self,text)
    return bs[0] if bs else None


def _v278_find_label_parent(self, label_text):
    for w in _v278_walk(self):
        try:
            if _v278_is_label(w) and _v278_text(w)==label_text and w.winfo_ismapped():
                return w.master
        except Exception: pass
    return None


def _v278_find_editor_action_row(self):
    b=_v278_find_visible_button(self,'Generate / Update')
    if b is not None: return b.master
    for w in _v278_walk(self):
        try:
            if _v278_is_button(w) and _v278_text(w)=='Generate / Update': return w.master
        except Exception: pass
    return None


def _v278_find_global_row(self):
    row=_v278_find_label_parent(self,'Global actions:')
    if row is not None: return row
    b=_v278_find_visible_button(self,'Use DIC/HOBt')
    if b is not None: return b.master
    return None


def _v278_setup_visible(self):
    panel=getattr(self,'pm_setup_panel',None)
    if panel is not None:
        try: return bool(panel.winfo_ismapped())
        except Exception: pass
    try:
        v=getattr(self,'_setup_visible',None)
        if v is not None: return bool(v.get())
    except Exception: pass
    return False


def _v278_set_setup_button_text(self):
    label='Hide setup' if _v278_setup_visible(self) else 'Show setup'
    for w in _v278_walk(self):
        try:
            if _v278_is_button(w) and _v278_text(w) in ('Show setup','Hide setup'):
                w.configure(text=label, command=lambda _self=self: _v278_toggle_setup(_self))
        except Exception: pass


def _v278_toggle_setup(self):
    """Single robust setup toggle used by every Show/Hide setup button."""
    try:
        panel=getattr(self,'pm_setup_panel',None)
        if panel is None:
            # Some legacy paths create the setup panel lazily. Build it in the editor area if possible.
            try:
                edit=getattr(self,'pm_editor_frame',None) or getattr(self,'pm_editor',None)
                if edit is not None and hasattr(self,'_build_pm_setup_panel'):
                    self._build_pm_setup_panel(edit)
                    panel=getattr(self,'pm_setup_panel',None)
            except Exception: pass
        if panel is None:
            try: self.log('Setup panel is not available.')
            except Exception: pass
            return
        visible=False
        try: visible=bool(panel.winfo_ismapped())
        except Exception: visible=False
        if visible:
            try: panel.grid_remove()
            except Exception: _v278_hide(panel)
            try: self._setup_visible.set(False)
            except Exception: pass
        else:
            # grid() restores the original row/column when grid_remove() was used.
            try: panel.grid()
            except Exception:
                try: panel.grid(row=5,column=0,columnspan=10,sticky='ew',pady=(6,0))
                except Exception: pass
            try: self._setup_visible.set(True)
            except Exception: pass
        _v278_set_setup_button_text(self)
        try: self.update_idletasks()
        except Exception: pass
    except Exception as exc:
        try: messagebox.showerror('Show setup', str(exc))
        except Exception: pass


def _v278_button(parent, text, command, side='left', padx=3):
    btn=ttk.Button(parent,text=text,command=command)
    btn.pack(side=side,padx=padx)
    return btn


def _v278_normalize_editor_actions(self):
    row=_v278_find_editor_action_row(self)
    if row is None: return
    try:
        existing=[]
        for c in list(row.winfo_children()):
            if _v278_is_button(c):
                t=_v278_text(c)
                if t in ('Generate / Update','Apply Change','Apply Plan','Save Session Now'):
                    existing.append(c)
                    _v278_hide(c)
        gen=next((b for b in existing if _v278_text(b)=='Generate / Update'), None)
        save=next((b for b in existing if _v278_text(b)=='Save Session Now'), None)
        apply=getattr(self,'_v278_apply_btn',None)
        if apply is None or not getattr(apply,'winfo_exists',lambda:False)() or getattr(apply,'master',None) is not row:
            apply=ttk.Button(row,text='Apply Change')
            self._v278_apply_btn=apply
        try: apply.configure(text='Apply Change',command=lambda _self=self:_v276_apply_change(_self,True,True))
        except Exception: pass
        if gen is not None:
            try: gen.configure(command=lambda _self=self:_v276_generate(_self,False))
            except Exception: pass
            gen.pack(side='left',padx=(0,4))
        apply.pack(side='left',padx=(0,4))
        if save is not None:
            save.pack(side='left',padx=(0,4))
    except Exception: pass


def _v278_normalize_global_actions(self):
    row=_v278_find_global_row(self)
    if row is None: return
    try:
        # Hide old project-output controls from the global row only. Output remains in Setup > Output.
        for c in list(row.winfo_children()):
            try:
                txt=_v278_text(c)
                if txt in ('Project output','Browse','Open Output') or (_v278_is_button(c) and txt in ('Show setup','Hide setup','Save Project','Export','Load Project','Import Output','Use DIC/HOBt','Use HBTU/NMP 10eq')):
                    _v278_hide(c)
                elif hasattr(c,'cget') and txt.strip().startswith('/'):
                    _v278_hide(c)
            except Exception: pass
        # Repack known global buttons once in the desired order.
        existing={}
        for c in list(row.winfo_children()):
            if _v278_is_button(c): existing.setdefault(_v278_text(c),c)
        specs=[
            ('Use DIC/HOBt', lambda _self=self: _self.apply_dic_hobt_preset() if hasattr(_self,'apply_dic_hobt_preset') else None),
            ('Use HBTU/NMP 10eq', lambda _self=self: _self.apply_hbtu_nmp_preset() if hasattr(_self,'apply_hbtu_nmp_preset') else None),
            ('Load Project', lambda _self=self: _v276_load_project(_self) if '_v276_load_project' in globals() else _self.load_project()),
            ('Import Output', lambda _self=self: _self.load_output_folder() if hasattr(_self,'load_output_folder') else None),
            ('Export', lambda _self=self: _v276_export_project(_self) if '_v276_export_project' in globals() else _self.export_outputs()),
            ('Save Project', lambda _self=self: _v276_save_project(_self,True) if '_v276_save_project' in globals() else None),
        ]
        for text,cmd in specs:
            b=existing.get(text)
            if b is None or not b.winfo_exists() or getattr(b,'master',None) is not row:
                b=ttk.Button(row,text=text)
            try: b.configure(command=cmd)
            except Exception: pass
            b.pack(side='left',padx=3)
        spacer=getattr(self,'_v278_global_spacer',None)
        if spacer is None or not spacer.winfo_exists() or getattr(spacer,'master',None) is not row:
            spacer=ttk.Frame(row,width=90)
            self._v278_global_spacer=spacer
        spacer.pack(side='right',padx=(12,0))
        setup=getattr(self,'_v278_setup_btn',None)
        if setup is None or not setup.winfo_exists() or getattr(setup,'master',None) is not row:
            setup=ttk.Button(row,text='Show setup')
            self._v278_setup_btn=setup
        setup.configure(text='Hide setup' if _v278_setup_visible(self) else 'Show setup', command=lambda _self=self:_v278_toggle_setup(_self))
        setup.pack(side='right',padx=(0,3))
    except Exception: pass


def _v278_normalize_plan_toolbar(self):
    tree=getattr(self,'pm_selected_plan_tree',None)
    if tree is None: return
    try:
        parent=tree.master
        # Hide any old toolbar frames/buttons in the selected plan parent, then rebuild a compact single toolbar.
        for c in list(parent.winfo_children()):
            if c is tree: continue
            if c.winfo_class() in ('TFrame','Frame') or (_v278_is_button(c) and _v278_text(c) in ('Delete selected row','Edit Unit name')):
                _v278_hide(c)
        bar=getattr(self,'_v278_plan_toolbar',None)
        if bar is None or not bar.winfo_exists() or getattr(bar,'master',None) is not parent:
            bar=ttk.Frame(parent)
            self._v278_plan_toolbar=bar
        for c in list(bar.winfo_children()):
            try: c.destroy()
            except Exception: pass
        ttk.Button(bar,text='Delete selected row',command=lambda _self=self:_v276_delete_selected_rows(_self)).pack(side='left',padx=(0,4),pady=0)
        ttk.Button(bar,text='Edit Unit name',command=lambda _self=self:_v276c_edit_unit(_self) if '_v276c_edit_unit' in globals() else None).pack(side='left',padx=(0,4),pady=0)
        # Compact grid if tree parent uses grid.
        try:
            scrollbars=[c for c in parent.winfo_children() if c.winfo_class() in ('TScrollbar','Scrollbar')]
            vbar=hbar=None
            for s in scrollbars:
                try:
                    if str(s.cget('orient')).lower()=='vertical': vbar=s
                    elif str(s.cget('orient')).lower()=='horizontal': hbar=s
                except Exception: pass
            for c in list(parent.winfo_children()):
                try: c.grid_forget()
                except Exception: pass
            parent.rowconfigure(0,weight=0,minsize=0); parent.rowconfigure(1,weight=1,minsize=0); parent.rowconfigure(2,weight=0,minsize=0)
            parent.columnconfigure(0,weight=1); parent.columnconfigure(1,weight=0)
            bar.grid(row=0,column=0,columnspan=2,sticky='w',pady=(0,1))
            tree.grid(row=1,column=0,sticky='nsew',pady=0)
            if vbar is not None: vbar.grid(row=1,column=1,sticky='ns')
            if hbar is not None: hbar.grid(row=2,column=0,sticky='ew')
        except Exception:
            try: bar.pack(fill='x',pady=(0,1),before=tree)
            except Exception: pass
    except Exception: pass


def _v278_bind_item_buttons(self):
    try:
        if hasattr(self,'pm_list'):
            self.pm_list.configure(selectmode=tk.EXTENDED, exportselection=False)
            self.pm_list.bind('<<ListboxSelect>>', lambda e,_self=self:_v276_pm_select(_self,e), add=False)
            self.pm_list.bind('<Double-Button-1>', lambda e,_self=self:_v276_pm_select(_self,e), add=False)
    except Exception: pass
    try:
        # Keep exactly one visible Add/Duplicate/Delete in the peptide-items box.
        for w in _v278_walk(self):
            if _v278_is_button(w):
                t=_v278_text(w)
                if t=='Add': w.configure(command=lambda _self=self:_v276_add_item(_self))
                elif t=='Duplicate': w.configure(command=lambda _self=self:_v277_duplicate_item(_self) if '_v277_duplicate_item' in globals() else _self.pm_duplicate_item())
                elif t=='Delete': w.configure(command=lambda _self=self:_v277_delete_item(_self) if '_v277_delete_item' in globals() else _self.pm_delete_item())
    except Exception: pass


def _v278_update_version_labels(self):
    try: self.title('SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass
    try:
        if hasattr(self,'title_label'):
            self.title_label.configure(text='SPPS Planner GitHub V2.1.7 - UI Rollback to V2.0.94 Layout')
    except Exception: pass


def _v278_normalize_ui(self):
    _v278_update_version_labels(self)
    _v278_normalize_editor_actions(self)
    _v278_normalize_global_actions(self)
    _v278_normalize_plan_toolbar(self)
    _v278_bind_item_buttons(self)
    _v278_set_setup_button_text(self)


try:
    _v278_prev_build = SPPSGui._build
    def _v278_build(self):
        _v278_prev_build(self)
        try: _v276_cancel_legacy_after(self)
        except Exception: pass
        _v278_normalize_ui(self)
        # One short delayed pass only to account for late-created notebook children.
        try: self.after(150, lambda _self=self: _v278_normalize_ui(_self))
        except Exception: pass
    SPPSGui._build = _v278_build
except Exception: pass

