def _v279_add_project_open_output(self):
    try:
        candidates = []
        for w in (_v278_walk(self) if '_v278_walk' in globals() else []):
            try:
                if hasattr(w, 'cget') and str(w.cget('text')).strip() == 'Output folder':
                    candidates.append(w.master)
            except Exception:
                pass
        done_parents = set()
        for parent in candidates:
            if parent in done_parents:
                continue
            done_parents.add(parent)
            children = list(parent.winfo_children())
            browse_btn = None
            open_btn = None
            for c in children:
                try:
                    txt = str(c.cget('text')).strip() if hasattr(c, 'cget') else ''
                    if txt == 'Browse':
                        browse_btn = c
                    elif txt == 'Open Output':
                        open_btn = c
                except Exception:
                    pass
            if browse_btn is None:
                continue
            # Keep only one Open Output button in the row.
            if open_btn is None or not open_btn.winfo_exists():
                open_btn = ttk.Button(parent, text='Open Output', command=lambda _self=self: _self.open_output())
            else:
                try:
                    open_btn.configure(command=lambda _self=self: _self.open_output())
                except Exception:
                    pass
            try:
                mgr = browse_btn.winfo_manager()
            except Exception:
                mgr = ''
            if mgr == 'grid':
                try:
                    info = browse_btn.grid_info()
                    row = int(info.get('row', 0))
                    col = int(info.get('column', 0)) + 1
                    open_btn.grid(row=row, column=col, sticky='w', padx=3, pady=2)
                except Exception:
                    pass
            else:
                try:
                    open_btn.pack_forget()
                except Exception:
                    pass
                try:
                    open_btn.pack(side='left', padx=3)
                except Exception:
                    pass
    except Exception:
        pass


