# ======================= V2.0.80 SELECTED TOTAL MATERIALS FINAL FIX =======================
# Fixes:
# - Generate / Update and Apply Change now immediately populate Selected Total Materials.
# - Export no longer rewrites Selected Total Materials into duplicated amount strings.
# - total amount is aggregated numerically from the visible Selected Materials table.

import re as _v280_re

def _v280_num(x):
    try:
        s = str(x or '').strip().replace(',', '')
        if not s:
            return 0.0
        m = _v280_re.search(r'-?\d+(?:\.\d+)?', s)
        return float(m.group(0)) if m else 0.0
    except Exception:
        return 0.0


def _v280_fmt(x):
    try:
        f = float(x)
        if abs(f) < 1e-12:
            return ''
        if abs(f - round(f)) < 1e-10:
            return str(int(round(f)))
        return f'{f:.6f}'.rstrip('0').rstrip('.')
    except Exception:
        return str(x or '')


def _v280_parse_amount(amount):
    """Return (g, mL) parsed from strings such as '4.551 g; 4.551 g' or '52.8 mL'."""
    g = 0.0
    ml = 0.0
    s = str(amount or '').replace(',', '')
    if not s.strip():
        return g, ml
    # Match number + unit.  This intentionally ignores numbers without units.
    for m in _v280_re.finditer(r'(-?\d+(?:\.\d+)?)\s*(mg|g|ml|mL|ML|L)\b', s):
        try:
            val = float(m.group(1))
        except Exception:
            continue
        unit = m.group(2).lower()
        if unit == 'mg':
            g += val / 1000.0
        elif unit == 'g':
            g += val
        elif unit == 'l':
            ml += val * 1000.0
        else:
            ml += val
    return g, ml


def _v280_tree_rows(tree):
    rows=[]
    if tree is None:
        return rows
    try:
        cols=list(tree['columns'])
        for iid in tree.get_children():
            vals=list(tree.item(iid,'values'))
            vals += [''] * max(0, len(cols)-len(vals))
            rows.append(dict(zip(cols, vals)))
    except Exception:
        pass
    return rows


def _v280_write_total_tree(tree, rows):
    show=['material','class','MW','Density(g/mL)','total mmol','total amount','note']
    try:
        if '_v265_write_tree' in globals():
            import pandas as _pd
            _v265_write_tree(tree, _pd.DataFrame(rows, columns=show), show)
        else:
            try:
                tree.configure(columns=show, show='headings')
            except Exception:
                pass
            for c in show:
                try:
                    tree.heading(c, text=c)
                    tree.column(c, width=150 if c != 'note' else 260, stretch=False, anchor='w')
                except Exception:
                    pass
            for iid in tree.get_children():
                tree.delete(iid)
            for r in rows:
                tree.insert('', 'end', values=[r.get(c,'') for c in show])
    except Exception:
        pass


def _v280_refresh_total_materials(self):
    """Canonical Selected Materials -> Selected Total Materials aggregator."""
    try:
        mat_tree = getattr(self, 'pm_selected_material_tree', None)
        total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        if mat_tree is None or total_tree is None:
            return []
        rows = _v280_tree_rows(mat_tree)
        if not rows:
            _v280_write_total_tree(total_tree, [])
            return []
        order=[]
        bucket={}
        for r in rows:
            material=str(r.get('material','')).strip()
            if not material:
                continue
            if material not in bucket:
                low=material.lower()
                cls=str(r.get('class','')).strip()
                if low == 'dmf':
                    cls='Reaction solvent 1'
                elif low == 'dcm':
                    cls='Reaction solvent 2'
                bucket[material]={
                    'material':material,
                    'class':cls,
                    'MW':str(r.get('MW','')).strip(),
                    'Density(g/mL)':str(r.get('Density(g/mL)','')).strip(),
                    'mmol':0.0,
                    'g':0.0,
                    'ml':0.0,
                }
                order.append(material)
            rec=bucket[material]
            # selected materials in current UI use total mmol / total amount columns.
            rec['mmol'] += _v280_num(r.get('planned_mmol', r.get('total mmol','')))
            g = _v280_num(r.get('planned_g',''))
            ml = _v280_num(r.get('planned_mL',''))
            if g == 0.0 and ml == 0.0:
                pg, pml = _v280_parse_amount(r.get('total amount',''))
                g += pg
                ml += pml
            rec['g'] += g
            rec['ml'] += ml
        out=[]
        for material in order:
            rec=bucket[material]
            amount=''
            if rec['g'] and rec['ml']:
                amount=f"{_v280_fmt(rec['g'])} g / {_v280_fmt(rec['ml'])} mL"
            elif rec['g']:
                amount=f"{_v280_fmt(rec['g'])} g"
            elif rec['ml']:
                amount=f"{_v280_fmt(rec['ml'])} mL"
            out.append({
                'material': rec['material'],
                'class': rec['class'],
                'MW': rec['MW'],
                'Density(g/mL)': rec['Density(g/mL)'],
                'total mmol': _v280_fmt(rec['mmol']) if rec['mmol'] else '',
                'total amount': amount,
                'note': 'Total from ordered Selected Materials',
            })
        _v280_write_total_tree(total_tree, out)
        return out
    except Exception:
        return []


