def _v280_export_project(self):
    """Lean project export using the fixed visible tables."""
    try:
        import json
        import pandas as _pd
        from pathlib import Path
        # Make current views current, then fix total table before writing Excel.
        try: _v280_apply_change(self, True, True)
        except Exception: pass
        try: _v280_refresh_total_materials(self)
        except Exception: pass
        try:
            if '_v271_ensure_outvars' in globals():
                _v271_ensure_outvars(self)
        except Exception:
            pass
        try:
            out = Path(self.project_outdir.get()) if hasattr(self, 'project_outdir') else Path(getattr(self, 'outdir').get())
        except Exception:
            out = Path('outputs/project_manager_exports')
        out.mkdir(parents=True, exist_ok=True)
        xlsx = out / 'project_manager_selected_outputs.xlsx'
        def df_from_tree(tree):
            try:
                return _pd.DataFrame(_v280_tree_rows(tree), columns=list(tree['columns']))
            except Exception:
                return _pd.DataFrame()
        editor = _v276_editor_snapshot(self) if '_v276_editor_snapshot' in globals() else {}
        plan = df_from_tree(getattr(self,'pm_selected_plan_tree',None))
        mats = df_from_tree(getattr(self,'pm_selected_material_tree',None))
        total = df_from_tree(getattr(self,'pm_selected_total_tree',None) or getattr(self,'pm_total_tree',None))
        chk = df_from_tree(getattr(self,'progress_tree',None) or getattr(self,'pm_selected_check_tree',None))
        with _pd.ExcelWriter(xlsx, engine='openpyxl') as w:
            _pd.DataFrame([editor]).to_excel(w, index=False, sheet_name='00_EDITOR_SUMMARY')
            plan.to_excel(w, index=False, sheet_name='01_SELECTED_PLAN')
            mats.to_excel(w, index=False, sheet_name='02_SELECTED_MATERIALS')
            total.to_excel(w, index=False, sheet_name='03_TOTAL_MATERIALS')
            chk.to_excel(w, index=False, sheet_name='04_SELECTED_CHECKLIST')
        state_path = out / 'project_manager_state.json'
        try:
            if '_v276_save_item' in globals(): _v276_save_item(self, None, True)
        except Exception: pass
        state_path.write_text(json.dumps({'app_version':'V2.0.80','active_index':(_v276_current_idx(self) if '_v276_current_idx' in globals() else None),'pm_items':getattr(self,'pm_items',[])}, ensure_ascii=False, indent=2), encoding='utf-8')
        try: self.last_outdir = out
        except Exception: pass
        try: messagebox.showinfo('Export complete', f'Project Manager export saved:\n{xlsx}')
        except Exception: pass
        return xlsx
    except Exception as exc:
        try: messagebox.showerror('Export error', str(exc))
        except Exception: pass
        return None


