# ======================= V2.0.82 CTC NAME / ADD RESET / TOTAL ORDER / LOADING CARET FIX =======================
# Requested fixes:
# - Rename CTC(합성용) -> CTC(합성기), while still accepting old saved values.
# - Add creates a fresh blank/default peptide instead of inheriting current editor settings.
# - Selected Total Materials is grouped by purpose: resin/base/solvents/reagents/catalyst/AA.
# - Clean up resin-loading display and move focus away after Generate/Apply so the loading caret does not remain visually stuck.

_V281_CTC_OLD = 'CTC(합성용)'
_V281_CTC_NEW = 'CTC(합성기)'

def _v281_canon_ctc_name(value):
    s = str(value or '').strip()
    return _V281_CTC_NEW if s == _V281_CTC_OLD else s


def _v281_walk(w):
    try:
        for c in w.winfo_children():
            yield c
            yield from _v281_walk(c)
    except Exception:
        return


def _v281_sync_ctc_labels(self):
    try:
        if hasattr(self, 'pm_resin') and self.pm_resin.get().strip() == _V281_CTC_OLD:
            self.pm_resin.set(_V281_CTC_NEW)
    except Exception:
        pass
    try:
        for w in _v281_walk(self):
            if isinstance(w, ttk.Combobox):
                vals = list(w.cget('values') or [])
                if _V281_CTC_OLD in vals or _V281_CTC_NEW in vals:
                    new_vals = []
                    for v in vals:
                        vv = _v281_canon_ctc_name(v)
                        if vv not in new_vals:
                            new_vals.append(vv)
                    try:
                        w.configure(values=new_vals)
                    except Exception:
                        pass
                    try:
                        if w.get().strip() == _V281_CTC_OLD:
                            w.set(_V281_CTC_NEW)
                    except Exception:
                        pass
    except Exception:
        pass
    try:
        for item in getattr(self, 'pm_items', []):
            if str(item.get('resin','')).strip() == _V281_CTC_OLD:
                item['resin'] = _V281_CTC_NEW
    except Exception:
        pass


def _v281_hide_loading_visual_noise(self):
    try:
        if not hasattr(self, 'pm_loading'):
            return
        loading_entry = None
        for w in _v281_walk(self):
            try:
                if isinstance(w, ttk.Entry) and str(w.cget('textvariable')) == str(self.pm_loading):
                    loading_entry = w
                    break
            except Exception:
                pass
        if loading_entry is None:
            return
        parent = loading_entry.master
        try:
            loading_entry.configure(width=12)
        except Exception:
            pass
        # Remove unit/orphan labels in the same editor row. The main label already says Resin loading (mmol/g).
        for c in list(parent.winfo_children()):
            try:
                txt = str(c.cget('text')).strip() if hasattr(c, 'cget') else ''
                if txt in {'mmol/g', '(mmol/g)', 'mol/g', '|'}:
                    try: c.grid_remove()
                    except Exception: pass
                    try: c.pack_forget()
                    except Exception: pass
            except Exception:
                pass
    except Exception:
        pass


def _v281_blur_loading(self):
    """Move focus away from loading entry after command buttons so the insertion caret is not left beside Chemistry."""
    try:
        tree = getattr(self, 'pm_selected_plan_tree', None) or getattr(self, 'pm_selected_material_tree', None)
        if tree is not None:
            tree.focus_set()
    except Exception:
        pass


def _v281_total_sort_key(row):
    mat = str(row.get('material','')).strip().lower()
    cls = str(row.get('class','')).strip().lower()
    if 'resin' in cls:
        g = 0
    elif 'deprotection base' in cls:
        g = 1
    elif mat == 'dmf' or 'reaction solvent 1' in cls:
        g = 2
    elif mat == 'dcm' or 'reaction solvent 2' in cls:
        g = 3
    elif 'coupling reagent' in cls:
        g = 4
    elif 'catalyst' in cls or 'additive' in cls:
        g = 5
    elif 'aa/chemical' in cls or 'chemical' in cls:
        g = 6
    else:
        g = 7
    return (g, str(row.get('material','')))


def _v281_refresh_total_materials(self):
    try:
        # Prefer the robust v280 numeric aggregator, then reorder and normalize names/classes.
        if '_v280_refresh_total_materials' in globals():
            rows = _v280_refresh_total_materials(self) or []
        else:
            rows = []
        tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        if tree is None:
            return rows
        if not rows:
            # Reconstruct from current total tree if v280 did not return rows.
            cols = list(tree['columns'])
            rows = []
            for iid in tree.get_children():
                vals = list(tree.item(iid, 'values'))
                vals += [''] * max(0, len(cols) - len(vals))
                rows.append(dict(zip(cols, vals)))
        fixed = []
        for r in rows:
            rr = dict(r)
            rr['material'] = _v281_canon_ctc_name(rr.get('material',''))
            low = str(rr.get('material','')).strip().lower()
            if low == 'dmf':
                rr['class'] = 'Reaction solvent 1'
            elif low == 'dcm':
                rr['class'] = 'Reaction solvent 2'
            fixed.append(rr)
        fixed.sort(key=_v281_total_sort_key)
        show = ['material','class','MW','Density(g/mL)','total mmol','total amount','note']
        try:
            if '_v280_write_total_tree' in globals():
                _v280_write_total_tree(tree, fixed)
            elif '_v265_write_tree' in globals():
                import pandas as _pd
                _v265_write_tree(tree, _pd.DataFrame(fixed, columns=show), show)
            else:
                for iid in tree.get_children(): tree.delete(iid)
                tree['columns'] = show
                for c in show:
                    tree.heading(c, text=c)
                for row in fixed:
                    tree.insert('', 'end', values=[row.get(c,'') for c in show])
        except Exception:
            pass
        return fixed
    except Exception:
        return []


