# ======================= V2.0.0 STD GHK / 2-CTC SOLVENT REPAIR =======================
# Reference basis: uploaded Tripeptide-1 / GHK 1000 mmol workbook.
# Goal: preserve the existing Project Manager UI/trees, but replace the broken
# 2-CTC GHK-like calculation path with a single deterministic STD calculator.

_V283_AA_MAP = {
    'A':'Fmoc-Ala-OH','R':'Fmoc-Arg(Pbf)-OH','N':'Fmoc-Asn(Trt)-OH','D':'Fmoc-Asp(OtBu)-OH',
    'C':'Fmoc-Cys(Trt)-OH','Q':'Fmoc-Gln(Trt)-OH','E':'Fmoc-Glu(OtBu)-OH','G':'Fmoc-Gly-OH',
    'H':'Fmoc-His(Trt)-OH','I':'Fmoc-Ile-OH','L':'Fmoc-Leu-OH','K':'Fmoc-Lys(Boc)-OH',
    'M':'Fmoc-Met-OH','F':'Fmoc-Phe-OH','P':'Fmoc-Pro-OH','S':'Fmoc-Ser(tBu)-OH',
    'T':'Fmoc-Thr(tBu)-OH','W':'Fmoc-Trp(Boc)-OH','Y':'Fmoc-Tyr(tBu)-OH','V':'Fmoc-Val-OH'
}
_V283_MW = {
    'Fmoc-Gly-OH':297.30, 'Fmoc-His(Trt)-OH':619.70, 'Fmoc-Lys(Boc)-OH':468.50,
    'DIC':126.20, 'HOBt hydrate':135.13, 'DMF':73.09, 'DCM':84.93,
    'MeOH':32.04, 'Piperidine':85.15, 'TFA':114.02, 'H2O':18.015,
}
_V283_DENS = {'DIC':0.8059808403920667, 'DMF':0.944, 'DCM':1.33, 'MeOH':0.792, 'Piperidine':0.862, 'TFA':1.49, 'H2O':1.0}


def _v283_float(v, default=0.0):
    try:
        if v is None: return default
        m = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", str(v).replace(',', ''))
        return float(m.group(0)) if m else default
    except Exception:
        return default


def _v283_int(v, default=0):
    try: return int(float(str(v).replace(',', '')))
    except Exception: return default


def _v283_is_ctc_text(resin):
    s = str(resin or '').lower()
    return ('ctc' in s) or ('trityl' in s) or ('tityl' in s) or ('2-chloro' in s) or ('2-choro' in s)


def _v283_resin_name(resin):
    s = str(resin or '').strip()
    if _v283_is_ctc_text(s):
        return 'CTC(합성기)'
    return s or 'Rink Amide AM'


def _v283_tokens(seq):
    try:
        return list(tokenize_core_sequence(str(seq or '').strip()))
    except Exception:
        s = str(seq or '').strip()
        s = re.sub(r'(?i)^\s*Ac[-_ ]*', '', s)
        s = re.sub(r'(?i)[-_ ]*(NH2|CONH2|COOH|OH)\s*$', '', s)
        return [x for x in re.findall(r'[A-Z]', s.upper()) if x in _V283_AA_MAP]


def _v283_mw_for_name(self, name):
    name = str(name or '').strip()
    if name in _V283_MW: return _V283_MW[name]
    try:
        v = self._mw_for_token(name)
        if v: return float(v)
    except Exception: pass
    try:
        return float(getattr(self, 'MW_FALLBACK', {}).get(name, 0.0) or 0.0)
    except Exception:
        return 0.0


def _v283_aa_name(self, tok):
    tok = str(tok or '').strip()
    if tok in _V283_AA_MAP: return _V283_AA_MAP[tok]
    try:
        nm = self._protected_name_for_token(tok)
        return str(nm or tok).strip()
    except Exception:
        return tok


def _v283_aa_eqs_for_ctc(tokens, default_eq=2.0):
    """C->N synthesis eq profile for 2-CTC reference mode.
    For GHK / tripeptide STD: C-terminal loading residue 1.0 eq,
    middle residue 1.5 eq, N-terminal residue 2.0 eq.
    For longer/non-STD sequences, first loading remains 1.0 eq and the rest
    use the editable default coupling eq to preserve existing functionality.
    """
    synth = list(reversed(tokens))
    n = len(synth)
    out = []
    for i, tok in enumerate(synth):
        if i == 0:
            eq = 1.0
        elif n == 3 and i == 1:
            eq = 1.5
        elif n == 3 and i == 2:
            eq = 2.0
        else:
            eq = float(default_eq or 2.0)
        out.append((tok, eq))
    return out


def _v283_fmt_num(x, nd=4):
    try:
        xf=float(x)
        if abs(xf-round(xf)) < 1e-9: return str(int(round(xf)))
        return (f"{xf:.{nd}f}").rstrip('0').rstrip('.')
    except Exception:
        return str(x)


def _v283_fmt_amount(g=0.0, ml=0.0):
    if ml and abs(float(ml)) > 1e-12:
        return f"{_v283_fmt_num(ml, 3)} mL"
    if g and abs(float(g)) > 1e-12:
        return f"{_v283_fmt_num(g, 4)} g"
    return ''


def _v283_build_ctc_reference(self):
    seq = str(getattr(self, 'pm_sequence', getattr(self, 'seq', _v225_const_var(""))).get() if hasattr(self, 'pm_sequence') else self.seq.get()).strip()
    tokens = _v283_tokens(seq)
    if not tokens:
        return None
    scale = _v283_float(self.pm_scale.get() if hasattr(self, 'pm_scale') else self.scale.get(), 0.0)
    copies = max(1, _v283_int(self.pm_copies.get() if hasattr(self, 'pm_copies') else 1, 1))
    total_scale = scale * copies
    loading = _v283_float(self.pm_loading.get() if hasattr(self, 'pm_loading') else self.loading.get(), 0.0)
    resin = _v283_resin_name(self.pm_resin.get() if hasattr(self, 'pm_resin') else self.resin.get())
    chem = str(self.pm_chemistry.get() if hasattr(self, 'pm_chemistry') else 'DIC/HOBt')
    default_eq = _v283_float(getattr(self, 'coupling_eq', _v225_const_var(2.0)).get(), 2.0)
    vol = total_scale * 4.0  # GHK / 2-CTC STD: 1000 mmol -> 4000 mL working volume.
    if total_scale <= 0 or loading <= 0:
        raise ValueError('Scale/loading must be positive for 2-CTC STD calculation.')

    aa_eqs = _v283_aa_eqs_for_ctc(tokens, default_eq=default_eq)
    plan_cols = ['No','Unit name','MW','Density(g/mL)','Unit mmol','Unit amount','Reagent 1','R1 MW','R1 Density','R1 mmol','R1 amount','Reagent 2 / catalyst','R2 MW','R2 Density','R2 mmol','R2 amount','Base','Base MW','Base Density','Base mmol','Base amount','Coupling solvent','Solvent mL','Repeat','Note']
    plan = []
    materials = []
    checklist = []
    line = 1

    def add_mat(step, material, cls, mw='', dens='', mmol='', g=0.0, ml=0.0, count='', repeat='', phase='', note='', source='STD 2-CTC reference'):
        if not str(material or '').strip(): return
        materials.append({
            'step': step, 'material': material, 'class': cls, 'MW': mw, 'density_g_per_mL': dens,
            'planned_mmol': round(float(mmol),4) if isinstance(mmol,(int,float)) or str(mmol).replace('.','',1).isdigit() else mmol,
            'planned_g': round(float(g),6) if g else '', 'planned_mL': round(float(ml),6) if ml else '',
            'use_count': count, 'repeat': repeat, 'phase': phase, 'note': note, 'source': source
        })

    def add_check(operation, unit='', next_step='', note=''):
        nonlocal line
        checklist.append({'line': line, 'done': 'No', 'checked_at': '', 'operation': operation, 'unit': unit, 'next_step': next_step, 'note': note})
        line += 1

    # Resin / fixed process solvents.
    resin_g = total_scale / loading
    add_mat('resin', resin, 'Resin', mmol=total_scale, g=resin_g, phase='resin', note=f'Resin loading {loading:g} mmol/g; scale {scale:g} mmol x copies {copies}', source='scale/loading')
    add_check('DCM swell', resin, '2-CTC loading', f'Working volume {vol:g} mL; CTC STD = 4 mL/mmol')

    # Plan rows and AA material rows.
    synth_len = len(aa_eqs)
    total_dic_mmol = 0.0
    total_hobt_mmol = 0.0
    for idx, (tok, aa_eq) in enumerate(aa_eqs, start=1):
        aa_name = _v283_aa_name(self, tok)
        mw = _v283_mw_for_name(self, aa_name)
        aa_mmol = total_scale * aa_eq
        aa_g = aa_mmol * mw / 1000.0 if mw else 0.0
        is_loading = idx == 1
        is_dic_hobt = ('DIC' in chem.upper() or 'HOBT' in chem.upper() or chem.strip() == '')
        r1 = r1_mw = r1_den = r1_mmol = r1_amt = r2 = r2_mw = r2_den = r2_mmol = r2_amt = ''
        solvent = 'DCM' if is_loading else 'DMF'
        solvent_ml = vol
        note = '2-CTC first residue loading; no DIC/HOBt; after loading: DMF wash x2 -> MeOH capping' if is_loading else 'STD coupling after Fmoc deprotection/DMF wash; post-coupling DMF wash x2'
        if (not is_loading) and is_dic_hobt:
            reagent_eq = 1.5 if synth_len == 3 else _v283_float(getattr(self, 'default_reagent_eq', _v225_const_var(1.5)).get(), 1.5)
            r1 = 'DIC'; r1_mw = 126.20; r1_den = 0.8059808403920667; r1_mmol = total_scale * reagent_eq
            r1_ml = (r1_mmol * r1_mw / 1000.0) / r1_den
            r1_amt = f"{_v283_fmt_num(r1_ml,3)} mL"
            r2 = 'HOBt hydrate'; r2_mw = 135.13; r2_mmol = total_scale * reagent_eq
            r2_g = r2_mmol * r2_mw / 1000.0
            r2_amt = f"{_v283_fmt_num(r2_g,4)} g"
            total_dic_mmol += r1_mmol; total_hobt_mmol += r2_mmol
        plan.append({
            'No': idx, 'Unit name': aa_name, 'MW': _v283_fmt_num(mw,3) if mw else '', 'Density(g/mL)': '',
            'Unit mmol': _v283_fmt_num(aa_mmol,4), 'Unit amount': _v283_fmt_amount(g=aa_g),
            'Reagent 1': r1, 'R1 MW': _v283_fmt_num(r1_mw,3) if r1_mw else '', 'R1 Density': _v283_fmt_num(r1_den,6) if r1_den else '',
            'R1 mmol': _v283_fmt_num(r1_mmol,4) if r1_mmol != '' else '', 'R1 amount': r1_amt,
            'Reagent 2 / catalyst': r2, 'R2 MW': _v283_fmt_num(r2_mw,3) if r2_mw else '', 'R2 Density': _v283_fmt_num(r2_den,6) if r2_den else '',
            'R2 mmol': _v283_fmt_num(r2_mmol,4) if r2_mmol != '' else '', 'R2 amount': r2_amt,
            'Base': '', 'Base MW': '', 'Base Density': '', 'Base mmol': '', 'Base amount': '',
            'Coupling solvent': solvent, 'Solvent mL': _v283_fmt_num(solvent_ml,3), 'Repeat': 1, 'Note': note
        })
        add_mat(idx, aa_name, 'AA/Chemical', mw=round(mw,3) if mw else '', mmol=aa_mmol, g=aa_g, count=1, repeat=1, phase='loading' if is_loading else 'coupling', note=f'{tok} / {aa_eq:g} eq', source=f'step {idx}; unit')
        if is_loading:
            add_check('2-CTC first residue loading', aa_name, 'DMF wash x2', f'{aa_eq:g} eq, {aa_g:.4f} g; loading solvent DCM {vol:g} mL')
            add_check('DMF wash after loading', 'DMF', 'MeOH capping', f'DMF x2 = {vol*2:g} mL')
            add_check('MeOH capping', 'MeOH', 'Fmoc deprotection', f'2-CTC only; MeOH = scale x copies x 0.25 = {total_scale*0.25:g} mL')
        else:
            add_check('Fmoc deprotection x2', '20% Piperidine/DMF', 'DMF wash x6', f'Before {aa_name}')
            add_check('DMF wash after deprotection', 'DMF', 'Coupling', f'DMF x6 = {vol*6:g} mL')
            add_check('DIC/HOBt coupling', aa_name, 'DMF wash x2', f'{aa_eq:g} eq AA; DIC/HOBt hydrate 1.5 eq each' if synth_len == 3 else f'{aa_eq:g} eq AA')
            add_check('Post-coupling DMF wash', 'DMF', 'Next step/final deprotection', f'DMF x2 = {vol*2:g} mL')

    # Reagent totals from the coupling rows.
    if total_dic_mmol > 0:
        dic_ml = (total_dic_mmol * 126.20 / 1000.0) / 0.8059808403920667
        add_mat('coupling total', 'DIC', 'Coupling reagent', mw=126.20, dens=0.8059808403920667, mmol=total_dic_mmol, ml=dic_ml, count=synth_len-1, phase='coupling', note='DIC/HOBt STD: 1.5 eq per non-loading coupling for GHK', source='reference total')
    if total_hobt_mmol > 0:
        hobt_g = total_hobt_mmol * 135.13 / 1000.0
        add_mat('coupling total', 'HOBt hydrate', 'Catalyst/additive', mw=135.13, mmol=total_hobt_mmol, g=hobt_g, count=synth_len-1, phase='coupling', note='HOBt hydrate total from reference workbook', source='reference total')

    # Solvent/deprotection totals from the GHK/2-CTC reference workflow.
    coupling_count = max(0, synth_len - 1)
    dmf_after_loading = vol * 2
    pre_depro_events = coupling_count
    final_depro_events = 1 if synth_len > 0 else 0
    dmf_depro_solution = (pre_depro_events + final_depro_events) * vol * 2 * 0.80
    pip_total = (pre_depro_events + final_depro_events) * vol * 2 * 0.20
    dmf_depro_wash = pre_depro_events * vol * 6
    dmf_coupling = coupling_count * vol
    dmf_post_coupling = coupling_count * vol * 2
    dmf_final_wash = vol * 3
    dmf_total = dmf_after_loading + dmf_depro_solution + dmf_depro_wash + dmf_coupling + dmf_post_coupling + dmf_final_wash
    dcm_total = vol * 5  # swell 1 + loading 1 + final DCM wash 3.
    meoh_total = total_scale * 0.25
    add_mat('loading wash', 'DMF', 'Reaction solvent 1', ml=dmf_after_loading, count=2, phase='loading wash', note='DMF wash x2 immediately after 2-CTC loading', source='reference solvent breakdown')
    add_mat('deprotection solution', 'DMF', 'Reaction solvent 1', ml=dmf_depro_solution, count=(pre_depro_events+final_depro_events)*2, phase='20% piperidine/DMF', note='80% DMF part of deprotection solution', source='reference solvent breakdown')
    add_mat('deprotection wash', 'DMF', 'Reaction solvent 1', ml=dmf_depro_wash, count=pre_depro_events*6, phase='deprotection wash', note='DMF wash x6 after pre-coupling deprotection events', source='reference solvent breakdown')
    add_mat('coupling solvent', 'DMF', 'Reaction solvent 1', ml=dmf_coupling, count=coupling_count, phase='coupling', note='DMF coupling solvent for non-loading couplings', source='reference solvent breakdown')
    add_mat('post-coupling wash', 'DMF', 'Reaction solvent 1', ml=dmf_post_coupling, count=coupling_count*2, phase='post-coupling wash', note='DMF wash x2 after each non-loading coupling', source='reference solvent breakdown')
    add_mat('final wash', 'DMF', 'Reaction solvent 1', ml=dmf_final_wash, count=3, phase='final wash', note='Final DMF wash x3 after final deprotection', source='reference solvent breakdown')
    add_mat('resin/loading/final wash', 'DCM', 'Reaction solvent 2', ml=dcm_total, count=5, phase='swell/loading/final wash', note='MC/DCM total: swell x1 + loading x1 + final DCM x3', source='reference solvent breakdown')
    add_mat('2-CTC capping', 'MeOH', 'Capping solvent', ml=meoh_total, count=1, phase='capping', note='2-CTC only: 1000 mmol -> MeOH 250 mL', source='reference solvent breakdown')
    add_mat('deprotection total', 'Piperidine', 'Deprotection base', ml=pip_total, count=(pre_depro_events+final_depro_events)*2, phase='20% piperidine/DMF', note='20% piperidine part of deprotection solution', source='reference solvent breakdown')

    # Cleavage reference rows from the uploaded Tripeptide-1 workbook. These are included
    # as raw-material totals but kept in a distinct class so synthesis solvent grouping stays clear.
    cleavage_total = total_scale / 2.0 * 14.0
    add_mat('cleavage', 'TFA', 'Cleavage reagent', ml=cleavage_total*0.95, count='', phase='cleavage', note='Reference: scale/2 x 14 x 0.95', source='reference cleavage')
    add_mat('cleavage', 'H2O (cleavage)', 'Cleavage reagent', ml=cleavage_total*0.05, count='', phase='cleavage', note='Reference: scale/2 x 14 x 0.05', source='reference cleavage')

    add_check('Final Fmoc deprotection x2', '20% Piperidine/DMF', 'Final DMF wash x3', f'Piperidine total included; final deprotection solution {vol*2:g} mL')
    add_check('Final DMF wash', 'DMF', 'Final DCM wash x3', f'DMF x3 = {vol*3:g} mL')
    add_check('Final DCM wash', 'DCM', 'Cleavage or dry resin', f'DCM x3; total MC/DCM should be {dcm_total:g} mL')

    return {'plan_cols':plan_cols, 'plan':plan, 'materials':materials, 'checklist':checklist, 'scale':scale, 'copies':copies, 'total_scale':total_scale, 'vol':vol, 'resin':resin, 'loading':loading, 'sequence':seq}


def _v283_material_total_rows(materials):
    groups = {}
    def num(v): return _v283_float(v, 0.0)
    for r in materials or []:
        mat = str(r.get('material','')).strip()
        if not mat: continue
        key = mat
        if key not in groups:
            groups[key] = {'material': mat, 'class': r.get('class',''), 'MW': r.get('MW',''), 'Density(g/mL)': r.get('density_g_per_mL',''), '_mmol':0.0, '_g':0.0, '_ml':0.0}
        groups[key]['_mmol'] += num(r.get('planned_mmol',''))
        groups[key]['_g'] += num(r.get('planned_g',''))
        groups[key]['_ml'] += num(r.get('planned_mL',''))
        # Prefer solvent class when any row says solvent.
        if 'solvent' in str(r.get('class','')).lower() or 'Reaction solvent' in str(r.get('class','')):
            groups[key]['class'] = r.get('class','')
    def sort_key(r):
        cls = str(r.get('class','')).lower(); mat=str(r.get('material','')).lower()
        if 'resin' in cls: g=0
        elif 'aa/chemical' in cls or 'amino' in cls: g=1
        elif 'coupling reagent' in cls: g=2
        elif 'catalyst' in cls or 'additive' in cls: g=3
        elif 'deprotection base' in cls: g=4
        elif 'solvent' in cls or mat in {'dmf','dcm','meoh'}: g=5
        elif 'cleavage' in cls: g=6
        else: g=9
        sub = {'dmf':0,'dcm':1,'meoh':2}.get(mat,0)
        return (g, sub, mat)
    out=[]
    for g in groups.values():
        total_amount=[]
        if g['_g']: total_amount.append(f"{_v283_fmt_num(g['_g'],4)} g")
        if g['_ml']: total_amount.append(f"{_v283_fmt_num(g['_ml'],3)} mL")
        out.append({'material':g['material'], 'class':g['class'], 'MW':g.get('MW',''), 'Density(g/mL)':g.get('Density(g/mL)',''), 'total mmol':_v283_fmt_num(g['_mmol'],4) if g['_mmol'] else '', 'total amount':'; '.join(total_amount), 'note':'Total from 2-CTC STD reference calculation'})
    out.sort(key=sort_key)
    return out


def _v283_write_tree(tree, rows, cols=None):
    if tree is None: return
    rows = list(rows or [])
    if cols is None:
        cols = list(rows[0].keys()) if rows else list(tree['columns'])
    try:
        _kids = list(tree.get_children())
        if _kids: tree.delete(*_kids)
    except Exception:
        for iid in list(tree.get_children()):
            try: tree.delete(iid)
            except Exception: pass
    try: tree['columns'] = cols
    except Exception: pass
    for c in cols:
        try:
            tree.heading(c, text=c)
            w = 120
            if c in {'Note','note','source'}: w = 260
            elif c in {'Unit name','material','operation'}: w = 190
            tree.column(c, width=w, minwidth=80, anchor='w', stretch=True)
        except Exception: pass
    for r in rows:
        tree.insert('', 'end', values=[r.get(c,'') for c in cols])


def _v283_apply_reference_outputs(self):
    data = _v283_build_ctc_reference(self)
    if data is None: return None
    total_rows = _v283_material_total_rows(data['materials'])
    material_cols = ['step','material','class','MW','density_g_per_mL','planned_mmol','planned_g','planned_mL','use_count','repeat','phase','note','source']
    total_cols = ['material','class','MW','Density(g/mL)','total mmol','total amount','note']
    check_cols = ['line','done','checked_at','operation','unit','next_step','note']
    _v283_write_tree(getattr(self, 'pm_selected_plan_tree', None), data['plan'], data['plan_cols'])
    _v283_write_tree(getattr(self, 'pm_selected_material_tree', None), data['materials'], material_cols)
    tt = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
    _v283_write_tree(tt, total_rows, total_cols)
    _v283_write_tree(getattr(self, 'progress_tree', None), data['checklist'], check_cols)
    # Also feed the main workbench usage trees where present.
    for attr in ('live_usage_tree','material_tree'):
        try: _v283_write_tree(getattr(self, attr, None), data['materials'], material_cols)
        except Exception: pass
    # Keep current item state persistent across item switching/export.
    try:
        idx = _v282_current_idx(self) if '_v282_current_idx' in globals() else None
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            item = self.pm_items[idx]
            if '_v282_editor_snapshot' in globals(): item.update(_v282_editor_snapshot(self))
            item['resin'] = data['resin']
            item['selected_plan_records'] = data['plan']
            item['selected_materials_records'] = data['materials']
            item['selected_total_records'] = total_rows
            item['selected_checklist_records'] = data['checklist']
            item['generated_sequence'] = data['sequence']
            item['status'] = 'Ready'
            if '_v282_refresh_pm_list' in globals(): _v282_refresh_pm_list(self, idx)
    except Exception:
        pass
    try:
        self._log(f"2-CTC STD reference calculation applied: sequence={data['sequence']}, total scale={data['total_scale']:g} mmol, working volume={data['vol']:g} mL.\n")
    except Exception: pass
    return data


def _v283_should_use_reference(self):
    try:
        seq = str(self.pm_sequence.get()).strip() if hasattr(self, 'pm_sequence') else str(self.seq.get()).strip()
        resin = str(self.pm_resin.get()).strip() if hasattr(self, 'pm_resin') else str(self.resin.get()).strip()
        chem = str(self.pm_chemistry.get()).strip() if hasattr(self, 'pm_chemistry') else 'DIC/HOBt'
        return bool(seq) and _v283_is_ctc_text(resin) and ('DIC' in chem.upper() or 'HOBT' in chem.upper() or chem == '')
    except Exception:
        return False


