def _v284_bool_var(self, name, default=False):
    try:
        v = getattr(self, name)
        return bool(v.get())
    except Exception:
        return bool(default)


def _v284_set_bool_var(self, name, value):
    try:
        if not hasattr(self, name):
            setattr(self, name, tk.BooleanVar(value=bool(value)))
        else:
            getattr(self, name).set(bool(value))
    except Exception:
        pass


def _v284_is_ctc_resin(resin_value=None):
    s = str(resin_value or '').strip().lower()
    return ('ctc' in s) or ('trityl' in s) or ('tityl' in s) or ('2-chloro' in s) or ('2-choro' in s) or ('합성기' in s)


def _v284_loading_checked_for_resin(self, resin_value=None):
    try:
        resin = resin_value
        if resin is None:
            resin = self.pm_resin.get() if hasattr(self, 'pm_resin') else self.resin.get()
        return bool(_v284_bool_var(self, 'apply_loading_calc', False)) and _v284_is_ctc_resin(resin)
    except Exception:
        return False


def _v284_should_use_reference(self):
    """Use the audited 2-CTC loading STD path only when the existing checkbox is ON."""
    try:
        seq = str(self.pm_sequence.get()).strip() if hasattr(self, 'pm_sequence') else str(self.seq.get()).strip()
        if not seq:
            return False
        resin = str(self.pm_resin.get()).strip() if hasattr(self, 'pm_resin') else str(self.resin.get()).strip()
        chem = str(self.pm_chemistry.get()).strip() if hasattr(self, 'pm_chemistry') else 'DIC/HOBt'
        chem_ok = ('DIC' in chem.upper()) or ('HOBT' in chem.upper()) or (chem.strip() == '')
        return _v284_loading_checked_for_resin(self, resin) and chem_ok
    except Exception:
        return False


