# Eq profile: preserve the uploaded GHK STD exactly. Longer/non-STD sequences keep
# the existing user-editable coupling eq for non-loading residues.
def _v284_aa_eqs_for_ctc(tokens, default_eq=2.0):
    synth = list(reversed(tokens))  # C -> N synthesis order
    if [str(t).upper() for t in tokens] == ['G', 'H', 'K']:
        return [(synth[0], 1.0), (synth[1], 1.5), (synth[2], 2.0)]
    out = []
    for i, tok in enumerate(synth):
        eq = 1.0 if i == 0 else float(default_eq or 2.0)
        out.append((tok, eq))
    return out

