def _v284_add_item(self, item=None):
    if item is None:
        # Fresh Add must be fully blank/default and must not inherit the previous
        # peptide's loading checkbox or generated tables.
        idx = _v284_prev_add_item(self, None) if _v284_prev_add_item is not None else None
        try:
            if idx is None:
                idx = _v282_current_idx(self) if '_v282_current_idx' in globals() else None
            if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
                self.pm_items[idx]['apply_loading_calc'] = False
                self.pm_items[idx]['loading_aa_eq'] = '1'
                self.pm_items[idx]['loading_diea_eq'] = '4'
                _v284_set_bool_var(self, 'apply_loading_calc', False)
                try: self.loading_aa_eq.set('1')
                except Exception: pass
                try: self.loading_diea_eq.set('4')
                except Exception: pass
        except Exception:
            pass
        return idx
    # Caller-supplied item, e.g. initial/project import: preserve supplied data.
    idx = _v284_prev_add_item(self, item) if _v284_prev_add_item is not None else None
    try:
        if idx is None:
            idx = _v282_current_idx(self) if '_v282_current_idx' in globals() else None
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            self.pm_items[idx].setdefault('apply_loading_calc', bool(item.get('apply_loading_calc', False)) if isinstance(item, dict) else False)
    except Exception:
        pass
    return idx

