def _v286_get_text_var(self, *names, default=''):
    for name in names:
        try:
            obj = getattr(self, name)
            return str(obj.get()).strip()
        except Exception:
            pass
    return str(default or '').strip()


def _v286_is_ctc(self, resin=None):
    try:
        resin = resin if resin is not None else _v286_get_text_var(self, 'pm_resin', 'resin')
        s = str(resin or '').lower().replace(' ', '')
        return any(x in s for x in ['ctc','trityl','tityl','2-chloro','2-choro','chloro-trityl','chlorotrityl','합성기','합성용'])
    except Exception:
        return False


def _v286_loading_on(self):
    try:
        return bool(getattr(self, 'apply_loading_calc').get())
    except Exception:
        return False


def _v286_should_direct_load(self):
    """Final authoritative predicate for 2-CTC direct-loading mode.
    Chemistry is deliberately not used as a blocker here: the loading checkbox
    means first-residue loading/capping for 2-CTC resin. This prevents DIC/HOBt
    vs HBTU/NMP display choices from silently disabling loading/capping.
    """
    try:
        seq = _v286_get_text_var(self, 'pm_sequence', 'seq')
        if not seq:
            return False
        return _v286_is_ctc(self) and _v286_loading_on(self)
    except Exception:
        return False


def _v286_save_item_state(self):
    try:
        if '_v284_save_current_item' in globals():
            _v284_save_current_item(self)
        elif '_v282_save_current_item' in globals():
            _v282_save_current_item(self)
    except Exception:
        pass
    try:
        idx = _v282_current_idx(self) if '_v282_current_idx' in globals() else None
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            self.pm_items[idx]['apply_loading_calc'] = _v286_loading_on(self)
            if hasattr(self, 'loading_aa_eq'):
                self.pm_items[idx]['loading_aa_eq'] = str(self.loading_aa_eq.get()).strip()
            if hasattr(self, 'loading_diea_eq'):
                self.pm_items[idx]['loading_diea_eq'] = str(self.loading_diea_eq.get()).strip()
    except Exception:
        pass


def _v286_clear_selected_outputs(self):
    for attr in ('pm_selected_plan_tree','pm_selected_material_tree','pm_selected_total_tree','pm_total_tree','progress_tree','pm_selected_check_tree'):
        try:
            tree = getattr(self, attr, None)
            if tree is not None:
                _kids = list(tree.get_children())
                if _kids: tree.delete(*_kids)
        except Exception:
            pass


def _v286_generate(self, force=False):
    try:
        _v286_save_item_state(self)
    except Exception:
        pass
    try:
        if not _v286_get_text_var(self, 'pm_sequence', 'seq'):
            _v286_clear_selected_outputs(self)
            return None
        if _v286_should_direct_load(self):
            # Directly call the audited 2-CTC calculator. Do not call older wrappers.
            return _v283_apply_reference_outputs(self)
        if _v286_prev_generate is not None and _v286_prev_generate is not _v286_generate:
            try:
                return _v286_prev_generate(self, force)
            except TypeError:
                return _v286_prev_generate(self)
    except Exception as exc:
        try: messagebox.showerror('Generate / Update', str(exc))
        except Exception: pass
    finally:
        try: _v286_save_item_state(self)
        except Exception: pass
    return None


def _v286_apply_change(self, save_state=True, refresh_batch=True):
    try:
        _v286_save_item_state(self)
    except Exception:
        pass
    try:
        if not _v286_get_text_var(self, 'pm_sequence', 'seq'):
            _v286_clear_selected_outputs(self)
            return None
        if _v286_should_direct_load(self):
            return _v283_apply_reference_outputs(self)
        if _v286_prev_apply is not None and _v286_prev_apply is not _v286_apply_change:
            try:
                return _v286_prev_apply(self, save_state, refresh_batch)
            except TypeError:
                return _v286_prev_apply(self)
    except Exception as exc:
        try: messagebox.showerror('Apply Change', str(exc))
        except Exception: pass
    finally:
        try: _v286_save_item_state(self)
        except Exception: pass
    return None


def _v286_export(self):
    try:
        # Make visible tables current before direct export.
        if _v286_should_direct_load(self):
            _v283_apply_reference_outputs(self)
        else:
            try: _v286_generate(self, False)
            except Exception: pass
        if '_v285_export_project' in globals():
            return _v285_export_project(self)
        if _v286_prev_export is not None:
            return _v286_prev_export(self)
    except Exception as exc:
        try: messagebox.showerror('Export', str(exc))
        except Exception: pass
    return None


def _v286_add_item(self, item=None):
    try:
        if _v286_prev_add is not None and _v286_prev_add is not _v286_add_item:
            idx = _v286_prev_add(self, item)
        elif '_v284_add_item' in globals():
            idx = _v284_add_item(self, item)
        else:
            idx = None
    except Exception:
        idx = None
    # Fresh Add starts blank and never inherits direct-loading state.
    if item is None:
        try: getattr(self, 'apply_loading_calc').set(False)
        except Exception: pass
        try: getattr(self, 'loading_aa_eq').set('1')
        except Exception: pass
        try: getattr(self, 'loading_diea_eq').set('4')
        except Exception: pass
        try:
            idx2 = _v282_current_idx(self) if '_v282_current_idx' in globals() else idx
            if idx2 is not None and 0 <= idx2 < len(getattr(self, 'pm_items', [])):
                self.pm_items[idx2]['apply_loading_calc'] = False
                self.pm_items[idx2]['loading_aa_eq'] = '1'
                self.pm_items[idx2]['loading_diea_eq'] = '4'
        except Exception:
            pass
        try: _v286_clear_selected_outputs(self)
        except Exception: pass
    return idx


