def _v287_bind_audited_buttons(self):
    try:
        walker = _v282_walk if '_v282_walk' in globals() else _v281_walk
        for w in walker(self):
            try:
                if isinstance(w, ttk.Button):
                    txt = str(w.cget('text')).strip()
                    if txt == 'Add':
                        w.configure(command=lambda _self=self: _v286_add_item(_self))
                    elif txt.startswith('Generate / Update'):
                        w.configure(command=lambda _self=self: _v286_generate(_self, False))
                    elif txt == 'Apply Change':
                        w.configure(command=lambda _self=self: _v286_apply_change(_self, True, True))
                    elif txt == 'Export':
                        w.configure(command=lambda _self=self: _v286_export(_self))
                elif isinstance(w, ttk.Checkbutton):
                    try:
                        if str(w.cget('variable')) == str(getattr(self, 'apply_loading_calc')):
                            w.configure(command=lambda _self=self: _self.after_idle(lambda: _v286_generate(_self, False)))
                    except Exception:
                        pass
            except Exception:
                pass
    except Exception:
        pass


def _v287_wrap_legacy(name):
    try:
        orig = globals().get(name)
        if orig is None or getattr(orig, '_v287_wrapped', False):
            return
        def wrapped(self, *args, __orig=orig, **kwargs):
            try:
                result = __orig(self, *args, **kwargs)
            finally:
                try: _v287_bind_audited_buttons(self)
                except Exception: pass
            return result
        wrapped._v287_wrapped = True
        globals()[name] = wrapped
    except Exception:
        pass

