# ======================= V2.0.0 FINAL AUDIT: 2-CTC LOADING DIEA FIX =======================
# The audited 2-CTC direct-loading path already handled first-residue loading,
# DMF wash x2, and MeOH capping, but the loading base (DIEA/DIPEA) was not
# being written into Selected Plan / Selected Materials / Selected Total Materials.
# Keep the existing UI and calculator intact; add DIEA only when the direct
# 2-CTC loading checkbox route is actually active.

try: _v287_prev_build_ctc_reference = _v283_build_ctc_reference
except Exception: _v287_prev_build_ctc_reference = None
try: _v287_prev_total_rows = _v283_material_total_rows
except Exception: _v287_prev_total_rows = None


def _v287_float_from_var(obj, default=0.0):
    try:
        if hasattr(obj, 'get'):
            obj = obj.get()
        return float(str(obj).replace(',', '').strip())
    except Exception:
        return float(default)


def _v287_fmt_amount_g_ml(g=0.0, ml=0.0):
    parts = []
    try:
        if abs(float(g)) > 1e-12:
            parts.append(f"{_v283_fmt_num(float(g),4)} g")
    except Exception:
        pass
    try:
        if abs(float(ml)) > 1e-12:
            parts.append(f"{_v283_fmt_num(float(ml),3)} mL")
    except Exception:
        pass
    return '; '.join(parts)


def _v287_loading_diea_values(self, total_scale):
    eq = _v287_float_from_var(getattr(self, 'loading_diea_eq', None), 4.0)
    if eq <= 0:
        eq = 4.0
    mw = 129.25
    dens = 0.742
    try:
        looked = _v283_mw_for_name(self, 'DIEA')
        if looked:
            mw = float(looked)
    except Exception:
        pass
    try:
        den_lookup = None
        if hasattr(self, '_density_for_token'):
            den_lookup = self._density_for_token('DIEA')
        if den_lookup:
            dens = float(den_lookup)
    except Exception:
        pass
    mmol = float(total_scale) * eq
    g = mmol * mw / 1000.0
    ml = g / dens if dens else 0.0
    return eq, mw, dens, mmol, g, ml


def _v287_build_ctc_reference(self):
    if _v287_prev_build_ctc_reference is None:
        return None
    data = _v287_prev_build_ctc_reference(self)
    if not data:
        return data
    try:
        total_scale = float(data.get('total_scale', 0.0) or 0.0)
        if total_scale <= 0:
            return data
        eq, mw, dens, mmol, g, ml = _v287_loading_diea_values(self, total_scale)
        materials = data.setdefault('materials', [])
        # Avoid duplicates if a future core calculator already emits DIEA.
        has_loading_diea = any(str(r.get('material','')).strip().upper() in {'DIEA','DIPEA'} and 'loading' in str(r.get('phase','')).lower() for r in materials if isinstance(r, dict))
        if not has_loading_diea:
            materials.append({
                'step': 'loading base',
                'material': 'DIEA',
                'class': 'Loading base',
                'MW': round(mw,3),
                'density_g_per_mL': round(dens,6),
                'planned_mmol': round(mmol,4),
                'planned_g': round(g,6),
                'planned_mL': round(ml,6),
                'use_count': 1,
                'repeat': 1,
                'phase': 'loading',
                'note': f'2-CTC first-residue loading base; DIEA {eq:g} eq; resin:AA:DIEA = 1:1:{eq:g} for current STD route',
                'source': '2-CTC loading DIEA fix'
            })
        # Write DIEA into the first Selected Plan row so the operator sees it at the loading step.
        plan = data.get('plan') or []
        if plan and isinstance(plan[0], dict):
            r = plan[0]
            r['Base'] = 'DIEA'
            r['Base MW'] = _v283_fmt_num(mw,3)
            r['Base Density'] = _v283_fmt_num(dens,6)
            r['Base mmol'] = _v283_fmt_num(mmol,4)
            r['Base amount'] = _v287_fmt_amount_g_ml(g, ml)
            old_note = str(r.get('Note','')).strip()
            add_note = f'DIEA {eq:g} eq included for 2-CTC loading'
            r['Note'] = (old_note + '; ' + add_note).strip('; ')
        # Add/upgrade checklist note.
        checklist = data.get('checklist') or []
        for row in checklist:
            try:
                if 'first residue loading' in str(row.get('operation','')).lower():
                    note = str(row.get('note','')).strip()
                    extra = f'DIEA {eq:g} eq = {_v283_fmt_num(ml,3)} mL ({_v283_fmt_num(g,4)} g)'
                    if 'DIEA' not in note.upper():
                        row['note'] = (note + '; ' + extra).strip('; ')
                    break
            except Exception:
                pass
    except Exception as exc:
        try:
            data.setdefault('materials', []).append({'step':'warning','material':'DIEA','class':'Loading base','note':f'DIEA loading calculation skipped: {exc}'})
        except Exception:
            pass
    return data


def _v287_material_total_rows(materials):
    """Same numeric grouping as v283, with an explicit sort bucket for loading base."""
    groups = {}
    def num(v): return _v283_float(v, 0.0)
    for r in materials or []:
        mat = str(r.get('material','')).strip()
        if not mat:
            continue
        key = mat.upper() if mat.upper() in {'DIEA','DIPEA'} else mat
        if key not in groups:
            groups[key] = {'material': mat, 'class': r.get('class',''), 'MW': r.get('MW',''), 'Density(g/mL)': r.get('density_g_per_mL',''), '_mmol':0.0, '_g':0.0, '_ml':0.0}
        groups[key]['_mmol'] += num(r.get('planned_mmol',''))
        groups[key]['_g'] += num(r.get('planned_g',''))
        groups[key]['_ml'] += num(r.get('planned_mL',''))
        cls_now = str(r.get('class',''))
        if 'solvent' in cls_now.lower() or 'Reaction solvent' in cls_now or 'base' in cls_now.lower():
            groups[key]['class'] = r.get('class','')
        if r.get('MW',''):
            groups[key]['MW'] = r.get('MW','')
        if r.get('density_g_per_mL',''):
            groups[key]['Density(g/mL)'] = r.get('density_g_per_mL','')
    def sort_key(r):
        cls = str(r.get('class','')).lower(); mat=str(r.get('material','')).lower()
        if 'resin' in cls: g=0
        elif 'aa/chemical' in cls or 'amino' in cls: g=1
        elif 'loading base' in cls or mat in {'diea','dipea'}: g=2
        elif 'coupling reagent' in cls: g=3
        elif 'catalyst' in cls or 'additive' in cls: g=4
        elif 'deprotection base' in cls: g=5
        elif 'solvent' in cls or mat in {'dmf','dcm','meoh'}: g=6
        elif 'cleavage' in cls: g=7
        else: g=9
        sub = {'diea':0,'dipea':0,'dmf':0,'dcm':1,'meoh':2}.get(mat,0)
        return (g, sub, mat)
    out=[]
    for g in groups.values():
        total_amount=[]
        if g['_g']: total_amount.append(f"{_v283_fmt_num(g['_g'],4)} g")
        if g['_ml']: total_amount.append(f"{_v283_fmt_num(g['_ml'],3)} mL")
        out.append({'material':g['material'], 'class':g['class'], 'MW':g.get('MW',''), 'Density(g/mL)':g.get('Density(g/mL)',''), 'total mmol':_v283_fmt_num(g['_mmol'],4) if g['_mmol'] else '', 'total amount':'; '.join(total_amount), 'note':'Total from audited 2-CTC reference calculation'})
    out.sort(key=sort_key)
    return out

# Route the existing audited output writer through the DIEA-aware build and total functions.
