# Fixes from latest Windows feedback:
# 1) Selected Materials is step-by-step again.
# 2) Selected Total Materials remains aggregated.
# 3) Cleavage cocktail uses bench volume rule, not molar neat-TFA volume.
# 4) Liquid/solution rows display mL-only in operator-facing material tables.


def _v217_display_liquid_ml_only(df):
    try:
        import pandas as _pd
        if df is None or df.empty:
            return df
        out = df.copy()
        mat = out.get('material', _pd.Series([''] * len(out))).astype(str).str.lower()
        state = out.get('physical_state', _pd.Series([''] * len(out))).astype(str).str.lower()
        dens = _pd.to_numeric(out.get('density_g_mL', out.get('density_g_per_mL', _pd.Series([0] * len(out)))), errors='coerce').fillna(0)
        liquid_names = ('dic','diea','dipea','dmf','dcm','mc/dcm','mc','tfa','tis','edt','acoh','tfe','piperidine','water','dw / water','triethylsilane','anisole','thioanisole')
        is_liq = mat.map(lambda x: any(x == n or x.startswith(n + ' ') or x.startswith(n + ' -') for n in liquid_names)) | state.isin(['liquid','solution']) | dens.gt(0) & mat.map(lambda x: any(n in x for n in liquid_names))
        for c in ('planned_g','planned_mg','approx_g'):
            if c in out.columns:
                out[c] = out[c].astype(object)
                out.loc[is_liq, c] = ''
        if 'unit' in out.columns:
            out.loc[is_liq, 'unit'] = 'mL'
        return out
    except Exception:
        return df


def _v217_core_tables(self):
    _v2093_app_path()
    import pandas as _pd
    from spps_planner.engine import (
        generate_excel_like_synthesis_table, generate_step_materials, generate_materials,
        generate_detailed_operations, generate_cleavage_cocktail, cleavage_cocktail_presets,
        validate_plan, plan_summary
    )
    inp = _v2093_plan_input(self)
    meta = _v2093_metadata(self, inp)
    plan = generate_excel_like_synthesis_table(inp)
    step_materials = _v217_display_liquid_ml_only(generate_step_materials(inp))
    total_materials = _v217_display_liquid_ml_only(generate_materials(inp))
    operations = generate_detailed_operations(inp)
    cleavage = generate_cleavage_cocktail(inp)
    # For the cleavage calculator keep approximate grams visible for reference;
    # material tabs remain mL-only for liquids.
    presets = cleavage_cocktail_presets()
    validation = validate_plan(inp)
    summary = _pd.DataFrame([plan_summary(inp)])
    return inp, meta, {
        'selected_plan_core': plan,
        'selected_materials_core': step_materials,
        'selected_total_materials_core': total_materials,
        'operations_core': operations,
        'cleavage_cocktail': cleavage,
        'cleavage_presets': presets,
        'validation': validation,
        'summary': summary,
    }


def _v217_refresh_selected_outputs(self):
    try:
        inp, meta, tables = _v217_core_tables(self)
        if hasattr(self, 'pm_selected_plan_tree'):
            _v2093_write_tree(self, self.pm_selected_plan_tree, tables['selected_plan_core'])
        if hasattr(self, 'pm_selected_material_tree'):
            _v2093_write_tree(self, self.pm_selected_material_tree, tables['selected_materials_core'])
        total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        if total_tree is not None:
            _v2093_write_tree(self, total_tree, tables['selected_total_materials_core'])
        try:
            txt = getattr(self, 'pm_selected_check_text', None)
            if txt is not None:
                txt.delete('1.0', 'end')
                for _, r in tables['operations_core'].iterrows():
                    txt.insert('end', f"[{r.get('line','')}] Step {r.get('step','')} {r.get('unit','')} - {r.get('operation_group','')}: {r.get('operation_detail','')} | {r.get('solution_note','')}\n")
        except Exception:
            pass
        try: _v2093_refresh_cleavage(self, tables.get('cleavage_cocktail'))
        except Exception: pass
        return tables
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
        return None


def _v217_generate(self, *args, **kwargs):
    try:
        _v2093_save_active(self)
        tables = _v217_refresh_selected_outputs(self)
        idx = _v2093_active_index(self)
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            self.pm_items[idx]['status'] = 'Calculated'
            _v2093_refresh_list(self, [idx])
        try: self.schedule_autosave()
        except Exception: pass
        return tables
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
        return None


def _v217_export_outputs(self):
    try:
        import json as _json
        import pandas as _pd
        from pathlib import Path as _Path
        _v2093_app_path()
        from spps_planner.export import export_csvs, export_excel
        _v2093_save_active(self)
        inp, meta, tables = _v217_core_tables(self)
        try:
            out = _Path(self.project_outdir.get()) if hasattr(self, 'project_outdir') and self.project_outdir.get() else _Path(self.outdir.get())
        except Exception:
            out = _Path('outputs') / 'project_manager_exports'
        out.mkdir(parents=True, exist_ok=True)
        export_csvs(inp, out / 'core_engine_outputs')
        export_excel(inp, out / 'spps_plan_core_engine.xlsx')
        # Rebuild visible tables from the current GUI after ensuring a refresh.
        _v217_refresh_selected_outputs(self)
        visible_plan = _v2093_tree_to_df(getattr(self, 'pm_selected_plan_tree', None))
        visible_mats = _v2093_tree_to_df(getattr(self, 'pm_selected_material_tree', None))
        total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        visible_total = _v2093_tree_to_df(total_tree)
        cleavage_df = tables['cleavage_cocktail']
        xlsx = out / 'project_manager_selected_outputs_v2.1.7.xlsx'
        with _pd.ExcelWriter(xlsx, engine='openpyxl') as w:
            _pd.DataFrame([meta]).to_excel(w, index=False, sheet_name='00_EDITOR_SUMMARY')
            visible_plan.to_excel(w, index=False, sheet_name='01_SELECTED_PLAN_VISIBLE')
            visible_mats.to_excel(w, index=False, sheet_name='02_SELECTED_MATERIALS_STEP')
            visible_total.to_excel(w, index=False, sheet_name='03_SELECTED_TOTAL_MATERIALS')
            tables['operations_core'].to_excel(w, index=False, sheet_name='04_OPERATIONS_CORE')
            cleavage_df.to_excel(w, index=False, sheet_name='05_CLEAVAGE_COCKTAIL')
            tables['cleavage_presets'].to_excel(w, index=False, sheet_name='06_CLEAVAGE_PRESETS')
            tables['validation'].to_excel(w, index=False, sheet_name='07_VALIDATION')
            tables['summary'].to_excel(w, index=False, sheet_name='08_SUMMARY')
        for name, df in [
            ('01_SELECTED_PLAN_VISIBLE', visible_plan),
            ('02_SELECTED_MATERIALS_STEP', visible_mats),
            ('03_SELECTED_TOTAL_MATERIALS', visible_total),
            ('05_CLEAVAGE_COCKTAIL', cleavage_df),
            ('validation', tables['validation']),
            ('summary', tables['summary']),
        ]:
            try: df.to_csv(out / f'{name}.csv', index=False, encoding='utf-8-sig')
            except Exception: pass
        state = {'app_version': APP_VERSION, 'active_index': _v2093_active_index(self), 'editor': meta, 'pm_items': getattr(self, 'pm_items', [])}
        (out / 'project_manager_state_v2.1.7.json').write_text(_json.dumps(state, ensure_ascii=False, indent=2), encoding='utf-8')
        try: self.last_outdir = out
        except Exception: pass
        try: self._log(f'V2.1.7 export completed: {xlsx}\n')
        except Exception: pass
        try: messagebox.showinfo('Export complete', f'CSV/XLSX exported to:\n{out}')
        except Exception: pass
        return xlsx
    except Exception as e:
        try: messagebox.showerror('Export error', str(e))
        except Exception: pass
        return None


