# ======================= V2.1.9 USER UI FEEDBACK MATERIAL/CLEAVAGE FINAL FIX =======================
# This final router fixes the latest user feedback without deleting classic UI:
# - Selected Materials is step-by-step only.
# - Selected Total Materials is consolidated only.
# - DIC/DIEA/solvents/liquid cleavage components are mL-only in operator-facing views.
# - Chemistry preset buttons no longer change resin or trigger old 2-CTC reference errors.
# - Blank loading safely falls back to 0.8 mmol/g instead of blocking Generate/Apply Change.

try:
    APP_VERSION = 'V2.1.9'
    VERSION_LABEL = 'SPPS Planner GitHub V2.1.9 - UI Rollback to V2.0.94 Layout + Material Order + Setup Fix'
except Exception:
    pass


def _v218_get(widget_or_var, default=''):
    try:
        return widget_or_var.get()
    except Exception:
        return default


def _v218_float(value, default=0.0):
    try:
        if hasattr(value, 'get'):
            value = value.get()
        text = str(value).replace(',', '').strip()
        if not text:
            return float(default)
        return float(text)
    except Exception:
        return float(default)


def _v218_int(value, default=1):
    try:
        if hasattr(value, 'get'):
            value = value.get()
        text = str(value).replace(',', '').strip()
        if not text:
            return int(default)
        return int(float(text))
    except Exception:
        return int(default)


def _v218_safe_loading(self):
    loading = _v218_float(getattr(self, 'pm_loading', None), 0.8)
    if loading <= 0:
        loading = 0.8
        try:
            self.pm_loading.set('0.8')
        except Exception:
            pass
    return loading


def _v218_safe_scale(self):
    scale = _v218_float(getattr(self, 'pm_scale', None), 400.0)
    if scale <= 0:
        scale = 400.0
        try:
            self.pm_scale.set('400')
        except Exception:
            pass
    copies = max(1, _v218_int(getattr(self, 'pm_copies', None), 1))
    return scale * copies, scale, copies


def _v218_parse_chemistry(self):
    chem = str(_v218_get(getattr(self, 'pm_chemistry', None), 'DIC/HOBt') or '').strip()
    up = chem.upper().replace(' ', '')
    if 'HBTU' in up:
        return 'HBTU', '', 'DIEA', 'NMP', 10.0
    if 'HATU' in up:
        return 'HATU', '', 'DIEA', 'DMF', _v218_float(getattr(self, 'coupling_eq', None), 5.0)
    if 'COMU' in up:
        return 'COMU', '', 'DIEA', 'DMF', _v218_float(getattr(self, 'coupling_eq', None), 5.0)
    if 'DIC' in up or 'HOBT' in up or not chem:
        return 'DIC', 'HOBt', '', 'DMF', _v218_float(getattr(self, 'coupling_eq', None), 5.0)
    # fallback to editable advanced fields
    reagent = _v218_get(getattr(self, 'default_reagent', None), 'DIC') or 'DIC'
    catalyst = _v218_get(getattr(self, 'default_catalyst', None), 'HOBt') or ''
    base = _v218_get(getattr(self, 'default_base', None), '') or ''
    solvent = _v218_get(getattr(self, 'default_coupling_solution_solvent', None), 'DMF') or 'DMF'
    return reagent, catalyst, base, solvent, _v218_float(getattr(self, 'coupling_eq', None), 5.0)


def _v218_resin_family_from_editor(self):
    text = str(_v218_get(getattr(self, 'pm_resin', None), 'Rink Amide AM') or '')
    low = text.lower().replace('-', ' ')
    return 'CTC/Trityl' if any(x in low for x in ('ctc', 'trityl', 'chlorotrityl', '2 chloro')) else 'Amide'


def _v218_plan_input(self):
    _v2093_app_path()
    from spps_planner.engine import PlanInput
    try:
        _v2093_save_active(self)
    except Exception:
        pass
    total_scale, single_scale, copies = _v218_safe_scale(self)
    reagent, catalyst, base, solvent, chem_eq = _v218_parse_chemistry(self)
    seq = str(_v218_get(getattr(self, 'pm_sequence', None), 'Ac-EEMQRR-NH2') or '').strip()
    if not seq:
        seq = 'Ac-EEMQRR-NH2'
    return PlanInput(
        sequence=seq,
        resin=_v218_resin_family_from_editor(self),
        scale_mmol=total_scale,
        resin_loading_mmol_g=_v218_safe_loading(self),
        coupling_eq=chem_eq,
        ac_eq=_v218_float(getattr(self, 'modifier_eq', None), 3.0),
        default_coupling_repeats=max(1, _v218_int(getattr(self, 'coupling_repeats', None), 1)),
        default_modifier_repeats=max(1, _v218_int(getattr(self, 'modifier_repeats', None), 1)),
        default_coupling_reagent=reagent,
        default_catalyst=catalyst,
        default_base=base,
        default_reaction_solvent=solvent,
        loading_aa_eq=_v218_float(getattr(self, 'loading_aa_eq', None), 2.0),
        loading_diea_eq=_v218_float(getattr(self, 'loading_diea_eq', None), 4.0),
        auto_short_peptide_eq=True,
        short_peptide_coupling_eq=_v218_float(getattr(self, 'short_peptide_coupling_eq', None), 2.0),
        step_overrides_text='',
        cleavage_eq_override=_v218_float(getattr(self, 'cleavage_eq_override', None), 0.0),
        cleavage_preset=_v218_get(getattr(self, 'cleavage_preset', None), 'AUTO') or 'AUTO',
        cleavage_components_text=_v218_get(getattr(self, 'cleavage_components_text', None), ''),
    )


def _v218_meta(self, inp=None):
    if inp is None:
        inp = _v218_plan_input(self)
    total_scale, single_scale, copies = _v218_safe_scale(self)
    return {
        'app_version': APP_VERSION,
        'project': _v218_get(getattr(self, 'pm_project', None), ''),
        'peptide': _v218_get(getattr(self, 'pm_peptide', None), ''),
        'lot_no': _v218_get(getattr(self, 'pm_lot', None), ''),
        'sequence': inp.sequence,
        'resin': inp.resin,
        'resin_text': _v218_get(getattr(self, 'pm_resin', None), ''),
        'scale_mmol_each': single_scale,
        'copies': copies,
        'scale_mmol_total': inp.scale_mmol,
        'resin_loading_mmol_g': inp.resin_loading_mmol_g,
        'loading_aa_eq': inp.loading_aa_eq,
        'loading_diea_eq': inp.loading_diea_eq,
        'chemistry': _v218_get(getattr(self, 'pm_chemistry', None), ''),
        'cleavage_eq_override': inp.cleavage_eq_override,
        'cleavage_preset': inp.cleavage_preset,
    }


def _v218_is_liquid_name(name):
    s = str(name or '').lower().strip()
    base = s.split(' -')[0].strip()
    names = {'dic','diea','dipea','dmf','dcm','mc','mc/dcm','nmp','tfa','tis','edt','acoh','acetic acid','tfe','tee','piperidine','water','h2o','dw','dw / water','meoh','methanol','thioanisole','anisole','dms','dmso','triethylsilane'}
    return base in names or s in names


def _v218_ml_only_df(df):
    try:
        import pandas as _pd
        out = df.copy()
        mat = out.get('material', _pd.Series([''] * len(out))).astype(str)
        reagent = out.get('reagent', _pd.Series([''] * len(out))).astype(str)
        state = out.get('physical_state', _pd.Series([''] * len(out))).astype(str).str.lower()
        is_liq = mat.map(_v218_is_liquid_name) | reagent.map(_v218_is_liquid_name) | state.isin(['liquid','solution'])
        for c in ('planned_g','planned_mg','approx_g'):
            if c in out.columns:
                out[c] = out[c].astype(object)
                out.loc[is_liq, c] = ''
        if 'unit' in out.columns:
            out.loc[is_liq, 'unit'] = 'mL'
        return out
    except Exception:
        return df


def _v218_total_display_df(total_df):
    import pandas as _pd
    rows = []
    if total_df is None:
        return _pd.DataFrame()
    df = _v218_ml_only_df(total_df).fillna('')
    for _, r in df.iterrows():
        material = str(r.get('material','')).strip()
        if not material:
            continue
        is_liq = _v218_is_liquid_name(material) or str(r.get('unit','')).lower() == 'ml' or str(r.get('physical_state','')).lower() in {'liquid','solution'}
        ml = _v218_float(r.get('planned_mL',''), 0.0)
        g = _v218_float(r.get('planned_g',''), 0.0)
        if is_liq:
            amount = f"{_v283_fmt_num(ml,3)} mL" if ml else ''
        else:
            amount = f"{_v283_fmt_num(g,4)} g" if g else (f"{_v283_fmt_num(ml,3)} mL" if ml else '')
        rows.append({
            'material': material,
            'class': r.get('class',''),
            'MW': r.get('MW',''),
            'Density(g/mL)': r.get('density_g_mL',''),
            'total mmol': r.get('planned_mmol',''),
            'total amount': amount,
            'unit': 'mL' if is_liq else r.get('unit',''),
            'note': r.get('warning','') or r.get('source',''),
        })
    return _pd.DataFrame(rows, columns=['material','class','MW','Density(g/mL)','total mmol','total amount','unit','note'])


def _v218_core_tables(self):
    _v2093_app_path()
    import pandas as _pd
    from spps_planner.engine import (
        generate_excel_like_synthesis_table, generate_step_materials, generate_materials,
        generate_detailed_operations, generate_cleavage_cocktail, cleavage_cocktail_presets,
        validate_plan, plan_summary,
    )
    inp = _v218_plan_input(self)
