    return inp, meta, {
        'selected_plan_core': generate_excel_like_synthesis_table(inp),
        'selected_materials_core': step_mats,
        'selected_total_materials_core': total_raw,
        'selected_total_materials_visible': _v218_total_display_df(total_raw),
        'operations_core': generate_detailed_operations(inp),
        'cleavage_cocktail': generate_cleavage_cocktail(inp),
        'cleavage_presets': cleavage_cocktail_presets(),
        'validation': validate_plan(inp),
        'summary': _pd.DataFrame([plan_summary(inp)]),
    }


