_V221_LIQUID_NAMES_GUI = {
    'dic','diea','dipea','dmf','dcm','mc','mc/dcm','nmp','tfa','tis','edt','acoh','acetic acid','tfe','tee',
    'piperidine','water','h2o','dw','dw / water','meoh','methanol','acetic anhydride','ac2o','tea','triethylamine',
    'pyridine','thioanisole','anisole','dms','dmso','triethylsilane'
}
_V221_AA_REAGENT_NAMES_GUI = {
    'A':'Fmoc-Ala-OH','R':'Fmoc-Arg(Pbf)-OH','N':'Fmoc-Asn(Trt)-OH','D':'Fmoc-Asp(OtBu)-OH','C':'Fmoc-Cys(Trt)-OH',
    'Q':'Fmoc-Gln(Trt)-OH','E':'Fmoc-Glu(OtBu)-OH','G':'Fmoc-Gly-OH','H':'Fmoc-His(Trt)-OH','I':'Fmoc-Ile-OH',
    'L':'Fmoc-Leu-OH','K':'Fmoc-Lys(Boc)-OH','M':'Fmoc-Met-OH','F':'Fmoc-Phe-OH','P':'Fmoc-Pro-OH','S':'Fmoc-Ser(tBu)-OH',
    'T':'Fmoc-Thr(tBu)-OH','W':'Fmoc-Trp(Boc)-OH','Y':'Fmoc-Tyr(tBu)-OH','V':'Fmoc-Val-OH'
}

def _v221_norm_gui(x):
    try:
        return re.sub(r'[^0-9a-z가-힣/]+', '', str(x or '').strip().lower())
    except Exception:
        return str(x or '').lower()

def _v221_display_resin(self=None, value=''):
    try:
        raw = str(value or '').strip()
        if not raw and self is not None and hasattr(self, 'pm_resin'):
            raw = str(self.pm_resin.get() or '').strip()
        n = _v221_norm_gui(raw)
        if 'ctc' in n or 'trityl' in n or '합성기' in raw or '합성용' in raw:
            return '2-CTC'
        return raw or 'Rink Amide AM'
    except Exception:
        return 'Rink Amide AM'

def _v221_is_liquid_gui(name='', cls='', state='', unit=''):
    s = str(name or '').strip().lower()
    base = s.split(' -')[0].strip()
    cls_l = str(cls or '').strip().lower()
    state_l = str(state or '').strip().lower()
    unit_l = str(unit or '').strip().lower()
    if unit_l == 'ml' or state_l in {'liquid','solution','mixture'}:
        return True
    if base in _V221_LIQUID_NAMES_GUI or s in _V221_LIQUID_NAMES_GUI:
        return True
    if base in {'dic','diea'}:
        return True
    if 'solvent' in cls_l or 'solution' in cls_l:
        return True
    if 'cleavage' in cls_l and base not in {'resin'}:
        return True
    return False

def _v221_num_gui(v, default=0.0):
    try:
        if v is None or str(v).strip() == '':
            return default
        return float(str(v).replace(',', '').strip())
    except Exception:
        return default

def _v221_fmt_gui(v, digits=4):
    try:
        x = float(v)
    except Exception:
        return ''
    if abs(x) < 1e-12:
        return ''
    return f'{x:.{digits}f}'.rstrip('0').rstrip('.')

def _v221_extract_ml_from_amount(text):
    s = str(text or '')
    # Supports broken old values like "517 g; 696.765 mL" and returns 696.765.
    m = re.search(r'([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s*mL\b', s, flags=re.I)
    if m:
        try: return float(m.group(1))
        except Exception: return 0.0
    return 0.0

def _v221_clean_operator_df(self, df, *, total=False):
    import pandas as _pd
    if df is None or getattr(df, 'empty', True):
        return _pd.DataFrame() if df is None else df
    out = df.copy().astype(object).where(_pd.notna(df), '')
    resin_disp = _v221_display_resin(self)
    for idx, r in out.iterrows():
        mat = str(r.get('material', r.get('component', '')) or '').strip()
        cls = str(r.get('class', r.get('role', '')) or '').strip()
        state = str(r.get('physical_state', '') or '').strip()
        unit = str(r.get('unit', '') or '').strip()
        reagent = str(r.get('reagent', '') or '').strip()
        # Never expose old internal resin aliases in user-facing tables.
        if str(r.get('step', '')).strip().lower() == 'resin' or mat.lower() == 'resin' or 'ctc' in _v221_norm_gui(mat) and 'resin' in cls.lower():
            if 'material' in out.columns:
                out.at[idx, 'material'] = resin_disp
            if 'reagent' in out.columns:
                out.at[idx, 'reagent'] = resin_disp
            mat = resin_disp
        # Total table should show bottle/protected reagent names, not one-letter residues.
        if mat in _V221_AA_REAGENT_NAMES_GUI and str(cls).upper() == 'AA':
            mat = _V221_AA_REAGENT_NAMES_GUI[mat]
            out.at[idx, 'material'] = mat
            if 'class' in out.columns:
                out.at[idx, 'class'] = 'AA/Chemical'
        is_liq = _v221_is_liquid_gui(mat, cls, state, unit) or _v221_is_liquid_gui(reagent, cls, state, unit)
        if not is_liq:
            continue
        density = _v221_num_gui(r.get('density_g_mL', r.get('Density(g/mL)', '')), 0.0)
        g = _v221_num_gui(r.get('planned_g', r.get('total_g', '')), 0.0)
        ml = _v221_num_gui(r.get('planned_mL', r.get('total_mL', r.get('volume_mL', ''))), 0.0)
        if ml <= 0:
            ml = _v221_extract_ml_from_amount(r.get('total amount', r.get('Amount', '')))
        if ml <= 0 and g > 0 and density > 0:
            ml = g / density
        for col in ('planned_g','planned_mg','approx_g','total_g'):
            if col in out.columns:
                out.at[idx, col] = ''
        if 'planned_mL' in out.columns and ml > 0:
            out.at[idx, 'planned_mL'] = ml
        if 'total_mL' in out.columns and ml > 0:
            out.at[idx, 'total_mL'] = ml
        if 'volume_mL' in out.columns and ml > 0:
            out.at[idx, 'volume_mL'] = ml
        if 'unit' in out.columns:
            out.at[idx, 'unit'] = 'mL'
        if 'total amount' in out.columns:
            out.at[idx, 'total amount'] = f'{_v221_fmt_gui(ml,3)} mL' if ml > 0 else ''
        if 'Amount' in out.columns:
            out.at[idx, 'Amount'] = f'{_v221_fmt_gui(ml,3)} mL' if ml > 0 else ''
    return out

def _v221_step_order_df(self, df):
    import pandas as _pd
    if df is None or getattr(df, 'empty', True):
        return _pd.DataFrame() if df is None else df
    out = _v221_clean_operator_df(self, df).copy()
    def step_rank(v):
        s = str(v or '').strip().lower()
        if s == 'resin': return -1000
        if s == 'cleavage': return 100000
        try: return int(float(s)) * 100
        except Exception: return 90000
    def phase_rank(r):
        s = str(r.get('step','')).strip().lower()
        phase = str(r.get('phase','')).strip().lower()
        src = str(r.get('source','')).strip().lower()
        cls = str(r.get('class','')).strip().lower()
        if s == 'resin': return 0
        if 'swell' in phase: return 1
        if 'loading' in phase and ('aa' in cls or 'unit' in src): return 10
        if 'loading' in phase and ('base' in cls or 'aux' in src): return 11
        if 'synthesis' in phase or 'reaction' in phase: return 12
        if 'deprotection' in phase and 'piperidine' in str(r.get('material','')).lower(): return 20
        if 'deprotection' in phase: return 21
        if 'dmf wash' in phase: return 30
        if 'regular aa' in phase or 'coupling' in phase:
            if 'aa' in cls or 'unit' in src: return 40
            if 'coupling reagent' in cls: return 41
            if 'catalyst' in cls: return 42
            if 'base' in cls: return 43
            if 'solvent' in cls: return 44
            return 45
        if 'post' in phase: return 50
        if 'final' in phase: return 60
        if 'cleavage' in phase: return 1000
        return 100
    out['_sort_v221'] = out.apply(lambda r: step_rank(r.get('step','')) + phase_rank(r), axis=1)
    out['_order_v221'] = range(len(out))
    out = out.sort_values(['_sort_v221','_order_v221'], kind='mergesort').drop(columns=['_sort_v221','_order_v221'])
    return out.reset_index(drop=True)

def _v221_total_display_df(self, df):
    import pandas as _pd
    if df is None or getattr(df, 'empty', True):
        return _pd.DataFrame(columns=['material','class','MW','Density(g/mL)','total mmol','total amount','unit','note'])
    d = _v221_clean_operator_df(self, df, total=True)
    rows = []
    for _, r in d.iterrows():
        material = str(r.get('material','')).strip()
        if not material:
            continue
        cls = r.get('class','')
        is_liq = _v221_is_liquid_gui(material, cls, r.get('physical_state',''), r.get('unit',''))
        ml = _v221_num_gui(r.get('planned_mL', r.get('total_mL', '')), 0.0)
        g = _v221_num_gui(r.get('planned_g', r.get('total_g', '')), 0.0)
        if ml <= 0:
            ml = _v221_extract_ml_from_amount(r.get('total amount',''))
        amount = f'{_v221_fmt_gui(ml,3)} mL' if is_liq and ml > 0 else (f'{_v221_fmt_gui(g,4)} g' if g > 0 else '')
        rows.append({
            'material': material,
            'class': cls,
            'MW': r.get('MW',''),
            'Density(g/mL)': r.get('density_g_ML', r.get('density_g_mL', r.get('Density(g/mL)',''))),
            'total mmol': r.get('planned_mmol', r.get('total mmol','')),
            'total amount': amount,
            'unit': 'mL' if is_liq else r.get('unit',''),
            'note': r.get('warning','') or r.get('source','') or r.get('note',''),
        })
    return _pd.DataFrame(rows, columns=['material','class','MW','Density(g/mL)','total mmol','total amount','unit','note'])

def _v221_plan_input(self):
    _v2093_app_path()
    from spps_planner.engine import PlanInput
    try: _v2093_save_active(self)
    except Exception: pass
    total_scale, single_scale, copies = _v218_safe_scale(self)
    reagent, catalyst, base, solvent, chem_eq = _v218_parse_chemistry(self)
    seq = str(_v218_get(getattr(self, 'pm_sequence', None), 'Ac-EEMQRR-NH2') or '').strip() or 'Ac-EEMQRR-NH2'
    return PlanInput(
        sequence=seq,
        resin=_v221_display_resin(self),
        scale_mmol=total_scale,
        resin_loading_mmol_g=_v218_safe_loading(self),
        coupling_eq=chem_eq,
        ac_eq=_v218_float(getattr(self, 'modifier_eq', None), 3.0),
        default_coupling_repeats=max(1, _v218_int(getattr(self, 'coupling_repeats', None), 1)),
        default_modifier_repeats=max(1, _v218_int(getattr(self, 'modifier_repeats', None), 1)),
        default_coupling_reagent=reagent,
        default_catalyst=catalyst,
        default_base=base,
        default_reaction_solvent=solvent,
        loading_aa_eq=_v218_float(getattr(self, 'loading_aa_eq', None), 2.0),
        loading_diea_eq=_v218_float(getattr(self, 'loading_diea_eq', None), 4.0),
        auto_short_peptide_eq=True,
        short_peptide_coupling_eq=_v218_float(getattr(self, 'short_peptide_coupling_eq', None), 2.0),
        step_overrides_text='',
        cleavage_eq_override=_v218_float(getattr(self, 'cleavage_eq_override', None), 0.0),
        cleavage_preset=_v218_get(getattr(self, 'cleavage_preset', None), 'AUTO') or 'AUTO',
        cleavage_components_text=_v218_get(getattr(self, 'cleavage_components_text', None), ''),
    )

def _v221_core_tables(self):
    _v2093_app_path()
    import pandas as _pd
    from spps_planner.engine import (
        generate_excel_like_synthesis_table, generate_step_materials, generate_materials,
        generate_detailed_operations, generate_cleavage_cocktail, cleavage_cocktail_presets,
        validate_plan, plan_summary,
    )
    inp = _v221_plan_input(self)
    meta = _v218_meta(self, inp) if '_v218_meta' in globals() else {}
    plan = generate_excel_like_synthesis_table(inp)
    step_mats = _v221_step_order_df(self, generate_step_materials(inp))
    total_raw = _v221_clean_operator_df(self, generate_materials(inp))
    return inp, meta, {
        'selected_plan_core': plan,
        'selected_materials_core': step_mats,
        'selected_total_materials_core': total_raw,
        'selected_total_materials_visible': _v221_total_display_df(self, total_raw),
        'operations_core': generate_detailed_operations(inp),
        'cleavage_cocktail': _v221_clean_operator_df(self, generate_cleavage_cocktail(inp)),
        'cleavage_presets': cleavage_cocktail_presets(),
        'validation': validate_plan(inp),
        'summary': _pd.DataFrame([plan_summary(inp)]),
    }

def _v221_refresh_selected_outputs(self):
    try:
        inp, meta, tables = _v221_core_tables(self)
        if hasattr(self, 'pm_selected_plan_tree'):
            _v2093_write_tree(self, self.pm_selected_plan_tree, tables['selected_plan_core'])
        if hasattr(self, 'pm_selected_material_tree'):
            _v2093_write_tree(self, self.pm_selected_material_tree, tables['selected_materials_core'])
        total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        if total_tree is not None:
            _v2093_write_tree(self, total_tree, tables['selected_total_materials_visible'])
        try:
            txt = getattr(self, 'pm_selected_check_text', None)
            if txt is not None:
                txt.delete('1.0', 'end')
                for _, r in tables['operations_core'].iterrows():
                    txt.insert('end', f"[{r.get('line','')}] Step {r.get('step','')} {r.get('unit','')} - {r.get('operation_group','')}: {r.get('operation_detail','')} | {r.get('solution_note','')}\n")
        except Exception:
            pass
        try: _v2093_refresh_cleavage(self, tables.get('cleavage_cocktail'))
        except Exception: pass
        return tables
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
        return None

def _v221_generate(self, *args, **kwargs):
    try:
        try: _v2093_save_active(self)
        except Exception: pass
        tables = _v221_refresh_selected_outputs(self)
        idx = _v2093_active_index(self) if '_v2093_active_index' in globals() else None
        if idx is not None and 0 <= idx < len(getattr(self, 'pm_items', [])):
            self.pm_items[idx]['status'] = 'Calculated'
            try: _v2093_refresh_list(self, [idx])
            except Exception: pass
        try: self.schedule_autosave()
        except Exception: pass
        return tables
    except Exception as e:
        try: messagebox.showerror('Generate / Update', str(e))
        except Exception: pass
        return None

def _v221_export_outputs(self):
    try:
        import json as _json
        import pandas as _pd
        from pathlib import Path as _Path
        _v2093_app_path()
        from spps_planner.export import export_csvs, export_excel
        _v221_generate(self)
        inp, meta, tables = _v221_core_tables(self)
        try:
            out = _Path(self.project_outdir.get()) if hasattr(self, 'project_outdir') and self.project_outdir.get() else _Path(self.outdir.get())
        except Exception:
            out = _Path('outputs') / 'project_manager_exports'
        out.mkdir(parents=True, exist_ok=True)
        export_csvs(inp, out / 'core_engine_outputs')
        export_excel(inp, out / 'spps_plan_core_engine.xlsx')
        visible_plan = _v2093_tree_to_df(getattr(self, 'pm_selected_plan_tree', None))
        visible_mats = _v2093_tree_to_df(getattr(self, 'pm_selected_material_tree', None))
        total_tree = getattr(self, 'pm_selected_total_tree', None) or getattr(self, 'pm_total_tree', None)
        visible_total = _v2093_tree_to_df(total_tree)
        xlsx = out / 'project_manager_selected_outputs_v2.2.5.xlsx'
        with _pd.ExcelWriter(xlsx, engine='openpyxl') as w:
            _pd.DataFrame([meta]).to_excel(w, index=False, sheet_name='00_EDITOR_SUMMARY')
            visible_plan.to_excel(w, index=False, sheet_name='01_SELECTED_PLAN_VISIBLE')
            visible_mats.to_excel(w, index=False, sheet_name='02_SELECTED_MATERIALS_STEP')
            visible_total.to_excel(w, index=False, sheet_name='03_SELECTED_TOTAL_MATERIALS')
            tables['operations_core'].to_excel(w, index=False, sheet_name='04_OPERATIONS_CORE')
            tables['cleavage_cocktail'].to_excel(w, index=False, sheet_name='05_CLEAVAGE_COCKTAIL')
            tables['cleavage_presets'].to_excel(w, index=False, sheet_name='06_CLEAVAGE_PRESETS')
            tables['validation'].to_excel(w, index=False, sheet_name='07_VALIDATION')
            tables['summary'].to_excel(w, index=False, sheet_name='08_SUMMARY')
        for name, df in [('01_SELECTED_PLAN_VISIBLE', visible_plan), ('02_SELECTED_MATERIALS_STEP', visible_mats), ('03_SELECTED_TOTAL_MATERIALS', visible_total), ('05_CLEAVAGE_COCKTAIL', tables['cleavage_cocktail']), ('validation', tables['validation']), ('summary', tables['summary'])]:
            try: df.to_csv(out / f'{name}.csv', index=False, encoding='utf-8-sig')
            except Exception: pass
        (out / 'project_manager_state_v2.2.5.json').write_text(_json.dumps({'app_version': APP_VERSION, 'active_index': _v2093_active_index(self), 'editor': meta, 'pm_items': getattr(self, 'pm_items', [])}, ensure_ascii=False, indent=2), encoding='utf-8')
        try: self.last_outdir = out
        except Exception: pass
        try: self._log(f'V2.2.5 export completed: {xlsx}\n')
        except Exception: pass
        try: messagebox.showinfo('Export complete', f'CSV/XLSX exported to:\n{out}')
        except Exception: pass
        return xlsx
    except Exception as e:
        try: messagebox.showerror('Export error', str(e))
        except Exception: pass
        return None

def _v221_bind_buttons(self):
    try:
        for w in _v2093_walk(self):
            try:
                if w.winfo_class() not in ('TButton','Button'):
                    continue
                txt = str(w.cget('text')).strip()
                if txt == 'Use DIC/HOBt':
                    w.configure(command=lambda _self=self: _v218_apply_dic_hobt_preset(_self))
                elif txt == 'Use HBTU/NMP 10eq':
                    w.configure(command=lambda _self=self: _v218_apply_hbtu_nmp_preset(_self))
                elif txt.startswith('Generate / Update') or txt in {'Apply Change', 'Apply cleavage'}:
                    w.configure(command=lambda _self=self: _v221_generate(_self))
                elif txt == 'Export':
                    w.configure(command=lambda _self=self: _v221_export_outputs(_self))
                elif txt in {'Show setup','Hide setup'}:
                    w.configure(command=lambda _self=self: _v219_toggle_setup_panel(_self) if '_v219_toggle_setup_panel' in globals() else None)
            except Exception:
                pass
    except Exception:
        pass

def _v221_light_normalize(self):
    try: self.title(VERSION_LABEL)
    except Exception: pass
    try:
        if hasattr(self, 'title_label'):
            self.title_label.configure(text=VERSION_LABEL)
    except Exception: pass
    try:
        from peptiforg_core.ui_helpers import set_pepforge_icon
        set_pepforge_icon(self)
    except Exception: pass
    try: _v2093_ensure_cleavage_vars(self)
    except Exception: pass
    try: _v2093_bind_project_items(self)
    except Exception: pass
    try: _v221_bind_buttons(self)
    except Exception: pass
    try:
        # Keep one fixed Show setup button; do not auto-toggle or duplicate it.
        if '_v219_fix_setup_button' in globals(): _v219_fix_setup_button(self)
    except Exception: pass
    try: _v2093_ensure_cleavage_tab(self)
    except Exception: pass

def _v221_build(self):
    # Use the V2.1.9/classic UI base, but do not auto-generate heavy tables on startup.
    base = globals().get('_v218_prev_build') or globals().get('_v219_base_build')
    if callable(base):
        base(self)
    else:
        try: SPPSGui.__mro__[1].__init__(self)
        except Exception: pass
    _v221_light_normalize(self)
    try:
        self.after_idle(lambda _self=self: _v221_light_normalize(_self))
    except Exception:
        pass

try:
    SPPSGui._build = _v221_build
    SPPSGui.generate_update_plan = _v221_generate
    SPPSGui.pm_generate_selected = _v221_generate
    SPPSGui.pm_calculate_all = _v221_generate
    SPPSGui.apply_change = _v221_generate
    SPPSGui.pm_apply_change = _v221_generate
    SPPSGui.export_outputs = _v221_export_outputs
except Exception:
    pass
