# V2.2.2e: cleavage solids such as phenol remain g; only explicit liquid components are mL-only.
def _v221_is_liquid_gui(name='', cls='', state='', unit=''):  # type: ignore[override]
    s = str(name or '').strip().lower()
    base = s.split(' -')[0].strip()
    cls_l = str(cls or '').strip().lower()
    state_l = str(state or '').strip().lower()
    unit_l = str(unit or '').strip().lower()
    if unit_l == 'ml' or state_l in {'liquid','solution','mixture'}:
        return True
    if state_l in {'solid','solid_wv','powder'}:
        return False
    if base in _V221_LIQUID_NAMES_GUI or s in _V221_LIQUID_NAMES_GUI:
        return True
    if base in {'dic','diea'}:
        return True
    if 'solvent' in cls_l or 'solution' in cls_l:
        return True
    return False
# ======================= END V2.2.2e CLEAVAGE SOLID DISPLAY FIX =======================

# ======================= V2.2.2 FINAL UI-PRESERVED RESIN/MATERIAL FIX =======================
# Keep the V2.1.9/V2.0.94-style UI.  Only repair final display paths:
# - exact resin label is preserved (2-CTC and CTC(합성용/합성기) are not aliases on screen)
# - Selected Materials is protocol order, not totals
# - Selected Total Materials is totals only and includes cleavage cocktail components
# - DIEA/DIC/solvents are mL-only in user-facing tables
# - startup delayed legacy callbacks are cancelled after base UI construction

try:
    APP_VERSION = 'V2.2.2'
    VERSION_LABEL = 'SPPS Planner GitHub V2.2.2 - UI preserved + exact resin/material display fix'
except Exception:
    pass

_V222_LIQUID_NAMES_GUI = {
    'dic','diea','dipea','dmf','dcm','mc','mc/dcm','nmp','tfa','tis','edt','acoh','acetic acid','tfe','tee',
    'piperidine','water','h2o','dw','dw / water','meoh','methanol','acetic anhydride','ac2o','tea','triethylamine',
    'pyridine','thioanisole','anisole','dms','dmso','triethylsilane'
}

def _v222_user_resin_label(self=None, value=''):
    try:
        raw = str(value or '').strip()
        if not raw and self is not None and hasattr(self, 'pm_resin'):
            raw = str(self.pm_resin.get() or '').strip()
        if not raw:
            return 'Rink Amide AM'
        if raw.strip().lower() in {'ctc/trityl','ctc_trityl'}:
            return '2-CTC'
        return raw
    except Exception:
        return 'Rink Amide AM'

# Override old collapsing alias helper.
def _v221_display_resin(self=None, value=''):  # type: ignore[override]
    return _v222_user_resin_label(self, value)

def _v222_num_gui(v, default=0.0):
    try:
        if v is None:
            return default
        s = str(v).replace(',', '').strip()
        if not s:
            return default
        return float(s)
    except Exception:
        return default

def _v222_fmt_gui(v, digits=3):
    try:
        f = float(v)
        if abs(f - round(f)) < 1e-9:
            return str(int(round(f)))
        return (f'{f:.{digits}f}').rstrip('0').rstrip('.')
    except Exception:
        return str(v or '')

def _v222_base_gui(x):
    return str(x or '').strip().lower().split(' -')[0].strip()

def _v222_is_liquid_gui(name='', cls='', state='', unit='', reagent=''):
    base = _v222_base_gui(name)
    rb = _v222_base_gui(reagent)
    s = str(name or '').strip().lower()
    rs = str(reagent or '').strip().lower()
    cls_l = str(cls or '').strip().lower()
    state_l = str(state or '').strip().lower()
    unit_l = str(unit or '').strip().lower()
    if unit_l == 'ml' or state_l in {'liquid','solution','mixture'}:
        return True
    if state_l in {'solid','solid_wv','powder'}:
        return False
    if base in _V222_LIQUID_NAMES_GUI or rb in _V222_LIQUID_NAMES_GUI or s in _V222_LIQUID_NAMES_GUI or rs in _V222_LIQUID_NAMES_GUI:
        return True
    if base in {'dic','diea','dipea'} or rb in {'dic','diea','dipea'}:
        return True
    if 'solvent' in cls_l or 'solution' in cls_l:
        return True
    return False

# Keep old liquid helper name routed to final implementation.
def _v221_is_liquid_gui(name='', cls='', state='', unit=''):  # type: ignore[override]
    return _v222_is_liquid_gui(name, cls, state, unit)

def _v222_clean_operator_df(self, df, *, total=False):
    import pandas as _pd
    if df is None or getattr(df, 'empty', True):
        return _pd.DataFrame() if df is None else df
    out = df.copy().astype(object).where(_pd.notna(df), '')
    resin_label = _v222_user_resin_label(self)
    for idx, r in out.iterrows():
        mat = str(r.get('material', r.get('component','')) or '').strip()
        reagent = str(r.get('reagent','') or '').strip()
        cls = str(r.get('class', r.get('role','')) or '').strip()
        state = str(r.get('physical_state','') or '').strip()
        unit = str(r.get('unit','') or '').strip()
        step = str(r.get('step','') or '').strip().lower()
        # Exact resin label: 2-CTC stays 2-CTC; CTC(합성용/합성기) stays itself.
        if step == 'resin' or mat.lower() == 'resin' or ('resin' in cls.lower() and ('ctc' in mat.lower() or 'trityl' in mat.lower() or not mat)):
            if 'material' in out.columns:
                out.at[idx, 'material'] = resin_label
            if 'reagent' in out.columns:
                out.at[idx, 'reagent'] = resin_label
            if 'class' in out.columns and cls in {'CTC/Trityl','Amide'}:
                out.at[idx, 'class'] = 'Resin'
            mat = resin_label
        if mat in _V221_AA_REAGENT_NAMES_GUI and str(cls).upper() == 'AA':
            mat = _V221_AA_REAGENT_NAMES_GUI[mat]
            if 'material' in out.columns:
                out.at[idx, 'material'] = mat
            if 'class' in out.columns:
                out.at[idx, 'class'] = 'AA/Chemical'
        is_liq = _v222_is_liquid_gui(mat, cls, state, unit, reagent)
        if not is_liq:
            continue
        density = _v222_num_gui(r.get('density_g_mL', r.get('Density(g/mL)', '')), 0.0)
        g = _v222_num_gui(r.get('planned_g', r.get('total_g', r.get('approx_g', ''))), 0.0)
        ml = _v222_num_gui(r.get('planned_mL', r.get('total_mL', r.get('volume_mL', ''))), 0.0)
        if ml <= 0:
            try:
                ml = _v221_extract_ml_from_amount(r.get('total amount', r.get('Amount', '')))
            except Exception:
                ml = 0.0
        if ml <= 0 and g > 0 and density > 0:
            ml = g / density
        for col in ('planned_g','planned_mg','approx_g','total_g'):
            if col in out.columns:
                out.at[idx, col] = ''
        for col in ('planned_mL','total_mL','volume_mL'):
            if col in out.columns and ml > 0:
                out.at[idx, col] = ml
        if 'unit' in out.columns:
            out.at[idx, 'unit'] = 'mL'
        if 'total amount' in out.columns:
            out.at[idx, 'total amount'] = f'{_v222_fmt_gui(ml,3)} mL' if ml > 0 else ''
        if 'Amount' in out.columns:
            out.at[idx, 'Amount'] = f'{_v222_fmt_gui(ml,3)} mL' if ml > 0 else ''
    return out

