APP_VERSION = 'V2.2.5'
VERSION_LABEL = 'SPPS Planner GitHub V2.2.5 - Full Classic UI + Conditions Restore'

_V224_ACTIVE_RESINS = [
    'Rink Amide AM', 'Rink Amide MBHA', 'Rink Amide ChemMatrix', 'Rink Amide Tentagel',
    '2-CTC', 'CTC(합성기)', 'Wang', 'HMPB', 'Sieber Amide', 'PAL resin', 'Tentagel', 'Manual'
]


def _v224_normalize_saved_resin(value):
    text = str(value or '').strip()
    if text in {'CTC(합성용)', 'CTC 합성용', 'CTC-synthesis', 'CTC synthesis'}:
        return 'CTC(합성기)'
    return text or 'Rink Amide AM'


def _v224_restore_solvent_controls(self):
    """Ensure all established volume controls exist and are visible without placeholders."""
    try:
        # Final legacy helper contains the full resin-factor/molarity panel and calculations.
        if '_v259_add_solvent_basis_controls' in globals():
            _v259_add_solvent_basis_controls(self)
        elif '_v257_add_solvent_basis_controls' in globals():
            _v257_add_solvent_basis_controls(self)
        elif '_v255_add_solvent_basis_controls' in globals():
            _v255_add_solvent_basis_controls(self)
    except Exception:
        pass
    defaults = {
        'solvent_volume_mode': ('resin_factor', tk.StringVar),
        'amide_ml_per_mmol': ('10', tk.StringVar),
        'ctc_ml_per_mmol': ('5', tk.StringVar),
        'solvent_molarity_m': ('0.2', tk.StringVar),
        'ml_per_mmol': ('10', tk.StringVar),
        'default_solvent1': ('DMF', tk.StringVar),
        'default_solvent1_count': (6, tk.IntVar),
        'default_solvent2': ('DCM', tk.StringVar),
        'default_solvent2_count': (3, tk.IntVar),
        'default_loading_dissolve_solvent': ('90% DCM / 10% DMF', tk.StringVar),
        'default_depro_ratio': ('20% in DMF', tk.StringVar),
        'default_depro_count': (2, tk.IntVar),
        'final_meoh_count': (0, tk.IntVar),
        'default_reagent_eq': (5.0, tk.DoubleVar),
        'default_reagent_count': (1, tk.IntVar),
        'default_catalyst_eq': (5.0, tk.DoubleVar),
        'default_catalyst_count': (1, tk.IntVar),
        'default_base_eq': (0.0, tk.DoubleVar),
        'default_base_count': (0, tk.IntVar),
    }
    for name, (value, cls) in defaults.items():
        if not hasattr(self, name):
            try: setattr(self, name, cls(value=value))
            except Exception: pass


def _v224_refresh_resin_widgets(self):
    try:
        SPPSGui.RESIN_VALUES = list(_V224_ACTIVE_RESINS)
        self.RESIN_VALUES = list(_V224_ACTIVE_RESINS)
    except Exception:
        pass
    for name in ('resin', 'pm_resin', 'batch_default_resin'):
        try:
            var = getattr(self, name)
            current = _v224_normalize_saved_resin(var.get())
            if current not in _V224_ACTIVE_RESINS:
                current = 'Rink Amide AM'
            var.set(current)
        except Exception:
            pass
    def walk(widget):
        for child in widget.winfo_children():
            try:
                if isinstance(child, ttk.Combobox):
                    values = [str(x) for x in child.cget('values')]
                    if any(('CTC' in x or 'Rink Amide' in x) for x in values):
                        child.configure(values=list(_V224_ACTIVE_RESINS))
                        try:
                            if str(child.get()).strip() == 'CTC(합성용)':
                                child.set('CTC(합성기)')
                        except Exception:
                            pass
            except Exception:
                pass
            try: walk(child)
            except Exception: pass
    try: walk(self)
    except Exception: pass


_V224_PREVIOUS_BUILD = getattr(SPPSGui, '_build', None)

def _v224_build(self):
    if callable(_V224_PREVIOUS_BUILD):
        _V224_PREVIOUS_BUILD(self)
    _v224_restore_solvent_controls(self)
    _v224_refresh_resin_widgets(self)
    try: self.title(VERSION_LABEL)
    except Exception: pass
    try:
        def walk_title(widget):
            for child in widget.winfo_children():
                try:
                    if isinstance(child, ttk.Label) and str(child.cget('text')).startswith('SPPS Planner'):
                        child.configure(text=VERSION_LABEL)
                except Exception: pass
                try: walk_title(child)
                except Exception: pass
        walk_title(self)
    except Exception:
        pass

SPPSGui.RESIN_VALUES = list(_V224_ACTIVE_RESINS)
SPPSGui._build = _v224_build
