# ======================= V2.2.5 FULL CONDITION/BATCH CONNECTION =======================
def _v225_value(self, name, default=''):
    try:
        obj = getattr(self, name)
        return obj.get() if hasattr(obj, 'get') else obj
    except Exception:
        return default


def _v225_float(self, name, default=0.0):
    try:
        return float(str(_v225_value(self, name, default)).replace(',', '').strip())
    except Exception:
        return float(default)


def _v225_int(self, name, default=0):
    try:
        return int(round(_v225_float(self, name, default)))
    except Exception:
        return int(default)


def _v225_batch_plan_input(self, row):
    """Build the Batch Manager plan from the same live Classic-UI conditions.

    This replaces the old parallel hard-coded 10/80/30 mL estimates.  Project
    Manager, Batch Manager and exports now use the same catalyst/base/solvent
    rules and the same resin-family volume basis.
    """
    _v2093_app_path()
    from spps_planner.engine import PlanInput

    copies = max(1, int(round(_v29_to_float(self, row.get('Copies'), 1))))
    scale_each = _v29_to_float(self, row.get('Scale mmol'), 0.2)
    total_scale = scale_each * copies
    resin = str(row.get('Resin', '') or 'Rink Amide AM')
    loading = _v29_to_float(self, row.get('Loading'), 0.8) or 0.8
    chemistry = str(row.get('Chemistry', '') or 'DIC/HOBt')
    chem_up = chemistry.upper().replace(' ', '')
    aa_eq = _v225_float(self, 'batch_coupling_eq', _v225_float(self, 'coupling_eq', 5.0))

    if 'HBTU' in chem_up:
        reagent, catalyst, base, solvent = 'HBTU', '', 'DIEA', 'NMP'
        reagent_eq = _v225_float(self, 'batch_hbtu_eq', 10.0)
        reagent_count = 1
        catalyst_eq = 0.0
        catalyst_count = 0
        base_eq = _v225_float(self, 'default_base_eq', reagent_eq)
        if base_eq <= 0:
            base_eq = reagent_eq
        base_count = max(1, _v225_int(self, 'default_base_count', 1))
        follow_eq = False
    else:
        reagent = str(_v225_value(self, 'default_reagent', 'DIC') or 'DIC')
        catalyst = str(_v225_value(self, 'default_catalyst', 'HOBt') or '')
        base = str(_v225_value(self, 'default_base', '') or '')
        solvent = str(_v225_value(self, 'default_coupling_solution_solvent', 'DMF') or 'DMF')
        reagent_eq = _v225_float(self, 'default_reagent_eq', aa_eq)
        reagent_count = max(0, _v225_int(self, 'default_reagent_count', 1))
        catalyst_eq = _v225_float(self, 'default_catalyst_eq', aa_eq if catalyst else 0.0)
        catalyst_count = max(0, _v225_int(self, 'default_catalyst_count', 1 if catalyst else 0))
        base_eq = _v225_float(self, 'default_base_eq', aa_eq if base else 0.0)
        base_count = max(0, _v225_int(self, 'default_base_count', 1 if base else 0))
        try:
            follow_eq = bool(_v262_reagent_range_on(self))
        except Exception:
            follow_eq = bool(_v225_value(self, 'reagent_range_mode', False))

    return PlanInput(
        sequence=str(row.get('Sequence', '') or '').strip(),
        resin=resin,
        scale_mmol=total_scale,
        resin_loading_mmol_g=loading,
        coupling_eq=aa_eq,
        ac_eq=_v225_float(self, 'modifier_eq', 3.0),
        default_coupling_repeats=max(1, _v225_int(self, 'coupling_repeats', 1)),
        default_modifier_repeats=max(1, _v225_int(self, 'modifier_repeats', 1)),
        default_coupling_reagent=reagent,
        default_catalyst=catalyst,
        default_base=base,
        default_reaction_solvent=solvent,
        default_reagent_eq=reagent_eq,
        default_reagent_count=reagent_count,
        default_catalyst_eq=catalyst_eq,
        default_catalyst_count=catalyst_count,
        default_base_eq=base_eq,
        default_base_count=base_count,
        reagent_eq_follows_coupling_eq=follow_eq,
        deprotection_base=str(_v225_value(self, 'default_depro', 'Piperidine') or 'Piperidine'),
        deprotection_ratio=str(_v225_value(self, 'default_depro_ratio', '20% in DMF') or '20% in DMF'),
        deprotection_count=max(0, _v225_int(self, 'default_depro_count', 2)),
        wash_solvent1=str(_v225_value(self, 'default_solvent1', 'DMF') or 'DMF'),
        wash_solvent1_count=max(0, _v225_int(self, 'default_solvent1_count', 6)),
        wash_solvent2=str(_v225_value(self, 'default_solvent2', 'DCM') or 'DCM'),
        wash_solvent2_count=max(0, _v225_int(self, 'default_solvent2_count', 3)),
        final_meoh_count=max(0, _v225_int(self, 'final_meoh_count', 0)),
        loading_dissolve_solvent=str(_v225_value(self, 'default_loading_dissolve_solvent', '90% DCM / 10% DMF') or '90% DCM / 10% DMF'),
        solvent_volume_mode=str(_v225_value(self, 'solvent_volume_mode', 'resin_factor') or 'resin_factor'),
        amide_ml_per_mmol=_v225_float(self, 'amide_ml_per_mmol', 10.0),
        ctc_ml_per_mmol=_v225_float(self, 'ctc_ml_per_mmol', 5.0),
        solvent_molarity_m=_v225_float(self, 'solvent_molarity_m', 0.2),
        loading_aa_eq=_v225_float(self, 'loading_aa_eq', 2.0),
        loading_diea_eq=_v225_float(self, 'loading_diea_eq', 4.0),
        # Batch AA eq is an explicit user-entered preparation value; do not
        # silently replace it with the short-peptide automatic rule.
        auto_short_peptide_eq=False,
        short_peptide_coupling_eq=_v225_float(self, 'short_peptide_coupling_eq', 2.0),
        cleavage_preset='AUTO',
    )


def _v225_direct_volume_df(self, totals):
    rows = []
    for (category, item), rec in totals.items():
        calc_ml = float(rec.get('mL', 0.0) or 0.0)
        if calc_ml <= 0:
            continue
        actual_ml = _v29_round_actual_ml(self, calc_ml)
        mw, density = _v29_material_lookup(self, item)
        rows.append({
            'Category': category,
            'Item': item,
            'Solvent': item,
            'Count': int(rec.get('count', 0) or 0),
            'Eq': '',
            'Conc_M': '',
            'Calculated_mL': calc_ml,
            'Actual_mL': actual_ml,
            'MW': mw if mw else '',
            'Density': density if density else '',
            'Weight_g': actual_ml * density if (actual_ml and density) else '',
            'Volume_mL': actual_ml,
            'Note': str(rec.get('note', '') or 'Exact operation total from connected Project/Batch conditions.'),
        })
    return pd.DataFrame(rows, columns=V29_BATCH_COLUMNS)


def _v225_calculate_batch_tables(self):
    """Final non-recursive Batch calculator using the connected core engine."""
    _v2093_app_path()
    from spps_planner.engine import generate_step_reagent_plan, generate_detailed_operations, resin_family

    rows = _v208_pm_rows(self)
    aa_records = {}
    coupling_records = {}
    catalyst_records = {}
    chemical_records = {}
    solvent_totals = {}
    aa_conc = _v225_float(self, 'batch_solution_conc', 0.25)
    aa_eq = _v225_float(self, 'batch_coupling_eq', _v225_float(self, 'coupling_eq', 5.0))
    hbtu_conc = _v225_float(self, 'batch_hbtu_conc', 0.4)

    def add_volume(category, item, mL, note):
        item = str(item or '').strip()
        if not item or float(mL or 0.0) <= 0:
            return
        if item.upper() == 'MC/DCM':
            item = 'DCM'
        key = (category, item)
        rec = solvent_totals.setdefault(key, {'mL': 0.0, 'count': 0, 'note': note})
        rec['mL'] += float(mL or 0.0)
        rec['count'] += 1

    for row in rows:
        inp = _v225_batch_plan_input(self, row)
        copies = max(1, int(round(_v29_to_float(self, row.get('Copies'), 1))))
        scale_each = _v29_to_float(self, row.get('Scale mmol'), 0.2)
        total_scale = scale_each * copies
        try:
            counts = _v201_counts_for_item(self, {'sequence': inp.sequence})
        except Exception:
            counts = _v29_aa_counts_from_seq(self, inp.sequence)
        for aa, local_count in counts.items():
            use_count = float(local_count or 0.0) * copies
            mmol = use_count * scale_each * aa_eq
            _v29_add_record(self, aa_records, 'AA stock', aa, 'DMF', use_count, aa_eq, aa_conc, mmol, 'AA stock final concentration; actual mL includes reserve')

        plan = generate_step_reagent_plan(inp)
        for _, step in plan.iterrows():
            rep = max(0, int(float(step.get('coupling_repeat') or 0)))
            if rep <= 0:
                continue
            phase = str(step.get('phase', '') or '')
            # Dedicated Resin loading table already accounts for C-terminal AA
            # and DIEA on CTC/Trityl loading; do not double-count them here.
            skip_loading_aux = phase == 'Loading' and resin_family(inp.resin) == 'CTC/Trityl'
            if not skip_loading_aux:
                items = [
                    ('Coupling reagent', coupling_records, step.get('coupling_reagent', ''), step.get('coupling_reagent_eq', 0), step.get('coupling_reagent_count', 0)),
                    ('Catalyst/additive', catalyst_records, step.get('catalyst', ''), step.get('catalyst_eq', 0), step.get('catalyst_count', 0)),
                    ('Base', catalyst_records, step.get('base', ''), step.get('base_eq', 0), step.get('base_count', 0)),
                ]
                for category, bucket, name, eq, count in items:
                    name = str(name or '').strip()
                    if not name or name.upper() in {'N/A', 'NONE'}:
                        continue
                    eq = float(eq or 0.0)
                    count = max(0, int(float(count or 0)))
                    if eq <= 0 or count <= 0:
                        continue
                    mmol = total_scale * eq * count * rep
                    solvent = str(step.get('reaction_solvent', '') or inp.default_reaction_solvent)
                    conc = hbtu_conc if name.upper() == 'HBTU' else ''
                    _v29_add_record(self, bucket, category, name, solvent, count * rep, eq, conc, mmol, f'{category} total from connected plan; count/use={count}; reaction repeat={rep}')

            if phase == 'Last / N-term cap':
                unit = str(step.get('unit', '') or '').strip()
                if unit and unit.lower() not in {'fmoc removal'}:
                    unit_mmol = total_scale * float(step.get('total_reagent_eq') or 0.0)
                    _v29_add_record(self, chemical_records, 'N-term chemical', unit, str(step.get('reaction_solvent', '') or inp.default_reaction_solvent), rep, step.get('reagent_eq', ''), '', unit_mmol, 'N-terminal chemical/label/tag from connected plan')

        ops = generate_detailed_operations(inp)
        for _, op in ops.iterrows():
            add_volume('Solvent/operation', op.get('solvent1_name', ''), op.get('solvent1_mL', 0.0), 'Operation solvent 1 total from selected resin/volume mode.')
            add_volume('Deprotection base', op.get('deprotection_base_name', ''), op.get('deprotection_base_mL', 0.0), f'Deprotection condition: {inp.deprotection_ratio}.')
            add_volume('Solvent/operation', op.get('solvent2_name', ''), op.get('solvent2_mL', 0.0), 'Operation solvent 2 total from selected resin/volume mode.')

    summary_cols = ['No', 'Project', 'Peptide name', 'LOT No', 'Sequence', 'Copies', 'Scale mmol', 'Resin', 'Loading', 'Resin_g', 'Chemistry']
    summary = pd.DataFrame([{c: r.get(c, '') for c in summary_cols} for r in rows], columns=summary_cols)
    return {
        'AA stock': _v29_records_to_df(self, aa_records),
        'Resin loading': _v208_resin_loading_df(self, rows),
        'Coupling reagents': _v29_records_to_df(self, coupling_records),
        'Catalyst/additive': _v29_records_to_df(self, catalyst_records),
        'Solvents': _v225_direct_volume_df(self, solvent_totals),
        'Chemicals': _v29_records_to_df(self, chemical_records),
        'Summary': summary,
    }


# Every old refresh/export callback resolves these names at runtime. Rebinding
# all aliases removes the parallel hard-coded calculator without deleting the
# established Batch Manager UI or its visible buttons/tables.
_v29_calculate_batch_tables = _v225_calculate_batch_tables
_v203_calculate_batch_tables = _v225_calculate_batch_tables
_v205_calculate_batch_tables = _v225_calculate_batch_tables
_v208_calculate_batch_tables = _v225_calculate_batch_tables
_v208_calculate_batch_tables_final = _v225_calculate_batch_tables
SPPSGui.calculate_batch_tables = _v225_calculate_batch_tables


def _v225_refresh_batch_workspace_preview(self):
    """Refresh every visible Batch table from the single final calculator."""
    try:
        tables = _v225_calculate_batch_tables(self)
        trees = getattr(self, 'v29_batch_trees', {}) or {}
        for key, tree in trees.items():
            df = tables.get(key, pd.DataFrame())
            if key == 'Summary':
                cols = ['No', 'Project', 'Peptide name', 'LOT No', 'Sequence', 'Copies', 'Scale mmol', 'Resin', 'Loading', 'Resin_g', 'Chemistry']
            else:
                cols = V29_BATCH_COLUMNS
            _v29_write_tree(self, tree, df, cols)
        # Later classic layouts also expose named tree attributes. Keep those
        # views synchronized without making them a second calculation source.
        named = {
            'batch_aa_tree': 'AA stock',
            'batch_coupling_reagent_tree': 'Coupling reagents',
            'batch_catalyst_tree': 'Catalyst/additive',
            'batch_base_tree': 'Catalyst/additive',
            'batch_solvent_tree': 'Solvents',
            'batch_modifier_tree': 'Chemicals',
            'batch_project_tree': 'Summary',
        }
        for attr, key in named.items():
            tree = getattr(self, attr, None)
            if tree is None or tree in trees.values():
                continue
            df = tables.get(key, pd.DataFrame())
            try:
                cols = list(tree.cget('columns') or [])
                _v29_write_tree(self, tree, df, cols or list(df.columns))
            except Exception:
                pass
        self._v225_batch_tables = tables
        return tables
    except Exception as exc:
        _v29_safe_log(self, f'Batch refresh warning: {exc}\n')
        return {}


def _v225_batch_output_dir(self):
    value = _v225_value(self, 'batch_outdir', '')
    if not str(value or '').strip():
        value = Path(str(_v225_value(self, 'outdir', 'spps_output') or 'spps_output')) / 'batch_manager'
    return Path(str(value)).expanduser()


def _v225_export_batch_tables(self, output_dir=None, notify=True):
    """Export Batch Manager from the final connected tables, never UI cache."""
    import json as _json
    out = Path(output_dir) if output_dir is not None else _v225_batch_output_dir(self)
    out.mkdir(parents=True, exist_ok=True)
    tables = _v225_calculate_batch_tables(self)
    xlsx = out / 'batch_manager_tables.xlsx'
    used = set()
    with pd.ExcelWriter(xlsx, engine='openpyxl') as writer:
        for name, df in tables.items():
            sheet = _v255_safe_sheet_name(name, used) if '_v255_safe_sheet_name' in globals() else str(name)[:31]
            (df if df is not None else pd.DataFrame()).to_excel(writer, index=False, sheet_name=sheet)
    state = {
        'app_version': APP_VERSION,
        'saved_at': datetime.now().isoformat(timespec='seconds'),
        'calculation_source': '_v225_calculate_batch_tables',
        'project_count': len(_v208_pm_rows(self)),
        'conditions': {
            'aa_conc_M': _v225_float(self, 'batch_solution_conc', 0.25),
            'aa_eq': _v225_float(self, 'batch_coupling_eq', 5.0),
            'hbtu_eq': _v225_float(self, 'batch_hbtu_eq', 10.0),
            'hbtu_conc_M': _v225_float(self, 'batch_hbtu_conc', 0.4),
            'solvent_volume_mode': str(_v225_value(self, 'solvent_volume_mode', 'resin_factor')),
            'amide_mL_per_mmol': _v225_float(self, 'amide_ml_per_mmol', 10.0),
            'ctc_mL_per_mmol': _v225_float(self, 'ctc_ml_per_mmol', 5.0),
        },
    }
    (out / 'batch_manager_export_state.json').write_text(
        _json.dumps(state, ensure_ascii=False, indent=2), encoding='utf-8'
    )
    self.last_batch_outdir = out
    if notify:
        try:
            messagebox.showinfo('Export complete', f'Batch Manager export saved:\n{xlsx}')
        except Exception:
            pass
    return xlsx


def _v225_export_batch_callback(self):
    try:
        return _v225_export_batch_tables(self, notify=True)
    except Exception as exc:
        try:
            messagebox.showerror('Batch export error', str(exc))
        except Exception:
            pass
        return None


# Final routing: refresh, visible tables and Excel export all use one source.
SPPSGui.refresh_batch_workspace_preview = _v225_refresh_batch_workspace_preview
SPPSGui.export_batch_tables = _v225_export_batch_tables
_v29_export_batch_tables = _v225_export_batch_callback
_v271_export_batch = _v225_export_batch_callback
