# ======================= V2.2.6 FINAL RESIN PROFILE / PER-PEPTIDE LOADING FIX =======================
# Authoritative final layer.  It keeps the complete Classic UI but removes the
# remaining state split between editor, Project Manager, Batch Manager and export:
#   * 2-CTC and CTC(합성기) stay distinct labels and operational profiles.
#   * the Loading checkbox is stored/restored per peptide, never globally reused.
#   * direct loading is applied only to 2-CTC when that peptide's checkbox is ON.
#   * CTC(합성기) is always preloaded; the removed CTC(합성용) alias only migrates
#     old saved projects to CTC(합성기).
#   * Project/Batch/export resolve the same PlanInput and core engine.
APP_VERSION = 'V2.2.6'
VERSION_LABEL = 'SPPS Planner GitHub V2.2.6 - Full Classic UI + Exact Resin/Loading Profiles'


def _v226_normalize_resin(value):
    text = str(value or '').strip()
    if text in {'CTC(합성용)', 'CTC 합성용', 'CTC-synthesis', 'CTC synthesis'}:
        return 'CTC(합성기)'
    if text.strip().lower() in {'ctc/trityl', 'ctc_trityl'}:
        return '2-CTC'
    return text or 'Rink Amide AM'


def _v226_is_direct_resin(value):
    try:
        _v2093_app_path()
        from spps_planner.engine import resin_profile
        return resin_profile(_v226_normalize_resin(value)) == 'CTC_DIRECT'
    except Exception:
        return _v226_normalize_resin(value) == '2-CTC'


def _v226_item_loading_flag(item, resin=None):
    resin = _v226_normalize_resin(resin if resin is not None else (item or {}).get('resin', ''))
    return bool((item or {}).get('apply_loading_calc', False)) and _v226_is_direct_resin(resin)


def _v226_editor_loading_flag(self, resin=None):
    resin = _v226_normalize_resin(resin if resin is not None else _v225_value(self, 'pm_resin', ''))
    if not _v226_is_direct_resin(resin):
        return False
    try:
        return bool(self.apply_loading_calc.get())
    except Exception:
        return False


_V226_BASE_SAVE_ACTIVE = _v2093_save_active

def _v226_save_active(self):
    _V226_BASE_SAVE_ACTIVE(self)
    try:
        idx = getattr(self, '_v2093_active_index', None)
        if idx is None:
            idx = _v2093_active_index(self)
        if idx is None or not (0 <= int(idx) < len(getattr(self, 'pm_items', []))):
            return
        item = self.pm_items[int(idx)]
        resin = _v226_normalize_resin(_v225_value(self, 'pm_resin', item.get('resin', '')))
        item['resin'] = resin
        checked = _v226_editor_loading_flag(self, resin)
        item['apply_loading_calc'] = checked
        item['loading_aa_eq'] = str(_v225_value(self, 'loading_aa_eq', item.get('loading_aa_eq', '2')))
        item['loading_diea_eq'] = str(_v225_value(self, 'loading_diea_eq', item.get('loading_diea_eq', '4')))
        if hasattr(self, 'pm_resin') and self.pm_resin.get() != resin:
            self.pm_resin.set(resin)
        if hasattr(self, 'apply_loading_calc') and bool(self.apply_loading_calc.get()) != checked:
            self.apply_loading_calc.set(checked)
    except Exception:
        pass


_V226_BASE_LOAD_ITEM = _v2093_load_item_to_editor

def _v226_load_item_to_editor(self, idx):
    _V226_BASE_LOAD_ITEM(self, idx)
    try:
        idx = int(idx)
        if not (0 <= idx < len(getattr(self, 'pm_items', []))):
            return
        item = self.pm_items[idx]
        resin = _v226_normalize_resin(item.get('resin', 'Rink Amide AM'))
        item['resin'] = resin
        item['apply_loading_calc'] = _v226_item_loading_flag(item, resin)
        self._v2093_active_index = idx
        self._v276_active_index = idx
        self.pm_resin.set(resin)
        if hasattr(self, 'apply_loading_calc'):
            self.apply_loading_calc.set(bool(item['apply_loading_calc']))
        if hasattr(self, 'loading_aa_eq'):
            self.loading_aa_eq.set(str(item.get('loading_aa_eq', '2')))
        if hasattr(self, 'loading_diea_eq'):
            self.loading_diea_eq.set(str(item.get('loading_diea_eq', '4')))
    except Exception:
        pass


def _v226_select_item(self, event=None):
    try:
        sel = list(self.pm_list.curselection())
        new_idx = int(sel[0]) if sel else _v2093_active_index(self)
    except Exception:
        new_idx = _v2093_active_index(self)
    if new_idx is None:
        return
    old_idx = getattr(self, '_v2093_active_index', None)
    try:
        if old_idx is not None and int(old_idx) != int(new_idx):
            _v226_save_active(self)
    except Exception:
        pass
    _v226_load_item_to_editor(self, int(new_idx))
    try:
        _v2093_refresh_cleavage(self)
    except Exception:
        pass


def _v226_resin_changed(self, *_args):
    if getattr(self, '_v226_resin_syncing', False):
        return
    self._v226_resin_syncing = True
    try:
        resin = _v226_normalize_resin(_v225_value(self, 'pm_resin', ''))
        if hasattr(self, 'pm_resin') and self.pm_resin.get() != resin:
            self.pm_resin.set(resin)
        # Non-direct profiles can never retain a stale direct-loading check.
        if not _v226_is_direct_resin(resin) and hasattr(self, 'apply_loading_calc'):
            self.apply_loading_calc.set(False)
        _v226_save_active(self)
    finally:
        self._v226_resin_syncing = False


_V226_BASE_PLAN_INPUT = _v222_plan_input

def _v226_plan_input(self):
    from dataclasses import replace as _replace
    base = _V226_BASE_PLAN_INPUT(self)
    resin = _v226_normalize_resin(_v225_value(self, 'pm_resin', getattr(base, 'resin', '')))
    return _replace(
        base,
        resin=resin,
        apply_resin_loading=_v226_editor_loading_flag(self, resin),
    )


# All existing final Project Manager table builders resolve this global at call time.
_v2093_save_active = _v226_save_active
_v2093_load_item_to_editor = _v226_load_item_to_editor
_v222_plan_input = _v226_plan_input
_v221_plan_input = _v226_plan_input


def _v226_pm_rows(self):
    # Save only the active editor, then preserve each peptide's own loading flag.
    try:
        _v226_save_active(self)
    except Exception:
        pass
    rows = []
    for i, item in enumerate(list(getattr(self, 'pm_items', []) or []), start=1):
        seq = str(item.get('sequence', '') or '').strip()
        if not seq:
            continue
        resin = _v226_normalize_resin(item.get('resin', 'Rink Amide AM'))
        item['resin'] = resin
        flag = _v226_item_loading_flag(item, resin)
        item['apply_loading_calc'] = flag
        copies = max(1, int(round(_v29_to_float(self, item.get('copies', '1'), 1))))
        scale_each = _v29_to_float(self, item.get('scale', '0.2'), 0.2)
        loading = _v29_to_float(self, item.get('loading', ''), 0.0)
        total_scale = scale_each * copies
        # Resin mass is required for every resin profile and is independent of
        # whether direct C-terminal loading chemistry is performed.
        resin_g = total_scale / loading if loading > 0 else 0.0
        rows.append({
            'No': i,
            'Project': item.get('project', ''),
            'Peptide name': item.get('peptide', ''),
            'Sequence': seq,
            'Copies': copies,
            'Scale mmol': scale_each,
            'Resin': resin,
            'Loading': loading if loading > 0 else '',
            'Resin_g': _v201_round2(resin_g) if resin_g else '',
            'LOT No': item.get('lot', item.get('lot_no', '')),
            'Chemistry': item.get('chemistry', 'DIC/HOBt') or 'DIC/HOBt',
            '_apply_loading_calc': flag,
            '_loading_aa_eq': _v29_to_float(self, item.get('loading_aa_eq', _v225_value(self, 'loading_aa_eq', 2)), 2),
            '_loading_diea_eq': _v29_to_float(self, item.get('loading_diea_eq', _v225_value(self, 'loading_diea_eq', 4)), 4),
        })
    return rows


_V226_BASE_BATCH_PLAN_INPUT = _v225_batch_plan_input

def _v226_batch_plan_input(self, row):
    from dataclasses import replace as _replace
    base = _V226_BASE_BATCH_PLAN_INPUT(self, row)
    resin = _v226_normalize_resin(row.get('Resin', getattr(base, 'resin', '')))
    flag = bool(row.get('_apply_loading_calc', False)) and _v226_is_direct_resin(resin)
    return _replace(
        base,
        resin=resin,
        apply_resin_loading=flag,
        loading_aa_eq=float(row.get('_loading_aa_eq', getattr(base, 'loading_aa_eq', 2.0)) or 2.0),
        loading_diea_eq=float(row.get('_loading_diea_eq', getattr(base, 'loading_diea_eq', 4.0)) or 4.0),
    )


def _v226_resin_loading_df(self, rows=None):
    _v2093_app_path()
    from spps_planner.engine import generate_step_materials, direct_loading_enabled
    rows = rows if rows is not None else _v226_pm_rows(self)
    out = []
    for r in rows:
        inp = _v226_batch_plan_input(self, r)
        if not direct_loading_enabled(inp):
            continue
        mats = generate_step_materials(inp)
        keep = mats[
            mats.get('step', pd.Series(dtype=object)).astype(str).str.lower().eq('resin')
            | mats.get('phase', pd.Series(dtype=object)).astype(str).str.lower().eq('loading')
        ]
        copies = max(1, int(round(_v29_to_float(self, r.get('Copies'), 1))))
        for _, m in keep.iterrows():
            item = str(m.get('material', '') or '').strip()
            if not item:
                continue
            cls = str(m.get('class', '') or '').strip()
            planned_mmol = _v29_to_float(self, m.get('planned_mmol'), 0.0)
            planned_g = _v29_to_float(self, m.get('planned_g'), 0.0)
            planned_ml = _v29_to_float(self, m.get('planned_mL'), 0.0)
            eq = planned_mmol / inp.scale_mmol if inp.scale_mmol else ''
            solvent = '' if cls.lower() == 'resin' else str(inp.loading_dissolve_solvent or '')
            mw, density = _v29_material_lookup(self, item)
            out.append({
                'Category': 'Resin loading',
                'Item': item,
                'Solvent': solvent,
                'Count': copies,
                'Eq': _v201_round2(eq) if eq != '' else '',
                'Conc_M': '',
                'Calculated_mL': _v201_round2(planned_ml) if planned_ml else '',
                'Actual_mL': _v201_round2(planned_ml) if planned_ml else '',
                'MW': _v201_round2(mw) if mw else m.get('MW', ''),
                'Density': _v201_round2(density) if density else m.get('density_g_mL', ''),
                'Weight_g': _v201_round2(planned_g) if planned_g else '',
                'Volume_mL': _v201_round2(planned_ml) if planned_ml else '',
                'Note': str(m.get('note', '') or m.get('source', '') or 'Connected core-engine 2-CTC loading calculation.'),
            })
    return pd.DataFrame(out, columns=V29_BATCH_COLUMNS)


# The final Batch calculator resolves these helper names at runtime.
_v208_pm_rows = _v226_pm_rows
_v225_batch_plan_input = _v226_batch_plan_input
_v208_resin_loading_df = _v226_resin_loading_df


def _v226_generate(self, *args, **kwargs):
    try:
        _v226_save_active(self)
        return _v221_generate(self, *args, **kwargs)
    except Exception as exc:
        try: messagebox.showerror('Generate / Update', str(exc))
        except Exception: pass
        return None


def _v226_export_outputs(self):
    result = _v221_export_outputs(self)
    try:
        out = Path(self.last_outdir)
        old_state = out / 'project_manager_state_v2.2.5.json'
        new_state = out / 'project_manager_state_v2.2.6.json'
        if old_state.exists():
            data = json.loads(old_state.read_text(encoding='utf-8'))
            data['app_version'] = APP_VERSION
            data['resin_profile_rule'] = '2-CTC direct only when per-peptide Loading is ON; CTC(합성기) always preloaded'
            new_state.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
            old_state.unlink(missing_ok=True)
        old_xlsx = out / 'project_manager_selected_outputs_v2.2.5.xlsx'
        new_xlsx = out / 'project_manager_selected_outputs_v2.2.6.xlsx'
        if old_xlsx.exists():
            old_xlsx.replace(new_xlsx)
            result = new_xlsx
    except Exception:
        pass
    return result


def _v226_bind_final_routes(self):
    try:
        SPPSGui.RESIN_VALUES = list(_V224_ACTIVE_RESINS)
        self.RESIN_VALUES = list(_V224_ACTIVE_RESINS)
    except Exception:
        pass
    try:
        for w in _v2093_walk(self):
            if isinstance(w, ttk.Button):
                text = str(w.cget('text')).strip()
                if text.startswith('Generate / Update') or text in {'Apply Change', 'Apply cleavage'}:
                    w.configure(command=lambda _self=self: _v226_generate(_self))
                elif text == 'Export':
                    w.configure(command=lambda _self=self: _v226_export_outputs(_self))
            elif isinstance(w, ttk.Combobox):
                vals = [str(v) for v in w.cget('values')]
                if any(('CTC' in v or 'Rink Amide' in v) for v in vals):
                    w.configure(values=list(_V224_ACTIVE_RESINS))
    except Exception:
        pass
    try:
        self.pm_list.bind('<<ListboxSelect>>', lambda e, _self=self: _v226_select_item(_self, e), add=False)
        self.pm_list.bind('<Double-Button-1>', lambda e, _self=self: _v226_select_item(_self, e), add=False)
        self.pm_list.bind('<Return>', lambda e, _self=self: _v226_select_item(_self, e), add=False)
    except Exception:
        pass
    try:
        if not getattr(self, '_v226_resin_trace_installed', False):
            self.pm_resin.trace_add('write', lambda *_a, _self=self: _self.after_idle(lambda: _v226_resin_changed(_self)))
            self._v226_resin_trace_installed = True
    except Exception:
        pass
    try:
        self.title(VERSION_LABEL)
        for w in _v2093_walk(self):
            if isinstance(w, ttk.Label) and str(w.cget('text')).startswith('SPPS Planner GitHub'):
                w.configure(text=VERSION_LABEL)
    except Exception:
        pass


_V226_PREV_BUILD = SPPSGui._build

def _v226_build(self):
    _V226_PREV_BUILD(self)
    _v226_bind_final_routes(self)
    try:
        current = _v2093_active_index(self)
        if current is not None:
            _v226_load_item_to_editor(self, current)
    except Exception:
        pass
    try:
        self.after_idle(lambda _self=self: _v226_bind_final_routes(_self))
        # A few historical UI layers schedule delayed title/button normalization.
        # Reassert only the final non-destructive bindings after those callbacks.
        for delay in (80, 250, 700, 1500):
            self.after(delay, lambda _self=self: _v226_bind_final_routes(_self))
    except Exception:
        pass


